import { useState, useEffect, useMemo } from 'react'
import api from '../services/api'
import { toast } from 'react-hot-toast'
import { useTranslation } from 'react-i18next'
import { formatNumber as utilsFormatNumber } from '../utils/formatters'

interface ProduitABC {
  id: number
  nom: string
  cip: string
  rayon: string
  fournisseur: string
  stock: number
  prix_vente: number
  chiffre_affaires: number
  quantite_vendue: number
  pourcentage_ca: number
  pourcentage_cumule: number
  categorie: 'A' | 'B' | 'C'
  en_rupture: boolean
}

interface AnalyseABCData {
  periode_mois: number
  date_debut: string
  ca_total: number
  nb_produits_a: number
  nb_produits_b: number
  nb_produits_c: number
  ca_categorie_a: number
  ca_categorie_b: number
  ca_categorie_c: number
  alertes_rupture_a: number
  produits_a_en_rupture: string[]
  produits: ProduitABC[]
}

interface Rayon {
  id: number
  name: string
}

interface Fournisseur {
  id: number
  name: string
}

const formatNumber = (n: number) => utilsFormatNumber(Math.round(n))

// ÔöÇÔöÇÔöÇ AbcFilterBar ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
interface AbcFilterBarProps {
  periode: number
  onPeriodeChange: (v: number) => void
  rayonId: string
  onRayonChange: (v: string) => void
  fournisseurId: string
  onFournisseurChange: (v: string) => void
  rayons: Rayon[]
  fournisseurs: Fournisseur[]
  onCopy: () => void
  copyDisabled: boolean
}

function AbcFilterBar({
  periode, onPeriodeChange,
  rayonId, onRayonChange,
  fournisseurId, onFournisseurChange,
  rayons, fournisseurs,
  onCopy, copyDisabled,
}: AbcFilterBarProps) {
  const { t } = useTranslation(['stock', 'common'])
  return (
    <div className="flex flex-wrap gap-2">
      <select
        className="h-9 px-3 rounded-xl border border-slate-200 bg-white text-xs font-bold text-slate-700 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all appearance-none"
        value={periode}
        onChange={(e) => onPeriodeChange(Number(e.target.value))}
      >
        <option value={3}>{t('stock:abc.filters.months_3')}</option>
        <option value={6}>{t('stock:abc.filters.months_6')}</option>
        <option value={12}>{t('stock:abc.filters.months_12')}</option>
      </select>

      <select
        className="h-9 px-3 rounded-xl border border-slate-200 bg-white text-xs font-bold text-slate-700 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all appearance-none"
        value={rayonId}
        onChange={(e) => onRayonChange(e.target.value)}
      >
        <option value="">{t('stock:abc.filters.all_rayons')}</option>
        {rayons.map(r => (
          <option key={r.id} value={r.id}>{r.name}</option>
        ))}
      </select>

      <select
        className="h-9 px-3 rounded-xl border border-slate-200 bg-white text-xs font-bold text-slate-700 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all appearance-none"
        value={fournisseurId}
        onChange={(e) => onFournisseurChange(e.target.value)}
      >
        <option value="">{t('stock:abc.filters.all_suppliers')}</option>
        {fournisseurs.map(f => (
          <option key={f.id} value={f.id}>{f.name}</option>
        ))}
      </select>

      <button
        type="button"
        className="inline-flex items-center gap-2 h-9 px-4 rounded-xl border border-slate-200 text-xs font-bold text-slate-700 hover:bg-slate-50 transition-colors disabled:opacity-40"
        onClick={onCopy}
        disabled={copyDisabled}
      >
        ­ƒôï {t('stock:abc.filters.copy')}
      </button>
    </div>
  )
}

// ÔöÇÔöÇÔöÇ AbcProductTable ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
interface AbcProductTableProps {
  produits: ProduitABC[]
}

function AbcProductTable({ produits }: AbcProductTableProps) {
  const { t } = useTranslation(['stock', 'common'])
  return (
    <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="overflow-auto h-full">
        <table className="w-full border-separate border-spacing-0 text-sm">
          <thead>
            <tr className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-[0.12em]">
              <th className="sticky top-0 bg-slate-50 py-3 pl-6 text-left border-b border-slate-200">{t('stock:abc.table.product')}</th>
              <th className="sticky top-0 bg-slate-50 py-3 text-left border-b border-slate-200">{t('stock:abc.table.cip')}</th>
              <th className="sticky top-0 bg-slate-50 py-3 text-left border-b border-slate-200">{t('stock:abc.table.rayon')}</th>
              <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200 pr-4">{t('stock:abc.table.stock')}</th>
              <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200">{t('stock:abc.table.qty_sold')}</th>
              <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200">{t('stock:abc.table.sale_price')}</th>
              <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200">{t('stock:abc.table.ca')}</th>
              <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200">{t('stock:abc.table.ca_percent')}</th>
              <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200 pr-6">{t('stock:abc.table.cumulated_percent')}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {produits.length === 0 ? (
              <tr>
                <td colSpan={9} className="text-center py-12 text-slate-400">
                  {t('stock:abc.table.no_products')}
                </td>
              </tr>
            ) : (
              produits.map((p) => (
                <tr key={p.id} className={`hover:bg-blue-50/30 transition-colors ${p.en_rupture ? 'bg-red-50/50' : ''}`}>
                  <td className="py-2.5 pl-6 font-medium text-slate-700">
                    {p.nom}
                    {p.en_rupture && <span className="inline-flex items-center ml-2 px-1.5 py-0.5 rounded-full bg-red-100 text-red-600 text-[10px] font-bold">{t('stock:abc.table.shortage_badge')}</span>}
                  </td>
                  <td className="py-2.5 font-mono text-xs text-slate-400">{p.cip}</td>
                  <td className="py-2.5 text-sm text-slate-600">{p.rayon}</td>
                  <td className={`py-2.5 text-right font-bold pr-4 ${
                    p.stock <= 0 ? 'text-red-500' : p.stock <= 5 ? 'text-amber-500' : 'text-slate-700'
                  }`}>{p.stock}</td>
                  <td className="py-2.5 text-right font-semibold text-blue-600">{formatNumber(p.quantite_vendue)}</td>
                  <td className="py-2.5 text-right text-slate-600">{formatNumber(p.prix_vente)} {t('common:currency_symbol', { defaultValue: 'F' })}</td>
                  <td className="py-2.5 text-right font-bold text-slate-800">{formatNumber(p.chiffre_affaires)} {t('common:currency_symbol', { defaultValue: 'F' })}</td>
                  <td className="py-2.5 text-right text-slate-600">{p.pourcentage_ca.toFixed(0)}%</td>
                  <td className="py-2.5 text-right text-slate-400 pr-6">{p.pourcentage_cumule.toFixed(1)}%</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

// ÔöÇÔöÇÔöÇ Main Component ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
export default function AnalyseABC() {
  const { t } = useTranslation(['stock', 'common'])
  const [data, setData] = useState<AnalyseABCData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Filtres
  const [periode, setPeriode] = useState(6)
  const [rayonId, setRayonId] = useState<string>('')
  const [fournisseurId, setFournisseurId] = useState<string>('')

  // Options de filtres
  const [rayons, setRayons] = useState<Rayon[]>([])
  const [fournisseurs, setFournisseurs] = useState<Fournisseur[]>([])

  // Tab active
  const [activeTab, setActiveTab] = useState<'A' | 'B' | 'C'>('A')

  // Charger les options de filtres
  useEffect(() => {
    const fetchOptions = async () => {
      try {
        const [rayonsRes, fournisseursRes] = await Promise.all([
          api.get('rayons/'),
          api.get('fournisseurs/')
        ])
        setRayons(rayonsRes.data.results || rayonsRes.data || [])
        setFournisseurs(fournisseursRes.data.results || fournisseursRes.data || [])
      } catch (err) {
        console.error('Erreur chargement filtres:', err)
      }
    }
    fetchOptions()
  }, [])

  // Charger les donn├®es ABC
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true)
      setError(null)
      try {
        const params = new URLSearchParams({ periode: periode.toString() })
        if (rayonId) params.append('rayon_id', rayonId)
        if (fournisseurId) params.append('fournisseur_id', fournisseurId)

        const response = await api.get(`produits/analyse_abc/?${params}`)
        setData(response.data)
      } catch (err: unknown) {
        setError(err.response?.data?.detail || t('stock:abc.error_loading'))
        console.error('Erreur analyse ABC:', err)
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [periode, rayonId, fournisseurId])

  const produitsFiltr├®s = useMemo(() => {
    if (!data) return []
    return data.produits.filter(p => p.categorie === activeTab)
  }, [data, activeTab])

  // Copier le tableau dans le presse-papier (format TSV pour Excel)
  const copyToClipboard = () => {
    if (!data) return

    // En-t├¬tes
    const headers = [
      t('stock:abc.table.product'),
      t('stock:abc.table.cip'),
      t('stock:abc.table.rayon'),
      t('stock:abc.table.stock'),
      t('stock:abc.table.qty_sold'),
      t('stock:abc.table.sale_price'),
      t('stock:abc.table.ca'),
      t('stock:abc.table.ca_percent'),
      t('stock:abc.table.cumulated_percent'),
      t('stock:abc.table.category', { defaultValue: 'Cat├®gorie' })
    ]

    // Lignes de donn├®es
    const rows = produitsFiltr├®s.map(p => [
      p.nom,
      p.cip,
      p.rayon,
      p.stock,
      p.quantite_vendue,
      p.prix_vente,
      Math.round(p.chiffre_affaires),
      p.pourcentage_ca.toFixed(0) + '%',
      p.pourcentage_cumule.toFixed(1) + '%',
      p.categorie
    ])

    // Construire le TSV
    const tsv = [headers.join('\t'), ...rows.map(r => r.join('\t'))].join('\n')

    // Modern clipboard API
    navigator.clipboard.writeText(tsv)
      .then(() => {
        toast.success(t('stock:abc.messages.copy_success', { count: produitsFiltr├®s.length }))
      })
      .catch((err) => {
        console.error('Failed to copy:', err)
        toast.error(t('stock:abc.messages.copy_error'))
      })
  }

  if (loading) {
    return (
      <div className="h-full flex items-center justify-center">
        <span className="size-12 border-4 border-slate-200 border-t-blue-500 rounded-full animate-spin inline-block"></span>
      </div>
    )
  }

  if (error) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="flex items-center gap-3 bg-red-50 border border-red-200 text-red-700 rounded-2xl px-6 py-4 max-w-md">
          <svg xmlns="http://www.w3.org/2000/svg" className="shrink-0 h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <span>{error}</span>
        </div>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col p-6 bg-white overflow-hidden">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6 shrink-0">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            ­ƒôè {t('stock:abc.title')}
          </h1>
          <p className="text-slate-500 text-sm">
            {t('stock:abc.subtitle')}
          </p>
        </div>

        {/* Filtres */}
        <AbcFilterBar
          periode={periode}
          onPeriodeChange={setPeriode}
          rayonId={rayonId}
          onRayonChange={setRayonId}
          fournisseurId={fournisseurId}
          onFournisseurChange={setFournisseurId}
          rayons={rayons}
          fournisseurs={fournisseurs}
          onCopy={copyToClipboard}
          copyDisabled={!data || produitsFiltr├®s.length === 0}
        />
      </div>

      {/* Alertes */}
      {data && data.alertes_rupture_a > 0 && (
        <div className="flex items-start gap-3 bg-amber-50 border border-amber-200 text-amber-800 rounded-2xl px-5 py-4 mb-4 shrink-0">
          <svg xmlns="http://www.w3.org/2000/svg" className="shrink-0 h-5 w-5 text-amber-500 mt-0.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
          <div>
            <span className="font-bold">{t('stock:abc.alerts.shortage', { count: data.alertes_rupture_a })}</span>
            <span className="ml-2 text-sm">{data.produits_a_en_rupture.join(', ')}</span>
          </div>
        </div>
      )}

      {/* Stats Cards */}
      {data && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6 shrink-0">
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-4">
            <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">{t('stock:abc.stats.total_ca')}</div>
            <div className="text-2xl font-black text-blue-600">{formatNumber(data.ca_total)} F</div>
            <div className="text-xs text-slate-400 mt-1">{t('stock:abc.stats.period_info', { count: data.periode_mois })}</div>
          </div>

          <div className="bg-red-50 rounded-xl border border-red-200 shadow-sm p-4">
            <div className="text-xs font-bold text-red-400 uppercase tracking-widest mb-1">­ƒö┤ {t('stock:abc.stats.category_a')}</div>
            <div className="text-2xl font-black text-red-600">{data.nb_produits_a}</div>
            <div className="text-xs text-red-400 mt-1">{formatNumber(data.ca_categorie_a)} F ({data.ca_total > 0 ? Math.round(data.ca_categorie_a / data.ca_total * 100) : 0}%)</div>
          </div>

          <div className="bg-yellow-50 rounded-xl border border-yellow-200 shadow-sm p-4">
            <div className="text-xs font-bold text-yellow-600 uppercase tracking-widest mb-1">­ƒƒí {t('stock:abc.stats.category_b')}</div>
            <div className="text-2xl font-black text-yellow-600">{data.nb_produits_b}</div>
            <div className="text-xs text-yellow-500 mt-1">{formatNumber(data.ca_categorie_b)} F ({data.ca_total > 0 ? Math.round(data.ca_categorie_b / data.ca_total * 100) : 0}%)</div>
          </div>

          <div className="bg-emerald-50 rounded-xl border border-emerald-200 shadow-sm p-4">
            <div className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-1">­ƒƒó {t('stock:abc.stats.category_c')}</div>
            <div className="text-2xl font-black text-emerald-600">{data.nb_produits_c}</div>
            <div className="text-xs text-emerald-500 mt-1">{formatNumber(data.ca_categorie_c)} F ({data.ca_total > 0 ? Math.round(data.ca_categorie_c / data.ca_total * 100) : 0}%)</div>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="flex bg-slate-100 p-1 rounded-xl mb-4 shrink-0 w-fit gap-1">
        <button
          type="button"
          className={`h-8 px-4 rounded-lg text-xs font-bold transition-all ${
            activeTab === 'A' ? 'bg-red-500 text-white shadow' : 'text-slate-500 hover:bg-slate-200'
          }`}
          onClick={() => setActiveTab('A')}
        >
          ­ƒö┤ {t('stock:abc.tabs.vital')} ({data?.nb_produits_a || 0})
        </button>
        <button
          type="button"
          className={`h-8 px-4 rounded-lg text-xs font-bold transition-all ${
            activeTab === 'B' ? 'bg-yellow-500 text-white shadow' : 'text-slate-500 hover:bg-slate-200'
          }`}
          onClick={() => setActiveTab('B')}
        >
          ­ƒƒí {t('stock:abc.tabs.important')} ({data?.nb_produits_b || 0})
        </button>
        <button
          type="button"
          className={`h-8 px-4 rounded-lg text-xs font-bold transition-all ${
            activeTab === 'C' ? 'bg-emerald-500 text-white shadow' : 'text-slate-500 hover:bg-slate-200'
          }`}
          onClick={() => setActiveTab('C')}
        >
          ­ƒƒó {t('stock:abc.tabs.secondary')} ({data?.nb_produits_c || 0})
        </button>
      </div>

      {/* Table */}
      <AbcProductTable produits={produitsFiltr├®s} />

      {/* Footer */}
      <div className="mt-4 text-xs text-slate-400 text-center shrink-0">
        {t('stock:abc.footer.analyzed_since', { date: data?.date_debut })} ÔÇó {t('stock:abc.footer.total_products', { count: data?.produits.length || 0 })}
      </div>
    </div>
  )
}

´╗┐import React, { useState, useEffect } from 'react';
import api from '../services/api';
import { useTranslation } from 'react-i18next';
import { formatCurrency } from '../utils/formatters';

interface CashierPerformance {
    user_id: number;
    username: string;
    full_name: string;
    moyenne_ecart_absolu: number;
    moyenne_ecart_algebrique: number;
    total_ecart_absolu: number;
    total_ecart_algebrique: number;
    nombre_clotures: number;
    total_theorique: number;
    total_reel: number;
    total_ventes: number;
}

interface BestCashierMetricProps {
    month: string;
    year: string;
    userId?: string;
}

const BestCashierMetric: React.FC<BestCashierMetricProps> = ({ month, year, userId }) => {
    const { t } = useTranslation(['cash_closings', 'common']);
    const [performances, setPerformances] = useState<CashierPerformance[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchPerformances();
    }, [month, year, userId]);

    const fetchPerformances = async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({ month, year })
            if (userId) params.append('user_id', userId)
            const response = await api.get(`clotures-caisse/performances_caissiers/?${params.toString()}`);
            setPerformances(response.data);
        } catch (err) {
            console.error("Error fetching cashier performances:", err);
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="bg-base-100 rounded-2xl shadow-sm border border-base-300 p-8 flex justify-center items-center">
                <span className="loading loading-spinner loading-md text-primary"></span>
            </div>
        );
    }

    if (performances.length === 0) {
        return (
            <div className="bg-base-100 rounded-2xl shadow-sm border border-base-300 p-10 flex flex-col items-center justify-center text-center space-y-4">
                <div className="bg-base-200 p-4 rounded-full">
                    <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-base-content/20"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <div>
                    <h4 className="font-bold text-base-content/40 uppercase tracking-widest text-xs mb-1">{t('performance.waiting_ranking')}</h4>
                    <p className="text-sm text-base-content/30 italic max-w-xs mx-auto">
                        {t('performance.no_closures_desc')}
                    </p>
                </div>
            </div>
        );
    }

    const winner = performances[0];

    return (
        <div className="flex flex-col sm:flex-row gap-3">
            {/* Winner Card ÔÇö compact horizontal */}
            <div className="sm:w-56 shrink-0 bg-emerald-600 rounded-xl p-3 text-white relative overflow-hidden border border-emerald-700">
                <div className="flex items-center gap-2 mb-2">
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-yellow-300 shrink-0"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                    <span className="text-[10px] font-black uppercase tracking-widest opacity-80">{t('performance.best_cashier')}</span>
                </div>
                <div className="flex items-center gap-2 mb-3">
                    <div className="bg-white/20 text-white rounded-lg size-9 flex items-center justify-center text-sm font-black border border-white/40 shrink-0">
                        {winner.username.charAt(0).toUpperCase()}
                    </div>
                    <div className="min-w-0">
                        <div className="text-sm font-black leading-tight truncate">{winner.full_name}</div>
                        <div className="text-white/60 text-[10px] font-bold">@{winner.username}</div>
                    </div>
                </div>
                <div className="space-y-1.5 border-t border-white/20 pt-2">
                    <div className="flex justify-between items-center">
                        <span className="text-white/70 text-[10px] font-bold uppercase tracking-wide">{t('performance.rigor_score')}</span>
                        <span className="text-sm font-black text-yellow-300">{formatCurrency(winner.moyenne_ecart_absolu)}</span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-white/70 text-[10px] font-bold uppercase tracking-wide">{t('performance.avg_trend')}</span>
                        <span className="text-xs font-black">{winner.moyenne_ecart_algebrique > 0 ? '+' : ''}{formatCurrency(winner.moyenne_ecart_algebrique)}</span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-white/70 text-[10px] font-bold uppercase tracking-wide">{t('performance.total_closures')}</span>
                        <span className="text-sm font-black">{winner.nombre_clotures}</span>
                    </div>
                </div>
            </div>

            {/* Ranking Table ÔÇö compact */}
            <div className="flex-1 bg-base-100 rounded-xl border border-base-200 overflow-hidden flex flex-col">
                <div className="px-4 py-2 border-b border-base-200 flex justify-between items-center">
                    <h3 className="font-black text-xs text-base-content uppercase tracking-widest flex items-center gap-2">
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-primary"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
                        {t('performance.ranking_title')}
                    </h3>
                    <span className="text-[10px] font-bold opacity-40 bg-base-200 px-2 py-0.5 rounded-full">Top {performances.length}</span>
                </div>
                <div className="overflow-x-auto flex-1">
                    <table className="table table-xs w-full">
                        <thead>
                            <tr className="bg-base-200/40">
                                <th className="text-[10px] uppercase font-black text-base-content/40 px-3 py-2 tracking-widest">{t('table.rank')}</th>
                                <th className="text-[10px] uppercase font-black text-base-content/40 px-3 py-2 tracking-widest">{t('table.operator')}</th>
                                <th className="text-[10px] uppercase font-black text-base-content/40 text-center px-3 py-2 tracking-widest">{t('table.closures')}</th>
                                <th className="text-[10px] uppercase font-black text-base-content/40 text-right px-3 py-2 tracking-widest">{t('table.avg_gap')}</th>
                                <th className="text-[10px] uppercase font-black text-base-content/40 text-right px-3 py-2 tracking-widest">{t('table.trend')}</th>
                            </tr>
                        </thead>
                        <tbody>
                            {performances.map((perf, index) => (
                                <tr key={perf.user_id} className="hover:bg-primary/5 transition-colors group border-b border-base-100">
                                    <td className="px-3 py-2">
                                        {index === 0 ? (
                                            <span className="badge badge-xs bg-yellow-400 border-none text-yellow-900 font-black italic px-2">{t('performance.badges.1st')}</span>
                                        ) : index === 1 ? (
                                            <span className="badge badge-xs bg-slate-300 border-none text-base-content/90 font-black italic px-2">{t('performance.badges.2nd')}</span>
                                        ) : index === 2 ? (
                                            <span className="badge badge-xs bg-warning border-none text-amber-50 font-black italic px-2">{t('performance.badges.3rd')}</span>
                                        ) : (
                                            <span className="text-base-content/30 font-black text-xs pl-1 font-mono">{index + 1}</span>
                                        )}
                                    </td>
                                    <td className="px-3 py-2">
                                        <div className="font-bold text-xs text-base-content group-hover:text-primary transition-colors leading-tight">{perf.full_name}</div>
                                        <div className="text-[10px] font-bold text-base-content/30 uppercase tracking-tighter">@{perf.username}</div>
                                    </td>
                                    <td className="px-3 py-2 text-center">
                                        <span className="font-black text-xs text-base-content/80">{perf.nombre_clotures}</span>
                                    </td>
                                    <td className="px-3 py-2 text-right">
                                        <span className="font-black text-xs text-primary bg-primary/5 rounded px-2 py-0.5">{formatCurrency(perf.moyenne_ecart_absolu)}</span>
                                    </td>
                                    <td className="px-3 py-2 text-right">
                                        <span className={`text-[11px] font-black inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded ${
                                            perf.moyenne_ecart_algebrique > 0 ? 'bg-success/10 text-success'
                                            : perf.moyenne_ecart_algebrique < 0 ? 'bg-error/10 text-error'
                                            : 'bg-base-200 text-base-content/30'
                                        }`}>
                                            {perf.moyenne_ecart_algebrique > 0 ? (
                                                <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="m5 12 7-7 7 7"/><path d="M12 19V5"/></svg>
                                            ) : perf.moyenne_ecart_algebrique < 0 ? (
                                                <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M12 5v14"/><path d="m19 12-7 7-7-7"/></svg>
                                            ) : null}
                                            {perf.moyenne_ecart_algebrique > 0 ? '+' : ''}{formatCurrency(perf.moyenne_ecart_algebrique)}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default BestCashierMetric;

