import { useState, useEffect, useCallback, useMemo } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { useNavigate } from 'react-router-dom'
import api from '../services/api'
import { toast } from 'react-hot-toast'
import { useAuth } from '../context/AuthContext'
import { usePharmacySettings } from '../hooks/usePharmacySettings'
import type { Facture, TicketCaisse, CouponMonnaie, PosteVente } from '../types'
import PasswordConfirmModal from './PasswordConfirmModal'
import { PaymentModal } from './caisse/PaymentModal'
import { FacturesTable } from './caisse/FacturesTable'
import { CouponPanel } from './caisse/CouponPanel'
import { useTranslation } from 'react-i18next'
import { getApiErrorDetail } from '../utils/errorHandling'
import { Keyboard } from 'lucide-react'
import { OpenCashSessionModal } from './caisse/OpenCashSessionModal'
import { cashSessionService } from '../services/cashSessionService'
import { useCaisseKeyboard } from '../hooks/useCaisseKeyboard'
import { useCaissePayment } from '../hooks/useCaissePayment'
import { useCaisseCoupons } from '../hooks/useCaisseCoupons'
import { useCaisseStats } from '../hooks/useCaisseStats'
import { useInvoiceModification } from '../hooks/useInvoiceModification'
import { useSudo } from '../hooks/useSudo'
import SudoValidationModal from './common/SudoValidationModal'
import { CaisseTicketPreviewModal } from './caisse/CaisseTicketPreviewModal'
import { CouponGenerateModal } from './caisse/CouponGenerateModal'
import { CouponDetailsModal } from './caisse/CouponDetailsModal'
import { ClosingReportModal } from './caisse/ClosingReportModal'
import { BulkCancelModal } from './caisse/BulkCancelModal'
import { CaisseHeader } from './caisse/CaisseHeader'
import { CaisseStatsCards } from './caisse/CaisseStatsCards'
import { SessionRecapBar } from './caisse/SessionRecapBar'

export default function CaisseCentralisee() {
const _queryClient = useQueryClient()
  const { t } = useTranslation('caisse')
const _navigate = useNavigate()
  const { user } = useAuth()
  const { settings: pharmacySettings } = usePharmacySettings()
  const [facturesEnAttente, setFacturesEnAttente] = useState<Facture[]>([])
  const [loading, setLoading] = useState(false)
  const [selectedFacture, setSelectedFacture] = useState<Facture | null>(null)
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false)
  const [ticketCaisse, setTicketCaisse] = useState<TicketCaisse | null>(null)
  const [showTicketPreview, setShowTicketPreview] = useState(false)

  // ├ëtats pour les coupons
  const [coupons, setCoupons] = useState<CouponMonnaie[]>([])
  const [isCouponPanelOpen, setIsCouponPanelOpen] = useState(false)
  const [isGenererCouponModalOpen, setIsGenererCouponModalOpen] = useState(false)
  const [nouveauCouponMontant, setNouveauCouponMontant] = useState('')
  const [nouveauCouponNotes, setNouveauCouponNotes] = useState('')
  const [couponTrouve, setCouponTrouve] = useState<CouponMonnaie | null>(null)
  const [isDetailsCouponModalOpen, setIsDetailsCouponModalOpen] = useState(false)
  const [isSudoModalOpen, setIsSudoModalOpen] = useState(false)
  
  // Coupon ├á appliquer PAR VENTE (cl├® = factureId, valeur = coupon)
  const [couponsParFacture, setCouponsParFacture] = useState<Record<number, CouponMonnaie>>({})
  // Modal pour s├®lectionner un coupon pour une facture sp├®cifique
  const [factureForCoupon, setFactureForCoupon] = useState<Facture | null>(null)
  
  // ├ëtat pour la navigation clavier (mouse killing)
  const [selectedRowIndex, setSelectedRowIndex] = useState<number>(0)
  
  // ├ëtats pour le multi-caisse et sessions
  const [postesCaisses, setPostesCaisses] = useState<unknown[]>([])
  const [selectedPosteCaisseId, setSelectedPosteCaisseId] = useState<string>('all')
  const [isMultiCaisse, setIsMultiCaisse] = useState(false)
  const [myActivePoste, setMyActivePoste] = useState<PosteVente | null>(null)
  const [showOpenSessionModal, setShowOpenSessionModal] = useState(false)
  const [closingReport, setClosingReport] = useState<unknown>(null)
  const [showClosingReport, setShowClosingReport] = useState(false)
  const [hideAmounts, setHideAmounts] = useState(false) // Mode s├®curit├®: masquer les montants aux caissiers
  const [selectedFactureIds, setSelectedFactureIds] = useState<Set<number>>(new Set())
  const [showBulkCancelModal, setShowBulkCancelModal] = useState(false)
  const [bulkCancelLoading, setBulkCancelLoading] = useState(false)
  const [bulkProgress, setBulkProgress] = useState<{ processed: number; total: number } | null>(null)
  const { sudoState, requireSudo, closeSudo } = useSudo()
  const [sessionRecap, setSessionRecap] = useState<{
    has_session: boolean
    poste_nom?: string
    date_ouverture?: string
    fond_de_caisse?: number
    total_encaisse?: number
    total_avec_fond?: number
    nb_transactions?: number
    details_par_mode?: Record<string, number>
  } | null>(null)

  // Fonction pour r├®cup├®rer les factures en attente
  const fetchFacturesEnAttente = useCallback(async () => {
    try {
      const params: Record<string, unknown> = { 
        status__in: 'BROU,VAL,PROF', 
        include_pending: true,
        include_details: true 
      }
      if (selectedPosteCaisseId !== 'all') params.poste_caisse = selectedPosteCaisseId

      const response = await api.get('factures/', { params })
      const facturesList = response.data.results || response.data || []
      
      setFacturesEnAttente(facturesList)
    } catch (err) {
      console.error('Erreur lors du chargement des factures en attente:', err)
    }
  }, [selectedPosteCaisseId])


  // Hook pour la logique des coupons
  const {
    loading: _couponLoading,
    searchCouponNumero,
    setSearchCouponNumero,
    fetchCoupons,
    handleGenererCoupon,
    handleRechercherCoupon: handleRechercherCouponBase,
    handleAppliquerCouponAFacture: handleAppliquerCouponBase,
    handleRetirerCouponDeFacture,
    utiliserCouponApresEncaissement
  } = useCaisseCoupons({
    coupons,
    setCoupons,
    couponsParFacture,
    setCouponsParFacture,
    setIsGenererCouponModalOpen,
    setIsDetailsCouponModalOpen,
    setCouponTrouve,
    selectedFacture,
    onSuccess: () => {
      setNouveauCouponMontant('')
      setNouveauCouponNotes('')
    }
  })

  // Wrappers pour adapter les signatures avec traduction
  const handleAppliquerCouponAFacture = useCallback((coupon: CouponMonnaie, facture: Facture) => {
    handleAppliquerCouponBase(coupon, facture, t)
    setFactureForCoupon(null)
    setIsDetailsCouponModalOpen(false)
    setCouponTrouve(null)
  }, [handleAppliquerCouponBase, t])

  const handleRechercherCoupon = useCallback(() => {
    handleRechercherCouponBase(searchCouponNumero, t)
  }, [handleRechercherCouponBase, searchCouponNumero, t])

  const handleRetirerCouponWrapper = useCallback((factureId: number) => {
    handleRetirerCouponDeFacture(factureId, t)
  }, [handleRetirerCouponDeFacture, t])

  const fetchSessionRecap = useCallback(async () => {
    try {
      const params: Record<string, string> = {}
      if (selectedPosteCaisseId !== 'all') params.poste_caisse = selectedPosteCaisseId
      const res = await api.get('postes-caisses/recap_session/', { params })
      setSessionRecap(res.data)
    } catch {
      // silencieux si pas de session
    }
  }, [selectedPosteCaisseId])

  // Rafra├«chissement automatique - toutes les 5 secondes pour plus de r├®activit├®
  useEffect(() => {
    fetchFacturesEnAttente()
    fetchCoupons()
    const interval = setInterval(() => {
      fetchFacturesEnAttente()
      fetchCoupons()
    }, 5000)
    return () => clearInterval(interval)
  }, [fetchFacturesEnAttente, fetchCoupons, selectedPosteCaisseId])

  // R├®cap session : toutes les 10 secondes + imm├®diat sur changement de poste
  useEffect(() => {
    fetchSessionRecap()
    const interval = setInterval(fetchSessionRecap, 10000)
    return () => clearInterval(interval)
  }, [fetchSessionRecap])

  // Wrapper pour la g├®n├®ration de coupon
  const handleGenererCouponWrapper = useCallback(async () => {
    await handleGenererCoupon(nouveauCouponMontant, nouveauCouponNotes, selectedFacture?.id || null, t)
  }, [handleGenererCoupon, nouveauCouponMontant, nouveauCouponNotes, selectedFacture, t])

  // Charger les postes de caisse et r├®glages
  useEffect(() => {
    const initPage = async () => {
      try {
        const [settingsRes, postesRes, myActive] = await Promise.all([
          api.get('parametres/').catch(() => ({ data: {} })),
          api.get('postes-caisses/').catch(() => ({ data: { results: [] } })),
          cashSessionService.getMyActivePostesVente().catch(() => [])
        ])
        
        // Charger le param├¿tre de s├®curit├® caisse
        const settings = settingsRes.data
        if (settings.hide_cash_totals) {
          setHideAmounts(true)
        }
        
        const postesList = postesRes.data.results || postesRes.data || []
        const activePoste = myActive.length > 0 ? myActive[0] : null
        setPostesCaisses(postesList)
        setMyActivePoste(activePoste)
        if (activePoste) {
          setSelectedPosteCaisseId(String(activePoste.caisse))
        }

        // D├®tecter si on est en mode multi-caisse
        const hasMultipleActive = myActive.length > 1
        setIsMultiCaisse(hasMultipleActive)
      } catch (err) {
        console.error('Erreur initialisation page:', err)
      }
    }
    initPage()
  }, [])

  // Ouvrir le panneau pour s├®lectionner un coupon pour une facture
  const openCouponSelectionForFacture = (facture: Facture) => {
    setFactureForCoupon(facture)
    setIsCouponPanelOpen(true)
  }

  // Trier les factures par date chronologique (plus ancienne en premier)
  const sortedFactures = useMemo(() => 
    facturesEnAttente.slice().sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()),
    [facturesEnAttente]
  )

  // Ouvrir la modale de paiement (useCallback pour les raccourcis clavier)
  const handleCloseSession = async () => {
    if (!myActivePoste) return

    // V├®rifier si des ventes en attente sont pr├®sentes
    if (facturesEnAttente.length > 0) {
      toast.error(
        t('cash_session.pending_sales_error', {
          defaultValue: `Impossible de fermer : ${facturesEnAttente.length} vente(s) en attente de r├¿glement. Veuillez r├®gler ou annuler les ventes avant de cl├┤turer.`,
          count: facturesEnAttente.length
        }),
        { duration: 5000 }
      )
      return
    }

    if (!window.confirm(t('cash_session.confirm_close', { defaultValue: 'Fermer votre caisse ?' }))) return
    try {
      const { data } = await cashSessionService.closePosteVente(myActivePoste.id, hideAmounts)
      setClosingReport(data)
      setShowClosingReport(true)
      setMyActivePoste(null)
      setSessionRecap(null)
    } catch (err: unknown) {
      toast.error(err.response?.data?.detail || t('cash_session.close_error', { defaultValue: 'Erreur fermeture' }))
    }
  }

  const handleEncaisser = useCallback((facture: Facture) => {
    setSelectedFacture(facture)
    setIsPaymentModalOpen(true)
  }, [])

  // Utiliser le hook personnalis├® pour les raccourcis clavier
  useCaisseKeyboard(
    {
      onEncaisser: handleEncaisser,
      onOpenCouponPanel: openCouponSelectionForFacture,
      onRefresh: () => {
        fetchFacturesEnAttente()
        fetchCoupons()
        toast.success(t('messages.refreshed'))
      },
      onToggleCouponPanel: () => {
        setIsCouponPanelOpen(false)
        setFactureForCoupon(null)
      },
      onCloseModal: () => {
        setIsPaymentModalOpen(false)
        setIsGenererCouponModalOpen(false)
        setIsDetailsCouponModalOpen(false)
        setShowTicketPreview(false)
      },
      canCashOut: (user as unknown)?.can_cash_out || user?.is_superuser || false
    },
    {
      sortedFactures,
      selectedRowIndex,
      isPaymentModalOpen,
      isGenererCouponModalOpen,
      isDetailsCouponModalOpen,
      isSudoModalOpen,
      showTicketPreview,
      isCouponPanelOpen
    },
    setSelectedRowIndex
  )

  // Garder l'index valide quand la liste change
  useEffect(() => {
    if (selectedRowIndex >= facturesEnAttente.length && facturesEnAttente.length > 0) {
      setSelectedRowIndex(facturesEnAttente.length - 1)
    }
  }, [facturesEnAttente.length, selectedRowIndex])

  // Hook pour la logique de paiement
  const { loading: paymentLoading, enregistrerPaiement: enregistrerPaiementHook } = useCaissePayment({
    selectedFacture,
    couponsParFacture,
    setCouponsParFacture,
    setTicketCaisse,
    setIsPaymentModalOpen,
    setShowTicketPreview,
    fetchFacturesEnAttente,
    fetchSessionRecap,
    fetchCoupons,
    utiliserCouponApresEncaissement,
    onSuccess: () => toast.success(t('messages.modification_success'))
  })

  // Wrapper pour adapter la signature au PaymentModal
  const enregistrerPaiement = useCallback((paiements: { mode: string; montant: number }[]) => {
    enregistrerPaiementHook(paiements, t, user)
  }, [enregistrerPaiementHook, t, user])
  // Envoi WhatsApp
  const handleSendWhatsApp = async () => {
    if (!ticketCaisse || !ticketCaisse.facture || typeof ticketCaisse.facture === 'number') return
    
    const facture = ticketCaisse.facture as unknown
    // D├®terminer le num├®ro (priorit├® au num├®ro du client si pr├®sent)
    const clientPhone = (typeof facture.client === 'object' ? facture.client?.phone : '') || facture.client_phone
    const phone = window.prompt(t('messages.enter_whatsapp_number') || t('messages.enter_whatsapp_number_desc'), clientPhone || '')
    
    if (!phone) return

    setLoading(true)
    try {
      const response = await api.post(`factures/${facture.id}/send_whatsapp/`, {
        phone: phone
      })
      toast.success(response.data.detail || t('messages.whatsapp_sent'))
    } catch (err) {
      console.error('Erreur envoi WhatsApp:', err)
      toast.error(getApiErrorDetail(err, t('messages.whatsapp_send_error')))
    } finally {
      setLoading(false)
    }
  }



  // Annuler une facture
  const handleAnnuler = async (facture: Facture) => {
    if (!window.confirm(t('confirm_cancel_invoice', { numero: facture.numero_facture }))) return

    try {
      await api.post(`factures/${facture.id}/annuler/`, { motif: 'Annulation depuis Caisse Centrale' })
      toast.success(t('messages.cancel_invoice_success'))
      fetchFacturesEnAttente()
    } catch (err) {
      console.error('Erreur annulation:', err)
      toast.error(t('messages.cancel_invoice_error'))
    }
  }

  // S├®lection en lot
  const toggleSelectFacture = useCallback((id: number) => {
    setSelectedFactureIds(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const selectAllFactures = useCallback(() => {
    setSelectedFactureIds(prev => {
      if (prev.size === facturesEnAttente.length) return new Set()
      return new Set(facturesEnAttente.map(f => f.id))
    })
  }, [facturesEnAttente])

  const canBulkCancel = user?.is_superuser || (user as unknown)?.can_cancel_invoice || (user as unknown)?.profile?.can_cancel_invoice

  // Ouvrir le modal de confirmation
  const handleBulkCancelClick = () => {
    if (selectedFactureIds.size === 0 && facturesEnAttente.length === 0) return
    setShowBulkCancelModal(true)
  }

  // Confirmer ÔåÆ demander sudo ÔåÆ ex├®cuter par lots
  const handleConfirmBulkCancel = () => {
    const BATCH_SIZE = 50
    const factureIdsToSend = selectedFactureIds.size > 0 ? Array.from(selectedFactureIds) : null
    const isAllPending = !factureIdsToSend || factureIdsToSend.length === facturesEnAttente.length

    requireSudo(
      async (validatorId: number, password: string) => {
        setBulkCancelLoading(true)
        setBulkProgress({ processed: 0, total: factureIdsToSend ? factureIdsToSend.length : facturesEnAttente.length })
        let totalSuccess = 0
        let totalError = 0
        let totalStockReintegrated = 0

        try {
          let remainingIds = factureIdsToSend ? [...factureIdsToSend] : null
          let totalProcessed = 0
          let totalRemaining = remainingIds ? remainingIds.length : facturesEnAttente.length
          let hasMore = true

          while (hasMore) {
            const payload: Record<string, unknown> = {
              motif: 'Vidange caisse centrale',
              sudo_user: validatorId,
              sudo_password: password,
              batch_size: BATCH_SIZE,
            }
            if (isAllPending) {
              payload.all_pending = true
            } else {
              payload.facture_ids = remainingIds!.slice(0, BATCH_SIZE)
            }

            const { data } = await api.post('factures/bulk_cancel/', payload)
            totalSuccess += data.success_count || 0
            totalError += data.error_count || 0
            totalStockReintegrated += data.total_stock_reintegrated || 0
            totalProcessed += data.processed || 0
            totalRemaining = data.remaining ?? 0

            setBulkProgress({ processed: totalProcessed, total: totalProcessed + totalRemaining })

            if (totalRemaining === 0) {
              hasMore = false
            } else if (!isAllPending) {
              remainingIds = remainingIds!.slice(data.processed)
              if (remainingIds.length === 0) hasMore = false
            }
          }

          toast.success(`${totalSuccess} facture(s) annul├®e(s). ${totalStockReintegrated} lignes de stock r├®int├®gr├®es.`)
          if (totalError > 0) {
            toast.error(`${totalError} erreur(s) au total`)
          }
          setSelectedFactureIds(new Set())
          setShowBulkCancelModal(false)
          fetchFacturesEnAttente()
        } catch (err: unknown) {
          toast.error(getApiErrorDetail(err, t('messages.bulk_cancel_error')))
          throw err
        } finally {
          setBulkCancelLoading(false)
          setBulkProgress(null)
        }
      },
      {
        title: t('bulk_cancel_sudo_title', { defaultValue: 'Validation requise ÔÇö Vidange caisse' }),
        message: t('bulk_cancel_sudo_msg', { defaultValue: 'Cette action annule des factures et r├®int├¿gre le stock. Validation d\'un administrateur requise.' }),
      }
    )
  }

  // Hooks pour les modifications
  const {
    handleFullModification,
    handleUpdateQuantity,
    handleRemoveProduct: handleRemoveProductBase
  } = useInvoiceModification({
    setLoading,
    fetchFacturesEnAttente,
    t
  })

  // Wrappers pour les modifications partielles
  const handleModifier = useCallback((facture: Facture) => {
    handleFullModification(facture)
  }, [handleFullModification])

  const handleUpdateProductQuantity = useCallback((factureId: number, produitId: number, newQty: number) => {
    handleUpdateQuantity(factureId, produitId, newQty, facturesEnAttente)
  }, [handleUpdateQuantity, facturesEnAttente])

  const handleRemoveProduct = useCallback((factureId: number, produitId: number) => {
    handleRemoveProductBase(factureId, produitId, facturesEnAttente, handleAnnuler)
  }, [handleRemoveProductBase, facturesEnAttente, handleAnnuler])

  // Hook pour les statistiques
  const {
    totalMontantEnAttente,
    activeCouponsCount,
    appliedCouponsCount
  } = useCaisseStats({
    facturesEnAttente,
    coupons,
    couponsParFacture
  })

  return (
    <div className="h-full bg-slate-50 flex flex-col overflow-hidden font-sans">
      <div className="flex-1 overflow-y-auto p-3 sm:p-6 space-y-4">

      {/* Header Card */}
      <CaisseHeader
        isMultiCaisse={isMultiCaisse}
        selectedPosteCaisseId={selectedPosteCaisseId}
        onPosteCaisseChange={setSelectedPosteCaisseId}
        postesCaisses={postesCaisses}
        myActivePoste={myActivePoste}
        hideAmounts={hideAmounts}
        onHideAmountsChange={setHideAmounts}
        onCloseSession={handleCloseSession}
        onOpenSession={() => setShowOpenSessionModal(true)}
        isCouponPanelOpen={isCouponPanelOpen}
        onToggleCouponPanel={() => setIsCouponPanelOpen(!isCouponPanelOpen)}
        activeCouponsCount={activeCouponsCount}
        appliedCouponsCount={appliedCouponsCount}
        canBulkCancel={canBulkCancel}
        facturesCount={facturesEnAttente.length}
        selectedFactureIds={selectedFactureIds}
        onBulkCancelClick={handleBulkCancelClick}
      />

      {/* Quick Stats Cards */}
      <CaisseStatsCards
        facturesCount={facturesEnAttente.length}
        totalMontantEnAttente={totalMontantEnAttente}
        activeCouponsCount={activeCouponsCount}
        appliedCouponsCount={appliedCouponsCount}
      />

      {/* Main Content: Sidebar + Table */}
      <div className="flex gap-6 min-h-0" style={{ height: 'calc(100vh - 340px)' }}>
        {/* Panneau des Coupons (Sidebar Gauche) */}
        {isCouponPanelOpen && (
          <CouponPanel
            coupons={coupons}
            onGenerateCoupon={() => setIsGenererCouponModalOpen(true)}
            searchNumero={searchCouponNumero}
            onSearchChange={setSearchCouponNumero}
            onSearch={handleRechercherCoupon}
            onSelectCoupon={(c) => {
              setCouponTrouve(c)
              setIsDetailsCouponModalOpen(true)
            }}
            user={user}
          />
        )}

        {/* Table Card */}
        <div className="flex-1 bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-0">
          <div className="flex-1 flex flex-col min-h-0 overflow-hidden">
            <FacturesTable
              sortedFactures={sortedFactures}
              loading={loading}
              selectedRowIndex={selectedRowIndex}
              onSelectRow={setSelectedRowIndex}
              onEncaisser={handleEncaisser}
              onRemoveCoupon={handleRetirerCouponWrapper}
              onModify={handleModifier}
              onCancel={handleAnnuler}
              onApplyCoupon={openCouponSelectionForFacture}
              onUpdateProductQuantity={handleUpdateProductQuantity}
              onRemoveProduct={handleRemoveProduct}
              couponsParFacture={couponsParFacture}
              user={user}
              myActivePoste={myActivePoste}
              selectedIds={selectedFactureIds}
              onToggleSelect={toggleSelectFacture}
              onSelectAll={selectAllFactures}
            />
          </div>
          {/* Keyboard Shortcuts Footer */}
          <div className="p-3 border-t border-slate-200 flex items-center justify-between text-xs text-slate-400 bg-white">
            <div className="flex items-center gap-1">
              <Keyboard className="size-3.5" />
              <span className="hidden sm:inline">{t('shortcuts.title')}</span>
            </div>
            <div className="flex gap-3">
              <span><kbd className="inline-block px-1.5 py-0.5 rounded bg-slate-100 border border-slate-200 text-[10px] font-mono">ÔåæÔåô</kbd> {t('shortcuts.navigate')}</span>
              <span><kbd className="inline-block px-1.5 py-0.5 rounded bg-slate-100 border border-slate-200 text-[10px] font-mono">{t('shortcuts.enter_key', 'Entr├®e')}</kbd> {t('shortcuts.cash_in')}</span>
              <span><kbd className="inline-block px-1.5 py-0.5 rounded bg-slate-100 border border-slate-200 text-[10px] font-mono">C</kbd> {t('shortcuts.coupon')}</span>
              <span><kbd className="inline-block px-1.5 py-0.5 rounded bg-slate-100 border border-slate-200 text-[10px] font-mono">R</kbd> {t('shortcuts.refresh')}</span>
              <span><kbd className="inline-block px-1.5 py-0.5 rounded bg-slate-100 border border-slate-200 text-[10px] font-mono">1-9</kbd> {t('shortcuts.quick_select')}</span>
            </div>
          </div>
        </div>
      </div>

      {/* R├®cap Session Live ÔÇö visible selon param├¿tre hide_cash_totals */}
      {sessionRecap?.has_session && (user?.is_superuser || !pharmacySettings?.hide_cash_totals) && (
        <SessionRecapBar sessionRecap={sessionRecap} />
      )}

      </div>

      {/* Modal de paiement */}
      {isPaymentModalOpen && selectedFacture && (
        <PaymentModal
          isOpen={isPaymentModalOpen}
          onClose={() => setIsPaymentModalOpen(false)}
          facture={selectedFacture}
          coupon={couponsParFacture[selectedFacture.id]}
          onConfirm={enregistrerPaiement}
          loading={paymentLoading}
        />
      )}

      <CaisseTicketPreviewModal
        isOpen={showTicketPreview}
        onClose={() => setShowTicketPreview(false)}
        ticket={ticketCaisse}
        settings={pharmacySettings}
        onSendWhatsApp={handleSendWhatsApp}
        loading={loading}
      />

      {/* Modals pour les Coupons */}
      <CouponGenerateModal
        isOpen={isGenererCouponModalOpen}
        onClose={() => setIsGenererCouponModalOpen(false)}
        montant={nouveauCouponMontant}
        onMontantChange={setNouveauCouponMontant}
        notes={nouveauCouponNotes}
        onNotesChange={setNouveauCouponNotes}
        onSubmit={() => setIsSudoModalOpen(true)}
        loading={loading}
      />

      {/* Modal Confirmation Sudo pour Coupon */}
      <PasswordConfirmModal
        isOpen={isSudoModalOpen}
        onClose={() => setIsSudoModalOpen(false)}
        onConfirm={handleGenererCouponWrapper}
        title={t('coupons.sudo_title')}
        message={t('coupons.sudo_confirm', { amount: nouveauCouponMontant })}
      />

      {/* Modal D├®tails Coupon */}
      <CouponDetailsModal
        isOpen={isDetailsCouponModalOpen}
        onClose={() => { setIsDetailsCouponModalOpen(false); setCouponTrouve(null); setSearchCouponNumero(''); }}
        coupon={couponTrouve}
        factureForCoupon={factureForCoupon}
        onAppliquer={handleAppliquerCouponAFacture}
        settings={pharmacySettings}
      />

      {/* Modal Ouvrir Caisse */}
      <OpenCashSessionModal
        isOpen={showOpenSessionModal}
        onClose={() => setShowOpenSessionModal(false)}
        onSessionOpened={async (poste) => {
          if (poste) {
            setMyActivePoste(poste)
            if (poste.caisse) {
              setSelectedPosteCaisseId(String(poste.caisse))
            }
          } else {
            const myActive = await cashSessionService.getMyActivePostesVente().catch(() => [])
            const activePoste = myActive.length > 0 ? myActive[0] : null
            setMyActivePoste(activePoste)
            if (activePoste?.caisse) {
              setSelectedPosteCaisseId(String(activePoste.caisse))
            }
          }
        }}
      />

      {/* Modal Rapport de Cl├┤ture */}
      <ClosingReportModal
        isOpen={showClosingReport}
        onClose={() => setShowClosingReport(false)}
        report={closingReport}
      />

      {/* Modal de confirmation ÔÇö Vidange caisse */}
      <BulkCancelModal
        isOpen={showBulkCancelModal}
        onClose={() => setShowBulkCancelModal(false)}
        onConfirm={handleConfirmBulkCancel}
        facturesEnAttente={facturesEnAttente}
        selectedFactureIds={selectedFactureIds}
        loading={bulkCancelLoading}
        progress={bulkProgress}
      />

      {/* Modal Sudo pour la vidange */}
      <SudoValidationModal
        isOpen={sudoState.isOpen}
        onClose={closeSudo}
        onValidate={sudoState.onValidate}
        saving={sudoState.isValidating}
        title={sudoState.title}
        message={sudoState.message}
      />
    </div>
  )
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import api from '../services/api';
import { toast } from 'react-hot-toast';
import { formatCurrency } from '../utils/formatters';
import { useRecharts } from '../hooks/useRecharts';


interface VendeurRanking {
  vendeur_id: number;
  vendeur: string;
  rang: number;
  nbre_ventes: number;
  chiffre_affaires: number;
  panier_moyen: number;
  evolution?: number | null;
}

interface RankingResponse {
  periode: {
    debut: string;
    fin: string;
    type: string;
  };
  data: VendeurRanking[];
}

const COLORS = ['#10B981', '#3B82F6', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899', '#06B6D4', '#84CC16'];

interface EvolutionSeries {
  vendeur: string;
  vendeur_id: number;
  data: {
    mois: string;
    label: string;
    chiffre_affaires: number;
  }[];
}

const formatMoney = (value: number, currencySymbol: string) => {
  return formatCurrency(value, 'fr-FR', currencySymbol);
};

const getMedal = (rang: number) => {
  switch (rang) {
    case 1: return '­ƒÑç';
    case 2: return '­ƒÑê';
    case 3: return '­ƒÑë';
    default: return rang;
  }
};

export default function ClassementVendeurs() {
  const { t } = useTranslation(['sellers', 'common']);
  const [loading, setLoading] = useState(true);
  const [ranking, setRanking] = useState<RankingResponse | null>(null);
  const [evolutionData, setEvolutionData] = useState<EvolutionSeries[]>([]);
  const [selectedVendeur, setSelectedVendeur] = useState<number | null>(null);
  const [periode, setPeriode] = useState<'mois' | 'trimestre' | 'annee'>('mois');
  const [mois, setMois] = useState(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  });

  // Fetch ranking data
  useEffect(() => {
    const fetchRanking = async () => {
      // Basic validation for YYYY-MM format
      if (!mois || !/^\d{4}-\d{2}$/.test(mois)) {
        console.warn("Format mois invalide:", mois);
        return;
      }

      setLoading(true);
      try {
        const res = await api.get<RankingResponse>('rapports/classement_vendeurs_mensuel/', {
          params: { mois, periode }
        });
        setRanking(res.data);
        
        // Auto-select first vendeur for evolution chart
        if (res.data.data.length > 0 && !selectedVendeur) {
          setSelectedVendeur(res.data.data[0].vendeur_id);
        }
      } catch (err) {
        toast.error(t('common:messages.error_loading'));
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchRanking();
  }, [mois, periode]);

  // Fetch global evolution data
  useEffect(() => {
    const fetchEvolution = async () => {
      try {
        const res = await api.get<EvolutionSeries[]>('rapports/evolution_vendeur/', {
          params: { vendeur_id: 'all' }
        });
        setEvolutionData(res.data);
      } catch (err) {
        console.error(err);
      }
    };
    fetchEvolution();
  }, []);

  // Format data for Recharts (merge series by month)
  const chartData = evolutionData.length > 0 ? evolutionData[0].data.map((point, index) => {
    const mergedPoint: unknown = { label: point.label };
    evolutionData.forEach(series => {
        mergedPoint[series.vendeur] = series.data[index]?.chiffre_affaires || 0;
    });
    return mergedPoint;
  }) : [];

  const Recharts = useRecharts();
  if (!Recharts) return <div className="flex items-center justify-center p-8"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-slate-400" /></div>;
  const { LineChart, Line, BarChart, Bar, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } = Recharts;

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            ­ƒÅå {t('sellers:ranking.title')}
          </h1>
          <p className="text-slate-500 text-sm">
            {t('sellers:ranking.subtitle')}
          </p>
        </div>
        <div className="flex gap-2">
          <input
            type="month"
            className="h-9 px-3 rounded-xl border border-slate-200 bg-white text-xs font-bold text-slate-700 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all"
            value={mois}
            onChange={(e) => setMois(e.target.value)}
          />
          <select
            className="h-9 px-3 rounded-xl border border-slate-200 bg-white text-xs font-bold text-slate-700 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all appearance-none"
            value={periode}
            onChange={(e) => setPeriode(e.target.value as 'mois' | 'trimestre' | 'annee')}
          >
            <option value="mois">{t('sellers:ranking.period.month')}</option>
            <option value="trimestre">{t('sellers:ranking.period.quarter')}</option>
            <option value="annee">{t('sellers:ranking.period.year')}</option>
          </select>
        </div>
      </div>

      {/* Stats Cards */}
      {ranking && ranking.data.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {ranking.data.slice(0, 3).map((v, i) => (
            <div 
              key={v.vendeur_id}
              className={`rounded-2xl shadow-lg cursor-pointer hover:shadow-xl transition-shadow p-5 ${
                i === 0 ? 'bg-gradient-to-br from-yellow-400 to-yellow-600 text-white' :
                i === 1 ? 'bg-gradient-to-br from-gray-300 to-gray-500 text-white' :
                'bg-gradient-to-br from-orange-400 to-orange-600 text-white'
              }`}
              onClick={() => setSelectedVendeur(v.vendeur_id)}
            >
              <div className="flex justify-between items-start">
                <div>
                  <p className="text-4xl font-bold">{getMedal(v.rang)}</p>
                  <h3 className="text-lg font-semibold mt-2">{v.vendeur}</h3>
                </div>
                {v.evolution !== null && v.evolution !== undefined && (
                  <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold ${
                    v.evolution >= 0 ? 'bg-white/20 text-white' : 'bg-black/20 text-white'
                  }`}>
                    {v.evolution >= 0 ? '+' : ''}{v.evolution}%
                  </span>
                )}
              </div>
              <div className="mt-4 space-y-1">
                <p className="text-2xl font-bold">{formatMoney(v.chiffre_affaires, t('common:currency'))}</p>
                <p className="text-sm opacity-80">
                  {v.nbre_ventes} ventes ┬À Panier: {formatMoney(v.panier_moyen, t('common:currency'))}
                </p>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Main Content */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Ranking Table */}
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-5">
          <h3 className="text-base font-bold text-slate-800 mb-4">
            {t('sellers:ranking.table_title')}
          </h3>
          {loading ? (
            <div className="h-64 flex items-center justify-center">
              <span className="size-10 border-4 border-slate-200 border-t-blue-500 rounded-full animate-spin"></span>
            </div>
          ) : ranking && ranking.data.length > 0 ? (
            <div className="overflow-x-auto max-h-96">
              <table className="w-full border-separate border-spacing-0 text-sm">
                <thead>
                  <tr className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-widest">
                    <th className="sticky top-0 bg-slate-50 py-3 pl-3 text-left border-b border-slate-200">#</th>
                    <th className="sticky top-0 bg-slate-50 py-3 text-left border-b border-slate-200">{t('sellers:ranking.seller')}</th>
                    <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200">{t('sellers:ranking.sales')}</th>
                    <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200">{t('sellers:ranking.revenue')}</th>
                    <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200">{t('sellers:ranking.avg_basket')}</th>
                    <th className="sticky top-0 bg-slate-50 py-3 text-right border-b border-slate-200 pr-3">{t('sellers:ranking.evolution')}</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {ranking.data.map((v) => (
                    <tr 
                      key={v.vendeur_id}
                      className={`cursor-pointer transition-colors ${
                        selectedVendeur === v.vendeur_id ? 'bg-blue-50' : 'hover:bg-slate-50'
                      }`}
                      onClick={() => setSelectedVendeur(v.vendeur_id)}
                    >
                      <td className="py-2.5 pl-3 font-bold text-slate-700">{getMedal(v.rang)}</td>
                      <td className="py-2.5 text-slate-700">{v.vendeur}</td>
                      <td className="py-2.5 text-right text-slate-600">{v.nbre_ventes}</td>
                      <td className="py-2.5 text-right font-mono text-slate-800 font-bold">{formatMoney(v.chiffre_affaires, t('common:currency'))}</td>
                      <td className="py-2.5 text-right font-mono text-sm text-slate-600">{formatMoney(v.panier_moyen, t('common:currency'))}</td>
                      <td className="py-2.5 text-right pr-3">
                        {v.evolution !== null && v.evolution !== undefined ? (
                          <span className={`font-bold ${
                            v.evolution >= 0 ? 'text-emerald-600' : 'text-red-500'
                          }`}>
                            {v.evolution >= 0 ? '+' : ''}{v.evolution}%
                          </span>
                        ) : '-'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="h-64 flex items-center justify-center text-slate-400">
              {t('sellers:ranking.no_data')}
            </div>
          )}
        </div>

        {/* Evolution Chart */}
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-5">
          <h3 className="text-base font-bold text-slate-800 mb-4">
            {t('sellers:ranking.evolution_chart')}
          </h3>
          {chartData.length > 0 ? (
            <ResponsiveContainer width="100%" height={350}>
              <LineChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" opacity={0.3} />
                <XAxis dataKey="label" fontSize={11} />
                <YAxis tickFormatter={(v: number) => `${(v / 1000).toFixed(0)}k`} fontSize={11} />
                <Tooltip formatter={(value: number) => formatMoney(value, t('common:currency'))} />
                <Legend />
                {evolutionData.map((series, index) => (
                  <Line 
                    key={series.vendeur_id}
                    type="monotone" 
                    dataKey={series.vendeur} 
                    name={series.vendeur} 
                    stroke={COLORS[index % COLORS.length]} 
                    strokeWidth={2}
                    dot={false}
                    opacity={selectedVendeur === null || selectedVendeur === series.vendeur_id ? 1 : 0.2}
                  />
                ))}
              </LineChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-80 flex items-center justify-center text-slate-400">
              {t('common:loading')}
            </div>
          )}
        </div>
      </div>

      {/* Bar Chart Comparison (Top 5) */}
      {ranking && ranking.data.length > 0 && (
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-5">
          <h3 className="text-base font-bold text-slate-800 mb-4">
            {t('sellers:ranking.comparison')}
          </h3>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={ranking.data.slice(0, 5)} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" opacity={0.3} />
                <XAxis type="number" tickFormatter={(v: number) => `${(v / 1000).toFixed(0)}k`} />
                <YAxis type="category" dataKey="vendeur" width={100} fontSize={12} />
                <Tooltip formatter={(value: number) => formatMoney(value, t('common:currency'))} />
                <Bar dataKey="chiffre_affaires" name={t('sellers:ranking.revenue')} radius={[0, 4, 4, 0]}>
                  {ranking.data.slice(0, 5).map((entry, index) => (
                    <Cell key={entry.vendeur} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import api from '../services/api';
import { useLocation, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { toast } from 'react-hot-toast';
import {
  UserPlus, Users, Settings, Trash2, Eye, EyeOff, Search, Phone, MapPin, Mail,
  User, ShoppingBag, ShieldCheck, Edit, Activity, CreditCard, ArrowLeft
} from 'lucide-react';
import { Button } from './shadcn/button';
import { Badge } from './shadcn/badge';
import { Checkbox } from './shadcn/checkbox';
import { Input } from './shadcn/input';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from './ui/Table';
import { cn } from '../lib/utils';

import type { Client, AyantDroit } from '../types';
import ClientDepositModal from './clients/ClientDepositModal';
import ClientDeleteWarningModal from './clients/ClientDeleteWarningModal';
import BulkDeleteWarningModal from './clients/BulkDeleteWarningModal';
import clientService from '../services/clientService';
import { formatCurrency, normalizeNumberInput } from '../utils/formatters';
import { clientSchema } from '../schemas/clientSchema';

// Components
import LoyaltyConfigModal from './LoyaltyConfigModal';
import ClientFormModal from './clients/ClientFormModal';
import PurchaseHistoryDrawer from './clients/PurchaseHistoryDrawer';
import SelectionHeader from './ui/SelectionHeader';
import Pagination from './ui/Pagination';

const emptyForm: Partial<Client> = {
  name: '',
  address: '',
  phone: '',
  email: '',
  client_type: 'PARTICULIER',
  plafond: '0',
  taux_couverture: '0',
  remise_automatique: '0',
  majoration_pro_pourcentage: '0',
  ayants_droit: [],
  is_active: true,
  is_deposit_enabled: false
};

export default function Clients() {
  const { t } = useTranslation(['clients', 'common']);
  const [clients, setClients] = useState<Client[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [showInactive, setShowInactive] = useState<boolean>(false);
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const itemsPerPage = 50;
  const location = useLocation();
  const navigate = useNavigate();

  // View/Navigation State
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [formMode, setFormMode] = useState<'create' | 'edit'>('create');
  const [formData, setFormData] = useState<Partial<Client>>(emptyForm);
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [debouncedSearch, setDebouncedSearch] = useState<string>('');
  const [isLoyaltyConfigOpen, setIsLoyaltyConfigOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isDepositModalOpen, setIsDepositModalOpen] = useState(false);
  const [isDeleteWarningOpen, setIsDeleteWarningOpen] = useState(false);
  const [deleteWarningData, setDeleteWarningData] = useState<{
    clientName: string;
    invoiceCount: number;
    totalDue: number;
    invoices: Array<{
      id: number;
      numero: string;
      date: string;
      total_ttc: number;
      paid: number;
      remainder: number;
    }>;
  } | null>(null);
  const [isBulkDeleteWarningOpen, setIsBulkDeleteWarningOpen] = useState(false);
  const [bulkDeleteWarningData, setBulkDeleteWarningData] = useState<{
    clientCount: number;
    clientsWithUnpaid: Array<{
      id: number;
      name: string;
      invoice_count: number;
      total_due: number;
    }>;
    totalDue: number;
  } | null>(null);
  const [loyaltyThreshold, setLoyaltyThreshold] = useState<number>(0);

  // Purchase History State
  const [purchaseHistory, setPurchaseHistory] = useState<unknown | null>(null);
  const [loadingHistory, setLoadingHistory] = useState(false);

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setCurrentPage(1);
    }, 300);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  const fetchClients = async (skipCache: boolean = false) => {
    setLoading(true);
    try {
      const data = await clientService.getAll({
        search: debouncedSearch,
        page: currentPage,
        page_size: itemsPerPage,
        // @ts-ignore - Backend supports include_inactive
        include_inactive: showInactive
      }, skipCache);
      
      if (data && 'results' in data) {
        setClients(data.results);
        setTotalCount(data.count);
      } else {
        setClients(data);
        setTotalCount(data.length);
      }
    } catch {
      toast.error(t('clients:messages.error_fetch'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
    fetchLoyaltyThreshold();
  }, [showInactive, currentPage, debouncedSearch]);

  const fetchLoyaltyThreshold = async () => {
    try {
      const res = await api.get('loyalty-settings/');
      let data = res.data;
      if (data && data.results) data = data.results[0];
      else if (Array.isArray(data)) data = data[0];
      
      if (data && data.auto_reward_threshold) {
        setLoyaltyThreshold(data.auto_reward_threshold);
      }
    } catch (err) {
      console.error("Error fetching loyalty threshold", err);
    }
  };

  // Handle incoming redirect from Omnisearch
  useEffect(() => {
    if (location.state?.action === 'NEW_CLIENT') {
      handleOpenCreate();
      navigate(location.pathname, { replace: true, state: {} });
    }
    if (location.state?.selectedClientId && clients.length > 0) {
      const cid = location.state.selectedClientId;
      const found = clients.find((c: Client) => c.id === cid);
      if (found) {
        handleSelectClient(found);
        // Clear state to avoid re-triggering
        navigate(location.pathname, { replace: true, state: {} });
      } else {
        if (searchTerm !== String(cid)) {
          setSearchTerm(String(cid));
        }
      }
    }
  }, [clients]);

  const handleSelectClient = async (client: Client) => {
    setLoadingHistory(true);
    try {
      // Fetch full details or at least beneficiaries to ensure the right panel is complete
      const [history, ayantsDroit] = await Promise.all([
        clientService.getPurchaseHistory(client.id),
        clientService.getAyantsDroit(client.id)
      ]);
      
      setPurchaseHistory(history);
      setSelectedClient({
        ...client,
        ayants_droit: ayantsDroit
      });
    } catch (err) {
      console.error(err);
      setSelectedClient(client);
    } finally {
      setLoadingHistory(false);
    }
  };

  const handleOpenCreate = () => {
    setFormMode('create');
    setFormData(emptyForm);
    setIsFormModalOpen(true);
  };

  const handleOpenEdit = (client: Client) => {
    setFormMode('edit');
    setFormData({...client});
    setIsFormModalOpen(true);
  };

  const handleFormSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
        // Validation avec Zod
        const validation = clientSchema.safeParse(formData);
        if (!validation.success) {
            const errorMsg = (validation.error as unknown).errors
                .map((err: unknown) => `${t(`clients:fields.${err.path[0]}`)}: ${err.message}`)
                .join('\n');
            toast.error(errorMsg, { duration: 5000 });
            setIsSubmitting(false);
            return;
        }

        const cleanData = validation.data as unknown;

        if (formMode === 'create') {
            const created = await clientService.create(cleanData);
            setClients(prev => [created, ...prev]);
            toast.success(t('clients:messages.create_success'));
        } else if (formData.id) {
            const updated = await clientService.update(formData.id, cleanData);
            setClients(prev => prev.map(c => c.id === updated.id ? updated : c));
            if (selectedClient?.id === updated.id) {
                setSelectedClient(updated);
            }
            toast.success(t('clients:messages.update_success'));
        }
        setIsFormModalOpen(false);
    } catch (err: unknown) {
        toast.error(err.response?.data?.message || t('clients:messages.error_save'));
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleDelete = async () => {
    if (!selectedClient) return;

    // V├®rifier d'abord si le client a des factures impay├®es
    try {
      const checkResult = await clientService.checkUnpaidInvoices(selectedClient.id);

      if (checkResult.has_unpaid) {
        // Afficher le modal d'avertissement et emp├¬cher la suppression
        setDeleteWarningData({
          clientName: selectedClient.name,
          invoiceCount: checkResult.count,
          totalDue: checkResult.total_due,
          invoices: checkResult.invoices
        });
        setIsDeleteWarningOpen(true);
        return;
      }
    } catch (err) {
      console.error('[Clients] Erreur lors de la v├®rification des factures:', err);
      // En cas d'erreur, on continue avec la confirmation standard
    }

    // Si pas de factures impay├®es, proc├®der ├á la confirmation
    if (window.confirm(t('clients:modals.delete_confirm', { name: selectedClient.name }))) {
        const deletedId = selectedClient.id;

        try {
            setClients(prev => prev.filter(c => c.id !== deletedId));
            setTotalCount(prev => prev - 1);
            setSelectedClient(null);
            await clientService.delete(deletedId);
            toast.success(t('clients:messages.delete_success'));
            setTimeout(() => fetchClients(true), 500);
        } catch (err: unknown) {
            console.error('[Clients] Delete error:', err);
            toast.error(err.response?.data?.detail || t('clients:messages.error_delete'));
            fetchClients(true);
        }
    }
  };

  const handleToggleActive = async () => {
    if (!selectedClient) return;
    try {
        const res = await clientService.toggleActive(selectedClient.id);
        toast.success(res.is_active ? t('clients:messages.status_active') : t('clients:messages.status_inactive'));
        setSelectedClient({...selectedClient, is_active: res.is_active});
        setTimeout(() => fetchClients(true), 500);
    } catch {
        toast.error(t('clients:messages.error_status'));
    }
  };

  const handleBulkDelete = async () => {
    if (selectedIds.length === 0) return;

    // V├®rifier d'abord si des clients ont des factures impay├®es
    try {
      const checkResult = await clientService.bulkCheckUnpaid(selectedIds);

      if (checkResult.has_unpaid) {
        // Afficher le modal d'avertissement et emp├¬cher la suppression
        setBulkDeleteWarningData({
          clientCount: selectedIds.length,
          clientsWithUnpaid: checkResult.clients,
          totalDue: checkResult.total_due
        });
        setIsBulkDeleteWarningOpen(true);
        return;
      }
    } catch (err) {
      console.error('[Clients] Erreur lors de la v├®rification bulk des factures:', err);
      // En cas d'erreur, on continue avec la confirmation standard
    }

    const confirmed = window.confirm(t('clients:modals.bulk_delete_confirm', { count: selectedIds.length }));

    if (confirmed) {
        const selectedSet = new Set(selectedIds);
        setClients(prev => prev.filter(c => !selectedSet.has(c.id)));
        setTotalCount(prev => prev - selectedIds.length);

        try {
            await clientService.bulkDelete(selectedIds);
            toast.success(t('clients:messages.bulk_delete_success', { count: selectedIds.length }));
            setSelectedIds([]);
            setTimeout(() => fetchClients(true), 500);
        } catch (err: unknown) {
            console.error('[Clients] Bulk delete error:', err);
            toast.error(err.response?.data?.detail || t('clients:messages.error_bulk_delete'));
            fetchClients(true);
        }
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-full bg-slate-50">
      {/* LEFT PANEL */}
      <div className={cn("w-full lg:w-1/3 border-b lg:border-b-0 lg:border-r border-slate-200 flex flex-col bg-white h-full lg:h-full", selectedClient ? 'hidden lg:flex' : 'flex')}>
        <div className="p-4 border-b border-slate-200 space-y-4">
           {selectedIds.length > 0 ? (
             <SelectionHeader
                selectedCount={selectedIds.length}
                onClear={() => setSelectedIds([])}
                colSpan={1}
                actions={
                  <li>
                    <a onClick={handleBulkDelete} className="text-red-600 hover:bg-red-50 font-medium">
                      <Trash2 className="size-4" />
                      {t('clients:actions.bulk_delete', { count: selectedIds.length })}
                    </a>
                  </li>
                }
             >
                <></>
             </SelectionHeader>
           ) : (
             <div className="flex justify-between items-center h-10">
               <div className="flex items-center gap-2">
                 <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg">
                    <Users className="size-5" />
                 </div>
                 <h2 className="font-bold text-lg text-slate-800">{t('clients:title')}</h2>
                 <Badge variant="secondary" className="text-xs">{totalCount}</Badge>
               </div>
               <div className="flex gap-1 items-center">
                 <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => setShowInactive(!showInactive)}
                    className={cn("size-9", showInactive ? 'bg-emerald-50 text-emerald-600' : 'text-slate-500')}
                    title={showInactive ? t('clients:filters.hide_inactive') : t('clients:filters.show_inactive')}
                 >
                    {showInactive ? <Eye className="size-4" /> : <EyeOff className="size-4" />}
                 </Button>
                 <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => setIsLoyaltyConfigOpen(true)}
                    className="size-9 text-slate-500"
                 >
                    <Settings className="size-4" />
                 </Button>
                 <Button size="sm" className="gap-2 bg-emerald-600 hover:bg-emerald-700" onClick={handleOpenCreate}>
                   <UserPlus className="size-4" />
                   {t('clients:actions.create')}
                 </Button>
               </div>
             </div>
           )}

           <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-slate-400" />
              <Input
                className="w-full pl-10 h-10 rounded-lg bg-slate-100 border border-slate-200 text-sm text-slate-700"
                placeholder={t('clients:filters.search_placeholder')}
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />
           </div>
        </div>

        <div className="flex-1 overflow-y-auto">
          {loading && clients.length === 0 ? (
            <div className="flex justify-center p-12">
              <div className="animate-spin rounded-full size-8 border-b-2 border-emerald-600"></div>
            </div>
          ) : (
            <ul className="p-2 space-y-0.5">
               {clients.map(client => {
                 const selectedSet = new Set(selectedIds);
                 return (
                 <li key={client.id}>
                    <div className={cn("flex items-center gap-2 p-2 rounded-lg transition-all cursor-pointer", selectedClient?.id === client.id ? 'bg-emerald-50' : 'hover:bg-slate-100')} onClick={() => handleSelectClient(client)}>
                       <Checkbox
                         checked={selectedSet.has(client.id)}
                         onCheckedChange={() => setSelectedIds(prev => { const s = new Set(prev); return s.has(client.id) ? prev.filter(id => id !== client.id) : [...prev, client.id]; })}
                         onClick={(e) => e.stopPropagation()}
                       />
                       <div className="flex-1 min-w-0">
                          <div className="flex justify-between items-center">
                             <p className={cn("text-sm font-semibold truncate", selectedClient?.id === client.id ? 'text-emerald-700' : 'text-slate-800')}>{client.name}</p>
                             <Badge variant="outline" className={cn("text-[10px] font-semibold uppercase tracking-wide", client.client_type === 'PROFESSIONNEL' ? 'bg-amber-50 text-amber-600 border-amber-200' : 'bg-slate-100 text-slate-500 border-slate-200')}>
                                {client.client_type === 'PROFESSIONNEL' ? t('clients:types.pro_short') : t('clients:types.part_short')}
                             </Badge>
                          </div>
                          <div className="flex items-center justify-between gap-1.5 text-xs text-slate-500">
                             <span className="flex items-center gap-1"><Phone className="size-3" /> {client.phone || 'ÔÇö'}</span>
                             {client.client_type === 'PROFESSIONNEL' && (client as unknown).ayants_droit_count > 0 && (
                               <span className="flex items-center gap-0.5 text-emerald-600 bg-emerald-50 px-1.5 py-0.5 rounded text-[10px] font-medium">
                                 <Users className="size-3" />
                                 {(client as unknown).ayants_droit_count}
                               </span>
                             )}
                          </div>
                       </div>
                    </div>
                 </li>
                 );
               })}
            </ul>
          )}
        </div>

        <Pagination
          currentPage={currentPage}
          totalPages={Math.ceil(totalCount / itemsPerPage)}
          totalItems={totalCount}
          onPrev={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
          onNext={() => setCurrentPage(prev => prev + 1)}
          hasNext={currentPage < Math.ceil(totalCount / itemsPerPage)}
        />
      </div>

      {/* RIGHT PANEL */}
      <div className={cn("flex-1 bg-slate-50 flex flex-col overflow-hidden max-w-full h-full", !selectedClient ? 'hidden lg:flex' : 'flex')}>
        {selectedClient ? (
          <>
            <div className="p-4 lg:p-6 border-b border-slate-200 bg-white flex flex-col sm:flex-row justify-between items-start sm:items-center shrink-0 gap-4">
               <div className="flex items-center gap-4 w-full">
                  <Button
                    variant="ghost"
                    size="icon"
                    className="lg:hidden mr-1"
                    onClick={() => setSelectedClient(null)}
                  >
                    <ArrowLeft className="size-5 text-slate-500" />
                  </Button>
                  <div className="size-12 lg:w-14 lg:h-14 bg-emerald-100 text-emerald-600 rounded-xl flex items-center justify-center text-xl lg:text-2xl font-bold shrink-0">
                    {selectedClient.name.charAt(0)}
                  </div>
                  <div>
                     <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                       {selectedClient.name}
                       {selectedClient.is_active === false && <Badge variant="outline" className="bg-amber-50 text-amber-600 border-amber-200 text-[10px]">{t('clients:status.inactive')}</Badge>}
                     </h2>
                     <p className="flex items-center gap-3 text-xs text-slate-500 mt-0.5">
                        <span className="flex items-center gap-1"><Phone className="size-3" /> {selectedClient.phone || 'ÔÇö'}</span>
                        <span className="flex items-center gap-1"><Mail className="size-3" /> {selectedClient.email || 'ÔÇö'}</span>
                     </p>
                  </div>
               </div>
               <div className="flex items-center gap-2">
                  <Button variant="outline" size="sm" className="gap-2" onClick={() => handleOpenEdit(selectedClient)}>
                    <Edit className="size-4" /> {t('common:edit')}
                  </Button>
                  <Button variant="outline" size="sm" className="gap-2 border-red-200 text-red-600 hover:bg-red-50" onClick={handleDelete}>
                    <Trash2 className="size-4" /> {t('common:delete')}
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => setIsHistoryOpen(true)}
                    className="text-emerald-600 bg-emerald-50 hover:bg-emerald-100"
                    title={t('clients:sections.purchase_history')}
                  >
                    <ShoppingBag className="size-4" />
                  </Button>
                  {selectedClient.client_type === 'PARTICULIER' && selectedClient.is_deposit_enabled && (
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => setIsDepositModalOpen(true)}
                      className="text-slate-500"
                      title={t('clients:finance.manage_deposit')}
                    >
                      <CreditCard className="size-4" />
                    </Button>
                  )}
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={handleToggleActive}
                    className="text-slate-500"
                  >
                    {selectedClient.is_active ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
                  </Button>
               </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6">
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 max-w-5xl">
                  {/* Info Card */}
                  <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                     <div className="px-5 py-3 border-b border-slate-200 bg-slate-50 flex items-center gap-2">
                        <div className="p-1.5 bg-emerald-100 text-emerald-600 rounded-md"><User className="size-4" /></div>
                        <h3 className="text-xs font-semibold uppercase tracking-wider text-slate-500">{t('clients:sections.contact')}</h3>
                     </div>
                     <div className="p-5 space-y-4">
                        <div className="space-y-1">
                           <span className="text-[10px] font-semibold uppercase tracking-wider text-slate-400">{t('clients:fields.address')}</span>
                           <div className="flex items-start gap-2 text-sm text-slate-700">
                              <MapPin className="size-4 text-emerald-500 mt-0.5 shrink-0" />
                              <span>{selectedClient.address || t('common:no_address')}</span>
                           </div>
                        </div>
                        <div className="space-y-1">
                           <span className="text-[10px] font-semibold uppercase tracking-wider text-slate-400">{t('clients:fields.type')}</span>
                           <div className="text-sm font-medium text-slate-700 flex items-center gap-2">
                              <Activity className="size-4 text-slate-500" />
                              {selectedClient.client_type === 'PROFESSIONNEL' ? t('clients:types.professional') : t('clients:types.individual')}
                           </div>
                        </div>
                     </div>
                  </div>

                  {/* Finance/Loyalty Card */}
                  <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                     <div className="px-5 py-3 border-b border-slate-200 bg-slate-50 flex items-center gap-2">
                        <div className="p-1.5 bg-amber-100 text-amber-600 rounded-md"><ShieldCheck className="size-4" /></div>
                        <h3 className="text-xs font-semibold uppercase tracking-wider text-slate-500">{t('clients:sections.programs')}</h3>
                     </div>
                     <div className="p-5 grid grid-cols-2 gap-3">
                        {selectedClient.client_type === 'PARTICULIER' && (
                           <div className="p-3 bg-amber-50 border border-amber-100 rounded-lg flex flex-col gap-1 relative">
                              <span className="text-[10px] font-semibold uppercase tracking-wider text-amber-600/70">{t('clients:history.loyalty')}</span>
                              <div className="flex justify-between items-end">
                                 <div className="text-lg font-bold text-amber-600">
                                    {selectedClient.points_fidelite ?? 0} {t('clients:units.pts')}
                                 </div>
                                 {loyaltyThreshold > 0 && (
                                   <div className="relative size-10 flex items-center justify-center">
                                     <svg className="absolute inset-0 size-10 -rotate-90" viewBox="0 0 36 36">
                                       <circle cx="18" cy="18" r="16" fill="none" stroke="currentColor" strokeWidth="3" className="text-amber-200" />
                                       <circle cx="18" cy="18" r="16" fill="none" stroke="currentColor" strokeWidth="3" strokeDasharray={`${Math.min(100, ((selectedClient.points_fidelite ?? 0) / loyaltyThreshold) * 100)} 100`} strokeLinecap="round" className="text-amber-500 transition-all" />
                                     </svg>
                                     <span className="text-[10px] font-bold text-amber-600">
                                       {Math.min(100, Math.round(((selectedClient.points_fidelite ?? 0) / loyaltyThreshold) * 100))}%
                                     </span>
                                   </div>
                                 )}
                              </div>
                              {loyaltyThreshold > 0 && (selectedClient.points_fidelite ?? 0) >= loyaltyThreshold && (
                                <div className="absolute top-2 right-2">
                                  <div className="size-2 bg-emerald-500 rounded-full animate-ping"></div>
                                </div>
                              )}
                           </div>
                        )}
                        {selectedClient.client_type === 'PARTICULIER' && (
                          <>
                            {selectedClient.is_deposit_enabled ? (
                              <div className="p-3 bg-indigo-50 border border-indigo-100 rounded-lg flex flex-col gap-1 cursor-pointer hover:bg-indigo-100 transition-colors" onClick={() => setIsDepositModalOpen(true)}>
                                 <span className="text-[10px] font-semibold uppercase tracking-wider text-indigo-500/70">{t('clients:finance.solde_depot')}</span>
                                 <div className="text-lg font-bold text-indigo-600">{formatCurrency(parseFloat(selectedClient.solde_depot || '0'))}</div>
                              </div>
                            ) : (
                              <div className="p-3 bg-slate-100 border border-slate-200 rounded-lg flex flex-col gap-1 text-slate-400">
                                 <span className="text-[10px] font-semibold uppercase tracking-wider text-slate-400">{t('clients:finance.solde_depot')}</span>
                                 <div className="text-lg font-bold text-slate-400">{formatCurrency(0)}</div>
                              </div>
                            )}
                            <div className="p-3 bg-slate-100 border border-slate-200 rounded-lg flex flex-col gap-1">
                               <span className="text-[10px] font-semibold uppercase tracking-wider text-slate-400">{t('clients:finance.auto_discount')}</span>
                               <div className="text-lg font-bold text-slate-700">{selectedClient.remise_automatique || 0}{t('clients:units.percent')}</div>
                            </div>
                          </>
                        )}
                        {selectedClient.client_type === 'PROFESSIONNEL' && (
                          <div className="col-span-2 p-3 bg-indigo-50 border border-indigo-100 rounded-lg flex flex-col gap-1">
                             <span className="text-[10px] font-semibold uppercase tracking-wider text-indigo-500/70">{t('clients:finance.auto_discount')}</span>
                             <div className="text-lg font-bold text-indigo-600">{selectedClient.remise_automatique || 0}{t('clients:units.percent')}</div>
                          </div>
                        )}
                        {selectedClient.client_type === 'PROFESSIONNEL' && (
                          <div className="col-span-2 p-3 bg-amber-50 border border-orange-100 rounded-lg flex justify-between items-center">
                             <div>
                                <span className="text-[10px] font-semibold uppercase tracking-wider text-orange-500/70">{t('clients:finance.debt_usage')}</span>
                                <div className="text-base font-bold text-slate-700">
                                  {formatCurrency(normalizeNumberInput(selectedClient.current_debt || '0'))} <span className="text-slate-400 font-normal">/ {formatCurrency(normalizeNumberInput(selectedClient.plafond || '0'))}</span>
                                </div>
                             </div>
                             <div className="relative size-12 flex items-center justify-center">
                               <svg className="absolute inset-0 size-12 -rotate-90" viewBox="0 0 36 36">
                                 <circle cx="18" cy="18" r="16" fill="none" stroke="currentColor" strokeWidth="4" className="text-orange-200" />
                                 <circle cx="18" cy="18" r="16" fill="none" stroke="currentColor" strokeWidth="4" strokeDasharray={`${Math.min(100, (normalizeNumberInput(selectedClient.current_debt || '0') / normalizeNumberInput(selectedClient.plafond || '1')) * 100)} 100`} strokeLinecap="round" className="text-orange-500 transition-all" />
                               </svg>
                               <span className="text-[10px] font-bold text-amber-600">{(normalizeNumberInput(selectedClient.current_debt || '0') / normalizeNumberInput(selectedClient.plafond || '1') * 100).toFixed(0)}%</span>
                             </div>
                          </div>
                        )}
                        {selectedClient.client_type === 'PROFESSIONNEL' && selectedClient.majoration_pro_pourcentage && parseFloat(selectedClient.majoration_pro_pourcentage) > 0 && (
                           <div className="col-span-2 p-3 bg-red-50 border border-red-100 rounded-lg flex flex-col gap-1">
                              <span className="text-[10px] font-semibold uppercase tracking-wider text-red-500/70">{t('clients:finance.majoration_pro')}</span>
                              <div className="text-lg font-bold text-red-600">+{selectedClient.majoration_pro_pourcentage}{t('clients:units.percent')}</div>
                           </div>
                        )}
                     </div>
                  </div>

                  {/* Beneficiaries Table */}
                  {selectedClient.client_type === 'PROFESSIONNEL' && (
                    <div className="lg:col-span-2 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                       <div className="px-5 py-3 border-b border-slate-200 bg-slate-50 flex items-center gap-2">
                          <Users className="size-4 text-indigo-500" />
                          <h3 className="text-xs font-semibold uppercase tracking-wider text-slate-400">{t('clients:beneficiaries.title')}</h3>
                       </div>
                       <div className="overflow-x-auto">
                          <Table className="min-w-full">
                             <TableHeader>
                                <TableRow className="bg-slate-100 hover:bg-slate-100">
                                   <TableHead className="px-6 py-3 text-left text-[10px] font-semibold text-slate-500 uppercase tracking-wider">{t('clients:beneficiaries.col_name')}</TableHead>
                                   <TableHead className="px-6 py-3 text-left text-[10px] font-semibold text-slate-500 uppercase tracking-wider">{t('clients:beneficiaries.company') || 'Soci├®t├®'}</TableHead>
                                   <TableHead className="px-6 py-3 text-right text-[10px] font-semibold text-slate-500 uppercase tracking-wider">{t('clients:beneficiaries.col_id')}</TableHead>
                                </TableRow>
                             </TableHeader>
                             <TableBody>
                                {selectedClient.ayants_droit && selectedClient.ayants_droit.length > 0 ? (
                                  selectedClient.ayants_droit.map((ad: AyantDroit, _idx: number) => (
                                    <TableRow key={ad.matricule || ad.nom} className="hover:bg-slate-50 transition-colors">
                                       <TableCell className="px-6 py-3 text-sm font-medium text-slate-700">{ad.nom}</TableCell>
                                       <TableCell className="px-6 py-3 text-sm text-slate-500">{ad.societe || 'ÔÇö'}</TableCell>
                                       <TableCell className="px-6 py-3 text-sm font-mono text-slate-500 text-right">{ad.matricule}</TableCell>
                                    </TableRow>
                                  ))
                                ) : (
                                  <TableRow><TableCell colSpan={3} className="py-12 text-center text-sm text-slate-400">{t('clients:beneficiaries.empty')}</TableCell></TableRow>
                                )}
                             </TableBody>
                          </Table>
                       </div>
                    </div>
                  )}
               </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center gap-6 text-slate-300 p-12 text-center">
             <Users className="size-24 text-slate-300" />
             <div>
                <h3 className="text-xl font-bold text-slate-400">{t('clients:modals.select_client_empty')}</h3>
                <p className="text-sm text-slate-400 mt-2 max-w-sm mx-auto">{t('clients:modals.select_client_empty_desc')}</p>
             </div>
          </div>
        )}
      </div>

      {/* MODALS */}
      <ClientFormModal 
        isOpen={isFormModalOpen}
        onClose={() => setIsFormModalOpen(false)}
        onSubmit={handleFormSubmit}
        data={formData}
        setData={setFormData}
        isSubmitting={isSubmitting}
        isEdit={formMode === 'edit'}
      />

      <PurchaseHistoryDrawer 
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        data={purchaseHistory}
        loading={loadingHistory}
      />

      <LoyaltyConfigModal 
        isOpen={isLoyaltyConfigOpen}
        onClose={() => setIsLoyaltyConfigOpen(false)}
      />

      {selectedClient && (
        <ClientDepositModal
          isOpen={isDepositModalOpen}
          onClose={() => setIsDepositModalOpen(false)}
          client={selectedClient}
          onSuccess={fetchClients}
        />
      )}

      <ClientDeleteWarningModal
        isOpen={isDeleteWarningOpen}
        onClose={() => setIsDeleteWarningOpen(false)}
        clientName={deleteWarningData?.clientName || ''}
        invoiceCount={deleteWarningData?.invoiceCount || 0}
        totalDue={deleteWarningData?.totalDue || 0}
        invoices={deleteWarningData?.invoices || []}
      />

      <BulkDeleteWarningModal
        isOpen={isBulkDeleteWarningOpen}
        onClose={() => setIsBulkDeleteWarningOpen(false)}
        clientCount={bulkDeleteWarningData?.clientCount || 0}
        clientsWithUnpaid={bulkDeleteWarningData?.clientsWithUnpaid || []}
        totalDue={bulkDeleteWarningData?.totalDue || 0}
      />
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useCommandesState } from '../hooks/useCommandesState';
import { ShoppingCart, Store, Truck } from 'lucide-react';
import { Button } from './shadcn/button';
import { Badge } from './shadcn/badge';
import { cn } from '../lib/utils';

function scrollMainToTop() {
  const main = document.querySelector('main');
  if (main) main.scrollTop = 0;
}

import CommandeList from './Commandes/CommandeList';
import CommandeForm from './Commandes/CommandeForm';
import CommandeDetails from './Commandes/CommandeDetails';

import ProduitFormModal from './ProduitFormModal';
import SimplePrintLabelsModal from './SimplePrintLabelsModal';
import SudoValidationModal from './common/SudoValidationModal';
import TransferCommandeModal from './Commandes/TransferCommandeModal';
import MergeCommandesModal from './Commandes/MergeCommandesModal';
import SuggestionCommandeModal from './Commandes/SuggestionCommandeModal';
import { ProductDetailsModal } from './products/modals/ProductDetailsModal';
import { useProduit, useProduitLots, useProduitStats, useProduitAchats, useProduitHistory } from '../hooks/useProduits';

interface CommandesProps {
    forcedType?: 'LOC' | 'DIR' | 'DIV';
}

export default function Commandes({ forcedType }: CommandesProps) {
  const hook = useCommandesState(forcedType);
  const { state, listProps, detailsProps, formProps, modals } = hook;
  const [detailProduitId, setDetailProduitId] = useState<number | null>(null);
  const [detailActiveTab, setDetailActiveTab] = useState('general');

  const { data: detailProduit } = useProduit(detailProduitId);
  const { data: detailLots = [] } = useProduitLots(detailProduitId);
  const { data: detailStats = [] } = useProduitStats(detailProduitId);
  const { data: detailAchats = [] } = useProduitAchats(detailProduitId);
  const { data: detailHistory = [], isLoading: detailHistoryLoading } = useProduitHistory(detailProduitId, detailActiveTab);

  const handleViewProductDetails = (produitId: number) => {
    setDetailProduitId(produitId);
    setDetailActiveTab('general');
  };
  
  const location = useLocation();
  const navigate = useNavigate();
  useEffect(() => {
    const pathname = location.pathname;
    if (location.state?.action === 'NEW_ORDER') {
      listProps.onOpenCreateView();
      navigate(pathname, { replace: true, state: {} });
    } else if (location.state?.action === 'OPEN_SUGGESTIONS') {
      state.setIsSuggestionModalOpen(true);
      navigate(pathname, { replace: true, state: {} });
    } else if (location.state?.selectedCommandeId && listProps.sortedCommandes.length > 0) {
      const cid = location.state.selectedCommandeId;
      const found = listProps.sortedCommandes.find((c: unknown) => c.id === cid);
      if (found) {
        listProps.onViewDetails(found);
        navigate(pathname, { replace: true, state: {} });
      }
    } else if (location.state?.selectedFournisseurId && listProps.sortedCommandes.length > 0) {
      const fid = location.state.selectedFournisseurId;
      // Filtrer les commandes par fournisseur
      const supplierOrders = listProps.sortedCommandes.filter((c: unknown) => c.fournisseur === fid || c.fournisseur_id === fid);
      if (supplierOrders.length > 0) {
        listProps.onViewDetails(supplierOrders[0]);
        navigate(pathname, { replace: true, state: {} });
      }
    }
  }, [listProps, navigate, state, location.state]);

  useEffect(() => {
    if (state.viewMode !== 'LIST') {
      scrollMainToTop();
    }
  }, [state.viewMode]);
  
  return (
    <div className="flex-1 flex flex-col overflow-hidden bg-slate-50">
      {/* Header moderne */}
      <div className="px-6 py-4 border-b border-slate-200 bg-white shrink-0 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-emerald-100 rounded-lg">
              <ShoppingCart className="size-5 text-emerald-600" />
            </div>
            <h1 className="text-lg font-bold text-slate-800">
                {state.activeTab === 'DIV' ? state.t('orders:title_divers') : state.activeTab === 'DIR' ? state.t('orders:title_direct') : state.t('orders:title_local')}
            </h1>
            <Badge variant="secondary" className="ml-2">
              {listProps.totalCount || 0}
            </Badge>
          </div>

          {!forcedType && (
            <div className="bg-slate-100 p-1 rounded-lg flex gap-1">
                <Button
                  variant={state.activeTab === 'LOC' ? 'default' : 'ghost'}
                  size="sm"
                  className={cn(
                    "px-5 py-2 rounded-md text-sm font-medium transition-all",
                    state.activeTab === 'LOC' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                  )}
                  onClick={() => state.setActiveTab('LOC')}
                >
                  <Store className="size-4 mr-2" />
                  {state.t('orders:tabs.local')}
                </Button>
                <Button
                  variant={state.activeTab === 'DIR' ? 'default' : 'ghost'}
                  size="sm"
                  className={cn(
                    "px-5 py-2 rounded-md text-sm font-medium transition-all",
                    state.activeTab === 'DIR' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                  )}
                  onClick={() => state.setActiveTab('DIR')}
                >
                  <Truck className="size-4 mr-2" />
                  {state.t('orders:tabs.direct')}
                </Button>
            </div>
          )}
      </div>

      {state.error && (
        <div role="alert" className="mx-4 mt-4 px-4 py-3 bg-red-50 border border-red-200 rounded-lg text-red-600 text-sm shrink-0">
          {state.error}
        </div>
      )}

      {state.viewMode === 'LIST' && (
        <div className="flex-1 min-h-0 overflow-hidden flex flex-col">
          <CommandeList {...listProps} />
        </div>
      )}

      {state.viewMode === 'DETAILS' && state.selectedCommande && (
        <div className="flex-1 min-h-0 overflow-hidden flex flex-col">
          <CommandeDetails {...(detailsProps as unknown)} />
        </div>
      )}

      {(state.viewMode === 'CREATE' || state.viewMode === 'EDIT') && (
        <div className="flex-1 min-h-0 overflow-hidden flex flex-col">
          <CommandeForm {...(formProps as unknown)} onViewProductDetails={handleViewProductDetails} />
        </div>
      )}

      {state.isSuggestionModalOpen && (
        <SuggestionCommandeModal 
          onClose={() => state.setIsSuggestionModalOpen(false)}
          onApply={(products, supplierId) => {
            modals.handleApplySuggestions(products, supplierId);
            state.setIsSuggestionModalOpen(false);
          }}
          fournisseurs={modals.fournisseurs}
          produitsList={modals.produitsList}
        />
      )}

      <ProduitFormModal
        open={state.isCreateProduitModalOpen}
        onClose={() => state.setIsCreateProduitModalOpen(false)}
        produitsEndpoint="produits/"
        onCreated={modals.handleProduitCreated}
        rayons={modals.rayons}
        fournisseurs={modals.fournisseurs}
        formes={modals.formes}
        title={modals.t('orders:messages.create_new_product')}
      />

      {state.showPrintLabelsModal && state.selectedCommande && (
        <SimplePrintLabelsModal
          commandeId={state.selectedCommande.id}
          commandeNumero={state.selectedCommande.numero_facture || `#${state.selectedCommande.id}`}
          commande={state.selectedCommande}
          produitsList={modals.produitsList}
          selectedRows={modals.selectedRows}
          onClose={() => state.setShowPrintLabelsModal(false)}
        />
      )}

      <SudoValidationModal
        isOpen={state.sudoState.isOpen}
        onClose={state.closeSudo}
        onValidate={state.sudoState.onValidate}
        saving={state.sudoState.isValidating}
        title={state.sudoState.title || modals.t('orders:messages.validation_required')}
        message={state.sudoState.message || ""}
      />

      {state.isTransferModalOpen && (
        <TransferCommandeModal
          isOpen={state.isTransferModalOpen}
          onClose={() => state.setIsTransferModalOpen(false)}
          selectedProducts={modals.commandeProduits.filter((_, idx) => modals.selectedRows.has(idx))}
          fournisseurs={modals.fournisseurs}
          currentSupplierId={modals.newCommandeFournisseurId}
          produitsList={modals.produitsList}
          commandesEndpoint={modals.commandesEndpoint}
          fournisseursEndpoint={modals.fournisseursEndpoint}
          onTransferSuccess={modals.handleTransferSuccess}
        />
      )}

      {state.isMergeModalOpen && (
        <MergeCommandesModal
          isOpen={state.isMergeModalOpen}
          onClose={() => state.setIsMergeModalOpen(false)}
          selectedOrderIds={modals.selectedOrderIds}
          fournisseurs={modals.fournisseurs}
          commandesEndpoint={modals.commandesEndpoint}
          onMergeSuccess={modals.handleMergeSuccess}
        />
      )}

      {detailProduitId && (
        <ProductDetailsModal
          isOpen={!!detailProduitId}
          onClose={() => setDetailProduitId(null)}
          selectedProduit={detailProduit || null}
          activeTab={detailActiveTab}
          setActiveTab={setDetailActiveTab}
          lots={detailLots}
          monthlyStats={detailStats}
          achats={detailAchats}
          stockHistory={detailHistory}
          loadingHistory={detailHistoryLoading}
          onMovementClick={() => {}}
          onOpenAdjustment={() => {}}
          onOpenEdit={() => {}}
          onDelete={() => {}}
        />
      )}
    </div>
  )
}

import React, { type FormEvent, type RefObject, useState, useCallback } from 'react';
import type { Commande, Fournisseur, ProduitModel, CommandeProduit } from '../../types';
import { useTranslation } from 'react-i18next';
import { toast } from 'react-hot-toast';
import { ArrowLeft, FileDown, FolderOpen, Plus, RotateCcw, Pause, Play, Check, Save } from 'lucide-react';
import CommandeProductTable from './CommandeProductTable';
import { formatCurrency } from '../../utils/formatters';
import ExportCommandeModal from './ExportCommandeModal';
import { Button } from '../shadcn/button';
import { Input } from '../shadcn/input';
import { Select } from '../ui/Select';
import { ProductSearch, type SearchResult } from '../common/ProductSearch';
import { cn } from '../../lib/utils';
import { useDataMatrixScanner } from '../../hooks/useDataMatrixScanner';
import DataMatrixScanBar from './DataMatrixScanBar';
import DuplicateLotModal from './DuplicateLotModal';

interface FieldConfig {
    name: string;
    editable: boolean;
}

interface CommandeFormProps {
    // View State
    viewMode: 'CREATE' | 'EDIT' | 'DETAILS';
    selectedCommande: Commande | null;
    
    // Form Data
    fournisseurs: Fournisseur[];
    newCommandeFournisseurId: string;
    setNewCommandeFournisseurId: (id: string) => void;
    numeroFacture: string;
    setNumeroFacture: (num: string) => void;
    
    // Direct Orders
    commandeType: 'LOC' | 'DIR';
    tauxChange: string;
    setTauxChange: (val: string) => void;
    fraisCoefficient: string;
    setFraisCoefficient: (val: string) => void;
    
    // Actions
    handleBackToList: () => void;
    handleSaveCommande: (e: FormEvent<HTMLFormElement>) => void;
    
    // CSV / Tools
    handleCsvExport: (wholesaler: 'PRINCIPAL' | 'SECONDAIRE_CIP3') => void;
    handleCsvImport: (e: React.ChangeEvent<HTMLInputElement>) => void;
    fileInputRef: RefObject<HTMLInputElement>;
    setIsCreateProduitModalOpen: (isOpen: boolean) => void;
    
    // Search
    searchInputRef: RefObject<HTMLInputElement>;
    fournisseurSelectRef: RefObject<HTMLSelectElement>;
    searchProduitQuery: string;
    setSearchProduitQuery: (q: string) => void;
    handleSearchKeyDown: (e: React.KeyboardEvent) => void;
    filteredProduits: ProduitModel[];
    selectProduct: (p: ProduitModel) => void;
    getItemProps: (index: number) => any;
    
    // Table Props
    commandeProduits: CommandeProduit[];
    produitsList: ProduitModel[];
    selectedRows: Set<number>;
    saving: boolean;
    fieldsConfig: FieldConfig[];
    focusedField: { row: number; field: number } | null;
    
    toggleRowSelection: (index: number) => void;
    toggleAllRows: () => void;
    deleteSelectedRows: () => void;
    openTransferModal: () => void;
    updateCommandeProduitField: (
        index: number, 
        field: 'quantity' | 'unites_gratuites' | 'price' | 'tva' | 'marge' | 'selling_price' | 'lot' | 'date_expiration' | 'prix_euro', 
        value: string | number
    ) => void;
    handleTableFieldKeyDown: (e: React.KeyboardEvent, rowIndex: number, fieldIndex: number) => void;
    handleSellingPriceBlur?: (index: number) => void;
    onRemoveProduct: (index: number) => void;
    onCreateAvoir?: () => void; // Optional handler for creating credit note
    commandeSortBy?: 'chrono' | 'stock' | 'name' | 'qty';
    onSortProduits?: (sortBy: 'chrono' | 'stock' | 'name' | 'qty') => void;
    onViewProductDetails?: (produitId: number) => void;
    // Actions rapides depuis le formulaire
    onCloture?: () => void;
    onMettreEnAttente?: () => void;
    executingAction?: boolean;
    pendingDuplicateProduct?: ProduitModel | null;
    setPendingDuplicateProduct?: (p: ProduitModel | null) => void;
    handleDuplicateAddNewLine?: () => void;
    handleDuplicateIncrementExisting?: (index: number) => void;
    orderTotals?: {
      totalHT: number;
      totalTVA: number;
      totalBuyTVA: number;
      totalTTC: number;
      totalBuyHT: number;
      totalBuyTTC: number;
      totalMarginValue: number;
      globalMargin: string;
      globalMarginPercent: string;
    };
}

export default function CommandeForm({
    viewMode,
    selectedCommande,
    fournisseurs,
    newCommandeFournisseurId,
    setNewCommandeFournisseurId,
    numeroFacture,
    setNumeroFacture,
    commandeType,
    tauxChange,
    setTauxChange,
    fraisCoefficient,
    setFraisCoefficient,
    handleBackToList,
    handleSaveCommande,
    handleCsvExport: _handleCsvExport,
    handleCsvImport,
    fileInputRef,
    setIsCreateProduitModalOpen,
    searchInputRef,
    fournisseurSelectRef: _fournisseurSelectRef,
    searchProduitQuery,
    setSearchProduitQuery,
    handleSearchKeyDown,
    filteredProduits,
    selectProduct,
    getItemProps,
    
    // Table Props
    commandeProduits,
    produitsList,
    selectedRows,
    saving,
    fieldsConfig,
    focusedField,
    toggleRowSelection,
    toggleAllRows,
    deleteSelectedRows,
    openTransferModal,
    updateCommandeProduitField,
    handleSellingPriceBlur,
    handleTableFieldKeyDown,
    onRemoveProduct,
    onCreateAvoir,
    commandeSortBy,
    onSortProduits,
    onViewProductDetails,
    onCloture,
    onMettreEnAttente,
    executingAction,
    orderTotals,
    pendingDuplicateProduct,
    setPendingDuplicateProduct,
    handleDuplicateAddNewLine,
    handleDuplicateIncrementExisting,
}: CommandeFormProps) {
    const { t } = useTranslation(['orders', 'common']);
    const [isExportModalOpen, setIsExportModalOpen] = useState(false);

    const handleNotFound = useCallback(() => {
        searchInputRef.current?.focus();
    }, [searchInputRef]);

    const { processScan, highlightedIndex } = useDataMatrixScanner({
        commandeProduits,
        updateCommandeProduitField: updateCommandeProduitField as (index: number, field: 'lot' | 'date_expiration', value: string) => void,
        onNotFound: handleNotFound,
    });

    return (
        <div className="flex flex-col h-full overflow-hidden bg-slate-50">
          <div className="flex items-center justify-between px-3 py-2 shrink-0 bg-white border-b border-slate-200">
             <div className="flex items-center gap-3">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={handleBackToList}
                  className="size-8 text-slate-400 hover:text-slate-600"
                  title={t('orders:form.back_to_list')}
                >
                  <ArrowLeft className="size-4" />
                </Button>
                <div>
                  <h3 className="font-bold text-sm text-slate-800">
                      {viewMode === 'EDIT' && selectedCommande
                        ? t('orders:form.edit_title', { id: selectedCommande.numero_facture || selectedCommande.id })
                        : t('orders:form.new_title')}
                  </h3>
                  <div className="hidden xl:flex gap-4 text-xs text-slate-400 mt-0.5">
                    <span className="flex items-center gap-1"><kbd className="px-1.5 py-0.5 bg-slate-100 rounded text-[10px] font-sans border border-slate-200">F2</kbd> {t('orders:form.shortcuts.search')}</span>
                    <span className="flex items-center gap-1"><kbd className="px-1.5 py-0.5 bg-slate-100 rounded text-[10px] font-sans border border-slate-200">F4</kbd> {t('orders:form.shortcuts.provider')}</span>
                    <span className="flex items-center gap-1"><kbd className="px-1.5 py-0.5 bg-slate-100 rounded text-[10px] font-sans border border-slate-200">Ctrl+A</kbd> {t('orders:form.shortcuts.select_all')}</span>
                    <span className="flex items-center gap-1"><kbd className="px-1.5 py-0.5 bg-slate-100 rounded text-[10px] font-sans border border-slate-200">Shift+Entr├®e</kbd> D├®tails produit</span>
                  </div>
                </div>
            </div>
          </div>


          <form
            className="flex-1 flex flex-col min-h-0 p-4 overflow-hidden"
            onSubmit={handleSaveCommande}
          >

            {/* Section sup├®rieure compacte ÔÇö tout sur une ligne */}
            <div className="shrink-0 mb-2">
              <div className="bg-white rounded-xl p-2 shadow-sm border border-slate-200">
                <div className="flex flex-wrap items-end gap-2">
                  {/* Fournisseur */}
                  <div className="flex-1 min-w-[150px]">
                    <Select
                      size="sm"
                      value={newCommandeFournisseurId}
                      onChange={(e) => setNewCommandeFournisseurId(e.target.value)}
                      className="bg-slate-100 border-slate-200 text-sm"
                    >
                      <option value="" disabled>{t('orders:form.provider_placeholder')}</option>
                      {fournisseurs.map(f => (
                        <option key={f.id} value={String(f.id)}>{f.name}</option>
                      ))}
                    </Select>
                  </div>

                  {/* Facture */}
                  <div className="w-32">
                    <label className="block text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-1">{t('orders:form.invoice_label')}</label>
                    <Input
                      type="text"
                      placeholder={t('orders:form.invoice_placeholder')}
                      className="w-full h-9 bg-slate-100 border-slate-200 text-sm"
                      value={numeroFacture}
                      onChange={(e) => setNumeroFacture(e.target.value.toUpperCase())}
                    />
                  </div>

                  {/* Param├¿tres Commande Directe */}
                  {commandeType === 'DIR' && (
                    <div className="flex items-center gap-2 border-l border-slate-200 pl-2">
                      <div className="flex flex-col">
                        <span className="text-[9px] font-semibold text-blue-600 uppercase">Taux</span>
                        <Input type="number" step="0.001" className="w-20 h-7 text-sm px-2" value={tauxChange} onChange={(e) => setTauxChange(e.target.value)} />
                      </div>
                      <div className="flex flex-col">
                        <span className="text-[9px] font-semibold text-blue-600 uppercase">Coeff</span>
                        <Input type="number" step="0.01" className="w-14 h-7 text-sm px-2" value={fraisCoefficient} onChange={(e) => setFraisCoefficient(e.target.value)} />
                      </div>
                    </div>
                  )}

                  {/* Recherche produit */}
                  <div className="flex-[2] min-w-[240px]">
                    <ProductSearch
                      searchQuery={searchProduitQuery}
                      setSearchQuery={setSearchProduitQuery}
                      results={filteredProduits as SearchResult[]}
                      loading={false}
                      modes={['products']}
                      compact
                      onSelect={(product) => selectProduct(product as ProduitModel)}
                      searchInputRef={searchInputRef}
                      handleKeyDown={handleSearchKeyDown}
                      getItemProps={getItemProps}
                      placeholder={t('orders:form.search_placeholder')}
                    />
                  </div>

                  {/* Boutons d'action */}
                  <div className="flex gap-1 pb-0.5">
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="size-9 text-slate-500"
                      onClick={() => {
                        if (commandeProduits.length === 0) {
                          toast(t('orders:messages.csv_empty_order'), { icon: 'ÔÜá´©Å' });
                          return;
                        }
                        setIsExportModalOpen(true);
                      }}
                      title={t('orders:form.export_btn')}
                    >
                      <FileDown className="size-4" />
                    </Button>
                    <Button type="button" variant="ghost" size="icon" className="size-9 text-slate-500" onClick={() => fileInputRef.current?.click()} title={t('orders:import_btn')}>
                      <FolderOpen className="size-4" />
                    </Button>
                    <Button type="button" variant="ghost" size="icon" className="size-9 text-slate-500" onClick={() => setIsCreateProduitModalOpen(true)} title={t('orders:new_product_btn')}>
                      <Plus className="size-4" />
                    </Button>

                    <input
                        type="file"
                        accept=".csv"
                        className="hidden"
                        ref={fileInputRef}
                        onChange={handleCsvImport}
                    />

                    {selectedCommande?.status === 'CLOT' && onCreateAvoir && (
                         <Button type="button" variant="ghost" size="icon" className="size-9 text-amber-600 hover:text-amber-700 hover:bg-amber-50" onClick={onCreateAvoir} title={t('orders:messages.create_credit_note_help')}>
                            <RotateCcw className="size-4" />
                         </Button>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {/* Tableau des produits - flex-1 + min-h-0 pour que seul le tableau d├®file */}
            <div className="flex-1 min-h-0 flex flex-col overflow-hidden">
            <CommandeProductTable
                commandeProduits={commandeProduits}
                produitsList={produitsList}
                selectedRows={selectedRows}
                commandeType={commandeType}
                viewMode={viewMode === 'CREATE' ? 'CREATE' : 'EDIT'}
                selectedCommande={selectedCommande}
                saving={saving}
                fieldsConfig={fieldsConfig}
                focusedField={focusedField}
                toggleRowSelection={toggleRowSelection}
                toggleAllRows={toggleAllRows}
                deleteSelectedRows={deleteSelectedRows}
                openTransferModal={openTransferModal}
                updateCommandeProduitField={updateCommandeProduitField}
                handleSellingPriceBlur={handleSellingPriceBlur}
                handleTableFieldKeyDown={handleTableFieldKeyDown}
                onRemoveProduct={onRemoveProduct}
                onViewProductDetails={onViewProductDetails}
                commandeSortBy={commandeSortBy}
                onSortProduits={onSortProduits}
                highlightedIndex={highlightedIndex}
            />
            </div>

            <div className="mt-1.5 flex flex-wrap justify-between items-end gap-2 shrink-0 bg-white p-2 rounded-xl border border-slate-200 shadow-sm">
                <div className="flex flex-wrap gap-2 items-center">
                    {/* PRIX A HT */}
                    <div className="hidden md:flex flex-col items-end">
                        <span className="text-[9px] uppercase font-bold text-slate-400 -mb-1">PRIX A HT</span>
                        <span className="text-sm font-bold text-slate-700">{formatCurrency(orderTotals?.totalBuyHT || 0)}</span>
                    </div>

                    {/* TVA A */}
                    <div className="hidden md:flex flex-col items-end border-l pl-2 border-slate-200">
                        <span className="text-[9px] uppercase font-bold text-slate-400 -mb-1">TVA A</span>
                        <span className="text-sm font-bold text-slate-500">{formatCurrency(orderTotals?.totalBuyTVA || 0)}</span>
                    </div>

                    {/* PRIX A TTC */}
                    <div className="flex flex-col items-end border-l pl-2 border-slate-200">
                        <span className="text-[9px] uppercase font-bold text-slate-400 -mb-1">PRIX A TTC</span>
                        <span className="text-base font-black leading-none text-slate-800">{formatCurrency(orderTotals?.totalBuyTTC || 0)}</span>
                    </div>

                    {/* PRIX V TTC */}
                    <div className="flex flex-col items-end border-l pl-2 border-slate-200">
                        <span className="text-[9px] uppercase font-bold text-emerald-600 -mb-1">PRIX V TTC</span>
                        <span className="text-base font-black leading-none text-emerald-600">{formatCurrency(orderTotals?.totalTTC || 0)}</span>
                    </div>

                    {/* MARGE */}
                    <div className="hidden sm:flex flex-col items-end border-l pl-2 border-slate-200">
                        <span className="text-[9px] uppercase font-bold text-slate-400 -mb-1">MARGE</span>
                        <span className={cn("text-sm font-bold", (Number(orderTotals?.globalMargin || 0)) >= 1.34 ? 'text-emerald-600' : 'text-amber-600')}>{formatCurrency(orderTotals?.totalMarginValue || 0)}</span>
                    </div>

                    {/* COEFF */}
                    <div className="hidden lg:flex flex-col items-end border-l pl-2 border-slate-200">
                        <span className="text-[9px] uppercase font-bold text-slate-400 -mb-1">COEFF</span>
                        <div className="flex items-baseline gap-1">
                            <span className={cn("text-sm font-bold", (Number(orderTotals?.globalMargin || 0)) >= 1.34 ? 'text-emerald-600' : 'text-amber-600')}>x{orderTotals?.globalMargin || '1.00'}</span>
                            <span className={cn("text-[10px] font-semibold", (Number(orderTotals?.globalMargin || 0)) >= 1.34 ? 'text-emerald-500' : 'text-amber-500')}>({orderTotals?.globalMarginPercent || '0.00'}%)</span>
                        </div>
                    </div>
                </div>

                <div className="flex gap-2">
                {/* Mettre en attente - visible uniquement en mode EDIT */}
                {viewMode === 'EDIT' && onMettreEnAttente && selectedCommande?.status !== 'CLOT' && (
                  <Button
                    type="button"
                    variant={selectedCommande?.status === 'ATT' ? 'default' : 'outline'}
                    size="sm"
                    className={cn(
                      "gap-1",
                      selectedCommande?.status === 'ATT' ? 'bg-blue-600 hover:bg-blue-700' : 'border-amber-300 text-amber-700 hover:bg-amber-50'
                    )}
                    onClick={onMettreEnAttente}
                    disabled={saving || executingAction}
                  >
                    {selectedCommande?.status === 'ATT' ? <Play className="size-4" /> : <Pause className="size-4" />}
                    {selectedCommande?.status === 'ATT' ? t('orders:details.resume') : t('orders:details.suspend')}
                  </Button>
                )}
                {/* Cl├┤turer - visible uniquement en mode EDIT */}
                {viewMode === 'EDIT' && onCloture && selectedCommande?.status !== 'CLOT' && (
                  <Button
                    type="button"
                    variant="default"
                    size="sm"
                    className="gap-1 bg-emerald-600 hover:bg-emerald-700"
                    onClick={onCloture}
                    disabled={saving || executingAction}
                  >
                    <Check className="size-4" /> {t('orders:details.close')}
                  </Button>
                )}
                <Button
                  type="submit"
                  size="sm"
                  className="gap-2 bg-emerald-600 hover:bg-emerald-700"
                  disabled={saving || !newCommandeFournisseurId}
                >
                  {!saving && <Save className="size-4" />}
                  {saving ? t('orders:form.saving') : t('orders:form.save_btn')}
                </Button>
              </div>
            </div>
          </form>

          <DataMatrixScanBar
            onScan={processScan}
            searchInputRef={searchInputRef}
            onClearSearchInput={() => setSearchProduitQuery('')}
            active={viewMode === 'CREATE' || viewMode === 'EDIT'}
          />

          <DuplicateLotModal
            isOpen={!!pendingDuplicateProduct}
            product={pendingDuplicateProduct ?? null}
            existingLines={commandeProduits.filter(cp =>
              (typeof cp.produit === 'object' ? cp.produit?.id : cp.produit) === pendingDuplicateProduct?.id
            )}
            onAddNewLine={() => handleDuplicateAddNewLine?.()}
            onIncrementExisting={(i) => handleDuplicateIncrementExisting?.(i)}
            onCancel={() => setPendingDuplicateProduct?.(null)}
          />

          {/* Modal d'export */}
          <ExportCommandeModal
            isOpen={isExportModalOpen}
            onClose={() => setIsExportModalOpen(false)}
            commande={selectedCommande}
          />
        </div>
    );
}

import { useTranslation } from 'react-i18next';
import { formatCurrency } from '../../utils/formatters';
import type { CommandeProduit, ProduitModel } from '../../types';

interface CommandeProductExpandedRowProps {
    p: CommandeProduit;
    colSpan: number;
}

export function CommandeProductExpandedRow({ p, colSpan }: CommandeProductExpandedRowProps) {
    const { t } = useTranslation(['orders', 'common']);

    const pObj = (p.produit && typeof p.produit === 'object') ? p.produit : null;

    const s = {
        dernier_achat: pObj?.dernier_achat || p.produit_dernier_achat,
        dernier_vente: pObj?.dernier_vente || p.produit_dernier_vente,
        rotation_moyenne: pObj?.rotation_moyenne || p.produit_rotation_moyenne,
        stock_minimum: pObj?.stock_minimum || p.produit_stock_minimum || 0,
        stock_maximum: pObj?.stock_maximum || p.produit_stock_maximum || 0,
        stock_alert: pObj?.stock_alert || p.produit_stock_alert || 0,
        cost_price: pObj?.cost_price || p.produit_cost_price || p.price,
        stock: pObj?.stock ?? p.produit_stock ?? 0,
    };

    const formatAchat = s.dernier_achat ? new Date(s.dernier_achat).toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' }) : 'Inconnu';
    const formatVente = s.dernier_vente ? new Date(s.dernier_vente).toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' }) : 'Jamais';

    return (
        <tr className="bg-blue-50/30 border-b border-slate-200">
            <td colSpan={colSpan} className="p-0">
                <div className="p-4 md:px-8 grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-8 text-sm">
                    <div>
                        <div className="text-xs uppercase font-bold text-slate-400 mb-1">{t('orders:product_table.info_row.purchase_history', "Historique d'Achat")}</div>
                        <div className="font-medium text-slate-800">{formatAchat}</div>
                        <div className="text-xs text-slate-500 mt-0.5">{t('orders:product_table.info_row.last_buy_price', "Dernier prix d'achat")}: {s.cost_price ? formatCurrency(Number(s.cost_price)) : '-'}</div>
                    </div>
                    <div>
                        <div className="text-xs uppercase font-bold text-slate-400 mb-1">{t('orders:product_table.info_row.sales_history', "Historique de Vente")}</div>
                        <div className="font-medium text-slate-800">{formatVente}</div>
                        {s.rotation_moyenne && Number(s.rotation_moyenne) > 0 && (
                            <div className="text-xs text-blue-600 mt-0.5 font-medium">
                                {t('orders:product_table.info_row.rotation', 'Rotation')}: {Number(s.rotation_moyenne).toFixed(2)} / mois
                                <span className="text-slate-400 ml-1">({(Number(s.rotation_moyenne) / 30).toFixed(2)} / j)</span>
                            </div>
                        )}
                    </div>
                    <div>
                        <div className="text-xs uppercase font-bold text-slate-400 mb-1">{t('orders:product_table.info_row.stock_alerts', 'Alertes Stock')}</div>
                        <div className="font-medium">
                            Min: <span className="text-amber-600">{s.stock_minimum}</span> / Max: <span className="text-emerald-600">{s.stock_maximum}</span>
                        </div>
                        {s.stock_alert > 0 && (
                            <div className="text-xs text-red-600 mt-0.5">{t('orders:product_table.info_row.alert_threshold', "Seuil d'alerte")}: {s.stock_alert}</div>
                        )}
                    </div>
                    <div>
                        <div className="text-xs uppercase font-bold text-slate-400 mb-1">{t('orders:product_table.info_row.indicators', 'Indicateurs')}</div>
                        <div className="flex flex-col gap-1">
                            {s.stock <= 0 ? (
                                <div className="text-xs text-red-600 font-medium">ÔÜá´©Å {t('orders:product_table.info_row.stock_out', 'Stock en rupture')}</div>
                            ) : s.rotation_moyenne && Number(s.rotation_moyenne) > 0 ? (
                                <div className="text-xs">
                                    {t('orders:product_table.info_row.stock_life', "Dur├®e de vie stock actuel")}: <span className="font-bold">~{Math.round(s.stock / (Number(s.rotation_moyenne) / 30))} j</span>
                                </div>
                            ) : (
                                <div className="text-xs text-slate-400">{t('orders:product_table.info_row.rotation_unknown', 'Rotation inconnue')}</div>
                            )}
                        </div>
                    </div>
                </div>
            </td>
        </tr>
    );
}

import React from 'react';
import { useTranslation } from 'react-i18next';
import { AlertTriangle, Info, Trash2 } from 'lucide-react';
import type { CommandeProduit, ProduitModel } from '../../types';
import { formatCurrency } from '../../utils/formatters';
import { Button } from '../ui/Button';
import { Input } from '../shadcn/input';
import { Checkbox } from '../shadcn/checkbox';
import {
    type FieldConfig,
    type FieldType,
    handleSelectAll,
    normalizeExpiryMMYY,
    finalizeExpiryMMYY,
    resolveProductInfo,
    resolveCip,
    resolveStock,
} from './productTableUtils';

interface CommandeProductRowProps {
    p: CommandeProduit;
    index: number;
    produitsList: ProduitModel[];
    commandeType: 'LOC' | 'DIR';
    fieldsConfig: FieldConfig[];
    focusedField: { row: number; field: number } | null;
    selectedRows: Set<number>;
    highlightedIndex?: number | null;
    isExpanded: boolean;
    marginThreshold: number;
    searchQuery: string;
    toggleRowSelection: (index: number) => void;
    updateCommandeProduitField: (index: number, field: FieldType, value: string | number) => void;
    handleTableFieldKeyDown: (e: React.KeyboardEvent, rowIndex: number, fieldIndex: number) => void;
    handleSellingPriceBlur?: (index: number) => void;
    onToggleExpand: () => void;
    onDeleteProduct: () => void;
}

export function CommandeProductRow({
    p,
    index,
    produitsList,
    commandeType,
    fieldsConfig,
    focusedField,
    selectedRows,
    highlightedIndex = null,
    isExpanded,
    marginThreshold,
    searchQuery,
    toggleRowSelection,
    updateCommandeProduitField,
    handleTableFieldKeyDown,
    handleSellingPriceBlur,
    onToggleExpand,
    onDeleteProduct,
}: CommandeProductRowProps) {
    const { t } = useTranslation(['orders', 'common']);

    const { produitName, isExclusive, supplierName, isDeleted } = resolveProductInfo(p, produitsList, t);

    // Local search filter
    if (searchQuery) {
        const q = searchQuery.toLowerCase();
        const cipVal = resolveCip(p, produitsList);
        const matchesName = produitName.toLowerCase().includes(q);
        const matchesCip = cipVal.toLowerCase().includes(q);
        if (!matchesName && !matchesCip) return null;
    }

    const cip = resolveCip(p, produitsList);
    const currentStock = resolveStock(p);
    const isDirty = false; // placeholder - dirty state handled by parent

    const _price = Number(p.price || 0);
    const _selling = Number(p.selling_price || 0);
    const _tva = Number(p.tva || 0);
    const hasMarginIssue = _price > 0 && _selling > 0 && (_selling / (1 + _tva / 100)) < _price;

    return (
        <React.Fragment key={p.id || `row-${index}`}>
            <tr
                className={`hover:bg-slate-100/50 group border-b border-slate-200 last:border-0 ${selectedRows.has(index) ? 'bg-indigo-50' : ''} ${highlightedIndex === index ? 'ring-2 ring-amber-400 bg-amber-50 animate-pulse' : ''} ${hasMarginIssue ? 'bg-red-50' : ''}`}
            >
                <td className="px-2">
                    <Checkbox
                        checked={selectedRows.has(index)}
                        onCheckedChange={() => toggleRowSelection(index)}
                    />
                </td>

                {/* Product Info */}
                <td className="pl-2 py-0.5 min-w-[220px]">
                    <div className="font-medium text-sm">
                        <div className="flex items-center gap-1">
                            <span className={`${isDeleted ? 'italic text-slate-400' : ''} whitespace-nowrap overflow-hidden text-ellipsis`} title={produitName}>
                                {produitName}
                            </span>
                            {isExclusive && (
                                <div
                                    className="group relative z-50 inline-flex shrink-0"
                                    title={t('orders:product_table.exclusivity_tooltip', { provider: supplierName || t('orders:product_table.specific_provider') })}
                                >
                                    <span className="inline-flex items-center justify-center size-4 rounded text-[8px] font-bold bg-emerald-100 text-emerald-600">
                                        E
                                    </span>
                                </div>
                            )}
                        </div>
                    </div>
                </td>

                {/* CIP Column */}
                <td className="pl-2 py-0.5">
                    <span className="text-sm font-mono font-bold text-slate-600">{cip}</span>
                </td>

                {/* Stock Actuel */}
                <td className="text-center py-0.5 bg-amber-50/20">
                    <span className={`text-xs font-bold px-1 rounded ${currentStock <= 0 ? 'text-red-600 bg-red-50' : 'text-amber-600'}`}>
                        {currentStock}
                    </span>
                </td>

                {/* Quantity (0) */}
                <td className="text-right py-0.5">
                    <Input
                        type="text"
                        data-row={index}
                        data-field="quantity"
                        value={p.quantity}
                        onChange={(e) => updateCommandeProduitField(index, 'quantity', e.target.value)}
                        onKeyDown={(e) => handleTableFieldKeyDown(e, index, 0)}
                        onFocus={handleSelectAll}
                        className={`h-8 px-2 text-sm w-full text-right font-bold focus:bg-white focus:text-indigo-600 ${!fieldsConfig[0].editable ? 'bg-slate-100 cursor-not-allowed' : ''}`}
                        autoFocus={focusedField?.row === index && focusedField?.field === 0}
                        readOnly={!fieldsConfig[0].editable}
                        tabIndex={!fieldsConfig[0].editable ? -1 : 0}
                    />
                </td>

                {/* Unites Gratuites (1) */}
                <td className="text-center py-0.5">
                    <Input
                        type="text"
                        inputMode="numeric"
                        data-row={index}
                        data-field="unites_gratuites"
                        value={p.unites_gratuites || 0}
                        onChange={(e) => {
                            const val = e.target.value;
                            if (/^\d*$/.test(val)) {
                                updateCommandeProduitField(index, 'unites_gratuites', val === '' ? 0 : parseInt(val));
                            }
                        }}
