import { useEffect, useRef, useState, useCallback } from 'react';
import { ScanLine, X, CheckCircle2, AlertTriangle, XCircle } from 'lucide-react';
import type { ScanResult } from '../../hooks/useDataMatrixScanner';

interface DataMatrixScanBarProps {
    onScan: (raw: string) => ScanResult;
    searchInputRef?: React.RefObject<HTMLInputElement>;
    onClearSearchInput?: () => void;
    active?: boolean;
}

type FeedbackState =
    | { type: 'idle' }
    | { type: 'success'; message: string }
    | { type: 'warning'; message: string }
    | { type: 'error'; message: string };

const SCAN_TIMEOUT_MS = 80; // ms : d├®lai max entre caract├¿res douchette
const MIN_SCAN_LENGTH = 18; // longueur minimale pour consid├®rer comme un scan Data Matrix

const feedbackColors: Record<FeedbackState['type'], string> = {
    idle: 'bg-slate-800/90 border-slate-600',
    success: 'bg-emerald-800/90 border-emerald-500',
    warning: 'bg-amber-800/90 border-amber-500',
    error: 'bg-red-800/90 border-red-500',
};

const feedbackIcons = {
    idle: <ScanLine className="size-4 text-slate-300 animate-pulse" />,
    success: <CheckCircle2 className="size-4 text-emerald-300" />,
    warning: <AlertTriangle className="size-4 text-amber-300" />,
    error: <XCircle className="size-4 text-red-300" />,
};

export default function DataMatrixScanBar({
    onScan,
    searchInputRef,
    onClearSearchInput,
    active = true,
}: DataMatrixScanBarProps) {
    const [feedback, setFeedback] = useState<FeedbackState>({ type: 'idle' });
    const [isVisible, setIsVisible] = useState(true);
    const bufferRef = useRef('');
    const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const feedbackTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const showFeedback = useCallback((state: FeedbackState, autoClearMs = 4000) => {
        setFeedback(state);
        if (feedbackTimerRef.current) clearTimeout(feedbackTimerRef.current);
        if (state.type !== 'idle') {
            feedbackTimerRef.current = setTimeout(() => setFeedback({ type: 'idle' }), autoClearMs);
        }
    }, []);

    const handleBuffer = useCallback(() => {
        const raw = bufferRef.current.trim();
        bufferRef.current = '';

        if (!raw || raw.length < 6) return; // trop court pour ├¬tre un code valide

        const result = onScan(raw);

        switch (result.status) {
            case 'filled':
                showFeedback({
                    type: 'success',
                    message: `Ô£ô ${result.cip} ÔåÆ Lot : ${result.lot || 'ÔÇö'}  Exp : ${result.date || 'ÔÇö'}`,
                });
                break;
            case 'already_filled':
                showFeedback({
                    type: 'warning',
                    message: `Ligne d├®j├á remplie ÔÇö CIP ${result.cip} (ligne surlign├®e)`,
                }, 5000);
                break;
            case 'not_found':
                showFeedback({
                    type: 'error',
                    message: `CIP ${result.cip ?? 'inconnu'} non trouv├® dans la commande`,
                });
                // Rediriger vers la recherche manuelle
                setTimeout(() => searchInputRef?.current?.focus(), 50);
                break;
            case 'parse_error':
                showFeedback({
                    type: 'error',
                    message: `Code non reconnu`,
                });
                break;
        }
    }, [onScan, showFeedback, searchInputRef]);

    useEffect(() => {
        if (!active) return;

        const handleKeyDown = (e: KeyboardEvent) => {
            const target = e.target as HTMLElement;
            const tag = target.tagName;
            const isInInput = tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || target.isContentEditable;

            // La douchette envoie Enter ├á la fin
            if (e.key === 'Enter') {
                if (timerRef.current) {
                    clearTimeout(timerRef.current);
                    timerRef.current = null;
                }
                if (bufferRef.current.length >= MIN_SCAN_LENGTH) {
                    e.preventDefault();
                    e.stopPropagation();
                    // Nettoyer l'input si les chars du scan y ont quand m├¬me atterri
                    if (isInInput) {
                        onClearSearchInput?.();
                    }
                    handleBuffer();
                } else {
                    bufferRef.current = '';
                }
                return;
            }

            // Filtrer les touches de contr├┤le (mais garder les chars imprimables + GS)
            if (e.key.length === 1 || e.key === 'GS' || e.charCode === 29) {
                bufferRef.current += e.key === 'GS' ? '\x1d' : e.key;

                if (timerRef.current) clearTimeout(timerRef.current);
                timerRef.current = setTimeout(() => {
                    // Timeout : si assez long c'est un scan sans Enter final
                    if (bufferRef.current.length >= MIN_SCAN_LENGTH) {
                        if (isInInput) {
                            onClearSearchInput?.();
                        }
                        handleBuffer();
                    } else {
                        bufferRef.current = '';
                    }
                }, SCAN_TIMEOUT_MS);
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            if (timerRef.current) clearTimeout(timerRef.current);
        };
    }, [active, handleBuffer]);

    if (!isVisible) {
        return (
            <button
                onClick={() => setIsVisible(true)}
                className="fixed top-2 right-2 z-50 bg-indigo-600 text-white rounded-full p-1.5 shadow-lg hover:bg-indigo-700 transition-colors"
                title="Afficher la barre de scan Data Matrix"
            >
                <ScanLine className="size-4" />
            </button>
        );
    }

    return (
        <div
            className={`fixed top-2 left-1/2 -translate-x-1/2 z-50 flex items-center gap-2 px-3 py-1.5 rounded-full border shadow-xl backdrop-blur-sm transition-all duration-300 ${feedbackColors[feedback.type]}`}
        >
            {feedbackIcons[feedback.type]}
            <span className="text-xs font-medium text-white max-w-[480px] truncate">
                {feedback.type === 'idle'
                    ? 'Scan Data Matrix actif ÔÇö pointez la douchette sur un code'
                    : feedback.message}
            </span>
            <button
                onClick={() => setIsVisible(false)}
                className="ml-1 text-white/60 hover:text-white transition-colors"
                title="Masquer"
            >
                <X className="size-3" />
            </button>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'react-hot-toast';
import {
  Download,
  FileText,
  AlertTriangle,
  CheckCircle,
  Loader2,
  FileSpreadsheet,
  AlertCircle,
} from 'lucide-react';
import api from '../../services/api';
import type { Commande } from '../../types';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '../shadcn/dialog';
import { Button } from '../shadcn/button';
import { Badge } from '../shadcn/badge';
import { cn } from '../../lib/utils';

interface ExportCommandeModalProps {
  isOpen: boolean;
  onClose: () => void;
  commande: Commande | null;
}

interface ExportPreview {
  commande_id: number;
  fournisseur: string;
  cip_field: string;
  cip_label: string;
  stats: {
    total_produits: number;
    avec_cip: number;
    sans_cip: number;
  };
  produits_avec_cip: Array<{
    id: number;
    cip: string;
    libelle: string;
    quantite: number;
    unites_gratuites: number;
  }>;
  produits_sans_cip: Array<{
    id: number;
    libelle: string;
    quantite: number;
    unites_gratuites: number;
  }>;
}

export const ExportCommandeModal: React.FC<ExportCommandeModalProps> = ({
  isOpen,
  onClose,
  commande,
}) => {
  const { t } = useTranslation('export');
  const [selectedCip, setSelectedCip] = useState<'cip1' | 'cip3'>('cip1');
  const [preview, setPreview] = useState<ExportPreview | null>(null);
  const [loading, setLoading] = useState(false);
  const [exporting, setExporting] = useState(false);

  useEffect(() => {
    if (isOpen && commande) {
      loadPreview();
    }
  }, [isOpen, commande, selectedCip]);

  const loadPreview = async () => {
    if (!commande) return;

    try {
      setLoading(true);
      const response = await api.get(
        `commandes/${commande.id}/export-preview/?cip_field=${selectedCip}`
      );
      setPreview(response.data);
    } catch (err: unknown) {
      toast.error(err.response?.data?.error || t('errors.load_failed'));
    } finally {
      setLoading(false);
    }
  };

  const downloadBlob = (blob: Blob, fallbackFilename: string, contentDisposition?: string) => {
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    const filenameMatch = contentDisposition?.match(/filename="(.+)"/);
    link.setAttribute('download', filenameMatch ? filenameMatch[1] : fallbackFilename);
    document.body.appendChild(link);
    link.click();
    link.parentNode?.removeChild(link);
    window.URL.revokeObjectURL(url);
  };

  const handleExportCSV = async () => {
    if (!commande) return;

    try {
      setExporting(true);
      const response = await api.get(
        `commandes/${commande.id}/export/?cip_field=${selectedCip}&export_format=csv`,
        { responseType: 'blob' }
      );
      downloadBlob(response.data, `commande_${commande.id}.csv`, response.headers['content-disposition']);
      toast.success(t('messages.export_success'));
    } catch {
      toast.error(t('errors.export_failed'));
    } finally {
      setExporting(false);
    }
  };

  const handleExportSansCipTxt = async () => {
    if (!commande || !preview?.produits_sans_cip.length) return;

    try {
      setExporting(true);
      const response = await api.get(
        `commandes/${commande.id}/export/?cip_field=${selectedCip}&export_format=txt`,
        { responseType: 'blob' }
      );
      downloadBlob(response.data, `commande_${commande.id}_sans_cip.txt`, response.headers['content-disposition']);
      toast.success(t('messages.txt_export_success'));
    } catch {
      toast.error(t('errors.export_failed'));
    } finally {
      setExporting(false);
    }
  };

  if (!commande) return null;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-2xl p-0 gap-0 overflow-hidden">
        <DialogHeader className="px-6 pt-6 pb-4 border-b border-slate-100">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-50 rounded-lg">
              <FileSpreadsheet className="size-5 text-emerald-600" />
            </div>
            <div>
              <DialogTitle>{t('title')}</DialogTitle>
              <DialogDescription>{commande.fournisseur_nom || t('subtitle')}</DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <div className="px-6 py-5 space-y-5 max-h-[60vh] overflow-y-auto">
          {/* S├®lection du CIP */}
          <div className="bg-slate-50 rounded-xl p-3 border border-slate-200">
            <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">
              {t('select_cip')}
            </div>
            <div className="flex gap-2">
              {(['cip1', 'cip3'] as const).map((cip) => (
                <button
                  key={cip}
                  type="button"
                  onClick={() => setSelectedCip(cip)}
                  className={cn(
                    "flex-1 flex flex-col items-center gap-0.5 rounded-lg border px-3 py-2 text-sm transition-all",
                    selectedCip === cip
                      ? "bg-emerald-600 text-white border-emerald-600 shadow-sm"
                      : "bg-white border-slate-200 text-slate-700 hover:border-emerald-300 hover:bg-emerald-50"
                  )}
                >
                  <span className="font-semibold">{cip.toUpperCase()}</span>
                  <span className={cn("text-[10px]", selectedCip === cip ? "text-emerald-100" : "text-slate-500")}>
                    {t(`${cip}_desc`)}
                  </span>
                </button>
              ))}
            </div>
          </div>

          {/* Stats */}
          {loading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="size-8 animate-spin text-emerald-600" />
            </div>
          ) : preview ? (
