export default ExportCommandeModal;

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import api from '../../services/api';
import { toast } from 'react-hot-toast';
import type { Commande, Fournisseur } from '../../types';
import { formatCurrency } from '../../utils/formatters';

interface MergeCommandesModalProps {
    isOpen: boolean;
    onClose: () => void;
    selectedOrderIds: Set<number>;
    fournisseurs: Fournisseur[];
    commandesEndpoint: string;
    onMergeSuccess: (mergedCount: number, targetOrderId: number) => void;
}

export default function MergeCommandesModal({
    isOpen,
    onClose,
    selectedOrderIds,
    fournisseurs,
    commandesEndpoint,
    onMergeSuccess
}: MergeCommandesModalProps) {
    const { t } = useTranslation(['orders', 'common']);
    const [mergeTargetOrderId, setMergeTargetOrderId] = useState<number | null>(null);
    const [mergeOrdersDetails, setMergeOrdersDetails] = useState<Commande[]>([]);
    const [loadingMergeDetails, setLoadingMergeDetails] = useState(false);

    // Charger les d├®tails des commandes ├á l'ouverture
    useEffect(() => {
        if (isOpen && selectedOrderIds.size > 0) {
            fetchMergeDetails();
            setMergeTargetOrderId(null);
        }
    }, [isOpen, selectedOrderIds]);

    const fetchMergeDetails = async () => {
        setLoadingMergeDetails(true);
        try {
            // Charger les d├®tails complets de chaque commande s├®lectionn├®e
            const orderIds = Array.from(selectedOrderIds);
            const detailsPromises = orderIds.map(id => 
                api.get<Commande>(`${commandesEndpoint}${id}/`)
            );
            const responses = await Promise.all(detailsPromises);
            setMergeOrdersDetails(responses.map(r => r.data));
        } catch (err) {
            console.error('Erreur chargement d├®tails commandes:', err);
            toast.error(t('orders:merge_modal.load_error'));
            onClose(); // Fermer si erreur critique
        } finally {
            setLoadingMergeDetails(false);
        }
    };

    const handleMergeOrders = async () => {
        if (!mergeTargetOrderId) {
            toast.error(t('orders:merge_modal.select_main_error'));
            return;
        }

        const orderIdsToMerge = Array.from(selectedOrderIds).filter(id => id !== mergeTargetOrderId);
        if (orderIdsToMerge.length === 0) {
            toast.error(t('orders:merge_modal.no_orders_error'));
            return;
        }

        try {
            // Utiliser l'action backend 'merge' pour chaque commande source
            await Promise.all(orderIdsToMerge.map(async (sourceOrderId) => {
                await api.post(`${commandesEndpoint}${mergeTargetOrderId}/merge/`, {
                    source_commande_id: sourceOrderId
                });
            }));

            // Notifier succ├¿s
            onMergeSuccess(orderIdsToMerge.length, mergeTargetOrderId);
            onClose();

        } catch (err: unknown) {
            console.error('Erreur lors de la fusion:', err);
            const msg = err.response?.data?.error || t('orders:merge_modal.merge_error');
            toast.error(msg);
        }
    };

    if (!isOpen) return null;

    const totalProduits = mergeOrdersDetails.reduce((sum, c) => sum + (c.produits?.length || 0), 0);
    const uniqueSuppliers = [...new Set(mergeOrdersDetails.map(c => c.fournisseur))];

    return (
        <div className="modal modal-open">
            <div className="modal-box max-w-2xl">
                {loadingMergeDetails ? (
                    <div className="flex flex-col items-center justify-center py-12">
                        <span className="inline-block size-8 border-2 border-base-300 border-t-indigo-600 rounded-full animate-spin mb-4"></span>
                        <p>{t('orders:merge_modal.loading')}</p>
                    </div>
                ) : (
                    <>
                        <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
                            {t('orders:merge_modal.title', { count: selectedOrderIds.size })}
                        </h3>

                        <p className="text-sm text-base-content/60 mb-4">
                           {t('orders:merge_modal.description')}
                        </p>

                        {/* S├®lection du fournisseur final */}
                        <div className=" mb-4">
                            <label className="label">
                                <span className="text-sm font-medium text-base-content font-semibold">{t('orders:merge_modal.supplier_label')}</span>
                            </label>
                            <select
                                className="select-ref select-bordered w-full"
                                value={mergeTargetOrderId ?? ''}
                                onChange={(e) => setMergeTargetOrderId(e.target.value ? parseInt(e.target.value) : null)}
                            >
                                <option value="">{t('orders:merge_modal.select_main')}</option>
                                {mergeOrdersDetails.map(order => (
                                    <option key={order.id} value={order.id}>
                                        #{order.id} - {fournisseurs.find(f => f.id === order.fournisseur)?.name} 
                                        ({order.produits?.length || 0} {t('orders:merge_modal.products_badge', { count: order.produits?.length || 0 }).split(' ').slice(1).join(' ')}, {formatCurrency(Number(order.total))})
                                    </option>
                                ))}
                            </select>
                            {uniqueSuppliers.length > 1 && (
                                <p className="text-xs text-warning mt-1">
                                    {t('orders:merge_modal.multi_supplier_warning', { count: uniqueSuppliers.length })}
                                </p>
                            )}
                        </div>

                        {/* Liste des commandes ├á fusionner */}
                        <div className="bg-base-200 rounded-lg p-4 mb-4 max-h-60 overflow-y-auto">
                            <h4 className="font-semibold text-sm mb-2">{t('orders:merge_modal.orders_to_merge')}</h4>
                            <div className="space-y-2">
                                {mergeOrdersDetails.map(order => {
                                    const isTarget = order.id === mergeTargetOrderId;
                                    return (
                                        <div 
                                            key={order.id} 
                                            className={`flex justify-between items-center text-sm p-2 rounded ${isTarget ? 'bg-primary/20 border border-indigo-500' : 'bg-base-100'}`}
                                        >
                                            <div className="flex items-center gap-2">
                                                {isTarget && <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-bold bg-primary/20 text-primary">{t('orders:merge_modal.main_badge')}</span>}
                                                <span className="font-medium">{t('orders:merge_modal.order_label', { id: order.id })}</span>
                                                <span className="text-base-content/50">
                                                    ({fournisseurs.find(f => f.id === order.fournisseur)?.name})
                                                </span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-bold bg-base-200 text-base-content/60">{t('orders:merge_modal.products_badge', { count: order.produits?.length || 0 })}</span>
                                                <span className="font-bold">{formatCurrency(Number(order.total))}</span>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>

                        {/* R├®sum├® */}
                        <div className="bg-base-100 border border-base-300 rounded-lg p-4 mb-4">
                            <div className="grid grid-cols-2 gap-4 text-center">
                                <div>
                                    <div className="text-xs text-base-content/50 uppercase">{t('orders:merge_modal.total_products')}</div>
                                    <div className="font-bold text-lg">{totalProduits}</div>
                                </div>
                                <div>
                                    <div className="text-xs text-base-content/50 uppercase">{t('orders:merge_modal.total_amount')}</div>
                                    <div className="font-bold text-lg text-primary">
                                        {formatCurrency(mergeOrdersDetails.reduce((sum, c) => sum + parseFloat(c.total || '0'), 0))}
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Actions */}
                        <div className="flex justify-end gap-3 pt-4">
                            <button 
                                type="button" 
                                className="btn-ref btn-ghost" 
                                onClick={onClose}
                            >
                                {t('orders:merge_modal.cancel')}
                            </button>
                            <button 
                                type="button" 
                                className="inline-flex items-center justify-center gap-2 px-4 py-2 bg-gray-900 text-white text-sm font-bold rounded-xl hover:bg-gray-800 transition-colors"
                                onClick={handleMergeOrders}
                                disabled={!mergeTargetOrderId}
                            >
                                {t('orders:merge_modal.merge_btn')}
                            </button>
                        </div>
                    </>
                )}
            </div>
            <div className="modal-backdrop" onClick={onClose}></div>
        </div>
    );
}

import { useState, useEffect } from 'react'
import api from '../../services/api'
import { toast } from 'react-hot-toast'
import { formatPrice } from '../../utils/formatters'
import procurementService from '../../services/procurementService'
import fournisseurService from '../../services/fournisseurService'
import PremiumModal from '../common/PremiumModal'
import { useTranslation } from 'react-i18next'
import { 
    Clock, 
    Settings2,
    Check,
    Search,
    ShoppingCart,
    ChevronLeft,
    Calendar,
    Zap,
    ShieldCheck,
    MessageSquare,
    Info,
    Bell,
    Loader2
} from 'lucide-react'
import type { Fournisseur, ProduitModel, CommandeProduit, OrderSchedule } from '../../types'
import { Button } from '../ui/Button'
import { Input } from '../shadcn/input'
import { Checkbox } from '../shadcn/checkbox'
import { Select } from '../ui/Select'

interface OrderSchedulingModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (schedule: OrderSchedule) => void;
    onApplySuggestions: (products: CommandeProduit[], fournisseurId: string) => void;
    fournisseurs: Fournisseur[];
    produitsList: ProduitModel[];
    initialSchedule?: Partial<OrderSchedule>;
}

export default function OrderSchedulingModal({ 
    isOpen, 
    onClose, 
    onSave,
    onApplySuggestions,
    fournisseurs,
    produitsList,
    initialSchedule 
}: OrderSchedulingModalProps) {
    const { t } = useTranslation('orders');

    const [activeTab, setActiveTab] = useState<'plan' | 'gen'>('plan');
    // --- Schedule State ---
    const defaultSchedule: OrderSchedule = {
        fournisseur: 0,
        active_days: [1, 2, 3, 4, 5],
        active_month_days: [],
        frequency_weeks: 1,
        start_date: new Date().toISOString().split('T')[0],
        time: '12:10',
        has_alert_sound: true,
        has_teletransmission: false,
        teletransmission_mode: 'IMMEDIATE',
        needs_financial_reception: true,
        print_copies: 1,
        delivery_time: '',
        auto_reception_delay: 0,
        notify_sms: false,
        notify_whatsapp: false,
        special_code: '',
        comment: '',
        is_active: true,
        min_amount: 0,
        min_items: 0,
        condition_logic: 'AND',
        execution_mode: 'OPTIMISE',
        analysis_period_days: 30,
        delai_couverture_jours: 30
    };

    const [schedule, setSchedule] = useState<OrderSchedule>({
        ...defaultSchedule,
        ...initialSchedule
    });

    useEffect(() => {
        if (isOpen) {
            setSchedule({
                ...defaultSchedule,
                ...initialSchedule
            });
        }
    }, [initialSchedule, isOpen]);

    // --- Param├¿tres logistiques du fournisseur (├®ditables dans le modal) ---
    const [logistics, setLogistics] = useState({ delai_livraison: 7, marge_retard: 2 });

    useEffect(() => {
        if (schedule.fournisseur > 0) {
            const f = fournisseurs.find(fx => fx.id === schedule.fournisseur);
            if (f) {
                setLogistics({
                    delai_livraison: f.delai_livraison_jours || 7,
                    marge_retard: f.marge_retard_jours || 2,
                });
            }
        }
    }, [schedule.fournisseur, fournisseurs]);

    // --- Generation Logic State (Manual) ---
    const [suggestionParams, setSuggestionParams] = useState({
        periode: 30,
        mode: 'optimise',
        budgetMax: '',
        dateDebut: new Date().toISOString().split('T')[0],
        dateFin: new Date().toISOString().split('T')[0],
    });
    const [suggestions, setSuggestions] = useState<unknown[]>([]);
    const [totalHt, setTotalHt] = useState<number>(0);
    const [loadingSuggestions, setLoadingSuggestions] = useState(false);
    const [saving, setSaving] = useState(false);
    const [stepGen, setStepGen] = useState<1 | 2>(1);
    const [selectedSuggestions, setSelectedSuggestions] = useState<Set<number>>(new Set());

    const handleSave = async () => {
        // Validation fournisseur
        if (!schedule.fournisseur || schedule.fournisseur === 0) {
            toast.error(t('scheduling.err_select_supplier'));
            return;
        }
        
        // Validation fr├®quence
        if (!schedule.frequency_weeks || schedule.frequency_weeks < 1) {
            toast.error(t('scheduling.err_frequency_min'));
            return;
        }
        
        // Validation jours actifs
        if (!schedule.active_days || schedule.active_days.length === 0) {
            toast.error(t('scheduling.err_select_day'));
            return;
        }
        
        // Validation format heure HH:MM ou HH:MM:SS
        const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$/;
        if (!schedule.time || !timeRegex.test(schedule.time)) {
            toast.error(t('scheduling.err_time_format'));
            return;
        }
        // Normaliser en HH:MM (supprimer les secondes si pr├®sentes)
        const normalizedTime = schedule.time.split(':').slice(0, 2).join(':');
        
        // Validation date de d├®but >= aujourd'hui
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const startDate = new Date(schedule.start_date);
        if (startDate < today) {
            toast.error(t('scheduling.err_date_past'));
            return;
        }
        
        // Validation logique conditions si les deux sont d├®finis
        if (schedule.min_amount > 0 && schedule.min_items > 0 && !schedule.condition_logic) {
            toast.error(t('scheduling.err_logic_and_or'));
            return;
        }
        
        try {
            setSaving(true);
            // Nettoyer les donn├®es pour l'API
            const cleanedSchedule = {
                ...schedule,
                time: normalizedTime, // HH:MM normalis├®
                delivery_time: schedule.delivery_time || null,
                special_code: schedule.special_code?.trim() || '',
                comment: schedule.comment?.trim() || '',
                // S'assurer que les valeurs num├®riques sont valides
                frequency_weeks: Math.max(1, parseInt(String(schedule.frequency_weeks)) || 1),
                analysis_period_days: Math.max(1, parseInt(String(schedule.analysis_period_days)) || 30),
                delai_couverture_jours: Math.max(1, parseInt(String(schedule.delai_couverture_jours)) || 30),
                min_amount: Math.max(0, parseInt(String(schedule.min_amount)) || 0),
                min_items: Math.max(0, parseInt(String(schedule.min_items)) || 0),
            };

            if (schedule.id) {
                await procurementService.updateSchedule(schedule.id, cleanedSchedule);
                toast.success(t('scheduling.success_updated'));
            } else {
                await procurementService.createSchedule(cleanedSchedule);
                toast.success(t('scheduling.success_created'));
            }

            // Mettre ├á jour les param├¿tres logistiques du fournisseur
            if (schedule.fournisseur > 0) {
                try {
                    await fournisseurService.update(schedule.fournisseur, {
                        delai_livraison_jours: logistics.delai_livraison,
                        marge_retard_jours: logistics.marge_retard,
                    });
                } catch (err) {
                    // Ne pas bloquer la sauvegarde du schedule si la mise ├á jour du fournisseur ├®choue
                    console.warn('Erreur mise ├á jour param├¿tres logistiques:', err);
                }
            }

            onSave(cleanedSchedule);
        } catch (err: unknown) {
            // Gestion d'erreur d├®taill├®e
            const errorMsg = err.response?.data?.fournisseur?.[0] 
                || err.response?.data?.active_days?.[0]
                || err.response?.data?.time?.[0]
                || err.response?.data?.detail
                || err.response?.data?.error
                || err.response?.data?.message
                || t('scheduling.err_save');
            toast.error(errorMsg);
        } finally {
            setSaving(false);
        }
    };

    const days = [
        { label: 'L', full: t('scheduling.days.monday'), value: 1 },
        { label: 'M', full: t('scheduling.days.tuesday'), value: 2 },
        { label: 'M', full: t('scheduling.days.wednesday'), value: 3 },
        { label: 'J', full: t('scheduling.days.thursday'), value: 4 },
        { label: 'V', full: t('scheduling.days.friday'), value: 5 },
        { label: 'S', full: t('scheduling.days.saturday'), value: 6 },
        { label: 'D', full: t('scheduling.days.sunday'), value: 0 },
    ];

    const toggleDay = (val: number) => {
        setSchedule(prev => ({
            ...prev,
            active_days: prev.active_days.includes(val)
                ? prev.active_days.filter(d => d !== val)
                : [...prev.active_days, val]
        }));
    };

    const toggleMonthDay = (val: number) => {
        setSchedule(prev => ({
            ...prev,
            active_month_days: prev.active_month_days.includes(val)
                ? prev.active_month_days.filter(d => d !== val)
                : [...prev.active_month_days, val]
        }));
    };

    async function fetchSuggestions() {
        // Validation fournisseur
        if (!schedule.fournisseur || schedule.fournisseur === 0) {
            toast.error(t('scheduling.err_select_supplier_first'));
            return;
        }
        
        // Validation budget num├®rique
        if (suggestionParams.budgetMax && isNaN(Number(suggestionParams.budgetMax))) {
            toast.error(t('scheduling.err_budget_number'));
            return;
        }
        
        // Validation dates pour mode ventes horaire
        if (suggestionParams.mode === 'ventes_horaire') {
            if (!suggestionParams.dateDebut || !suggestionParams.dateFin) {
                toast.error(t('scheduling.err_dates_required'));
                return;
            }
            if (new Date(suggestionParams.dateDebut) > new Date(suggestionParams.dateFin)) {
                toast.error(t('scheduling.err_date_order'));
                return;
            }
        }
        
        setLoadingSuggestions(true);
        try {
            const payload: unknown = {
                mode: suggestionParams.mode,
                fournisseur_id: schedule.fournisseur,
            };

            if (suggestionParams.mode === 'ventes_horaire') {
                payload.date_debut = suggestionParams.dateDebut;
                payload.date_fin = suggestionParams.dateFin;
            } else {
                payload.periode = Math.max(1, Number(suggestionParams.periode) || 30);
                const budgetVal = suggestionParams.budgetMax ? Number(suggestionParams.budgetMax) : null;
                payload.budget_max = budgetVal && !isNaN(budgetVal) && budgetVal > 0 ? budgetVal : null;
            }
            
            const response = await api.post('generer-suggestions/', payload);
            setSuggestions(response.data.suggestions || []);
            setTotalHt(response.data.total_ht || 0);
            
            const allIndices = new Set(response.data.suggestions.map((_: unknown, i: number) => i));
            setSelectedSuggestions(allIndices as Set<number>);
            setStepGen(2);
        } catch (err: unknown) {
            const errorMsg = err.response?.data?.error 
                || err.response?.data?.detail 
                || err.response?.data?.message 
                || t('scheduling.err_suggestions');
            toast.error(errorMsg);
        } finally {
            setLoadingSuggestions(false);
        }
    }

    function handleApply() {
        const selectedItems = suggestions.filter((_, i) => selectedSuggestions.has(i));
        if (selectedItems.length === 0) {
            toast(t('scheduling.no_selection'), { icon: 'ÔÜá´©Å' });
            return;
        }

        const newLines: CommandeProduit[] = selectedItems.map((item: unknown, index) => {
             const realProduct = produitsList.find(p => p.id === item.produit_id);
             let productStub: ProduitModel;
             if (realProduct) productStub = realProduct;
             else {
                 productStub = {
                    id: item.produit_id,
                    name: item.produit_nom,
                    cip1: item.produit_ref,
                    stock: item.stock_actuel,
                    cost_price: String(item.prix_achat),
                    selling_price: String(item.prix_vente || item.prix_achat * 1.3),
                    tva: item.tva || '0',
                    taux_marge: item.taux_marge || '1.3'
                } as unknown;
             }

            return {
                id: Date.now() + index,
                produit: productStub,
                quantity: item.quantite_suggeree,
                price: String(item.prix_achat || productStub.cost_price || 0),
                tva: item.tva || productStub.tva || '0',
                marge: item.taux_marge || productStub.taux_marge || '1.3',
                selling_price: String(item.prix_vente || productStub.selling_price || 0),
            } as unknown;
        });

        onApplySuggestions(newLines, String(schedule.fournisseur));
    }

