                    </label>
                    <select 
                      className="w-full rounded-xl border border-slate-200 bg-white h-10 px-3 text-sm font-bold focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all appearance-none"
