                        className="inline-flex items-center gap-1.5 px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold hover:bg-blue-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                      >
                        <Copy className="size-4" />
                        {t('form.copy_btn', 'Copier')}
                      </button>
                    </div>
                    <p className="text-xs text-slate-400 italic">
                      {t('form.copy_help', 'Copie tous les droits, menus autoris├®s et permissions sp├®ciales de l\'utilisateur s├®lectionn├®.')}
                    </p>
                  </div>
                )}
              </div>


              <div className="space-y-4">
                <div className="flex items-center gap-2 border-l-2 border-purple-500 pl-3 bg-purple-50 py-1 rounded-r-lg">
                  <h4 className="font-bold text-xs uppercase tracking-widest text-purple-600">{t('modal.authorized_menus')}</h4>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {MENU_HIERARCHY.map(menu => {
                      const allowedSet = new Set(formData.allowed_menus);
                      const parentLabel = t(menu.labelKey);
                      const isParentChecked = allowedSet.has(menu.key);
                      const indeterminate = !isParentChecked && menu.submenus?.some(sub => allowedSet.has(sub.key));

                      return (
                        <div key={menu.key} className={`bg-slate-50 rounded-xl border border-slate-200 overflow-hidden ${menu.submenus && menu.submenus.length > 0 ? 'flex flex-col h-full' : ''}`}>
                           <div className="bg-slate-100 p-3 flex-none border-b border-slate-200">
                             <label className="flex items-center cursor-pointer gap-3">
                               <input 
                                 type="checkbox" 
                                 className="size-4 rounded border-slate-300 accent-blue-600 shrink-0 cursor-pointer"
                                 checked={isParentChecked || indeterminate}
                                 onChange={() => handleMenuToggle(menu.key, menu.submenus)}
                                 disabled={formData.is_superuser}
                               />
                               <span className={`font-bold text-sm select-none ${formData.is_superuser ? 'text-slate-400' : 'text-slate-700'}`}>{parentLabel}</span>
                             </label>
                           </div>
                           
                           {menu.submenus && menu.submenus.length > 0 && (
                               <div className="p-3 grid grid-cols-1 gap-1.5 flex-1 bg-white">
                                  {menu.submenus.map(sub => {
                                     const subLabel = t(sub.labelKey);
                                     return (
                                        <div key={sub.key} className="flex items-start transition-all py-0.5 group">
                                          <Checkbox 
                                            size="xs"
                                            color="primary"
                                            checked={allowedSet.has(sub.key) || allowedSet.has(menu.key)}
                                            onChange={() => handleSubMenuToggle(sub.key, menu.key, menu.submenus!.length)}
                                            disabled={formData.is_superuser}
                                            label={subLabel}
                                          />
                                        </div>
                                     );
                                  })}
                               </div>
                           )}
                        </div>
                   )})}
                </div>
                {formData.is_superuser && (
                  <div className="p-3 rounded-xl bg-blue-50 border border-blue-200 text-blue-700 text-sm italic flex items-center gap-2">
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" className="stroke-current shrink-0 size-4"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                    <span>{t('modal.admin_note')}</span>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-4">
                    <div className="flex items-center gap-2 border-l-2 border-emerald-500 pl-3 bg-emerald-50 py-1 rounded-r-lg">
                      <h4 className="font-bold text-xs uppercase tracking-widest text-emerald-600">{t('modal.special_permissions')}</h4>
                    </div>
                    
                    <div className="grid grid-cols-1 gap-3 bg-slate-50 p-4 rounded-xl border border-slate-200">
                      <label className="flex cursor-pointer justify-start gap-4 p-2 bg-white rounded-lg border border-slate-200 hover:border-emerald-300 transition-all shadow-sm group">
                        <input 
                          type="checkbox" 
                          className="size-4 rounded border-slate-300 accent-emerald-500 cursor-pointer"
                          checked={formData.can_cash_out}
                          onChange={e => setFormData({...formData, can_cash_out: e.target.checked})}
                          disabled={formData.is_superuser || formData.role === 'VENDEUR'}
                        />
                        <div className="flex flex-col">
                          <span className="font-bold text-xs group-hover:text-emerald-600 transition-colors">{t('permissions.cash_out')}</span>
                          <span className="text-[10px] opacity-60 leading-none mt-0.5">{t('permissions.cash_out_desc')}</span>
                        </div>
                      </label>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                        <Checkbox 
                          size="xs"
                          checked={formData.can_do_returns} 
                          onChange={checked => setFormData({...formData, can_do_returns: checked})} 
                          label={t('permissions.returns')} 
                          className="p-2 bg-white rounded-lg border border-slate-200"
                        />
                        <Checkbox 
                          size="xs"
                          color="warning"
                          checked={formData.can_sell_negative_stock} 
                          onChange={checked => setFormData({...formData, can_sell_negative_stock: checked})} 
                          label={t('permissions.negative_stock')} 
                          className="p-2 bg-white rounded-lg border border-slate-200 text-amber-600 font-bold"
                        />
                        <Checkbox 
                          size="xs"
                          checked={formData.can_modify_price} 
                          onChange={checked => setFormData({...formData, can_modify_price: checked})} 
                          label={t('permissions.modify_price')} 
                          className="p-2 bg-white rounded-lg border border-slate-200"
                        />
                        <Checkbox 
                          size="xs"
                          checked={formData.can_generate_coupon} 
                          onChange={checked => setFormData({...formData, can_generate_coupon: checked})} 
                          label={t('permissions.generate_coupon')} 
                          className="p-2 bg-white rounded-lg border border-slate-200"
                        />
                        <Checkbox 
                          size="xs"
                          checked={formData.can_modify_invoice} 
                          onChange={checked => setFormData({...formData, can_modify_invoice: checked})} 
                          label={t('permissions.modify_invoice')} 
                          className="p-2 bg-white rounded-lg border border-slate-200"
                        />
                        <Checkbox 
                          size="xs"
                          checked={formData.can_view_cash_sessions} 
                          onChange={checked => setFormData({...formData, can_view_cash_sessions: checked})} 
                          label={t('permissions.view_cash_sessions', 'Voir les sessions de caisse')} 
                          className="p-2 bg-white rounded-lg border border-slate-200"
                        />
                      </div>

                      <div className="flex flex-col gap-1 px-2 mt-1">
                        <label className="flex flex-col gap-0.5 py-1">
                          <span className="text-[10px] font-bold text-slate-400">{t('form.max_discount')}</span>
                        </label>
                        <input 
                          type="number" 
                          className="w-full rounded-xl border border-slate-200 bg-white h-8 px-3 text-sm font-bold focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all" 
                          value={formData.max_discount_rate}
                          onChange={e => setFormData({...formData, max_discount_rate: parseInt(e.target.value) || 0})}
                        />
                      </div>
                    </div>
                  </div>

                  <div className="space-y-4">
                    <div className="flex items-center gap-2 border-l-2 border-red-500 pl-3 bg-red-50 py-1 rounded-r-lg">
                      <h4 className="font-bold text-xs uppercase tracking-widest text-red-500">{t('modal.security_sudo')}</h4>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 bg-slate-50 p-4 rounded-xl border border-slate-200">
                      <Checkbox 
                        size="xs" color="error"
                        checked={formData.can_validate_zero_amount}
                        onChange={checked => setFormData({...formData, can_validate_zero_amount: checked})}
                        label={t('permissions.validate_zero_amount', 'Autoriser ventes ├á 0F')}
                        className="p-2 bg-white rounded-lg border border-red-100 text-red-500 font-bold"
                      />
                      <Checkbox 
                        size="xs" color="error"
                        checked={formData.can_cancel_invoice} onChange={checked => setFormData({...formData, can_cancel_invoice: checked})}
                        label={t('permissions.cancel_invoice')} className="p-2 bg-white rounded-lg border border-red-100 text-red-500 font-medium"
                      />
                      <Checkbox 
                        size="xs" color="error"
                        checked={formData.can_cancel_promis} onChange={checked => setFormData({...formData, can_cancel_promis: checked})}
                        label={t('permissions.cancel_promis')} className="p-2 bg-white rounded-lg border border-red-100 text-red-500 font-medium"
                      />
                      <Checkbox 
                        size="xs" color="error"
                        checked={formData.can_delete_product} onChange={checked => setFormData({...formData, can_delete_product: checked})}
                        label={t('permissions.delete_product')} className="p-2 bg-white rounded-lg border border-red-100 text-red-500 font-medium"
                      />
                      <Checkbox 
                        size="xs" color="error"
                        checked={formData.can_delete_fournisseur} onChange={checked => setFormData({...formData, can_delete_fournisseur: checked})}
                        label={t('permissions.delete_fournisseur')} className="p-2 bg-white rounded-lg border border-red-100 text-red-500 font-medium"
                      />
                      <Checkbox 
                        size="xs" color="warning"
                        checked={formData.can_adjust_stock} onChange={checked => setFormData({...formData, can_adjust_stock: checked})}
                        label={t('permissions.adjust_stock')} className="p-2 bg-white rounded-lg border border-amber-100 text-amber-600 font-medium"
                      />
                      <Checkbox 
                        size="xs" color="warning"
                        checked={formData.can_manage_perimes} onChange={checked => setFormData({...formData, can_manage_perimes: checked})}
                        label={t('permissions.manage_perimes')} className="p-2 bg-white rounded-lg border border-amber-100 text-amber-600 font-medium"
                      />
                      <Checkbox 
                        size="xs" color="warning"
                        checked={formData.can_manage_avoirs} onChange={checked => setFormData({...formData, can_manage_avoirs: checked})}
                        label={t('permissions.manage_avoirs')} className="p-2 bg-white rounded-lg border border-amber-100 text-amber-600 font-medium"
                      />
                      <Checkbox 
                        size="xs" color="warning"
                        checked={formData.can_delete_commande} onChange={checked => setFormData({...formData, can_delete_commande: checked})}
                        label={t('permissions.delete_commande')} className="p-2 bg-white rounded-lg border border-amber-100 text-amber-600 font-medium"
                      />
                      <Checkbox 
                        size="xs" color="warning"
                        checked={formData.can_close_commande} onChange={checked => setFormData({...formData, can_close_commande: checked})}
                        label={t('permissions.close_commande')} className="p-2 bg-white rounded-lg border border-amber-100 text-amber-600 font-medium"
                      />
                    </div>
                  </div>
              </div>
            </form>

            <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end gap-3 flex-none">
              <button type="button" className="inline-flex items-center gap-1.5 px-3 py-2 text-slate-500 hover:bg-slate-100 rounded-xl text-sm font-medium transition-colors" onClick={() => setModalOpen(false)}>{t('common:cancel')}</button>
              <button type="submit" onClick={() => handleSubmit({ preventDefault: () => {} } as React.FormEvent)} className="inline-flex items-center gap-1.5 px-10 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold hover:bg-blue-700 transition-colors shadow-sm shadow-blue-200">{t('common:save')}</button>
            </div>
          </div>
        </div>
      )}

      <PasswordConfirmModal
        isOpen={isPasswordModalOpen}
        onClose={() => setIsPasswordModalOpen(false)}
        onConfirm={handlePasswordConfirmed}
        title={passwordModalConfig.title}
        message={passwordModalConfig.message}
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import api from '../services/api';
import { format } from 'date-fns';
import { fr } from 'date-fns/locale';
import { useAuth } from '../context/AuthContext';
import { useTranslation } from 'react-i18next';
import { Calendar, RefreshCw, Package, TrendingUp, ChevronLeft, ChevronRight, FileDown, Printer } from 'lucide-react';
import { formatCurrency } from '../utils/formatters';
import { usePharmacySettings } from '../hooks/usePharmacySettings';
import { exportToExcel } from '../utils/excelExport';

interface _DailyPurchase {
  date: string;
  nb_commandes: number;
  total_achat: number;
}

interface DetailedPurchase {
  produit_id: number;
  produit__name: string;
  produit__cip1: string;
  total_quantite: number;
  total_achat: number;
  nb_commandes: number;
}

interface Supplier {
  id: number;
  name: string;
}

interface HistoriqueAchatsProps {
    forcedType?: 'LOC' | 'DIR';
}

const formatMoney = (amount: number) => formatCurrency(amount);

function normalizeNumber(val: unknown) {
    if (typeof val === 'string') return parseFloat(val);
    return val;
}

const handlePrint = () => {
    window.print();
};

const HistoriqueAchats = ({ forcedType }: HistoriqueAchatsProps) => {
  const { t, i18n } = useTranslation('orders');
  const { user } = useAuth();
  const { settings: pharmacySettings } = usePharmacySettings();
  const [data, setData] = useState<unknown[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(true);
  
  // Pagination
  const [page, setPage] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const pageSize = 50;

  // Global Totals from Backend
  const [globalTotals, setGlobalTotals] = useState({
    total_achat_global: 0,
    nb_commandes_global: 0,
    total_produits_global: 0
  });

  // Filters
  const [dateDebut, setDateDebut] = useState('');
  const [dateFin, setDateFin] = useState('');
  const [selectedSupplier, setSelectedSupplier] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'summary' | 'details'>('summary');
  const [searchQuery, setSearchQuery] = useState('');

  // Fetch Suppliers on mount
  useEffect(() => {
    const fetchSuppliers = async () => {
        if (!user?.token) return;
        try {
            const response = await api.get('fournisseurs/');
            const data = response.data;
            setSuppliers(Array.isArray(data) ? data : (data.results || []));
        } catch (error) {
            console.error('Error fetching suppliers:', error);
        }
    };
    fetchSuppliers();
  }, [user]);

  const fetchHistory = async (targetPage = page) => {
    if (!user?.token) return;
    
    setLoading(true);
    try {
      const params = new URLSearchParams();
      params.append('page', targetPage.toString());
      params.append('page_size', pageSize.toString());
      if (dateDebut) params.append('date_debut', dateDebut);
      if (dateFin) params.append('date_fin', dateFin);
      if (selectedSupplier) params.append('fournisseur_id', selectedSupplier);
      if (forcedType) params.append('type', forcedType);

      const endpoint = activeTab === 'summary' ? 'historique-achats/' : 'historique-achats/produits_details/';
      
      const response = await api.get(`${endpoint}?${params.toString()}`);
      
      if (response.data.results) {
        setData(response.data.results);
        setTotalCount(response.data.count);
        if (response.data.extras) {
          setGlobalTotals(response.data.extras);
        }
      } else {
        setData(response.data);
        setTotalCount(response.data.length);
      }
    } catch (error) {
      console.error('Error fetching purchase history:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user?.token) {
      setData([]); // Reset data to avoid "Invalid Date" errors when switching tabs
      setPage(1);
      fetchHistory(1);
    }
  }, [dateDebut, dateFin, selectedSupplier, user, activeTab, forcedType]);

  const handlePageChange = (newPage: number) => {
    setPage(newPage);
    fetchHistory(newPage);
  };

  const handleExportExcel = async () => {
    if (!user?.token) return;
    setLoading(true);
    try {
        const params = new URLSearchParams();
        params.append('no_pagination', 'true');
        if (dateDebut) params.append('date_debut', dateDebut);
        if (dateFin) params.append('date_fin', dateFin);
        if (selectedSupplier) params.append('fournisseur_id', selectedSupplier);
        if (forcedType) params.append('type', forcedType);
        
        const endpoint = activeTab === 'summary' ? 'historique-achats/' : 'historique-achats/produits_details/';
        
        const response = await api.get(`${endpoint}?${params.toString()}`);
        
        const exportData = response.data;
        if (!exportData || exportData.length === 0) return;

        let dataToExport: unknown[] = [];
        if (activeTab === 'summary') {
            dataToExport = exportData.map((row: unknown) => ({
                [t('history.columns.date')]: format(new Date(row.date), 'dd/MM/yyyy'),
                [t('history.columns.nb_orders')]: row.nb_commandes,
                [t('history.columns.total_purchase')]: normalizeNumber(row.total_achat)
            }));
        } else {
            dataToExport = exportData.map((row: unknown) => ({
                [t('history.columns.product')]: row.produit__name,
                [t('history.columns.cip')]: row.produit__cip1,
                [t('history.columns.quantity')]: row.total_quantite,
                [t('history.columns.nb_purchases')]: row.nb_commandes,
                [t('history.columns.total_purchase')]: normalizeNumber(row.total_achat)
            }));
        }

        const filename = `historique_achats_${activeTab}_${format(new Date(), 'yyyy-MM-dd')}.xlsx`;
        exportToExcel(dataToExport, pharmacySettings, {
            sheetName: activeTab === 'summary' ? t('tabs.purchase_summary') : t('tabs.purchase_details'),
            filename,
            title: activeTab === 'summary' ? t('tabs.purchase_summary') : t('tabs.purchase_details'),
        });
    } catch (error) {
        console.error('Error exporting history:', error);
    } finally {
        setLoading(false);
    }
  };

  const totalPages = Math.ceil(totalCount / pageSize);
  // Using global totals instead of page-only totals as requested
  const totalDisplayCount = activeTab === 'summary' 
    ? globalTotals.nb_commandes_global 
    : globalTotals.total_produits_global;
  const totalDisplayAmount = globalTotals.total_achat_global;

  const filteredData = activeTab === 'summary' || !searchQuery
    ? data
    : data.filter(row => {
        const d = row as DetailedPurchase;
        const q = searchQuery.toLowerCase();
        return d.produit__name?.toLowerCase().includes(q) || String(d.produit__cip1 ?? '').includes(q);
      });

  return (
    <>
      <div className="h-full flex flex-col p-3 sm:p-6 overflow-hidden">
        <div className="w-full max-w-4xl mx-auto flex flex-col h-full min-h-0 overflow-hidden">
          {/* Header */}
          <div className="flex flex-col gap-3 mb-4 sm:mb-5 shrink-0">
            <div>
              <h1 className="text-lg sm:text-xl font-bold text-slate-800 flex flex-col sm:flex-row sm:items-center gap-2">
                <span className="inline-flex items-center gap-2">
                  <Calendar className="size-5 text-blue-600" />
                  {t('history.title')}
                </span>
                <span className="text-blue-600 text-sm sm:text-xl sm:ml-1">
                  {forcedType === 'LOC' ? t('history.subtitle_local') : forcedType === 'DIR' ? t('history.subtitle_direct') : t('history.subtitle_daily')}
                </span>
              </h1>
              <p className="text-[10px] text-slate-400 mt-0.5 uppercase tracking-wider font-semibold">{totalCount} {t('history.results_found')}</p>
            </div>

            <div className="w-full max-w-full overflow-x-auto pb-1 -mx-1 px-1 sm:mx-0 sm:px-0">
              <div className="flex bg-slate-200/70 p-1 rounded-xl no-print w-max min-w-full sm:min-w-0 sm:w-auto gap-1">
                <button
                  className={`h-8 px-4 rounded-lg text-xs font-bold uppercase transition-all whitespace-nowrap ${
                    activeTab === 'summary' ? 'bg-blue-600 text-white shadow' : 'text-slate-500 hover:bg-slate-300'
                  }`}
                  onClick={() => setActiveTab('summary')}
                >
                  {t('tabs.purchase_summary')}
                </button>
                <button
                  className={`h-8 px-4 rounded-lg text-xs font-bold uppercase transition-all whitespace-nowrap ${
                    activeTab === 'details' ? 'bg-blue-600 text-white shadow' : 'text-slate-500 hover:bg-slate-300'
                  }`}
                  onClick={() => setActiveTab('details')}
                >
                  {t('tabs.purchase_details')}
                </button>
              </div>
            </div>
          </div>

          {/* Filters Bar */}
          <div className="mb-4 shrink-0 no-print">
            <div className="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full">
                <div className="relative w-full">
                  <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-slate-400" />
                  <input
                    type="date"
                    className="w-full h-9 pl-10 pr-4 rounded-xl border border-slate-200 bg-white text-xs font-bold text-slate-700 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all"
                    value={dateDebut}
                    onChange={(e) => setDateDebut(e.target.value)}
                  />
                </div>
                <div className="relative w-full">
                  <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-slate-400" />
                  <input
                    type="date"
                    className="w-full h-9 pl-10 pr-4 rounded-xl border border-slate-200 bg-white text-xs font-bold text-slate-700 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all"
                    value={dateFin}
                    onChange={(e) => setDateFin(e.target.value)}
                  />
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-3 w-full lg:w-auto lg:min-w-[280px]">
                <select
                  className="w-full h-9 rounded-xl border border-slate-200 bg-white px-3 text-xs font-bold text-slate-700 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all appearance-none"
                  value={selectedSupplier}
                  onChange={(e) => setSelectedSupplier(e.target.value)}
                >
                  <option value="">{t('history.all_providers')}</option>
                  {suppliers.map((s) => (
                    <option key={s.id} value={s.id}>
                      {s.name}
                    </option>
                  ))}
                </select>

                <div className="flex items-center justify-stretch sm:justify-end gap-1 w-full sm:w-auto">
                  <button
                    className="flex-1 sm:flex-initial h-9 w-9 rounded-xl flex items-center justify-center text-blue-600 hover:bg-blue-50 transition-colors disabled:opacity-40"
                    onClick={() => fetchHistory()}
                    disabled={loading}
                    title={t('history.refresh')}
                    type="button"
                  >
                    <RefreshCw className={`size-4 ${loading ? 'animate-spin' : ''}`} />
                  </button>
                  <button
                    className="flex-1 sm:flex-initial h-9 w-9 rounded-xl flex items-center justify-center text-emerald-600 hover:bg-emerald-50 transition-colors disabled:opacity-40"
                    onClick={handleExportExcel}
                    disabled={loading}
                    title={t('history.export_excel')}
                    type="button"
                  >
                    <FileDown className="size-4" />
                  </button>
                  <button
                    className="flex-1 sm:flex-initial h-9 w-9 rounded-xl flex items-center justify-center text-cyan-600 hover:bg-cyan-50 transition-colors disabled:opacity-40"
                    onClick={handlePrint}
                    disabled={loading || data.length === 0}
                    title={t('history.print_pdf')}
                    type="button"
                  >
                    <Printer className="size-4" />
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* Search bar inside filters bar logic or below */}
          {activeTab === 'details' && (
            <div className="mb-4 no-print">
              <input 
                type="text"
                className="w-full h-9 rounded-xl border border-slate-200 bg-white px-4 text-xs text-slate-700 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all"
                placeholder={t('history.product_search_placeholder')}
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          )}

          {/* Summary Cards */}
          <div className="grid grid-cols-2 gap-4 mb-4 shrink-0">
            <div className="bg-gradient-to-br from-blue-50 to-blue-100/60 border border-blue-200 rounded-2xl px-5 py-3 flex items-center shadow-sm">
              <div className="flex items-center gap-3">
                <div className="size-10 rounded-xl bg-blue-100 flex items-center justify-center">
                  <Package className="size-5 text-blue-600" />
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none mb-1">
                    {activeTab === 'summary' ? t('history.columns.nb_orders') : t('history.columns.nb_products', { defaultValue: 'Nombre de produits' })}
                  </p>
                  <p className="text-xl font-black text-slate-800 leading-none">{totalDisplayCount}</p>
                </div>
              </div>
            </div>
            <div className="bg-gradient-to-br from-emerald-50 to-emerald-100/60 border border-emerald-200 rounded-2xl px-5 py-3 flex items-center shadow-sm">
              <div className="flex items-center gap-3">
                <div className="size-10 rounded-xl bg-emerald-100 flex items-center justify-center">
                  <TrendingUp className="size-5 text-emerald-600" />
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none mb-1">{t('history.columns.total_purchase')}</p>
                  <p className="text-xl font-black text-slate-800 leading-none">
                    {formatMoney(totalDisplayAmount)} <span className="text-xs font-bold text-slate-400 ml-0.5">{t('common:currency_symbol')}</span>
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Table Container */}
          <div className="flex-1 min-h-0 flex flex-col">
            <div className={`overflow-auto flex-1 rounded-xl border border-slate-200 bg-white shadow-sm transition-opacity duration-300 ${loading ? 'opacity-60 pointer-events-none' : 'opacity-100'}`}>
              <table className="w-full border-separate border-spacing-0 text-sm">
                <thead>
                  <tr className="bg-slate-50 text-[11px] font-black text-slate-400 uppercase tracking-[0.15em]">
                    {activeTab === 'summary' ? (
                      <>
                        <th className="sticky top-0 z-30 py-4 pl-8 text-left border-b border-slate-200 bg-slate-50">{t('history.columns.date')}</th>
                        <th className="sticky top-0 z-30 text-center py-4 border-b border-slate-200 bg-slate-50">{t('history.columns.nb_orders')}</th>
                        <th className="sticky top-0 z-30 text-right py-4 pr-8 border-b border-slate-200 bg-slate-50">{t('history.columns.total_purchase')}</th>
                      </>
                    ) : (
                      <>
                        <th className="sticky top-0 z-30 py-4 pl-8 text-left border-b border-slate-200 bg-slate-50">{t('history.columns.product')}</th>
                        <th className="sticky top-0 z-30 py-4 text-left border-b border-slate-200 bg-slate-50">{t('history.columns.cip')}</th>
                        <th className="sticky top-0 z-30 text-center py-4 border-b border-slate-200 bg-slate-50">{t('history.columns.quantity')}</th>
                        <th className="sticky top-0 z-30 text-center py-4 border-b border-slate-200 bg-slate-50">{t('history.columns.nb_purchases')}</th>
                        <th className="sticky top-0 z-30 text-right py-4 pr-8 border-b border-slate-200 bg-slate-50">{t('history.columns.total_purchase')}</th>
                      </>
                    )}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 font-sans">
                  {loading && data.length === 0 ? (
                    <tr>
                      <td colSpan={activeTab === 'summary' ? 3 : 5} className="py-20 text-center">
                        <span className="size-10 border-4 border-slate-200 border-t-blue-500 rounded-full animate-spin inline-block"></span>
                      </td>
                    </tr>
                  ) : filteredData.map((row, i) => (
                    <tr key={activeTab === 'summary' ? row.date : row.produit_id} className="group hover:bg-blue-50/40 transition-colors">
                      {activeTab === 'summary' ? (
                        <>
                          <td className="py-3 pl-8">
                            <div className="flex items-center gap-3">
                              <div className={`size-1.5 rounded-full ${i === 0 ? 'bg-blue-500' : 'bg-slate-200'}`} />
                              <span className="text-sm font-bold text-slate-600">
                                {row.date ? format(new Date(row.date), 'dd MMMM yyyy', { locale: i18n.language.startsWith('fr') ? fr : undefined }) : '---'}
                              </span>
                            </div>
                          </td>
                          <td className="py-3 text-center">
                            <span className="inline-flex items-center justify-center h-7 px-3 rounded-full bg-slate-100 text-slate-600 text-xs font-black group-hover:bg-blue-100 group-hover:text-blue-700 transition-colors">
                              {row.nb_commandes}
                            </span>
                          </td>
                          <td className="py-3 text-right pr-8">
                            <span className="text-base font-black text-slate-800 group-hover:text-blue-600 transition-colors">
                              {formatMoney(normalizeNumber(row.total_achat))}
                            </span>
                            <span className="text-[10px] font-bold text-slate-400 ml-1">{t('common:currency_symbol')}</span>
                          </td>
                        </>
                      ) : (
                        <>
                          <td className="py-3 pl-8">
                            <div className="font-bold text-sm text-slate-700 group-hover:text-blue-600 transition-colors">{row.produit__name}</div>
                          </td>
                          <td className="py-3">
                            <div className="font-mono text-xs text-slate-400">{row.produit__cip1}</div>
                          </td>
                          <td className="py-3 text-center">
                            <span className="inline-flex items-center justify-center h-6 px-2.5 rounded-full bg-slate-100 text-slate-600 text-xs font-bold">{row.total_quantite}</span>
                          </td>
                          <td className="py-3 text-center">
                            <span className="text-xs font-bold text-slate-500">{row.nb_commandes}</span>
                          </td>
                          <td className="py-3 text-right pr-8">
                            <span className="text-sm font-black text-slate-800">
                              {formatMoney(normalizeNumber(row.total_achat))}
                            </span>
                            <span className="text-[10px] font-bold text-slate-400 ml-1">{t('common:currency_symbol')}</span>
                          </td>
                        </>
                      )}
                    </tr>
                  ))}
                  {data.length === 0 && !loading && (
                    <tr>
                      <td colSpan={activeTab === 'summary' ? 3 : 5} className="text-center py-24">
                        <div className="flex flex-col items-center gap-3 text-slate-300">
                          <Package className="size-12" />
                          <p className="text-sm font-bold uppercase tracking-widest">{t('history.no_data')}</p>
                        </div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>

            {/* Pagination Component */}
            {totalPages > 1 && (
              <div className="flex items-center justify-between mt-5 px-2 shrink-0 no-print">
                <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  {t('history.pagination.page')} {page} <span className="mx-1 text-slate-300">/</span> {totalPages}
                </div>
                <div className="flex gap-2">
                  <button 
                    className="h-7 w-7 rounded-xl bg-white border border-slate-200 hover:border-blue-400 text-slate-600 flex items-center justify-center transition-all active:scale-90 disabled:opacity-40" 
                    disabled={page === 1}
                    onClick={() => handlePageChange(page - 1)}
                  >
                    <ChevronLeft className="size-4" />
                  </button>
                  <button 
                    className="h-7 w-7 rounded-xl bg-white border border-slate-200 hover:border-blue-400 text-slate-600 flex items-center justify-center transition-all active:scale-90 disabled:opacity-40" 
                    disabled={page === totalPages}
                    onClick={() => handlePageChange(page + 1)}
                  >
                    <ChevronRight className="size-4" />
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
      <style>{`
        @media print {
          .no-print, .tabs, .pagination, button, .select, input, .tooltip {
            display: none !important;
          }
          .card, .rounded-xl, .border-2, .shadow-sm, .shadow-lg {
            border: none !important;
            box-shadow: none !important;
            border-radius: 0 !important;
          }
          .p-6, .max-w-4xl {
            padding: 0 !important;
            max-width: 100% !important;
            margin: 0 !important;
          }
          table {
            border-collapse: collapse !important;
            width: 100% !important;
          }
          th {
            background-color: #f1f5f9 !important;
            -webkit-print-color-adjust: exact;
            color: black !important;
            border-bottom: 2px solid #e2e8f0 !important;
          }
          body {
            background: white !important;
            color: black !important;
          }
          .h-full, .overflow-hidden, .overflow-auto {
            height: auto !important;
            overflow: visible !important;
          }
        }
      `}</style>
    </>
  );
};

export default HistoriqueAchats;

import { useState, useEffect, useCallback, useMemo } from 'react'
import api from '../services/api'
import { toast } from 'react-hot-toast'
import { fr } from 'date-fns/locale'
import 'react-datepicker/dist/react-datepicker.css'
import DatePicker, { registerLocale } from 'react-datepicker'
import { generateClotureTemplate } from '../utils/print/printTemplates'
import BestCashierMetric from './BestCashierMetric'
import { format } from 'date-fns'
import { formatCurrency, normalizeNumberInput } from '../utils/formatters'
import { useTranslation } from 'react-i18next'
import { usePharmacySettings } from '../hooks/usePharmacySettings'
import { useAuth } from '../context/AuthContext'
import { Button } from './shadcn/button'
import { Badge } from './shadcn/badge'
import { cn } from '../lib/utils'

registerLocale('fr', fr)

import { 
  CheckCircle,
  XCircle,
  Banknote,
  Eye,
  Printer,
  Monitor,
  Clock,
  PlayCircle,
  StopCircle,
  List,
  CalendarDays
} from 'lucide-react'

interface DetailsPaiement {
  [mode: string]: string | number | undefined
}

interface DetailsMeta {
  total_ca_pharmacie?: number
  total_ca_divers?: number
}

interface ClotureCaisse {
  id: number
  date: string
  montant_reel: string
  montant_theorique: string
  ecart_caisse: string
  total_ventes: string | number
  total_entrees: string | number
  total_sorties: string | number
  details_paiement: DetailsPaiement
  poste_caisse_nom?: string
  date_debut: string | null
  date_fin: string | null
  user: number | null
  user_name: string
  cloture_par_name?: string
  username: string
  observation: string | null
}

interface SessionCaisse {
  id: number
  poste: number
  poste_nom: string
  ouvert_par: number | null
  ouvert_par_name: string
  fond_de_caisse: string | null
  date_ouverture: string
  date_fermeture: string | null
  montant_total_encaisse: string | null
  est_active: boolean
  ventilation_paiements: Record<string, number>
}

const formatDateForApi = (date: Date): string => {
  const pad = (num: number) => num.toString().padStart(2, '0')
  const year = date.getFullYear()
  const month = pad(date.getMonth() + 1)
  const day = pad(date.getDate())
  return `${year}-${month}-${day}`
}

export default function HistoriqueClotures() {
  const { t } = useTranslation(['cash_closings', 'common'])
  const { settings: pharmacySettings } = usePharmacySettings()
  const { user: currentUser } = useAuth()
  const currentLocale = t('common:locale', { defaultValue: 'fr-FR' })
  const currencySymbol = t(['common:currency_symbol', 'currency_symbol'], 'F')
  const [clotures, setClotures] = useState<ClotureCaisse[]>([])
  const [loading, setLoading] = useState(false)
  
  // Onglet actif: 'clotures' | 'sessions'
  const [activeTab, setActiveTab] = useState<'clotures' | 'sessions'>('clotures')
  
  // Permission pour voir les sessions
  const [canViewSessions, setCanViewSessions] = useState(false)
  
  // Sessions de caisse
  const [sessions, setSessions] = useState<SessionCaisse[]>([])
  const [sessionsLoading, setSessionsLoading] = useState(false)
  const [selectedSession, setSelectedSession] = useState<SessionCaisse | null>(null)
  
  // Utilisateurs pour le filtrage
  const [users, setUsers] = useState<{ id: string | number; username: string; first_name?: string; last_name?: string }[]>([])
  const [selectedUser, setSelectedUser] = useState<string>('')
  
  // Filtres ÔÇö par d├®faut : mois en cours
  const [dateDebut, setDateDebut] = useState<Date | null>(() => {
    const now = new Date()
    return new Date(now.getFullYear(), now.getMonth(), 1)
  })
  const [dateFin, setDateFin] = useState<Date | null>(() => {
    const now = new Date()
    return new Date(now.getFullYear(), now.getMonth() + 1, 0)
  })
  
  // Pagination
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize] = useState(31)
  const [totalItems, setTotalItems] = useState(0)
  
  // Totaux globaux de la p├®riode
  const [globalTotals, setGlobalTotals] = useState<Record<string, string | number> | null>(null)

  // Multi-Caisse
  const [postesCaisses, setPostesCaisses] = useState<{ id: string | number; nom: string }[]>([])
  const [selectedPosteCaisse, setSelectedPosteCaisse] = useState<string>('')
  const [isMultiCaisse, setIsMultiCaisse] = useState(false)
  
  // Mode d'affichage: liste d├®taill├®e ou agr├®gation par jour
  const [viewMode, setViewMode] = useState<'list' | 'daily'>('list')

  // S├®lection
  const [selectedCloture, setSelectedCloture] = useState<ClotureCaisse | null>(null)

  // Metric month/year (default to now)
  const [metricMonth, setMetricMonth] = useState<string>(() => format(new Date(), 'MM'))
  const [metricYear, setMetricYear] = useState<string>(() => format(new Date(), 'yyyy'))
  const [showMetric, setShowMetric] = useState(false)


  // R├®cup├®rer les donn├®es initiales (utilisateurs, r├®glages, postes, permissions)
  useEffect(() => {
    const initPage = async () => {
      try {
        const [usersRes, settingsRes, postesRes, meRes] = await Promise.all([
          api.get('caisse/page_init/'),
          api.get('invoice-settings/'),
          api.get('postes-caisses/'),
          api.get('users/me/')
        ])
        
        setUsers(usersRes.data.users || [])
        setIsMultiCaisse(settingsRes.data.is_multi_caisse ?? false)
        setPostesCaisses(postesRes.data.results || postesRes.data || [])
        
        // V├®rifier la permission can_view_cash_sessions
        const profile = meRes.data?.profile
        const isSuperuser = meRes.data?.is_superuser || currentUser?.is_superuser
        setCanViewSessions(isSuperuser || profile?.can_view_cash_sessions || false)
      } catch (err) {
        console.error('Erreur initialisation HistoriqueClotures:', err)
      }
    }
    initPage()
  }, [])

  const fetchClotures = useCallback(async (page = currentPage) => {
    setLoading(true)
    try {
      const params: Record<string, string | number | undefined> = {
        page,
        page_size: pageSize
      }
      
      if (dateDebut) params.date_debut = formatDateForApi(dateDebut)
      if (dateFin) params.date_fin = formatDateForApi(dateFin)
      if (selectedUser) params.user = selectedUser
      if (selectedPosteCaisse) params.poste_caisse = selectedPosteCaisse
      
      const response = await api.get('clotures-caisse/', { params })
      
      const { results, count, totals } = response.data
      setClotures(results || [])
      setTotalItems(count || 0)
      setGlobalTotals(totals || null)
    } catch (err) {
      console.error('Erreur chargement cl├┤tures:', err)
      toast.error(t('table.loading_error') || 'Erreur lors du chargement des cl├┤tures')
    } finally {
      setLoading(false)
    }
  }, [pageSize, dateDebut, dateFin, selectedUser, selectedPosteCaisse, t])

  // Fetch data whenever filters or page change
  useEffect(() => {
    fetchClotures(currentPage)
  }, [fetchClotures, currentPage, dateDebut, dateFin, selectedUser, selectedPosteCaisse])

  const handleSearch = () => {
    setCurrentPage(1)
    fetchClotures(1)
  }

  const resetFilters = () => {
    const now = new Date()
    setDateDebut(new Date(now.getFullYear(), now.getMonth(), 1))
    setDateFin(new Date(now.getFullYear(), now.getMonth() + 1, 0))
    setSelectedUser('')
    setSelectedPosteCaisse('')
    setCurrentPage(1)
  }

  // Pagination sessions (c├┤t├® frontend)
  const SESSION_PAGE_SIZE = 15
  const [sessionPage, setSessionPage] = useState(1)

  // Fetch des sessions de caisse
  const fetchSessions = useCallback(async () => {
    setSessionsLoading(true)
    try {
      const response = await api.get('sessions-caisses/')
      const data = Array.isArray(response.data) ? response.data : (response.data.results || [])
      setSessions(data)
    } catch (err) {
      console.error('Erreur chargement sessions:', err)
      toast.error('Erreur lors du chargement des sessions de caisse')
    } finally {
      setSessionsLoading(false)
    }
  }, [])

  // Charger les sessions quand l'onglet est activ├®
  useEffect(() => {
    if (activeTab === 'sessions' && canViewSessions) {
      fetchSessions()
      setSessionPage(1)
    }
  }, [activeTab, canViewSessions, fetchSessions])

  const sessionsTotalPages = Math.ceil(sessions.length / SESSION_PAGE_SIZE)
  const sessionsPaged = sessions.slice((sessionPage - 1) * SESSION_PAGE_SIZE, sessionPage * SESSION_PAGE_SIZE)

  const totalPages = Math.ceil(totalItems / pageSize)

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleString(currentLocale, {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const formatMoney = (value: string | number) => {
    return formatCurrency(normalizeNumberInput(value), currentLocale, currencySymbol)
  }

  const getModeLabel = (mode: string) => {
    return t(`common:payment_modes.${mode}`, { defaultValue: mode })
  }

  // Agr├®gation journali├¿re
  const dailyData = useMemo(() => {
    const map = new Map<string, {
      date: string
      count: number
      montant_theorique: number
      montant_reel: number
      ecart_caisse: number
      total_ventes: number
      total_entrees: number
      total_sorties: number
    }>()

    clotures.forEach(c => {
      const d = c.date?.split('T')[0] || ''
      if (!d) return
      const existing = map.get(d)
      if (existing) {
        existing.count += 1
        existing.montant_theorique += normalizeNumberInput(c.montant_theorique)
        existing.montant_reel += normalizeNumberInput(c.montant_reel)
        existing.ecart_caisse += normalizeNumberInput(c.ecart_caisse)
        existing.total_ventes += normalizeNumberInput(c.total_ventes)
        existing.total_entrees += normalizeNumberInput(c.total_entrees)
        existing.total_sorties += normalizeNumberInput(c.total_sorties)
      } else {
        map.set(d, {
          date: d,
          count: 1,
          montant_theorique: normalizeNumberInput(c.montant_theorique),
          montant_reel: normalizeNumberInput(c.montant_reel),
          ecart_caisse: normalizeNumberInput(c.ecart_caisse),
          total_ventes: normalizeNumberInput(c.total_ventes),
          total_entrees: normalizeNumberInput(c.total_entrees),
          total_sorties: normalizeNumberInput(c.total_sorties),
        })
      }
    })

    return Array.from(map.values()).sort((a, b) => b.date.localeCompare(a.date))
  }, [clotures])

  const formatDay = (dateString: string) => {
    return new Date(dateString + 'T00:00:00').toLocaleDateString(currentLocale, {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    })
  }

  const handlePrint = (cloture: ClotureCaisse) => {
    const win = window.open('about:blank', '', 'height=600,width=400')
    if (win) {
      const htmlContent = generateClotureTemplate({
        ...cloture,
        montant_reel: cloture.montant_reel,
        montant_theorique: cloture.montant_theorique,
        ecart_caisse: cloture.ecart_caisse,
        total_ventes: cloture.total_ventes,
        total_entrees: cloture.total_entrees,
        total_sorties: cloture.total_sorties,
        details_paiement: cloture.details_paiement,
        pharmacy_name: pharmacySettings.pharmacy_name
      });
      
      win.document.write(`
        <html>
          <head>
            <title>Cl├┤ture Caisse #${cloture.id}</title>
            <style>
              @media print {
                body { margin: 0; padding: 0; }
                @page { margin: 0; }
              }
              body { margin: 0; padding: 2mm; width: 80mm; background: white; }
            </style>
          </head>
          <body>
            ${htmlContent}
          </body>
        </html>
      `)
      win.document.close()
      
      // Wait for resources if any (none in this template currently but good practice)
      win.onload = () => {
        win.print();
        // win.close(); // Optionnel: fermer apr├¿s impression
      };
      
      // Fallback if onload doesn't trigger
      setTimeout(() => {
        if (win) win.print();
      }, 500);
    }
  }

  return (
    <div className="h-full flex flex-col bg-slate-50">
      {/* Header and Filters Card */}
      <div className="bg-white border-b border-slate-200 shrink-0 p-6">
        <div className="flex flex-col lg:flex-row gap-6 justify-between items-start lg:items-end">
          <div>
            <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-3">
              <div className="p-2 bg-emerald-100 rounded-lg text-emerald-600">
                <Banknote className="size-6" />
              </div>
              {t('title')}
            </h1>
            <p className="text-slate-500 mt-1 pl-12 text-sm">
              {t('description')}
            </p>

            {/* Tab Selector */}
            {canViewSessions && (
              <div className="flex gap-1 mt-4 ml-12 bg-slate-100 rounded-lg p-1 w-fit">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setActiveTab('clotures')}
                  className={cn("flex items-center gap-2 px-4 py-2 rounded-md text-sm font-bold transition-all", activeTab === 'clotures' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500 hover:text-slate-700')}
                >
                  <Banknote className="size-4" />
                  Cl├┤tures de caisse
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setActiveTab('sessions')}
                  className={cn("flex items-center gap-2 px-4 py-2 rounded-md text-sm font-bold transition-all", activeTab === 'sessions' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500 hover:text-slate-700')}
                >
                  <Clock className="size-4" />
                  Sessions de caisse
                  {sessions.filter(s => s.est_active).length > 0 && (
                    <Badge variant="outline" className="ml-1 px-1.5 py-0.5 text-[10px] font-bold rounded-full bg-emerald-50 text-emerald-600 border-emerald-200 animate-pulse">
                      {sessions.filter(s => s.est_active).length} active{sessions.filter(s => s.est_active).length > 1 ? 's' : ''}
                    </Badge>
                  )}
                </Button>
              </div>
            )}
          </div>

          <div className="flex flex-wrap lg:flex-nowrap gap-3 items-end w-full lg:w-auto">
            <div className="flex-1 lg:w-48">
              <label className="block py-1">
                <span className="text-xs font-bold uppercase tracking-wider text-slate-600">{t('filters.date_start')}</span>
              </label>
              <DatePicker
                selected={dateDebut}
                onChange={(date: Date | null) => {
                  const now = new Date()
                  setDateDebut(date ?? new Date(now.getFullYear(), now.getMonth(), 1))
                  setCurrentPage(1)
                }}
                dateFormat="dd/MM/yyyy"
                placeholderText={t('filters.select_placeholder')}
                locale="fr"
                className="w-full h-9 px-3 rounded-lg bg-slate-100 border border-slate-200 text-sm text-slate-700 focus:outline-none focus:bg-white focus:border-emerald-300 focus:ring-2 focus:ring-emerald-100 transition-all"
                isClearable
              />
            </div>

            <div className="flex-1 lg:w-48">
              <label className="block py-1">
                <span className="text-xs font-bold uppercase tracking-wider text-slate-600">{t('filters.date_end')}</span>
              </label>
              <DatePicker
                selected={dateFin}
                onChange={(date: Date | null) => {
                  const now = new Date()
                  setDateFin(date ?? new Date(now.getFullYear(), now.getMonth() + 1, 0))
                  setCurrentPage(1)
                }}
                dateFormat="dd/MM/yyyy"
                placeholderText={t('filters.select_placeholder')}
                locale="fr"
                className="w-full h-9 px-3 rounded-lg bg-slate-100 border border-slate-200 text-sm text-slate-700 focus:outline-none focus:bg-white focus:border-emerald-300 focus:ring-2 focus:ring-emerald-100 transition-all"
                isClearable
                minDate={dateDebut || undefined}
              />
            </div>

            <div className="flex-1 lg:w-48">
                <label className="block py-1">
                    <span className="text-xs font-bold uppercase tracking-wider text-slate-600">{t('filters.cashier')}</span>
                </label>
                <select
                    value={selectedUser}
                    onChange={(e) => {
                        setSelectedUser(e.target.value)
                        setCurrentPage(1)
                    }}
                    className="w-full h-9 px-3 rounded-lg bg-slate-100 border border-slate-200 text-sm text-slate-700 focus:outline-none focus:border-emerald-300 focus:ring-2 focus:ring-emerald-100 transition-all font-medium"
                >
                    <option value="">­ƒæñ {t('filters.all_cashiers') || 'Tous les caissiers'}</option>
                    {users.map((u) => (
                        <option key={u.id} value={u.id}>
                            {u.first_name ? `${u.first_name} ${u.last_name || ''}` : u.username}
                        </option>
                    ))}
                </select>
            </div>

            {isMultiCaisse && (
                <div className="flex-1 lg:w-48">
                    <label className="block py-1">
                        <span className="text-xs font-bold uppercase tracking-wider text-slate-600">Poste de Caisse</span>
                    </label>
                    <select
                        value={selectedPosteCaisse}
                        onChange={(e) => {
                            setSelectedPosteCaisse(e.target.value)
                            setCurrentPage(1)
                        }}
                        className="w-full h-9 px-3 rounded-lg bg-slate-100 border border-slate-200 text-sm text-slate-700 focus:outline-none focus:border-emerald-300 focus:ring-2 focus:ring-emerald-100 transition-all font-medium"
                    >
                        <option value="">­ƒûÑ´©Å Tous les postes</option>
                        {postesCaisses.map((p) => (
                            <option key={p.id} value={p.id}>{p.nom}</option>
                        ))}
                    </select>
                </div>
            )}

            <div className="flex gap-2">
              <Button
                size="sm"
                onClick={handleSearch}
                disabled={loading}
                className="lg:px-6"
              >
                {loading ? <div className="animate-spin rounded-full size-4 border-b-2 border-white" /> : t('filters.filter_btn')}
              </Button>

              {(dateDebut || dateFin) && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={resetFilters}
                  title={t('filters.reset_title')}
                  disabled={loading}
                >
                  Ô£ò {t('filters.reset_btn')}
                </Button>
              )}
{/* 
              <button 
                onClick={exportExcel}
                className="btn btn-sm btn-outline btn-success gap-2"
                disabled={loading || clotures.length === 0}
              >
                <Download className="size-4" />
                Excel
              </button> */}
            </div>
          </div>
        </div>
      </div>

      {/* Contenu conditionnel selon l'onglet */}
      {activeTab === 'sessions' && canViewSessions ? (
        /* ========== ONGLET SESSIONS DE CAISSE ========== */
        <div className="flex-1 px-3 sm:px-6 py-4 sm:py-6 overflow-hidden flex flex-col gap-4">
          {/* Active Sessions Banner */}
          {(() => { const activeSessions = sessions.filter(s => s.est_active); return activeSessions.length > 0 ? (
            <div className="mb-4 p-4 bg-emerald-50 border border-emerald-200 rounded-xl">
              <h3 className="font-bold text-emerald-600 text-sm uppercase tracking-wider flex items-center gap-2 mb-3">
                <PlayCircle className="size-4 animate-pulse" />
                Sessions actives en cours
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                {activeSessions.map(session => (
                  <div key={session.id} className="bg-white rounded-lg p-4 border border-emerald-200 shadow-sm">
                    <div className="flex items-center justify-between mb-2">
                      <span className="font-bold text-sm">{session.poste_nom}</span>
                      <Badge className="bg-emerald-500 text-white gap-1 font-bold">
                        <span className="size-1.5 rounded-full bg-white animate-pulse"></span>
                        En cours
                      </Badge>
                    </div>
                    <div className="text-xs text-slate-500 space-y-1">
                      <div>­ƒæñ {session.ouvert_par_name}</div>
                      <div>­ƒòÉ Ouvert le {formatDate(session.date_ouverture)}</div>
                      {session.fond_de_caisse && <div>­ƒÆ░ Fond: {formatMoney(session.fond_de_caisse)}</div>}
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setSelectedSession(session)}
                      className="w-full text-emerald-600 mt-2"
                    >
                      <Eye className="size-3" /> Voir d├®tails
                    </Button>
                  </div>
                ))}
              </div>
            </div>
          ) : null; })()}

          {/* Sessions Table */}
          <div className="flex-1 bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden flex flex-col min-h-0">
            <div className="flex-1 overflow-auto">
              <table className="min-w-full divide-y divide-slate-200">
                <thead className="bg-slate-100 sticky top-0 z-10">
                  <tr>
                    <th className="py-3 px-2 text-[10px] lg:text-xs tracking-wider uppercase text-slate-500 font-bold whitespace-nowrap">Statut</th>
                    <th className="py-3 px-2 text-[10px] lg:text-xs tracking-wider uppercase text-slate-500 font-bold whitespace-nowrap">Poste</th>
                    <th className="py-3 px-2 text-[10px] lg:text-xs tracking-wider uppercase text-slate-500 font-bold whitespace-nowrap">Caissier</th>
                    <th className="py-3 px-2 text-[10px] lg:text-xs tracking-wider uppercase text-slate-500 font-bold whitespace-nowrap">Ouverture</th>
                    <th className="py-3 px-2 text-[10px] lg:text-xs tracking-wider uppercase text-slate-500 font-bold whitespace-nowrap">Fermeture</th>
                    <th className="text-right py-3 px-2 text-[10px] lg:text-xs tracking-wider uppercase text-slate-500 font-bold whitespace-nowrap">Fond de caisse</th>
                    <th className="text-right py-3 px-2 text-[10px] lg:text-xs tracking-wider uppercase text-slate-500 font-bold whitespace-nowrap">Total encaiss├®</th>
                    <th className="text-center py-3 px-2 text-[10px] lg:text-xs tracking-wider uppercase text-slate-500 font-bold whitespace-nowrap">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-200 bg-white">
                  {sessionsLoading ? (
                    <tr>
                      <td colSpan={8} className="h-64 text-center">
                        <div className="animate-spin rounded-full size-8 border-b-2 border-emerald-600 mx-auto"></div>
                      </td>
                    </tr>
                  ) : sessions.length === 0 ? (
                    <tr>
                      <td colSpan={8} className="h-64 text-center text-slate-500">
                        <div className="flex flex-col items-center justify-center gap-3">
                          <Clock className="size-12 text-slate-300" />
                          <p className="text-lg">Aucune session de caisse</p>
                          <p className="text-sm">Les sessions appara├«tront ici apr├¿s l'ouverture d'un poste de caisse.</p>
                        </div>
                      </td>
                    </tr>
                  ) : (
                    sessionsPaged.map(session => {
                      const totalVentilation = Object.values(session.ventilation_paiements || {}).reduce((s, v) => s + v, 0)
                      return (
                        <tr key={session.id} className={cn("hover:bg-slate-50 transition-colors", session.est_active ? 'bg-emerald-50/50' : '')}>
                          <td className="py-3 px-2">
                            {session.est_active ? (
                              <Badge className="bg-emerald-500 text-white gap-1 font-bold text-[10px]">
                                <PlayCircle className="size-3" />
                                Active
                              </Badge>
                            ) : (
                              <Badge variant="outline" className="gap-1 font-bold text-slate-600 border-slate-200 text-[10px]">
                                <StopCircle className="size-3" />
                                Ferm├®e
                              </Badge>
                            )}
                          </td>
                          <td className="py-3 px-2">
                            <div className="flex items-center gap-2">
                              <Monitor className="size-4 text-slate-400" />
                              <span className="font-bold text-sm">{session.poste_nom}</span>
                            </div>
                          </td>
                          <td className="py-3 px-2 font-medium text-sm">{session.ouvert_par_name}</td>
                          <td className="py-3 px-2">
                            <div className="font-semibold text-sm">{formatDate(session.date_ouverture)}</div>
                          </td>
                          <td className="py-3 px-2">
                            {session.date_fermeture ? (
                              <div className="font-semibold text-sm">{formatDate(session.date_fermeture)}</div>
                            ) : (
                              <span className="text-emerald-600 font-bold text-xs animate-pulse">ÔÇö En cours ÔÇö</span>
                            )}
                          </td>
                          <td className="text-right py-3 px-2 font-medium text-slate-700 text-sm">
                            {session.fond_de_caisse ? formatMoney(session.fond_de_caisse) : '-'}
                          </td>
                          <td className="text-right py-3 px-2 font-bold text-emerald-600 text-sm">
                            {formatMoney(totalVentilation)}
                          </td>
                          <td className="text-center py-3 px-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => setSelectedSession(session)}
                              className="text-emerald-600 h-8 w-8 p-0"
                              title="Voir le d├®tail"
                            >
                              <Eye className="size-4" />
                            </Button>
                          </td>
                        </tr>
                      )
                    })
                  )}
                </tbody>
              </table>
            </div>
            {/* Pagination sessions */}
            {sessions.length > SESSION_PAGE_SIZE && (
              <div className="bg-white border-t border-slate-200 p-3 flex items-center justify-between shrink-0">
                <span className="text-sm text-slate-500">
                  {(sessionPage - 1) * SESSION_PAGE_SIZE + 1}ÔÇô{Math.min(sessionPage * SESSION_PAGE_SIZE, sessions.length)} sur {sessions.length} sessions
                </span>
                <div className="flex gap-1.5">
                  <Button variant="outline" size="sm" onClick={() => setSessionPage(p => Math.max(1, p - 1))} disabled={sessionPage === 1}>Pr├®c├®dent</Button>
                  <span className="px-3 py-1.5 text-xs font-bold bg-slate-100 rounded-md flex items-center">Page {sessionPage}/{sessionsTotalPages}</span>
                  <Button variant="outline" size="sm" onClick={() => setSessionPage(p => Math.min(sessionsTotalPages, p + 1))} disabled={sessionPage === sessionsTotalPages}>Suivant</Button>
                </div>
              </div>
            )}
          </div>
        </div>
      ) : (
        /* ========== ONGLET CL├öTURES (existant) ========== */
        <>

      {/* Best Cashier Ranking Section */}
      <div className="px-3 sm:px-6 pt-4 sm:pt-6">
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-4 border-b border-slate-200 flex flex-col gap-3 sm:flex-row sm:justify-between sm:items-center bg-white">
            <h2 className="font-black text-sm uppercase tracking-widest text-slate-500 flex items-center gap-2">
