import { useEffect, useState, useCallback, useRef } from 'react';
import { toast } from 'react-hot-toast';
import { useTranslation } from 'react-i18next';
import { licenceService, type LicenceNotification } from '../services/licenceService';
import { useAuth } from '../context/AuthContext';
import { AlertTriangle, Info, XCircle, X } from 'lucide-react';

/**
 * Composant qui affiche les notifications d'alerte de licence
 * sous forme de modals/toasts persistants pour tous les utilisateurs.
 *
 * ├Ç placer dans le layout principal (ex: App.tsx)
 */
export function LicenceNotifications() {
  const { t } = useTranslation('auth');
  const { isAuthenticated, loading } = useAuth();
  const notificationsRef = useRef<LicenceNotification[]>([]);
  const dismissedIdsRef = useRef<Set<number>>(new Set());
  const isLoadingRef = useRef(true);
  // Trigger pour forcer le re-render quand n├®cessaire
  const [tick, setTick] = useState(0);

  // Charger les notifications au montage (seulement si authentifi├®)
  useEffect(() => {
    if (loading || !isAuthenticated) return;
    loadNotifications();

    // Recharger toutes les 5 minutes
    const interval = setInterval(loadNotifications, 5 * 60 * 1000);
    return () => clearInterval(interval);
  }, [isAuthenticated, loading]);

  const loadNotifications = async () => {
    try {
      isLoadingRef.current = true;
      const data = await licenceService.getNotifications();
      notificationsRef.current = data.notifications;
    } catch (error) {
      console.error('Erreur chargement notifications licence:', error);
    } finally {
      isLoadingRef.current = false;
      setTick(t => t + 1); // Force re-render apr├¿s chargement
    }
  };

  // Ignorer une notification
  const handleDismiss = useCallback(async (notification: LicenceNotification) => {
    try {
      await licenceService.dismissNotification(notification.id);
      dismissedIdsRef.current.add(notification.id);
      setTick(t => t + 1);
      toast.success(t('licence.notification_dismissed'));
    } catch {
      toast.error(t('licence.notification_dismiss_error'));
    }
  }, [t]);

  // Afficher les notifications actives non ignor├®es
  useEffect(() => {
    if (isLoadingRef.current) return;

    const activeNotifications = notificationsRef.current.filter(
      (n: LicenceNotification) => !dismissedIdsRef.current.has(n.id)
    );

    activeNotifications.forEach((notification: LicenceNotification) => {
      // Afficher comme toast persistant selon la s├®v├®rit├®
      switch (notification.severity) {
        case 'CRITICAL':
          toast.error(
            (t) => <LicenceToastContent notification={notification} onDismiss={() => {
              toast.dismiss(t.id);
              handleDismiss(notification);
            }} />,
            {
              duration: Infinity,
              position: 'top-center',
              style: {
                background: '#dc2626',
                color: 'white',
                padding: '16px',
                borderRadius: '8px',
                maxWidth: '500px',
              },
            }
          );
          break;

        case 'WARNING':
          toast.error(
            (t) => <LicenceToastContent notification={notification} onDismiss={() => {
              toast.dismiss(t.id);
              handleDismiss(notification);
            }} />,
            {
              duration: 30000, // 30 secondes
              position: 'top-center',
              style: {
                background: '#f59e0b',
                color: 'white',
                padding: '16px',
                borderRadius: '8px',
                maxWidth: '500px',
              },
            }
          );
          break;

        case 'INFO':
          toast.success(
            (t) => <LicenceToastContent notification={notification} onDismiss={() => {
              toast.dismiss(t.id);
              handleDismiss(notification);
            }} />,
            {
              duration: 10000, // 10 secondes
              position: 'top-center',
              style: {
                background: '#3b82f6',
                color: 'white',
                padding: '16px',
                borderRadius: '8px',
                maxWidth: '500px',
              },
            }
          );
          break;
      }
    });
  }, [tick, handleDismiss]);

  return null; // Pas de rendu visuel, les toasts g├¿rent l'affichage
}

/**
 * Contenu d'un toast de notification de licence
 */
interface LicenceToastContentProps {
  notification: LicenceNotification;
  onDismiss: () => void;
}

function LicenceToastContent({ notification, onDismiss }: LicenceToastContentProps) {
  const { t } = useTranslation('auth');
  const getIcon = () => {
    switch (notification.severity) {
      case 'CRITICAL':
        return <XCircle className="size-6 mr-2" />;
      case 'WARNING':
        return <AlertTriangle className="size-6 mr-2" />;
      default:
        return <Info className="size-6 mr-2" />;
    }
  };

  return (
    <div className="flex items-start gap-3">
      <div className="flex-shrink-0 mt-0.5">{getIcon()}</div>
      <div className="flex-1">
        <div className="font-bold text-lg mb-1">{notification.title}</div>
        <div className="text-sm opacity-90 leading-relaxed">
          {notification.message}
        </div>
        {notification.days_remaining !== null && (
          <div className="mt-2 text-xs font-semibold opacity-80">
            {notification.days_remaining === 0
              ? t('licence.expires_today')
              : notification.days_remaining === 1
              ? t('licence.expires_tomorrow')
              : t('licence.expires_in_days', { days: notification.days_remaining })}
          </div>
        )}
      </div>
      <button
        onClick={onDismiss}
        className="flex-shrink-0 p-1 hover:bg-base-100/20 rounded-full transition-colors"
        title="Ignorer cette alerte"
      >
        <X className="size-5" />
      </button>
    </div>
  );
}

/**
 * Hook pour v├®rifier le statut de la licence
 */
function _useLicenceStatus() {
  const { isAuthenticated, loading } = useAuth();
  const [status, setStatus] = useState<{
    isValid: boolean;
    isLifetime: boolean;
    daysRemaining: number | null;
    pharmacieNom: string | null;
    plan: string | null;
  } | null>(null);

  useEffect(() => {
    if (loading || !isAuthenticated) return;

    const checkStatus = async () => {
      try {
        const data = await licenceService.getNotifications();
        setStatus({
          isValid: data.licence_status.is_valid,
          isLifetime: data.licence_status.is_lifetime,
          daysRemaining: data.licence_status.days_remaining,
          pharmacieNom: data.licence_status.pharmacie_nom,
          plan: data.licence_status.plan,
        });
      } catch (error) {
        console.error('Erreur v├®rification statut licence:', error);
      }
    };

    checkStatus();
  }, [isAuthenticated, loading]);

  return status;
}

import { useState, useEffect, useMemo } from 'react'
import { Package, RotateCcw } from 'lucide-react'
import { useStockLots } from '../hooks/useStockLots'
import { formatPrice } from '../utils/formatters'
import { formatDate } from '../utils/dateUtils'
import type { ProduitModel, StockLot, LotAllocation } from '../types'
import PremiumModal from './common/PremiumModal'

type LotSelectionModalProps = {
  isOpen: boolean
  onClose: () => void
  produit: ProduitModel | null
  quantity: number
  currentAllocations: LotAllocation[] | null
  onSelectAllocations: (allocations: LotAllocation[] | null) => void
}

function sortLotsFEFO(lots: StockLot[]): StockLot[] {
  return lots.slice().sort((a, b) => {
    const expA = a.date_expiration ? new Date(a.date_expiration).getTime() : Infinity
    const expB = b.date_expiration ? new Date(b.date_expiration).getTime() : Infinity
    if (expA !== expB) return expA - expB
    const recA = a.date_reception ? new Date(a.date_reception).getTime() : 0
    const recB = b.date_reception ? new Date(b.date_reception).getTime() : 0
    return recA - recB
  })
}

function computeFEFO(lots: StockLot[], quantity: number): LotAllocation[] {
  const sorted = sortLotsFEFO(lots)
  const allocations: LotAllocation[] = []
  let remaining = quantity
  for (const lot of sorted) {
    if (remaining <= 0) break
    const available = lot.quantity_remaining ?? 0
    if (available <= 0) continue
    const qty = Math.min(available, remaining)
    allocations.push({
      lotId: lot.id,
      lotText: lot.lot,
      lotExpiration: lot.date_expiration || null,
      quantity: qty,
      sellingPrice: lot.selling_price ?? null,
    })
    remaining -= qty
  }
  return allocations
}

export default function LotSelectionModal({
  isOpen,
  onClose,
  produit,
  quantity,
  currentAllocations,
  onSelectAllocations,
}: LotSelectionModalProps) {
  const { lots, loading, error } = useStockLots(produit?.id || null)
  const [isAuto, setIsAuto] = useState(!currentAllocations)
  const [allocations, setAllocations] = useState<LotAllocation[]>(currentAllocations || [])

  useEffect(() => {
    if (!isOpen) return
    setIsAuto(!currentAllocations)
    if (currentAllocations) {
      setAllocations(currentAllocations)
    } else if (lots.length > 0 && quantity > 0) {
      setAllocations(computeFEFO(lots, quantity))
    } else {
      setAllocations([])
    }
  }, [isOpen, lots.length, quantity, currentAllocations])

  const totalAllocated = useMemo(() => allocations.reduce((sum, a) => sum + (a.quantity || 0), 0), [allocations])
  const isValid = totalAllocated === quantity && quantity > 0
  const remaining = quantity - totalAllocated

  const handleResetFEFO = () => {
    setIsAuto(true)
    setAllocations(computeFEFO(lots, quantity))
  }

  const handleSwitchAuto = () => {
    setIsAuto(true)
    setAllocations(computeFEFO(lots, quantity))
  }

  const handleQuantityChange = (lotId: string | number, value: string) => {
    const qty = value === '' ? 0 : Math.max(0, parseInt(value, 10) || 0)
    setIsAuto(false)
    setAllocations(prev => {
      const existing = prev.find(a => String(a.lotId) === String(lotId))
      if (existing) {
        return prev.map(a => (String(a.lotId) === String(lotId) ? { ...a, quantity: qty } : a))
      }
      const lot = lots.find(l => String(l.id) === String(lotId))
      if (!lot) return prev
      return [
        ...prev,
        {
          lotId: lot.id,
          lotText: lot.lot,
          lotExpiration: lot.date_expiration || null,
          quantity: qty,
          sellingPrice: lot.selling_price ?? null,
        },
      ]
    })
  }

  const handleConfirm = () => {
    if (isAuto) {
      onSelectAllocations(null)
    } else {
      onSelectAllocations(allocations.filter(a => a.quantity > 0))
    }
    onClose()
  }

  if (!produit) return null

  return (
    <PremiumModal
      isOpen={isOpen}
      onClose={onClose}
      title={`R├®partition des lots`}
      subtitle={`${produit.name} ÔÇö Qt├®: ${quantity}`}
      icon={<Package className="size-5 text-blue-500" />}
      gradientFrom="blue-50"
      gradientTo="indigo-50"
      maxWidth="max-w-2xl"
    >
      <div className="p-6">
        {loading ? (
          <div className="flex justify-center py-8">
            <span className="inline-block w-8 h-8 border-2 border-blue-600 border-t-transparent rounded-full animate-spin"></span>
          </div>
        ) : error ? (
          <div className="p-4 bg-red-50 border border-red-200 text-red-600 text-sm rounded-xl flex items-center gap-2">
            <span className="font-medium">{error}</span>
          </div>
        ) : (
          <>
            {/* Option Auto / FEFO */}
            <div
              className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-colors mb-3 ${
                isAuto ? 'bg-blue-50 border-blue-300' : 'bg-white border-slate-200 hover:bg-slate-50'
              }`}
              onClick={handleSwitchAuto}
            >
              <div className={`size-4 rounded-full border-2 flex items-center justify-center ${isAuto ? 'border-blue-600' : 'border-slate-300'}`}>
                {isAuto && <div className="size-2 bg-blue-600 rounded-full"></div>}
              </div>
              <div className="flex-1">
                <div className="font-bold text-sm text-blue-700">­ƒÜÇ AUTOMATIQUE (FEFO)</div>
                <div className="text-xs text-slate-500">Le syst├¿me choisira automatiquement les lots expirant le plus t├┤t.</div>
              </div>
            </div>

            <div className="rounded-xl border border-slate-200">
              <table className="w-full text-sm">
                <thead className="bg-slate-100/50">
                  <tr className="text-left text-xs font-bold uppercase tracking-wider text-slate-500">
                    <th className="px-4 py-3">Lot</th>
                    <th className="px-4 py-3">Expiration</th>
                    <th className="px-4 py-3 text-right">Stock</th>
                    <th className="px-4 py-3 text-right">Prix</th>
                    <th className="px-4 py-3 text-center w-32">Qt├®</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sortLotsFEFO(lots).map(lot => {
                    const now = new Date()
                    const expire = lot.date_expiration ? new Date(lot.date_expiration) : null
                    let expiryColor = 'text-emerald-600'
                    if (expire) {
                      const days = Math.ceil((expire.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
                      if (days < 0) expiryColor = 'text-red-600 font-bold'
                      else if (days < 30) expiryColor = 'text-amber-500 font-bold'
                    }
                    const allocation = allocations.find(a => String(a.lotId) === String(lot.id))
                    const allocatedQty = allocation?.quantity || 0

                    return (
                      <tr key={lot.id} className={`${isAuto ? 'opacity-60' : 'hover:bg-slate-50'}`}>
                        <td className="px-4 py-3">
                          <div className="font-medium text-slate-800">{lot.lot}</div>
                          <div className="text-xs text-slate-400">Re├ºu le {formatDate(lot.date_reception)}</div>
                        </td>
                        <td className={`px-4 py-3 font-medium ${expiryColor}`}>
                          {lot.date_expiration ? (() => { const d = new Date(lot.date_expiration); return `${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getFullYear()).slice(-2)}`; })() : 'N/A'}
                        </td>
                        <td className="px-4 py-3 text-right font-medium text-slate-700">{lot.quantity_remaining}</td>
                        <td className="px-4 py-3 text-right whitespace-nowrap font-bold text-slate-800">{formatPrice(Number(lot.selling_price))} F</td>
                        <td className="px-4 py-3 text-center">
                          <input
                            type="number"
                            min={0}
                            max={lot.quantity_remaining}
                            value={allocatedQty || ''}
                            onChange={(e) => handleQuantityChange(lot.id, e.target.value)}
                            className="w-20 px-2 py-1 text-sm text-center border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                          />
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>

              {lots.length === 0 && (
                <div className="text-center py-4 text-slate-400 italic text-sm">
                  Aucun lot sp├®cifique disponible. Le stock global sera utilis├®.
                </div>
              )}
            </div>

            {/* R├®sum├® */}
            <div className="mt-3 flex items-center justify-between p-3 rounded-xl bg-slate-50 border border-slate-200">
              <div className="text-sm">
                <span className="font-medium text-slate-600">Allou├®: </span>
                <span className={`font-bold ${isValid ? 'text-emerald-600' : 'text-amber-600'}`}>{totalAllocated}</span>
                <span className="text-slate-500"> / {quantity}</span>
              </div>
              {!isValid && !isAuto && (
                <div className="text-xs font-medium text-amber-600">
                  {remaining > 0 ? `Il manque ${remaining} unit├®(s)` : `Exc├¿s de ${-remaining} unit├®(s)`}
                </div>
              )}
            </div>
          </>
        )}

        <div className="flex justify-end gap-3 pt-4">
          <button
            className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-bold text-blue-700 bg-blue-50 hover:bg-blue-100 rounded-xl transition-colors"
            onClick={handleResetFEFO}
            disabled={isAuto}
            type="button"
          >
            <RotateCcw className="size-4" />
