    }
  };

  const totalPreviewCount = preview?.reduce((sum, p) => {
    const childTotal = p.children.reduce((cs, c) => cs + c.count, 0);
    return sum + p.count + childTotal;
  }, 0) ?? 0;

  const tableMap = new Map(tables.map(t => [t.key, t]));

  return (
    <div className="p-4 md:p-6 max-w-5xl mx-auto">
      {/* Header */}
      <div className="flex items-center gap-3 mb-6">
        <div className="p-3 rounded-xl bg-gradient-to-br from-red-500/20 to-orange-500/20">
          <Wrench className="size-7 text-red-400" />
        </div>
        <div>
          <h1 className="text-2xl font-bold">{t('title')}</h1>
          <p className="text-sm text-slate-500">{t('subtitle')}</p>
        </div>
      </div>

      {/* Warning Banner */}
      <div className="flex items-center gap-3 mb-6 shadow-lg bg-amber-50 border border-amber-200 rounded-xl p-4">
        <AlertTriangle className="size-5 text-amber-600 shrink-0" />
        <div>
          <h3 className="font-bold text-amber-800">{t('irreversible')}</h3>
          <p className="text-sm text-amber-700">{t('warning_msg')}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Table Selection */}
        <div className="lg:col-span-2">
          <div className="bg-white shadow-xl rounded-2xl border border-slate-200">
            <div className="p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-bold flex items-center gap-2">
                  <CheckSquare className="size-5 text-indigo-600" />
                  {t('tables_title')}
                </h2>
                <div className="flex gap-2">
                  <Button variant="ghost" size="sm" onClick={selectAll}>{t('select_all')}</Button>
                  <Button variant="ghost" size="sm" onClick={deselectAll}>{t('deselect_all')}</Button>
                </div>
              </div>

              <div className="space-y-2">
                {Object.entries(TABLE_CATEGORIES).map(([catKey, cat]) => {
                  const availableKeys = cat.keys.filter(k => tableMap.has(k));
                  if (availableKeys.length === 0) return null;
                  const allCatSelected = availableKeys.every(k => selectedTables.has(k));
                  const someCatSelected = availableKeys.some(k => selectedTables.has(k));
                  const isExpanded = expandedCategories.has(catKey);

                  return (
                    <div key={catKey} className="border border-slate-200 rounded-lg overflow-hidden">
                      {/* Category header */}
                      <div
                        className={`flex items-center justify-between px-4 py-3 cursor-pointer transition-colors ${someCatSelected ? 'bg-indigo-50' : 'bg-slate-100/50 hover:bg-slate-100'}`}
                        onClick={() => toggleExpandCategory(catKey)}
                      >
                        <div className="flex items-center gap-3">
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-auto p-0"
                            onClick={(e) => { e.stopPropagation(); toggleCategory(availableKeys); }}
                          >
                            {allCatSelected ? (
                              <CheckSquare className="size-4 text-indigo-600" />
                            ) : someCatSelected ? (
                              <CheckSquare className="size-4 text-indigo-600/50" />
                            ) : (
                              <Square className="size-4 text-slate-400" />
                            )}
                          </Button>
                          <span className="font-semibold text-sm">{cat.label}</span>
                          <Badge variant="secondary" className="text-xs">{availableKeys.length}</Badge>
                        </div>
                        {isExpanded ? <ChevronUp className="size-4" /> : <ChevronDown className="size-4" />}
                      </div>

                      {/* Category items */}
                      {isExpanded && (
                        <div className="divide-y divide-slate-200">
                          {availableKeys.map(key => {
                            const table = tableMap.get(key)!;
                            const isSelected = selectedTables.has(key);
                            return (
                              <label
                                key={key}
                                className={`flex items-center gap-3 px-6 py-2.5 cursor-pointer transition-colors ${isSelected ? 'bg-indigo-50/50' : 'hover:bg-slate-100/30'}`}
                              >
                                <Checkbox
                                  checked={isSelected}
                                  onCheckedChange={() => toggleTable(key)}
                                />
                                  <span className="text-sm flex-1">{t('tables.' + table.key, table.label)}</span>
                                {table.children.length > 0 && (
                                  <span className="text-xs text-slate-400">
                                    +{table.children.length} {t('common:sub_table', { count: table.children.length })}
                                  </span>
                                )}
                              </label>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>

        {/* Right Column: Controls */}
        <div className="space-y-4">
          {/* Date Range */}
          <div className="bg-white shadow-xl rounded-2xl border border-slate-200">
            <div className="p-6">
              <h2 className="text-lg font-bold flex items-center gap-2 mb-2">
                <Calendar className="size-5 text-slate-600" />
                {t('period_title')}
              </h2>
              <div className="mb-2">
                <label className="block"><span className="text-xs text-slate-600">{t('date_from')}</span></label>
                <Input
                  type="date"
                  lang={getLocale()}
                  className="h-9 text-sm"
                  value={dateFrom}
                  onChange={e => { setDateFrom(e.target.value); setPreview(null); setPurgeResults(null); }}
                />
              </div>
              <div>
                <label className="block"><span className="text-xs text-slate-600">{t('date_to')}</span></label>
                <Input
                  type="date"
                  lang={getLocale()}
                  className="h-9 text-sm"
                  value={dateTo}
                  onChange={e => { setDateTo(e.target.value); setPreview(null); setPurgeResults(null); }}
                />
              </div>
              {!dateFrom && !dateTo && (
                <p className="text-xs text-amber-600 mt-2">{t('date_warning')}</p>
              )}
            </div>
          </div>

          {/* Action Buttons */}
          <div className="bg-white shadow-xl rounded-2xl border border-slate-200">
            <div className="p-6 space-y-3">
              <h2 className="text-lg font-bold">{t('actions')}</h2>

              <Button
                variant="primary"
                size="sm"
                className="w-full gap-2"
                onClick={handlePreview}
                disabled={loading || selectedTables.size === 0}
              >
                {loading ? <Loader2 className="size-4 animate-spin" /> : <Eye className="size-4" />}
                {t('preview_btn')}
              </Button>

              <Button
                variant="outline"
                size="sm"
                className="w-full gap-2 border-blue-500 text-blue-600 hover:bg-blue-50"
                onClick={handleExport}
                disabled={exporting || selectedTables.size === 0}
              >
                {exporting ? <Loader2 className="size-4 animate-spin" /> : <Download className="size-4" />}
                {t('export_btn')}
              </Button>

              <div className="border-t border-slate-200 my-0"></div>

              <Button
                variant="danger"
                size="sm"
                className="w-full gap-2"
                onClick={() => { if (selectedTables.size > 0) setShowConfirmModal(true); else toast.error(t('common:select_tables')); }}
                disabled={selectedTables.size === 0}
              >
                <Trash2 className="size-4" />
                {t('purge_btn')}
              </Button>
            </div>
          </div>

          {/* Gestion des Produits */}
          <div className="bg-white shadow-xl rounded-2xl border border-indigo-500/20">
            <div className="p-6 space-y-4">
              <h2 className="text-lg font-bold flex items-center gap-2">
                <Package className="size-5 text-indigo-500" />
                Gestion des Produits
              </h2>

              {/* Compteur */}
              <div className="flex items-center justify-between bg-slate-100/50 rounded-lg px-4 py-2">
                <span className="text-sm text-slate-500">Produits en base</span>
                <div className="flex items-center gap-2">
                  <span className="font-bold text-lg text-indigo-500">
                    {produitsCount === null ? '...' : produitsCount.toLocaleString()}
                  </span>
                  <Button variant="ghost" size="sm" className="h-auto p-1" onClick={() => api.get('maintenance/produits_count/').then(r => setProduitsCount(r.data.count)).catch(() => {})}>
                    <RefreshCw className="size-3" />
                  </Button>
                </div>
              </div>

              <div className="border-t border-slate-200 my-0 text-xs text-center text-slate-400 py-1">IMPORT</div>

              {/* Import Excel */}
              <div className="space-y-2">
                <p className="text-xs text-slate-500">Importez un fichier Excel (.xlsx) ou CSV pour cr├®er/mettre ├á jour les produits.</p>
                <div className="w-full">
                  <input
                    type="file"
                    accept=".xlsx,.xls,.csv"
                    className="block w-full text-sm text-slate-500 file:mr-3 file:py-1 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-medium file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100 cursor-pointer"
                    onChange={e => { setImportFile(e.target.files?.[0] || null); setImportResult(null); }}
                  />
                </div>
                <Button
                  variant="primary"
                  size="sm"
                  className="w-full gap-2"
                  onClick={handleImportProduits}
                  disabled={importing || !importFile}
                >
                  {importing ? <Loader2 className="size-4 animate-spin" /> : <FileUp className="size-4" />}
                  {importing ? 'Import en cours...' : 'Importer'}
                </Button>

                {importing && (
                  <div className="space-y-1 animate-in fade-in duration-300">
                    <div className="flex justify-between text-xs text-slate-500">
                      <span className="italic">{importMessage}</span>
                      <span className="font-bold text-indigo-500">{importProgress}%</span>
                    </div>
                    <div className="w-full h-2 bg-slate-200 rounded-full overflow-hidden">
                      <div className="h-full bg-indigo-600 rounded-full transition-all" style={{ width: `${importProgress}%` }} />
                    </div>
                  </div>
                )}

                {/* R├®sultat import */}
                {importResult && (
                  <div className="bg-slate-100 rounded-lg p-3 space-y-1 text-sm">
                    <div className="flex justify-between">
                      <span className="text-slate-500">Cr├®├®s</span>
                      <span className="font-bold text-emerald-600">{importResult.created}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-500">Mis ├á jour</span>
                      <span className="font-bold text-blue-600">{importResult.updated}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-500">Erreurs</span>
                      <span className={`font-bold ${importResult.errors > 0 ? 'text-red-600' : 'text-slate-400'}`}>{importResult.errors}</span>
                    </div>
                    {importResult.rapport_xlsx && (
                      <Button
                        variant="outline"
                        size="sm"
                        className="w-full gap-1 mt-2 border-emerald-500 text-emerald-600 hover:bg-emerald-50"
                        onClick={() => downloadRapport(importResult.rapport_xlsx as string)}
                      >
                        <FileDown className="size-3" /> T├®l├®charger le rapport Excel
                      </Button>
                    )}
                    {importResult.rapport_txt && (
                      <Button
                        variant="outline"
                        size="sm"
                        className="w-full gap-1"
                        onClick={() => downloadRapport(importResult.rapport_txt as string)}
                      >
                        <FileDown className="size-3" /> T├®l├®charger le rapport texte
                      </Button>
                    )}
                  </div>
                )}
              </div>

              <div className="border-t border-slate-200 my-0 text-xs text-center text-slate-400 py-1">PURGE</div>

              {/* Purge */}
              {purgeResult && (
                <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-3 text-sm">
                  <p className="font-bold text-emerald-600">Ô£à {purgeResult.deleted} produit(s) supprim├®(s)</p>
                  {purgeResult.conserves > 0 && (
                    <p className="text-xs text-slate-500">{purgeResult.conserves} conserv├®(s) car li├®s ├á des ventes</p>
                  )}
                </div>
              )}
              <div className="space-y-1">
                <p className="text-xs text-slate-500">Supprime tous les produits (utile si mauvais fichier import├®).</p>
                <label className="flex items-center gap-2 text-xs cursor-pointer">
                  <Checkbox
                    checked={purgeSansVentes}
                    onCheckedChange={(checked) => setPurgeSansVentes(!!checked)}
                  />
                  Conserver les produits li├®s ├á des ventes
                </label>
                <Button
                  variant="danger"
                  size="sm"
                  className="w-full gap-2"
                  onClick={() => { setPurgeResult(null); setShowPurgeModal(true); }}
                >
                  <Trash2 className="size-4" />
                  Purger les produits
                </Button>
              </div>
            </div>
          </div>

          {/* Backup Section */}
          <div className="bg-white shadow-xl rounded-2xl border border-indigo-500/20">
            <div className="p-6 space-y-4">
              <h2 className="text-lg font-bold flex items-center gap-2">
                <Database className="size-5 text-indigo-600" />
                {t('backup_title')}
              </h2>

              <div className="space-y-4">
                {/* Manual Backup */}
                <div>
                  <p className="text-xs text-slate-500 mb-2">{t('backup_desc')}</p>
                  <Button
                    variant="primary"
                    size="sm"
                    className="w-full gap-2"
                    onClick={handleManualBackup}
                    disabled={backupLoading}
                  >
                    {backupLoading ? <Loader2 className="size-4 animate-spin" /> : <Download className="size-4" />}
                    {t('backup_now')}
                  </Button>

                  {backupLoading && (
                    <div className="mt-4 space-y-2 animate-in fade-in slide-in-from-top-2 duration-300">
                      <div className="flex justify-between items-center text-[10px] font-bold uppercase tracking-widest text-indigo-600">
                        <span>{backupStep}</span>
                        <span>{Math.round(backupProgress)}%</span>
                      </div>
                      <div className="w-full h-2 bg-slate-200 rounded-full overflow-hidden shadow-inner">
                        <div className="h-full bg-indigo-600 rounded-full transition-all" style={{ width: `${backupProgress}%` }} />
                      </div>
                    </div>
                  )}
                </div>

                <div className="border-t border-slate-200 my-0"></div>

                {/* Scheduled Backup */}
                <div className="space-y-3">
                  <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 flex items-center gap-2">
                    <Clock className="size-4" />
                    {t('automatic')}
                  </h3>
                  
                  <div>
                    <label className="flex items-center gap-3 cursor-pointer p-0">
                      <Checkbox 
                        checked={pharmacySettings?.backup_enabled || false}
                        onCheckedChange={(checked) => setPharmacySettings({...pharmacySettings, backup_enabled: !!checked})}
                      />
                      <span className="text-sm text-slate-700">{t('enable_auto')}</span>
                    </label>
                  </div>

                  <div>
                    <label className="block py-1">
                      <span className="text-xs text-slate-600">{t('scheduled_time')}</span>
                    </label>
                    <Input 
                      type="time"
                      lang={getLocale()}
                      className="h-9 text-sm w-full" 
                      value={pharmacySettings?.backup_time?.substring(0, 5) || "02:00"}
                      onChange={e => setPharmacySettings({...pharmacySettings, backup_time: e.target.value})}
                    />
                  </div>

                  <div>
                    <label className="block py-1">
                      <span className="text-xs text-slate-600">{t('secondary_path')}</span>
                    </label>
                    <Input 
                      type="text" 
                      className="h-9 text-sm w-full" 
                      placeholder="Ex: E:\Backups_Pharma"
                      value={pharmacySettings?.secondary_backup_path || ""}
                      onChange={e => setPharmacySettings({...pharmacySettings, secondary_backup_path: e.target.value})}
                    />
                  </div>

                  <Button
                    variant="outline"
                    size="sm"
                    className="w-full gap-2 mt-2"
                    onClick={saveBackupSettings}
                    disabled={savingSettings || !pharmacySettings}
                  >
                    {savingSettings ? <Loader2 className="size-3 animate-spin" /> : <Save className="size-3" />}
                    {t('save_settings')}
                  </Button>
                </div>
              </div>
            </div>
          </div>


          {/* Restoration Section */}
          <div className="bg-white shadow-xl rounded-2xl border border-red-500/20">
            <div className="p-6 space-y-4">
              <h2 className="text-lg font-bold flex items-center gap-2">
                <Upload className="size-5 text-red-600" />
                {t('restore_title')}
              </h2>

              <div className="space-y-4">
                <p className="text-xs text-slate-500">{t('restore_desc')}</p>
                
                <div className="w-full">
                  <input 
                    type="file" 
                    accept=".sql.gz"
                    className="block w-full text-sm text-slate-500 file:mr-3 file:py-1 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-medium file:bg-red-50 file:text-red-700 hover:file:bg-red-100 cursor-pointer" 
                    onChange={e => setRestoreFile(e.target.files?.[0] || null)}
                  />
                </div>

                <Button
                  variant="danger"
                  size="sm"
                  className="w-full gap-2"
                  onClick={() => { if (restoreFile) setShowRestoreConfirm(true); else toast.error(t('common:select_file')); }}
                  disabled={restoring || !restoreFile}
                >
                  {restoring ? <Loader2 className="size-4 animate-spin" /> : <ShieldAlert className="size-4" />}
                  {t('restore_now')}
                </Button>
                
                {restoring && (
                  <div className="mt-4 space-y-2 animate-in fade-in slide-in-from-top-2 duration-300">
                    <div className="flex justify-between items-center text-[10px] font-bold uppercase tracking-widest text-red-600">
                      <span>{restoreStep}</span>
                      <span>{Math.round(restoreProgress)}%</span>
                    </div>
                    <div className="w-full h-2 bg-slate-200 rounded-full overflow-hidden shadow-inner">
                      <div className="h-full bg-red-600 rounded-full transition-all" style={{ width: `${restoreProgress}%` }} />
                    </div>
                    <p className="text-[10px] text-center text-red-600/60 italic">{t('restore_restart_msg')}</p>
                  </div>
                )}
              </div>
            </div>
          </div>


          {/* Source Code Management Section */}
          <div className="bg-white shadow-xl rounded-2xl border border-slate-400/20">
            <div className="p-6 space-y-4">
              <h2 className="text-lg font-bold flex items-center gap-2">
                <ShieldAlert className="size-5 text-slate-600" />
                {t('code_management.title')}
              </h2>

              <div className="space-y-4">
                {/* Code Backup */}
                <div>
                  <p className="text-xs text-slate-500 mb-2">{t('code_management.desc')}</p>
                  <Button
                    variant="secondary"
                    size="sm"
                    className="w-full gap-2"
                    onClick={handleCodeBackup}
                    disabled={codeBackupLoading}
                  >
                    {codeBackupLoading ? <Loader2 className="size-4 animate-spin" /> : <Download className="size-4" />}
                    {t('code_management.backup_now')}
                  </Button>
                </div>

                <div className="border-t border-slate-200 my-0"></div>

                {/* Code Restore */}
                <div>
                  <p className="text-xs text-slate-500 mb-2">{t('code_management.restore_desc')}</p>
                  <div className="w-full mb-2">
                    <input 
                      type="file" 
                      accept=".zip"
                      className="block w-full text-sm text-slate-500 file:mr-3 file:py-1 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-medium file:bg-slate-100 file:text-slate-700 hover:file:bg-slate-200 cursor-pointer" 
                      onChange={e => setCodeRestoreFile(e.target.files?.[0] || null)}
                    />
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    className="w-full gap-2"
                    onClick={handleCodeRestore}
                    disabled={codeRestoring || !codeRestoreFile}
                  >
                    {codeRestoring ? <Loader2 className="size-4 animate-spin" /> : <Upload className="size-4" />}
                    {t('code_management.restore_now')}
                  </Button>
                </div>
              </div>
            </div>
          </div>


          {/* Selection Summary */}
          <div className="bg-slate-100/50 rounded-2xl">
            <div className="p-3">
              <p className="text-sm">
                <span className="font-bold text-indigo-600">{selectedTables.size}</span> {t('selection_summary', { count: selectedTables.size })}
              </p>
              {dateFrom && <p className="text-xs text-slate-500">{t('from')}: {dateFrom}</p>}
              {dateTo && <p className="text-xs text-slate-500">{t('to')}: {dateTo}</p>}
            </div>
          </div>
        </div>
      </div>

      {/* Preview Results */}
      {preview && (
        <div className="bg-white shadow-xl rounded-2xl border border-slate-200 mt-6">
          <div className="p-6">
            <h2 className="text-lg font-bold flex items-center gap-2 mb-4">
              <Eye className="size-5 text-blue-600" />
              {t('preview_title', { count: totalPreviewCount })}
            </h2>
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{t('common:table')}</TableHead>
                    <TableHead className="text-right">{t('common:rows')}</TableHead>
                    <TableHead>{t('common:sub_tables')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                   {preview.map(p => (
                     <TableRow key={p.key}>
                       <TableCell className="font-medium">{t('tables.' + p.key, p.label)}</TableCell>
                      <TableCell className="text-right">
                        <Badge variant={p.count > 0 ? 'destructive' : 'secondary'} className="text-xs">
                          {formatNumber(p.count)}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        {p.children.length > 0 ? (
                          <div className="flex gap-2 flex-wrap">
                             {p.children.map((c) => (
                               <Badge key={c.label} variant="outline" className="text-xs">
                                 {t('tables.children.' + c.label.toLowerCase().replace(/ /g, '_').normalize("NFD").replace(/[\u0300-\u036f]/g, ""), c.label)}: {formatNumber(c.count)}
                               </Badge>
                             ))}
                          </div>
                        ) : (
                          <span className="text-slate-300 text-xs">-</span>
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>
        </div>
      )}

      {/* Purge Results */}
      {purgeResults && (
        <div className="bg-emerald-50 border border-emerald-200 shadow-xl rounded-2xl mt-6">
          <div className="p-6">
            <h2 className="text-lg font-bold text-emerald-600 flex items-center gap-2 mb-4">
              <Trash2 className="size-5" />
              {t('purge_finished')}
            </h2>
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{t('common:table')}</TableHead>
                    <TableHead className="text-right">{t('common:rows_deleted')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                   {purgeResults.map(r => (
                     <TableRow key={r.key}>
                       <TableCell>{t('tables.' + r.key, r.label)}</TableCell>
                      <TableCell className="text-right font-bold text-emerald-600">{formatNumber(r.deleted)}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>
        </div>
      )}

      {/* Confirmation Modal */}
      <Dialog open={showConfirmModal} onOpenChange={(open) => { if (!open) { setShowConfirmModal(false); setPassword(''); } }}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-3">
              <div className="p-2 rounded-full bg-red-100">
                <ShieldAlert className="size-6 text-red-600" />
              </div>
              {t('confirm_title')}
            </DialogTitle>
            <DialogDescription>
              <div className="flex items-center gap-3 bg-red-50 border border-red-200 rounded-lg p-3 mt-2">
                <AlertTriangle className="size-5 text-red-600 shrink-0" />
                <span className="text-sm text-red-700">
                  {t('confirm_msg')}
                </span>
              </div>
            </DialogDescription>
          </DialogHeader>

          <div className="bg-slate-100 rounded-lg p-3 mb-4 max-h-32 overflow-y-auto">
            <p className="text-xs font-semibold mb-1">{t('common:concerned_tables')} :</p>
            <ul className="text-xs space-y-0.5">
               {Array.from(selectedTables).map(key => {
                 const tbl = tableMap.get(key);
                 return <li key={key}>ÔÇó {t('tables.' + key, tbl?.label || key)}</li>;
               })}
            </ul>
            {(dateFrom || dateTo) && (
              <p className="text-xs mt-2 text-slate-500">
                {t('period')} : {dateFrom || '...'} ÔåÆ {dateTo || '...'}
              </p>
            )}
          </div>

          <div className="mb-4">
            <label className="block">
              <span className="text-sm font-semibold text-slate-700">{t('password_label')}</span>
            </label>
            <Input
              type="password"
              placeholder={t('placeholders.enter_password')}
              value={password}
              onChange={e => setPassword(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter') handlePurge(); }}
              autoFocus
            />
          </div>

          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => { setShowConfirmModal(false); setPassword(''); }}>
              {t('cancel')}
            </Button>
            <Button
              variant="danger"
              className="gap-2"
              onClick={handlePurge}
              disabled={purging || !password}
            >
              {purging ? <Loader2 className="size-4 animate-spin" /> : <Trash2 className="size-4" />}
              {t('confirm_purge')}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Restore Confirmation Modal */}
      <Dialog open={showRestoreConfirm} onOpenChange={(open) => { if (!open) { setShowRestoreConfirm(false); setRestorePassword(''); } }}>
        <DialogContent className="border-2 border-red-500/50 shadow-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-3 text-red-600">
              <div className="p-2 rounded-full bg-red-100">
                <AlertTriangle className="size-6 text-red-600" />
              </div>
              {t('restore_title')}
            </DialogTitle>
            <DialogDescription>
              <div className="flex items-center gap-3 bg-red-50 border border-red-200 rounded-lg p-3 mt-2 shadow-sm">
                <ShieldAlert className="size-5 text-red-600 shrink-0" />
                <span className="text-sm text-red-700">
                  {t('confirm_msg')}
                  <div className="font-mono mt-1 font-bold text-xs">{restoreFile?.name}</div>
                </span>
              </div>
            </DialogDescription>
          </DialogHeader>

          <div className="mb-4">
            <label className="block">
              <span className="text-sm font-semibold text-slate-700">{t('password_label')}</span>
            </label>
            <Input
              type="password"
              className="border-red-300"
              placeholder={t('placeholders.password_required')}
              value={restorePassword}
              onChange={e => setRestorePassword(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter') handleRestore(); }}
              autoFocus
            />
          </div>

          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => { setShowRestoreConfirm(false); setRestorePassword(''); }}>
              {t('cancel')}
            </Button>
            <Button
              variant="danger"
              className="gap-2 px-8"
              onClick={handleRestore}
              disabled={restoring || !restorePassword}
            >
              {restoring ? <Loader2 className="size-4 animate-spin" /> : <Database className="size-4" />}
              {t('restore_now')}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Modal Purge Produits */}
      <Dialog open={showPurgeModal} onOpenChange={(open) => { if (!open) { setShowPurgeModal(false); setPurgePassword(''); } }}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-3">
              <div className="p-2 rounded-full bg-red-100">
                <Trash2 className="size-6 text-red-600" />
              </div>
              Purger les produits
            </DialogTitle>
            <DialogDescription>
              <div className="flex items-center gap-3 bg-red-50 border border-red-200 rounded-lg p-3 mt-2">
                <AlertTriangle className="size-5 text-red-600 shrink-0" />
                <div>
                  <p className="font-bold text-red-800">Op├®ration irr├®versible</p>
                  <p className="text-sm text-red-700">
                    {purgeSansVentes
                      ? 'Tous les produits NON li├®s ├á des ventes seront supprim├®s.'
                      : 'TOUS les produits seront supprim├®s.'}
                  </p>
                </div>
              </div>
            </DialogDescription>
          </DialogHeader>

          <div className="mb-4">
            <label className="block">
              <span className="text-sm font-semibold text-slate-700">Confirmez votre mot de passe</span>
            </label>
            <Input
              type="password"
              placeholder="Mot de passe admin"
              value={purgePassword}
              onChange={e => setPurgePassword(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter') handlePurgeProduits(); }}
              autoFocus
            />
          </div>

          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => { setShowPurgeModal(false); setPurgePassword(''); }}>
              Annuler
            </Button>
            <Button
              variant="danger"
              className="gap-2"
              onClick={handlePurgeProduits}
              disabled={purging2 || !purgePassword}
            >
              {purging2 ? <Loader2 className="size-4 animate-spin" /> : <Trash2 className="size-4" />}
              Confirmer la purge
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecharts } from '../hooks/useRecharts';
import {
  useCAEvolution,
  useMargesEvolution,
  usePredictions,
  useKPIs,
  useTopProducts,
  useRepartitionCA,
  useAnalyseCategories,
  useAnalyseMarges,
  useAnalyseFournisseurs,
  useMarginVarianceAnalysis
} from '../hooks/useFinanceStats';

import { formatCurrency, formatNumber } from '../utils/formatters';
import { Button } from './ui/Button';
import { Select } from './ui/Select';
import { Badge } from './shadcn/badge';
import { Loader2 } from 'lucide-react';

// Color palette
const COLORS = ['#10B981', '#3B82F6', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899', '#06B6D4', '#84CC16'];

// Format currency
const formatMoney = (value: number) => {
  if (value >= 1000000) {
    return `${(value / 1000000).toFixed(1)}M`;
  }
  if (value >= 1000) {
    return `${(value / 1000).toFixed(0)}k`;
  }
  return formatNumber(value);
};

const formatMoneyFull = (value: number) => {
  return formatCurrency(value);
};

// Stable formatter functions for Recharts (avoid inline functions that cause infinite re-renders)
const tooltipFormatterMoney = (value: number) => formatMoneyFull(value);
const tooltipFormatterPercent = (value: number, name: string) =>
  name === 'taux' ? `${value}%` : formatMoneyFull(value);
const tooltipFormatterOptional = (value: number) => value ? formatMoneyFull(value) : '-';
const pieLabelFormatter = ({ name, percent }: { name?: string; percent?: number }) =>
  `${String(name || '').substring(0, 10)}... ${((percent || 0) * 100).toFixed(0)}%`;

export default function ModuleFinancier() {
  const { t, i18n } = useTranslation(['finance', 'common', 'sidebar']);
  const [periode, setPeriode] = useState<'mois' | 'trimestre' | 'annee'>('mois');
  const [critereTop, setCritereTop] = useState<'ca' | 'marge'>('ca');
  const [repartitionBy, setRepartitionBy] = useState<'categorie' | 'fournisseur'>('categorie');
  const [activeChart, setActiveChart] = useState<'ca' | 'marges' | 'predictions'>('ca');
  const [categoryType, setCategoryType] = useState<'rayon' | 'groupe' | 'forme'>('rayon');

  // Fetch data
  const { data: caEvolution, isLoading: loadingCA } = useCAEvolution();
  const { data: margesData, isLoading: loadingMarges } = useMargesEvolution();
  const { data: predictions, isLoading: loadingPredictions } = usePredictions();
  const { data: kpis, isLoading: loadingKPIs } = useKPIs();
  const { data: topProducts, isLoading: loadingTop } = useTopProducts(periode, critereTop);
  const { data: repartition, isLoading: loadingRepartition } = useRepartitionCA(repartitionBy, periode);
  const { data: categoryAnalysis, isLoading: loadingCategories } = useAnalyseCategories(categoryType, periode);
  const { data: marginAnalysis, isLoading: loadingMarginAnalysis } = useAnalyseMarges();
  const { data: supplierAnalysis, isLoading: loadingSupplierAnalysis } = useAnalyseFournisseurs();
  const { data: varianceReport, isLoading: loadingVariance } = useMarginVarianceAnalysis();

  const isEnglish = i18n.language.startsWith('en');

  // Prepare chart data for CA Evolution
  const caChartData = useMemo(() => caEvolution?.labels.map((label, i) => ({
    name: label,
    current: caEvolution.data[i],
    n1: caEvolution.comparaison_n1[i]
  })) || [], [caEvolution]);

  // Prepare chart data for Margins
  const margesChartData = useMemo(() => margesData?.labels.map((label, i) => ({
    name: label,
    marge: margesData.marge_brute[i],
    taux: margesData.taux_marge[i]
  })) || [], [margesData]);

  // Prepare predictions chart data
  const predictionsChartData = useMemo(() => {
    if (!predictions) return [];
    return [
      ...(predictions.labels.map((label, i) => ({
        name: label,
        historique: predictions.historique[i],
        prediction: null as number | null
      }))),
      ...(predictions.prediction_labels.map((label, i) => ({
        name: label,
        historique: null as number | null,
        prediction: predictions.predictions[i]
      })))
    ];
  }, [predictions]);

  // Get trend icon and color (memoized to avoid infinite re-renders in Recharts)
  const trendInfo = useMemo(() => {
    if (!predictions) return null;
    switch (predictions.tendance) {
      case 'hausse':
        return { icon: '­ƒôê', color: 'text-emerald-500', label: t('trend.up', 'En hausse') };
      case 'baisse':
        return { icon: '­ƒôë', color: 'text-red-500', label: t('trend.down', 'En baisse') };
      default:
        return { icon: 'Ô×í´©Å', color: 'text-yellow-500', label: t('trend.stable', 'Stable') };
    }
  }, [predictions?.tendance, t]);

  // Memoize chart data to prevent infinite re-renders in Recharts
  const pieChartData = useMemo(() =>
    repartition?.data.map(item => ({ ...item, name: item.nom })) || [],
    [repartition]
  );

  const categoryChartData = useMemo(() =>
    categoryAnalysis?.data.slice(0, 10) || [],
    [categoryAnalysis]
  );

  const Recharts = useRecharts();
  if (!Recharts) return <div className="flex items-center justify-center p-8"><Loader2 className="size-8 animate-spin text-slate-400" /></div>;
  const { AreaChart, Area, LineChart, Line, BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } = Recharts;

  return (
    <div className="p-6 space-y-6">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-slate-800">
              {t('title', 'Module Financier')}
            </h1>
            <p className="text-slate-500">
              {t('subtitle', 'Analyse et pr├®dictions du chiffre d\'affaires')}
            </p>
          </div>
          <div className="flex gap-2">
            <Select
              size="sm"
              value={periode}
              onChange={(e) => setPeriode(e.target.value as 'mois' | 'trimestre' | 'annee')}
            >
              <option value="mois">{t('periode.mois', 'Ce mois')}</option>
              <option value="trimestre">{t('periode.trimestre', 'Ce trimestre')}</option>
              <option value="annee">{t('periode.annee', 'Cette ann├®e')}</option>
            </Select>
          </div>
        </div>
      {/* KPIs Cards */}
      {loadingKPIs ? (
        <div data-testid="finance-loading" className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="bg-white rounded-xl shadow-lg animate-pulse h-32"></div>
          ))}
        </div>
      ) : kpis && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {/* Panier Moyen */}
          <div className="rounded-xl bg-gradient-to-br from-emerald-500 to-emerald-600 text-white shadow-lg">
            <div className="p-4">
              <h3 className="text-sm font-medium opacity-80">
                {t('kpis.avg_basket', 'Panier Moyen')}
              </h3>
              <p className="text-3xl font-bold">{formatMoneyFull(kpis.panier_moyen.mois)}</p>
              <p className="text-xs text-white/70">
                {t('kpis.annual')}: {formatMoneyFull(kpis.panier_moyen.annee)}
              </p>
            </div>
          </div>

          {/* Taux de Marge */}
          <div className="rounded-xl bg-gradient-to-br from-blue-500 to-blue-600 text-white shadow-lg">
            <div className="p-4">
              <h3 className="text-sm font-medium opacity-80">
                {t('kpis.margin_rate', 'Taux de Marge')}
              </h3>
              <p className="text-3xl font-bold">{kpis.taux_marge}%</p>
              <p className="text-xs text-white/70">
                {kpis.nb_ventes_mois} {t('charts.sales_count', 'ventes ce mois')}
              </p>
            </div>
          </div>

          {/* DSI */}
          <div className="rounded-xl bg-gradient-to-br from-purple-500 to-purple-600 text-white shadow-lg">
            <div className="p-4">
              <h3 className="text-sm font-medium opacity-80">
                {t('kpis.dsi', 'Jours Stock (DSI)')}
              </h3>
              <p className="text-3xl font-bold">{kpis.dsi} j</p>
              <p className="text-xs text-white/70">
                Stock: {formatMoneyFull(kpis.stock_value)}
              </p>
            </div>
          </div>

          {/* Croissance */}
          <div className={`rounded-xl shadow-lg ${kpis.croissance_mensuelle >= 0
            ? 'bg-gradient-to-br from-emerald-500 to-emerald-600'
            : 'bg-gradient-to-br from-red-500 to-red-600'} text-white`}>
            <div className="p-4">
              <h3 className="text-sm font-medium opacity-80">
                {t('kpis.growth', 'Croissance Mensuelle')}
              </h3>
              <p className="text-3xl font-bold">
                {kpis.croissance_mensuelle >= 0 ? '+' : ''}{kpis.croissance_mensuelle}%
              </p>
              <p className="text-xs text-white/70">
                CA: {formatMoneyFull(kpis.ca_mois)}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Margin Variance Report (NEW) */}
      <div className="bg-white rounded-xl shadow-xl border-t-4 border-indigo-500 overflow-hidden">
        <div className="p-0">
          <div className="bg-indigo-50 p-4 flex items-center justify-between">
            <div>
              <h2 className="text-xl font-bold flex items-center gap-2">
                <span className="text-2xl">­ƒôè</span>
                {isEnglish ? 'Margin Variance Report' : 'Rapport de Variation de Marge'}
              </h2>
              <p className="text-sm text-slate-500">
                {isEnglish ? 'Analysis of profit fluctuations and data integrity' : 'Analyse des fluctuations de profit et int├®grit├® des donn├®es'}
              </p>
            </div>
            {varianceReport && (
              <div className={`px-4 py-2 rounded-lg font-bold text-lg ${varianceReport.variance_pct >= 0 ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'}`}>
                {varianceReport.variance_pct >= 0 ? '+' : ''}{varianceReport.variance_pct}%
              </div>
            )}
          </div>

          {loadingVariance ? (
            <div className="p-8 flex justify-center"><Loader2 className="size-8 animate-spin text-slate-400" /></div>
          ) : varianceReport && (
            <div className="p-6 grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Left: Summary & Insights */}
              <div className="space-y-6">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-100 rounded-xl">
                    <p className="text-xs uppercase font-bold text-slate-400 mb-1">{isEnglish ? 'Current Period' : 'P├®riode Actuelle'}</p>
                    <p className="text-2xl font-black">{Number(varianceReport?.period1?.stats?.margin_pct || 0).toFixed(1)}%</p>
                    <p className="text-xs text-slate-500">{formatMoney(Number(varianceReport?.period1?.stats?.margin || 0))} {isEnglish ? 'Profit' : 'Marge'}</p>
                  </div>
                  <div className="p-4 bg-slate-100 rounded-xl">
                    <p className="text-xs uppercase font-bold text-slate-400 mb-1">{isEnglish ? 'Baseline' : 'R├®f├®rence (Hier)'}</p>
                    <p className="text-2xl font-black">{Number(varianceReport?.period2?.stats?.margin_pct || 0).toFixed(1)}%</p>
                    <p className="text-xs text-slate-500">{formatMoney(Number(varianceReport?.period2?.stats?.margin || 0))} {isEnglish ? 'Profit' : 'Marge'}</p>
                  </div>
                </div>

                <div className="space-y-3">
                  <h3 className="font-bold text-sm uppercase tracking-wider text-slate-400">{isEnglish ? 'Key Insights' : 'Analyses Cl├®s'}</h3>
                  {varianceReport.insights.map((insight) => {
                    const text = isEnglish ? insight.en : insight.fr;
                    return (
                      <div key={insight.en ?? insight.fr} className="flex items-start gap-2 p-3 rounded-lg bg-blue-50 border border-blue-200 text-sm text-slate-700">
                        <span>{text}</span>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Right: Suspicious Products */}
              <div className="bg-slate-100/50 rounded-2xl p-4 border border-slate-200">
                <h3 className="font-bold text-sm uppercase tracking-wider text-slate-400 mb-4 flex items-center gap-2">
                  <span className="text-amber-600">­ƒÜ®</span>
                  {isEnglish ? 'Atypical Margins Detected' : 'Marges Atypiques D├®tect├®es'}
                </h3>
                
                {varianceReport.suspicious_products.length > 0 ? (
                  <div className="overflow-x-auto">
                    <table className="w-full text-xs">
                      <thead>
                        <tr className="text-slate-400">
                          <th className="text-left py-1">{isEnglish ? 'Product' : 'Produit'}</th>
                          <th className="text-right py-1">{isEnglish ? 'Margin' : 'Marge'}</th>
                          <th className="text-right py-1">{isEnglish ? 'Cost (PMP)' : 'Co├╗t (PMP)'}</th>
                        </tr>
                      </thead>
                      <tbody>
                        {varianceReport.suspicious_products.map((p, idx) => {
                          const productId = p?.produit__id || p?.id || `prod-${idx}`;
                          const productName = typeof p?.produit__name === 'string' ? p.produit__name : 
                                            typeof p?.nom === 'string' ? p.nom : 'Produit inconnu';
                          const marginPct = typeof p?.unit_margin_pct === 'number' ? p.unit_margin_pct : 
                                          typeof p?.unit_margin_pct === 'string' ? parseFloat(p.unit_margin_pct) : 0;
                          const pmp = typeof p?.produit__pmp === 'number' ? p.produit__pmp : 
                                    typeof p?.produit__pmp === 'string' ? parseFloat(p.produit__pmp) : 0;
                          return (
                            <tr key={productId} className="hover:bg-slate-200/50 transition-colors border-b border-slate-200">
                              <td className="font-medium max-w-[150px] truncate py-1">{String(productName)}</td>
                              <td className={`text-right font-bold py-1 ${marginPct > 80 ? 'text-purple-500' : 'text-orange-500'}`}>
                                {marginPct.toFixed(1)}%
                              </td>
                              <td className="text-right text-slate-500 py-1">{formatMoney(pmp)}</td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                    <p className="text-[10px] mt-4 italic text-slate-400">
                      {isEnglish 
                        ? '* High margins (>80%) often indicate missing cost prices (PMP = 0).' 
                        : '* Les marges ├®lev├®es (>80%) indiquent souvent des prix d\'achat manquants (PMP = 0).'}
                    </p>
                  </div>
                ) : (
                  <div className="h-40 flex items-center justify-center text-sm text-slate-400 italic">
                    {isEnglish ? 'No abnormal margins detected today.' : 'Aucune marge anormale d├®tect├®e aujourd\'hui.'}
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Main Charts */}
      <div className="bg-white rounded-xl shadow-lg">
        <div className="p-6">
          {/* Chart Tabs */}
          <div className="inline-flex bg-slate-100 p-1 rounded-lg mb-4 w-fit gap-1">
            <Button 
              variant="ghost" size="sm"
              className={`rounded-md ${activeChart === 'ca' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}
              onClick={() => setActiveChart('ca')}
            >
              {t('charts.ca_evolution', '├ëvolution CA')}
            </Button>
            <Button 
              variant="ghost" size="sm"
              className={`rounded-md ${activeChart === 'marges' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}
              onClick={() => setActiveChart('marges')}
            >
              {t('charts.margins', 'Marges')}
            </Button>
            <Button 
              variant="ghost" size="sm"
              className={`rounded-md ${activeChart === 'predictions' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}
              onClick={() => setActiveChart('predictions')}
            >
              {t('charts.predictions', 'Pr├®dictions')} {trendInfo && <span className="ml-1">{trendInfo.icon}</span>}
            </Button>
          </div>

          {/* CA Evolution Chart */}
          {activeChart === 'ca' && (
            <div>
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold">
                  {t('charts.ca_12_months', 'Chiffre d\'Affaires (12 derniers mois)')}
                </h3>
                {caEvolution && (
                  <Badge variant={caEvolution.croissance_yoy >= 0 ? 'default' : 'destructive'} className="text-sm">
                    {caEvolution.croissance_yoy >= 0 ? '+' : ''}{caEvolution.croissance_yoy}% vs N-1
                  </Badge>
                )}
              </div>
              {loadingCA ? (
                <div className="h-80 flex items-center justify-center">
                  <Loader2 className="size-8 animate-spin text-slate-400" />
                </div>
              ) : (
                <ResponsiveContainer width="100%" height={350}>
                  <AreaChart data={caChartData}>
                    <defs>
                      <linearGradient id="colorCurrent" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#10B981" stopOpacity={0.3}/>
                        <stop offset="95%" stopColor="#10B981" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" opacity={0.3} />
                    <XAxis dataKey="name" fontSize={12} />
                    <YAxis tickFormatter={formatMoney} fontSize={12} />
                    <Tooltip formatter={tooltipFormatterMoney} />
                    <Legend />
                    <Area
                      type="monotone"
                      dataKey="current"
