  }
}

const toLocalISODate = (date: Date) => {
  const y = date.getFullYear()
  const m = String(date.getMonth() + 1).padStart(2, '0')
  const d = String(date.getDate()).padStart(2, '0')
  return `${y}-${m}-${d}`
}

const getExpiryEndOfMonthISO = (dateString: string) => {
  const [datePart] = dateString.split('T')
  const [yStr, mStr] = datePart.split('-')
  const y = Number(yStr)
  const m = Number(mStr)
  if (!y || !m) return null
  const lastDay = new Date(y, m, 0).getDate()
  return `${yStr}-${mStr}-${String(lastDay).padStart(2, '0')}`
}

const _formatDateShort = (dateString: string) => {
  if (!dateString) return '-'
  const [datePart] = dateString.split('T')
  const [, m, y] = datePart.split('-')
  if (!m || !y) return dateString
  return `${m}/${y.slice(-2)}`
}

const getUrgencyClass = (valeur: number) => {
  if (valeur > 500000) return 'border-red-400 bg-red-50'
  if (valeur > 100000) return 'border-amber-400 bg-amber-50'
  return 'border-emerald-400 bg-emerald-50'
}

const isExpiredByEndOfMonth = (dateString: string) => {
  if (!dateString) return false
  const expiryEom = getExpiryEndOfMonthISO(dateString)
  if (!expiryEom) return false
  const todayStr = toLocalISODate(new Date())
  return expiryEom < todayStr
}

export default function Perimes() {
  const { t } = useTranslation(['stock', 'common'])
  const [lots, setLots] = useState<StockLot[]>([])
  const [stats, setStats] = useState<PerimesStats | null>(null)
  const [loading, setLoading] = useState(false)
  const [loadingStats, setLoadingStats] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [filterDays, setFilterDays] = useState<number>(30)
  const [showExpiredOnly, setShowExpiredOnly] = useState<boolean>(true)
  const [selectedLotIds, setSelectedLotIds] = useState<Set<number>>(new Set())
  const [adjustments, setAdjustments] = useState<StockAdjustment[]>([])
  const [loadingAdjustments, setLoadingAdjustments] = useState(false)
  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'history'>('dashboard')
  
  const [dateDebut, setDateDebut] = useState<string>(() => {
    const d = new Date()
    d.setMonth(d.getMonth() - 1)
    return d.toISOString().split('T')[0]
  })
  const [dateFin, setDateFin] = useState<string>(() => new Date().toISOString().split('T')[0])

  const { sudoState, requireSudo, closeSudo } = useSudo()
  const [processing, setProcessing] = useState(false)



  useEffect(() => {
    fetchStats()
    fetchLots()
    fetchAdjustments()
  }, [])

  useEffect(() => {
    if (activeTab === 'list') {
      fetchLots()
    } else if (activeTab === 'history') {
      fetchAdjustments()
    }
  }, [filterDays, showExpiredOnly, activeTab, dateDebut, dateFin])

  const fetchStats = async () => {
    setLoadingStats(true)
    try {
      const response = await api.get<PerimesStats>('stock-lots/stats_perimes/')
      setStats(response.data)
    } catch (err) {
      console.error('Erreur chargement stats:', err)
      toast.error(t('perimes.messages.error_stats'))
    } finally {
      setLoadingStats(false)
    }
  }

  const fetchAdjustments = async () => {
    setLoadingAdjustments(true)
    try {
      const response = await api.get('stock-adjustments/', {
        params: {
          reason_type: 'PERIME',
          created_at__date__gte: dateDebut,
          created_at__date__lte: dateFin,
          limit: 100
        }
      })
      const data: unknown = response.data
      setAdjustments(Array.isArray(data) ? data : (data.results || []))
    } catch (err) {
      console.error('Erreur chargement historiques:', err)
      toast.error(t('perimes.messages.error_history'))
    } finally {
      setLoadingAdjustments(false)
    }
  }

  const fetchLots = async () => {
    setLoading(true)
    setError(null)
    setSelectedLotIds(new Set()) // Reset selection on refresh
    try {
      const today = new Date()
      const thresholdDate = new Date()
      thresholdDate.setDate(today.getDate() + filterDays)

      const dateStr = toLocalISODate(thresholdDate)
      
      const response = await api.get<StockLot[]>('stock-lots/', {
        params: {
          date_expiration_lte: dateStr,
          include_empty: 'false' // Hide depleted lots as they are redundant in the list view (available in History)
        }
      })
      
      const data: unknown = response.data
      let fetchedLots: StockLot[] = Array.isArray(data) ? data : (data.results || [])
      
      if (showExpiredOnly) {
         fetchedLots = fetchedLots.filter(l => !!l.date_expiration && isExpiredByEndOfMonth(l.date_expiration))
      }
      
      setLots(fetchedLots)
    } catch (err) {
      console.error('Erreur chargement lots:', err)
      setError(t('perimes.messages.error_loading'))
    } finally {
      setLoading(false)
    }
  }

  const handleSortirStock = async (lot: StockLot) => {
    const quantity = prompt(t('perimes.prompt.qty', { lot: lot.lot, max: lot.quantity_remaining }), String(lot.quantity_remaining))
    
    if (!quantity) return
    
    const qty = parseInt(quantity, 10)
    if (isNaN(qty) || qty <= 0 || qty > lot.quantity_remaining) {
      toast.error(t('perimes.messages.invalid_qty'))
      return
    }

    requireSudo(async (validatorId, password) => {
      try {
        setProcessing(true)
        await api.post(`stock-lots/${lot.id}/sortir_perimes/`, {
          quantity: qty,
          reason: t('stock:ajustements.filters.reasons.PERIME') + ' / ' + t('stock:ajustements.filters.reasons.AVARIE'),
          validated_by_id: validatorId,
          sudo_password: password
        })
        toast.success(t('perimes.messages.success_exit'))
        fetchLots()
        fetchStats() 
      } catch (err) {
        console.error('Erreur sortie stock:', err);
        toast.error(t('perimes.messages.error_exit') + ': ' + getApiErrorDetail(err, 'Erreur inconnue'))
        throw err;
      } finally {
        setProcessing(false)
      }
    }, {
      title: t('perimes.confirm.exit_title'),
      message: t('perimes.confirm.exit_message', { qty, product: lot.produit_nom, lot: lot.lot })
    });
  }

  const handleBulkSortir = async () => {
      if (selectedLotIds.size === 0) return

      requireSudo(async (validatorId, password) => {
          try {
              setProcessing(true)
              await api.post('stock-lots/bulk_sortir_perimes/', {
                  lot_ids: Array.from(selectedLotIds),
                  reason: t('stock:perimes.confirm.bulk_exit_title'),
                  validated_by_id: validatorId,
                  sudo_password: password
              })
              toast.success(t('perimes.messages.success_bulk_exit', { count: selectedLotIds.size }))
              fetchLots()
              fetchStats()
          } catch (err) {
              console.error('Erreur sortie group├®e:', err)
              toast.error(getApiErrorDetail(err, t('perimes.messages.error_bulk_exit')))
              throw err;
          } finally {
              setProcessing(false)
          }
      }, {
          title: t('perimes.confirm.bulk_exit_title'),
          message: t('perimes.confirm.bulk_exit_message', { count: selectedLotIds.size })
      })
  }

  const toggleLotSelection = (id: number) => {
      setSelectedLotIds(prev => {
          const newSet = new Set(prev);
          if (newSet.has(id)) {
              newSet.delete(id);
          } else {
              newSet.add(id);
          }
          return newSet;
      });
  }

  const toggleAllSelection = () => {
      const availableLots = lots.filter(l => l.quantity_remaining > 0);
      if (selectedLotIds.size === availableLots.length) {
          setSelectedLotIds(new Set())
      } else {
          setSelectedLotIds(new Set(availableLots.map(l => l.id)))
      }
  }

  const { printWithTemplate } = usePrint()

  const handlePrintHistory = () => {
    if (adjustments.length === 0) return

    const totalVal = adjustments.reduce((sum, adj) => sum + (adj.valorisation || 0), 0)

    const content = `
      <div style="font-family: Arial, sans-serif; color: #333;">
        <h3 style="text-align: center; border-bottom: 2px solid #333; padding-bottom: 10px;">${t('stock:perimes.history.title')}</h3>
        <p style="text-align: center; font-size: 0.9em; margin-bottom: 20px;">
          ${t('common:period')}: ${formatDate(dateDebut)} ${t('common:to').toLowerCase()} ${formatDate(dateFin)}
        </p>
        
        <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px; font-size: 0.85em;">
          <thead>
            <tr style="background-color: #f3f4f6;">
              <th style="border: 1px solid #ddd; padding: 8px; text-align: left;">${t('stock:perimes.history.table.date')}</th>
              <th style="border: 1px solid #ddd; padding: 8px; text-align: left;">${t('stock:perimes.history.table.product')}</th>
              <th style="border: 1px solid #ddd; padding: 8px; text-align: left;">${t('stock:perimes.history.table.lot')}</th>
              <th style="border: 1px solid #ddd; padding: 8px; text-align: right;">${t('stock:perimes.history.table.qty')}</th>
              <th style="border: 1px solid #ddd; padding: 8px; text-align: right;">${t('stock:perimes.history.table.value')}</th>
            </tr>
          </thead>
          <tbody>
            ${adjustments.map(adj => `
              <tr>
                <td style="border: 1px solid #ddd; padding: 8px;">${formatDate(adj.created_at)}</td>
                <td style="border: 1px solid #ddd; padding: 8px;">${adj.produit_name}</td>
                <td style="border: 1px solid #ddd; padding: 8px;">${adj.lot_number || '-'}</td>
                <td style="border: 1px solid #ddd; padding: 8px; text-align: right;">${Math.abs(adj.quantity_change)}</td>
                <td style="border: 1px solid #ddd; padding: 8px; text-align: right; font-weight: bold;">${formatCurrency(adj.valorisation)}</td>
              </tr>
            `).join('')}
          </tbody>
          <tfoot>
            <tr style="background-color: #f9fafb; font-weight: bold;">
              <td colspan="4" style="border: 1px solid #ddd; padding: 8px; text-align: right;">${t('stock:perimes.history.total_valorization').toUpperCase()}</td>
              <td style="border: 1px solid #ddd; padding: 8px; text-align: right; color: #dc2626;">${formatCurrency(totalVal)}</td>
            </tr>
          </tfoot>
        </table>
        
        <div style="text-align: right; font-size: 0.8em; margin-top: 30px;">
          <p>${t('stock:perimes.history_print_generated')} ${new Date().toLocaleString()}</p>
        </div>
      </div>
    `

    printWithTemplate(content, { title: t('stock:perimes.history.title'), width: 800 })
  }

  const handleExportExcel = () => {
    const baseUrl = (import.meta.env.VITE_API_BASE_URL || '').replace(/\/$/, '')
    window.open(`${baseUrl}/api/stock-adjustments/export_excel/?reason_type=PERIME&created_at__date__gte=${dateDebut}&created_at__date__lte=${dateFin}`, '_blank')
  }

  return (
    <div className="h-full flex flex-col bg-slate-50 overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200/60 bg-white/80 backdrop-blur-md sticky top-0 z-30 shrink-0">
        <div className="flex items-center gap-4">
          <div className="p-2.5 bg-red-50 text-red-500 rounded-xl">
            <AlertTriangle className="size-6" />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight text-slate-800">{t('perimes.title')}</h1>
            <p className="text-[11px] font-medium text-slate-400 uppercase tracking-widest">{t('perimes.subtitle')}</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as typeof activeTab)}>
            <TabsList className="bg-slate-100">
              <TabsTrigger value="dashboard" className="gap-1.5 text-xs">
                <BarChart2 className="size-3.5" />
                <span className="hidden sm:inline font-semibold">{t('perimes.tabs.dashboard')}</span>
              </TabsTrigger>
              <TabsTrigger value="list" className="gap-1.5 text-xs">
                <List className="size-3.5" />
                <span className="hidden sm:inline font-semibold">{t('perimes.tabs.list')}</span>
              </TabsTrigger>
              <TabsTrigger value="history" className="gap-1.5 text-xs">
                <History className="size-3.5" />
                <span className="hidden sm:inline font-semibold">{t('perimes.tabs.history')}</span>
              </TabsTrigger>
            </TabsList>
          </Tabs>
          <Button
            variant="outline"
            size="sm"
            onClick={() => { fetchLots(); fetchStats() }}
            disabled={loading || loadingStats}
            className="gap-2"
          >
            <RefreshCw className={cn("size-4", (loading || loadingStats) && "animate-spin")} />
            <span className="hidden sm:inline">{t('common:refresh')}</span>
          </Button>
        </div>
      </div>

      {error && (
        <div className="px-6 pt-4 shrink-0">
          <div role="alert" className="p-3 rounded-xl bg-red-50 border border-red-200 text-red-700 flex items-start gap-2 text-sm font-medium">
            <AlertTriangle className="size-5 shrink-0 mt-0.5" />
            <span>{error}</span>
          </div>
        </div>
      )}

      {/* Content */}
      <div className="flex-1 overflow-auto px-6 py-4">
        {activeTab === 'dashboard' ? (
          /* ========== DASHBOARD VIEW ========== */
          <div className="space-y-6">
            {/* KPI Cards Row */}
            {loadingStats ? (
              <div className="flex items-center justify-center py-12">
                <span className="size-8 border-2 border-slate-200 border-t-red-500 rounded-full animate-spin"></span>
              </div>
            ) : stats ? (
              <>
                {/* Main KPIs */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <Card className="bg-gradient-to-br from-red-50 to-red-50/40 border-red-200">
                    <CardContent className="p-5">
                      <div className="flex items-center gap-3">
                        <div className="size-12 rounded-full bg-red-100 flex items-center justify-center text-2xl">­ƒÆ©</div>
                        <div>
                          <p className="text-sm text-slate-500">{t('perimes.stats.valeur_perimes')}</p>
                          <p className="text-2xl font-bold text-red-600">{formatCurrency(stats.perimes.valeur_cout)}</p>
                          <p className="text-xs text-slate-400">{t('perimes.stats.lots_count', { count: stats.perimes.count_lots })}</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>

                  <Card className="bg-gradient-to-br from-amber-50 to-amber-50/40 border-amber-200">
                    <CardContent className="p-5">
                      <div className="flex items-center gap-3">
                        <div className="size-12 rounded-full bg-amber-100 flex items-center justify-center text-2xl">­ƒôë</div>
                        <div>
                          <p className="text-sm text-slate-500">{t('perimes.stats.manque_gagner')}</p>
                          <p className="text-2xl font-bold text-amber-600">{formatCurrency(stats.perimes.valeur_vente_perdue)}</p>
                          <p className="text-xs text-slate-400">{t('perimes.stats.at_sale_price')}</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>

                  <Card className="bg-gradient-to-br from-blue-50 to-blue-50/40 border-blue-200">
                    <CardContent className="p-5">
                      <div className="flex items-center gap-3">
                        <div className="size-12 rounded-full bg-blue-100 flex items-center justify-center text-2xl">­ƒôè</div>
                        <div>
                          <p className="text-sm text-slate-500">{t('perimes.stats.taux_perte')}</p>
                          <p className="text-2xl font-bold text-blue-600">{stats.indicateurs.taux_perte_pct}%</p>
                          <p className="text-xs text-slate-400">{t('perimes.stats.vs_ca')} ({formatCurrency(stats.indicateurs.ca_periode)})</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </div>

                {/* Pr├®visions Section */}
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">ÔÅ░ {t('perimes.prevision.title')}</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      {(['30j', '60j', '90j'] as const).map((key, i) => (
                        <div key={key} className={cn("border-2 rounded-xl p-4", getUrgencyClass(stats.previsions[key].valeur_vente))}>
                          <div className="flex items-center justify-between mb-2">
                            <span className="font-bold text-slate-700">{t('common:count_days', { count: [30, 60, 90][i] })}</span>
                            <Badge variant="outline" className="bg-white/80 text-slate-600">{t('perimes.prevision.lots_count', { count: stats.previsions[key].count_lots })}</Badge>
                          </div>
                          <p className="text-xl font-bold text-slate-800">{formatCurrency(stats.previsions[key].valeur_vente)}</p>
                          <p className="text-xs text-slate-500 mt-1">{t('perimes.prevision.potential_risk')}</p>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>

                {/* Top Produits P├®rim├®s */}
                {stats.perimes.details.length > 0 && (
                  <Card className="overflow-hidden">
                    <CardHeader>
                      <CardTitle className="text-lg">­ƒÜ¿ {t('perimes.top_perimes')}</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="overflow-x-auto">
                        <Table className="w-full text-sm">
                          <TableHeader>
                            <TableRow className="bg-slate-50 hover:bg-slate-50">
                              <TableHead className="text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.table.product')}</TableHead>
                              <TableHead className="text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.table.lot')}</TableHead>
                              <TableHead className="text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.table.expiration')}</TableHead>
                              <TableHead className="text-right px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.table.qty')}</TableHead>
                              <TableHead className="text-right px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.table.value_cost')}</TableHead>
                              <TableHead className="text-right px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.table.value_sale')}</TableHead>
                            </TableRow>
                          </TableHeader>
                          <TableBody>
                            {stats.perimes.details.slice(0, 10).map((item) => (
                              <TableRow key={item.lot_id} className="hover:bg-slate-50 transition-colors">
                                <TableCell className="font-medium px-4 py-2.5 text-slate-700">{item.produit_nom}</TableCell>
                                <TableCell className="font-mono text-xs px-4 py-2.5 text-slate-500">{item.lot_numero || '-'}</TableCell>
                                <TableCell className="px-4 py-2.5">
                                  <Badge variant="outline" className="bg-red-50 text-red-500 border-red-200">{item.date_expiration ? formatDate(item.date_expiration) : '-'}</Badge>
                                </TableCell>
                                <TableCell className="text-right font-bold px-4 py-2.5 text-slate-700">{item.quantity}</TableCell>
                                <TableCell className="text-right px-4 py-2.5 text-red-500 font-medium">{formatCurrency(item.valeur_cout)}</TableCell>
                                <TableCell className="text-right px-4 py-2.5 text-amber-600 font-medium">{formatCurrency(item.valeur_vente)}</TableCell>
                              </TableRow>
                            ))}
                          </TableBody>
                        </Table>
                      </div>
                      {stats.perimes.details.length > 10 && (
                        <div className="mt-3 text-center">
                          <Button variant="link" size="sm" onClick={() => setActiveTab('list')}>
                            Voir tous les {stats.perimes.count_lots} lots ÔåÆ
                          </Button>
                        </div>
                      )}
                    </CardContent>
                  </Card>
                )}
              </>
            ) : (
              <div className="text-center py-12 text-slate-400">
                <p>{t('stock:perimes.no_data')}</p>
              </div>
            )}
          </div>
        ) : activeTab === 'list' ? (
          /* ========== LIST VIEW ========== */
          <div className="flex flex-col h-full bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-4 border-b border-slate-100 bg-white sticky top-0 z-20 shrink-0">
               <div className="flex justify-between items-center h-10">
                  {selectedLotIds.size > 0 ? (
                     <div className="flex items-center gap-2">
                       <DropdownMenu>
                         <DropdownMenuTrigger asChild>
                           <Button variant="destructive" size="sm" className="gap-2">
                             <MoreVertical className="size-4" />
                             {t('common:actions_title')}
                             <Badge variant="destructive" className="bg-red-500">{selectedLotIds.size}</Badge>
                           </Button>
                         </DropdownMenuTrigger>
                         <DropdownMenuContent align="start" className="w-48">
                           <DropdownMenuLabel>{t('common:bulk_actions')}</DropdownMenuLabel>
                           <DropdownMenuSeparator />
                           <DropdownMenuItem onClick={handleBulkSortir} className="text-red-500 focus:bg-red-50 focus:text-red-600">
                             <Trash2 className="size-4 mr-2" /> {t('perimes.table.exit_btn')}
                           </DropdownMenuItem>
                         </DropdownMenuContent>
                       </DropdownMenu>
                       <Button
                         variant="ghost"
                         size="sm"
                         onClick={() => setSelectedLotIds(new Set())}
                         className="gap-2"
                       >
                         <X className="size-4" />
                         {t('common:cancel')}
                       </Button>
                     </div>
                  ) : (
                     <>
                        <div className="flex items-center gap-2">
                           <div className="p-2 bg-red-50 text-red-500 rounded-lg"><AlertTriangle className="size-5" /></div>
                           <h2 className="font-bold text-lg tracking-tight text-slate-800">{t('perimes.risk_lots')}</h2>
                           <Badge variant="secondary" className="bg-slate-100 text-slate-500">{lots.length}</Badge>
                        </div>
                        <div className="flex gap-3 items-center">
                           <div className="flex items-center gap-2 bg-slate-50 p-1 px-3 rounded-xl border border-slate-200">
                             <span className="text-[10px] font-bold text-slate-400 uppercase">{t('common:filters')}</span>
                             <div className="h-4 w-px bg-slate-200 mx-1"></div>
                             <label className="flex items-center gap-2 cursor-pointer">
                               <Checkbox
                                 checked={showExpiredOnly}
                                 onCheckedChange={(checked) => setShowExpiredOnly(checked === true)}
                                 className="data-[state=checked]:bg-red-500 data-[state=checked]:border-red-500"
                               />
                               <span className="text-[11px] font-semibold text-slate-500">{t('stock:perimes.show_expired_only')}</span>
                             </label>
                             {!showExpiredOnly && (
                               <select
                                 className="rounded-lg border border-slate-200 bg-white h-7 px-2 text-[11px] font-bold text-slate-700 focus:outline-none focus:border-red-400 transition-all"
                                 value={filterDays}
                                 onChange={(e) => setFilterDays(parseInt(e.target.value))}
                               >
                                 <option value={30}>{t('common:count_days', { count: 30 })}</option>
                                 <option value={60}>{t('common:count_days', { count: 60 })}</option>
                                 <option value={90}>{t('common:count_days', { count: 90 })}</option>
                                 <option value={180}>{t('common:count_days', { count: 180 })}</option>
                               </select>
                             )}
                           </div>
                        </div>
                     </>
                  )}
               </div>
            </div>

            <div className="flex-1 overflow-auto">
              {loading ? (
                <div className="flex items-center justify-center h-64">
                  <span className="size-8 border-2 border-slate-200 border-t-red-500 rounded-full animate-spin"></span>
                </div>
              ) : lots.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-64 text-slate-300 gap-4">
                  <PieChart className="size-16" />
                  <p className="text-sm font-bold uppercase tracking-widest text-slate-400">{t('perimes.no_result')}</p>
                </div>
              ) : (
                <Table className="w-full text-xs">
                  <TableHeader className="bg-slate-50 sticky top-0 z-30 border-b border-slate-100">
                    <TableRow className="text-slate-400 uppercase text-[10px] tracking-widest font-black hover:bg-slate-50">
                      <TableHead className="py-3 px-4 w-12 text-center">
                        <Checkbox
                          checked={selectedLotIds.size === lots.filter(l => l.quantity_remaining > 0).length && lots.filter(l => l.quantity_remaining > 0).length > 0}
                          onCheckedChange={toggleAllSelection}
                          className="data-[state=checked]:bg-red-500 data-[state=checked]:border-red-500"
                        />
                      </TableHead>
                      <TableHead className="py-3 px-4 text-left">{t('perimes.table.product')}</TableHead>
                      <TableHead className="py-3 px-4 text-center">{t('perimes.table.lot')}</TableHead>
                      <TableHead className="py-3 px-4 text-center">{t('perimes.table.expiration')}</TableHead>
                      <TableHead className="py-3 px-4 text-left">{t('perimes.table.provider')}</TableHead>
                      <TableHead className="py-3 px-4 text-right">{t('perimes.table.stock')}</TableHead>
                      <TableHead className="py-3 px-4 text-right">{t('perimes.table.value')}</TableHead>
                      <TableHead className="py-3 px-4 text-center">{t('perimes.table.actions')}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {lots.map((lot) => (
                      <TableRow key={lot.id} className={cn("hover:bg-slate-50 transition-colors group", lot.quantity_remaining <= 0 && 'opacity-50', selectedLotIds.has(lot.id) && 'bg-red-50/40')}>
                        <TableCell className="py-2.5 px-4 text-center">
                          <Checkbox
                            checked={selectedLotIds.has(lot.id)}
                            onCheckedChange={() => toggleLotSelection(lot.id)}
                            disabled={lot.quantity_remaining <= 0}
                            className="data-[state=checked]:bg-red-500 data-[state=checked]:border-red-500"
                          />
                        </TableCell>
                        <TableCell className="py-2.5 px-4">
                          <div className="font-bold text-sm text-slate-800">{lot.produit_nom}</div>
                          <div className="text-[10px] font-mono text-slate-400">#{lot.produit}</div>
                        </TableCell>
                        <TableCell className="py-2.5 px-4 text-center font-mono text-[11px] font-bold text-slate-500">
                          {lot.lot || '-'}
                        </TableCell>
                        <TableCell className="py-2.5 px-4 text-center">
                          <Badge variant="outline" className={cn("gap-1.5", lot.date_expiration && isExpiredByEndOfMonth(lot.date_expiration) ? 'bg-red-50 text-red-500 border-red-200' : 'bg-amber-50 text-amber-600 border-amber-200')}>
                            <Calendar className="size-3" />
                            {formatDate(lot.date_expiration || '')}
                          </Badge>
                        </TableCell>
                        <TableCell className="py-2.5 px-4 text-xs font-semibold text-slate-500 truncate max-w-[140px]" title={lot.fournisseur_nom}>
                          {lot.fournisseur_nom}
                        </TableCell>
                        <TableCell className="py-2.5 px-4 text-right">
                          <div className={cn("font-black text-sm", lot.quantity_remaining > 0 ? 'text-slate-800' : 'text-slate-300')}>
                            {lot.quantity_remaining}
                          </div>
                        </TableCell>
                        <TableCell className="py-2.5 px-4 text-right text-red-500 font-mono font-black text-xs">
                          {formatCurrency(Number(lot.price_cost || 0) * lot.quantity_remaining)}
                        </TableCell>
                        <TableCell className="py-2.5 px-4 text-center">
                          {lot.quantity_remaining > 0 ? (
                            <Button
                              variant="outline"
                              size="sm"
                              className="gap-1 border-red-200 bg-red-50 text-red-500 hover:bg-red-100 opacity-0 group-hover:opacity-100"
                              onClick={() => handleSortirStock(lot)}
                              disabled={processing}
                            >
                              <Trash2 className="size-3.5" />
                              {t('perimes.table.exit_btn')}
                            </Button>
                          ) : (
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center justify-center gap-1">
                              <Check className="size-3" />
                              {t('perimes.table.sorti')}
                            </span>
                          )}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </div>
          </div>
        ) : (
          /* ========== HISTORY VIEW ========== */
          <div className="space-y-4">
             <div className="flex flex-wrap gap-4 items-center justify-between bg-slate-50 p-4 rounded-xl border border-slate-200">
                <div className="flex flex-wrap gap-4 items-center">
                    <div className="flex flex-col gap-1">
                        <span className="text-[10px] font-bold text-slate-400 uppercase pl-1">{t('common:from')}</span>
                        <Input
                            type="date"
                            className="h-9 w-auto"
                            value={dateDebut}
                            onChange={(e) => setDateDebut(e.target.value)}
                        />
                    </div>
                    <div className="flex flex-col gap-1">
                        <span className="text-[10px] font-bold text-slate-400 uppercase pl-1">{t('common:to')}</span>
                        <Input
                            type="date"
                            className="h-9 w-auto"
                            value={dateFin}
                            onChange={(e) => setDateFin(e.target.value)}
                        />
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={handlePrintHistory}
                        disabled={adjustments.length === 0}
                        className="gap-2"
                    >
                        <Printer className="size-4" />
                        {t('perimes.history.print')}
                    </Button>
                    <Button
                        variant="default"
                        size="sm"
                        onClick={handleExportExcel}
                        disabled={adjustments.length === 0}
                        className="gap-2"
                    >
                        <FileSpreadsheet className="size-4" />
                        {t('perimes.history.excel')}
                    </Button>
                </div>
             </div>

             {adjustments.length > 0 && (
               <Card>
                 <CardContent className="p-4">
                   <div className="text-xs font-bold uppercase text-slate-400">{t('perimes.history.total_valorization')}</div>
                   <div className="text-red-500 text-2xl font-bold">
                     {formatCurrency(adjustments.reduce((sum, a) => sum + (a.valorisation || 0), 0))}
                   </div>
                   <div className="text-sm font-medium text-slate-400">{t('perimes.history.operations_count', { count: adjustments.length })}</div>
                 </CardContent>
               </Card>
             )}

             {loadingAdjustments ? (
               <div className="flex items-center justify-center h-64">
                 <span className="size-8 border-2 border-slate-200 border-t-red-500 rounded-full animate-spin"></span>
               </div>
             ) : adjustments.length === 0 ? (
               <div className="flex flex-col items-center justify-center h-64 text-slate-400 border-2 border-dashed border-slate-200 rounded-2xl">
                 <p className="text-lg font-bold">{t('perimes.history.no_result')}</p>
               </div>
             ) : (
               <Card className="overflow-hidden">
                 <div className="overflow-x-auto">
                   <Table className="w-full text-sm">
                     <TableHeader>
                       <TableRow className="bg-slate-50 hover:bg-slate-50">
                         <TableHead className="text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.history.table.date')}</TableHead>
                         <TableHead className="text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.history.table.product')}</TableHead>
                         <TableHead className="text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.history.table.lot')}</TableHead>
                         <TableHead className="text-right px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.history.table.qty')}</TableHead>
                         <TableHead className="text-right px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.history.table.value')}</TableHead>
                         <TableHead className="text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.history.table.user')}</TableHead>
                         <TableHead className="text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400">{t('perimes.history.table.details')}</TableHead>
                       </TableRow>
                     </TableHeader>
                     <TableBody>
                       {adjustments.map((adj) => (
                         <TableRow key={adj.id} className="hover:bg-slate-50 transition-colors">
                           <TableCell className="text-xs px-4 py-2.5 text-slate-500">{formatDate(adj.created_at)}</TableCell>
                           <TableCell className="px-4 py-2.5">
                             <div className="font-bold text-xs text-slate-800">{adj.produit_name}</div>
                             <div className="text-[10px] text-slate-400 font-mono">{adj.produit_cip}</div>
                           </TableCell>
                           <TableCell className="font-mono text-[11px] px-4 py-2.5 text-slate-500">{adj.lot_number || '-'}</TableCell>
                           <TableCell className="text-right font-bold text-red-500 px-4 py-2.5">{adj.quantity_change}</TableCell>
                           <TableCell className="text-right font-bold px-4 py-2.5 text-slate-700">{formatCurrency(adj.valorisation)}</TableCell>
                           <TableCell className="text-xs px-4 py-2.5 text-slate-500">{adj.user_name}</TableCell>
                           <TableCell className="text-xs truncate max-w-[150px] px-4 py-2.5 text-slate-500" title={adj.reason_detail}>
                             {t(`stock:ajustements.filters.reasons.${adj.reason_type}`, { defaultValue: adj.reason_type_display })} {adj.reason_detail ? `- ${adj.reason_detail}` : ''}
                           </TableCell>
                         </TableRow>
                       ))}
                     </TableBody>
                   </Table>
                 </div>
               </Card>
             )}
          </div>
        )}
      </div>

      <SudoValidationModal
        isOpen={sudoState.isOpen}
        onClose={closeSudo}
        onValidate={sudoState.onValidate}
        title={sudoState.title}
        message={sudoState.message}
        saving={sudoState.isValidating}
      />
    </div>
  )
}

import { useState, useEffect, useMemo } from 'react';
import api from '../services/api';
import { useTranslation } from 'react-i18next';
import PremiumModal from './common/PremiumModal';
import { formatCurrency } from '../utils/formatters';
import { getLocale } from '../utils/dateUtils';

interface FactureReleve {
  id: number;
  numero_facture: string;
  date_cloture: string;
  montant: number;
}

interface ReleveResponse {
  fournisseur_id: number;
  fournisseur_nom: string;
  periode: { start_date: string; end_date: string };
  total_factures: number;
  montant_total_periode: number;
  factures: FactureReleve[];
}

interface Props {
  isOpen: boolean;
  onClose: () => void;
  fournisseurs: { id: number; name: string }[];
  initialFournisseurId?: number;
  onReglerSelection: (fournisseurId: number, commandeIds: number[], montant: number) => void;
}

export default function PointageReleveModal({ isOpen, onClose, fournisseurs, onReglerSelection, initialFournisseurId }: Props) {
  const { t } = useTranslation(['providers', 'common']);
  const [data, setData] = useState<ReleveResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Fournisseur s├®lectionn├®
  const [selectedFournisseurId, setSelectedFournisseurId] = useState<number | ''>('');

  // Filtres
  const currentYear = new Date().getFullYear();
  const currentMonth = new Date().getMonth() + 1; // 1-12

  const [year, setYear] = useState<number>(currentYear);
  const [month, setMonth] = useState<number>(currentMonth);
  const [periodeType, setPeriodeType] = useState<string>('MENSUELLER'); // MENSUELLER, QUINZAINE_1, QUINZAINE_2, DECADE_1, DECADE_2, DECADE_3
  const [customStart, setCustomStart] = useState<string>('');
  const [customEnd, setCustomEnd] = useState<string>('');

  // Pour le pointage visuel sans le stocker en DB (juste cocher en direct)
  const [pointedIds, setPointedIds] = useState<Set<number>>(new Set());

  const dateRange = useMemo(() => {
    if (periodeType === 'CUSTOM') {
      return { start: customStart, end: customEnd };
    }

    // Format YYYY-MM
    const yStr = year.toString();
    const mStr = month.toString().padStart(2, '0');

    // Last day of month
    const lastDay = new Date(year, month, 0).getDate();

    if (periodeType === 'MENSUELLER') {
      return { start: `${yStr}-${mStr}-01`, end: `${yStr}-${mStr}-${lastDay}` };
    }
    if (periodeType === 'QUINZAINE_1') {
      return { start: `${yStr}-${mStr}-01`, end: `${yStr}-${mStr}-15` };
    }
    if (periodeType === 'QUINZAINE_2') {
      return { start: `${yStr}-${mStr}-16`, end: `${yStr}-${mStr}-${lastDay}` };
    }
    if (periodeType === 'DECADE_1') {
      return { start: `${yStr}-${mStr}-01`, end: `${yStr}-${mStr}-10` };
    }
    if (periodeType === 'DECADE_2') {
      return { start: `${yStr}-${mStr}-11`, end: `${yStr}-${mStr}-20` };
    }
    if (periodeType === 'DECADE_3') {
      return { start: `${yStr}-${mStr}-21`, end: `${yStr}-${mStr}-${lastDay}` };
    }

    return { start: '', end: '' };
  }, [year, month, periodeType, customStart, customEnd]);

  // Main effect to handle modal opening and data fetching
  useEffect(() => {
    if (!isOpen) return;

    // If opening or provider changed, reset selection
    setPointedIds(new Set());

    // Handle initial provider if provided on open
    if (initialFournisseurId && !selectedFournisseurId) {
      setSelectedFournisseurId(initialFournisseurId);
      return; // selectedFournisseurId update will trigger next run
    }

    if (selectedFournisseurId && dateRange.start && dateRange.end) {
      if (periodeType === 'CUSTOM' && (!customStart || !customEnd)) {
        return;
      }
      fetchReleve(selectedFournisseurId, dateRange.start, dateRange.end);
    } else if (!selectedFournisseurId) {
      setData(null);
    }
  }, [isOpen, initialFournisseurId, selectedFournisseurId, dateRange, periodeType, customStart, customEnd]);

  async function fetchReleve(fId: number | string, start: string, end: string) {
    setLoading(true);
    setError(null);
    try {
      const { data } = await api.get(`fournisseurs/${fId}/releve_factures/`, {
        params: {
          start_date: start,
          end_date: end
        }
      });
      setData(data);
    } catch (err: unknown) {
      setError(err.response?.data?.error || err.message || t('providers:pointage_modal.load_error'));
    } finally {
      setLoading(false);
    }
  }

  const togglePointage = (id: number) => {
    setPointedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const toggleAll = () => {
    if (!data) return;
    if (pointedIds.size === data.factures.length && data.factures.length > 0) {
      setPointedIds(new Set()); // Tout d├®cocher
    } else {
      setPointedIds(new Set(data.factures.map(f => f.id))); // Tout cocher
    }
  };

  const pointageSum = useMemo(() => {
    if (!data) return 0;
    return data.factures.reduce((sum, f) => {
      if (pointedIds.has(f.id)) return sum + f.montant;
      return sum;
    }, 0);
  }, [data, pointedIds]);

  return (
    <PremiumModal
      isOpen={isOpen}
      onClose={onClose}
      title={t('providers:pointage_modal.title')}
      subtitle={t('providers:pointage_modal.subtitle')}
      icon={
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-purple-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
        </svg>
      }
      maxWidth="max-w-5xl"
    >
      <div className="flex flex-col h-[75vh]">
        {/* En-t├¬te / Filtres */}
        <div className="p-4 bg-base-200/50 border-b border-base-200 shrink-0">
          <div className="flex flex-col md:flex-row gap-4 items-end">
            <div>
              <label className="block text-[10px] font-bold uppercase text-base-content/40 mb-1">{t('providers:pointage_modal.provider_label')}</label>
              <select 
                className="select select-sm select-bordered w-full md:w-48 font-bold text-base-content/90" 
                value={selectedFournisseurId} 
                onChange={e => setSelectedFournisseurId(e.target.value === '' ? '' : Number(e.target.value))}
              >
                <option value="">{t('providers:pointage_modal.choose_provider')}</option>
                {fournisseurs.map(f => (
                  <option key={f.id} value={f.id}>{f.name}</option>
                ))}
              </select>
            </div>
            {selectedFournisseurId && (
              <>
                <div>
                  <label className="block text-[10px] font-bold uppercase text-base-content/40 mb-1">{t('providers:pointage_modal.month_label')}</label>
                  <select className="select select-sm select-bordered w-full md:w-32" value={month} onChange={e => setMonth(Number(e.target.value))} disabled={periodeType === 'CUSTOM'}>
                    {Array.from({length: 12}, (_, i) => i + 1).map(m => (
                      <option key={m} value={m}>{new Date(0, m - 1).toLocaleString(getLocale(), { month: 'long' })}</option>
                    ))}
                  </select>
                </div>
            <div>
              <label className="block text-[10px] font-bold uppercase text-base-content/40 mb-1">{t('providers:pointage_modal.year_label')}</label>
              <select className="select select-sm select-bordered w-full md:w-24" value={year} onChange={e => setYear(Number(e.target.value))} disabled={periodeType === 'CUSTOM'}>
                {[currentYear - 1, currentYear, currentYear + 1].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-[10px] font-bold uppercase text-base-content/40 mb-1">{t('providers:pointage_modal.target_period')}</label>
              <select className="select select-sm select-bordered w-full md:w-48" value={periodeType} onChange={e => setPeriodeType(e.target.value)}>
                <option value="MENSUELLER">{t('providers:pointage_modal.period_full')}</option>
                <optgroup label="Quinzaines">
                  <option value="QUINZAINE_1">{t('providers:pointage_modal.period_q1')}</option>
                  <option value="QUINZAINE_2">{t('providers:pointage_modal.period_q2')}</option>
                </optgroup>
                <optgroup label="D├®cades">
                  <option value="DECADE_1">{t('providers:pointage_modal.period_d1')}</option>
                  <option value="DECADE_2">{t('providers:pointage_modal.period_d2')}</option>
                  <option value="DECADE_3">{t('providers:pointage_modal.period_d3')}</option>
                </optgroup>
                <option value="CUSTOM">{t('providers:pointage_modal.period_custom')}</option>
              </select>
            </div>

            {periodeType === 'CUSTOM' && (
              <>
                <div>
                  <label className="block text-[10px] font-bold uppercase text-base-content/40 mb-1">{t('providers:pointage_modal.start_label')}</label>
                  <input type="date" lang={getLocale()} className="input input-sm input-bordered" value={customStart} onChange={e => setCustomStart(e.target.value)} />
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase text-base-content/40 mb-1">{t('providers:pointage_modal.end_label')}</label>
                  <input type="date" lang={getLocale()} className="input input-sm input-bordered" value={customEnd} onChange={e => setCustomEnd(e.target.value)} />
                </div>
              </>
            )}

              </>
            )}

            <div className="flex-1"></div>

            {data && (
               <div className="bg-base-100 px-4 py-2 rounded-lg border border-base-200 shadow-sm text-right">
                 <div className="text-[10px] font-bold uppercase text-base-content/40">{t('providers:pointage_modal.total_period')}</div>
                 <div className="text-lg font-black text-purple-600 font-mono">
                   {formatCurrency(data.montant_total_periode)}
                 </div>
               </div>
            )}
          </div>
        </div>

        {/* Contenu */}
        <div className="flex-1 overflow-hidden flex flex-col p-6">
          {error && (
            <div className="alert alert-error mb-4 shrink-0">
              <span>{error}</span>
            </div>
          )}

          {loading ? (
             <div className="flex justify-center flex-1 items-center">
               <span className="loading loading-spinner loading-lg text-primary"></span>
             </div>
          ) : !selectedFournisseurId ? (
            <div className="text-center flex-1 flex flex-col justify-center items-center bg-base-200/50 rounded-xl border border-slate-100">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-base-content/30 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
              </svg>
              <h3 className="text-lg font-bold text-base-content/80">{t('providers:pointage_modal.select_instruction')}</h3>
            </div>
          ) : !data || data.factures.length === 0 ? (
            <div className="text-center flex-1 flex flex-col justify-center items-center bg-base-200/50 rounded-xl border border-slate-100">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-base-content/30 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              <h3 className="text-lg font-bold text-base-content/80">{t('providers:pointage_modal.empty')}</h3>
              <p className="text-sm text-base-content/60">{t('providers:pointage_modal.empty_subtitle', { start: dateRange.start, end: dateRange.end })}</p>
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden bg-base-100 border border-base-200 rounded-xl shadow-sm">
              {/* Pointage En T├¬te */}
              <div className="flex items-center justify-between p-3 border-b bg-base-200/50">
                <div className="flex items-center gap-3">
                   <div className="badge badge-primary badge-sm font-bold">{t('providers:pointage_modal.pointed_count', { count: pointedIds.size, total: data.factures.length })}</div>
                   <button className="btn btn-xs btn-outline rounded-full" onClick={toggleAll}>
                     {pointedIds.size === data.factures.length ? t('providers:pointage_modal.uncheck_all') : t('providers:pointage_modal.check_all')}
                   </button>
                </div>
                <div className="text-sm font-bold text-base-content/90">
                  {t('providers:pointage_modal.pointed_sum')} <span className="font-mono text-success bg-success/10 px-2 py-1 rounded ml-1">{formatCurrency(pointageSum)}</span>
                </div>
              </div>

              {/* Tableau avec scroll */}
              <div className="flex-1 overflow-auto">
                <table className="table table-sm table-pin-rows w-full">
                  <thead className="bg-[#f8fafc] text-[#64748b] text-[10px] uppercase">
                    <tr>
                      <th className="w-10 text-center"><svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 inline-block" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg></th>
                      <th>{t('providers:pointage_modal.table.date')}</th>
                      <th>{t('providers:pointage_modal.table.ref')}</th>
                      <th className="text-right">{t('providers:pointage_modal.table.amount')}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.factures.map((f) => {
                      const isPointed = pointedIds.has(f.id);
                      return (
                        <tr 
                          key={f.id} 
                          className={`hover transition-colors cursor-pointer border-b border-slate-100 last:border-0 ${isPointed ? 'bg-success/10/50' : 'bg-base-100'}`}
                          onClick={() => togglePointage(f.id)}
                        >
                          <td className="text-center">
                            <input 
                              type="checkbox" 
                              className="checkbox checkbox-sm checkbox-success" 
                              checked={isPointed}
                              onChange={() => {}} // Handle on TR click
                            />
                          </td>
                          <td>
                            <div className={`font-medium ${isPointed ? 'text-success' : 'text-base-content/80'}`}>
                              {new Date(f.date_cloture).toLocaleDateString(getLocale(), { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' })}
                            </div>
                          </td>
                          <td>
                            <div className="font-mono text-xs font-bold bg-base-200 text-base-content/90 px-2 py-0.5 rounded inline-block">
                              {f.numero_facture}
                            </div>
                          </td>
                          <td className="text-right">
                            <div className={`font-black font-mono ${isPointed ? 'text-success' : 'text-base-content/90'}`}>
                              {formatCurrency(f.montant)}
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
              <div className="p-4 border-t bg-base-200/50 flex justify-end">
                <button 
                  className="btn btn-primary rounded-xl px-8 shadow-lg shadow-primary/20"
                  disabled={pointedIds.size === 0}
                  onClick={() => {
                     if (selectedFournisseurId) {
                        onReglerSelection(Number(selectedFournisseurId), Array.from(pointedIds), pointageSum);
                     }
                  }}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  {t('providers:pointage_modal.regler_btn', { amount: formatCurrency(pointageSum) })}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </PremiumModal>
  );
}

import React, { useState, useMemo, useEffect } from 'react'
import { useNavigate, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import api from '../services/api'
import { toast } from 'react-hot-toast'
import { getApiErrorDetail } from '../utils/errorHandling';
import { useConfirm } from '../hooks/useConfirm';
import { useAuth } from '../context/AuthContext';
import PasswordConfirmModal from './PasswordConfirmModal';
import type { ProduitModel, Facture } from '../types'
import { Package, Upload, RotateCw, RefreshCw } from 'lucide-react'

import {
  useProduits,
  useRayons,
  useFournisseurs,
  useFormes,
  useGroupes,
  useProduitAchats,
  useProduitLots,
  useProduitStats,
  useProduitHistory,
  useAdjustStock,
  useDeleteProduit,
  useRecalculateRotation
} from '../hooks/useProduits';
import { useTVA } from '../hooks/useTVA';

import ProduitCreateModal from './ProduitFormModal'
import { ProductDetailsModal as SalesDetailsModal } from './sales/modals/ProductDetailsModal';

// Modular Components
import { ProductFilters } from './products/ProductFilters';
import { ProductTable } from './products/ProductTable';
import { BulkActionsBar } from './products/BulkActionsBar';
import { ProductDetailPanel } from './products/ProductDetailPanel';
import { ProductDetailsModal } from './products/modals/ProductDetailsModal';
import { StockAdjustmentModal } from './products/modals/StockAdjustmentModal';
import ImportProductsModal from './products/ImportProductsModal';
import Pagination from './ui/Pagination';

export default function Produit() {
  const confirm = useConfirm()
  const navigate = useNavigate()
  const location = useLocation()
  const { t } = useTranslation(['products', 'common']);
  const { user } = useAuth();
  const [page, setPage] = useState(1)
  const [searchQuery, setSearchQuery] = useState('')
  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState('')
  const [filterRayon, setFilterRayon] = useState('')
  const [filterFournisseur, setFilterFournisseur] = useState('')
  const [filterExclusive, setFilterExclusive] = useState(false)
  const [showInactive, setShowInactive] = useState(false)
  const [showInStockOnly, setShowInStockOnly] = useState(false)

  // Modals Visibility
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false)
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false)
  const [isEditModalOpen, setIsEditModalOpen] = useState(false)
  const [isAdjustmentModalOpen, setIsAdjustmentModalOpen] = useState(false)
  const [isImportModalOpen, setIsImportModalOpen] = useState(false)
  
  // Selection
  const [selectedProduit, setSelectedProduit] = useState<ProduitModel | null>(null)
  const [selectedProductIds, setSelectedProductIds] = useState<number[]>([])
  const [activeTab, setActiveTab] = useState<'general' | 'prix' | 'achats' | 'lots' | 'stats' | 'mvmts'>('general')

  // Sales/Facture Details
  const [showSalesModal, setShowSalesModal] = useState(false);
  const [selectedFacture, setSelectedFacture] = useState<Facture | null>(null);
  const [loadingFacture, setLoadingFacture] = useState(false);

  // -- API CALLS (React Query) --
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearchQuery(searchQuery)
      setPage(1)
    }, 500)
    return () => clearTimeout(timer)
  }, [searchQuery])

  // Reset page when stock filter changes
  useEffect(() => {
    setPage(1)
  }, [showInStockOnly, showInactive, filterRayon, filterFournisseur])

  const { 
    data: productsData, 
    isLoading: loading, 
    error: loadError,
    refetch: refetchProduits
  } = useProduits({
    search: debouncedSearchQuery,
    page: page,
    page_size: 50,
    rayon: filterRayon,
    fournisseur: filterFournisseur,
    include_inactive: showInactive,
    only_in_stock: showInStockOnly
  });

  // Handle incoming redirect from Omnisearch
  useEffect(() => {
    if (location.state?.action === 'NEW_PRODUCT') {
      setIsCreateModalOpen(true);
      navigate(location.pathname, { replace: true, state: {} });
    }
    if (location.state?.searchProduitId && productsData?.results) {
      const pid = location.state.searchProduitId;
      const found = productsData.results.find((p: ProduitModel) => p.id === pid);
      if (found) {
        setSelectedProduit(found);
        setActiveTab('stats');
        // Clear state to avoid re-triggering
        navigate(location.pathname, { replace: true, state: {} });
      } else {
        // If not in current page, maybe search for it specifically 
        if (searchQuery !== String(pid)) {
          setSearchQuery(String(pid));
        }
      }
    }
  }, [productsData]);

  const { data: rayons = [] } = useRayons();
  const { data: fournisseurs = [] } = useFournisseurs();
  const { data: formes = [] } = useFormes();
  const { data: groupes = [] } = useGroupes();
  const { loading: _loadingTVA } = useTVA();



  const produits = useMemo(() => productsData?.results || [], [productsData]);
  const totalCount = productsData?.count || 0;
  const totalPages = Math.ceil(totalCount / 50) || 1;

  // Debug: log pagination values
  useEffect(() => {
    console.log('[Pagination Debug] count:', totalCount, 'pages:', totalPages, 'data:', productsData);
  }, [totalCount, totalPages, productsData]);

  const { data: lots = [], isLoading: detailsLoadingLots } = useProduitLots(selectedProduit?.id || null);
  const { data: monthlyStats = [], isLoading: detailsLoadingStats } = useProduitStats(selectedProduit?.id || null);
  const { data: achats = [], isLoading: loadingAchats } = useProduitAchats(selectedProduit?.id || null);
  const { data: stockHistory = [], isLoading: loadingHistory } = useProduitHistory(selectedProduit?.id || null, activeTab);

  const detailsLoading = detailsLoadingLots || detailsLoadingStats || loadingAchats;

  // Mutations
  const deleteProduitMutation = useDeleteProduit();
  const adjustStockMutation = useAdjustStock();
  const recalculateRotationMutation = useRecalculateRotation();
  const [transferLoading, setTransferLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);

  // Constants
  // -- FORMS --
  const [editForm, setEditForm] = useState<unknown>({
    name: '', stock: '', cost_price: '', selling_price: '', cip1: '', cip2: '', cip3: '',
    expire_date: '', stock_alert: '', stock_minimum: '', stock_maximum: '', tva: '19.25',
    rayon: '', fournisseur: '', forme: '', use_lot_management: true, requires_prescription: false,
    surveillance_category: 'NONE', is_supplier_exclusive: false, has_reserve_storage: false,
    capacite_rayon: '0', min_rayon: '0', message_alerte: ''
  })
  
  const [adjustmentForm, setAdjustmentForm] = useState({
    new_quantity: '',
    new_reserve_quantity: '',
    reason_type: 'INVENTAIRE',
    stock_lot_id: ''
  })

  // Sudo actions
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [passwordModalConfig, setPasswordModalConfig] = useState({ title: '', message: '' });
  const [pendingAction, setPendingAction] = useState<() => Promise<void>>(() => Promise.resolve());

  // -- HANDLERS --
  const handleViewDetails = (produit: ProduitModel) => {
    setSelectedProduit(produit)
  }

  const handleTransferToRayon = async (produit: ProduitModel) => {
    if (!produit.has_reserve_storage || (produit.stock_reserve ?? 0) <= 0) return;
    const needed = Math.max(0, (produit.capacite_rayon ?? 0) - (produit.stock ?? 0));
    const suggest = Math.min(needed, produit.stock_reserve ?? 0);
    const informMsg = t('products:messages.transfer_prompt', { 
      reserve: produit.stock_reserve, 
      capacity: produit.capacite_rayon, 
      needed: needed 
    });
    const qtyStr = prompt(informMsg, String(suggest));
    if (qtyStr === null) return;
    const qty = parseInt(qtyStr, 10);
    if (isNaN(qty) || qty <= 0) { toast.error(t('products:messages.invalid_quantity')); return; }

    setTransferLoading(true);
    try {
      await api.post(`produits/${produit.id}/transfer_to_shelf/`, { quantity: qty });
      toast.success(t('products:messages.transfer_success', { count: qty }));
      refetchProduits();
    } catch (err) {
      toast.error(getApiErrorDetail(err, t('products:messages.transfer_error')));
    } finally { setTransferLoading(false); }
  };

  const handleMovementClick = async (item: unknown) => {
    if (!item) return;
    if (item.facture) {
      try {
        setLoadingFacture(true);
        const response = await api.get(`factures/${item.facture}/`);
        setSelectedFacture(response.data);
        setShowSalesModal(true);
      } catch (error) {
        console.error('Error loading invoice from movement:', error);
        toast.error(t('products:messages.facture_load_error'));
      } finally { setLoadingFacture(false); }
    } else if (item.commande) {
      navigate('/app/commandes', { state: { openDetailsId: item.commande } });
    }
  };

  const executeDeleteProduit = async (produitId: number) => {
    try {
      await deleteProduitMutation.mutateAsync(produitId);
      setSelectedProduit(null)
      toast.success(t('products:messages.delete_success'))
    } catch (err) { toast.error(getApiErrorDetail(err, t('products:messages.delete_error'))) }
  }

  const handleDeleteProduit = async (produit: ProduitModel) => {
    if (!user?.is_superuser && !user?.profile?.can_delete_product && !user?.can_delete_product) {
        toast.error(t('products:messages.access_denied_delete'))
        return
    }
    const confirmed = await confirm({
      title: t('products:messages.delete_confirm_title'),
      message: t('products:messages.delete_confirm_body', { name: produit.name }),
      variant: 'danger',
      confirmText: t('products:actions.delete')
    })
    if (!confirmed) return
    setPasswordModalConfig({
        title: t('products:messages.password_confirm_delete_title'),
        message: t('products:messages.password_confirm_delete_body')
    })
    setPendingAction(() => () => executeDeleteProduit(produit.id))
    setIsPasswordModalOpen(true)
  }

  const handleToggleActive = async (produit: ProduitModel) => {
    try {
      const response = await api.post(`produits/${produit.id}/toggle_active/`)
      const isActive = response.data.is_active
      toast.success(isActive ? t('products:messages.status_reactivated') : t('products:messages.status_hidden'))
      setSelectedProduit(prev => prev ? ({ ...prev, is_active: isActive }) : null)
      refetchProduits()
    } catch (err) { toast.error(getApiErrorDetail(err, t('products:messages.status_error'))) }
  }

  const handleOpenEditModal = (produit: ProduitModel) => {
    setEditForm({
      id: produit.id,
      name: produit.name,
      stock: String(produit.stock ?? ''),
      cost_price: String(produit.cost_price ?? ''),
      selling_price: String(produit.selling_price ?? ''),
      cip1: produit.cip1 || '',
      cip2: produit.cip2 || '',
      cip3: produit.cip3 || '',
      expire_date: produit.expire_date || '',
      stock_alert: String(produit.stock_alert ?? '0'),
      stock_minimum: String(produit.stock_minimum ?? '0'),
      stock_maximum: String(produit.stock_maximum ?? '0'),
      tva: produit.tva || '19.25',
      rayon: produit.rayon ? String(produit.rayon) : '',
      fournisseur: produit.fournisseur ? String(produit.fournisseur) : '',
      forme: produit.forme ? String(produit.forme) : '',
      use_lot_management: produit.use_lot_management ?? true,
      requires_prescription: produit.requires_prescription ?? false,
      surveillance_category: produit.surveillance_category || 'NONE',
      is_supplier_exclusive: produit.is_supplier_exclusive ?? false,
      has_reserve_storage: produit.has_reserve_storage ?? false,
      capacite_rayon: String(produit.capacite_rayon ?? '0'),
      min_rayon: String(produit.min_rayon ?? '0'),
      message_alerte: produit.message_alerte || ''
    })
    setIsEditModalOpen(true)
  }

  const executeStockAdjustment = async () => {
    if (!selectedProduit) return
    try {
      const data = await adjustStockMutation.mutateAsync({
        id: selectedProduit.id,
        quantity: parseInt(adjustmentForm.new_quantity),
        newReserveQuantity: selectedProduit.has_reserve_storage ? parseInt(adjustmentForm.new_reserve_quantity || '0') : undefined,
        reason: adjustmentForm.reason_type,
        stockLotId: adjustmentForm.stock_lot_id ? parseInt(adjustmentForm.stock_lot_id) : undefined
      });
      const qtyChangeStr = (data.quantity_change ?? 0) >= 0 ? '+' : '';
      toast.success(t('products:messages.adjust_success', { change: `${qtyChangeStr}${data.quantity_change ?? 0}` }))
      setSelectedProduit(prev => {
        if (!prev) return null;
        return {
          ...prev,
          stock: (prev.stock ?? 0) + (data.quantity_change ?? 0),
          stock_reserve: (prev.stock_reserve ?? 0) + ((data as unknown).reserve_change ?? 0)
        };
      });
      setIsAdjustmentModalOpen(false)
    } catch (err) { toast.error(getApiErrorDetail(err, t('products:messages.adjust_error'))) }
  }

  const handleStockAdjustmentSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!selectedProduit) return
    if (!user?.is_superuser && !user?.profile?.can_adjust_stock && !user?.can_adjust_stock) {
        toast.error(t('products:messages.access_denied_adjust')); return;
    }
    setIsAdjustmentModalOpen(false)
    setPasswordModalConfig({
        title: t('products:messages.password_confirm_adjust_title'),
        message: t('products:messages.password_confirm_adjust_body', { 
          name: selectedProduit.name, 
          oldStock: selectedProduit.stock, 
          newStock: adjustmentForm.new_quantity,
          ...((selectedProduit.has_reserve_storage) && {
            reserveDetails: t('products:messages.adjust_reserve_details', { oldReserve: selectedProduit.stock_reserve, newReserve: adjustmentForm.new_reserve_quantity })
          })
        })
    })
    setPendingAction(() => executeStockAdjustment)
    setIsPasswordModalOpen(true)
  }

  const handleBulkDelete = async () => {
    const confirmed = await confirm({
      title: t('products:messages.bulk_delete_title'),
      message: t('products:messages.bulk_delete_body', { count: selectedProductIds.length }),
      variant: 'danger',
      confirmText: t('products:actions.bulk_delete')
    })
    if (!confirmed) return
    setActionLoading(true)
    let successCount = 0
    try {
      const results = await Promise.all(selectedProductIds.map(async (id) => {
        try { await api.delete(`produits/${id}/`); return true; } catch { return false; }
      }));
      successCount = results.filter(Boolean).length;
      if (successCount > 0) { refetchProduits(); setSelectedProductIds([]); toast.success(`${successCount} ${t('products:messages.delete_success')}`); }
    } finally { setActionLoading(false) }
  }

  const handleGenerateLabels = async (produit: ProduitModel) => {
    const qtyStr = prompt(t('products:messages.labels_prompt', { name: produit.name }), "1")
    if (!qtyStr) return
    const quantity = parseInt(qtyStr, 10)
    if (isNaN(quantity) || quantity <= 0) { toast.error(t('products:messages.invalid_quantity')); return; }
    try {
      const resp = await api.post('produits/generate_labels/', { products: [{ id: produit.id, quantity }] }, { responseType: 'blob' })
      const url = window.URL.createObjectURL(new Blob([resp.data]));
      const link = document.createElement('a'); link.href = url; link.setAttribute('download', `${t('products:labels.filename_prefix')}_${produit.name}.pdf`);
      document.body.appendChild(link); link.click(); link.remove();
    } catch (err) { toast.error(getApiErrorDetail(err, t('products:messages.generation_error'))) }
  }

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const activeElement = document.activeElement as HTMLElement
      if (activeElement?.tagName === 'TEXTAREA' || (activeElement?.tagName === 'INPUT' && activeElement.getAttribute('type') !== 'text')) return;
      if (e.key === 'Enter' && selectedProduit) { e.preventDefault(); setSelectedProductIds(prev => prev.includes(selectedProduit.id) ? prev.filter(pid => pid !== selectedProduit.id) : [...prev, selectedProduit.id]); return; }
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        if (produits.length === 0) return
        const currentIndex = selectedProduit ? produits.findIndex(p => p.id === selectedProduit.id) : -1
        const newIndex = e.key === 'ArrowDown' ? (currentIndex < produits.length - 1 ? currentIndex + 1 : 0) : (currentIndex > 0 ? currentIndex - 1 : produits.length - 1)
        const newProduit = produits[newIndex]
        if (newProduit) {
          setSelectedProduit(newProduit)
          document.querySelector(`tr[data-product-id="${newProduit.id}"]`)?.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
        }
        e.preventDefault()
      }
    }
    document.addEventListener('keydown', handleKeyDown); return () => document.removeEventListener('keydown', handleKeyDown)
  }, [produits, selectedProduit])

  // -- RENDER --
  const lowStockCount = useMemo(() => produits.filter(p => (p.stock ?? 0) <= (p.stock_alert ?? 0) && (p.stock ?? 0) > 0).length, [produits])
  const outOfStockCount = useMemo(() => produits.filter(p => (p.stock ?? 0) <= 0).length, [produits])
  const error = loadError instanceof Error ? loadError.message : (loadError ? String(loadError) : null);

  return (
    <div className="flex-1 flex flex-col overflow-hidden bg-base-200">
      {/* ÔöÇÔöÇ HEADER ÔöÇÔöÇ */}
      <div className="px-6 py-4 border-b border-base-200 bg-base-100 shrink-0 flex flex-col sm:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="p-2.5 bg-primary/10 rounded-lg">
            <Package className="size-5 text-primary" />
          </div>
          <div>
            <h1 className="text-lg font-bold text-base-content">
              {t('products:title', { defaultValue: 'Gestion des produits' })}
            </h1>
            <p className="text-xs text-base-content/50 font-medium">
              {t('products:subtitle', { defaultValue: 'Cr├®ez et g├®rez vos produits et services' })}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => recalculateRotationMutation.mutate()}
            className="p-2 text-base-content/50 hover:bg-base-200 rounded-lg transition-colors"
            title={t('products:actions.rotation')}
          >
            <RotateCw className="size-4" />
          </button>
          <button
            onClick={() => refetchProduits()}
            className="p-2 text-base-content/50 hover:bg-base-200 rounded-lg transition-colors"
            disabled={loading}
            title={t('common:actions.refresh')}
          >
            {loading ? <span className="inline-block size-4 border-2 border-base-300 border-t-gray-600 rounded-full animate-spin" /> : <RefreshCw className="size-4" />}
          </button>
          <button
            className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg text-white bg-primary hover:bg-primary-focus transition-colors shadow-sm"
            onClick={() => setIsCreateModalOpen(true)}
          >
            <Package className="size-3.5" />
            <span>{t('products:actions.new', { defaultValue: 'Nouveau' })}</span>
          </button>
          <button
            className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg border border-base-300 bg-base-100 text-base-content hover:bg-base-200 transition-colors"
            onClick={() => {
              setPasswordModalConfig({
                title: t('products:messages.password_confirm_import_title'),
                message: t('products:messages.password_confirm_import_body')
              });
              setPendingAction(() => async () => {
                setIsImportModalOpen(true);
              });
              setIsPasswordModalOpen(true);
            }}
          >
            <Upload className="size-3.5" />
            <span>{t('products:import.title')}</span>
          </button>
        </div>
      </div>

      <div className="flex-1 p-4 min-h-0 overflow-hidden flex flex-col gap-4">
      {error && (
        <div className="px-4 py-3 bg-error/10 border border-red-200 rounded-lg text-error text-sm">
          {error}
        </div>
      )}

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 h-full min-h-0 w-full overflow-hidden">
        {/* Left Panel: List & Actions */}
        <div className="lg:col-span-12 xl:col-span-5 bg-base-100 rounded-xl shadow-sm border border-base-200 flex flex-col overflow-hidden h-full">
          <div className="shrink-0">
            <ProductFilters
              searchQuery={searchQuery} setSearchQuery={setSearchQuery}
              filterRayon={filterRayon} setFilterRayon={setFilterRayon}
              filterFournisseur={filterFournisseur} setFilterFournisseur={setFilterFournisseur}
              filterExclusive={filterExclusive} setFilterExclusive={setFilterExclusive}
              showInactive={showInactive} setShowInactive={setShowInactive}
              showInStockOnly={showInStockOnly} setShowInStockOnly={setShowInStockOnly}
            />
          </div>

          <div className="overflow-y-auto flex-1 min-h-0">
            <ProductTable
              products={produits} selectedProduit={selectedProduit}
              onViewDetails={handleViewDetails} loading={loading}
              selectedProductIds={selectedProductIds}
              onSelectProduct={(id) => setSelectedProductIds(prev => prev.includes(id) ? prev.filter(pid => pid !== id) : [...prev, id])}
              onSelectAll={() => setSelectedProductIds(prev => prev.length === produits.length ? [] : produits.map(p => p.id))}
              onZoom={() => setIsDetailsModalOpen(true)}
            />
          </div>

          {totalPages > 1 && (
            <div className="shrink-0">
              <Pagination
                currentPage={page}
                totalPages={totalPages}
                totalItems={totalCount}
                onPrev={() => setPage(p => Math.max(1, p - 1))}
                onNext={() => setPage(p => Math.min(totalPages, p + 1))}
                hasNext={page < totalPages}
                isLoading={loading}
              />
            </div>
          )}

          <div className="px-4 py-2 border-t border-base-200 bg-base-200 shrink-0 flex justify-between items-center">
            <div className="flex items-center gap-1.5">
              <span className="text-[10px] font-semibold text-base-content/50 uppercase tracking-wider">{t('products:stats.total')}</span>
              <span className="text-primary font-bold text-sm">{totalCount}</span>
            </div>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-1.5" title={t('products:stats.low_stock')}>
                <div className="size-2 rounded-full bg-amber-400"></div>
                <span className="text-warning font-semibold text-sm">{lowStockCount}</span>
              </div>
              <div className="flex items-center gap-1.5" title={t('products:stats.out_of_stock')}>
                <div className="size-2 rounded-full bg-red-500"></div>
                <span className="text-error font-semibold text-sm">{outOfStockCount}</span>
              </div>
            </div>
          </div>

          <div className="shrink-0">
            <BulkActionsBar
              selectedCount={selectedProductIds.length} rayons={rayons} fournisseurs={fournisseurs} loading={actionLoading}
              onDeselectAll={() => setSelectedProductIds([])}
              onBulkDelete={handleBulkDelete}
              onBulkChangeRayon={() => { /* handleBulkChangeRayon Logic */ }}
              onBulkChangeFournisseur={() => { /* handleBulkChangeFournisseur Logic */ }}
            />
          </div>
        </div>

        {/* Right Panel: Details */}
        <div className="lg:col-span-12 xl:col-span-7 bg-base-100 rounded-xl shadow-sm border border-base-200 flex flex-col overflow-hidden h-full">
          <ProductDetailPanel
            selectedProduit={selectedProduit} detailsLoading={detailsLoading}
            activeTab={activeTab} setActiveTab={setActiveTab}
            lots={lots} monthlyStats={monthlyStats}
            achats={achats} loadingAchats={loadingAchats}
            stockHistory={stockHistory} loadingHistory={loadingHistory} transferLoading={transferLoading}
            onMovementClick={handleMovementClick}
            onOpenAdjustment={() => {
              setAdjustmentForm({
                new_quantity: String(selectedProduit?.stock || 0),
                new_reserve_quantity: String(selectedProduit?.stock_reserve || 0),
                reason_type: 'INVENTAIRE',
                stock_lot_id: ''
              });
              setIsAdjustmentModalOpen(true);
            }}
            onOpenEdit={handleOpenEditModal}
            onGenerateLabels={handleGenerateLabels}
            onDelete={handleDeleteProduit}
            onToggleActive={handleToggleActive}
            onTransferToRayon={handleTransferToRayon}
          />
        </div>
      </div>

      {/* Modals */}
      <ProduitCreateModal
        open={isEditModalOpen}
        onClose={() => setIsEditModalOpen(false)}
        onSuccess={(updated) => {
          setSelectedProduit(updated);
          setIsEditModalOpen(false);
          refetchProduits();
          toast.success(t('products:messages.update_success'));
        }}
        produitsEndpoint="produits/"
        initialData={editForm}
        rayons={rayons}
        fournisseurs={fournisseurs}
        formes={formes}
        groupes={groupes as unknown}
      />
      <StockAdjustmentModal 
        isOpen={isAdjustmentModalOpen} onClose={() => setIsAdjustmentModalOpen(false)}
        selectedProduit={selectedProduit} form={adjustmentForm} setForm={setAdjustmentForm}
        onSubmit={handleStockAdjustmentSubmit}
      />
      <PasswordConfirmModal 
        isOpen={isPasswordModalOpen} onClose={() => setIsPasswordModalOpen(false)}
        onConfirm={pendingAction} title={passwordModalConfig.title} message={passwordModalConfig.message}
      />
      <ProduitCreateModal
        open={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onCreated={(produit) => {
          refetchProduits();
          setIsCreateModalOpen(false);
          setSelectedProduit(produit);
          toast.success(`Ô£à ${produit.name} ÔÇö ${t('products:messages.create_success')}`);
        }}
        produitsEndpoint={'produits/'}
        rayons={rayons}
        fournisseurs={fournisseurs}
        formes={formes}
        groupes={groupes as unknown}
      />
      {isImportModalOpen && (
        <ImportProductsModal 
          onClose={() => setIsImportModalOpen(false)} 
          onSuccess={() => { refetchProduits(); setIsImportModalOpen(false); }} 
        />
      )}
      <SalesDetailsModal isOpen={showSalesModal} onClose={() => { setShowSalesModal(false); setSelectedFacture(null); }} facture={selectedFacture} loading={loadingFacture} />
      <ProductDetailsModal 
        isOpen={isDetailsModalOpen} 
        onClose={() => setIsDetailsModalOpen(false)}
        selectedProduit={selectedProduit}
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        lots={lots}
        monthlyStats={monthlyStats}
        achats={achats}
        stockHistory={stockHistory}
        loadingHistory={loadingHistory}
        onMovementClick={handleMovementClick}
        onOpenAdjustment={() => {
          setAdjustmentForm({ 
            new_quantity: String(selectedProduit?.stock || 0), 
            new_reserve_quantity: String(selectedProduit?.stock_reserve || 0),
            reason_type: 'INVENTAIRE',
            stock_lot_id: '' 
          });
          setIsAdjustmentModalOpen(true);
        }}
        onOpenEdit={handleOpenEditModal}
        onDelete={handleDeleteProduit}
      />
    </div>
    </div>
  )
}

import React, { useState, useMemo, useEffect, useRef } from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { toast } from 'react-hot-toast'
import {
  Package, Upload, RefreshCw, Search, X,
  ChevronLeft, ChevronRight, AlertTriangle,
  BarChart3, Tags, Eye, EyeOff, Truck
} from 'lucide-react'

import api from '../services/api'
import { getApiErrorDetail } from '../utils/errorHandling'
import { useConfirm } from '../hooks/useConfirm'
import { useAuth } from '../context/AuthContext'
import type { ProduitModel } from '../types'
import type { Groupe } from '../types/catalog'

import {
  useProduits, useRayons, useFournisseurs, useFormes, useGroupes,
  useProduitLots, useProduitStats, useProduitAchats, useProduitHistory,
  useAdjustStock
} from '../hooks/useProduits'
import { useTVA } from '../hooks/useTVA'

import { Card } from './ui/Card'
import { Button } from './ui/Button'
import { Input } from './ui/Input'
import { Badge } from './ui/Badge'
import { Checkbox } from './ui/Checkbox'
import SkeletonTable from './ui/SkeletonTable'
import { ProductTabsContent } from './products/ProductTabsContent'
import ProduitCreateModal from './ProduitFormModal'
import PasswordConfirmModal from './PasswordConfirmModal'
import { StockAdjustmentModal } from './products/modals/StockAdjustmentModal'

/* ------------------------------------------------------------------ */
/*  Types                                                               */
/* ------------------------------------------------------------------ */
type ActiveTab = 'general' | 'prix' | 'achats' | 'lots' | 'stats' | 'mvmts'

/* ------------------------------------------------------------------ */
/*  Helpers                                                             */
/* ------------------------------------------------------------------ */
function stockClass(stock: number): string {
  if (stock < 0) return 'text-red-600 font-bold'
  if (stock === 0) return 'text-slate-400 font-medium'
  return 'text-slate-800 font-bold'
}

/* ------------------------------------------------------------------ */
/*  Component                                                           */
/* ------------------------------------------------------------------ */
export default function ProduitShadcn() {
  /* ÔöÇÔöÇ Hooks ÔöÇÔöÇ */
  const confirm = useConfirm()
  const navigate = useNavigate()
  const location = useLocation()
  const { t } = useTranslation(['products', 'common'])
  const { user } = useAuth()

  /* ÔöÇÔöÇ Pagination & Filters ÔöÇÔöÇ */
  const [page, setPage] = useState(1)
  const [searchQuery, setSearchQuery] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  const [filterRayon, setFilterRayon] = useState('')
  const [filterFournisseur, setFilterFournisseur] = useState('')
  const [showInactive, setShowInactive] = useState(false)
  const [showInStockOnly, setShowInStockOnly] = useState(false)

  /* ÔöÇÔöÇ Selection ÔöÇÔöÇ */
  const [selectedProduit, setSelectedProduit] = useState<ProduitModel | null>(null)
  const [selectedIds, setSelectedIds] = useState<number[]>([])
  const [activeTab, setActiveTab] = useState<ActiveTab>('general')

  /* ÔöÇÔöÇ Modals ÔöÇÔöÇ */
  const [isCreateOpen, setIsCreateOpen] = useState(false)
  const [isEditOpen, setIsEditOpen] = useState(false)
  const [isAdjustOpen, setIsAdjustOpen] = useState(false)
  const [isPasswordOpen, setIsPasswordOpen] = useState(false)
  const [passwordConfig, setPasswordConfig] = useState({ title: '', message: '' })
  const pendingActionRef = useRef<() => Promise<void>>(() => Promise.resolve())

  /* ÔöÇÔöÇ Forms ÔöÇÔöÇ */
  const [editForm, setEditForm] = useState<Record<string, unknown>>({})
  const [adjustForm, setAdjustForm] = useState({
    new_quantity: '',
    new_reserve_quantity: '',
    reason_type: 'INVENTAIRE',
    stock_lot_id: '',
    new_lot_number: '',
    new_lot_expiration: ''
  })
  const adjustStockMutation = useAdjustStock()
  const [transferLoading, setTransferLoading] = useState(false)

  /* ÔöÇÔöÇ Debounce search ÔöÇÔöÇ */
  useEffect(() => {
    const timer = setTimeout(() => { setDebouncedSearch(searchQuery); setPage(1) }, 500)
    return () => clearTimeout(timer)
  }, [searchQuery])

  useEffect(() => {
    console.log('[Filter Change] showInStockOnly:', showInStockOnly, 'resetting page to 1')
    setPage(1)
  }, [showInStockOnly, showInactive, filterRayon, filterFournisseur])

  /* ÔöÇÔöÇ Data ÔöÇÔöÇ */
  const { data: productsData, isLoading, error: loadError, refetch } = useProduits({
    search: debouncedSearch,
    page,
    page_size: 50,
    rayon: filterRayon,
    fournisseur: filterFournisseur,
    include_inactive: showInactive,
    only_in_stock: showInStockOnly,
  })

  const { data: lots = [] } = useProduitLots(selectedProduit?.id || null)
  const { data: monthlyStats = [] } = useProduitStats(selectedProduit?.id || null)
  const { data: achats = [] } = useProduitAchats(selectedProduit?.id || null)
  const { data: stockHistory = [], isLoading: loadingHistory } = useProduitHistory(selectedProduit?.id || null, activeTab)

  useEffect(() => {
    if (location.state?.action === 'NEW_PRODUCT') {
      setIsCreateOpen(true)
      navigate(location.pathname, { replace: true, state: {} })
    }
    if (location.state?.searchProduitId && productsData?.results) {
      const pid = location.state.searchProduitId
      const found = productsData.results.find((p: ProduitModel) => p.id === pid)
      if (found) { setSelectedProduit(found); setActiveTab('stats') }
      else if (searchQuery !== String(pid)) setSearchQuery(String(pid))
      navigate(location.pathname, { replace: true, state: {} })
    }
  }, [productsData])

  const { data: rayons = [] } = useRayons()
  const { data: fournisseurs = [] } = useFournisseurs()
  const { data: formes = [] } = useFormes()
  const { data: groupes = [] } = useGroupes()
  useTVA()

  const produits = useMemo(() => productsData?.results || [], [productsData])
  const totalCount = productsData?.count || 0
  const totalPages = Math.ceil(totalCount / 50) || 1

  // DEBUG pagination
  useEffect(() => {
    console.log('[Pagination Debug] page:', page, 'count:', totalCount, 'totalPages:', totalPages, 'results:', productsData?.results?.length)
  }, [page, productsData, totalCount, totalPages])

  /* ÔöÇÔöÇ Stats ÔöÇÔöÇ */
  const lowStockCount = useMemo(() => produits.filter(p => (p.stock ?? 0) <= (p.stock_alert ?? 0) && (p.stock ?? 0) > 0).length, [produits])
  const outOfStockCount = useMemo(() => produits.filter(p => (p.stock ?? 0) <= 0).length, [produits])
  const error = loadError instanceof Error ? loadError.message : (loadError ? String(loadError) : null)

  /* ÔöÇÔöÇ Handlers ÔöÇÔöÇ */
  const handleDelete = async (produit: ProduitModel) => {
    if (!user?.is_superuser && !user?.profile?.can_delete_product && !user?.can_delete_product) {
      toast.error(t('products:messages.access_denied_delete')); return
    }
    const ok = await confirm({
      title: t('products:messages.delete_confirm_title'),
      message: t('products:messages.delete_confirm_body', { name: produit.name }),
      variant: 'danger',
      confirmText: t('products:actions.delete')
    })
    if (!ok) return
    setPasswordConfig({ title: 'Confirmation', message: 'Entrez votre mot de passe pour supprimer' })
    pendingActionRef.current = async () => {
      await api.delete(`produits/${produit.id}/`)
      setSelectedProduit(null)
      refetch()
      toast.success(t('products:messages.delete_success'))
    }
    setIsPasswordOpen(true)
  }

  const handleStockAdjustment = async () => {
    if (!selectedProduit) return
    try {
      const data = await adjustStockMutation.mutateAsync({
        id: selectedProduit.id,
        quantity: parseInt(adjustForm.new_quantity),
        newReserveQuantity: selectedProduit.has_reserve_storage ? parseInt(adjustForm.new_reserve_quantity || '0') : undefined,
        reason: adjustForm.reason_type,
        stockLotId: adjustForm.stock_lot_id ? parseInt(adjustForm.stock_lot_id) : undefined,
        newLotNumber: adjustForm.new_lot_number || undefined,
        newLotExpiration: adjustForm.new_lot_expiration || undefined
      })
      const qtyChangeStr = (data.quantity_change ?? 0) >= 0 ? '+' : ''
      toast.success(t('products:messages.adjust_success', { change: `${qtyChangeStr}${data.quantity_change ?? 0}` }))
      setSelectedProduit(prev => prev ? { ...prev, stock: (prev.stock ?? 0) + (data.quantity_change ?? 0), stock_reserve: (prev.stock_reserve ?? 0) + ((data as unknown as Record<string, number>).reserve_change ?? 0) } : null)
      setIsAdjustOpen(false)
      refetch()
    } catch (err) {
      toast.error(getApiErrorDetail(err, t('products:messages.adjust_error', { defaultValue: 'Erreur lors de l\u00e9ajustement' })))
    }
  }

  const handleStockAdjustmentSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (!selectedProduit) return
    if (!user?.is_superuser && !user?.profile?.can_adjust_stock && !user?.can_adjust_stock) {
      toast.error(t('products:messages.access_denied_adjust', { defaultValue: 'Acc\u00e8s refus\u00e9' })); return
    }
    setIsAdjustOpen(false)
    setPasswordConfig({
      title: t('products:messages.password_confirm_adjust_title', { defaultValue: 'Confirmation' }),
      message: t('products:messages.password_confirm_adjust_body', {
        name: selectedProduit.name,
        oldStock: selectedProduit.stock,
        newStock: adjustForm.new_quantity,
        defaultValue: 'Confirmer ajustement'
      })
    })
    pendingActionRef.current = handleStockAdjustment
    setIsPasswordOpen(true)
  }

  const handleToggleActive = async (produit: ProduitModel) => {
    try {
      const response = await api.post(`produits/${produit.id}/toggle_active/`)
      const isActive = response.data.is_active
      toast.success(isActive ? t('products:messages.status_reactivated', { defaultValue: 'Produit r\u00e9activ\u00e9' }) : t('products:messages.status_hidden', { defaultValue: 'Produit masqu\u00e9' }))
      setSelectedProduit(prev => prev ? { ...prev, is_active: isActive } : null)
      refetch()
    } catch (err) { toast.error(getApiErrorDetail(err, t('products:messages.status_error', { defaultValue: 'Erreur' }))) }
  }

  const handleGenerateLabels = async (produit: ProduitModel) => {
    const qtyStr = prompt(t('products:messages.labels_prompt', { name: produit.name, defaultValue: `Quantit\u00e9 \u00e9tiquettes pour ${produit.name}` }), "1")
    if (!qtyStr) return
    const quantity = parseInt(qtyStr, 10)
    if (isNaN(quantity) || quantity <= 0) { toast.error(t('products:messages.invalid_quantity', { defaultValue: 'Quantit\u00e9 invalide' })); return }
    try {
      const resp = await api.post('produits/generate_labels/', { products: [{ id: produit.id, quantity }] }, { responseType: 'blob' })
      const url = window.URL.createObjectURL(new Blob([resp.data]))
      const link = document.createElement('a'); link.href = url; link.setAttribute('download', `etiquettes_${produit.name}.pdf`)
      document.body.appendChild(link); link.click(); link.remove()
    } catch (err) { toast.error(getApiErrorDetail(err, t('products:messages.generation_error', { defaultValue: 'Erreur g\u00e9n\u00e9ration' }))) }
  }

  const handleTransferToRayon = async (produit: ProduitModel) => {
    if (!produit.has_reserve_storage || (produit.stock_reserve ?? 0) <= 0) return
    const needed = Math.max(0, (produit.capacite_rayon ?? 0) - (produit.stock ?? 0))
    const suggest = Math.min(needed, produit.stock_reserve ?? 0)
    const qtyStr = prompt(t('products:messages.transfer_prompt', { reserve: produit.stock_reserve, capacity: produit.capacite_rayon, needed, defaultValue: 'Quantit\u00e9 \u00e0 transf\u00e9rer ?' }), String(suggest))
    if (qtyStr === null) return
    const qty = parseInt(qtyStr, 10)
    if (isNaN(qty) || qty <= 0) { toast.error(t('products:messages.invalid_quantity', { defaultValue: 'Quantit\u00e9 invalide' })); return }
    setTransferLoading(true)
    try {
      await api.post(`produits/${produit.id}/transfer_to_shelf/`, { quantity: qty })
      toast.success(t('products:messages.transfer_success', { count: qty, defaultValue: `${qty} unit\u00e9s transf\u00e9r\u00e9es` }))
      refetch()
    } catch (err) {
      toast.error(getApiErrorDetail(err, t('products:messages.transfer_error', { defaultValue: 'Erreur transfert' })))
    } finally { setTransferLoading(false) }
  }

  const handleMovementClick = async (item: { facture?: number; commande?: number; type?: string }) => {
    if (item.facture && (item.type === 'SORTIE' || item.type === 'RETOUR')) {
      try {
        await api.get(`factures/${item.facture}/`)
        toast.success(t('products:messages.facture_loaded', { defaultValue: 'Facture #' + item.facture }))
      } catch {
        toast.error(t('products:messages.facture_load_error', { defaultValue: 'Erreur chargement facture' }))
      }
    } else if (item.commande) {
      navigate('/app/commandes', { state: { openDetailsId: item.commande } })
    }
  }

  const handleOpenEdit = (produit: ProduitModel) => {
    setEditForm({
      id: produit.id,
      name: produit.name,
      stock: String(produit.stock ?? ''),
      cost_price: String(produit.cost_price ?? ''),
      selling_price: String(produit.selling_price ?? ''),
      cip1: produit.cip1 || '',
      cip2: produit.cip2 || '',
      cip3: produit.cip3 || '',
      expire_date: produit.expire_date || '',
      stock_alert: String(produit.stock_alert ?? '0'),
      stock_minimum: String(produit.stock_minimum ?? '0'),
      stock_maximum: String(produit.stock_maximum ?? '0'),
      tva: produit.tva || '19.25',
      rayon: produit.rayon ? String(produit.rayon) : '',
      fournisseur: produit.fournisseur ? String(produit.fournisseur) : '',
      forme: produit.forme ? String(produit.forme) : '',
      use_lot_management: produit.use_lot_management ?? true,
      requires_prescription: produit.requires_prescription ?? false,
      surveillance_category: produit.surveillance_category || 'NONE',
      is_supplier_exclusive: produit.is_supplier_exclusive ?? false,
      has_reserve_storage: produit.has_reserve_storage ?? false,
      capacite_rayon: String(produit.capacite_rayon ?? '0'),
      min_rayon: String(produit.min_rayon ?? '0'),
      message_alerte: produit.message_alerte || ''
    })
    setIsEditOpen(true)
  }

  const resetFilters = () => {
    setSearchQuery('')
    setFilterRayon('')
    setFilterFournisseur('')
    setShowInactive(false)
    setShowInStockOnly(false)
  }

  const isAllSelected = selectedIds.length === produits.length && produits.length > 0
  const isPartial = selectedIds.length > 0 && selectedIds.length < produits.length

  /* ÔöÇÔöÇ Keyboard nav ÔöÇÔöÇ */
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const el = document.activeElement as HTMLElement
      if (el?.tagName === 'TEXTAREA' || (el?.tagName === 'INPUT' && el.getAttribute('type') !== 'text')) return
      if (e.key === 'Enter' && selectedProduit) {
        e.preventDefault()
        setSelectedIds(prev => prev.includes(selectedProduit.id) ? prev.filter(id => id !== selectedProduit.id) : [...prev, selectedProduit.id])
        return
      }
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        if (!produits.length) return
        const idx = selectedProduit ? produits.findIndex(p => p.id === selectedProduit.id) : -1
        const next = e.key === 'ArrowDown'
          ? (idx < produits.length - 1 ? idx + 1 : 0)
          : (idx > 0 ? idx - 1 : produits.length - 1)
        const p = produits[next]
        if (p) { setSelectedProduit(p); document.querySelector(`tr[data-product-id="${p.id}"]`)?.scrollIntoView({ block: 'nearest', behavior: 'smooth' }) }
        e.preventDefault()
      }
    }
    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [produits, selectedProduit])

  /* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
  /*  RENDER                                                         */
  /* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
  return (
    <div className="flex-1 flex flex-col overflow-hidden bg-slate-50">

      {/* ÔöÇÔöÇ Header ÔöÇÔöÇ */}
      <header className="px-6 py-4 border-b border-slate-200 bg-white shrink-0 flex flex-col sm:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="p-2.5 bg-emerald-50 rounded-xl">
            <Package className="size-5 text-emerald-600" />
          </div>
          <div>
            <h1 className="text-lg font-bold text-slate-900">{t('products:title', { defaultValue: 'Gestion des produits' })}</h1>
            <p className="text-xs text-slate-400 font-medium">{t('products:subtitle', { defaultValue: 'Cr├®ez et g├®rez vos produits et services' })}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={() => refetch()} disabled={isLoading} leftIcon={isLoading ? <RefreshCw className="size-4 animate-spin" /> : <RefreshCw className="size-4" />}>
            {t('common:actions.refresh', { defaultValue: 'Rafra├«chir' })}
          </Button>
          <Button variant="primary" size="sm" leftIcon={<Package className="size-4" />} onClick={() => setIsCreateOpen(true)}>
            {t('products:actions.new', { defaultValue: 'Nouveau' })}
          </Button>
          <Button variant="outline" size="sm" leftIcon={<Upload className="size-4" />} onClick={() => {}}>
            {t('products:import.title', { defaultValue: 'Importer' })}
          </Button>
        </div>
      </header>

      {/* ÔöÇÔöÇ Error Banner ÔöÇÔöÇ */}
      {error && (
        <div className="mx-6 mt-4 p-3 bg-red-50 border border-red-200 rounded-xl text-red-700 text-sm flex items-center gap-2">
          <AlertTriangle className="size-4" />
          {error}
        </div>
      )}

      {/* ÔöÇÔöÇ Main Content ÔöÇÔöÇ */}
      <main className="flex-1 p-4 min-h-0 overflow-hidden">
        <div className="grid grid-cols-1 xl:grid-cols-12 gap-4 h-full min-h-0 w-full overflow-hidden">

          {/* ÔòÉÔòÉÔòÉÔòÉÔòÉ Left Panel : List ÔòÉÔòÉÔòÉÔòÉÔòÉ */}
          <section className="xl:col-span-5 flex flex-col h-full min-h-0 gap-3">

            {/* Search & Filters */}
            <Card variant="default" padding="md" className="shrink-0">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-slate-400" />
                <Input
