            {/* Table */}
            <Card variant="default" padding="none" className="flex-1 min-h-0 flex flex-col overflow-hidden">
              {/* Table Header */}
              <div className="shrink-0 px-4 py-3 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
