const prefetchedRoutes = new Set<string>();
function handleRoutePrefetch(path: string) {
  if (prefetchedRoutes.has(path)) return;
  const factory = routePrefetchMap[path];
  if (factory) {
    prefetchedRoutes.add(path);
    prefetchRoute(factory);
  }
}


