}

// Constante de module pour ├®viter la recr├®ation ├á chaque render
const EMPTY_PRODUCTS_LIST: ProduitModel[] = []

/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ
   STORAGE KEY
   ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
const LABEL_CONFIG_KEY = 'zenith_label_fields_config:v1'
const LABEL_FORMAT_KEY = 'zenith_label_format:v1'
const LABEL_BARCODE_TYPE_KEY = 'zenith_label_barcode_type:v1'
const LEGACY_LABEL_CONFIG_KEY = 'zenith_label_fields_config'

function loadBarcodeType(): 'CODE128' | 'DATAMATRIX' {
  try {
    const saved = localStorage.getItem(LABEL_BARCODE_TYPE_KEY)
    if (saved === 'DATAMATRIX') return 'DATAMATRIX'
  } catch { /* ignore */ }
  return 'CODE128'
}

/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ
   DEFAULT FIELDS LOADER (Internal keys)
   ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
const FIELD_KEYS = [
  { key: 'productName', icon: '­ƒôª' },
  { key: 'rayon', icon: '­ƒôì' },
  { key: 'barcode', icon: 'Ôû«Ôû»Ôû«Ôû»' },
  { key: 'sellingPrice', icon: '­ƒÆ░' },
  { key: 'pharmacyName', icon: '­ƒÅÑ' },
  { key: 'fournisseur', icon: '­ƒÜÜ' },
  { key: 'dateEntree', icon: '­ƒôà' },
  { key: 'dateExpiration', icon: 'ÔÅ│' },
  { key: 'orderNumber', icon: '­ƒôï' },
  { key: 'lot', icon: '­ƒÅÀ´©Å' },
  { key: 'invoiceNumber', icon: '­ƒº¥' },
]

function loadFieldsConfig(): Partial<LabelField>[] {
  try {
    const saved = localStorage.getItem(LABEL_CONFIG_KEY)
    if (saved) return JSON.parse(saved)

    // Migration cl├® non versionn├®e -> versionn├®e
    const legacy = localStorage.getItem(LEGACY_LABEL_CONFIG_KEY)
    if (legacy) {
      const parsed = JSON.parse(legacy)
      localStorage.setItem(LABEL_CONFIG_KEY, legacy)
      localStorage.removeItem(LEGACY_LABEL_CONFIG_KEY)
      return parsed
    }
  } catch { /* ignore */ }
  return []
}

function loadFormat(): '40x20' | '30x15' {
  try {
    const saved = localStorage.getItem(LABEL_FORMAT_KEY)
    if (saved === '30x15') return '30x15'
  } catch { /* ignore */ }
  return '40x20'
}

/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ
   BARCODE COMPONENTS
   ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
function BarcodeCanvas({ value, height, width }: { value: string; height: number; width: number }) {
  const svgRef = useRef<SVGSVGElement>(null)

  useEffect(() => {
    if (svgRef.current && value) {
      try {
        JsBarcode(svgRef.current, value, {
          format: 'CODE128',
          width: 1.2,
          height: height + 4,
          displayValue: true,
          fontSize: 8,
          margin: 0,
          textMargin: 1,
          font: 'monospace',
        })
      } catch {
        if (svgRef.current) svgRef.current.innerHTML = ''
      }
    }
  }, [value, height, width])

  if (!value) return null
  return <svg ref={svgRef} style={{ maxWidth: width }} />
}

function DatamatrixCanvas({ cip, lot, expiration, size }: { cip: string; lot: string; expiration: string; size: number }) {
  const canvasRef = useRef<HTMLCanvasElement>(null)

  // Construit la cha├«ne GS1 Datamatrix : 01<CIP13 padded to 14> 10<LOT> 17<YYMMDD>
  const gs1Data = (() => {
    const gtin = cip.length === 13 ? '0' + cip : cip.padStart(14, '0')
    let s = `(01)${gtin}`
    if (lot) s += `(10)${lot}`
    if (expiration) {
      try {
        const d = new Date(expiration)
        const yy = String(d.getFullYear()).slice(-2)
        const mm = String(d.getMonth() + 1).padStart(2, '0')
        const dd = String(d.getDate()).padStart(2, '0')
        s += `(17)${yy}${mm}${dd}`
      } catch { /* ignore */ }
    }
    return s
  })()

  useEffect(() => {
    if (!canvasRef.current || !cip) return
    try {
      bwipjs.toCanvas(canvasRef.current, {
        bcid: 'datamatrix',
        text: gs1Data,
        scale: 2,
        height: Math.round(size / 3.78), // px ÔåÆ mm approx
        width: Math.round(size / 3.78),
        parsefnc: true,
      })
    } catch { /* ignore */ }
  }, [gs1Data, size])

  if (!cip) return null
  return <canvas ref={canvasRef} style={{ width: size, height: size }} />
}

/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ
   LABEL PREVIEW COMPONENT 
   ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
function LabelPreview({
  label,
  fields,
  format,
  barcodeType,
  t,
}: {
  label: LabelData
  fields: LabelField[]
  format: '40x20' | '30x15'
  barcodeType: 'CODE128' | 'DATAMATRIX'
  t: unknown
}) {
  const isEnabled = (key: string) => fields.find(f => f.key === key)?.enabled ?? false
  const isCompact = format === '30x15'

  return (
    <div
      className="label-item"
      style={{
        width: isCompact ? '30mm' : '40mm',
        height: isCompact ? '15mm' : '20mm',
        padding: isCompact ? '0.8mm 1mm' : '1mm 1.2mm',
        border: '0.3px solid #ccc',
        borderRadius: '1px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'flex-start',
        overflow: 'hidden',
        fontFamily: "'Inter', 'Helvetica Neue', Arial, sans-serif",
        background: '#fff',
        color: '#000',
        boxSizing: 'border-box',
        pageBreakAfter: 'always',
        breakAfter: 'page',
      }}
    >
      {/* Top zone: pharmacy + product name */}
      <div style={{ lineHeight: 1.15 }}>
        {isEnabled('pharmacyName') && label.pharmacyName && (
          <div style={{
            fontSize: isCompact ? '4.5pt' : '5pt',
            fontWeight: 800,
            textTransform: 'uppercase',
            letterSpacing: '0.02em',
            color: '#333',
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            textAlign: 'center',
          }}>
            {label.pharmacyName}
          </div>
        )}
        {isEnabled('productName') && (
          <div style={{
            fontSize: isCompact ? '5pt' : '6pt',
            fontWeight: 900,
            lineHeight: 1.1,
            marginTop: '0.3mm',
            display: '-webkit-box',
            WebkitLineClamp: 2,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            wordBreak: 'break-word',
          }}>
            {label.productName}
          </div>
        )}
      </div>

      {/* Middle zone: barcode / datamatrix */}
      {isEnabled('barcode') && label.barcode && (
        <div style={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          margin: '0.2mm 0',
          flexShrink: 1,
          overflow: 'hidden',
          minHeight: 0,
        }}>
          {barcodeType === 'DATAMATRIX'
            ? <DatamatrixCanvas
                cip={label.cip}
                lot={label.lot}
                expiration={label.dateExpiration}
                size={isCompact ? 28 : 36}
              />
            : <BarcodeCanvas
                value={label.barcode}
                height={isCompact ? 7 : 10}
                width={isCompact ? 80 : 110}
              />
          }
        </div>
      )}

      {/* Bottom zone: metadata row */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'flex-end',
        gap: '0.5mm',
        lineHeight: 1,
      }}>
        {/* Left: metadata stacked */}
        <div style={{ flex: 1, minWidth: 0 }}>
          {/* Row 1: Rayon & Lot */}
          {(isEnabled('rayon') || isEnabled('lot')) && (
            <div style={{ fontSize: isCompact ? '3.5pt' : '4pt', color: '#444', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {isEnabled('rayon') && label.rayon ? `${t('prefixes.rayon')}:${label.rayon} ` : ''}
              {isEnabled('lot') && label.lot ? `${t('prefixes.lot')}:${label.lot}` : ''}
            </div>
          )}
          
          {/* Row 2: Entry Date */}
          {isEnabled('dateEntree') && label.dateEntree && (
            <div style={{ fontSize: isCompact ? '3.5pt' : '4pt', fontWeight: 600, color: '#444' }}>
              {label.dateEntree}
            </div>
          )}
          
          {/* Row 3: Expiration Date */}
          {isEnabled('dateExpiration') && label.dateExpiration && (
            <div style={{ fontSize: isCompact ? '3.5pt' : '4.5pt', fontWeight: 700, color: '#c00' }}>
              {t('prefixes.expiration')}:{label.dateExpiration}
            </div>
          )}
          
          {/* Row 4: Fournisseur */}
          {isEnabled('fournisseur') && label.fournisseur && (
            <div style={{ fontSize: isCompact ? '3.5pt' : '4pt', color: '#666', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {label.fournisseur}
            </div>
          )}

          {/* Row 5: CMD & Invoice */}
          {(isEnabled('orderNumber') || isEnabled('invoiceNumber')) && (
            <div style={{ fontSize: isCompact ? '3.5pt' : '4pt', color: '#777', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {isEnabled('orderNumber') && label.orderNumber ? `${t('prefixes.order')}:${label.orderNumber} ` : ''}
              {isEnabled('invoiceNumber') && label.invoiceNumber ? `${t('prefixes.invoice')}:${label.invoiceNumber}` : ''}
            </div>
          )}
        </div>

        {/* Right: price */}
        {isEnabled('sellingPrice') && (
          <div style={{
            fontSize: isCompact ? '7pt' : '8pt',
            fontWeight: 900,
            whiteSpace: 'nowrap',
            flexShrink: 0,
            textAlign: 'right',
          }}>
            {label.sellingPrice.toLocaleString('fr-FR', { maximumFractionDigits: 0 })}{t('common:currency_symbol', { defaultValue: 'F' })}
          </div>
        )}
      </div>
    </div>
  )
}

/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ
   PREVIEW WRAPPER (Handles scaling correctly)
   ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
function PreviewLabelWrapper({
  label,
  fields,
  format,
  barcodeType,
  t,
  scale = 2.0,
}: {
  label: LabelData
  fields: LabelField[]
  format: '40x20' | '30x15'
  barcodeType: 'CODE128' | 'DATAMATRIX'
  t: unknown
  scale?: number
}) {
  const isCompact = format === '30x15'
  const baseW = isCompact ? 30 : 40 // mm
  const baseH = isCompact ? 15 : 20 // mm

  return (
    <div
      className="label-preview-container"
      style={{
        width: `${baseW * scale}mm`,
        height: `${baseH * scale}mm`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
        overflow: 'hidden',
        borderRadius: '4px',
        boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
        flexShrink: 0,
      }}
    >
      <div
        style={{
          transform: `scale(${scale})`,
          transformOrigin: 'center center',
          width: `${baseW}mm`,
          height: `${baseH}mm`,
        }}
      >
        <LabelPreview label={label} fields={fields} format={format} barcodeType={barcodeType} t={t} />
      </div>
    </div>
  )
}

/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ
   MAIN MODAL COMPONENT
   ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
export default function SimplePrintLabelsModal({
  commandeId,
  commandeNumero,
  commande,
  produitsList = EMPTY_PRODUCTS_LIST,
  selectedRows,
  onClose,
}: SimplePrintLabelsModalProps) {
  const { t } = useTranslation(['labels', 'common'])
  const { settings: pharmacySettings } = usePharmacySettings()

  // Initialize and merge fields with current language
  const [fields, setFields] = useState<LabelField[]>(() => {
    const saved = loadFieldsConfig()
    return FIELD_KEYS.map(f => {
      const savedField = saved.find(s => s.key === f.key)
      return {
        key: f.key,
        icon: f.icon,
        label: t(`fields.${f.key}`),
        enabled: savedField ? savedField.enabled : (f.key !== 'orderNumber' && f.key !== 'invoiceNumber')
      }
    }) as LabelField[]
  })

  // Update labels if language changes
  useEffect(() => {
    setFields(prev => prev.map(f => ({ ...f, label: t(`fields.${f.key}`) })))
  }, [t])

  const [labelFormat, setLabelFormat] = useState<'40x20' | '30x15'>(loadFormat)
  const [barcodeType, setBarcodeType] = useState<'CODE128' | 'DATAMATRIX'>(loadBarcodeType)
  const [qtyMode, setQtyMode] = useState<'received' | 'fixed'>('received')
  const [fixedQty, setFixedQty] = useState(1)
  const [printing, setPrinting] = useState(false)

  const [showConfig, setShowConfig] = useState(false)

  // Persist config to localStorage
  useEffect(() => {
    localStorage.setItem(LABEL_CONFIG_KEY, JSON.stringify(fields))
  }, [fields])

  useEffect(() => {
    localStorage.setItem(LABEL_FORMAT_KEY, labelFormat)
  }, [labelFormat])

  useEffect(() => {
    localStorage.setItem(LABEL_BARCODE_TYPE_KEY, barcodeType)
  }, [barcodeType])

  const toggleField = (key: string) => {
    setFields(prev =>
      prev.map(f => (f.key === key ? { ...f, enabled: !f.enabled } : f))
    )
  }

  // ÔöÇÔöÇÔöÇ Drag & Drop for reordering ÔöÇÔöÇÔöÇ
  const dragIndexRef = useRef<number | null>(null)
  const [dragOverIndex, setDragOverIndex] = useState<number | null>(null)

  const handleDragStart = (index: number) => {
    dragIndexRef.current = index
  }

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault()
    if (dragIndexRef.current === null || dragIndexRef.current === index) return
    setDragOverIndex(index)
  }

  const handleDrop = (e: React.DragEvent, dropIndex: number) => {
    e.preventDefault()
    const dragIndex = dragIndexRef.current
    if (dragIndex === null || dragIndex === dropIndex) {
      dragIndexRef.current = null
      setDragOverIndex(null)
      return
    }
    setFields(prev => {
      const updated = [...prev]
      const [dragged] = updated.splice(dragIndex, 1)
      updated.splice(dropIndex, 0, dragged)
      return updated
    })
    dragIndexRef.current = null
    setDragOverIndex(null)
  }

  const handleDragEnd = () => {
    dragIndexRef.current = null
    setDragOverIndex(null)
  }

  /* ÔöÇÔöÇÔöÇ Build label data from commande ÔöÇÔöÇÔöÇ */
  const labelsData: LabelData[] = (() => {
    if (!commande?.produits) return []

    const result: LabelData[] = []
    const produitsMap = new Map(produitsList.map(p => [p.id, p]))

    // Si des produits sont s├®lectionn├®s (checkbox), ne g├®n├®rer que pour ceux-l├á
    const produits = selectedRows && selectedRows.size > 0
      ? commande.produits.filter((_, idx) => selectedRows.has(idx))
      : commande.produits

    for (const item of produits) {
      const isObj = item.produit && typeof item.produit === 'object'
      const produitObj = isObj ? (item.produit as ProduitModel) : null
      const produitId = isObj ? produitObj!.id : (item.produit as number)

      // Resolve product data
      const resolved = produitObj || produitsMap.get(produitId)

      const productName =
        (item as unknown).produit_nom ||
        resolved?.name ||
        `Produit #${produitId}`

      const cip =
        (item as unknown).produit_cip ||
        resolved?.cip1 ||
        resolved?.cip2 ||
        resolved?.cip3 ||
        ''

      const rayon = resolved?.rayon_name || ''

      const barcode = cip || String(produitId).padStart(8, '0')

      const sellingPrice = item.selling_price
        ? parseFloat(item.selling_price)
        : resolved?.selling_price
          ? parseFloat(resolved.selling_price)
          : 0

      const lot = item.lot || ''
      // Date de p├®remption ÔÇö forcer le format MM/YY
      const dateExpiration = (() => {
        const raw = item.date_expiration || ''
        if (!raw) return ''
        // Si c'est d├®j├á MM/YY (ex: 03/27), on garde
        if (/^\d{2}\/\d{2}$/.test(raw)) return raw
        // Sinon essaye de parser (ISO YYYY-MM-DD)
        try {
          const d = new Date(raw)
          if (isNaN(d.getTime())) return raw
          const mm = String(d.getMonth() + 1).padStart(2, '0')
          const yy = String(d.getFullYear()).slice(-2)
          return `${mm}/${yy}`
        } catch {
          return raw
        }
      })()

      const orderNumber = `#${commande.id}`
      const invoiceNumber = commande.numero_facture || ''
      const pharmacyName = pharmacySettings?.pharmacy_name || 'PHARMACIE'

      // Date d'entr├®e = date de cl├┤ture de la commande (r├®ception effective) ou date du jour
      const refDate = (commande as unknown).date_cloture || commande.date || new Date().toISOString()
      const dateEntree = (() => {
        try {
          const d = new Date(refDate)
          return d.toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: '2-digit' })
        } catch {
          return ''
        }
      })()

      // Fournisseur
      const fournisseur =
        (commande as unknown).fournisseur_nom ||
        resolved?.fournisseur_name ||
        ''

      const receivedTotal = (item.quantity || 0) + (item.unites_gratuites || 0)
      const copies = qtyMode === 'received' ? receivedTotal : fixedQty

      for (let i = 0; i < copies; i++) {
        result.push({
          productName,
          cip,
          rayon,
          barcode,
          sellingPrice,
          pharmacyName,
          orderNumber,
          lot,
          invoiceNumber,
          dateEntree,
          dateExpiration,
          fournisseur,
          quantity: receivedTotal,
        })
      }
    }

    return result
  })()

  /* ÔöÇÔöÇÔöÇ Print handler ÔöÇÔöÇÔöÇ */
  const handlePrint = useCallback(() => {
    setPrinting(true)
    const isCompact = labelFormat === '30x15'
    const w = isCompact ? '30mm' : '40mm'
    const h = isCompact ? '15mm' : '20mm'

    // Build print-ready HTML
    const printWindow = window.open('about:blank', '_blank', 'width=600,height=800')
    if (!printWindow) {
      setPrinting(false)
      return
    }

    const labelsHTML = labelsData.map(label => {
      const isEnabled = (key: string) => fields.find(f => f.key === key)?.enabled ?? false
      const truncate = (s: string, max: number) => s.length > max ? s.slice(0, max - 2) + '..' : s

      // Build barcode / datamatrix SVG string
      let barcodeSvg = ''
      if (isEnabled('barcode') && label.barcode) {
        if (barcodeType === 'DATAMATRIX') {
          try {
            const gtin = label.cip.length === 13 ? '0' + label.cip : label.cip.padStart(14, '0')
            let gs1 = `(01)${gtin}`
            if (label.lot) gs1 += `(10)${label.lot}`
            if (label.dateExpiration) {
              const d = new Date(label.dateExpiration)
              if (!isNaN(d.getTime())) {
                const yy = String(d.getFullYear()).slice(-2)
                const mm = String(d.getMonth() + 1).padStart(2, '0')
                const dd = String(d.getDate()).padStart(2, '0')
                gs1 += `(17)${yy}${mm}${dd}`
              }
            }
            const size = isCompact ? 7 : 9
            const svgRaw = bwipjs.toSVG({ bcid: 'datamatrix', text: gs1, scale: 1, height: size, width: size, parsefnc: true })
            const svgMm = isCompact ? '7mm' : '9mm'
            barcodeSvg = svgRaw.replace('<svg ', `<svg style="width:${svgMm};height:${svgMm};display:block;" `)
          } catch { /* ignore */ }
        } else {
          try {
            const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
            JsBarcode(svg, label.barcode, {
              format: 'CODE128',
              width: isCompact ? 1 : 1.2,
              height: isCompact ? 10 : 14,
              displayValue: true,
              fontSize: isCompact ? 6 : 7,
              margin: 0,
              textMargin: 1,
              font: 'monospace',
            })
            barcodeSvg = svg.outerHTML
          } catch { /* ignore */ }
        }
      }

      const lines: string[] = []

      // Pharmacy name
      if (isEnabled('pharmacyName') && label.pharmacyName) {
        lines.push(`<div style="font-size:${isCompact ? '4.5pt' : '5pt'};font-weight:800;text-transform:uppercase;letter-spacing:0.02em;color:#333;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center;">${label.pharmacyName}</div>`)
      }

      // Product name
      if (isEnabled('productName')) {
        lines.push(`<div style="font-size:${isCompact ? '5pt' : '6pt'};font-weight:900;line-height:1.1;margin-top:0.3mm;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${label.productName}</div>`)
      }

      // Barcode
      if (barcodeSvg) {
        const barcodeMaxH = barcodeType === 'DATAMATRIX' ? (isCompact ? '6mm' : '8mm') : (isCompact ? '5mm' : '7mm')
        lines.push(`<div style="display:flex;justify-content:center;align-items:center;margin:0.1mm 0;flex-shrink:1;max-height:${barcodeMaxH};overflow:hidden;">${barcodeSvg}</div>`)
      }

      // Bottom row - Grouped version for space saving
      const leftRows: string[] = []
      
      // Group: Rayon + Lot
      if ((isEnabled('rayon') && label.rayon) || (isEnabled('lot') && label.lot)) {
        let txt = ""
        if (isEnabled('rayon') && label.rayon) txt += `${t('prefixes.rayon')}:${truncate(label.rayon, 12)} `
        if (isEnabled('lot') && label.lot) txt += `${t('prefixes.lot')}:${truncate(label.lot, 10)}`
        leftRows.push(`<div style="font-size:${isCompact ? '4.5pt' : '5.5pt'};font-weight:700;color:#111;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${txt}</div>`)
      }

      if (isEnabled('dateEntree') && label.dateEntree) {
        leftRows.push(`<div style="font-size:${isCompact ? '4.5pt' : '5.5pt'};font-weight:700;color:#111;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${label.dateEntree}</div>`)
      }
      if (isEnabled('dateExpiration') && label.dateExpiration) {
        leftRows.push(`<div style="font-size:${isCompact ? '3.5pt' : '4.5pt'};font-weight:700;color:#c00;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${t('prefixes.expiration')}:${label.dateExpiration}</div>`)
      }
      if (isEnabled('fournisseur') && label.fournisseur) {
        leftRows.push(`<div style="font-size:${isCompact ? '4pt' : '5pt'};font-weight:600;color:#333;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${truncate(label.fournisseur, 15)}</div>`)
      }

      // Group: Order + Invoice
      if ((isEnabled('orderNumber') && label.orderNumber) || (isEnabled('invoiceNumber') && label.invoiceNumber)) {
        let txt = ""
        if (isEnabled('orderNumber') && label.orderNumber) txt += `${t('prefixes.order')}:${label.orderNumber} `
        if (isEnabled('invoiceNumber') && label.invoiceNumber) txt += `${t('prefixes.invoice')}:${truncate(label.invoiceNumber, 10)}`
        leftRows.push(`<div style="font-size:${isCompact ? '3.5pt' : '4pt'};color:#777;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${txt}</div>`)
      }

      const priceVal = label.sellingPrice.toLocaleString('fr-FR', { maximumFractionDigits: 0 })
      const priceFontSize = priceVal.length > 7
        ? (isCompact ? '5.5pt' : '6.5pt')
        : priceVal.length > 5
          ? (isCompact ? '6pt' : '7pt')
          : (isCompact ? '7pt' : '8pt')
      const priceHtml = isEnabled('sellingPrice')
        ? `<div style="font-size:${priceFontSize};font-weight:900;white-space:nowrap;flex-shrink:0;text-align:right;max-width:45%;overflow:hidden;text-overflow:ellipsis;">${priceVal}${t('common:currency_symbol', { defaultValue: 'F' })}</div>`
        : ''

      const bottomRow = `<div style="display:flex;justify-content:space-between;align-items:flex-end;gap:0.5mm;line-height:1.0;">
        <div style="flex:1;min-width:0;overflow:hidden;">${leftRows.join('')}</div>
        ${priceHtml}
      </div>`

      lines.push(bottomRow)

      return `<div class="label" style="padding:${isCompact ? '0.8mm 1mm' : '1mm 1.2mm'};border:0.3px solid #ccc;border-radius:1px;display:flex;flex-direction:column;justify-content:flex-start;overflow:hidden;font-family:'Inter','Helvetica Neue',Arial,sans-serif;background:#fff;color:#000;box-sizing:border-box;page-break-after:always;break-after:page;">
        ${lines.join('')}
      </div>`
    }).join('\n')

    printWindow.document.write(`<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>${t('modal_title')} - ${commandeNumero}</title>
  <style>
    /* Local Fonts (Offline Support) */
    @font-face {
      font-family: 'Inter';
      src: url('/fonts/inter-400.woff2') format('woff2');
      font-weight: 400;
      font-style: normal;
      font-display: block;
    }
    @font-face {
      font-family: 'Inter';
      src: url('/fonts/inter-600.woff2') format('woff2');
      font-weight: 600;
      font-style: normal;
      font-display: block;
    }
    @font-face {
      font-family: 'Inter';
      src: url('/fonts/inter-800.woff2') format('woff2');
      font-weight: 800;
      font-style: normal;
      font-display: block;
    }
    @font-face {
      font-family: 'Inter';
      src: url('/fonts/inter-900.woff2') format('woff2');
      font-weight: 900;
      font-style: normal;
      font-display: block;
    }

    @page {
      size: ${w} ${h} landscape;
      margin: 0;
    }
    @media print {
      @page {
        size: ${w} ${h} landscape;
        margin: 0;
      }
    }
    * { 
      margin: 0; 
      padding: 0; 
      box-sizing: border-box; 
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      text-rendering: optimizeLegibility;
    }
    body {
      font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
      background: #fff;
    }
    .label {
      page-break-after: always;
      break-after: page;
      position: relative;
    }
    .label:last-child {
      page-break-after: auto;
      break-after: auto;
    }
    @media print {
      body { margin: 0; padding: 0; }
      .label { border: none !important; }
    }
  </style>
</head>
<body>
${labelsHTML}
</body>
</html>`)

    printWindow.document.close()

    // Function to trigger printing
    const triggerPrint = () => {
      printWindow.focus()
      printWindow.print()
      setTimeout(() => {
        setPrinting(false)
        onClose()
        printWindow.close()
      }, 500)
    }

    // Wait for fonts to be ready
    if ((printWindow.document as unknown).fonts) {
      (printWindow.document as unknown).fonts.ready.then(() => {
        // Small delay to ensure browser layout engine catch up
        setTimeout(triggerPrint, 500)
      })
    } else {
      setTimeout(triggerPrint, 1000)
    }
  }, [labelsData, fields, labelFormat, commandeNumero, onClose])

  /* ÔöÇÔöÇÔöÇ PDF backend print handler ÔöÇÔöÇÔöÇ */
  const handlePrintPDF = useCallback(() => {
    const format = labelFormat === '30x15' ? '30x15' : '40x20'
    const url = `${window.location.origin}/api/commandes/${commandeId}/imprimer_etiquettes/?format=${format}`
    window.open(url, '_blank')
  }, [commandeId, labelFormat])

  const enabledFieldsCount = fields.filter(f => f.enabled).length

  return (
    <PremiumModal
      isOpen={true}
      onClose={onClose}
      title={t('modal_title')}
      subtitle={t('subtitle', { numero: commandeNumero })}
      icon={
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-primary" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z" />
        </svg>
      }
      gradientFrom="primary/10"
      gradientTo="info/10"
      disableClose={printing}
    >
      <div className="p-5 space-y-4">

        {/* ÔöÇÔöÇ Format Selection ÔöÇÔöÇ */}
        <div>
          <label className="block text-xs font-bold uppercase tracking-wider text-base-content/40 mb-2.5">{t('format_label')}</label>
          <div className="flex gap-3">
            <label className={`label cursor-pointer gap-2 border rounded-xl p-3 flex-1 transition-all ${labelFormat === '40x20' ? 'border-primary bg-primary/5 shadow-sm' : 'hover:bg-base-200'}`}>
              <input
                type="radio"
                name="format"
                className="radio radio-primary radio-sm"
                checked={labelFormat === '40x20'}
                onChange={() => setLabelFormat('40x20')}
              />
              <div className="flex-1">
                <span className="label-text font-semibold text-sm">40├ù20mm</span>
                <p className="text-xs text-base-content/50">{t('format_standard')}</p>
              </div>
            </label>
            <label className={`label cursor-pointer gap-2 border rounded-xl p-3 flex-1 transition-all ${labelFormat === '30x15' ? 'border-primary bg-primary/5 shadow-sm' : 'hover:bg-base-200'}`}>
              <input
                type="radio"
                name="format"
                className="radio radio-primary radio-sm"
                checked={labelFormat === '30x15'}
                onChange={() => setLabelFormat('30x15')}
              />
              <div className="flex-1">
                <span className="label-text font-semibold text-sm">30├ù15mm</span>
                <p className="text-xs text-base-content/50">{t('format_compact')}</p>
              </div>
            </label>
          </div>
        </div>

        {/* ÔöÇÔöÇ Barcode Type Selection ÔöÇÔöÇ */}
        <div>
          <label className="block text-xs font-bold uppercase tracking-wider text-base-content/40 mb-2.5">
            Type de code-barres
          </label>
          <div className="flex gap-3">
            <label className={`label cursor-pointer gap-2 border rounded-xl p-3 flex-1 transition-all ${barcodeType === 'CODE128' ? 'border-primary bg-primary/5 shadow-sm' : 'hover:bg-base-200'}`}>
              <input
                type="radio"
                name="barcodeType"
                className="radio radio-primary radio-sm"
                checked={barcodeType === 'CODE128'}
                onChange={() => setBarcodeType('CODE128')}
              />
              <div className="flex-1">
                <span className="label-text font-semibold text-sm">Code-barres</span>
                <p className="text-xs text-base-content/50">CODE128 lin├®aire</p>
              </div>
            </label>
            <label className={`label cursor-pointer gap-2 border rounded-xl p-3 flex-1 transition-all ${barcodeType === 'DATAMATRIX' ? 'border-emerald-500 bg-emerald-50 shadow-sm' : 'hover:bg-base-200'}`}>
              <input
                type="radio"
                name="barcodeType"
                className="radio radio-sm"
                style={{ accentColor: '#10b981' }}
                checked={barcodeType === 'DATAMATRIX'}
                onChange={() => setBarcodeType('DATAMATRIX')}
              />
              <div className="flex-1">
                <span className="label-text font-semibold text-sm">Datamatrix</span>
                <p className="text-xs text-base-content/50">GS1 (CIP + lot + exp.)</p>
              </div>
            </label>
          </div>
        </div>

        {/* ÔöÇÔöÇ Configuration Toggle ÔöÇÔöÇ */}
        <div className="border border-base-200 rounded-xl overflow-hidden">
          <button
            type="button"
            className="w-full flex items-center justify-between p-3 hover:bg-base-50 transition-colors"
            onClick={() => setShowConfig(!showConfig)}
          >
            <div className="flex items-center gap-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-primary" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.066 2.573c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.573 1.066c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.066-2.573c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
              </svg>
              <span className="font-bold text-sm">{t('info_title')}</span>
              <span className="badge badge-primary badge-sm font-mono">{enabledFieldsCount}/{fields.length}</span>
            </div>
            <svg
              xmlns="http://www.w3.org/2000/svg"
              className={`h-4 w-4 transition-transform ${showConfig ? 'rotate-180' : ''}`}
              fill="none" viewBox="0 0 24 24" stroke="currentColor"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </button>

          {showConfig && (
            <div className="border-t border-base-200 p-3 space-y-0.5 bg-base-50/50">
              <div className="text-[10px] text-base-content/40 font-medium mb-2 flex items-center gap-1">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4" /></svg>
                {t('drag_info')}
              </div>
              {fields.map((field, index) => (
                <div
                  key={field.key}
                  draggable
                  onDragStart={() => handleDragStart(index)}
                  onDragOver={(e) => handleDragOver(e, index)}
                  onDrop={(e) => handleDrop(e, index)}
                  onDragEnd={handleDragEnd}
                  className={`flex items-center gap-2 p-2 rounded-lg transition-all select-none ${
                    dragOverIndex === index
                      ? 'border-2 border-primary border-dashed bg-primary/10 scale-[1.02]'
                      : field.enabled
                        ? 'bg-primary/5 border border-primary/15'
                        : 'hover:bg-base-200/80 border border-transparent'
                  }`}
                  style={{ cursor: 'grab' }}
                >
                  {/* Drag handle */}
                  <span className="text-base-content/30 hover:text-base-content/60 text-sm font-bold shrink-0" style={{ cursor: 'grab', lineHeight: 1 }}>
                    Ôá┐
                  </span>
                  <input
                    type="checkbox"
                    className="checkbox checkbox-primary checkbox-sm shrink-0"
                    checked={field.enabled}
                    onChange={() => toggleField(field.key)}
                    onClick={(e) => e.stopPropagation()}
                  />
                  <span className="text-base select-none shrink-0">{field.icon}</span>
                  <span className={`text-sm font-medium select-none flex-1 ${field.enabled ? 'text-base-content' : 'text-base-content/50'}`}>
                    {field.label}
                  </span>
                  <span className="text-[10px] text-base-content/25 font-mono shrink-0">{index + 1}</span>
                </div>
              ))}
              
              {/* Reset button */}
              <div className="pt-1.5 flex justify-end">
                <button
                  type="button"
                  className="btn btn-ghost btn-xs text-primary gap-1"
                  onClick={() => setFields(FIELD_KEYS.map(f => ({
                    key: f.key,
                    icon: f.icon,
                    label: t(`fields.${f.key}`),
                    enabled: f.key !== 'orderNumber' && f.key !== 'invoiceNumber'
                  })))}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                  </svg>
                  {t('common:reset_default', { defaultValue: 'Par d├®faut' })}
                </button>
              </div>
            </div>
          )}
        </div>

        {/* ÔöÇÔöÇ Selection indicator ÔöÇÔöÇ */}
        {selectedRows && selectedRows.size > 0 && (
          <div className="flex items-center gap-2 p-3 rounded-xl bg-info/10 border border-info/20">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-info shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span className="text-sm font-medium text-info">
              {t('common:selection_count', { count: selectedRows.size, total: commande?.produits?.length || 0, defaultValue: `${selectedRows.size} produit(s) s├®lectionn├®(s)` })}
            </span>
          </div>
        )}

        {/* ÔöÇÔöÇ Quantity Selection ÔöÇÔöÇ */}
        <div className="space-y-3">
          <label className="block text-xs font-bold uppercase tracking-wider text-base-content/40">{t('quantity_label', { defaultValue: 'Quantit├® d\'├®tiquettes' })}</label>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <label className={`label cursor-pointer items-start gap-3 border rounded-xl p-3 h-full transition-all ${qtyMode === 'received' ? 'border-primary bg-primary/5 shadow-sm' : 'hover:bg-base-200'}`}>
              <input
                type="radio"
                name="qtyMode"
                className="radio radio-primary radio-sm mt-1"
                checked={qtyMode === 'received'}
                onChange={() => setQtyMode('received')}
              />
              <div className="flex-1 min-w-0">
                <span className="label-text font-bold text-sm block whitespace-normal leading-tight">{t('qty.by_unit')}</span>
                <p className="text-[10px] text-base-content/50 mt-0.5 leading-snug whitespace-normal">{t('qty.received_desc', { defaultValue: 'Total unit├®s + gratuits' })}</p>
              </div>
            </label>

            <label className={`label cursor-pointer items-start gap-3 border rounded-xl p-3 h-full transition-all ${qtyMode === 'fixed' ? 'border-primary bg-primary/5 shadow-sm' : 'hover:bg-base-200'}`}>
              <input
                type="radio"
                name="qtyMode"
                className="radio radio-primary radio-sm mt-1"
                checked={qtyMode === 'fixed'}
                onChange={() => setQtyMode('fixed')}
              />
              <div className="flex-1 min-w-0">
                <span className="label-text font-bold text-sm block whitespace-normal leading-tight">{t('qty.fixed')}</span>
                <p className="text-[10px] text-base-content/50 mt-0.5 leading-snug whitespace-normal">{t('qty.fixed_desc', { defaultValue: 'Nombre identique par produit' })}</p>
              </div>
            </label>
          </div>

          {qtyMode === 'fixed' && (
            <div className="flex items-center gap-3 bg-base-100 border border-base-200 p-3 rounded-xl animate-in fade-in slide-in-from-top-1 duration-200">
              <span className="text-sm font-medium flex-1">{t('qty.fixed_count_label', { defaultValue: "Nombre d'├®tiquettes par produit :" })}</span>
              <div className="flex items-center gap-1">
                <button 
                  type="button"
                  className="btn btn-circle btn-ghost btn-xs"
                  onClick={() => setFixedQty(Math.max(0, fixedQty - 1))}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" /></svg>
                </button>
                <input
                  type="number"
                  min="0"
                  className="input input-bordered input-sm w-16 text-center font-bold"
                  value={fixedQty}
                  onChange={(e) => setFixedQty(Math.max(0, parseInt(e.target.value) || 0))}
                />
                <button 
                  type="button"
                  className="btn btn-circle btn-ghost btn-xs"
                  onClick={() => setFixedQty(fixedQty + 1)}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                </button>
              </div>
            </div>
          )}
        </div>

        {/* ÔöÇÔöÇ Preview ÔöÇÔöÇ */}
        {labelsData.length > 0 && (
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <label className="text-xs font-bold uppercase tracking-wider text-base-content/40">
                {t('preview')} ({labelsData.length})
              </label>
              <div className="badge badge-sm badge-outline text-[10px] text-base-content/50">Zoom 200%</div>
            </div>
            
            <div className="bg-base-300/30 rounded-2xl p-6 max-h-[400px] overflow-y-auto custom-scrollbar border border-base-content/5">
              <div className="grid grid-cols-1 gap-8 justify-items-center">
                {labelsData.slice(0, 10).map((label, i) => (
                  <PreviewLabelWrapper
                    key={label.cip || label.barcode || i}
                    label={label}
                    fields={fields}
                    format={labelFormat}
                    barcodeType={barcodeType}
                    t={t}
                    scale={1.8}
                  />
                ))}
              </div>
              
              {labelsData.length > 10 && (
                <div className="mt-6 flex flex-col items-center gap-2">
                  <div className="h-px w-12 bg-base-content/10"></div>
                  <span className="text-xs text-base-content/40 font-medium">
                    {t('qty.hidden_preview', { count: labelsData.length - 10, defaultValue: `+ ${labelsData.length - 10} autre(s) ├®tiqette(s) masqu├®e(s)` })}
                  </span>
                </div>
              )}
            </div>
          </div>
        )}

        {/* ÔöÇÔöÇ No data warning ÔöÇÔöÇ */}
        {labelsData.length === 0 && (
          <div className="alert alert-warning rounded-xl">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" className="stroke-current shrink-0 size-5">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
            </svg>
            <div className="text-sm">
              <p><strong>{t('no_data_title', { defaultValue: 'Aucune donn├®e produit disponible' })}</strong></p>
              <p className="text-xs mt-0.5">{t('no_data_desc', { defaultValue: 'Les donn├®es de la commande doivent ├¬tre charg├®es pour g├®n├®rer les ├®tiquettes.' })}</p>
            </div>
          </div>
        )}

        {/* ÔöÇÔöÇ Actions ÔöÇÔöÇ */}
        <div className="flex justify-end gap-3 pt-1">
          <button onClick={onClose} className="btn btn-ghost px-6 rounded-xl">
            {t('cancel')}
          </button>
          <button
            onClick={handlePrintPDF}
            className="btn btn-secondary px-6 rounded-xl gap-2"
            disabled={labelsData.length === 0}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            PDF
          </button>
          <button
            onClick={handlePrint}
            className="btn btn-primary px-8 rounded-xl shadow-lg shadow-primary/20 gap-2"
            disabled={printing || labelsData.length === 0}
          >
            {printing ? (
              <>
                <span className="loading loading-spinner loading-sm"></span>
                {t('generating')}
              </>
            ) : (
              <>
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                </svg>
                {t('print')} ({labelsData.length})
              </>
            )}
          </button>
        </div>
      </div>
    </PremiumModal>
  )
}

import { useState, useEffect, useMemo } from 'react';
import api from '../services/api';
import { formatCurrency } from '../utils/formatters';
import { getLocale } from '../utils/dateUtils';
import { useRecharts } from '../hooks/useRecharts';
import {
  useAnalyseFournisseurs,
  useComparaisonPrix,
  useRepartitionAchats
} from '../hooks/useFinanceStats';
import { useTranslation } from 'react-i18next';

interface StatsFournisseur {
  id: number;
  nom: string;
  ca_ttc: number;
  cout_achat: number;
  marge_brute: number;
  quantite_vendue: number;
}

const COLORS = [
  '#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d',
  '#3B82F6', '#EF4444', '#10B981', '#F59E0B', '#6366F1', '#EC4899',
  '#8B5CF6', '#14B8A6', '#F97316', '#06B6D4', '#84CC16', '#D946EF'
];

const formatDate = (date: Date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export default function StatistiquesFournisseur() {
  const { t, i18n } = useTranslation(['supplier_stats', 'common']);
  const [activeTab, setActiveTab] = useState('ventes');

  const [stats, setStats] = useState<StatsFournisseur[]>([]);
  const [loading, setLoading] = useState(false);
  const [dateDebut, setDateDebut] = useState(() => {
    const d = new Date();
    d.setDate(1); // 1er du mois
    return formatDate(d);
  });
  const [dateFin, setDateFin] = useState(() => {
    return formatDate(new Date());
  });

  // Hooks pour les nouvelles analyses
  const { data: supplierAnalysis, isLoading: loadingAnalysis } = useAnalyseFournisseurs();
  const { data: prixComparaison, isLoading: loadingPrix } = useComparaisonPrix();
  const { data: repartitionAchats, isLoading: loadingRepartition } = useRepartitionAchats();


  const fetchStats = async () => {
    try {
      setLoading(true);

      const response = await api.get('statistiques/ca_par_fournisseur/', {
        params: {
          date_debut: dateDebut,
          date_fin: dateFin
        }
      });

      setStats(response.data);
    } catch (error) {
      console.error("Erreur lors du chargement des statistiques", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStats();
  }, []); 

  // Totaux Ventes
  const totaux = useMemo(() => {
    return stats.reduce((acc, curr) => ({
      ca_ttc: acc.ca_ttc + Number(curr.ca_ttc),
      cout_achat: acc.cout_achat + Number(curr.cout_achat),
      marge_brute: acc.marge_brute + Number(curr.marge_brute),
      quantite_vendue: acc.quantite_vendue + curr.quantite_vendue
    }), { ca_ttc: 0, cout_achat: 0, marge_brute: 0, quantite_vendue: 0 });
  }, [stats]);

  const Recharts = useRecharts();
  if (!Recharts) return <div className="flex items-center justify-center p-8"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-slate-400" /></div>;
  const { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend, PieChart, Pie, Cell } = Recharts;

  return (
    <div className="p-3 sm:p-6 space-y-4 sm:space-y-6 animate-fade-in">
      <div className="flex flex-col gap-3 md:flex-row md:justify-between md:items-start">
        <div>
          <h1 className="text-2xl font-bold text-base-content">{t('title')}</h1>
          <p className="text-sm text-base-content/80">{t('subtitle')}</p>
        </div>
        
        {/* Date Filter only for Sales Tab currently */}
        {activeTab === 'ventes' && (
            <div className="flex flex-col sm:flex-row sm:items-end gap-2 bg-base-100 p-2 sm:p-3 rounded-lg shadow-sm border border-base-200 w-full md:w-auto">
            <div className="form-control w-full sm:w-40">
                <label className="label py-1"><span className="label-text text-xs">{t('filters.from')}</span></label>
                <input 
                type="date"
                lang={getLocale()}
                className="input input-bordered input-sm w-full" 
                value={dateDebut}
                onChange={(e) => setDateDebut(e.target.value)}
                />
            </div>
            <div className="form-control w-full sm:w-40">
                <label className="label py-1"><span className="label-text text-xs">{t('filters.to')}</span></label>
                <input 
                type="date"
                lang={getLocale()}
                className="input input-bordered input-sm w-full" 
                value={dateFin}
                onChange={(e) => setDateFin(e.target.value)}
                />
            </div>
            <button 
                className="btn btn-primary btn-sm w-full sm:w-auto h-10"
                onClick={fetchStats}
                disabled={loading}
            >
                {loading ? <span className="loading loading-spinner loading-xs"></span> : t('filters.refresh')}
            </button>
            </div>
        )}
      </div>

      {/* Tabs Navigation */}
      <div className="w-full max-w-full overflow-x-auto pb-1 -mx-1 px-1 sm:mx-0 sm:px-0">
        <div className="tabs tabs-boxed bg-base-100 p-1 w-max min-w-full sm:min-w-0 sm:w-fit">
        <a className={`tab whitespace-nowrap ${activeTab === 'ventes' ? 'tab-active' : ''}`} onClick={() => setActiveTab('ventes')}>{t('tabs.sales')}</a>
        <a className={`tab whitespace-nowrap ${activeTab === 'performance' ? 'tab-active' : ''}`} onClick={() => setActiveTab('performance')}>{t('tabs.performance')}</a>
        <a className={`tab whitespace-nowrap ${activeTab === 'prix' ? 'tab-active' : ''}`} onClick={() => setActiveTab('prix')}>{t('tabs.price_comparison')}</a>
        <a className={`tab whitespace-nowrap ${activeTab === 'concentration' ? 'tab-active' : ''}`} onClick={() => setActiveTab('concentration')}>{t('tabs.concentration')}</a>
        </div>
      </div>

      {/* TAB 1: VENTES (Existing Content) */}
      {activeTab === 'ventes' && (
        <div className="space-y-6 animate-fade-in">
           {/* Info Box */}
            <div className="alert alert-info shadow-sm">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" className="stroke-current shrink-0 size-6">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                </svg>
                <div>
                <h3 className="font-bold">{t('sales_tab.calculation_method')}</h3>
                <div className="text-sm">
                    {t('sales_tab.info_text')}
                </div>
                </div>
            </div>

            {/* Cartes R├®sum├® */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="card bg-base-100 shadow-sm border border-base-200">
                <div className="card-body p-4">
                    <p className="text-sm font-medium text-base-content/70">{t('sales_tab.cards.total_ca')}</p>
                    <h3 className="text-2xl font-bold text-success">{formatCurrency(Math.round(totaux.ca_ttc), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}</h3>
                </div>
                </div>
                <div className="card bg-base-100 shadow-sm border border-base-200">
                <div className="card-body p-4">
                    <p className="text-sm font-medium text-base-content/70">{t('sales_tab.cards.purchase_cost')}</p>
                    <h3 className="text-2xl font-bold text-primary">{formatCurrency(Math.round(totaux.cout_achat), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}</h3>
                </div>
                </div>
                <div className="card bg-base-100 shadow-sm border border-base-200">
                <div className="card-body p-4">
                    <p className="text-sm font-medium text-base-content/70">{t('sales_tab.cards.gross_margin')}</p>
                    <h3 className="text-2xl font-bold text-warning">{formatCurrency(Math.round(totaux.marge_brute), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}</h3>
                    <p className="text-xs text-base-content/60">
                    {totaux.ca_ttc > 0 ? ((totaux.marge_brute / totaux.ca_ttc) * 100).toFixed(1) : 0} {t('sales_tab.cards.margin_percentage')}
                    </p>
                </div>
                </div>
                <div className="card bg-base-100 shadow-sm border border-base-200">
                <div className="card-body p-4">
                    <p className="text-sm font-medium text-base-content/70">{t('sales_tab.cards.units_sold')}</p>
                    <h3 className="text-2xl font-bold text-purple-600">{totaux.quantite_vendue}</h3>
                </div>
                </div>
            </div>

            {/* Graphique */}
            <div className="card bg-base-100 shadow-sm border border-base-200">
                <div className="card-body p-4">
                <h2 className="card-title text-lg font-bold mb-4">{t('sales_tab.chart.title')}</h2>
                <div className="h-80">
                    <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={stats} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="nom" />
                        <YAxis />
                        <Tooltip formatter={(value: number | string) => `${formatCurrency(Number(value), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}`} />
                        <Legend />
                        <Bar dataKey="ca_ttc" name={t('sales_tab.chart.ca')} fill="#10b981" />
                        <Bar dataKey="marge_brute" name={t('sales_tab.chart.margin')} fill="#f59e0b" />
                    </BarChart>
                    </ResponsiveContainer>
                </div>
                </div>
            </div>

            {/* Tableau d├®taill├® */}
            <div className="card bg-base-100 shadow-sm border border-base-200">
                <div className="card-body p-0">
                <div className="overflow-x-auto">
                    <table className="table table-zebra w-full">
                    <thead>
                        <tr className="bg-base-200">
                        <th>{t('sales_tab.table.supplier')}</th>
                        <th className="text-right">{t('sales_tab.table.qty_sold')}</th>
                        <th className="text-right">{t('sales_tab.table.purchase_cost')}</th>
                        <th className="text-right">{t('sales_tab.table.ca_ttc')}</th>
                        <th className="text-right">{t('sales_tab.table.gross_margin')}</th>
                        <th className="text-right">{t('sales_tab.table.margin_percent')}</th>
                        </tr>
                    </thead>
                    <tbody>
                        {stats.length === 0 ? (
                        <tr>
                            <td colSpan={6} className="text-center py-8 text-base-content/50">
                            {t('sales_tab.table.no_data')}
                            </td>
                        </tr>
                        ) : (
                        stats.map((stat) => (
                            <tr key={stat.id}>
                            <td className="font-medium">{stat.nom}</td>
                            <td className="text-right">{stat.quantite_vendue}</td>
                             <td className="text-right">{formatCurrency(Math.round(Number(stat.cout_achat)), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}</td>
                             <td className="text-right font-bold">{formatCurrency(Math.round(Number(stat.ca_ttc)), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}</td>
                             <td className="text-right text-success">{formatCurrency(Math.round(Number(stat.marge_brute)), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}</td>
                            <td className="text-right text-sm">
                                {Number(stat.ca_ttc) > 0 
                                ? ((Number(stat.marge_brute) / Number(stat.ca_ttc)) * 100).toFixed(1) 
                                : 0}%
                            </td>
                            </tr>
                        ))
                        )}
                    </tbody>
                    </table>
                </div>
                </div>
            </div>
        </div>
      )}

      {/* TAB 2: PERFORMANCE (Scoring) */}
      {activeTab === 'performance' && (
        <div className="space-y-6 animate-fade-in">
             <div className="alert alert-warning shadow-sm">
                <svg xmlns="http://www.w3.org/2000/svg" className="stroke-current shrink-0 h-6 w-6" fill="none" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                <div>
                <h3 className="font-bold">{t('performance_tab.alert_title')}</h3>
                <div className="text-sm">{t('performance_tab.alert_text')}</div>
                </div>
            </div>
            
            {loadingAnalysis ? (
                 <div className="h-64 flex items-center justify-center">
                    <span className="loading loading-spinner loading-lg"></span>
                 </div>
            ) : (
                <div className="grid grid-cols-1 gap-4">
                     {supplierAnalysis?.map((item) => (
                         <div key={item.id} className="card bg-base-100 shadow-sm border border-base-200">
                             <div className="card-body p-4">
                                 <div className="flex justify-between items-start">
                                     <div>
                                         <h3 className="text-xl font-bold">{item.nom}</h3>
                                         <div className="badge badge-lg mt-2 badge-outline">Score: {item.score_global}/100</div>
                                     </div>
                                     <div className={`radial-progress font-bold text-lg ${
                                        item.score_global >= 80 ? 'text-success' : 
                                        item.score_global >= 50 ? 'text-warning' : 'text-error'
                                    }`} style={{ "--value": item.score_global, "--size": "4rem" } as unknown}>
                                        {item.score_global}
                                    </div>
                                 </div>
                                 
                                 <div className="divider my-1"></div>

                                 <div className="grid grid-cols-3 gap-4 text-center">
                                     <div>
                                         <div className="text-xs uppercase font-bold text-base-content/50">{t('performance_tab.metrics.volume')}</div>
                                          <div className="font-bold text-lg">{formatCurrency(Math.round(item.details.volume.valeur ?? 0), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}</div>
                                         <progress className="progress progress-primary w-full" value={item.details.volume.score} max="100"></progress>
                                     </div>
                                     <div>
                                         <div className="text-xs uppercase font-bold text-base-content/50">{t('performance_tab.metrics.quality')}</div>
                                         <div className="font-bold text-lg">{item.details.qualite.incidents} {t('performance_tab.metrics.incidents')}</div>
                                         <progress className={`progress w-full ${item.details.qualite.score > 80 ? 'progress-success' : 'progress-error'}`} value={item.details.qualite.score} max="100"></progress>
                                     </div>
                                     <div>
                                         <div className="text-xs uppercase font-bold text-base-content/50">{t('performance_tab.metrics.consistency')}</div>
                                         <div className="font-bold text-lg">{item.details.regularite.nb_livraisons} {t('performance_tab.metrics.deliveries')}</div>
                                         <progress className="progress progress-info w-full" value={item.details.regularite.score} max="100"></progress>
                                     </div>
                                 </div>
                             </div>
                         </div>
                     ))}
                </div>
            )}
        </div>
      )}

      {/* TAB 3: COMPARATEUR PRIX */}
      {activeTab === 'prix' && (
        <div className="space-y-6 animate-fade-in">
             <div className="alert alert-success shadow-sm">
                <svg xmlns="http://www.w3.org/2000/svg" className="stroke-current shrink-0 h-6 w-6" fill="none" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                <div>
                <h3 className="font-bold">{t('prices_tab.alert_title')}</h3>
                <div className="text-sm">{t('prices_tab.alert_text')}</div>
                </div>
            </div>

            {loadingPrix ? (
                <div className="h-64 flex items-center justify-center">
                    <span className="loading loading-spinner loading-lg"></span>
                 </div>
            ) : (
                <div className="overflow-x-auto card bg-base-100 shadow-sm border border-base-200">
                    <table className="table table-zebra w-full">
                        <thead>
                            <tr>
                                <th>{t('prices_tab.table.product')}</th>
                                <th>{t('prices_tab.table.max_gap')}</th>
                                <th>{t('prices_tab.table.offers')}</th>
                                <th>{t('prices_tab.table.best_price')}</th>
                            </tr>
                        </thead>
                        <tbody>
                            {prixComparaison?.map((prod) => (
                                <tr key={prod.id}>
                                    <td className="font-bold max-w-xs truncate" title={prod.produit}>{prod.produit}</td>
                                    <td>
                                        <span className={`badge ${
                                            prod.ecart_pourcentage > 20 ? 'badge-error text-white' : 
                                            prod.ecart_pourcentage > 5 ? 'badge-warning' : 'badge-ghost'
                                        }`}>
                                            {prod.ecart_pourcentage}%
                                        </span>
                                    </td>
                                    <td className="space-y-1">
                                        {prod.offres.map((offre) => (
                                            <div key={offre.fournisseur} className="flex justify-between text-xs w-64">
                                                <span>{offre.fournisseur}:</span>
                                                 <span className={offre.prix_moyen === prod.meilleur_prix ? 'font-bold text-success' : ''}>
                                                     {formatCurrency(Math.round(offre.prix_moyen), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}
                                                 </span>
                                             </div>
                                         ))}
                                     </td>
                                      <td className="font-bold text-success text-lg">
                                         {formatCurrency(Math.round(prod.meilleur_prix), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}
                                      </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
      )}

      {/* TAB 4: CONCENTRATION */}
      {activeTab === 'concentration' && (
        <div className="space-y-6 animate-fade-in">
             <div className="card bg-base-100 shadow-sm border border-base-200">
                <div className="card-body">
                    <h2 className="card-title">{t('concentration_tab.title')}</h2>
                    
                    {loadingRepartition ? (
                        <div className="h-64 flex items-center justify-center">
                            <span className="loading loading-spinner loading-lg"></span>
                        </div>
                    ) : (
                        <div className="flex flex-col md:flex-row items-center justify-center gap-8">
                            <div className="h-80 w-80">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={repartitionAchats?.data}
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={60}
                                            outerRadius={100}
                                            paddingAngle={5}
                                            dataKey="ca"
                                        >
                                            {repartitionAchats?.data.map((entry, index) => (
                                                <Cell key={entry.nom} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                         <Tooltip formatter={(value: number | string) => `${formatCurrency(Number(value), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}`} />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                            
                            <div className="flex-1">
                                <table className="table w-full">
                                    <thead>
                                        <tr>
                                            <th>{t('concentration_tab.table.color')}</th>
                                            <th>{t('concentration_tab.table.supplier')}</th>
                                            <th>{t('concentration_tab.table.market_share')}</th>
                                            <th>{t('concentration_tab.table.volume')}</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {repartitionAchats?.data.map((entry, index) => (
                                            <tr key={entry.id}>
                                                <td>
                                                    <div className="size-4 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                                                </td>
                                                <td className="font-bold">{entry.nom}</td>
                                                <td>{entry.pourcentage}%</td>
                                                 <td>{formatCurrency(Math.round(Number(entry.ca)), i18n.language === 'fr' ? 'fr-FR' : 'en-GB', t('common:currency'))}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}
                </div>
             </div>
        </div>
      )}

    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import api from '../services/api';
import {
  Server, Database, RefreshCw, Play, ShieldCheck, ShieldAlert,
  HardDrive, Clock, CheckCircle2, XCircle, AlertTriangle,
  RotateCcw, Wifi, WifiOff, Upload, Archive, Zap
} from 'lucide-react';

type TabId = 'sante' | 'sauvegardes';

interface DockerContainer {
  name: string;
  running: boolean;
  restart_policy: string;
  started_at: string | null;
  auto_restart: boolean;
  error?: string;
}

interface BackupInfo {
  filename: string;
  size_mb: number;
  created_at: string;
  has_checksum: boolean;
  checksum: string | null;
  age_hours: number;
}

interface LastBackup {
  filename: string;
  size_mb: number;
  age_hours: number;
  has_checksum: boolean;
  status: 'ok' | 'warning' | 'critical';
}

interface SystemStatus {
  docker: DockerContainer[];
  backup: {
    last: LastBackup | null;
    count: number;
    directory: string;
  };
}

interface BackupListData {
  backups: BackupInfo[];
  total: number;
}

const backupStatusColor = (status: string) => {
  if (status === 'ok') return 'text-emerald-600 bg-emerald-50';
  if (status === 'warning') return 'text-amber-600 bg-amber-50';
  return 'text-red-600 bg-red-50';
};

export default function SystemAdmin() {
  const { t } = useTranslation('system_admin');
  const [activeTab, setActiveTab] = useState<TabId>('sante');
  const [systemStatus, setSystemStatus] = useState<SystemStatus | null>(null);
  const [backupList, setBackupList] = useState<BackupListData | null>(null);
  const [loadingStatus, setLoadingStatus] = useState(true);
  const [loadingBackups, setLoadingBackups] = useState(false);
  const [runningBackup, setRunningBackup] = useState(false);
  const [fixingRestart, setFixingRestart] = useState(false);
  const [backupOutput, setBackupOutput] = useState<string | null>(null);
  const [backupError, setBackupError] = useState<string | null>(null);
  const [restoring, setRestoring] = useState(false);
  const [restoreFile, setRestoreFile] = useState<File | null>(null);
  const [restoreOutput, setRestoreOutput] = useState<string | null>(null);
  const [restoreError, setRestoreError] = useState<string | null>(null);
  const [showRestoreConfirm, setShowRestoreConfirm] = useState(false);
  const [restoreTarget, setRestoreTarget] = useState<string | null>(null);
  const [restoreProgress, setRestoreProgress] = useState<string[]>([]);

  // WAL / PITR state
  const [walStatus, setWalStatus] = useState<{
    archive_active: boolean;
    wal_count: number;
    wal_size_mb: number;
    oldest_wal: string | null;
    newest_wal: string | null;
    wal_directory: string;
    base_backups: { name: string; size_mb: number; created_at: string }[];
    base_backups_count: number;
  } | null>(null);
  const [loadingWal, setLoadingWal] = useState(false);
  const [runningBaseBackup, setRunningBaseBackup] = useState(false);
  const [pitrTargetTime, setPitrTargetTime] = useState('');
  const [pitrOutput, setPitrOutput] = useState<string | null>(null);
  const [pitrError, setPitrError] = useState<string | null>(null);
  const [runningPitr, setRunningPitr] = useState(false);

  // Backup settings configuration
  const [backupSettings, setBackupSettings] = useState<{
    backup_enabled: boolean;
    backup_time: string;
    backup_interval_minutes: number;
    backup_retention_count: number;
    secondary_backup_path: string;
    external_backup_path_1: string;
    external_backup_path_2: string;
    external_backup_path_3: string;
    cloud_backup_enabled: boolean;
    cloud_backup_endpoint: string;
    cloud_backup_bucket: string;
    cloud_backup_access_key: string;
    cloud_backup_secret_key: string;
    cloud_backup_region: string;
    cloud_backup_path_prefix: string;
  } | null>(null);
  const [loadingBackupSettings, setLoadingBackupSettings] = useState(false);
  const [savingBackupSettings, setSavingBackupSettings] = useState(false);

  const fetchStatus = useCallback(async () => {
    setLoadingStatus(true);
    try {
      const res = await api.get('/system-admin/status/');
      setSystemStatus(res.data);
    } catch {
      setSystemStatus(null);
    } finally {
      setLoadingStatus(false);
    }
  }, []);

  const fetchBackups = useCallback(async () => {
    setLoadingBackups(true);
    try {
      const res = await api.get('/system-admin/backups/');
      setBackupList(res.data);
    } catch {
      setBackupList(null);
    } finally {
      setLoadingBackups(false);
    }
  }, []);

  const fetchBackupSettings = useCallback(async () => {
    setLoadingBackupSettings(true);
    try {
      const res = await api.get('/pharmacy-settings/');
      setBackupSettings({
        backup_enabled: res.data.backup_enabled ?? true,
        backup_time: (res.data.backup_time || '02:00:00').substring(0, 5),
        backup_interval_minutes: res.data.backup_interval_minutes ?? 1440,
        backup_retention_count: res.data.backup_retention_count ?? 30,
        secondary_backup_path: res.data.secondary_backup_path || '',
        external_backup_path_1: res.data.external_backup_path_1 || '',
        external_backup_path_2: res.data.external_backup_path_2 || '',
        external_backup_path_3: res.data.external_backup_path_3 || '',
        cloud_backup_enabled: res.data.cloud_backup_enabled ?? false,
        cloud_backup_endpoint: res.data.cloud_backup_endpoint || '',
        cloud_backup_bucket: res.data.cloud_backup_bucket || '',
        cloud_backup_access_key: res.data.cloud_backup_access_key || '',
        cloud_backup_secret_key: res.data.cloud_backup_secret_key || '',
        cloud_backup_region: res.data.cloud_backup_region || '',
        cloud_backup_path_prefix: res.data.cloud_backup_path_prefix || 'pharmacie-backups/',
      });
    } catch {
      setBackupSettings(null);
    } finally {
      setLoadingBackupSettings(false);
    }
  }, []);

  const fetchWalStatus = useCallback(async () => {
    setLoadingWal(true);
    try {
      const res = await api.get('/system-admin/wal_status/');
      setWalStatus(res.data);
    } catch {
      setWalStatus(null);
    } finally {
      setLoadingWal(false);
    }
  }, []);

  useEffect(() => { fetchStatus(); }, [fetchStatus]);

  useEffect(() => {
    if (activeTab === 'sauvegardes') {
      fetchBackups();
      fetchBackupSettings();
      fetchWalStatus();
    }
  }, [activeTab, fetchBackups, fetchBackupSettings, fetchWalStatus]);

  const saveBackupSettings = async () => {
    if (!backupSettings) return;
    setSavingBackupSettings(true);
    try {
      await api.put('/pharmacy-settings/', {
        backup_enabled: backupSettings.backup_enabled,
        backup_time: backupSettings.backup_time,
        backup_interval_minutes: backupSettings.backup_interval_minutes,
        backup_retention_count: backupSettings.backup_retention_count,
        secondary_backup_path: backupSettings.secondary_backup_path,
        external_backup_path_1: backupSettings.external_backup_path_1,
        external_backup_path_2: backupSettings.external_backup_path_2,
        external_backup_path_3: backupSettings.external_backup_path_3,
        cloud_backup_enabled: backupSettings.cloud_backup_enabled,
        cloud_backup_endpoint: backupSettings.cloud_backup_endpoint,
        cloud_backup_bucket: backupSettings.cloud_backup_bucket,
        cloud_backup_access_key: backupSettings.cloud_backup_access_key,
        cloud_backup_secret_key: backupSettings.cloud_backup_secret_key,
        cloud_backup_region: backupSettings.cloud_backup_region,
        cloud_backup_path_prefix: backupSettings.cloud_backup_path_prefix,
      });
      setBackupOutput(t('settings_saved'));
      fetchStatus();
    } catch (e: unknown) {
      const err = e as { response?: { data?: { detail?: string } } };
      setBackupError(err?.response?.data?.detail || t('settings_save_error'));
    } finally {
      setSavingBackupSettings(false);
    }
  };

  const handleBaseBackup = async () => {
    setRunningBaseBackup(true);
    setPitrOutput(null);
    setPitrError(null);
    try {
      const res = await api.post('/system-admin/base_backup/');
      setPitrOutput(res.data.output || res.data.message);
      if (!res.data.success) setPitrError(res.data.error || 'Erreur');
      fetchWalStatus();
    } catch (e: unknown) {
      const err = e as { response?: { data?: { detail?: string; error?: string; message?: string } } };
      setPitrError(err?.response?.data?.error || err?.response?.data?.detail || err?.response?.data?.message || 'Erreur lors du base backup');
    } finally {
      setRunningBaseBackup(false);
    }
  };

  const handlePitrRestore = async () => {
    setRunningPitr(true);
    setPitrOutput(null);
    setPitrError(null);
    try {
      const res = await api.post('/system-admin/pitr_restore/', {
        target_time: pitrTargetTime || undefined,
      }, { timeout: 180000 });
      setPitrOutput(res.data.output || res.data.message);
      if (!res.data.success) setPitrError(res.data.error || 'Erreur');
    } catch (e: unknown) {
      setPitrError((e as { response?: { data?: { detail?: string } } })?.response?.data?.detail || 'Erreur lors de la restauration PITR');
    } finally {
      setRunningPitr(false);
    }
  };

  const handleRunBackup = async () => {
    setRunningBackup(true);
    setBackupOutput(null);
    setBackupError(null);
    try {
      const res = await api.post('/system-admin/run_backup/');
      setBackupOutput(res.data.output || res.data.message);
      if (!res.data.success) setBackupError(res.data.error || t('unknown_error'));
      fetchStatus();
      fetchBackups();
    } catch (e: unknown) {
      const err = e as { response?: { data?: { detail?: string; error?: string; message?: string } } };
      setBackupError(err?.response?.data?.detail || err?.response?.data?.error || err?.response?.data?.message || t('backup_error'));
    } finally {
      setRunningBackup(false);
    }
  };

  const handleBackupBeforeRestore = async () => {
    setRestoring(true);
    setRestoreOutput(null);
    setRestoreError(null);
    setRestoreProgress([t('restore_progress.safety_backup')]);
    setShowRestoreConfirm(false);
    try {
      const res = await api.post('/system-admin/run_backup/');
      if (!res.data.success) {
        setRestoreProgress(p => [...p, t('restore_progress.safety_failed')]);
        setRestoreError(res.data.error || t('security_backup_error'));
        setRestoring(false);
        return;
      }
      setRestoreProgress(p => [...p, t('restore_progress.safety_ok')]);
      await new Promise(r => setTimeout(r, 1000));
      await handleRestore();
    } catch (e: unknown) {
      setRestoreProgress(p => [...p, t('restore_progress.safety_failed')]);
      const err = e as { response?: { data?: { detail?: string } } };
      setRestoreError(err?.response?.data?.detail || t('security_backup_error'));
      setRestoring(false);
    }
  };

  const handleRestore = async () => {
    if (!restoreTarget && !restoreFile) return;
    setRestoring(true);
    setRestoreOutput(null);
    setRestoreError(null);
    setRestoreProgress([t('restore_progress.connecting')]);
    setShowRestoreConfirm(false);
    try {
      const formData = new FormData();
      if (restoreFile) {
        formData.append('file', restoreFile);
        setRestoreProgress(p => [...p, t('restore_progress.uploading', { name: restoreFile.name })]);
      } else if (restoreTarget) {
        formData.append('filename', restoreTarget);
        setRestoreProgress(p => [...p, t('restore_progress.using_file', { name: restoreTarget })]);
      }
      setRestoreProgress(p => [...p, t('restore_progress.running')]);
      const res = await api.post('/system-admin/restore/', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
        timeout: 120000,
      });
      setRestoreProgress(p => [...p, t('restore_progress.done')]);
      setRestoreOutput(res.data.output || res.data.message);
      if (!res.data.success) setRestoreError(res.data.error || t('unknown_error'));
      else {
        setRestoreFile(null);
        setRestoreTarget(null);
      }
    } catch (e: unknown) {
      setRestoreProgress(p => [...p, t('restore_progress.failed')]);
      const err = e as { response?: { data?: { detail?: string } } };
      setRestoreError(err?.response?.data?.detail || t('restore_error'));
    } finally {
      setRestoring(false);
    }
  };

  const handleFixRestart = async () => {
    setFixingRestart(true);
    try {
      await api.post('/system-admin/fix_restart_policy/');
      fetchStatus();
    } catch {
    } finally {
      setFixingRestart(false);
    }
  };

  const tabs: { id: TabId; label: string; icon: React.ReactNode }[] = [
    { id: 'sante', label: t('tabs.health'), icon: <Server className="w-4 h-4" /> },
