                      }
                      return null;
                    })()
                  )}

                  {restoreFile && (
                    <p className="text-xs text-amber-600 mb-4 font-medium">
                      {t('external_file_warning')}
                    </p>
                  )}

                  {/* Option backup de s├®curit├® */}
                  <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 mb-4">
                    <p className="text-xs text-amber-700 mb-2">
                      {t('safety_tip')}
                    </p>
                  </div>

                  <div className="flex gap-3 justify-end flex-wrap">
                    <button
                      onClick={() => setShowRestoreConfirm(false)}
                      className="px-4 py-2 text-sm font-semibold text-gray-600 bg-gray-100 rounded-lg hover:bg-gray-200"
                    >
                      {t('cancel')}
                    </button>
                    <button
                      onClick={handleBackupBeforeRestore}
                      disabled={restoring}
                      className="flex items-center gap-2 px-4 py-2 text-sm font-semibold bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-60"
                    >
                      <Database className="w-3.5 h-3.5" />
                      {restoring ? t('in_progress') : t('backup_then_restore')}
                    </button>
                    <button
                      onClick={handleRestore}
                      disabled={restoring}
                      className="px-4 py-2 text-sm font-semibold bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:opacity-60"
                    >
                      {restoring ? t('restoring') : t('restore_without_backup')}
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* ÔöÇÔöÇ Section WAL / PITR ÔöÇÔöÇ */}
            <div className="bg-white rounded-xl border border-gray-100 shadow-sm px-5 py-4">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xs font-bold uppercase tracking-wider text-gray-400 flex items-center gap-2">
                  <Archive className="w-4 h-4" />
                  Journal WAL & R├®cup├®ration Point-in-Time (PITR)
                </h3>
                <button
                  onClick={fetchWalStatus}
                  disabled={loadingWal}
                  className="flex items-center gap-1.5 px-2 py-1 text-xs text-gray-500 hover:text-gray-700"
                >
                  <RefreshCw className={`w-3 h-3 ${loadingWal ? 'animate-spin' : ''}`} />
                  Actualiser
                </button>
              </div>

              {walStatus ? (
                <div className="space-y-4">
                  {/* Statut archivage */}
                  <div className="flex items-center gap-3">
                    {walStatus.archive_active ? (
                      <span className="flex items-center gap-2 text-sm font-semibold text-emerald-600">
                        <CheckCircle2 className="w-4 h-4" /> Archivage WAL actif
                      </span>
                    ) : (
                      <span className="flex items-center gap-2 text-sm font-semibold text-red-600">
                        <XCircle className="w-4 h-4" /> Archivage WAL inactif
                      </span>
                    )}
                  </div>

                  {/* Stats WAL */}
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                    <div className="bg-gray-50 rounded-lg p-3">
                      <p className="text-xs text-gray-400">Fichiers WAL</p>
                      <p className="text-lg font-bold text-gray-700">{walStatus.wal_count}</p>
                    </div>
                    <div className="bg-gray-50 rounded-lg p-3">
                      <p className="text-xs text-gray-400">Taille</p>
                      <p className="text-lg font-bold text-gray-700">{walStatus.wal_size_mb} MB</p>
                    </div>
                    <div className="bg-gray-50 rounded-lg p-3">
                      <p className="text-xs text-gray-400">Plus ancien</p>
                      <p className="text-xs font-semibold text-gray-700">{walStatus.oldest_wal || 'ÔÇö'}</p>
                    </div>
                    <div className="bg-gray-50 rounded-lg p-3">
                      <p className="text-xs text-gray-400">Plus r├®cent</p>
                      <p className="text-xs font-semibold text-gray-700">{walStatus.newest_wal || 'ÔÇö'}</p>
                    </div>
                  </div>

                  {/* Base backups */}
                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <p className="text-sm font-semibold text-gray-700">
                        Backups de base: {walStatus.base_backups_count}
                      </p>
                      <button
                        onClick={handleBaseBackup}
                        disabled={runningBaseBackup}
                        className="flex items-center gap-2 px-3 py-1.5 text-sm font-semibold bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-all disabled:opacity-60"
                      >
                        <Zap className={`w-3.5 h-3.5 ${runningBaseBackup ? 'animate-pulse' : ''}`} />
                        {runningBaseBackup ? 'En cours...' : 'Cr├®er un base backup'}
                      </button>
                    </div>
                    {walStatus.base_backups.length > 0 && (
                      <div className="space-y-1">
                        {walStatus.base_backups.map((bb) => (
                          <div key={bb.name} className="flex items-center justify-between bg-gray-50 rounded-lg px-3 py-2">
                            <div className="flex items-center gap-2">
                              <Archive className="w-3.5 h-3.5 text-indigo-500" />
                              <span className="text-xs font-mono text-gray-700">{bb.name}</span>
                            </div>
                            <div className="flex items-center gap-3 text-xs text-gray-400">
                              <span>{bb.size_mb} MB</span>
                              <span>{bb.created_at}</span>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* PITR Restore */}
                  <div className="border-t border-gray-100 pt-4">
                    <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 mb-3">
                      <p className="text-xs text-amber-700">
                        <AlertTriangle className="w-3.5 h-3.5 inline mr-1" />
                        La restauration PITR rejoue le journal WAL jusqu'au timestamp choisi.
                        Si crash ├á 14h30 avec backup ├á 14h00, les transactions jusqu'├á 14h29 seront r├®cup├®r├®es.
                        Laisser vide pour r├®cup├®rer toutes les transactions disponibles.
                      </p>
                    </div>
                    <div className="flex items-end gap-3">
                      <div className="flex-1">
                        <label className="block text-xs font-semibold text-gray-500 mb-1">
                          Timestamp cible (optionnel)
                        </label>
                        <input
                          type="text"
                          placeholder="ex: 2026-07-23 14:29:00"
                          value={pitrTargetTime}
                          onChange={(e) => setPitrTargetTime(e.target.value)}
                          className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent font-mono"
                        />
                      </div>
                      <button
                        onClick={handlePitrRestore}
                        disabled={runningPitr || walStatus.base_backups_count === 0}
                        className="flex items-center gap-2 px-4 py-2 text-sm font-semibold bg-red-600 text-white rounded-lg hover:bg-red-700 transition-all disabled:opacity-60"
                      >
                        <RotateCcw className={`w-3.5 h-3.5 ${runningPitr ? 'animate-spin' : ''}`} />
                        {runningPitr ? 'Restauration...' : 'Restaurer PITR'}
                      </button>
                    </div>
                    {pitrOutput && (
                      <pre className="mt-3 p-3 bg-gray-50 border border-gray-100 rounded-lg text-xs text-gray-600 overflow-auto max-h-40 whitespace-pre-wrap">
                        {pitrOutput}
                      </pre>
                    )}
                    {pitrError && (
                      <p className="mt-2 text-xs text-red-600 flex items-center gap-1">
                        <XCircle className="w-3.5 h-3.5" /> {pitrError}
                      </p>
                    )}
                  </div>
                </div>
              ) : loadingWal ? (
                <div className="text-center py-4 text-gray-400">
                  <RefreshCw className="w-5 h-5 animate-spin mx-auto mb-2" />
                  Chargement du statut WAL...
                </div>
              ) : (
                <div className="text-center py-4 text-red-500">
                  <XCircle className="w-5 h-5 mx-auto mb-2" />
                  Impossible de charger le statut WAL
                </div>
              )}
            </div>

            {/* Info cron */}
            <div className="bg-white rounded-xl border border-gray-100 shadow-sm px-5 py-4">
              <h3 className="text-xs font-bold uppercase tracking-wider text-gray-400 mb-3">{t('scheduling.title')}</h3>
              <div className="space-y-2 text-sm text-gray-600">
                <div className="flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />
                  <span dangerouslySetInnerHTML={{ __html: t('scheduling.hourly') }} />
                </div>
                <div className="flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />
                  <span dangerouslySetInnerHTML={{ __html: t('scheduling.daily') }} />
                </div>
                <div className="flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />
                  <span dangerouslySetInnerHTML={{ __html: t('scheduling.check') }} />
                </div>
                <p className="text-xs text-gray-400 mt-2" dangerouslySetInnerHTML={{ __html: t('scheduling.logs') }} />
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import api from '../services/api';
import { useTranslation } from 'react-i18next';
import { format } from 'date-fns';
import { fr } from 'date-fns/locale';
import { Search, RefreshCcw, CheckCircle2, XCircle, Clock, FileText, User, Hash } from 'lucide-react';

interface TelegramLog {
    id: number;
    recipient_chat_id: string;
    recipient_name: string;
    message: string;
    type: string;
    type_display: string;
    status: string;
    status_display: string;
    has_attachment: boolean;
    created_at: string;
    sent_at: string;
    sent_by_name: string;
    facture_numero: string;
}

const getStatusIcon = (status: string) => {
    switch (status) {
        case 'SENT': return <CheckCircle2 className="size-4 text-success" />;
        case 'FAILED': return <XCircle className="size-4 text-error" />;
        case 'READ': return <CheckCircle2 className="size-4 text-info fill-info/20" />;
        default: return <Clock className="size-4 text-warning" />;
    }
};

const getStatusClass = (status: string) => {
    switch (status) {
        case 'SENT': return 'badge-success';
        case 'FAILED': return 'badge-error';
        case 'READ': return 'badge-info';
        default: return 'badge-warning';
    }
};

const TelegramHistory: React.FC = () => {
    const { } = useTranslation();
    const [logs, setLogs] = useState<TelegramLog[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [filterType, setFilterType] = useState('ALL');

    const fetchLogs = async () => {
        setLoading(true);
        try {
            const params: unknown = {};
            if (filterType !== 'ALL') params.type = filterType;

            const response = await api.get('telegram-logs/', { params });
            setLogs(Array.isArray(response.data) ? response.data : response.data.results || []);
        } catch (error) {
            console.error('Erreur lors du chargement de l\'historique Telegram:', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchLogs();
    }, [filterType]);

    const filteredLogs = logs.filter(log => 
        log.recipient_chat_id.includes(searchTerm) || 
        log.recipient_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        log.message.toLowerCase().includes(searchTerm.toLowerCase()) ||
        log.facture_numero?.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="h-full flex flex-col bg-base-200 p-4 md:p-6 lg:p-8 gap-4 sm:gap-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-base-100 p-6 rounded-2xl shadow-sm border border-base-200">
                <div>
                    <h1 className="text-2xl font-black text-base-content flex items-center gap-3">
                        <div className="p-2 bg-info/10 rounded-lg">
                            <svg className="size-6 text-info" viewBox="0 0 24 24" fill="currentColor">
                                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.64 6.8c-.15 1.58-.8 5.42-1.13 7.19-.14.75-.42 1-.68 1.03-.58.05-1.02-.38-1.58-.75-.88-.58-1.38-.94-2.23-1.5-.99-.65-.35-1.01.22-1.59.15-.15 2.71-2.48 2.76-2.69a.2.2 0 0 0-.05-.18c-.06-.05-.14-.03-.21-.02-.09.02-1.49.95-4.22 2.79-.4.27-.76.41-1.08.4-.36-.01-1.04-.2-1.55-.37-.63-.2-1.12-.31-1.08-.66.02-.18.27-.36.74-.55 2.92-1.27 4.86-2.11 5.83-2.51 2.78-1.16 3.35-1.36 3.73-1.36.08 0 .27.02.39.12.1.08.13.19.14.27-.01.06.01.24 0 .38z"/>
                            </svg>
                        </div>
                        Historique Telegram
                    </h1>
                    <p className="text-base-content/60 text-sm mt-1">
                        Consultez tous les messages Telegram envoy├®s depuis le syst├¿me (rapports, factures, etc.)
                    </p>
                </div>
                <button 
                    onClick={fetchLogs} 
                    className="btn btn-outline btn-sm gap-2 rounded-xl"
                    disabled={loading}
                >
                    <RefreshCcw className={`size-4 ${loading ? 'animate-spin' : ''}`} />
                    Actualiser
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="md:col-span-3 relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 size-5 text-base-content/40" />
                    <input 
                        type="text" 
                        placeholder="Rechercher par chat ID, nom ou message..." 
                        className="input input-bordered w-full pl-12 rounded-xl bg-base-100 shadow-sm border-base-200"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
                <select 
                    className="select select-bordered w-full rounded-xl bg-base-100 shadow-sm border-base-200"
                    value={filterType}
                    onChange={(e) => setFilterType(e.target.value)}
                >
                    <option value="ALL">Tous les types</option>
                    <option value="RAPPORT">Rapports Flash</option>
                    <option value="FACTURE">Factures</option>
                    <option value="PROMIS">Rappels Promis</option>
                    <option value="MANUEL">Envois Manuels</option>
                </select>
            </div>

            <div className="bg-base-100 rounded-2xl shadow-sm border border-base-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="table w-full">
                        <thead>
                            <tr className="bg-base-200/50">
                                <th>Date & Exp├®diteur</th>
                                <th>Destinataire</th>
                                <th>Message</th>
                                <th>Type</th>
                                <th>Statut</th>
                            </tr>
                        </thead>
                        <tbody>
                            {loading ? (
                                <tr>
                                    <td colSpan={5} className="text-center py-10">
                                        <span className="loading loading-spinner loading-lg text-primary"></span>
                                    </td>
                                </tr>
                            ) : filteredLogs.length === 0 ? (
                                <tr>
                                    <td colSpan={5} className="text-center py-10 text-base-content/50">
                                        Aucun log trouv├®
                                    </td>
                                </tr>
                            ) : filteredLogs.map(log => (
                                <tr key={log.id} className="hover:bg-base-200/30 transition-colors">
                                    <td>
                                        <div className="flex flex-col gap-1">
                                            <span className="font-bold text-sm">
                                                {format(new Date(log.created_at), 'dd/MM/yyyy HH:mm', { locale: fr })}
                                            </span>
                                            <span className="text-xs flex items-center gap-1 text-base-content/60">
                                                <User className="size-3" /> {log.sent_by_name || 'Syst├¿me'}
                                            </span>
                                        </div>
                                    </td>
                                    <td>
                                        <div className="flex flex-col gap-1">
                                            <span className="font-bold text-sm">{log.recipient_name || 'Inconnu'}</span>
                                            <span className="text-xs flex items-center gap-1 font-mono text-base-content/70">
                                                <Hash className="size-3 text-info" /> {log.recipient_chat_id}
                                            </span>
                                        </div>
                                    </td>
                                    <td>
                                        <div className="max-w-md">
                                            <p className="text-sm line-clamp-2" title={log.message}>{log.message}</p>
                                            {log.facture_numero && (
                                                <span className="badge badge-ghost badge-sm gap-1 mt-1 font-mono whitespace-nowrap">
                                                    <FileText className="size-2" /> {log.facture_numero}
                                                </span>
                                            )}
                                        </div>
                                    </td>
                                    <td>
                                        <span className="badge badge-ghost badge-sm font-semibold">{log.type_display}</span>
                                    </td>
                                    <td>
                                        <div className={`badge ${getStatusClass(log.status)} badge-sm gap-1 font-bold text-[10px]`}>
                                            {getStatusIcon(log.status)}
                                            {log.status_display}
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default TelegramHistory;

import React, { useState, useEffect, useRef } from 'react';
import api from '../services/api';
import { toast } from 'react-hot-toast';
import { getApiErrorDetail } from '../utils/errorHandling';
import { useTranslation } from 'react-i18next';
import { useConfirm } from '../hooks/useConfirm';
import { useProductSearch } from '../hooks/useProductSearch';
import { useSearchNavigation } from '../hooks/useSearchNavigation';
import PremiumModal from './common/PremiumModal';
import { Checkbox } from './ui/Checkbox';
import type { ProduitModel } from '../types';
import { 
  ChevronRight, Trash2, Plus 
} from 'lucide-react';
import { normalizeNumberInput, formatNumber } from '../utils/formatters';
import { formatDate, formatDateTime } from '../utils/dateUtils';

// Interfaces
interface RelationTransformation {
  id: number;
  produit_source: number;
  produit_source_nom: string;
  produit_destination: number;
  produit_destination_nom: string;
  ratio: number;
  actif: boolean;
}

interface HistoriqueTransformation {
  id: number;
  produit_source_nom: string;
  produit_destination_nom: string;
  quantite_source: number;
  quantite_destination: number;
  user_nom: string;
  date_transformation: string;
  notes: string;
}

// --- Composant Autocomplete Produit ---
interface ProductAutocompleteProps {
  label: string;
  icon: React.ReactNode;
  selected: ProduitModel | null;
  onSelect: (product: ProduitModel) => void;
  onClear: () => void;
  placeholder?: string;
}

const ProductAutocomplete: React.FC<ProductAutocompleteProps> = ({
  label, icon, selected, onSelect, onClear, placeholder
}) => {
  const { t } = useTranslation(['stock', 'common']);
  const placeholderText = placeholder || t('stock:transformations.modal_relation.source_placeholder');
  const { produits, loading, searchQuery, setSearchQuery } = useProductSearch({
    minSearchLength: 2,
    debounceMs: 250,
    pageSize: 1000,
  });
  const [isFocused, setIsFocused] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Keyboard navigation
  const handleSelect = (product: ProduitModel) => {
    onSelect(product);
    setSearchQuery('');
    setIsFocused(false);
  };

  const { handleKeyDown, getItemProps } = useSearchNavigation(
    produits,
    handleSelect,
    { resetOnSelect: true, searchInputRef: inputRef }
  );

  // Fermer le dropdown quand on clique en dehors
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsFocused(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  if (selected) {
    return (
      <div>
        <label className="block text-xs font-bold uppercase tracking-wider text-slate-400 mb-2 flex items-center gap-2">
          {icon} {label}
        </label>
        <div className="flex items-center gap-3 bg-gradient-to-r from-emerald-50 to-emerald-100/60 border-2 border-emerald-200 rounded-xl px-4 py-3 transition-all">
          <div className="size-9 rounded-lg bg-emerald-100 flex items-center justify-center text-emerald-600 font-black text-sm">
            {selected.name.charAt(0).toUpperCase()}
          </div>
          <div className="flex-1 min-w-0">
            <div className="font-bold text-slate-800 truncate">{selected.name}</div>
            <div className="text-[11px] text-slate-400 flex gap-3">
              <span>{t('common:cip')}: {selected.cip1 || t('common:not_available')}</span>
              <span>{t('common:stock')}: <b className={selected.stock <= 0 ? 'text-red-500' : 'text-emerald-600'}>{formatNumber(selected.stock)}</b></span>
            </div>
          </div>
          <button
            type="button"
            onClick={onClear}
            className="size-7 rounded-full flex items-center justify-center text-slate-400 hover:text-red-500 hover:bg-red-50 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
      </div>
    );
  }

  const showResults = isFocused && searchQuery.length >= 2;

  return (
    <div ref={containerRef}>
      <label className="block text-xs font-bold uppercase tracking-wider text-slate-400 mb-2 flex items-center gap-2">
        {icon} {label}
      </label>
      <div className="relative">
        <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
        </div>
        <input
          ref={inputRef}
          type="text"
          className="w-full pl-10 h-12 rounded-xl border border-slate-200 bg-slate-50 text-sm text-slate-700 focus:outline-none focus:bg-white focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 transition-all"
          placeholder={placeholderText}
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          onFocus={() => setIsFocused(true)}
          onKeyDown={(e) => {
            if (showResults) {
              handleKeyDown(e);
            }
          }}
        />
        {loading && (
          <div className="absolute right-3 top-1/2 -translate-y-1/2">
            <span className="size-4 border-2 border-emerald-300 border-t-emerald-600 rounded-full animate-spin inline-block"></span>
          </div>
        )}

        {/* Dropdown r├®sultats */}
        {showResults && (
          <div className="absolute z-50 left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-2xl overflow-hidden max-h-60 overflow-y-auto">
            {produits.length === 0 && !loading && (
              <div className="p-4 text-center text-slate-400 italic text-sm">
                {t('common:no_results_found')}
              </div>
            )}
            {produits.map((p, idx) => {
              const itemProps = getItemProps(idx);
              return (
                <div
                  key={p.id}
                  id={itemProps.id}
                  onMouseEnter={itemProps.onMouseEnter}
                  className={`px-4 py-3 cursor-pointer border-b border-slate-100 last:border-0 flex items-center gap-3 transition-colors group ${itemProps.className}`}
                  style={itemProps.style}
                  onClick={() => handleSelect(p)}
                >
                  <div className="size-8 rounded-lg bg-slate-100 group-hover:bg-emerald-50 flex items-center justify-center text-slate-500 group-hover:text-emerald-600 font-bold text-xs transition-colors"
                    style={itemProps.style.backgroundColor ? { backgroundColor: 'rgba(255,255,255,0.2)' } : {}}
                  >
                    {p.name.charAt(0).toUpperCase()}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="font-semibold text-sm truncate text-slate-700">{p.name}</div>
                    <div className="text-[10px] flex gap-3 text-slate-400">
                      <span>{t('common:cip')}: {p.cip1 || t('common:not_available')}</span>
                      <span>{t('common:stock')}: <b>{formatNumber(p.stock)}</b></span>
                    </div>
                  </div>
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-slate-300 group-hover:text-emerald-500 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" />
                  </svg>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

// --- Composant Principal ---
const Transformations: React.FC = () => {
  const { t } = useTranslation(['stock', 'common']);
  const confirm = useConfirm();
  const [activeTab, setActiveTab] = useState<'relations' | 'historique'>('relations');
  const [relations, setRelations] = useState<RelationTransformation[]>([]);
  const [historique, setHistorique] = useState<HistoriqueTransformation[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Modals
  const [isRelationModalOpen, setIsRelationModalOpen] = useState(false);
  const [isTransformerModalOpen, setIsTransformerModalOpen] = useState(false);
  
  // Cr├®ation relation - produits s├®lectionn├®s
  const [selectedSource, setSelectedSource] = useState<ProduitModel | null>(null);
  const [selectedDestination, setSelectedDestination] = useState<ProduitModel | null>(null);
  const [ratioValue, setRatioValue] = useState('');
  
  const [transformationData, setTransformationData] = useState({
    relation: null as RelationTransformation | null,
    quantite: 1,
    notes: ''
  });

  const [preview, setPreview] = useState<{
    stock_source: number;
    stock_source_after: number;
    stock_destination: number;
    stock_destination_after: number;
    quantite_source: number;
    quantite_destination: number;
    ratio: number;
    use_lot_management: boolean;
    lots: {
      lot_id: number;
      lot: string;
      quantity_remaining: number;
      quantity_consumed: number;
      quantity_remaining_after: number;
      date_expiration: string | null;
      fournisseur: string | null;
      selected: boolean;
    }[];
    manual_lots_enabled: boolean;
  } | null>(null);

  const [manualLots, setManualLots] = useState<Record<number, number>>({});

  const [submitting, setSubmitting] = useState(false);

  // URL de base API dynamique

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [relationsRes, historiqueRes] = await Promise.all([
        api.get('relations-transformation/'),
        api.get('historique-transformation/')
      ]);
      
      const relationsData = Array.isArray(relationsRes.data) ? relationsRes.data : (relationsRes.data.results || []);
      const historiqueData = Array.isArray(historiqueRes.data) ? historiqueRes.data : (historiqueRes.data.results || []);

      setRelations(relationsData);
      setHistorique(historiqueData);
      setLoading(false);
    } catch (error) {
      console.error("Erreur fetch:", error);
      toast.error(t('transformations.messages.load_error'));
      setLoading(false);
    }
  };

  const handleCreateRelation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSource || !selectedDestination || !ratioValue) return;

    try {
      await api.post('relations-transformation/', {
        produit_source: selectedSource.id,
        produit_destination: selectedDestination.id,
        ratio: normalizeNumberInput(ratioValue)
      });
      toast.success(t('transformations.messages.create_success'));
      setIsRelationModalOpen(false);
      resetRelationForm();
      fetchData();
    } catch (error) {
      console.error(error);
      toast.error(getApiErrorDetail(error, t('transformations.messages.create_error')));
    }
  };

  const resetRelationForm = () => {
    setSelectedSource(null);
    setSelectedDestination(null);
    setRatioValue('');
  };

  const handleDeleteRelation = async (id: number) => {
    const confirmed = await confirm({
      title: t('transformations.messages.delete_confirm_title'),
      message: t('transformations.messages.delete_confirm_message'),
      variant: 'danger',
      confirmText: t('transformations.messages.delete_confirm_btn')
    })
    if (!confirmed) return;
    try {
      await api.delete(`relations-transformation/${id}/`);
      toast.success(t('transformations.messages.delete_success'));
      fetchData();
    } catch {
      toast.error(t('transformations.messages.delete_error'));
    }
  };

  const openTransformerModal = (relation: RelationTransformation) => {
    setSubmitting(false);
    setManualLots({});
    setTransformationData({
      relation,
      quantite: 1,
      notes: ''
    });
    setIsTransformerModalOpen(true);
  };

  const handleTransformer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!transformationData.relation) return;

    const confirmed = await confirm({
      title: t('transformations.messages.transform_confirm_title', { defaultValue: 'Confirmer la transformation' }),
      message: t('transformations.messages.transform_confirm_message', { defaultValue: `Transformer ${transformationData.quantite} ${transformationData.relation.produit_source_nom} en ${quantiteDestinationCalculee} ${transformationData.relation.produit_destination_nom} ?` }),
      variant: 'warning',
      confirmText: t('transformations.messages.transform_confirm_btn', { defaultValue: 'Oui, transformer' })
    });
    if (!confirmed) return;

    setSubmitting(true);
    try {
      const res = await api.post(`relations-transformation/${transformationData.relation.id}/transformer/`, {
        quantite: transformationData.quantite,
        notes: transformationData.notes,
        lots: Object.entries(manualLots)
          .flatMap(([lot_id, qty]) => qty > 0 ? [{ lot_id: Number(lot_id), quantity: qty }] : [])
      });

      if (res.data.success) {
        toast.success(res.data.message || t('transformations.messages.transform_success'));
        setIsTransformerModalOpen(false);
        fetchData();
      }
    } catch (error) {
      toast.error(getApiErrorDetail(error, t('transformations.messages.transform_error')));
      setSubmitting(false);
    }
  };

  // Calculs dynamiques pour le modal transformer
  const quantiteDestinationCalculee = transformationData.relation 
    ? Math.floor(transformationData.quantite * transformationData.relation.ratio) 
    : 0;

  // R├®cup├®rer la pr├®visualisation des lots consomm├®s
  const fetchPreview = async (relation: RelationTransformation, quantite: number) => {
    if (!relation || quantite <= 0) {
      setPreview(null);
      setManualLots({});
      return;
    }
    try {
      const res = await api.post(`relations-transformation/${relation.id}/preview/`, { quantite });
      setPreview(res.data);
      // Initialiser les lots manuels depuis la s├®lection FEFO
      const initialManual: Record<number, number> = {};
      res.data.lots?.forEach((lot: unknown) => {
        if (lot.quantity_consumed > 0) {
          initialManual[lot.lot_id] = lot.quantity_consumed;
        }
      });
      setManualLots(initialManual);
    } catch (error) {
      console.error('Erreur preview transformation:', error);
      setPreview(null);
      setManualLots({});
    }
  };

  useEffect(() => {
    if (transformationData.relation) {
      fetchPreview(transformationData.relation, transformationData.quantite);
    } else {
      setPreview(null);
      setManualLots({});
    }
  }, [transformationData.relation, transformationData.quantite]);

  // Calculer le total s├®lectionn├® manuellement
  const manualTotal = Object.values(manualLots).reduce((sum, qty) => sum + (qty || 0), 0);

  // Filtrage recherche
  const filteredRelations = relations.filter(r => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return r.produit_source_nom.toLowerCase().includes(q) || r.produit_destination_nom.toLowerCase().includes(q);
  });
  const filteredHistorique = historique.filter(h => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return h.produit_source_nom.toLowerCase().includes(q) || h.produit_destination_nom.toLowerCase().includes(q);
  });

  // Mettre ├á jour la quantit├® d'un lot manuellement
  const updateManualLotQty = (lot_id: number, qty: number) => {
    setManualLots(prev => {
      const next = { ...prev };
      if (qty <= 0) {
        delete next[lot_id];
      } else {
        next[lot_id] = qty;
      }
      return next;
    });
  };

  // Basculer la s├®lection d'un lot
  const toggleManualLot = (lot_id: number, maxQty: number, currentQty: number) => {
    if (currentQty > 0) {
      updateManualLotQty(lot_id, 0);
    } else {
      // Attribuer automatiquement ce qui manque jusqu'├á la quantit├® totale
      const remainingNeeded = transformationData.quantite - manualTotal;
      const qty = Math.min(maxQty, Math.max(0, remainingNeeded));
      if (qty > 0) {
        updateManualLotQty(lot_id, qty);
      }
    }
  };

  return (
    <div className="h-full flex flex-col bg-slate-100 overflow-hidden font-sans">
      {/* Header Section */}
      <div className="bg-white border-b border-slate-200 sticky top-0 z-30 flex flex-col shrink-0">
        <div className="px-6 py-4 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-emerald-50 rounded-xl text-emerald-600 shadow-inner">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-800 tracking-tight">{t('transformations.title')}</h1>
              <p className="text-[11px] font-medium text-slate-400 uppercase tracking-widest mt-0.5">{t('transformations.subtitle')}</p>
            </div>
          </div>
          <button 
            onClick={() => { resetRelationForm(); setIsRelationModalOpen(true); }}
            className="inline-flex items-center gap-2 h-10 px-5 bg-emerald-600 text-white rounded-xl text-sm font-bold hover:bg-emerald-700 transition-colors shadow-sm"
          >
            <Plus size={16} />
            {t('transformations.new_relation_btn')}
          </button>
        </div>

        {/* Tab Navigation + Search */}
        <div className="px-6 py-2 bg-slate-50 flex items-center gap-1 border-t border-slate-100">
          <button 
            className={`h-8 px-4 rounded-lg text-xs font-bold transition-all duration-200 ${
              activeTab === 'relations' ? 'bg-emerald-600 text-white shadow-sm' : 'text-slate-500 hover:bg-slate-200'
            }`}
            onClick={() => setActiveTab('relations')}
          >
            {t('transformations.tabs.configured_relations')}
          </button>
          <button 
            className={`h-8 px-4 rounded-lg text-xs font-bold transition-all duration-200 ${
              activeTab === 'historique' ? 'bg-emerald-600 text-white shadow-sm' : 'text-slate-500 hover:bg-slate-200'
            }`}
            onClick={() => setActiveTab('historique')}
          >
            {t('transformations.tabs.history')}
          </button>
          <div className="flex-1" />
          <div className="relative">
            <svg xmlns="http://www.w3.org/2000/svg" className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            <input
              type="text"
              className="h-8 w-56 pl-9 pr-3 rounded-lg border border-slate-200 bg-white text-xs text-slate-700 focus:outline-none focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 transition-all"
              placeholder={t('common:search', { defaultValue: 'Rechercher...' })}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* Main Content Section */}
      <div className="flex-1 overflow-auto p-6">
        {loading ? (
          <div className="flex flex-col items-center justify-center p-20 gap-4">
            <span className="size-10 border-4 border-slate-200 border-t-emerald-500 rounded-full animate-spin"></span>
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{t('common:loading')}</p>
          </div>
        ) : (
          <div className="h-full">
            {activeTab === 'relations' && (
              <div className="space-y-3">
                {filteredRelations.map(relation => (
                  <div key={relation.id} className="group relative bg-white border border-slate-200 rounded-2xl px-5 py-4 hover:border-emerald-300 transition-all hover:shadow-md flex items-center gap-4">
                    {/* Source */}
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                      <div className="size-10 rounded-xl bg-slate-100 flex items-center justify-center text-slate-600 font-black shadow-inner shrink-0">
                        {relation.produit_source_nom.charAt(0).toUpperCase()}
                      </div>
                      <div className="min-w-0">
                        <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-0.5">{t('common:source')}</div>
                        <div className="font-bold text-sm text-slate-700 truncate" title={relation.produit_source_nom}>{relation.produit_source_nom}</div>
                      </div>
                    </div>

                    {/* Arrow + Ratio */}
                    <div className="flex flex-col items-center gap-1 shrink-0">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-slate-300 group-hover:text-emerald-500 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                      <span className="bg-emerald-600 text-white font-mono font-black text-[10px] h-5 px-2 rounded-full inline-flex items-center">1:{formatNumber(relation.ratio)}</span>
                    </div>

                    {/* Destination */}
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                      <div className="min-w-0">
                        <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-0.5">{t('stock:transformations.labels.dest')}</div>
                        <div className="font-bold text-sm truncate text-emerald-600" title={relation.produit_destination_nom}>{relation.produit_destination_nom}</div>
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-2 shrink-0">
                      <button 
                        className="h-9 px-5 bg-emerald-600 text-white rounded-lg text-xs font-bold hover:bg-emerald-700 transition-colors"
                        onClick={() => openTransformerModal(relation)}
                      >
                        {t('stock:transformations.labels.transformer')}
                      </button>
                      <button 
                        className="size-9 rounded-lg text-red-500 hover:bg-red-50 flex items-center justify-center transition-colors"
                        onClick={() => handleDeleteRelation(relation.id)}
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                ))}
                {filteredRelations.length === 0 && (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-300 italic">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                    <p className="font-bold uppercase tracking-widest text-xs">{searchQuery ? t('common:no_results_found', { defaultValue: 'Aucun r├®sultat' }) : t('stock:transformations.labels.no_relations')}</p>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'historique' && (
              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="overflow-x-auto whitespace-nowrap">
                  <table className="w-full border-separate border-spacing-0 text-sm">
                    <thead className="bg-slate-50 sticky top-0 z-10 border-b border-slate-200">
                      <tr className="text-slate-400 uppercase text-[10px] tracking-widest font-black h-12">
                        <th className="pl-6 text-left font-black">{t('transformations.table_history.date')}</th>
                        <th className="px-4 text-left font-black">{t('transformations.table_history.user')}</th>
                        <th className="px-4 text-left font-black">{t('transformations.table_history.transformation')}</th>
                        <th className="px-4 text-left font-black">{t('transformations.table_history.quantities')}</th>
                        <th className="px-4 pr-6 text-left font-black">{t('transformations.table_history.notes')}</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredHistorique.map(hist => (
                        <tr key={hist.id} className="hover:bg-slate-50 transition-colors group">
                          <td className="pl-6 py-4">
                             <div className="font-bold text-xs text-slate-800">{formatDate(hist.date_transformation)}</div>
                             <div className="text-[10px] text-slate-400 font-mono uppercase tracking-tighter">{formatDateTime(hist.date_transformation).split(' ').slice(1).join(' ')}</div>
                          </td>
                          <td className="px-4 font-black text-xs text-emerald-700">{hist.user_nom}</td>
                          <td className="px-4 max-w-xs">
                             <div className="flex items-center gap-2 text-xs font-bold truncate">
                                <span className="text-slate-400">{hist.produit_source_nom}</span>
                                <ChevronRight size={12} className="text-slate-300" />
                                <span className="text-emerald-600">{hist.produit_destination_nom}</span>
                             </div>
                          </td>
                          <td className="px-4">
                             <div className="flex items-center gap-3">
                                <div className="bg-red-50 text-red-500 px-2 py-0.5 rounded text-[10px] font-black font-mono">-{formatNumber(hist.quantite_source)}</div>
                                <ChevronRight size={12} className="text-slate-200" />
                                <div className="bg-emerald-50 text-emerald-600 px-2 py-0.5 rounded text-[10px] font-black font-mono">+{formatNumber(hist.quantite_destination)}</div>
                             </div>
                          </td>
                          <td className="px-4 pr-6 italic text-slate-400 text-[11px] max-w-sm truncate group-hover:whitespace-normal group-hover:overflow-visible transition-all">
                             {hist.notes || '-'}
                          </td>
                        </tr>
                      ))}
                      {filteredHistorique.length === 0 && (
                        <tr>
                          <td colSpan={5} className="text-center py-20 text-slate-300 italic font-bold uppercase tracking-widest text-xs">{searchQuery ? t('common:no_results_found', { defaultValue: 'Aucun r├®sultat' }) : t('stock:transformations.table_history.empty')}</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* ===== Modal Cr├®ation Relation ===== */}
      <PremiumModal
        isOpen={isRelationModalOpen}
        onClose={() => setIsRelationModalOpen(false)}
        title={t('transformations.modal_relation.title')}
        subtitle={t('transformations.modal_relation.subtitle')}
        icon={
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-primary" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" />
          </svg>
        }
      >
        <form onSubmit={handleCreateRelation} className="p-6 space-y-5">
          {/* Produit Source */}
          <ProductAutocomplete
            label={t('transformations.modal_relation.source')}
            icon={
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
              </svg>
            }
            selected={selectedSource}
            onSelect={setSelectedSource}
            onClear={() => setSelectedSource(null)}
            placeholder={t('transformations.modal_relation.source_placeholder')}
          />

          {/* Separation Arrow */}
          <div className="flex items-center justify-center py-1">
            <div className="flex items-center gap-2 text-base-200">
              <div className="h-px w-12 bg-base-300"></div>
              <div className="size-8 rounded-full bg-primary/5 flex items-center justify-center">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-primary text-base-content/50" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 14l-7 7m0 0l-7-7m7 7V3" />
                </svg>
              </div>
              <div className="h-px w-12 bg-base-300"></div>
            </div>
          </div>

          {/* Produit Destination */}
          <ProductAutocomplete
            label={t('transformations.modal_relation.destination')}
            icon={
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" />
              </svg>
            }
            selected={selectedDestination}
            onSelect={setSelectedDestination}
            onClear={() => setSelectedDestination(null)}
            placeholder={t('transformations.modal_relation.destination_placeholder')}
          />

          {/* Ratio */}
          <div>
            <label className="block text-[10px] font-black uppercase tracking-widest text-base-content/40 mb-2 flex items-center gap-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 20l4-16m2 16l4-16M6 9h14M4 15h14" />
              </svg>
              {t('transformations.modal_relation.ratio_label')}
            </label>
            <input 
              type="number" 
              step="0.01"
              className="w-full h-12 rounded-xl border-2 border-slate-200 bg-slate-50 text-lg font-black text-center focus:outline-none focus:bg-white focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 transition-all" 
              placeholder={t('stock:transformations.modal_relation.ratio_placeholder')}
              value={ratioValue}
              onChange={e => setRatioValue(e.target.value)}
              required
            />
            <p className="text-[11px] font-medium text-slate-400 mt-1.5 text-center px-4">
              {t('transformations.modal_relation.ratio_help')}
            </p>
          </div>

          {/* Preview */}
          {selectedSource && selectedDestination && ratioValue && (
            <div className="bg-gradient-to-br from-emerald-50 to-blue-50 border border-emerald-200 rounded-xl p-4 shadow-inner">
              <div className="flex items-center justify-between text-sm">
                  <div className="text-center flex-1">
                    <div className="font-bold text-slate-800 truncate text-xs">{selectedSource.name}</div>
                    <div className="text-[10px] font-black text-slate-400 mt-0.5">├ù 1 {t('stock:transformations.labels.unit')}</div>
                  </div>
                  <div className="px-4 text-emerald-400 flex flex-col items-center">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M17 8l4 4m0 0l-4 4m4-4H3" />
                    </svg>
                    <span className="text-[10px] font-black mt-1 bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full">├ù {ratioValue}</span>
                  </div>
                  <div className="text-center flex-1">
                    <div className="font-bold text-emerald-600 truncate text-xs">{selectedDestination.name}</div>
                    <div className="text-[10px] font-black text-emerald-400/60 mt-0.5">├ù {Math.floor(normalizeNumberInput(ratioValue))} {t('stock:transformations.labels.units')}</div>
                  </div>
              </div>
            </div>
          )}

          {/* Footer Actions */}
          <div className="flex justify-end gap-3 pt-4 border-t border-slate-200">
            <button type="button" className="h-10 px-6 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-100 transition-colors" onClick={() => setIsRelationModalOpen(false)}>
              {t('transformations.modal_relation.cancel')}
            </button>
            <button 
              type="submit" 
              className="inline-flex items-center gap-2 h-10 px-8 bg-emerald-600 text-white rounded-xl text-sm font-bold hover:bg-emerald-700 transition-colors shadow-sm disabled:opacity-50"
              disabled={!selectedSource || !selectedDestination || !ratioValue}
            >
              <Plus size={16} />
              {t('transformations.modal_relation.create')}
            </button>
          </div>
        </form>
      </PremiumModal>

      {/* ===== Modal Transformer ===== */}
      <PremiumModal
        isOpen={isTransformerModalOpen && !!transformationData.relation}
        onClose={() => setIsTransformerModalOpen(false)}
        title={t('transformations.modal_transform.title')}
        subtitle={t('transformations.modal_transform.subtitle')}
        icon={
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-accent" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
          </svg>
        }
        gradientFrom="accent/10"
        gradientVia="primary/5"
        gradientTo="success/10"
        maxWidth="max-w-xl"
        disableClose={submitting}
      >
        {transformationData.relation && (
          <form onSubmit={handleTransformer} className="p-6 space-y-5">
            {/* Source ÔåÆ Destination cards */}
            <div className="flex items-stretch gap-3">
              {/* Source */}
              <div className="flex-1 bg-gradient-to-b from-red-50 to-transparent border border-red-200 rounded-2xl p-4 text-center">
                <div className="text-[9px] font-black uppercase tracking-widest text-red-400 mb-3 flex items-center justify-center gap-1">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M20 12H4" />
                  </svg>
                  {t('common:source')}
                </div>
                <div className="font-bold text-slate-800 text-xs mb-4 h-8 flex items-center justify-center line-clamp-2" title={transformationData.relation.produit_source_nom}>{transformationData.relation.produit_source_nom}</div>
                <input 
                  type="number" 
                  className="w-full h-14 rounded-xl border-2 border-slate-200 bg-slate-50 text-2xl font-black text-center focus:outline-none focus:bg-white focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 transition-all"
                  min="1"
                  value={transformationData.quantite}
                  onChange={e => setTransformationData({...transformationData, quantite: normalizeNumberInput(e.target.value)})}
                  required
                  autoFocus
                />
                <div className="text-[10px] uppercase font-black text-slate-400 mt-3">{t('transformations.modal_transform.qty_to_transform')}</div>
              </div>

              {/* Arrow */}
              <div className="flex flex-col items-center justify-center gap-2 px-1 pt-6">
                <div className="size-10 rounded-full bg-slate-100 flex items-center justify-center shadow-inner">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M17 8l4 4m0 0l-4 4m4-4H3" />
                  </svg>
                </div>
                <span className="text-[9px] font-black text-emerald-600 bg-emerald-50 px-2.5 py-1 rounded-full border border-emerald-200">├ù {transformationData.relation.ratio}</span>
              </div>

              {/* Destination */}
              <div className="flex-1 bg-gradient-to-b from-emerald-50 to-transparent border border-emerald-200 rounded-2xl p-4 text-center">
                <div className="text-[9px] font-black uppercase tracking-widest text-emerald-400 mb-3 flex items-center justify-center gap-1">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" />
                  </svg>
                  {t('common:destination')}
                </div>
                <div className="font-bold text-slate-800 text-xs mb-4 h-8 flex items-center justify-center line-clamp-2" title={transformationData.relation.produit_destination_nom}>{transformationData.relation.produit_destination_nom}</div>
                <div className="w-full h-14 rounded-xl bg-emerald-50 border-2 border-emerald-200 flex items-center justify-center font-black text-2xl text-emerald-600 shadow-inner">
                  {formatNumber(quantiteDestinationCalculee)}
                </div>
                <div className="text-[10px] uppercase font-black text-emerald-400 mt-3">{t('transformations.modal_transform.qty_obtained')}</div>
                {preview && (
                  <div className="mt-3 pt-3 border-t border-emerald-100 space-y-1">
                    <div className="flex items-center justify-between text-[10px]">
                      <span className="text-slate-400 font-bold uppercase tracking-wider">{t('stock:transformations.preview.current_stock')}</span>
                      <span className="font-bold text-slate-600">{formatNumber(preview.stock_destination)}</span>
                    </div>
                    <div className="flex items-center justify-between text-[10px]">
                      <span className="text-emerald-400 font-bold uppercase tracking-wider">{t('stock:transformations.preview.stock_after')}</span>
                      <span className="font-bold text-emerald-600">{formatNumber(preview.stock_destination_after)}</span>
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Informations stock source et lots */}
            {preview && (
              <div className="bg-slate-50 rounded-2xl border border-slate-200 p-4 space-y-3">
                <div className="flex items-center justify-between text-sm">
                  <span className="text-slate-500">{t('stock:transformations.preview.stock_remaining')}</span>
                  <span className="font-bold text-slate-800">
                    {formatNumber(preview.stock_source - manualTotal)} / {formatNumber(preview.stock_source)}
                  </span>
                </div>
                {preview.use_lot_management && preview.lots.length > 0 && (
                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <div className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                        {t('stock:transformations.preview.lots_consumed')}
                      </div>
                      <div className={`text-[10px] font-bold ${manualTotal === transformationData.quantite ? 'text-emerald-600' : 'text-amber-600'}`}>
                        {formatNumber(manualTotal)} / {formatNumber(transformationData.quantite)} {t('stock:transformations.preview.selected')}
                      </div>
                    </div>
                    <div className="space-y-1.5 max-h-40 overflow-y-auto">
                      {preview.lots.map((lot) => {
                        const currentQty = manualLots[lot.lot_id] || 0;
                        return (
                          <div key={lot.lot_id} className="flex items-center gap-2 bg-white rounded-lg px-3 py-2 border border-slate-100 text-xs">
                            <Checkbox
                              checked={currentQty > 0}
                              onChange={() => toggleManualLot(lot.lot_id, lot.quantity_remaining, currentQty)}
                            />
                            <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2">
                                <span className="font-mono font-bold text-emerald-600 truncate">{lot.lot}</span>
                                {lot.date_expiration && (
                                  <span className="text-[10px] text-slate-400">{formatDate(lot.date_expiration)}</span>
                                )}
                              </div>
                              <div className="text-[10px] text-slate-400">
                                {formatNumber(lot.quantity_remaining)} {t('stock:transformations.preview.available')}{lot.quantity_remaining > 1 ? 's' : ''}
                              </div>
                            </div>
                            <input
                              type="number"
                              min={0}
                              max={lot.quantity_remaining}
                              value={currentQty}
                              disabled={currentQty <= 0}
                              onChange={(e) => {
                                const val = normalizeNumberInput(e.target.value);
                                updateManualLotQty(lot.lot_id, Math.min(val, lot.quantity_remaining));
                              }}
                              className="w-16 h-8 rounded-lg border border-slate-200 text-center text-xs font-bold focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 disabled:bg-slate-100 disabled:text-slate-400"
                            />
                            <div className="text-right w-14 shrink-0 text-[10px] text-slate-400">
                              {formatNumber(lot.quantity_remaining - currentQty)} {t('stock:transformations.preview.remaining')}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                    {manualTotal !== transformationData.quantite && (
                      <p className="text-[11px] text-amber-600 mt-2">
                        {t('stock:transformations.preview.lot_qty_mismatch', {
                          selected: formatNumber(manualTotal),
                          total: formatNumber(transformationData.quantite)
                        })}
                      </p>
                    )}
                  </div>
                )}
              </div>
            )}

            {/* Notes */}
            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 flex items-center gap-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                </svg>
                {t('transformations.modal_transform.notes_label')}
              </label>
              <textarea 
                className="w-full h-20 rounded-xl border-2 border-slate-200 bg-slate-50 p-4 text-sm font-medium text-slate-700 focus:outline-none focus:bg-white focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 transition-all resize-none" 
                placeholder={t('transformations.modal_transform.notes_placeholder')}
                value={transformationData.notes}
                onChange={e => setTransformationData({...transformationData, notes: e.target.value})}
              ></textarea>
            </div>

            {/* Footer Actions */}
            <div className="flex justify-end gap-3 pt-4 border-t border-slate-200">
              <button 
                type="button" 
                className="h-10 px-6 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-100 transition-colors disabled:opacity-50" 
                onClick={() => setIsTransformerModalOpen(false)} 
                disabled={submitting}
              >
                {t('transformations.modal_relation.cancel')}
              </button>
              <button 
                type="submit" 
                className="inline-flex items-center gap-2 h-10 px-8 bg-purple-600 text-white rounded-xl text-sm font-bold hover:bg-purple-700 transition-colors shadow-sm disabled:opacity-50"
                disabled={submitting || (preview?.use_lot_management && manualTotal !== transformationData.quantite)}
              >
                {submitting ? (
                  <span className="size-4 border-2 border-purple-300 border-t-white rounded-full animate-spin"></span>
                ) : (
                  <>
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                    </svg>
                    {t('transformations.modal_transform.confirm_btn')}
                  </>
                )}
              </button>
            </div>
          </form>
        )}
      </PremiumModal>

    </div>
  );
};

export default Transformations;

import React, { useState, useEffect, useRef } from 'react';
import api from '../services/api';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { format } from 'date-fns';
import { fr } from 'date-fns/locale';
import { LogOut, Monitor, Users, Clock, CalendarDays, Search, Loader2 } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { getLocale } from '../utils/dateUtils';

import { Card, CardHeader, CardTitle, CardDescription, CardContent } from './shadcn/card';
import { Button } from './shadcn/button';
import { Input } from './shadcn/input';
import { Badge } from './shadcn/badge';
import { Tabs, TabsList, TabsTrigger } from './shadcn/tabs';

import { Label } from './ui/Label';
import { Select } from './ui/Select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from './ui/Table';

interface UserSession {
  id: number;
  user: number;
  username: string;
  full_name: string;
  date: string;
  first_login: string;
  last_logout: string | null;
  duration_display: string;
  workstation: string | null;
}

interface RecapStats {
  user_id: number;
  username: string;
  full_name: string;
  days_count: number;
  total_hours: number;
  total_minutes: number;
  total_duration_display: string;
  avg_duration_display: string;
}

const formatTime = (dateStr: string | null) => {
  if (!dateStr) return '---';
  return format(new Date(dateStr), 'HH:mm:ss');
};

const UserSessionsShadcn: React.FC = () => {
  const { t, i18n } = useTranslation(['users', 'common']);
  const { user, getServerDate } = useAuth();
  const [sessions, setSessions] = useState<UserSession[]>([]);
  const [recapData, setRecapData] = useState<RecapStats[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'daily' | 'monthly'>('daily');
  const [disconnectingId, setDisconnectingId] = useState<number | null>(null);

  // Daily filters
  const [startDate, setStartDate] = useState(() => format(getServerDate(), 'yyyy-MM-dd'));
  const endDateRef = useRef(format(getServerDate(), 'yyyy-MM-dd'));
  const [selectedUser, setSelectedUser] = useState<string>('');
  const [operators, setOperators] = useState<{ id: number; username: string }[]>([]);

  // Monthly recap filters
  const [recapMonth, setRecapMonth] = useState<string>(() => format(getServerDate(), 'MM'));
  const [recapYear, setRecapYear] = useState<string>(() => format(getServerDate(), 'yyyy'));

  useEffect(() => {
    fetchOperators();
    if (activeTab === 'daily') {
      fetchSessions();
    } else {
      fetchRecap();
    }
  }, [activeTab]);

  const fetchOperators = async () => {
    try {
      const response = await api.get('users/operators/');
      setOperators(response.data);
    } catch (err) {
      console.error('Error fetching operators:', err);
    }
  };

  const fetchSessions = async () => {
    setLoading(true);
    try {
      const endDate = endDateRef.current;
      let url = `user-sessions/?ordering=-date,-first_login`;
      if (startDate) url += `&date_after=${startDate}`;
      if (endDate) url += `&date_before=${endDate}`;
      if (startDate === endDate) {
        url = `user-sessions/?date=${startDate}&ordering=-first_login`;
      }
      if (selectedUser) url += `&user=${selectedUser}`;

      const response = await api.get(url);
      const sessionData = Array.isArray(response.data) ? response.data : response.data.results;
      setSessions(sessionData || []);
    } catch (err) {
      console.error('Error fetching sessions:', err);
    } finally {
      setLoading(false);
    }
  };

  const fetchRecap = async () => {
    setLoading(true);
    try {
      const response = await api.get(
        `user-sessions/recap_mensuel/?month=${recapMonth}&year=${recapYear}`
      );
      setRecapData(response.data);
    } catch (err) {
      console.error('Error fetching recap:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleFilter = (e: React.FormEvent) => {
    e.preventDefault();
    fetchSessions();
  };

  const handleRecapFilter = (e: React.FormEvent) => {
    e.preventDefault();
    fetchRecap();
  };

  const handleForceLogout = async (sessionId: number, username: string) => {
    if (!window.confirm(t('sessions.force_logout_confirm', { username }))) {
      return;
    }
    setDisconnectingId(sessionId);
    try {
      await api.post(`user-sessions/${sessionId}/force_logout/`);
      toast.success(t('sessions.force_logout_success', { username }));
      fetchSessions();
    } catch (err) {
      console.error('Error during force logout:', err);
      toast.error(t('sessions.force_logout_error'));
    } finally {
      setDisconnectingId(null);
    }
  };

  const formatDate = (dateStr: string) => {
    return format(new Date(dateStr), 'dd MMMM yyyy', {
      locale: i18n.language === 'en' ? undefined : fr,
    });
  };

  const getMonthName = (monthValue: string) => {
    const months = [
      'january', 'february', 'march', 'april', 'may', 'june',
      'july', 'august', 'september', 'october', 'november', 'december',
    ];
    const monthKey = months[parseInt(monthValue) - 1];
    return t(`common:months.${monthKey}`);
  };

  return (
    <div className="h-full flex flex-col bg-base-200 p-4 lg:p-6 gap-4 sm:gap-6">
      {/* Header + Tabs */}
      <Card className="overflow-hidden">
        <CardHeader className="p-5 lg:p-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <CardTitle className="text-2xl flex items-center gap-2">
              <Users className="size-6 text-primary" />
              {t('sessions.title')}
            </CardTitle>
            <CardDescription>{t('sessions.subtitle')}</CardDescription>
          </div>

          <Tabs
            value={activeTab}
            onValueChange={(v) => setActiveTab(v as 'daily' | 'monthly')}
          >
            <TabsList className="grid w-full md:w-auto grid-cols-2">
              <TabsTrigger value="daily">{t('sessions.tabs.daily')}</TabsTrigger>
              <TabsTrigger value="monthly">{t('sessions.tabs.monthly')}</TabsTrigger>
            </TabsList>
          </Tabs>
        </CardHeader>

        <CardContent className="p-5 lg:p-6 bg-base-100">
          {activeTab === 'daily' ? (
            <form onSubmit={handleFilter} className="flex flex-wrap items-end gap-4">
              <div className="space-y-1.5">
                <Label htmlFor="session-date">{t('sessions.date')}</Label>
                <Input
                  id="session-date"
                  type="date"
                  lang={getLocale()}
                  className="w-full md:w-44"
                  value={startDate}
                  onChange={(e) => {
                    setStartDate(e.target.value);
                    endDateRef.current = e.target.value;
                  }}
                />
              </div>

              {user?.is_superuser && (
                <div className="space-y-1.5">
                  <Label htmlFor="session-operator">{t('sessions.operator')}</Label>
                  <Select
                    id="session-operator"
                    containerClassName="w-full md:w-56"
                    value={selectedUser}
                    onChange={(e) => setSelectedUser(e.target.value)}
                  >
                    <option value="">{t('sessions.all_operators')}</option>
                    {operators.map((op) => (
                      <option key={op.id} value={op.id}>
                        {op.username}
                      </option>
                    ))}
                  </Select>
                </div>
              )}

              <Button type="submit" disabled={loading} className="gap-2">
                {loading ? <Loader2 className="size-4 animate-spin" /> : <Search className="size-4" />}
                {t('common:filter')}
              </Button>
            </form>
          ) : (
            <form onSubmit={handleRecapFilter} className="flex flex-wrap items-end gap-4">
              <div className="space-y-1.5">
                <Label htmlFor="recap-month">{t('sessions.recap.month')}</Label>
                <Select
                  id="recap-month"
                  containerClassName="w-full md:w-44"
                  value={recapMonth}
                  onChange={(e) => setRecapMonth(e.target.value)}
                >
                  {['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11', '12'].map(
                    (m) => (
                      <option key={m} value={m}>
                        {getMonthName(m)}
                      </option>
                    )
                  )}
                </Select>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="recap-year">{t('sessions.recap.year')}</Label>
                <Select
                  id="recap-year"
                  containerClassName="w-full md:w-32"
                  value={recapYear}
                  onChange={(e) => setRecapYear(e.target.value)}
                >
                  {[2023, 2024, 2025, 2026, 2027].map((y) => (
                    <option key={y} value={y.toString()}>
                      {y}
                    </option>
                  ))}
                </Select>
              </div>

              <Button type="submit" disabled={loading} className="gap-2">
                {loading ? <Loader2 className="size-4 animate-spin" /> : <Search className="size-4" />}
                {t('common:filter')}
              </Button>
            </form>
          )}
        </CardContent>
      </Card>

      {/* Data Table */}
      <Card className="overflow-hidden">
        <div className="overflow-x-auto">
          {activeTab === 'daily' ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>{t('sessions.operator')}</TableHead>
                  <TableHead>{t('sessions.date')}</TableHead>
                  <TableHead>{t('sessions.workstation')}</TableHead>
                  <TableHead>{t('sessions.first_login')}</TableHead>
                  <TableHead>{t('sessions.last_logout')}</TableHead>
                  <TableHead>{t('sessions.duration')}</TableHead>
                  <TableHead className="text-right">{t('sessions.status')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center py-16">
                      <div className="flex flex-col items-center gap-3">
                        <Loader2 className="size-8 text-primary animate-spin" />
                        <p className="text-base-content/50 font-medium text-sm">{t('common:loading')}</p>
                      </div>
                    </TableCell>
                  </TableRow>
                ) : sessions.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center py-16 text-base-content/50 italic">
                      {t('common:no_result')}
                    </TableCell>
                  </TableRow>
                ) : (
                  sessions.map((session) => (
                    <TableRow key={session.id}>
                      <TableCell>
                        <div className="flex items-center gap-3">
                          <div className="bg-primary/10 text-primary rounded-xl size-10 flex items-center justify-center font-bold text-sm border border-primary/20 shrink-0">
                            {session.username.charAt(0).toUpperCase()}
                          </div>
                          <div>
                            <div className="font-semibold text-sm text-base-content">{session.full_name}</div>
                            <div className="text-xs text-base-content/50">@{session.username}</div>
                          </div>
                        </div>
                      </TableCell>
                      <TableCell className="text-base-content/70 font-medium text-sm">
                        <div className="flex items-center gap-1.5">
                          <CalendarDays className="size-3.5 text-base-content/40" />
                          {formatDate(session.date)}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <div className="size-8 rounded-lg bg-base-200 flex items-center justify-center text-base-content/50">
                            <Monitor size={14} />
                          </div>
                          <span className="text-sm font-medium text-base-content/70">
                            {session.workstation || '---'}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell className="font-mono font-semibold text-emerald-600 text-sm">
                        <div className="flex items-center gap-1.5">
                          <Clock className="size-3.5 text-emerald-400" />
                          {formatTime(session.first_login)}
                        </div>
                      </TableCell>
                      <TableCell className="font-mono font-semibold text-amber-600 text-sm">
                        {formatTime(session.last_logout)}
                      </TableCell>
                      <TableCell className="font-semibold text-primary text-sm">
                        {session.duration_display || t('sessions.not_closed')}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-2">
                          {session.last_logout ? (
                            <Badge variant="default">{t('sessions.closed')}</Badge>
                          ) : (
                            <>
                              {format(getServerDate(), 'yyyy-MM-dd') === session.date ? (
                                <Badge variant="default" className="animate-pulse">
                                  {t('sessions.ongoing')}
                                </Badge>
                              ) : (
                                <Badge variant="outline">
                                  {t('sessions.not_closed')}
                                </Badge>
                              )}

                              {user?.is_superuser && (
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() => handleForceLogout(session.id, session.username)}
                                  disabled={!!disconnectingId}
                                  className="text-error hover:bg-red-50"
                                  title={t('sessions.force_logout')}
                                >
                                  {disconnectingId === session.id ? (
                                    <Loader2 className="size-4 animate-spin" />
                                  ) : (
                                    <LogOut size={16} />
                                  )}
                                </Button>
                              )}
                            </>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>{t('sessions.operator')}</TableHead>
                  <TableHead className="text-center">{t('sessions.recap.days_present')}</TableHead>
                  <TableHead className="text-right">{t('sessions.recap.total_hours')}</TableHead>
                  <TableHead className="text-right">{t('sessions.recap.avg_hours')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={4} className="text-center py-16">
                      <div className="flex flex-col items-center gap-3">
                        <Loader2 className="size-8 text-primary animate-spin" />
                        <p className="text-base-content/50 font-medium text-sm">{t('common:loading')}</p>
                      </div>
                    </TableCell>
                  </TableRow>
                ) : recapData.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={4} className="text-center py-16 text-base-content/50 italic">
                      {t('common:no_result')}
                    </TableCell>
                  </TableRow>
                ) : (
                  recapData.map((stat) => (
                    <TableRow key={stat.user_id}>
                      <TableCell>
                        <div className="flex items-center gap-3">
                          <div className="bg-base-200 text-base-content/70 rounded-xl size-11 flex items-center justify-center font-bold text-sm border border-base-300 shrink-0">
                            {stat.username.charAt(0).toUpperCase()}
                          </div>
                          <div>
                            <div className="font-bold text-base text-base-content">{stat.full_name}</div>
                            <div className="text-sm text-base-content/50">@{stat.username}</div>
                          </div>
                        </div>
                      </TableCell>
                      <TableCell className="text-center">
                        <Badge variant="outline" className="text-muted-foreground font-normal">
                          {stat.days_count} {t('sessions.recap.days_present')}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="text-xl font-black text-base-content tracking-tight">
                          {stat.total_duration_display}
                        </div>
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="text-sm font-medium text-base-content/60">
                          <span className="text-xs uppercase opacity-40 mr-1">{t('sessions.recap.avg')}</span>
                          {stat.avg_duration_display}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          )}
        </div>
      </Card>
    </div>
  );
};

export default UserSessionsShadcn;

import React, { useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation, useNavigate } from 'react-router-dom';
import { useSalesData } from '../hooks/useSalesData';
import { useInvoiceActions } from '../hooks/useInvoiceActions';

// Components
import { SalesFilters } from './sales/SalesFilters';
import { SalesTable } from './sales/SalesTable';
import { SalesQuickStats } from './sales/SalesQuickStats';
import { ClientNameModal } from './sales/modals/ClientNameModal';
import { ProductDetailsModal } from './sales/modals/ProductDetailsModal';
import TicketPreviewModal from './facturation/TicketPreviewModal';
import { usePharmacySettings } from '../hooks/usePharmacySettings';

import { TrancheHoraireStats } from './sales/TrancheHoraireStats';
import Pagination from './ui/Pagination';
import { Receipt, Plus } from 'lucide-react';
import { Link } from 'react-router-dom';
import { Button } from './shadcn/button';

const Ventes: React.FC = () => {
    const { t } = useTranslation(['sales', 'common']);
    const { settings } = usePharmacySettings();
    const location = useLocation();
    const navigate = useNavigate();
    
    // Hooks
    const { 
        setFactures,
        filteredFactures, 
        loading, 
        stats,
        users,
        filters, 
        refresh, 
        handleDeleteBrouillons,
        deleteFacture,
        bulkDeleteFactures,
        pagination
    } = useSalesData();

    const {
        modals,
        actions
    } = useInvoiceActions({ 
        setFacturesLocal: setFactures 
    });

    const [showQuickStats, setShowQuickStats] = React.useState(false);
    const [trancheStats, setTrancheStats] = React.useState<unknown>(null);

    // Handle incoming redirect from Omnisearch
    useEffect(() => {
        if (location.state?.selectedFactureId && filteredFactures.length > 0) {
            const fid = location.state.selectedFactureId;
            const found = filteredFactures.find((f: unknown) => f.id === fid);
            if (found) {
                actions.handleViewProducts(found);
                navigate(location.pathname, { replace: true, state: {} });
            }
        }
    }, [location.state, filteredFactures, actions, navigate]);
    
    return (
        <div className="h-full flex flex-col bg-slate-50 font-sans p-4 sm:p-6 gap-4 sm:gap-6">

            {/* ÔöÇÔöÇ HEADER ÔöÇÔöÇ */}
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm px-6 py-4">
                <div className="flex items-center justify-between gap-4">
                    <div className="flex items-center gap-3 min-w-0">
                        <div className="bg-emerald-100 text-emerald-600 rounded-xl p-2.5 shrink-0">
                            <Receipt className="size-6" />
                        </div>
                        <div className="min-w-0">
                            <h1 className="text-xl font-bold text-slate-900 tracking-tight truncate">
                                {t('title')}
                            </h1>
                            <p className="text-sm text-slate-500">
                                {t('subtitle')}
                            </p>
                        </div>
                    </div>
                    <Link to="/app/facturation">
                        <Button className="gap-2 rounded-xl bg-emerald-600 hover:bg-emerald-700 shadow-lg shadow-emerald-600/20">
                            <Plus className="size-4" />
                            <span className="hidden sm:inline">Nouvelle vente</span>
                            <span className="sm:hidden">Vente</span>
                        </Button>
                    </Link>
                </div>
            </div>

                <SalesFilters
                    filters={filters}
                    onDeleteDrafts={handleDeleteBrouillons}
                    onRefresh={() => { refresh(); }}
                    users={users}
                />

                <TrancheHoraireStats
                    startDate={filters.startDate}
                    endDate={filters.endDate}
                    onVerify={(data) => {
                        setTrancheStats({
                            ...stats,
                            total_ttc: data.total_ttc,
                            total_regle: data.total_regle,
                            total_en_compte: data.total_en_compte,
                        });
                        setShowQuickStats(true);
                    }}
                />

                {showQuickStats && (
                    <SalesQuickStats
                        stats={trancheStats || stats}
                        onClose={() => setShowQuickStats(false)}
                    />
                )}

                {/* Main Content: Table */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-visible">
                    <SalesTable
                        factures={filteredFactures}
                        loading={loading}
                        onView={actions.handleViewProducts}
                        onPrint={actions.handlePrintInvoice}
                        onPrintBL={actions.handlePrintBL}
                        onPrintTicket={actions.handlePrintTicket}
                        onRefund={actions.handleEditInvoice}
                        onDuplicate={actions.handleDuplicateInvoice}
                        onGenerateAvoir={actions.handleGenerateAvoir}
                        onDelete={deleteFacture}
                        onBulkDelete={bulkDeleteFactures}
                    />

                    <div className="border-t border-slate-100">
                        <Pagination
                            currentPage={pagination?.currentPage || 1}
                            totalPages={pagination?.totalPages || 1}
                            totalItems={pagination?.totalItems || 0}
                            onPrev={() => pagination?.prevPage && pagination.prevPage()}
                            onNext={() => pagination?.nextPage && pagination.nextPage()}
                            hasNext={pagination?.hasNext}
                            isLoading={loading}
                        />
                    </div>
                </div>

                {/* Modals */}
                <ProductDetailsModal 
                    isOpen={modals.showProductDetailsModal}
                    onClose={() => modals.setShowProductDetailsModal(false)}
                    facture={modals.selectedFacture}
                    loading={modals.detailsLoading}
                />

                <ClientNameModal 
                    isOpen={modals.showClientNameModal}
                    onClose={() => {
                        modals.setShowClientNameModal(false);
                    }}
                    onConfirm={actions.handleConfirmPrintClientName}
                    facture={modals.pendingPrintFacture}
                />

                <TicketPreviewModal
                    isOpen={modals.showTicketModal}
                    onClose={() => modals.setShowTicketModal(false)}
                    ticket={modals.selectedTicket}
                    settings={settings}
                />
        </div>
    );
}

export default Ventes;

import React, { useState, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { Package, Minus, Plus, Trash2, Pencil, XCircle, Ticket, Banknote, ChevronLeft, ChevronRight, Loader2 } from 'lucide-react'
import type { Facture, CouponMonnaie } from '../../types'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '../shadcn/dialog'
import { Button } from '../shadcn/button'
import { Badge } from '../shadcn/badge'
import { Checkbox } from '../shadcn/checkbox'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '../ui/Table'

interface FacturesTableProps {
  sortedFactures: Facture[]
  loading: boolean
  selectedRowIndex: number
  onSelectRow: (index: number) => void
  onEncaisser: (facture: Facture) => void
  onRemoveCoupon: (factureId: number) => void
  onModify: (facture: Facture) => void
  onCancel: (facture: Facture) => void
  onApplyCoupon: (facture: Facture) => void
  onUpdateProductQuantity: (factureId: number, produitId: number, newQty: number) => void
  onRemoveProduct: (factureId: number, produitId: number) => void
  couponsParFacture: Record<number, CouponMonnaie>
  user: unknown // Replace with proper User type if available
  myActivePoste?: unknown | null // Poste de caisse actif de l'utilisateur courant
  selectedIds?: Set<number>
  onToggleSelect?: (id: number) => void
  onSelectAll?: () => void
}

const PAGE_SIZE = 100

export const FacturesTable: React.FC<FacturesTableProps> = ({
  sortedFactures,
  loading,
  selectedRowIndex,
  onSelectRow,
  onEncaisser,
  onRemoveCoupon,
  onModify,
  onCancel,
  onApplyCoupon,
  onUpdateProductQuantity,
  onRemoveProduct,
  couponsParFacture,
  user,
  myActivePoste,
  selectedIds,
  onToggleSelect,
  onSelectAll
}) => {
  const { t } = useTranslation('caisse')
  const [previewFacture, setPreviewFacture] = useState<Facture | null>(null)
  const [page, setPage] = useState(1)

  const canModify = user?.is_superuser || (user as unknown)?.can_modify_invoice || user?.profile?.can_modify_invoice
  const canCancel = user?.is_superuser || (user as unknown)?.can_cancel_invoice || user?.profile?.can_cancel_invoice
  // Pour encaisser : il faut la permission ET avoir une caisse ouverte (sauf superuser)
  const hasCashOutPermission = user?.is_superuser || (user as unknown)?.can_cash_out || user?.profile?.can_cash_out
  const hasActiveCashSession = !!myActivePoste
  const canCashOut = hasCashOutPermission && (user?.is_superuser || hasActiveCashSession)

  // Reset page if list shrinks
  useEffect(() => {
    if (page > 1 && (page - 1) * PAGE_SIZE >= sortedFactures.length) setPage(1)
  }, [sortedFactures.length, page])

  // Sync preview modal if the invoice is updated in the list
  useEffect(() => {
    if (previewFacture) {
      const updated = sortedFactures.find(f => f.id === previewFacture.id)
      if (updated) {
        setPreviewFacture(updated)
      } else {
        // If it's no longer in the list (e.g. cancelled), close the modal
        setPreviewFacture(null)
      }
    }
  }, [sortedFactures, previewFacture?.id])

  if (loading && sortedFactures.length === 0) {
    return (
      <div className="flex justify-center items-center h-64">
        <Loader2 className="size-8 animate-spin text-slate-400" />
      </div>
    )
  }

  const totalPages = Math.ceil(sortedFactures.length / PAGE_SIZE)
  const pagedFactures = sortedFactures.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE)

  if (sortedFactures.length === 0) {
    return (
      <div className="text-center py-16 bg-white">
        <div className="text-5xl mb-4">­ƒô¡</div>
        <h3 className="font-bold text-lg text-slate-800">{t('no_pending')}</h3>
        <p className="text-slate-500 text-sm mt-1">{t('no_pending_desc')}</p>
      </div>
    )
  }

  // Helper to get product display name
  const getProductName = (p: unknown): string => {
    if (typeof p.produit === 'object' && p.produit !== null) {
      return p.produit.name || `#${p.produit.id}`
    }
    if (p.produit_name) return p.produit_name
    if (p.produit_nom) return p.produit_nom
    return t('table.product_placeholder', { id: p.produit })
  }

  // Get product summary text for table cell  
  const getProductsSummary = (facture: Facture): string => {
    if (!facture.produits || facture.produits.length === 0) return '-'
    const names = facture.produits.map(getProductName)
    if (names.length <= 2) return names.join(', ')
    return `${names[0]}, ${names[1]} +${names.length - 2}`
  }

  return (
    <>
      <div className="overflow-auto flex-1 min-h-0">
        <Table>
          <TableHeader className="bg-slate-100 sticky top-0 z-10 border-b border-slate-200">
            <TableRow className="text-xs uppercase tracking-wider text-slate-600 font-bold hover:bg-slate-100">
              {onToggleSelect && (
                <TableHead className="w-10">
                  <Checkbox
                    checked={selectedIds ? selectedIds.size === pagedFactures.length && pagedFactures.length > 0 : false}
                    onCheckedChange={() => { if (onSelectAll) onSelectAll() }}
                    onClick={(e) => e.stopPropagation()}
                    className="border-red-400 data-[state=checked]:bg-red-500"
                  />
                </TableHead>
              )}
              <TableHead>{t('table.ticket')}</TableHead>
              <TableHead>{t('table.invoice')}</TableHead>
              <TableHead>{t('table.client')}</TableHead>
              <TableHead className="hidden lg:table-cell">{t('table.date')}</TableHead>
              <TableHead className="hidden xl:table-cell">{t('table.products')}</TableHead>
              <TableHead className="hidden md:table-cell">{t('table.seller', 'Vendeur')}</TableHead>
              <TableHead className="text-right">{t('table.amount')}</TableHead>
              <TableHead className="text-center">{t('table.actions')}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {pagedFactures.map((facture, index) => {
              // R├®cup├®rer le coupon appliqu├® ├á CETTE facture sp├®cifique
              const couponPourCetteFacture = couponsParFacture[facture.id]
              const montantAPayer = Math.round(
                (facture.part_client !== null
                  ? Number(facture.part_client)
                  : Number(facture.total_ttc))
                - (couponPourCetteFacture ? Number(couponPourCetteFacture.montant) : 0)
              )
              const hasTiersPayant = facture.part_client !== null && facture.part_client !== undefined && Number(facture.part_client) >= 0 && Number(facture.part_client) < Number(facture.total_ttc)
              const isSelected = index === selectedRowIndex
              
              const isChecked = selectedIds ? selectedIds.has(facture.id) : false

              return (
                <tr 
                  key={facture.id} 
                  className={`cursor-pointer transition-all border-b border-slate-100 ${
                    isChecked
                      ? 'bg-red-50 border-l-4 border-red-500'
                      : isSelected 
                        ? 'bg-sky-50 border-l-4 border-sky-500 font-medium' 
                        : 'hover:bg-slate-50'
                  }`}
                  onClick={() => onSelectRow(index)}
                  onDoubleClick={() => {
                    if ((user as unknown)?.can_cash_out || user?.is_superuser) {
                      onEncaisser(facture)
                    }
                  }}
                >
                  {onToggleSelect && (
                    <TableCell onClick={(e) => e.stopPropagation()}>
                      <Checkbox
                        checked={isChecked}
                        onCheckedChange={() => { if (onToggleSelect) onToggleSelect(facture.id) }}
                        className="border-red-400 data-[state=checked]:bg-red-500"
                      />
                    </TableCell>
                  )}
                  <TableCell>
                    <span className="inline-flex items-center justify-center min-w-[1.75rem] px-2 h-6 rounded-md bg-slate-800 text-white text-xs font-bold shadow-sm">
                      {facture.session_ticket_number || '?'}
                    </span>
                  </TableCell>
                  <TableCell>
                    <div className="font-bold text-sky-600">#{facture.numero_facture}</div>
                    {hasTiersPayant && (
                      <Badge variant="outline" className="bg-amber-100 text-amber-700 border-amber-200 mt-1 text-[10px]">{t('table.tiers_payant')}</Badge>
                    )}
                    {couponPourCetteFacture && (
                      <Badge variant="outline" className="bg-emerald-100 text-emerald-700 border-emerald-200 mt-1 text-[10px]">{t('table.coupon_applied')}</Badge>
                    )}
                  </TableCell>
                  <TableCell>
                    <div className="font-bold">{facture.client_name || t('table.passerby_client')}</div>
                  </TableCell>
                  <TableCell className="text-xs hidden lg:table-cell text-slate-600">
                    <div className="font-medium">{new Date(facture.date).toLocaleDateString('fr-FR', {
                      day: '2-digit',
                      month: '2-digit',
                      year: '2-digit'
                    })}</div>
                    <div className="text-slate-400">{new Date(facture.date).toLocaleTimeString('fr-FR', {
                      hour: '2-digit',
                      minute: '2-digit'
                    })}</div>
                  </TableCell>
                  <TableCell className="text-xs max-w-xs hidden xl:table-cell">
                    <button
                      type="button"
                      className="text-sky-600 hover:text-sky-700 hover:underline text-left truncate block max-w-[150px] font-medium"
                      onClick={(e) => {
                        e.stopPropagation()
                        setPreviewFacture(facture)
                      }}
                      onDoubleClick={(e) => e.stopPropagation()}
                      title={t('table.view_products')}
                    >
                      {getProductsSummary(facture)}
                    </button>
                  </TableCell>
                  <TableCell className="text-xs hidden md:table-cell">
                    <div className="font-medium">{facture.created_by_name || '-'}</div>
                  </TableCell>
                  <TableCell className="text-right font-mono font-bold text-lg text-slate-800">
                    {montantAPayer} {t('common:currency_symbol', 'F')}
                    {couponPourCetteFacture && (
                      <div className="text-xs font-normal text-emerald-600 line-through text-slate-500 flex items-center justify-end gap-1">
                        {hasTiersPayant ? Number(facture.part_client) : Number(facture.total_ttc)} {t('common:currency_symbol', 'F')}
                         <Button
                          variant="ghost"
                          size="icon"
                          className="size-4 text-red-500 hover:bg-red-50"
                          onClick={(e) => {
                            e.stopPropagation()
                            onRemoveCoupon(facture.id)
                          }}
                          onDoubleClick={(e) => e.stopPropagation()}
                          title={t('table.remove_coupon')}
                        >
                          <XCircle className="size-3" />
                        </Button>
                      </div>
                    )}
                  </TableCell>
                  <TableCell className="text-center">
                    <div className="flex justify-center gap-1">
                      <Button
                        variant="outline"
                        size="sm"
                        className="bg-amber-50 text-amber-700 border-amber-200 hover:bg-amber-100 hover:border-amber-300 h-8 w-8 p-0"
                        onClick={(e) => {
                           e.stopPropagation()
                           onModify(facture)
                        }}
                        onDoubleClick={(e) => e.stopPropagation()}
                        title={canModify ? t('table.modify') : t('table.not_authorized')}
                        disabled={!canModify}
                      >
                        <Pencil className="size-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        className="bg-red-50 text-red-700 border-red-200 hover:bg-red-100 hover:border-red-300 h-8 w-8 p-0"
                        onClick={(e) => {
                           e.stopPropagation()
                           onCancel(facture)
                        }}
                        onDoubleClick={(e) => e.stopPropagation()}
                        title={canCancel ? t('table.cancel') : t('table.not_authorized')}
                        disabled={!canCancel}
                      >
                        <Trash2 className="size-4" />
                      </Button>
                      {!couponPourCetteFacture && (
                        <Button
                          variant="outline"
                          size="sm"
                          className="bg-fuchsia-50 text-fuchsia-700 border-fuchsia-200 hover:bg-fuchsia-100 hover:border-fuchsia-300 h-8 w-8 p-0"
                          onClick={(e) => {
                             e.stopPropagation()
                             onApplyCoupon(facture)
                          }}
                          onDoubleClick={(e) => e.stopPropagation()}
                          title={t('table.apply_coupon')}
                        >
                          <Ticket className="size-4" />
                        </Button>
                      )}
                      <Button
                        variant="default"
                        size="sm"
                        className="bg-emerald-600 text-white hover:bg-emerald-700 gap-1 shadow-sm h-8"
                        onClick={(e) => {
                          e.stopPropagation()
                          onEncaisser(facture)
                        }}
                        onDoubleClick={(e) => e.stopPropagation()}
                        disabled={!canCashOut}
                        title={!canCashOut
                          ? (!hasActiveCashSession && !user?.is_superuser
                            ? t('table.open_cash_register_first', { defaultValue: 'Veuillez d\'abord ouvrir votre caisse' })
                            : t('table.not_authorized'))
                          : t('table.cash_in')}
                      >
                        <Banknote className="size-4" />
                        {t('table.cash_in')}
                      </Button>
                    </div>
                  </TableCell>
                </tr>
              )
            })}
          </TableBody>
        </Table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="shrink-0 bg-white border-t border-slate-200 px-4 py-2 flex items-center justify-between text-sm">
          <span className="text-slate-500">
            {(page - 1) * PAGE_SIZE + 1}ÔÇô{Math.min(page * PAGE_SIZE, sortedFactures.length)} {t('common.pagination.of', 'sur')} {sortedFactures.length}
          </span>
          <div className="flex items-center gap-1">
            <Button variant="outline" size="sm" onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}>
              <ChevronLeft className="size-4" />
              {t('common.pagination.prev', 'Pr├®c├®dent')}
            </Button>
            <span className="px-3 py-1.5 text-sm font-medium text-slate-600 bg-slate-100 rounded-md">{page}/{totalPages}</span>
            <Button variant="outline" size="sm" onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}>
              {t('common.pagination.next', 'Suivant')}
              <ChevronRight className="size-4" />
            </Button>
          </div>
        </div>
      )}

      {/* Products Preview Popup */}
      <Dialog open={!!previewFacture} onOpenChange={(open) => !open && setPreviewFacture(null)}>
        <DialogContent className="max-w-2xl p-0 gap-0 overflow-hidden" aria-labelledby="preview-title" aria-describedby="preview-desc">
          <DialogHeader className="px-6 py-5 border-b border-slate-200 bg-gradient-to-r from-emerald-50 via-white to-sky-50">
            <div className="flex items-center gap-3">
              <div className="size-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-emerald-600">
                <Package className="size-5" />
              </div>
              <div className="min-w-0">
                <DialogTitle id="preview-title" className="text-lg font-bold text-slate-800 truncate">
                  {t('table.products_preview_title', { numero: previewFacture?.numero_facture })}
                </DialogTitle>
                <DialogDescription id="preview-desc" className="text-xs text-slate-500 truncate">
                  {t('table.seller', 'Vendeur')} : {previewFacture?.created_by_name || '?'}
                </DialogDescription>
              </div>
            </div>
          </DialogHeader>

          <div className="p-6">
            {previewFacture?.produits && previewFacture.produits.length > 0 ? (
              <div className="rounded-xl border border-slate-200 overflow-hidden">
                <Table>
                  <TableHeader>
                    <TableRow className="bg-slate-50 hover:bg-slate-50">
                      <TableHead>{t('table.product')}</TableHead>
                      <TableHead className="text-center w-32">{t('table.quantity')}</TableHead>
                      <TableHead className="text-right w-28">{t('table.unit_price_short')}</TableHead>
                      <TableHead className="text-right w-28">{t('table.total')}</TableHead>
                      <TableHead className="w-10"></TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {previewFacture.produits.map((p: unknown, idx: number) => {
                      const name = getProductName(p)
                      const qty = p.quantity || p.quantite || 1
                      const price = Number(p.selling_price || p.prix_vente || 0)
                      const canModify = user?.is_superuser || user?.profile?.can_modify_invoice || (user as unknown)?.can_modify_invoice

                      return (
                        <TableRow key={p.id ?? p.produit_id ?? p.produit ?? idx} className="group">
                          <TableCell>
                            <div className="flex flex-col">
                              <span className="font-semibold text-slate-800">{name}</span>
                              {p.lot && <span className="text-[10px] text-slate-400">Lot: {p.lot}</span>}
                            </div>
                          </TableCell>
                          <TableCell className="text-center">
                            <div className="flex items-center justify-center gap-1">
                              {canModify ? (
                                <>
                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    className="size-7 text-red-600 hover:bg-red-50"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      if (qty > 1) {
                                        onUpdateProductQuantity(previewFacture.id, p.produit, qty - 1);
                                      } else if (window.confirm(t('confirm_delete_product', { name }))) {
                                        onRemoveProduct(previewFacture.id, p.produit);
                                      }
                                    }}
                                  >
                                    <Minus className="size-3.5" />
                                  </Button>
                                  <span className="font-bold min-w-[1.5rem] text-sm">{qty}</span>
                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    className="size-7 text-emerald-600 hover:bg-emerald-50"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      onUpdateProductQuantity(previewFacture.id, p.produit, qty + 1);
                                    }}
                                  >
                                    <Plus className="size-3.5" />
                                  </Button>
                                </>
                              ) : (
                                <span className="font-bold min-w-[1.5rem] text-sm">{qty}</span>
                              )}
                            </div>
                          </TableCell>
                          <TableCell className="text-right font-mono text-sm text-slate-600">{Math.round(price)} {t('common:currency_symbol', 'F')}</TableCell>
                          <TableCell className="text-right font-mono font-bold text-sm text-slate-800">{Math.round(qty * price)} {t('common:currency_symbol', 'F')}</TableCell>
                          <TableCell className="text-right">
                            {canModify && (
                              <Button
                                variant="ghost"
                                size="icon"
                                className="size-7 text-red-600 hover:bg-red-50 opacity-0 group-hover:opacity-100 transition-opacity"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  if (window.confirm(t('confirm_delete_product', { name }))) {
                                    onRemoveProduct(previewFacture.id, p.produit);
                                  }
                                }}
                              >
                                <Trash2 className="size-3.5" />
                              </Button>
                            )}
                          </TableCell>
                        </TableRow>
                      )
                    })}
                  </TableBody>
                </Table>
                <div className="flex items-center justify-between px-4 py-3 bg-slate-50 border-t border-slate-200">
                  <span className="text-sm font-semibold text-slate-600">{t('table.total_ttc')}</span>
                  <span className="text-lg font-bold font-mono text-emerald-600">
                    {Math.round(Number(previewFacture.total_ttc))} {t('common:currency_symbol', 'F')}
                  </span>
                </div>
              </div>
            ) : (
              <div className="text-center py-8 text-slate-500">
                <Package className="size-10 mx-auto mb-2 text-slate-300" />
                <p className="text-sm font-medium">{t('table.no_products')}</p>
              </div>
            )}
          </div>

          <DialogFooter className="px-6 py-4 border-t border-slate-200 bg-slate-50">
            <Button variant="outline" onClick={() => setPreviewFacture(null)}>
              {t('table.close')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  )
}

import React, { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { toast } from 'react-hot-toast'
import { cashSessionService, type PosteCaisse, type PosteVente } from '../../services/cashSessionService'
import { usePosteCaisseMode } from '../../context/PosteCaisseModeContext'
import { Monitor, Unlock, Wallet, Check, Loader2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '../shadcn/dialog'
import { Card } from '../shadcn/card'
import { Badge } from '../shadcn/badge'
import { Button } from '../shadcn/button'

interface OpenCashSessionModalProps {
  isOpen: boolean
  onClose: () => void
  onSessionOpened: (poste?: PosteVente) => void
  autoOpen?: boolean
}

export const OpenCashSessionModal: React.FC<OpenCashSessionModalProps> = ({
  isOpen,
  onClose,
  onSessionOpened,
  autoOpen = false
}) => {
  const { t } = useTranslation('caisse')
  const { setActivePosteVente } = usePosteCaisseMode()
  const [allCaisses, setAllCaisses] = useState<PosteCaisse[]>([])
  const [selectedPosteId, setSelectedPosteId] = useState<number | null>(null)
  const [fondCaisse, setFondCaisse] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [loadingCaisses, setLoadingCaisses] = useState(false)

  const loadCaisses = useCallback(async () => {
    setLoadingCaisses(true)
    try {
      const caisses = await cashSessionService.getAllCaisses()
      setAllCaisses(caisses)

      const available = caisses.filter((c) => !c.est_actif)
      if (available.length === 1) {
        setSelectedPosteId(available[0].id)
      }

      if (autoOpen && available.length === 1 && isOpen) {
        handleOpenSession(available[0].id)
      }
    } catch {
      toast.error(t('messages.error_loading_posts', { defaultValue: 'Erreur chargement postes de caisse' }))
    } finally {
      setLoadingCaisses(false)
    }
  }, [autoOpen, isOpen, t])

  useEffect(() => {
    if (isOpen) {
      setSelectedPosteId(null)
      setFondCaisse('')
      loadCaisses()
    }
  }, [isOpen, loadCaisses])

  const handleOpenSession = async (caisseId?: number) => {
    const id = caisseId ?? selectedPosteId
    if (!id || isLoading) return

    const caisse = allCaisses.find((c) => c.id === id)
    if (caisse?.est_actif) {
      toast.error(t('messages.caisse_already_open', { defaultValue: 'Ce poste de caisse est d├®j├á ouvert.' }))
      return
    }

    setIsLoading(true)
    try {
      const poste = await cashSessionService.openPosteVente(id, fondCaisse || undefined)
      setActivePosteVente(poste)
      toast.success(t('messages.session_opened', { defaultValue: 'Caisse ouverte.' }))
      onSessionOpened(poste)
      onClose()
      setFondCaisse('')
    } catch (err: unknown) {
      toast.error(err.response?.data?.detail || t('messages.error_opening', { defaultValue: 'Erreur ouverture.' }))
    } finally {
      setIsLoading(false)
    }
  }

  const handleOpen = () => {
    if (!selectedPosteId) {
      toast.error(t('messages.select_post', { defaultValue: 'Veuillez s├®lectionner un poste de caisse.' }))
      return
    }
    handleOpenSession(selectedPosteId)
  }

  const selectedCaisse = allCaisses.find((c) => c.id === selectedPosteId)
  const canOpenSelected = selectedCaisse && !selectedCaisse.est_actif

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-2xl p-0 gap-0 overflow-hidden">
        <DialogHeader className="p-6 pb-4 border-b border-slate-100">
          <div className="flex items-center gap-3">
            <div className="size-10 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center">
              <Monitor className="size-5" />
            </div>
            <div>
              <DialogTitle className="text-xl font-bold text-slate-900">
                {t('cash_session.open_title', { defaultValue: 'Ouvrir ma caisse' })}
              </DialogTitle>
              <DialogDescription className="text-sm text-slate-500 mt-1">
                {t('cash_session.select_post', { defaultValue: 'S├®lectionnez un poste de caisse' })}
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <div className="p-6 space-y-5">
          {loadingCaisses ? (
            <div className="flex flex-col items-center justify-center py-12 gap-3">
              <Loader2 className="size-8 text-emerald-600 animate-spin" />
              <p className="text-sm text-slate-500">{t('cash_session.loading', { defaultValue: 'Chargement des postes de caisse...' })}</p>
            </div>
          ) : allCaisses.length === 0 ? (
            <div className="bg-slate-50 rounded-2xl border border-slate-200 p-8 text-center">
              <div className="size-14 rounded-full bg-slate-100 text-slate-400 flex items-center justify-center mx-auto mb-4">
                <Monitor className="size-7" />
              </div>
              <p className="text-base font-semibold text-slate-700">
                {t('cash_session.no_caisse', { defaultValue: 'Aucun poste de caisse configur├®.' })}
              </p>
            </div>
          ) : (
            <>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {allCaisses.map((caisse) => {
                  const isSelected = selectedPosteId === caisse.id
                  const isActive = caisse.est_actif

                  return (
                    <Card
                      key={caisse.id}
                      onClick={() => !isActive && setSelectedPosteId(caisse.id)}
                      className={`
                        relative p-4 cursor-pointer transition-all duration-200
                        ${isSelected ? 'ring-2 ring-emerald-500 border-emerald-500 bg-emerald-50/40' : 'border-slate-200 hover:border-emerald-300 hover:shadow-md'}
                        ${isActive ? 'opacity-60 cursor-not-allowed' : ''}
                      `}
                    >
                      <div className="flex items-start gap-4">
                        <div className={`
                          size-12 rounded-xl flex items-center justify-center shrink-0
                          ${isSelected ? 'bg-emerald-100 text-emerald-600' : 'bg-slate-100 text-slate-500'}
                          ${isActive ? 'bg-amber-100 text-amber-600' : ''}
                        `}>
                          {isActive ? <Monitor className="size-6" /> : <Unlock className="size-6" />}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center justify-between gap-2">
                            <p className="font-bold text-slate-900 truncate">{caisse.nom}</p>
                            {isSelected && (
                              <div className="size-5 rounded-full bg-emerald-500 text-white flex items-center justify-center shrink-0">
                                <Check className="size-3" />
                              </div>
                            )}
                          </div>
                          <div className="mt-2 flex items-center gap-2 flex-wrap">
                            {isActive ? (
                              <Badge variant="default" className="bg-amber-500 hover:bg-amber-500">
                                {t('cash_session.open', { defaultValue: 'Ouvert' })}
                              </Badge>
                            ) : (
                              <Badge variant="outline" className="text-slate-600 border-slate-300">
                                {t('cash_session.available', { defaultValue: 'Disponible' })}
                              </Badge>
                            )}
                          </div>
                        </div>
                      </div>
                    </Card>
                  )
                })}
              </div>

              <div className="w-full">
                <label className="block py-1 text-xs font-semibold text-slate-700">
                  {t('cash_session.initial_amount', { defaultValue: 'Fond de caisse (optionnel)' })}
                </label>
                <div className="relative">
                  <Wallet className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-slate-400" />
                  <input
                    type="number"
                    step="0.01"
                    className="w-full h-10 px-3 pl-10 rounded-lg border border-slate-200 bg-white text-right font-mono text-slate-700 focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 outline-none text-sm"
                    value={fondCaisse}
                    onChange={(e) => setFondCaisse(e.target.value)}
                    placeholder="0"
                  />
                </div>
                <label className="block py-0 text-[10px] text-slate-400 mt-1">
                  {t('cash_session.amount_hint', { defaultValue: 'Laisser vide si pas de fond initial' })}
                </label>
              </div>
            </>
          )}
        </div>

        <DialogFooter className="p-6 pt-2 border-t border-slate-100 gap-3">
          <Button type="button" variant="outline" onClick={onClose} className="rounded-xl" disabled={isLoading}>
            {t('common:actions.cancel', 'Annuler')}
          </Button>
          <Button
            type="button"
            onClick={handleOpen}
            disabled={isLoading || !selectedPosteId || !canOpenSelected || allCaisses.length === 0}
            className="rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white"
          >
            {isLoading ? (
              <Loader2 className="size-4 mr-2 animate-spin" />
            ) : (
              <><Unlock className="size-4 mr-2" /> {t('cash_session.open_btn', { defaultValue: 'Ouvrir' })}</>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import React, { useState, useEffect } from 'react'
import { toast } from 'react-hot-toast'
import { useTranslation } from 'react-i18next'
import { Plus, Minus, History, CreditCard, Banknote, Calendar } from 'lucide-react'
import PremiumModal from '../common/PremiumModal'
import clientService from '../../services/clientService'
import { formatCurrency, formatDateFr } from '../../utils/formatters'
import type { Client, DepotClient } from '../../types/crm'
import { getCaissePaymentModes, getPaymentModeLabel } from '../../config/paymentModes'
import { usePharmacySettings } from '../../hooks/usePharmacySettings'

interface Props {
    isOpen: boolean
    onClose: () => void
    client: Client
    onSuccess?: () => void
}

export default function ClientDepositModal({ isOpen, onClose, client, onSuccess }: Props) {
    const { t } = useTranslation(['clients', 'common'])
    const { settings } = usePharmacySettings()
    const [activeTab, setActiveTab] = useState<'transaction' | 'history'>('transaction')
    const [type, setType] = useState<'DEPOT' | 'RETRAIT'>('DEPOT')
    const [montant, setMontant] = useState('')
    const [modePaiement, setModePaiement] = useState('especes')
    const [notes, setNotes] = useState('')
    const [loading, setLoading] = useState(false)
    const [history, setHistory] = useState<DepotClient[]>([])
    const [loadingHistory, setLoadingHistory] = useState(false)

    useEffect(() => {
        if (isOpen && activeTab === 'history') {
            fetchHistory()
        }
    }, [isOpen, activeTab, client.id])

    const fetchHistory = async () => {
        setLoadingHistory(true)
        try {
            const data = await clientService.getDepotHistory(client.id)
            setHistory(data.results || data)
        } catch (err) {
            console.error(err)
            toast.error(t('common:messages.error_loading'))
        } finally {
            setLoadingHistory(false)
        }
    }

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault()
        const amount = parseFloat(montant)
        if (isNaN(amount) || amount <= 0) {
            toast.error(t('common:messages.invalid_amount'))
            return
        }

        if (type === 'RETRAIT' && amount > parseFloat(client.solde_depot || '0')) {
            toast.error(t('common:messages.insufficient_deposit'))
            return
        }

        setLoading(true)
        try {
            await clientService.addDepot(client.id, {
                type,
                montant: amount,
                mode_paiement: modePaiement,
                notes
            })
            toast.success(t('common:messages.saved'))
            setMontant('')
            setNotes('')
            if (onSuccess) onSuccess()
            setActiveTab('history')
        } catch (err: unknown) {
            console.error(err)
            toast.error(err.response?.data?.error || t('common:messages.error_saving'))
        } finally {
            setLoading(false)
        }
    }

    return (
        <PremiumModal
            isOpen={isOpen}
            onClose={onClose}
            title={`${t('clients:finance.manage_deposit')} - ${client.name}`}
            subtitle={`${t('clients:finance.solde_depot')}: ${formatCurrency(parseFloat(client.solde_depot || '0'))}`}
            icon={<CreditCard className="size-5 text-primary" />}
            maxWidth="max-w-3xl"
        >
            <div className="flex flex-col h-full">
                {/* Tabs */}
                <div className="flex border-b border-base-300 px-6 bg-base-100 sticky top-0 z-10">
                    <button
                        className={`py-4 px-6 text-sm font-medium transition-colors border-b-2 ${activeTab === 'transaction' ? 'border-indigo-500 text-primary' : 'border-transparent text-base-content/60 hover:text-base-content'}`}
                        onClick={() => setActiveTab('transaction')}
                    >
                        <div className="flex items-center gap-2">
                            <Plus className="size-4" />
                            Transaction
                        </div>
                    </button>
                    <button
                        className={`py-4 px-6 text-sm font-medium transition-colors border-b-2 ${activeTab === 'history' ? 'border-indigo-500 text-primary' : 'border-transparent text-base-content/60 hover:text-base-content'}`}
                        onClick={() => setActiveTab('history')}
                    >
                        <div className="flex items-center gap-2">
                            <History className="size-4" />
                            {t('common:history')}
                        </div>
                    </button>
                </div>

                <div className="p-6 overflow-y-auto max-h-[60vh]">
                    {activeTab === 'transaction' ? (
                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="grid grid-cols-2 gap-4 p-1 bg-base-200 rounded-xl">
                                <button
                                    type="button"
                                    className={`flex items-center justify-center gap-2 py-3 rounded-lg text-sm font-bold transition-all ${type === 'DEPOT' ? 'bg-base-100 shadow-sm text-primary' : 'text-base-content/40 hover:text-base-content/60'}`}
                                    onClick={() => setType('DEPOT')}
                                >
                                    <Plus className="size-4" /> {t('common:add_deposit')}
                                </button>
                                <button
                                    type="button"
                                    className={`flex items-center justify-center gap-2 py-3 rounded-lg text-sm font-bold transition-all ${type === 'RETRAIT' ? 'bg-base-100 shadow-sm text-error' : 'text-base-content/40 hover:text-base-content/60'}`}
                                    onClick={() => setType('RETRAIT')}
                                >
                                    <Minus className="size-4" /> {t('common:make_withdrawal')}
                                </button>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-xs font-bold uppercase tracking-wider text-base-content/40 mb-2">{t('common:total')}</label>
                                    <div className="relative">
                                        <input
                                            type="number"
                                            className="w-full h-12 rounded-xl border border-base-300 bg-base-100 pl-10 text-sm font-medium text-base-content focus:outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all"
                                            value={montant}
                                            onChange={e => setMontant(e.target.value)}
                                            placeholder="0"
                                            required
                                        />
                                        <Banknote className="size-5 absolute left-3 top-3.5 text-base-content/30" />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-xs font-bold uppercase tracking-wider text-base-content/40 mb-2">{t('common:payment_modes.title') || 'Mode de paiement'}</label>
                                    <select
                                        className="w-full h-12 rounded-xl border border-base-300 bg-base-100 px-3 text-sm font-medium text-base-content focus:outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all appearance-none"
                                        value={modePaiement}
                                        onChange={e => setModePaiement(e.target.value)}
                                    >
                                        {getCaissePaymentModes(settings?.disabled_payment_modes, settings?.custom_payment_modes).flatMap(m => m.value !== 'depot' ? [(
                                            <option key={m.value} value={m.value}>{getPaymentModeLabel(m.value, t, settings?.custom_payment_modes)}</option>
                                        )] : [])}
                                    </select>
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-bold uppercase tracking-wider text-base-content/40 mb-2">Notes</label>
                                <textarea
                                    className="w-full rounded-xl border border-base-300 bg-base-100 p-3 text-sm font-medium text-base-content focus:outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all"
                                    rows={3}
                                    value={notes}
                                    onChange={e => setNotes(e.target.value)}
                                    placeholder="Description de la transaction..."
                                ></textarea>
                            </div>

                            <div className="flex justify-end pt-4">
                                <button
                                    type="submit"
                                    className={`inline-flex items-center justify-center gap-2 px-12 py-3 rounded-xl text-sm font-bold transition-colors shadow-lg ${type === 'DEPOT' ? 'bg-primary text-white hover:bg-primary-focus shadow-indigo-500/20' : 'bg-error text-white hover:bg-error-focus shadow-red-500/20'}`}
                                    disabled={loading}
                                >
                                    {loading && <span className="inline-block size-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>}
                                    {type === 'DEPOT' ? t('common:add_deposit') : t('common:make_withdrawal')}
                                </button>
                            </div>
                        </form>
                    ) : (
                        <div className="space-y-4">
                            {loadingHistory ? (
                                <div className="flex justify-center py-12"><span className="inline-block size-8 border-2 border-base-300 border-t-indigo-600 rounded-full animate-spin"></span></div>
                            ) : history.length > 0 ? (
                                <div className="overflow-x-auto">
                                    <table className="w-full">
                                        <thead>
                                            <tr className="text-xs uppercase tracking-wider text-base-content/40">
                                                <th>{t('common:date')}</th>
                                                <th>Type</th>
                                                <th className="text-right">{t('common:total')}</th>
                                                <th>Mode</th>
                                                <th className="min-w-[150px]">{t('common:info') || 'Info'}</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {history.map((item) => (
                                                <tr key={item.id} className="text-sm">
                                                    <td className="whitespace-nowrap flex items-center gap-2">
                                                        <Calendar className="size-3.5 text-base-content/30" />
                                                        {formatDateFr(item.date)}
                                                    </td>
                                                    <td>
                                                        <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold whitespace-nowrap ${
                                                            item.type === 'DEPOT' ? 'bg-success/20 text-success' : 
                                                            item.type === 'RETRAIT' ? 'bg-error/20 text-error' : 
                                                            item.type === 'ACHAT' ? 'bg-info/20 text-info' : 'bg-warning/20 text-warning'
                                                        }`}>
                                                            {item.type_display}
                                                        </span>
                                                    </td>
                                                    <td className={`text-right font-mono font-bold whitespace-nowrap ${
                                                        item.type === 'DEPOT' || item.type === 'ANNULATION_ACHAT' ? 'text-success' : 'text-error'
                                                    }`}>
                                                        {item.type === 'DEPOT' || item.type === 'ANNULATION_ACHAT' ? '+' : '-'} {formatCurrency(parseFloat(item.montant))}
                                                    </td>
                                                    <td className="capitalize text-xs text-base-content/60">{item.mode_paiement || '-'}</td>
                                                    <td className="text-xs whitespace-nowrap text-base-content/60">
                                                        {item.facture_numero ? `#${item.facture_numero}` : item.notes || '-'}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            ) : (
                                <div className="text-center py-12 text-base-content/40">
                                    <History className="size-12 mx-auto mb-3 text-base-content/20" />
                                    <p>{t('common:no_results_found')}</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </PremiumModal>
    )
}

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Calculator, Info, Scale, Ruler, Activity, Baby, User } from 'lucide-react';

interface BMIResult {
  value: number;
  category: string;
  color: string;
  description: string;
}

const BMICalculator: React.FC = () => {
  const { t } = useTranslation(['clients', 'common']);
  const [activeTab, setActiveTab] = useState<'adult' | 'child'>('adult');
  
  // Adult BMI State
  const [weight, setWeight] = useState<number | ''>('');
  const [height, setHeight] = useState<number | ''>('');
  const [result, setResult] = useState<BMIResult | null>(null);

  // Child Weight State
  const [age, setAge] = useState<number | ''>('');
  const [ageUnit, setAgeUnit] = useState<'months' | 'years'>('years');
  const [childWeightResult, setChildWeightResult] = useState<number | null>(null);

  // Calculate Adult BMI
  const calculateBMI = () => {
    if (weight && height) {
      const heightInMeters = height / 100;
      const bmiValue = weight / (heightInMeters * heightInMeters);
      const roundedBMI = Math.round(bmiValue * 10) / 10;

      let category = '';
      let color = '';
      let description = '';

      if (roundedBMI < 18.5) {
        category = t('bmi.categories.underweight');
        color = 'text-blue-400 bg-blue-400/10 border-blue-400/20';
        description = t('bmi.descriptions.underweight');
      } else if (roundedBMI >= 18.5 && roundedBMI <= 24.9) {
        category = t('bmi.categories.normal');
        color = 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20';
        description = t('bmi.descriptions.normal');
      } else if (roundedBMI >= 25 && roundedBMI <= 29.9) {
        category = t('bmi.categories.overweight');
        color = 'text-yellow-400 bg-yellow-400/10 border-yellow-400/20';
        description = t('bmi.descriptions.overweight');
      } else if (roundedBMI >= 30 && roundedBMI <= 34.9) {
        category = t('bmi.categories.obesity_1');
        color = 'text-orange-400 bg-orange-400/10 border-orange-400/20';
        description = t('bmi.descriptions.obesity_1');
      } else if (roundedBMI >= 35 && roundedBMI <= 39.9) {
        category = t('bmi.categories.obesity_2');
        color = 'text-red-400 bg-red-400/10 border-red-400/20';
        description = t('bmi.descriptions.obesity_2');
      } else {
        category = t('bmi.categories.obesity_3');
        color = 'text-purple-400 bg-purple-400/10 border-purple-400/20';
        description = t('bmi.descriptions.obesity_3');
      }

      setResult({
        value: roundedBMI,
        category,
        color,
        description
      });
    } else {
      setResult(null);
    }
  };

  // Calculate Child Weight (APLS Formula)
  const calculateChildWeight = () => {
    if (age === '' || age === 0) {
      setChildWeightResult(null);
      return;
    }

    let estimatedWeight = 0;
    if (ageUnit === 'months') {
      // < 1 year: (0.5 * age in months) + 4
      estimatedWeight = (0.5 * age) + 4;
    } else {
      if (age < 1) {
        estimatedWeight = (0.5 * (age * 12)) + 4;
      } else if (age >= 1 && age <= 5) {
        // 1-5 years: (2 * age in years) + 8
        estimatedWeight = (2 * age) + 8;
      } else if (age > 5 && age <= 12) {
        // 6-12 years: (3 * age in years) + 7
        estimatedWeight = (3 * age) + 7;
      } else {
        // > 12 years: Age * 4 (very rough estimation or just cap it)
        estimatedWeight = (age * 3) + 7;
      }
    }
    setChildWeightResult(Math.round(estimatedWeight * 10) / 10);
  };

  useEffect(() => {
    if (activeTab === 'adult') calculateBMI();
    else calculateChildWeight();
  }, [weight, height, age, ageUnit, activeTab]);

  const bmiRanges = [
    { label: '< 18.5', text: t('bmi.categories.underweight'), color: 'bg-blue-400' },
    { label: '18.5 - 25', text: t('bmi.categories.normal'), color: 'bg-emerald-400' },
    { label: '25 - 30', text: t('bmi.categories.overweight'), color: 'bg-yellow-400' },
    { label: '30 - 35', text: t('bmi.categories.obesity_1'), color: 'bg-orange-400' },
    { label: '35 - 40', text: t('bmi.categories.obesity_2'), color: 'bg-red-400' },
    { label: '> 40', text: t('bmi.categories.obesity_3'), color: 'bg-purple-400' },
  ];

  return (
    <div className="p-4 md:p-8 max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
        <div className="flex items-center gap-4">
          <div className="size-10 md:w-12 md:h-12 rounded-xl md:rounded-2xl bg-emerald-500/20 flex items-center justify-center text-emerald-500 shadow-lg shadow-emerald-500/10">
            <Calculator className="size-5 md:w-6 md:h-6" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-black text-base-content dark:text-white tracking-tight">{t('bmi.title')}</h2>
            <p className="text-base-content/60 dark:text-white/50 text-[10px] md:text-sm font-medium">{t('bmi.subtitle')}</p>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex bg-base-200 p-1 rounded-xl md:rounded-2xl border border-base-300">
          <button
            onClick={() => setActiveTab('adult')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg md:rounded-xl text-xs md:text-sm font-bold transition-all ${activeTab === 'adult' ? 'bg-base-100 dark:bg-slate-800 text-emerald-500 shadow-sm' : 'text-base-content/60 hover:text-base-content'}`}
          >
            <User className="size-4" />
            {t('bmi.tab_adult')}
          </button>
          <button
            onClick={() => setActiveTab('child')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg md:rounded-xl text-xs md:text-sm font-bold transition-all ${activeTab === 'child' ? 'bg-base-100 dark:bg-slate-800 text-emerald-500 shadow-sm' : 'text-base-content/60 hover:text-base-content'}`}
          >
            <Baby className="size-4" />
            {t('bmi.tab_child')}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
        {/* Input Section */}
        <div className="pharma-card p-6 md:p-8 space-y-6">
          {activeTab === 'adult' ? (
            <div className="space-y-4">
              <label className="block">
                <span className="text-[10px] md:text-xs font-black text-base-content/50 uppercase tracking-widest mb-2 block">{t('bmi.weight')}</span>
                <div className="relative group">
                  <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-base-content/30 group-focus-within:text-primary transition-colors">
                    <Scale className="size-4 md:w-5 md:h-5" />
                  </div>
                  <input
                    type="number"
                    inputMode="decimal"
                    value={weight}
                    onChange={(e) => setWeight(e.target.value === '' ? '' : parseFloat(e.target.value))}
                    placeholder={t('bmi.weight_placeholder')}
                    className="w-full bg-base-200 border border-base-300 rounded-xl md:rounded-2xl py-3 md:py-4 pl-10 md:pl-12 pr-4 text-base-content text-lg md:text-xl font-bold placeholder:text-base-content/10 focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
                  />
                </div>
              </label>

              <label className="block">
                <span className="text-[10px] md:text-xs font-black text-base-content/50 uppercase tracking-widest mb-2 block">{t('bmi.height')}</span>
                <div className="relative group">
                  <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-base-content/30 group-focus-within:text-primary transition-colors">
                    <Ruler className="size-4 md:w-5 md:h-5" />
                  </div>
                  <input
                    type="number"
                    inputMode="decimal"
                    value={height}
                    onChange={(e) => setHeight(e.target.value === '' ? '' : parseFloat(e.target.value))}
                    placeholder={t('bmi.height_placeholder')}
                    className="w-full bg-base-200 border border-base-300 rounded-xl md:rounded-2xl py-3 md:py-4 pl-10 md:pl-12 pr-4 text-base-content text-lg md:text-xl font-bold placeholder:text-base-content/10 focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
                  />
                </div>
              </label>
            </div>
          ) : (
            <div className="space-y-4">
              <label className="block">
                <span className="text-[10px] md:text-xs font-black text-base-content/50 uppercase tracking-widest mb-2 block">{t('bmi.age')}</span>
                <div className="flex gap-2">
                  <div className="relative group flex-1">
                  <input
                    type="number"
                    inputMode="decimal"
                    value={age}
                    onChange={(e) => setAge(e.target.value === '' ? '' : parseFloat(e.target.value))}
                    placeholder={t('bmi.age_placeholder', 'Ex: 4')}
                    className="w-full bg-base-200 border border-base-300 rounded-xl md:rounded-2xl py-3 md:py-4 px-4 text-base-content text-lg md:text-xl font-bold focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
                  />
                  </div>
                  <select
                    value={ageUnit}
                    onChange={(e) => setAgeUnit(e.target.value as 'months' | 'years')}
                    className="bg-base-200 border border-base-300 rounded-xl md:rounded-2xl px-4 text-xs font-bold text-base-content focus:outline-none focus:ring-2 focus:ring-primary/50"
                  >
                    <option value="years">{t('bmi.age_unit_years')}</option>
                    <option value="months">{t('bmi.age_unit_months')}</option>
                  </select>
                </div>
              </label>
            </div>
          )}

          <div className="p-3 md:p-4 bg-base-200 border border-base-300 rounded-xl md:rounded-2xl flex gap-3">
            <Info className="size-4 md:w-5 md:h-5 text-primary shrink-0 mt-0.5" />
            <p className="text-[10px] md:text-xs text-base-content/60 leading-relaxed">
              {activeTab === 'adult' ? t('bmi.info_text') : t('bmi.child_info_text')}
            </p>
          </div>
        </div>

        {/* Result Section */}
        <div className="flex flex-col gap-6">
          {activeTab === 'adult' ? (
            result ? (
              <div className={`flex-1 rounded-2xl md:rounded-3xl border p-6 md:p-8 flex flex-col items-center justify-center text-center transition-all duration-500 shadow-lg ${result.color}`}>
                <div className="text-5xl md:text-[64px] font-black leading-none mb-2 tracking-tighter">{result.value}</div>
                <div className="text-[10px] font-black uppercase tracking-[0.2em] mb-4 text-base-content/70">{t('bmi.your_bmi')}</div>
                <div className="h-px w-10 md:w-12 bg-current text-base-content/20 mb-4 md:mb-6"></div>
                <div className="text-lg md:text-xl font-bold mb-2 md:mb-3">{result.category}</div>
                <p className="text-xs md:text-sm font-medium opacity-80 leading-relaxed max-w-[280px]">{result.description}</p>
                <div className="mt-6 md:mt-8 w-full">
                  <div className="h-1.5 md:h-2 w-full bg-base-100/10 rounded-full overflow-hidden flex">
                    {bmiRanges.map((range, idx) => (
                      <div 
                        key={range.label} 
                        className={`h-full ${range.color} transition-all duration-700`}
                        style={{ 
                          width: '16.66%',
                          opacity: result.value >= (idx === 0 ? 0 : parseFloat(range.label.split('-')[0]) || 40) ? 1 : 0.2
                        }}
                      />
                    ))}
                  </div>
                </div>
              </div>
            ) : (
              <div className="flex-1 bg-base-100 border border-dashed border-base-300 rounded-2xl md:rounded-3xl p-8 flex flex-col items-center justify-center text-center">
                <Activity className="size-10 md:w-12 md:h-12 text-base-content/10 mb-4" />
                <p className="text-xs md:text-sm text-base-content/30 font-medium px-4">{t('bmi.empty_state')}</p>
              </div>
            )
          ) : (
            childWeightResult ? (
              <div className="flex-1 rounded-2xl md:rounded-3xl border border-emerald-500/20 bg-emerald-500/5 p-6 md:p-8 flex flex-col items-center justify-center text-center transition-all duration-500 shadow-lg">
                <div className="text-5xl md:text-[64px] font-black leading-none mb-2 tracking-tighter text-emerald-500">
                  {childWeightResult} <span className="text-2xl md:text-3xl">{t('bmi.unit_kg', 'kg')}</span>
                </div>
                <div className="text-[10px] font-black uppercase tracking-[0.2em] mb-4 text-emerald-500/60">{t('bmi.estimated_weight')}</div>
                <div className="h-px w-10 md:w-12 bg-emerald-500/20 mb-4 md:mb-6"></div>
                <div className="p-4 bg-emerald-500/10 rounded-2xl border border-emerald-500/10">
                  <p className="text-xs md:text-sm font-bold text-success">
                    {age} {ageUnit === 'years' ? t('bmi.age_unit_years') : t('bmi.age_unit_months')}
                  </p>
                </div>
              </div>
            ) : (
              <div className="flex-1 bg-base-100 border border-dashed border-base-300 rounded-2xl md:rounded-3xl p-8 flex flex-col items-center justify-center text-center">
                <Baby className="size-10 md:w-12 md:h-12 text-base-content/10 mb-4" />
                <p className="text-xs md:text-sm text-base-content/30 font-medium px-4">{t('bmi.empty_state')}</p>
              </div>
            )
          )}

          {/* Reference Table (Only for Adult BMI) */}
          {activeTab === 'adult' && (
            <div className="pharma-card p-5 md:p-6">
              <h3 className="text-[9px] md:text-[10px] font-black text-base-content/40 uppercase tracking-[0.2em] mb-3 md:mb-4">{t('bmi.oms_classification')}</h3>
              <div className="grid grid-cols-1 gap-1 md:gap-2">
                {bmiRanges.map((range) => (
                  <div key={range.label} className="flex items-center justify-between p-2 md:p-2.5 rounded-lg md:rounded-xl hover:bg-base-200 transition-colors">
                    <div className="flex items-center gap-2 md:gap-3">
                      <div className={`size-1.5 md:w-2 md:h-2 rounded-full ${range.color}`}></div>
                      <span className="text-[10px] md:text-xs font-semibold text-base-content/70">{range.text}</span>
                    </div>
                    <span className="text-[9px] md:text-[10px] font-black text-base-content/40 tabular-nums">{range.label}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

