                        </span>
                      </div>
                      <p className="text-sm text-slate-500 whitespace-pre-wrap">{m.content}</p>
                      {m.attachment_url && (
                        <div className="mt-3">
                          <div 
                            className="inline-flex items-center justify-center rounded-lg border border-slate-200 bg-white overflow-hidden cursor-zoom-in hover:opacity-90 max-w-xs shadow-sm"
                            onClick={() => setZoomImage(m.attachment_url as string)}
                          >
                           <img src={m.attachment_url} alt="Pi├¿ce jointe" className="max-h-32 object-contain hidden md:block" onError={(e) => e.currentTarget.style.display='none'} />
                           <div className="p-2 px-3 text-xs md:hidden flex items-center gap-2 font-medium text-blue-600"><Paperclip size={14}/> Voir la pi├¿ce jointe</div>
                          </div>
                        </div>
                      )}
                    </div>
                  ))
                )}
              </div>
            </div>
          )}

          {activeTab === 'templates' && (
            <div className="space-y-4">
              <div className="flex items-center justify-between mb-6 sticky top-0 bg-white z-10 pb-2 border-b border-slate-200">
                <h4 className="text-lg font-semibold text-slate-700">{t('templates.title')}</h4>
                <button 
                  onClick={() => { setEditingTemplate(null); setTemplateForm({title: '', content: ''}); setActiveTab('new'); }}
                  className="inline-flex items-center px-3 py-1.5 border border-indigo-600 text-xs font-medium rounded-lg text-blue-600 bg-white hover:bg-blue-50 transition-colors"
                >
                  {t('templates.manage')}
                </button>
              </div>
              <div className="grid gap-4">
                {templates.map((temp) => (
                  <div key={temp.id} className="p-4 rounded-xl border border-slate-200 bg-slate-100 group relative">
                    <div className="flex justify-between items-start mb-2 pr-16 min-w-0">
                      <h5 className="font-semibold text-blue-600 truncate">{temp.title}</h5>
                      <span className="text-[10px] text-slate-400 italic truncate ml-2">{temp.created_by_name}</span>
                    </div>
                    <p className="text-sm text-slate-500 line-clamp-3 mb-4">{temp.content}</p>
                    <div className="flex gap-2">
                      <button 
                        onClick={() => applyTemplate(temp.content)}
                        className="inline-flex items-center justify-center px-3 py-1.5 text-xs font-medium rounded-lg text-white bg-blue-600 hover:bg-blue-700 transition-colors flex-1"
                      >
                        {t('new.send')}
                      </button>
                      <button 
                        onClick={() => { setEditingTemplate(temp); setTemplateForm({title: temp.title, content: temp.content}); setActiveTab('new'); }}
                        className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-slate-100 rounded transition-colors shrink-0"
                      >
                        <Edit2 size={14} />
                      </button>
                      <button 
                        onClick={() => handleDeleteTemplate(temp.id)}
                        className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded transition-colors shrink-0"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'new' && (
            <div className="animate-in slide-in-from-right-4 duration-300 h-full flex flex-col">
              <h4 className="text-lg font-semibold text-slate-700 mb-6 border-b border-slate-200 pb-2">
                {editingTemplate ? t('templates.edit') : t('new.title')}
              </h4>
              <form onSubmit={editingTemplate ? handleSaveTemplate : handleSendMessage} className="space-y-4 md:space-y-6 flex flex-col flex-1 min-h-0">
                {editingTemplate ? (
                  <div className="w-full shrink-0">
                    <label className="block text-xs font-medium text-slate-400 uppercase tracking-wider mb-1">
                      {t('templates.placeholder_title')}
                    </label>
                    <input 
                      type="text"
                      className="w-full px-3 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white"
                      value={templateForm.title}
                      onChange={(e) => setTemplateForm({ ...templateForm, title: e.target.value })}
                      required
                      placeholder={t('templates.placeholder_title')}
                    />
                  </div>
                ) : (
                  <div className="w-full shrink-0">
                    <label className="block text-xs font-medium text-slate-400 uppercase tracking-wider mb-1">
                      {t('new.recipient')}
                    </label>
                    <select 
                      className="w-full px-3 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white"
                      value={recipientId}
                      onChange={(e) => dispatchComposer({ type: 'SET_RECIPIENT', payload: e.target.value === '' ? '' : Number(e.target.value) })}
                    >
                      <option value="">{t('new.all')}</option>
                      {users.map((u: unknown) => (
                        <option key={u.id} value={u.id}>{u.username}</option>
                      ))}
                    </select>
                  </div>
                )}

                <div className="flex-1 min-h-[100px] flex flex-col">
                  {!editingTemplate && replyingTo && (
                    <div className="mb-2 p-3 bg-blue-50 rounded-lg border border-indigo-200 flex flex-col gap-1 relative pr-8">
                       <button 
                         type="button" 
                         className="absolute right-2 top-2 text-slate-400 hover:text-red-500"
                         onClick={() => dispatchComposer({ type: 'SET_REPLY_TO', payload: null })}
                       >
                         <X size={14} />
                       </button>
                       <span className="text-xs font-semibold text-blue-600 flex items-center gap-1"><Reply size={12}/> R├®ponse ├á {replyingTo.sender_name}</span>
                       <p className="text-xs text-slate-500 line-clamp-2 italic border-l-2 border-indigo-300 pl-2">{replyingTo.content}</p>
                    </div>
                  )}
                  <label className="block text-xs font-medium text-slate-400 uppercase tracking-wider mb-1">
                    {editingTemplate ? t('templates.placeholder_content') : t('new.content')}
                  </label>
                  <textarea 
                    className="w-full flex-1 px-3 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 resize-none text-sm bg-white"
                    value={editingTemplate ? templateForm.content : msgContent}
                    onChange={(e) => editingTemplate ? setTemplateForm({ ...templateForm, content: e.target.value }) : dispatchComposer({ type: 'SET_CONTENT', payload: e.target.value })}
                    required={!attachmentFile}
                    placeholder={t('new.placeholder')}
                  />
                </div>

                {!editingTemplate && (
                  <div className="shrink-0">
                    <label className="flex items-center gap-2 px-4 py-3 rounded-lg border border-dashed border-slate-200 bg-slate-100 cursor-pointer hover:bg-slate-100 transition-colors relative">
                      <Paperclip size={18} className="text-blue-600" />
                      <span className="text-sm font-medium text-slate-500 truncate mr-8">
                        {attachmentFile ? attachmentFile.name : 'Joindre un fichier ou une image'}
                      </span>
                      <input 
                        type="file" 
                        className="hidden" 
                        onChange={(e) => {
                          if (e.target.files && e.target.files[0]) {
                            dispatchComposer({ type: 'SET_ATTACHMENT', payload: e.target.files[0] });
                          }
                        }}
                      />
                      {attachmentFile && (
                        <button 
                          type="button" 
                          className="absolute right-3 p-1 text-red-500 hover:bg-red-50 rounded-full bg-white shadow-sm"
                          onClick={(e) => { e.preventDefault(); e.stopPropagation(); dispatchComposer({ type: 'SET_ATTACHMENT', payload: null }); }}
                        >
                          <X size={14} />
                        </button>
                      )}
                    </label>
                  </div>
                )}

                <div className="flex gap-2 md:gap-3 py-4 shrink-0">
                  <button 
                    type="button" 
                    onClick={() => setActiveTab(editingTemplate ? 'templates' : 'received')}
                    className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 rounded-lg hover:bg-slate-100 transition-colors flex-1"
                  >
                    {t('common:cancel')}
                  </button>
                  <button 
                    type="submit" 
                    className="inline-flex items-center justify-center gap-2 px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700 shadow-sm flex-1"
                  >
                    <Send size={18} />
                    {editingTemplate ? t('common:save') : t('new.send')}
                  </button>
                </div>
              </form>
            </div>
          )}
        </div>
      </div>

      {zoomImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in duration-200" onClick={() => setZoomImage(null)}>
          <div className="relative max-w-5xl max-h-[90vh] size-full flex flex-col items-center justify-center" onClick={(e) => e.stopPropagation()}>
            <button className="absolute top-2 right-2 text-white/70 hover:text-white bg-black/50 hover:bg-black/70 rounded-full transition-all p-2 z-10 shadow-lg" onClick={() => setZoomImage(null)}>
               <X size={24} />
            </button>
            <div className="bg-white p-2 rounded-xl shadow-2xl h-full w-full flex items-center justify-center overflow-auto relative">
                <img src={zoomImage} alt="Zoom" className="max-w-full max-h-full object-contain" />
            </div>
          </div>
        </div>
      )}
    </PremiumModal>,
    document.body
  );
}

import React from 'react'
import { useTranslation } from 'react-i18next'
import { formatCurrency } from '../../../utils/formatters'
import { Pill, Package, FlaskConical, Search, Plus, ArrowLeft, Upload } from 'lucide-react'
import { Button } from '../../shadcn/button'
import { Badge } from '../../shadcn/badge'
import { cn } from '../../../lib/utils'
import type { ProductSearchProps, SearchMode, SearchResult, PackResult, DciResult } from './types'

export * from './types'

const modeConfig: Record<SearchMode, { icon: React.ReactNode; color: string; label: string }> = {
  products: { icon: <Pill className="size-3.5" />, color: 'emerald', label: 'products' },
  packs: { icon: <Package className="size-3.5" />, color: 'violet', label: 'packs' },
  dci: { icon: <FlaskConical className="size-3.5" />, color: 'amber', label: 'dci' }
}

export const ProductSearch: React.FC<ProductSearchProps> = ({
  searchQuery,
  setSearchQuery,
  results,
  loading,
  placeholder,
  modes = ['products'],
  showCsvImport = false,
  onSelect,
  onSelectOutOfStock,
  onCsvImport,
  onQuantityShortcut,
  // Mode DCI/Packs
  packResults = [],
  dciResults = [],
  selectedDci,
  setSelectedDci,
  dciProducts = [],
  onSelectPack,
  onSelectDci,
  // Search state
  searchInputRef,
  handleKeyDown,
  getItemProps,
  // Controlled mode
  controlledMode,
  onModeChange,
  // Permissions
  user,
  compact = false
}) => {
  const { t } = useTranslation(['facturation', 'common'])
  const [internalMode, setInternalMode] = React.useState<SearchMode>(modes[0])
  const searchMode = selectedDci ? 'dci' : (controlledMode ?? internalMode)

  const handleModeChange = (mode: SearchMode) => {
    if (onModeChange) {
      onModeChange(mode)
    } else {
      setInternalMode(mode)
    }
    setSearchQuery('')
    if (setSelectedDci) setSelectedDci(null)
    searchInputRef.current?.focus()
  }

  const onInternalKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    // Quantity shortcut
    if ((e.key === '*' || e.key === 'Multiply') && onQuantityShortcut && searchQuery && !isNaN(Number(searchQuery))) {
      e.preventDefault()
      onQuantityShortcut(Number(searchQuery))
      setSearchQuery('')
      return
    }

    const resultCount = searchMode === 'packs' ? packResults.length : 
                      searchMode === 'dci' ? (selectedDci ? dciProducts.length : dciResults.length) :
                      results.length

    handleKeyDown?.(e, resultCount)
  }

  const renderModeTabs = () => {
    if (modes.length <= 1) return null

    return (
      <div className="flex bg-slate-100 p-1 rounded-xl items-center gap-1">
        {modes.map((mode) => {
          const config = modeConfig[mode]
          const isActive = searchMode === mode && !selectedDci
          const colorClass = isActive ? `text-${config.color}-600 bg-white shadow-sm` : 'text-slate-500 hover:text-slate-700 hover:bg-slate-200'

          return (
            <Button
              key={mode}
              variant="ghost"
              size="sm"
              className={cn("h-7 px-3 text-xs font-semibold rounded-lg flex items-center gap-1.5 transition-all", colorClass)}
              onClick={() => handleModeChange(mode)}
            >
              {config.icon}
              {t(`facturation:search.tabs_${config.label}`)}
            </Button>
          )
        })}

        {showCsvImport && (
          <div className="relative border-l border-slate-200 pl-1 ml-1 flex items-center">
            <input
              type="file"
              accept=".csv"
              id="csv_import"
              className="hidden"
              onChange={(e) => {
                const file = e.target.files?.[0]
                if (file && onCsvImport) onCsvImport(file)
                e.target.value = ''
              }}
            />
            <label
              htmlFor="csv_import"
              className="flex items-center gap-1.5 px-2 py-1 text-xs font-semibold rounded-lg bg-emerald-100 text-emerald-700 hover:bg-emerald-200 cursor-pointer transition-colors"
              title={t('facturation:search.csv_import_tooltip')}
            >
              <Upload className="size-3.5" />
              CSV
            </label>
          </div>
        )}
      </div>
    )
  }

  const renderSearchInput = () => {
    const getPlaceholder = () => {
      if (placeholder) return placeholder
      if (searchMode === 'packs') return t('facturation:search.placeholder_pack')
      if (searchMode === 'dci') return t('facturation:search.placeholder_dci')
      return t('facturation:search.placeholder')
    }

    const getFocusColor = () => {
      if (searchMode === 'packs') return 'focus:ring-violet-100 focus:border-violet-300'
      if (searchMode === 'dci') return 'focus:ring-amber-100 focus:border-amber-300'
      return 'focus:ring-emerald-100 focus:border-emerald-300'
    }

    return (
      <div className="relative">
        <input
          ref={searchInputRef}
          type="text"
          placeholder={getPlaceholder()}
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          onKeyDown={onInternalKeyDown}
          className={cn(
            "w-full pl-10 pr-4 text-base h-11 bg-white border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:border-transparent transition-all",
            getFocusColor()
          )}
        />
        <Search className="size-5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
        {loading && (
          <span className="absolute right-4 top-1/2 -translate-y-1/2 inline-block size-5 border-2 border-emerald-200 border-t-emerald-600 rounded-full animate-spin" />
        )}
      </div>
    )
  }

  const renderProductItem = (item: SearchResult, idx: number) => {
    const itemProps = getItemProps?.(idx) || { className: '', style: {} }
    const isSelected = itemProps.className?.includes('shadow')
    const stock = item.stock ?? 0
    const canSellNegativeStock = user?.is_superuser || user?.profile?.can_sell_negative_stock || user?.can_sell_negative_stock
    const isOutOfStock = stock <= 0
    const isBlocked = isOutOfStock && !canSellNegativeStock
    const isNegativeStock = stock < 0
    const isZeroStock = stock === 0

    const handleClick = () => {
      if (isBlocked) return
      if (isOutOfStock && onSelectOutOfStock) {
        onSelectOutOfStock(item)
      } else {
        onSelect(item)
      }
    }

    return (
      <div
        key={item.id}
        {...itemProps}
        onClick={handleClick}
        className={cn(
          "group flex items-center justify-between p-3 rounded-lg cursor-pointer transition-all",
          isSelected ? 'bg-emerald-50 shadow-md border-l-4 border-l-emerald-500' : 'hover:bg-slate-50',
          isBlocked ? 'text-slate-400 cursor-not-allowed' : ''
        )}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <div className={cn(
              "truncate text-sm",
              isNegativeStock ? 'text-red-600 font-medium' :
              isZeroStock ? 'text-slate-500 font-normal' :
              'text-slate-800 font-bold'
            )}>{item.name}</div>
            {(item.active_promis_count ?? 0) > 0 && (
              <Badge variant="secondary" className="text-[9px] h-4 px-1 bg-amber-100 text-amber-700 border-amber-200 animate-pulse shrink-0">
                PROMIS ({item.active_promis_count})
              </Badge>
            )}
          </div>
          <div className="text-xs flex gap-3 mt-0.5">
            <span className={cn(
              isNegativeStock ? 'text-red-500 font-semibold' :
              isZeroStock ? 'text-slate-400' :
              'text-slate-500'
            )}>
              {isZeroStock
                ? t('facturation:search.out_of_stock', { defaultValue: '├ëpuis├®' })
                : `${t('facturation:search.stock_label')} ${stock}`}
            </span>
            <span className="text-slate-600 font-medium">{formatCurrency(Number(item.selling_price))}</span>
          </div>
        </div>
        {!isBlocked && (
          <Button variant="ghost" size="icon" className="size-8 opacity-0 group-hover:opacity-100 text-emerald-600 hover:text-emerald-700 hover:bg-emerald-100">
            <Plus className="size-4" />
          </Button>
        )}
      </div>
    )
  }

  const renderPackItem = (pack: PackResult, idx: number) => {
    const itemProps = getItemProps?.(idx) || { className: '', style: {} }
    const isSelected = itemProps.className?.includes('shadow')

    return (
      <div
        key={pack.id}
        {...itemProps}
        onClick={() => onSelectPack?.(pack)}
        className={cn(
          "group flex items-center justify-between p-3 rounded-lg cursor-pointer transition-all border-l-4 border-violet-400",
          isSelected ? 'shadow-md bg-violet-50' : 'hover:bg-slate-50'
        )}
      >
        <div className="flex-1 min-w-0">
          <div className="font-semibold text-violet-700 text-sm">{pack.name}</div>
          <div className="text-xs text-slate-500 mt-0.5">
            {formatCurrency(Number(pack.value))} ÔÇó {pack.products_count || pack.pack_items?.length || '?'} {t('facturation:search.products_count')}
          </div>
        </div>
        <Button variant="ghost" size="icon" className="size-8 opacity-0 group-hover:opacity-100 text-violet-600 hover:text-violet-700 hover:bg-violet-100">
          <Plus className="size-4" />
        </Button>
      </div>
    )
  }

  const renderDciItem = (dci: DciResult, idx: number) => {
    const itemProps = getItemProps?.(idx) || { className: '', style: {} }
    const isSelected = itemProps.className?.includes('shadow')

    return (
      <div
        key={dci.id}
        {...itemProps}
        onClick={() => onSelectDci?.(dci)}
        className={cn(
          "group flex items-center justify-between p-3 rounded-lg cursor-pointer transition-all border-l-4 border-amber-400",
          isSelected ? 'shadow-md bg-amber-50' : 'hover:bg-slate-50'
        )}
      >
        <div className="flex-1 min-w-0">
          <div className="font-semibold text-amber-700 text-sm">{dci.nom}</div>
          <div className="text-xs text-slate-500 mt-0.5">
            {dci.produits_count ? `${dci.produits_count} ${t('facturation:search.dci_products_count')}` : ''}
          </div>
        </div>
        <Button variant="ghost" size="icon" className="size-8 opacity-0 group-hover:opacity-100 text-amber-600 hover:text-amber-700 hover:bg-amber-100">
          <Plus className="size-4" />
        </Button>
      </div>
    )
  }

  const renderResults = () => {
    // DCI Products view
    if (selectedDci && searchMode === 'dci') {
      return (
        <div className="p-2">
          <div className="flex items-center justify-between mb-2 p-2 bg-amber-50 rounded-lg border border-amber-100">
            <div className="flex items-center gap-2">
              <FlaskConical className="size-4 text-amber-600" />
              <span className="font-semibold text-sm text-amber-800">{selectedDci.nom}</span>
            </div>
            <Button
              variant="ghost"
              size="sm"
              className="h-7 text-xs text-amber-700 hover:text-amber-800 hover:bg-amber-100"
              onClick={() => setSelectedDci?.(null)}
            >
              <ArrowLeft className="size-3.5 mr-1" />
              Retour
            </Button>
          </div>
          <div className="max-h-80 overflow-y-auto space-y-0.5">
            {dciProducts.map((produit, idx) => renderProductItem(produit as SearchResult, idx))}
          </div>
        </div>
      )
    }

    // Pack results
    if (searchMode === 'packs') {
      if (packResults.length === 0) {
        return (
          <div className="text-center py-8 text-slate-400 text-sm">
            {searchQuery.length < 2 ? t('facturation:search.placeholder_pack') : t('facturation:search.no_results_pack')}
          </div>
        )
      }
      return (
        <div className="max-h-96 overflow-y-auto space-y-0.5 p-1">
          {packResults.map((pack, idx) => renderPackItem(pack, idx))}
        </div>
      )
    }

    // DCI results
    if (searchMode === 'dci') {
      if (dciResults.length === 0) {
        return (
          <div className="text-center py-8 text-slate-400 text-sm">
            {searchQuery.length < 2 ? t('facturation:search.min_chars') : t('facturation:search.no_results_dci')}
          </div>
        )
      }
      return (
        <div className="max-h-96 overflow-y-auto space-y-0.5 p-1">
          {dciResults.map((dci, idx) => renderDciItem(dci, idx))}
        </div>
      )
    }

    // Product results (default)
    if (results.length === 0) {
      return (
        <div className="text-center py-8 text-slate-400 text-sm">
          {searchQuery.length < 2 ? t('facturation:search.min_chars') : t('facturation:search.no_results')}
        </div>
      )
    }

    return (
      <div className="max-h-96 overflow-y-auto space-y-0.5 p-1">
        {results.map((item, idx) => renderProductItem(item, idx))}
      </div>
    )
  }

  const hasResults = searchQuery || selectedDci

  return (
    <div className={cn("flex-1 relative flex flex-col gap-2", compact ? "p-0" : "p-3 md:p-4")}>
      {!compact && (
        <div className="flex justify-between items-center">
          <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider py-0">
            {searchMode === 'packs' ? t('facturation:search.label_pack') : 
             searchMode === 'dci' ? t('facturation:search.label_dci') : 
             t('facturation:search.label')}
          </label>
          {renderModeTabs()}
        </div>
      )}
      {compact && modes.length > 1 && (
        <div className="absolute right-0 top-0 z-10">
          {renderModeTabs()}
        </div>
      )}

      {renderSearchInput()}

      {hasResults && (
        <div className="absolute left-0 right-0 top-full mt-2 bg-white rounded-xl shadow-xl shadow-slate-200/50 border border-slate-200 max-h-[60vh] overflow-y-auto z-50">
          {renderResults()}
        </div>
      )}
    </div>
  )
}

