import { useState, useEffect, useRef } from 'react';
import toast from 'react-hot-toast';
import { useAuth } from '../../context/AuthContext';
import { useSidebar } from '../../hooks/useSidebar';
import { useTranslation } from 'react-i18next';
import communicationService from '../../services/communicationService';
import MessagingModal from './MessagingModal';
import FeedbackModal from './FeedbackModal';
import { Bell, ChevronDown, LogOut, Moon, Sun, MessageSquare, User as UserIcon, MessageCircle } from 'lucide-react';
import { playNotificationSound } from '../../utils/audio';

export default function UserHeader() {
  const { t, i18n } = useTranslation(['messaging', 'sidebar', 'common']);
  const { user, logout } = useAuth();
  const { isMidnightTheme, toggleMidnightTheme } = useSidebar();
  const [unreadCount, setUnreadCount] = useState(0);
  const [isMessagingOpen, setIsMessagingOpen] = useState(false);
  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const prevUnreadCount = useRef<number>(0);

  const fetchUnread = async () => {
    if (!user) return;
    try {
      const res = await communicationService.getUnreadCount();
      const newCount = res.data.count || 0;
      
      // Notify if new messages arrive
      if (newCount > prevUnreadCount.current) {
        // Play an alert sound for the recipient
        playNotificationSound();

        if (!isMessagingOpen) {
          toast.success(
            (toastObj: { id: string }) => (
              <div className="flex items-center gap-3">
                <div className="flex-1">
                  <p className="text-sm font-semibold text-slate-700">{t('new.new_notification')}</p>
                  <p className="text-xs text-slate-400">{t('subtitle')}</p>
                </div>
                <button 
                  onClick={() => {
                    setIsMessagingOpen(true);
                    toast.dismiss(toastObj.id);
                  }}
                  className="px-3 py-1.5 text-xs font-medium text-white bg-emerald-600 rounded-lg hover:bg-emerald-700 transition-colors"
                >
                  {t('new.view')}
                </button>
              </div>
            ),
            { duration: 6000, position: 'top-right' }
          );
        }
      }
      
      setUnreadCount(newCount);
      prevUnreadCount.current = newCount;
    } catch (error) {
      console.error("Error fetching unread count", error);
    }
  };

  // Polling for unread messages
  useEffect(() => {
    fetchUnread();
    const interval = setInterval(fetchUnread, 30000); // Check every 30 seconds
    return () => clearInterval(interval);
  }, [user, fetchUnread]);

  // Handle outside click to close menu
  useEffect(() => {
    if (isMenuOpen) {
      const handleClickOutside = () => setIsMenuOpen(false);
      document.addEventListener('click', handleClickOutside);
      return () => document.removeEventListener('click', handleClickOutside);
    }
  }, [isMenuOpen]);

  const switchLanguage = (lng: string) => {
    i18n.changeLanguage(lng);
    localStorage.setItem('i18nextLng', lng);
  };

  if (!user) return null;

  return (
    <>
      <header className="flex items-center justify-end w-full">
        <div className="flex items-center gap-2">
          
          {/* Notifications / Messages Bell */}
          <button 
            onClick={() => setIsMessagingOpen(true)}
            className="relative p-2 rounded-full hover:bg-emerald-50 transition-colors"
            title="Messagerie Interne"
          >
            <Bell size={16} className="text-slate-500" />
            {unreadCount > 0 && (
              <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold size-5 flex items-center justify-center rounded-full animate-pulse">
                {unreadCount}
              </span>
            )}
          </button>

          {/* Feedback Button */}
          <button 
            onClick={() => setIsFeedbackOpen(true)}
            className="p-2 rounded-full hover:bg-emerald-50 transition-colors"
            title="Feedback"
          >
            <MessageCircle size={16} className="text-slate-500" />
          </button>

          {/* Language Switcher ÔÇö toujours visible */}
          <div className="flex items-center gap-0.5 bg-slate-100 rounded-lg p-0.5">
            <button
              onClick={() => switchLanguage('fr')}
              className={`px-2 py-1 rounded-md text-xs font-bold transition-all ${
                i18n.language === 'fr' || i18n.language.startsWith('fr')
                  ? 'bg-emerald-600 text-white shadow-sm'
                  : 'text-slate-400 hover:text-slate-700'
              }`}
              title="Fran├ºais"
            >
              FR
            </button>
            <button
              onClick={() => switchLanguage('en')}
              className={`px-2 py-1 rounded-md text-xs font-bold transition-all ${
                i18n.language === 'en' || i18n.language.startsWith('en')
                  ? 'bg-emerald-600 text-white shadow-sm'
                  : 'text-slate-400 hover:text-slate-700'
              }`}
              title="English"
            >
              EN
            </button>
          </div>

          <div className="h-6 w-[1px] bg-gray-300 mx-0.5"></div>

          {/* User Profile Area */}
          <div 
            className="relative"
            onClick={(e) => {
              e.stopPropagation();
              setIsMenuOpen(!isMenuOpen);
            }}
          >
            <button className="flex items-center gap-2 px-1.5 py-0.5 rounded-lg hover:bg-slate-100 transition-all group">
              <div className="size-7 rounded-full bg-emerald-600 text-white flex items-center justify-center font-bold text-sm shadow-md ring-2 ring-gray-200 overflow-hidden">
                {user.username.charAt(0).toUpperCase()}
              </div>
              <div className="hidden sm:block text-left mr-1">
                <p className="text-sm font-semibold text-slate-700 leading-none mb-1">
                  {user.username}
                </p>
                <p className="text-[10px] uppercase tracking-wider text-slate-400 font-medium">
                  {user.is_superuser ? t('sidebar:roles.pharmacist') : t('sidebar:roles.user')}
                </p>
              </div>
              <ChevronDown size={14} className={`text-slate-400 transition-transform duration-300 ${isMenuOpen ? 'rotate-180' : ''}`} />
            </button>

            {/* Dropdown Menu */}
            {isMenuOpen && (
              <div className="absolute top-full right-0 mt-2 w-64 bg-white border border-slate-200 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 z-50">
                <div className="p-4 border-b border-slate-100 bg-slate-50">
                  <p className="text-xs font-semibold text-slate-400 uppercase tracking-widest mb-2">Compte</p>
                  <div className="flex items-center gap-3">
                    <div className="size-10 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center">
                      <UserIcon size={20} />
                    </div>
                    <div className="min-w-0">
                      <p className="text-sm font-semibold text-slate-700 truncate">{user.username}</p>
                      <p className="text-xs text-slate-400 truncate">{user.email || t('sidebar:roles.user')}</p>
                    </div>
                  </div>
                </div>

                <div className="p-2">
                  <button 
                    onClick={() => setIsMessagingOpen(true)}
                    className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm hover:bg-emerald-50 hover:text-emerald-600 transition-colors text-left"
                  >
                    <MessageSquare size={18} />
                    <span className="flex-1">Messages</span>
                    {unreadCount > 0 && <span className="inline-flex items-center justify-center px-2 py-0.5 text-xs font-bold text-white bg-red-500 rounded-full">{unreadCount}</span>}
                  </button>

                  <button 
                    onClick={toggleMidnightTheme}
                    className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm hover:bg-slate-100 hover:text-slate-700 transition-colors text-left"
                  >
                    {isMidnightTheme ? <Sun size={18} className="text-amber-500" /> : <Moon size={18} className="text-emerald-600" />}
                    <span>{isMidnightTheme ? 'Mode Clair' : 'Mode Sombre'}</span>
                  </button>

                  <div className="flex items-center gap-2 p-2 mt-1">
                    <button
                      onClick={() => switchLanguage('fr')}
                      className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${i18n.language === 'fr' ? 'bg-emerald-600 text-white shadow-sm' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
                    >
                      FR
                    </button>
                    <button
                      onClick={() => switchLanguage('en')}
                      className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${i18n.language === 'en' ? 'bg-emerald-600 text-white shadow-sm' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
                    >
                      EN
                    </button>
                  </div>
                </div>

                <div className="p-2 bg-slate-50 border-t border-slate-100">
                  <button 
                    onClick={logout}
                    className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm text-red-500 hover:bg-red-50 transition-colors text-left"
                  >
                    <LogOut size={18} />
                    <span className="font-semibold">D├®connexion</span>
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </header>

      <MessagingModal 
        isOpen={isMessagingOpen}
        onClose={() => {
          setIsMessagingOpen(false);
          // Refresh unread count when closing
          const fetchUnread = async () => {
            const res = await communicationService.getUnreadCount();
            setUnreadCount(res.data.count || 0);
          };
          fetchUnread();
        }}
        onMessageRead={() => {
          fetchUnread();
        }}
        currentUser={user}
      />

      <FeedbackModal 
        isOpen={isFeedbackOpen}
        onClose={() => setIsFeedbackOpen(false)}
      />
    </>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import DatePicker, { registerLocale } from 'react-datepicker';
import { fr } from 'date-fns/locale';
import 'react-datepicker/dist/react-datepicker.css';
import type { QueryDefinition, Client } from '../../../hooks/useCentreRapports';
import { Search, User, Truck, Users, Tag, Save, History, Trash2, LayoutPanelTop, Filter, Plus, X } from 'lucide-react';
import { Button } from '../../ui/Button';
import { Input } from '../../shadcn/input';
import { Select } from '../../ui/Select';
import { Checkbox } from '../../shadcn/checkbox';
import { Badge } from '../../shadcn/badge';

registerLocale('fr', fr);

interface ReportFiltersProps {
    selectedQuery: QueryDefinition;
    params: Record<string, unknown>;
    onParamsChange: (params: Record<string, unknown>) => void;
    safeDate: (dateStr: unknown) => Date | null;
    clientSearch: {
        query: string;
        filtered: Client[];
        showDropdown: boolean;
        selectedName: string;
    };
    clientActions: {
        setQuery: (q: string) => void;
        setShowDropdown: (show: boolean) => void;
        setSelectedName: (name: string) => void;
    };
    supplierSearch: {
        query: string;
        filtered: unknown[];
        showDropdown: boolean;
        selectedName: string;
    };
    supplierActions: {
        setQuery: (q: string) => void;
        setShowDropdown: (show: boolean) => void;
        setSelectedName: (name: string) => void;
    };
    userSearch: {
        query: string;
        filtered: unknown[];
        showDropdown: boolean;
        selectedName: string;
    };
    userActions: {
        setQuery: (q: string) => void;
        setShowDropdown: (show: boolean) => void;
        setSelectedName: (name: string) => void;
    };
    familleSearch: {
        query: string;
        filtered: unknown[];
        showDropdown: boolean;
        selectedName: string;
    };
    familleActions: {
        setQuery: (q: string) => void;
        setShowDropdown: (show: boolean) => void;
        setSelectedName: (name: string) => void;
    };
    presets: {
        save: (name: string) => void;
        delete: (id: string) => void;
        apply: (preset: unknown) => void;
    };
    presetList: unknown[];
}

export const ReportFilters: React.FC<ReportFiltersProps> = ({
    selectedQuery,
    params,
    onParamsChange,
    safeDate,
    clientSearch,
    clientActions,
    supplierSearch,
    supplierActions,
    userSearch,
    userActions,
    familleSearch,
    familleActions,
    presets,
    presetList
}) => {
    const { t } = useTranslation(['reports', 'common', 'products']);
    const [conditionsOpen, setConditionsOpen] = useState(false);
    const [fieldsOpen, setFieldsOpen] = useState(false);
    const conditionsRef = useRef<HTMLDivElement>(null);
    const fieldsRef = useRef<HTMLDivElement>(null);
    const vendeurRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handler = (e: MouseEvent) => {
            if (conditionsRef.current && !conditionsRef.current.contains(e.target as Node)) setConditionsOpen(false);
            if (fieldsRef.current && !fieldsRef.current.contains(e.target as Node)) setFieldsOpen(false);
            if (vendeurRef.current && !vendeurRef.current.contains(e.target as Node)) userActions.setShowDropdown(false);
        };
        document.addEventListener('mousedown', handler);
        return () => document.removeEventListener('mousedown', handler);
    }, []);

    if (selectedQuery.params.length === 0) return null;

    const setParam = (key: string, value: unknown) => {
        onParamsChange({ ...params, [key]: value });
    };

    const getSafeConditions = () => {
        try {
            const conds = params.conditions;
            if (!conds) return [];
            return typeof conds === 'string' ? JSON.parse(conds) : conds;
        } catch (e) {
            console.error(t('reports.err_parse_conditions', { defaultValue: 'Erreur de parsing des conditions:' }), e);
            return [];
        }
    };

    const currentConditions = getSafeConditions();

    const sourceForParams = params.source || 'ventes';
    const filteredParams = selectedQuery.params.filter(param => {
                if (param.key === 'source') return true;
                if (sourceForParams === 'ventes') return !['fournisseur_id'].includes(param.key);
                if (sourceForParams === 'achats') return !['vendeur_id', 'client_id'].includes(param.key);
                if (sourceForParams === 'stock') return !['vendeur_id', 'client_id'].includes(param.key);
                if (sourceForParams === 'produits') return !['date_debut', 'date_fin', 'vendeur_id', 'client_id', 'fournisseur_id'].includes(param.key);
                return true;
            });

    return (
        <div className="flex flex-col gap-6">
            {/* Presets Toolbar */}
            <div className="flex flex-wrap items-center gap-3 border-b border-slate-200 pb-4">
                <div className="flex items-center gap-2 text-xs font-black uppercase tracking-widest text-slate-300">
                    <History className="size-3" />
                    {t('reports.my_configs', { defaultValue: 'Mes Configurations :' })}
                </div>
                {presetList.flatMap(p => p.queryId === selectedQuery.id ? [(
                    <div key={p.id} className="group flex items-center gap-1">
                        <Button
                            variant="ghost" size="sm"
                            onClick={() => presets.apply(p)}
                            className="rounded-full bg-slate-100 hover:bg-indigo-600 hover:text-white border-none transition-all px-3"
                        >
                            {p.name}
                        </Button>
                        <button 
                            onClick={() => presets.delete(p.id)}
                            className="size-7 p-0 rounded-full opacity-0 group-hover:opacity-100 text-red-600 hover:bg-red-50 transition-all flex items-center justify-center"
                        >
                            <Trash2 className="size-3" />
                        </button>
                    </div>
                )] : [])}
                <Button 
                    variant="outline" size="sm"
                    onClick={() => {
                        const name = prompt(t('reports.preset_prompt_name', { defaultValue: 'Nom de cette configuration ?' }));
                        if (name) presets.save(name);
                    }}
                    className="rounded-full gap-2"
                >
                    <Save className="size-3" />
                    {t('reports.preset_save_btn', { defaultValue: 'Sauvegarder' })}
                </Button>
            </div>

            <div className="flex flex-col sm:flex-row sm:flex-wrap gap-4 sm:gap-6 sm:items-end w-full">
            {filteredParams.map(param => (
                <div key={param.key} className="w-full sm:w-auto sm:min-w-[200px] min-w-0">
                    <label className="block py-1">
                        <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">
                            {t(`params.${param.key}`, { defaultValue: param.label })}
                            {param.required && <span className="text-red-600 ml-1">*</span>}
                        </span>
                    </label>

                        {param.type === 'month' && (
                            <DatePicker
                                selected={safeDate(params[param.key] ? params[param.key] + '-01' : null)}
                                onChange={(date: Date | null) => {
                                    if (date) {
                                        const formatted = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
                                        setParam(param.key, formatted);
                                    }
                                }}
                                dateFormat="MM/yyyy"
                                showMonthYearPicker
                                locale="fr"
                                className="w-full rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                            />
                        )}

                        {param.type === 'date' && (
                            <DatePicker
                                selected={safeDate(params[param.key])}
                                onChange={(date: Date | null) => {
                                    if (date) {
                                        const formatted = date.toISOString().slice(0, 10);
                                        setParam(param.key, formatted);
                                    }
                                }}
                                dateFormat="dd/MM/yyyy"
                                locale="fr"
                                className="w-full rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                            />
                        )}

                        {param.type === 'datetime' && (
                            <DatePicker
                                selected={safeDate(params[param.key])}
                                onChange={(date: Date | null) => {
                                    if (date) {
                                        const year = date.getFullYear();
                                        const month = String(date.getMonth() + 1).padStart(2, '0');
                                        const day = String(date.getDate()).padStart(2, '0');
                                        const hours = String(date.getHours()).padStart(2, '0');
                                        const minutes = String(date.getMinutes()).padStart(2, '0');
                                        const formatted = `${year}-${month}-${day}T${hours}:${minutes}`;
                                        setParam(param.key, formatted);
                                    }
                                }}
                                showTimeSelect
                                timeFormat="HH:mm"
                                timeIntervals={15}
                                dateFormat="dd/MM/yyyy HH:mm"
                                locale="fr"
                                className="w-full rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                            />
                        )}

                        {param.type === 'number' && (
                            <Input
                                type="number"
                                value={params[param.key] !== undefined && params[param.key] !== null ? params[param.key] : ''}
                                onChange={e => setParam(param.key, e.target.value === '' ? '' : Number(e.target.value))}
                                className="w-full rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                            />
                        )}

                        {param.type === 'text' && (
                            <Input
                                type="text"
                                value={params[param.key] || ''}
                                onChange={e => setParam(param.key, e.target.value)}
                                className="w-full rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                            />
                        )}

                        {param.type === 'client_id' && (
                            <div className="relative group">
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-600 transition-colors">
                                    <Search className="size-4" />
                                </div>
                                <Input
                                    type="text"
                                    value={clientSearch.query || clientSearch.selectedName}
                                    onChange={e => {
                                        clientActions.setQuery(e.target.value);
                                        clientActions.setSelectedName('');
                                        setParam(param.key, '');
                                    }}
                                    onFocus={() => clientSearch.query.length > 0 && clientActions.setShowDropdown(true)}
                                    placeholder={t('params.client_id', 'Rechercher un client...')}
                                    className="w-full pl-10 rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                                />
                                {clientSearch.showDropdown && clientSearch.filtered.length > 0 && (
                                    <ul className="absolute z-50 w-full bg-white shadow-xl rounded-2xl mt-2 max-h-60 overflow-auto border border-slate-200 py-2 animate-in fade-in zoom-in duration-200">
                                        {clientSearch.filtered.map(client => (
                                            <li key={client.id}>
                                                <button
                                                    type="button"
                                                    className="w-full text-left px-4 py-3 hover:bg-slate-100 transition-colors flex items-center gap-3"
                                                    onClick={() => {
                                                        setParam(param.key, client.id);
                                                        clientActions.setSelectedName(client.name);
                                                        clientActions.setQuery('');
                                                        clientActions.setShowDropdown(false);
                                                    }}
                                                >
                                                    <div className="size-8 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600">
                                                        <User className="size-4" />
                                                    </div>
                                                    <div className="flex-1">
                                                        <div className="font-bold text-sm">{client.name}</div>
                                                        {client.phone && <div className="text-[10px] text-slate-300 font-bold">{client.phone}</div>}
                                                    </div>
                                                </button>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </div>
                        )}

                        {param.type === 'fournisseur_id' && (
                            <div className="relative group">
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-600 transition-colors">
                                    <Search className="size-4" />
                                </div>
                                <Input
                                    type="text"
                                    value={supplierSearch.query || supplierSearch.selectedName}
                                    onChange={e => {
                                        supplierActions.setQuery(e.target.value);
                                        supplierActions.setSelectedName('');
                                        setParam(param.key, '');
                                    }}
                                    onFocus={() => supplierSearch.query.length > 0 && supplierActions.setShowDropdown(true)}
                                    placeholder={t('params.fournisseur_id', 'Rechercher un fournisseur...')}
                                    className="w-full pl-10 rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                                />
                                {supplierSearch.showDropdown && supplierSearch.filtered.length > 0 && (
                                    <ul className="absolute z-50 w-full bg-white shadow-xl rounded-2xl mt-2 max-h-60 overflow-auto border border-slate-200 py-2 animate-in fade-in zoom-in duration-200">
                                        {supplierSearch.filtered.map(supplier => (
                                            <li key={supplier.id}>
                                                <button
                                                    type="button"
                                                    className="w-full text-left px-4 py-3 hover:bg-slate-100 transition-colors flex items-center gap-3"
                                                    onClick={() => {
                                                        setParam(param.key, supplier.id);
                                                        supplierActions.setSelectedName(supplier.name);
                                                        supplierActions.setQuery('');
                                                        supplierActions.setShowDropdown(false);
                                                    }}
                                                >
                                                    <div className="size-8 rounded-full bg-emerald-50 flex items-center justify-center text-emerald-600">
                                                        <Truck className="size-4" />
                                                    </div>
                                                    <div className="flex-1">
                                                        <div className="font-bold text-sm">{supplier.name}</div>
                                                    </div>
                                                </button>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </div>
                        )}

                        {param.type === 'vendeur_id' && (
                            <div ref={vendeurRef} className="relative group">
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-600 transition-colors pointer-events-none">
                                    <Users className="size-4" />
                                </div>
                                <Input
                                    type="text"
                                    value={userSearch.query || userSearch.selectedName}
                                    onChange={e => {
                                        userActions.setQuery(e.target.value);
                                        userActions.setSelectedName('');
                                        setParam(param.key, '');
                                    }}
                                    onFocus={() => userActions.setShowDropdown(true)}
                                    placeholder={t('params.vendeur_id', 'Tous les vendeurs...')}
                                    className="w-full pl-10 rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                                />
                                {userSearch.showDropdown && (
                                    <ul className="absolute z-50 w-full bg-white shadow-xl rounded-2xl mt-2 max-h-60 overflow-auto border border-slate-200 py-2 animate-in fade-in zoom-in duration-200">
                                        <li>
                                            <button
                                                type="button"
                                                className="w-full text-left px-4 py-3 hover:bg-slate-100 transition-colors flex items-center gap-3"
                                                onClick={() => {
                                                    setParam(param.key, '');
                                                    userActions.setSelectedName('');
                                                    userActions.setQuery('');
                                                    userActions.setShowDropdown(false);
                                                }}
                                            >
                                                <div className="size-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500">
                                                    <Users className="size-4" />
                                                </div>
                                                <div className="flex-1">
                                                    <div className="font-bold text-sm text-slate-600">{t('params.all_vendors', 'Tous les vendeurs')}</div>
                                                </div>
                                            </button>
                                        </li>
                                        {(userSearch.query.length > 0 ? userSearch.filtered : []).map(user => (
                                            <li key={user.id}>
                                                <button
                                                    type="button"
                                                    className="w-full text-left px-4 py-3 hover:bg-slate-100 transition-colors flex items-center gap-3"
                                                    onClick={() => {
                                                        setParam(param.key, user.id);
                                                        userActions.setSelectedName(user.username);
                                                        userActions.setQuery('');
                                                        userActions.setShowDropdown(false);
                                                    }}
                                                >
                                                    <div className="size-8 rounded-full bg-blue-50 flex items-center justify-center text-blue-600">
                                                        <Users className="size-4" />
                                                    </div>
                                                    <div className="flex-1">
                                                        <div className="font-bold text-sm">{user.username}</div>
                                                    </div>
                                                </button>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </div>
                        )}

                        {param.type === 'famille_id' && (
                            <div className="relative group">
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-600 transition-colors">
                                    <Search className="size-4" />
                                </div>
                                <Input
                                    type="text"
                                    value={familleSearch.query || familleSearch.selectedName}
                                    onChange={e => {
                                        familleActions.setQuery(e.target.value);
                                        familleActions.setSelectedName('');
                                        setParam(param.key, '');
                                    }}
                                    onFocus={() => familleSearch.query.length > 0 && familleActions.setShowDropdown(true)}
                                    placeholder={t('params.famille_id', 'Rechercher une famille...')}
                                    className="w-full pl-10 rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                                />
                                {familleSearch.showDropdown && familleSearch.filtered.length > 0 && (
                                    <ul className="absolute z-50 w-full bg-white shadow-xl rounded-2xl mt-2 max-h-60 overflow-auto border border-slate-200 py-2 animate-in fade-in zoom-in duration-200">
                                        {familleSearch.filtered.map(famille => (
                                            <li key={famille.id}>
                                                <button
                                                    type="button"
                                                    className="w-full text-left px-4 py-3 hover:bg-slate-100 transition-colors flex items-center gap-3"
                                                    onClick={() => {
                                                        setParam(param.key, famille.id);
                                                        familleActions.setSelectedName(famille.nom);
                                                        familleActions.setQuery('');
                                                        familleActions.setShowDropdown(false);
                                                    }}
                                                >
                                                    <div className="size-8 rounded-full bg-amber-50 flex items-center justify-center text-amber-600">
                                                        <Tag className="size-4" />
                                                    </div>
                                                    <div className="flex-1">
                                                        <div className="font-bold text-sm">{famille.nom}</div>
                                                    </div>
                                                </button>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </div>
                        )}

                        {param.type === 'select' && param.options && (
                            <Select
                                value={params[param.key] || ''}
                                onChange={e => setParam(param.key, e.target.value)}
                                className="w-full rounded-lg border border-slate-200 bg-slate-50/50 font-bold h-10 px-3 text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 outline-none"
                            >
                                {param.options.map(opt => (
                                    <option key={opt.value} value={opt.value}>
                                        {t(`reports.query_options.${selectedQuery.id}.${param.key}.${opt.value}`, { defaultValue: opt.label })}
                                    </option>
                                ))}
                            </Select>
                        )}

                        {param.type === 'checkbox' && (
                            <div className="flex items-center gap-3 bg-slate-50/50 px-4 h-12 rounded-lg border border-slate-200">
                                <Checkbox
                                    checked={!!params[param.key]}
                                    onCheckedChange={(checked) => setParam(param.key, !!checked)}
                                />
                                <span className="text-xs font-bold uppercase tracking-tight text-slate-500">
                                    {t(`params.${param.key}_active`, { defaultValue: t('common:active', { defaultValue: 'Activ├®' }) })}
                                </span>
                            </div>
                        )}

                        {param.type === 'fields_selector' && param.options && (
                            <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center">
                                {/* Condition Builder */}
                                <div ref={conditionsRef} className="relative">
                                    <button type="button" onClick={() => setConditionsOpen(v => !v)} className="inline-flex items-center gap-2 h-12 px-6 rounded-xl border border-slate-200 hover:bg-slate-100 hover:border-slate-300 text-slate-500 cursor-pointer text-sm font-medium transition-all">
                                        <Filter className="size-4 text-indigo-600" />
                                        <span>{t('dynamic_constructor.conditions_title')}</span>
                                        {currentConditions.length > 0 && (
                                            <Badge variant="secondary" className="ml-1">{currentConditions.length}</Badge>
                                        )}
                                    </button>
                                    {conditionsOpen && (
                                    <div className="absolute z-[100] left-0 top-full p-6 shadow-2xl bg-white rounded-3xl border border-slate-200 w-[320px] sm:w-[580px] mt-2 animate-in slide-in-from-top-2 duration-300">
                                        <div className="flex items-center justify-between mb-6">
                                            <div className="text-xs font-black uppercase tracking-widest text-slate-300 flex items-center gap-2">
                                                <Filter className="size-3" />
                                                {t('dynamic_constructor.conditions_title')}
                                            </div>
                                            
                                            {/* Global Logic Toggle (AND/OR) */}
                                            <div className="flex items-center bg-slate-100 rounded-xl p-1 gap-1">
                                                <Button 
                                                    variant="ghost" size="sm"
                                                    className={`rounded-lg px-3 transition-all ${(!params.logic || params.logic === 'AND') ? 'bg-indigo-600 text-white' : ''}`}
                                                    onClick={() => setParam('logic', 'AND')}
                                                >
                                                    {t('dynamic_constructor.logic_and')}
                                                </Button>
                                                <Button 
                                                    variant="ghost" size="sm"
                                                    className={`rounded-lg px-3 transition-all ${params.logic === 'OR' ? 'bg-slate-700 text-white' : ''}`}
                                                    onClick={() => setParam('logic', 'OR')}
                                                >
                                                    {t('dynamic_constructor.logic_or')}
                                                </Button>
                                            </div>

                                            <button 
                                                className="text-xs font-medium text-red-600 hover:bg-red-50 px-2 py-1 rounded-lg transition-colors"
                                                onClick={() => setParam('conditions', '[]')}
                                            >
                                                {t('dynamic_constructor.reset_conditions')}
                                            </button>
                                        </div>

                                        <div className="space-y-3 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
                                            {currentConditions.map((cond: unknown, idx: number) => {
                                                const showValueInput = !['isnull', 'notnull'].includes(cond.operator);
                                                
                                                return (
                                                    <div key={`cond-${cond.field}-${cond.operator}`} className="flex flex-wrap items-center gap-2 p-3 bg-slate-50/50 rounded-2xl border border-slate-200 animate-in zoom-in-95 duration-200">
                                                        <Select 
                                                            className="rounded-lg flex-1 min-w-[140px] font-bold text-[11px] uppercase bg-white h-8 px-2 text-xs border border-slate-200"
                                                            value={cond.field}
                                                            onChange={(e) => {
                                                                const newConds = [...currentConditions];
                                                                newConds[idx] = { ...newConds[idx], field: e.target.value };
                                                                setParam('conditions', JSON.stringify(newConds));
                                                            }}
                                                        >
                                                            <option value="">{t('dynamic_constructor.field_placeholder')}</option>
                                                            <option value="quantite">{t('dynamic_constructor.fields.quantite')}</option>
                                                            <option value="total_ht">{t('dynamic_constructor.fields.total_ht')}</option>
                                                            <option value="prix_vente">{t('dynamic_constructor.fields.prix_vente')}</option>
                                                            <option value="cout_achat">{t('dynamic_constructor.fields.cout_achat')}</option>
                                                            <option value="pourcentage_marge">{t('dynamic_constructor.fields.pourcentage_marge')}</option>
                                                            <option value="tva">{t('dynamic_constructor.fields.tva')}</option>
                                                            <option value="cip">{t('dynamic_constructor.fields.cip')}</option>
                                                            <option value="stock_minimum">{t('dynamic_constructor.fields.stock_minimum')}</option>
                                                        </Select>

                                                        <Select 
                                                            className="rounded-lg w-32 font-bold text-[11px] bg-white h-8 px-2 text-xs border border-slate-200"
                                                            value={cond.operator}
                                                            onChange={(e) => {
                                                                const newConds = [...currentConditions];
                                                                newConds[idx] = { ...newConds[idx], operator: e.target.value };
                                                                setParam('conditions', JSON.stringify(newConds));
                                                            }}
                                                        >
                                                            <option value="gte">ÔëÑ</option>
                                                            <option value="lte">Ôëñ</option>
                                                            <option value="gt">&gt;</option>
                                                            <option value="lt">&lt;</option>
                                                            <option value="eq">=</option>
                                                            <option value="isnull">{t('dynamic_constructor.operators.isnull')}</option>
                                                            <option value="notnull">{t('dynamic_constructor.operators.notnull')}</option>
                                                        </Select>

                                                        {showValueInput ? (
                                                            <Input 
                                                                type="text"
                                                                className="rounded-lg w-24 font-bold text-[11px] bg-white h-8 px-2 text-xs border border-slate-200"
                                                                placeholder={t('dynamic_constructor.value_placeholder')}
                                                                value={cond.value}
                                                                onChange={(e) => {
                                                                    const newConds = [...currentConditions];
                                                                    newConds[idx] = { ...newConds[idx], value: e.target.value };
                                                                    setParam('conditions', JSON.stringify(newConds));
                                                                }}
                                                            />
                                                        ) : (
                                                            <div className="w-24 px-2 py-1 bg-slate-200/50 rounded-lg text-[10px] font-black uppercase text-center text-slate-300 border border-slate-200 border-dashed">
                                                                {t('dynamic_constructor.no_value')}
                                                            </div>
                                                        )}

                                                        <button 
                                                            className="size-7 p-0 rounded-full text-red-600 hover:bg-red-50 ml-auto flex items-center justify-center transition-colors"
                                                            onClick={() => {
                                                                const newConds = currentConditions.filter((_: unknown, i: number) => i !== idx);
                                                                setParam('conditions', JSON.stringify(newConds));
                                                            }}
                                                        >
                                                            <X className="size-4" />
                                                        </button>
                                                    </div>
                                                );
                                            })}
                                        </div>

                                        <Button 
                                            className="w-full rounded-xl gap-2 mt-6 h-10 shadow-lg shadow-indigo-500/20"
                                            onClick={() => {
                                                const newConds = [...currentConditions, { field: '', operator: 'gte', value: '' }];
                                                setParam('conditions', JSON.stringify(newConds));
                                            }}
                                        >
                                            <Plus className="size-4" />
                                            {t('dynamic_constructor.add_condition')}
                                        </Button>
                                    </div>
                                    )}
                                </div>

                                {/* Fields Selector Dropdown */}
                                <div ref={fieldsRef} className="relative">
                                    <button type="button" onClick={() => setFieldsOpen(v => !v)} className="inline-flex items-center gap-2 h-12 px-6 rounded-xl border border-slate-200 hover:bg-slate-100 hover:border-slate-300 text-slate-500 cursor-pointer text-sm font-medium transition-all">
                                        <LayoutPanelTop className="size-4" />
                                        <span>{t('dynamic_constructor.select_columns')}</span>
                                        <Badge className="ml-1">
                                            {(params[param.key] || '').split(',').filter(Boolean).length}
                                        </Badge>
                                    </button>
                                    {fieldsOpen && (
                                    <div className="absolute z-[100] right-0 top-full p-4 shadow-2xl bg-white rounded-2xl border border-slate-200 w-[300px] sm:w-[450px] mt-2 animate-in slide-in-from-top-2 duration-300">
                                        <div className="text-xs font-black uppercase tracking-widest text-slate-300 mb-4 flex items-center gap-2">
                                            <LayoutPanelTop className="size-3" />
                                            {t('dynamic_constructor.table_composition')}
                                        </div>
                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-[350px] overflow-y-auto custom-scrollbar pr-2">
                                            {(() => {
                                                const source = params.source || 'ventes';
                                                const filteredOptions = param.options.filter(opt => {
                                                if (source === 'ventes') {
                                                    return !['fournisseur', 'lot'].includes(opt.value);
                                                }
                                                if (source === 'achats') {
                                                    return !['vendeur', 'client', 'marge', 'pourcentage_marge', 'lot'].includes(opt.value);
                                                }
                                                if (source === 'stock') {
                                                    return !['vendeur', 'client', 'marge', 'pourcentage_marge', 'facture'].includes(opt.value);
                                                }
                                                if (source === 'produits') {
                                                    return !['date', 'facture', 'client', 'vendeur', 'lot', 'marge'].includes(opt.value);
                                                }
                                                return true;
                                            });
                                            return filteredOptions.map(opt => {
                                                const currentFields = (params[param.key] || '').split(',').filter(Boolean);
                                                const isChecked = currentFields.includes(opt.value);
                                                
                                                return (
                                                    <label key={opt.value} className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${isChecked ? 'bg-indigo-50 border-indigo-200 shadow-sm' : 'bg-slate-50/30 border-slate-200 hover:border-slate-300'}`}>
                                                        <Checkbox
                                                            checked={isChecked}
                                                            onCheckedChange={(checked) => {
                                                                let newFields;
                                                                if (checked) {
                                                                    newFields = [...currentFields, opt.value];
                                                                } else {
                                                                    newFields = currentFields.filter((f: string) => f !== opt.value);
                                                                }
                                                                setParam(param.key, newFields.join(','));
                                                            }}
                                                        />
                                                        <span className={`text-[11px] font-bold uppercase tracking-tight ${isChecked ? 'text-indigo-600' : 'text-slate-500'}`}>
                                                            {t(`reports.query_options.${selectedQuery.id}.${param.key}.${opt.value}`, { defaultValue: opt.label })}
                                                        </span>
                                                    </label>
                                                );
                                            });
                                            })()}
                                        </div>
                                        <div className="mt-4 pt-4 border-t border-slate-200 flex justify-between items-center">
                                            <div className="text-[9px] font-bold uppercase text-slate-300 italic">
                                                * {t('reports.select_columns_hint', { defaultValue: 'S├®lectionnez les colonnes ├á afficher' })}
                                            </div>
                                            <button 
                                                className="text-xs font-medium text-indigo-600 hover:bg-indigo-50 px-2 py-1 rounded-lg transition-colors"
                                                onClick={() => {
                                                    if (param.options) {
                                                        const all = param.options.map(o => o.value).join(',');
                                                        setParam(param.key, all);
                                                    }
                                                }}
                                            >
                                                {t('dynamic_constructor.check_all')}
                                            </button>
                                        </div>
                                    </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>
                ))}
            </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { 
  ShoppingBag, 
  DollarSign, 
  Calendar,
  Filter,
  CalendarDays,
  Package,
  ClipboardList,
  ChevronLeft,
  ChevronRight,
  Warehouse,
  ArrowLeft,
  Eye,
} from 'lucide-react';
import api from '../../services/api';
import { format, parseISO } from 'date-fns';
import { fr } from 'date-fns/locale';
import toast from 'react-hot-toast';
import Commandes from '../Commandes';
import { useCommandesStore } from '../../stores/useCommandesStore';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Card } from '../ui/Card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/Tabs';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from '../ui/Table';
import { Skeleton } from '../ui/Skeleton';

interface VenteDivers {
  id: number;
  date: string;
  produit_name: string;
  facture_numero: string;
  quantity: number;
  selling_price: number;
  total: number;
  lot: string;
}

interface VentesDiversesResponse {
  count: number;
  total_ca: number;
  results: VenteDivers[];
}

interface VenteJournaliere {
  date: string;
  total_ca: number;
  total_quantity: number;
  nb_produits: number;
  nb_factures: number;
}

interface VentesJournalieresResponse {
  count: number;
  total_ca: number;
  results: VenteJournaliere[];
}

interface StockDiversResponse {
  is_pmp: boolean;
  type_valorisation: string;
  total_ht: number;
  total_tva: number;
  total_ttc: number;
  tva_breakdown: Array<{
    rate: number;
    ht: number;
    tva: number;
    ttc: number;
  }>;
  rayon_breakdown: Array<{
    name: string;
    ht: number;
    tva: number;
    ttc: number;
  }>;
  date: string;
}

const GestionDivers: React.FC<{ defaultTab?: 'ca' | 'commandes' | 'stock' }> = ({ defaultTab = 'ca' }) => {
  const { t } = useTranslation('orders');
  const [activeTab, setActiveTab] = useState<'ca' | 'commandes' | 'stock'>(() => defaultTab);
  const [loading, setLoading] = useState(false);
  const [ventes, setVentes] = useState<VenteDivers[]>([]);
  const [totalCA, setTotalCA] = useState(0);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(1);
  const pageSize = 50;
  const [dateRange, setDateRange] = useState(() => ({
    debut: format(new Date(), 'yyyy-MM-dd'),
    fin: format(new Date(), 'yyyy-MM-dd')
  }));
  const [stockData, setStockData] = useState<StockDiversResponse | null>(null);
  const [stockLoading, setStockLoading] = useState(false);
  const [valorisation, setValorisation] = useState<'ACHAT' | 'VENTE'>('ACHAT');
  const isInitialMount = useRef(true);

  // Vue journali├¿re
  const [dailyVentes, setDailyVentes] = useState<VenteJournaliere[]>([]);
  const [dailyLoading, setDailyLoading] = useState(false);
  const [viewMode, setViewMode] = useState<'daily' | 'detail'>('daily');
  const [selectedDate, setSelectedDate] = useState<string | null>(null);

  // Fix #2 : Reset du store Zustand au d├®montage pour ├®viter la pollution LOC/DIR/DIV
  const setActiveTabStore = useCommandesStore((s) => s.setActiveTab);
  const setCommandeType = useCommandesStore((s) => s.setCommandeType);
  useEffect(() => {
    return () => {
      setActiveTabStore('LOC');
      setCommandeType('LOC');
    };
  }, [setActiveTabStore, setCommandeType]);

  const fetchVentesDiverses = useCallback(async (targetPage?: number) => {
    const pageToFetch = targetPage ?? page;
    setLoading(true);
    try {
      const response = await api.get<VentesDiversesResponse>('/caisse/ventes_diverses/', {
        params: {
          date: selectedDate,
          page: pageToFetch,
          page_size: pageSize
        }
      });
      setVentes(response.data.results);
      setTotalCA(response.data.total_ca);
      setTotalCount(response.data.count);
    } catch (error) {
      console.error('Error fetching divers sales:', error);
      toast.error(t('divers.error_load_detail'));
    } finally {
      setLoading(false);
    }
  }, [selectedDate]); // Retirer 'page' pour ├®viter la boucle

  const fetchVentesJournalieres = useCallback(async () => {
    setDailyLoading(true);
    try {
      const response = await api.get<VentesJournalieresResponse>('/caisse/ventes_diverses/', {
        params: {
          date_debut: dateRange.debut,
          date_fin: dateRange.fin,
          group_by: 'day'
        }
      });
      setDailyVentes(response.data.results);
      setTotalCA(response.data.total_ca);
      setTotalCount(response.data.count);
    } catch (error) {
      console.error('Error fetching daily divers sales:', error);
      toast.error(t('divers.error_load_daily'));
    } finally {
      setDailyLoading(false);
    }
  }, [dateRange.debut, dateRange.fin]);

  useEffect(() => {
    if (activeTab === 'ca') {
      if (viewMode === 'daily') {
        fetchVentesJournalieres();
      } else {
        if (isInitialMount.current) {
          isInitialMount.current = false;
          fetchVentesDiverses(1);
        } else {
          fetchVentesDiverses(page);
        }
      }
    }
  }, [activeTab, viewMode, page, fetchVentesJournalieres, fetchVentesDiverses]);

  const handleViewDetail = (date: string) => {
    setSelectedDate(date);
    setViewMode('detail');
    setPage(1);
    fetchVentesDiverses(1);
  };

  const handleBackToDaily = () => {
    setSelectedDate(null);
    setViewMode('daily');
    setVentes([]);
  };

  const fetchStockDivers = useCallback(async () => {
    setStockLoading(true);
    try {
      const response = await api.get<StockDiversResponse>('/rapports/valeur_stock_divers_json/', {
        params: { valorisation }
      });
      setStockData(response.data);
    } catch (error) {
      console.error('Error fetching divers stock:', error);
      toast.error(t('divers.error_load_stock'));
    } finally {
      setStockLoading(false);
    }
  }, [valorisation]);

  useEffect(() => {
    if (activeTab === 'stock') {
      fetchStockDivers();
    }
  }, [activeTab, fetchStockDivers]);

  // Reset page quand les dates changent
  const handleFilter = () => {
    setPage(1);
    fetchVentesDiverses(1);
  };

  const totalPages = Math.ceil(totalCount / pageSize);

  return (
    <div className="p-6 h-full flex flex-col space-y-6">
      <div className="flex items-center gap-3">
        <div className="p-2 bg-emerald-100 dark:bg-emerald-900/30 rounded-lg">
          <Package className="h-6 w-6 text-emerald-600 dark:text-emerald-400" />
        </div>
        <div>
          <h1 className="text-2xl font-bold tracking-tight">{t('divers.revenue_tab')}</h1>
          <p className="text-sm text-muted-foreground">{t('divers.imported_products_management')}</p>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as 'ca' | 'commandes' | 'stock')} className="flex-1 flex flex-col min-h-0">
        <TabsList className="grid w-full grid-cols-3 max-w-md">
          <TabsTrigger value="ca" className="gap-2">
            <DollarSign className="h-4 w-4" />
            {t('divers.revenue')}
          </TabsTrigger>
          <TabsTrigger value="commandes" className="gap-2">
            <ShoppingBag className="h-4 w-4" />
            {t('divers.orders_tab')}
          </TabsTrigger>
          <TabsTrigger value="stock" className="gap-2">
            <Warehouse className="h-4 w-4" />
            {t('divers.stock_tab')}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="ca" className="flex-1 flex flex-col min-h-0 space-y-6 mt-6 data-[state=inactive]:hidden">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <Card className="lg:col-span-2 p-6 flex flex-wrap items-center gap-4">
              <div className="flex items-center gap-2 flex-1 min-w-[200px]">
                <Calendar className="h-4 w-4 text-muted-foreground shrink-0" />
                <Input type="date" value={dateRange.debut} onChange={(e) => setDateRange({ ...dateRange, debut: e.target.value })} className="h-9" />
              </div>
              <span className="text-muted-foreground font-medium text-sm">{t('divers.to_date')}</span>
              <div className="flex items-center gap-2 flex-1 min-w-[200px]">
                <Calendar className="h-4 w-4 text-muted-foreground shrink-0" />
                <Input type="date" value={dateRange.fin} onChange={(e) => setDateRange({ ...dateRange, fin: e.target.value })} className="h-9" />
              </div>
              <Button onClick={handleFilter} variant="outline" className="gap-2 ml-auto border-emerald-600 text-emerald-700 hover:bg-emerald-50 hover:text-emerald-800">
                <Filter className="h-4 w-4" />
                {t('divers.filter')}
              </Button>
            </Card>
            <Card className="bg-emerald-600 text-white border-emerald-600 p-6 flex flex-col justify-center">
              <p className="text-emerald-100 text-xs font-semibold uppercase tracking-wider">{t('divers.revenue')}</p>
              <h2 className="text-3xl font-bold mt-1">{totalCA.toLocaleString()} {t('divers.currency')}</h2>
              <div className="mt-3 flex items-center text-emerald-100 text-xs">
                <CalendarDays className="h-3 w-3 mr-1" />
                {format(new Date(dateRange.debut), 'dd/MM/yy')} ÔåÆ {format(new Date(dateRange.fin), 'dd/MM/yy')}
              </div>
            </Card>
          </div>

          <Card className="flex-1 flex flex-col min-h-0 overflow-hidden p-0">
            <div className="px-6 py-4 border-b flex justify-between items-center bg-muted/30">
              <h3 className="font-semibold flex items-center gap-2 text-sm">
                {viewMode === 'daily' ? (
                  <>
                    <CalendarDays className="h-4 w-4 text-emerald-600" />
                    {t('divers.daily_sales_title')}
                  </>
                ) : (
                  <>
                    <ClipboardList className="h-4 w-4 text-emerald-600" />
                    {t('divers.detail_of')} {selectedDate ? format(parseISO(selectedDate), 'dd/MM/yyyy', { locale: fr }) : ''}
                  </>
                )}
              </h3>
              {viewMode === 'detail' && (
                <Button variant="outline" size="sm" onClick={handleBackToDaily} className="gap-2">
                  <ArrowLeft className="h-4 w-4" /> {t('divers.back_to_days')}
                </Button>
              )}
            </div>
            <div className="flex-1 overflow-auto">
              {viewMode === 'daily' ? (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>{t('divers.table.date')}</TableHead>
                      <TableHead className="text-right">{t('divers.daily_products')}</TableHead>
                      <TableHead className="text-right">{t('divers.daily_qty')}</TableHead>
                      <TableHead className="text-right">{t('divers.daily_invoices')}</TableHead>
                      <TableHead className="text-right">{t('divers.daily_total_ca')}</TableHead>
                      <TableHead className="text-center">{t('divers.actions')}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {dailyLoading ? (
                      Array.from({ length: 5 }).map((_, i) => (
                        <TableRow key={i}>
                          <TableCell colSpan={6}><Skeleton className="h-4 w-full" /></TableCell>
                        </TableRow>
                      ))
                    ) : dailyVentes.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={6} className="text-center text-muted-foreground py-12">{t('divers.no_sales_found')}</TableCell>
                      </TableRow>
                    ) : (
                      dailyVentes.map((day) => (
                        <TableRow
                          key={day.date}
                          className="cursor-pointer hover:bg-emerald-50/50 transition-colors"
                          onClick={() => handleViewDetail(day.date)}
                        >
                          <TableCell className="font-medium">
                            {format(parseISO(day.date), 'EEEE dd/MM/yyyy', { locale: fr })}
                          </TableCell>
                          <TableCell className="text-right">{day.nb_produits}</TableCell>
                          <TableCell className="text-right">{day.total_quantity}</TableCell>
                          <TableCell className="text-right">{day.nb_factures}</TableCell>
                          <TableCell className="text-right font-bold text-emerald-600">{day.total_ca.toLocaleString()} {t('divers.currency')}</TableCell>
                          <TableCell className="text-center">
