                <Button variant={valorisation === 'VENTE' ? 'primary' : 'outline'} size="sm" onClick={() => setValorisation('VENTE')}>
                  {t('divers.selling_price')}
                </Button>
              </div>
            </div>
          </Card>

          {stockLoading ? (
            <Card className="p-12 text-center">
              <Skeleton className="h-8 w-8 rounded-full mx-auto" />
              <p className="mt-4 text-muted-foreground">{t('divers.loading_valuation')}</p>
            </Card>
          ) : stockData ? (
            <>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <Card className="bg-emerald-600 text-white border-emerald-600 p-6">
                  <p className="text-emerald-100 text-xs font-semibold uppercase tracking-wider">{t('divers.total_value_ttc')}</p>
                  <h2 className="text-3xl font-bold mt-1">{stockData.total_ttc.toLocaleString()} {t('divers.currency')}</h2>
                  <p className="mt-2 text-emerald-100 text-xs">{stockData.type_valorisation === 'PMP' ? t('divers.purchase_cost') : t('divers.selling_price')}</p>
                </Card>
                <Card className="p-6">
                  <p className="text-muted-foreground text-xs font-semibold uppercase tracking-wider">{t('divers.value_ht')}</p>
                  <h2 className="text-2xl font-bold mt-1">{stockData.total_ht.toLocaleString()} {t('divers.currency')}</h2>
                </Card>
                <Card className="p-6">
                  <p className="text-muted-foreground text-xs font-semibold uppercase tracking-wider">{t('divers.total_vat')}</p>
                  <h2 className="text-2xl font-bold mt-1">{stockData.total_tva.toLocaleString()} {t('divers.currency')}</h2>
                </Card>
              </div>

              <Card className="overflow-hidden p-0">
                <div className="px-6 py-4 border-b bg-muted/30">
                  <h3 className="font-semibold flex items-center gap-2 text-sm">
                    <ClipboardList className="h-4 w-4 text-emerald-600" />
                    {t('divers.vat_breakdown')}
                  </h3>
                </div>
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>{t('divers.table.vat_rate')}</TableHead>
                        <TableHead className="text-right">{t('divers.table.base_ht')}</TableHead>
                        <TableHead className="text-right">{t('divers.table.vat_amount')}</TableHead>
                        <TableHead className="text-right">{t('divers.table.total_ttc')}</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {stockData.tva_breakdown.map((item) => (
                        <TableRow key={item.rate}>
                          <TableCell className="font-medium">{item.rate}%</TableCell>
                          <TableCell className="text-right text-muted-foreground">{item.ht.toLocaleString()} {t('divers.currency')}</TableCell>
                          <TableCell className="text-right text-muted-foreground">{item.tva.toLocaleString()} {t('divers.currency')}</TableCell>
                          <TableCell className="text-right font-bold text-emerald-600">{item.ttc.toLocaleString()} {t('divers.currency')}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </Card>

              <Card className="overflow-hidden p-0">
                <div className="px-6 py-4 border-b bg-muted/30">
                  <h3 className="font-semibold flex items-center gap-2 text-sm">
                    <Package className="h-4 w-4 text-emerald-600" />
                    {t('divers.section_breakdown')}
                  </h3>
                </div>
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>{t('divers.table.section')}</TableHead>
                        <TableHead className="text-right">{t('divers.table.base_ht')}</TableHead>
                        <TableHead className="text-right">{t('divers.table.vat_amount')}</TableHead>
                        <TableHead className="text-right">{t('divers.table.total_ttc')}</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {stockData.rayon_breakdown.map((item) => (
                        <TableRow key={item.name}>
                          <TableCell className="font-medium">{item.name}</TableCell>
                          <TableCell className="text-right text-muted-foreground">{item.ht.toLocaleString()} {t('divers.currency')}</TableCell>
                          <TableCell className="text-right text-muted-foreground">{item.tva.toLocaleString()} {t('divers.currency')}</TableCell>
                          <TableCell className="text-right font-bold text-emerald-600">{item.ttc.toLocaleString()} {t('divers.currency')}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </Card>
            </>
          ) : (
            <Card className="p-12 text-center">
              <Warehouse className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
              <p className="text-muted-foreground">{t('divers.no_stock_data')}</p>
            </Card>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default GestionDivers;

import React from 'react'
import { useTranslation } from 'react-i18next'
import { formatCurrency, normalizeNumberInput } from '../../utils/formatters'
import type { LigneFacture, ProduitModel, StockLot, LotAllocation } from '../../types'
import { useAuth } from '../../context/AuthContext'
import { toast } from 'react-hot-toast'
import { Button } from '../shadcn/button'
import { Badge } from '../shadcn/badge'
import { Input } from '../shadcn/input'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '../ui/Table'
import { Tag, X, Trash2, ShoppingCart } from 'lucide-react'

function getFEFOPreview(lots: StockLot[] | undefined, quantity: number): { lot: string; qty: number; expiration?: string }[] {
  if (!lots || lots.length === 0 || quantity <= 0) return []
  const sorted = [...lots]
    .filter(l => (l.quantity_remaining || 0) > 0)
    .sort((a, b) => {
      const expA = a.date_expiration ? new Date(a.date_expiration).getTime() : Infinity
      const expB = b.date_expiration ? new Date(b.date_expiration).getTime() : Infinity
      if (expA !== expB) return expA - expB
      const recA = a.date_reception ? new Date(a.date_reception).getTime() : 0
      const recB = b.date_reception ? new Date(b.date_reception).getTime() : 0
      return recA - recB
    })
  let remaining = quantity
  const preview: { lot: string; qty: number; expiration?: string }[] = []
  for (const lot of sorted) {
    if (remaining <= 0) break
    const available = lot.quantity_remaining || 0
    const take = Math.min(available, remaining)
    if (take > 0) {
      preview.push({
        lot: lot.lot || `Lot ${lot.id}`,
        qty: take,
        expiration: lot.date_expiration || undefined
      })
      remaining -= take
    }
  }
  return preview
}

interface CartTableProps {
  lignesFacture: LigneFacture[]
  updateQuantite: (produitId: number, quantite: number) => void
  updatePrix: (produitId: number, prix: string) => void
  updateRemiseProduit: (produitId: number, remise: string) => void
  updateTreatmentDuration?: (produitId: number, duration: number) => void
  removeLigne: (produitId: number) => void
  onOpenLotModal: (product: ProduitModel, currentLotId: string | null, quantity: number, currentAllocations: LotAllocation[] | null) => void
  quantityInputsRef: React.MutableRefObject<Map<number, HTMLInputElement>>
  onReturnFocus: () => void
  selectedIndex?: number
  onSelectLine?: (index: number) => void
  refreshTrigger?: number
  isSidebarStyle?: boolean
}

interface CartRowProps {
  ligne: LigneFacture
  index: number
  selectedIndex: number
  onSelectLine?: (index: number) => void
  updateQuantite: (produitId: number, quantite: number) => void
  updatePrix: (produitId: number, prix: string) => void
  updateRemiseProduit: (produitId: number, remise: string) => void
  updateTreatmentDuration?: (produitId: number, duration: number) => void
  removeLigne: (produitId: number) => void
  onOpenLotModal: (product: ProduitModel, currentLotId: string | null, quantity: number, currentAllocations: LotAllocation[] | null) => void
  quantityInputsRef: React.MutableRefObject<Map<number, HTMLInputElement>>
  onReturnFocus: () => void
  canModifyPrice: boolean
  maxDiscount: number
  t: (key: string, options?: unknown) => string
  refreshTrigger?: number
  isSidebarStyle?: boolean
}

const CartRow = React.memo(({
  ligne,
  index,
  selectedIndex,
  onSelectLine,
  updateQuantite,
  updatePrix,
  updateRemiseProduit,
  updateTreatmentDuration,
  removeLigne,
  onOpenLotModal,
  quantityInputsRef,
  onReturnFocus,
  canModifyPrice,
  maxDiscount,
  t,
  refreshTrigger,
  isSidebarStyle
}: CartRowProps) => {
  const [localQty, setLocalQty] = React.useState(() => ligne.quantite.toString())
  const [localPrice, setLocalPrice] = React.useState(() => ligne.prix_unitaire)
  const [localRemise, setLocalRemise] = React.useState(() => ligne.remise_produit)

  // Sync local states when external state changes (shortcuts, barcode, etc.)
  React.useEffect(() => {
    setLocalQty(ligne.quantite.toString())
    setLocalPrice(ligne.prix_unitaire)
    setLocalRemise(ligne.remise_produit)
  }, [ligne.quantite, ligne.prix_unitaire, ligne.remise_produit, refreshTrigger])

  const handleQtyChange = (value: string) => {
    // Regex: allow only digits and a single minus sign at the very beginning
    const filteredValue = value.replace(/[^0-9-]/g, '').replace(/(?!^)-/g, '')
    setLocalQty(filteredValue)
    // Ne PAS mettre ├á jour le parent ici ÔÇö attendre la confirmation (Entr├®e / blur)
  }

  const handleQtySubmit = () => {
    const numValue = normalizeNumberInput(localQty)
    if (!isNaN(numValue) && numValue !== 0) {
      updateQuantite(ligne.produit.id, numValue)
    } else if (localQty === '' || localQty === '0') {
      // Si l'utilisateur efface ou met 0, remettre ├á 1
      setLocalQty(ligne.quantite.toString())
    }
  }

  const handlePriceSubmit = () => {
    if (localPrice !== ligne.prix_unitaire) {
      updatePrix(ligne.produit.id, localPrice)
    }
  }

  const handleRemiseSubmit = () => {
    const numValue = normalizeNumberInput(localRemise)
    if (!isNaN(numValue) && numValue > maxDiscount) {
      toast.error(t('facturation:messages.discount_limit_error', { rate: maxDiscount }))
      setLocalRemise(String(maxDiscount))
      updateRemiseProduit(ligne.produit.id, String(maxDiscount))
    } else if (localRemise !== ligne.remise_produit) {
      updateRemiseProduit(ligne.produit.id, localRemise || '0')
    }
  }

  const isReturn = normalizeNumberInput(ligne.quantite) < 0

  const fefoPreview = React.useMemo(() => {
    if (ligne.lotId) return []
    return getFEFOPreview(ligne.produit.stock_lots, Math.abs(ligne.quantite))
  }, [ligne.lotId, ligne.produit.stock_lots, ligne.quantite])

  const lotDisplayText = React.useMemo(() => {
    const manualAllocs = ligne.lotAllocations?.filter(a => a.quantity > 0)
    if (manualAllocs && manualAllocs.length > 0) {
      if (manualAllocs.length === 1) {
        const a = manualAllocs[0]
        const parts = [a.lotText || `Lot ${a.lotId}`]
        if (a.lotExpiration) {
          const d = new Date(a.lotExpiration)
          parts.push(`${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getFullYear()).slice(-2)}`)
        }
        return parts.join(' ÔÇó ')
      }
      return `${manualAllocs.length} lots ÔÇó ${manualAllocs.map(a => `${a.lotText || a.lotId}├ù${a.quantity}`).join(', ')}`
    }
    if (!ligne.lotId) {
      if (fefoPreview.length === 0) return t('facturation:cart_extra.auto_fefo')
      if (fefoPreview.length === 1) {
        const p = fefoPreview[0]
        const parts = [p.lot]
        if (p.expiration) {
          const d = new Date(p.expiration)
          parts.push(`${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getFullYear()).slice(-2)}`)
        }
        return `${t('facturation:cart_extra.auto_prefix')} ÔÇó ${parts.join(' ÔÇó ')}`
      }
      const totalLots = fefoPreview.length
      const firstLot = fefoPreview[0]
      return `${t('facturation:cart_extra.auto_prefix')} ÔÇó ${firstLot.lot} +${totalLots - 1}`
    }
    const parts = [ligne.lotText || `Lot ${ligne.lotId}`]
    if (ligne.lotExpiration) {
      const d = new Date(ligne.lotExpiration)
      parts.push(`${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getFullYear()).slice(-2)}`)
    }
    if (ligne.lotSellingPrice) {
      parts.push(`${formatCurrency(Number(ligne.lotSellingPrice))}`)
    }
    return parts.join(' ÔÇó ')
  }, [ligne.lotId, ligne.lotText, ligne.lotExpiration, ligne.lotSellingPrice, ligne.lotAllocations, fefoPreview])

  const lotTooltip = React.useMemo(() => {
    const manualAllocs = ligne.lotAllocations?.filter(a => a.quantity > 0)
    if (manualAllocs && manualAllocs.length > 0) {
      return [
        t('facturation:cart_extra.manual_allocation'),
        ...manualAllocs.map(a => {
          const exp = a.lotExpiration ? new Date(a.lotExpiration).toLocaleDateString('fr-FR') : 'sans date'
          return `${a.lotText || a.lotId} ├ù ${a.quantity} (exp ${exp})`
        })
      ].join('\n')
    }
    if (!ligne.lotId) {
      if (fefoPreview.length === 0) return t('facturation:cart.product_status.auto_lot')
      return [
        t('facturation:cart_extra.fefo_automatic'),
        ...fefoPreview.map(p => {
          const exp = p.expiration ? new Date(p.expiration).toLocaleDateString('fr-FR') : 'sans date'
          return `${p.lot} ├ù ${p.qty} (exp ${exp})`
        })
      ].join('\n')
    }
    return [
      ligne.lotText ? `${t('facturation:cart.headers.lot')}: ${ligne.lotText}` : '',
      ligne.lotExpiration ? `${t('facturation:cart_extra.peremption')} ${new Date(ligne.lotExpiration).toLocaleDateString('fr-FR')}` : '',
      ligne.lotSellingPrice ? `${t('facturation:cart_extra.prix_lot')} ${formatCurrency(Number(ligne.lotSellingPrice))}` : ''
    ].filter(Boolean).join(' | ')
  }, [ligne, t, fefoPreview])

  if (isSidebarStyle) {
    return (
      <div
        onClick={() => onSelectLine?.(index)}
        className={`group relative flex flex-col p-3 border-b border-slate-100 transition-all duration-200 cursor-pointer
          ${index === selectedIndex ? 'bg-emerald-50 border-l-4 border-l-emerald-500' : 'hover:bg-slate-50'}
          ${isReturn ? 'bg-red-50' : ''}`}
      >
        {/* Ligne Haut: Nom Produit + Total + Action */}
        <div className="flex justify-between items-start gap-2">
          <div className="flex-1 min-w-0">
             <div className="flex items-center gap-1.5">
               <h4 className={`text-sm font-semibold truncate leading-tight ${isReturn ? 'text-red-600' : 'text-slate-800'}`} title={ligne.produit.name}>
                 {ligne.produit.name}
               </h4>
               {ligne.isPromis && <Badge variant="secondary" className="text-[9px] h-4 px-1 bg-amber-100 text-amber-700 border-amber-200">{t('facturation:cart_extra.promis')}</Badge>}
             </div>
             {ligne.produit.stock !== undefined && (
                <div className={`text-[10px] leading-none mt-1 ${ligne.produit.stock <= 0 ? 'text-red-500 font-semibold' : 'text-slate-400'}`}>
                  {t('facturation:cart_extra.stock_label')} {ligne.produit.stock}
                </div>
             )}
          </div>

          <div className="flex items-start shrink-0 gap-2">
             <span className="text-sm font-bold text-slate-900 font-mono whitespace-nowrap">
                {formatCurrency(normalizeNumberInput(ligne.total_ligne))}
             </span>
             <Button
               variant="ghost"
               size="icon"
               onClick={(e) => { e.stopPropagation(); removeLigne(ligne.produit.id); }}
               className="size-7 text-slate-300 hover:text-red-500 hover:bg-red-50 lg:opacity-0 lg:group-hover:opacity-100 transition-all"
             >
               <X className="size-4" />
             </Button>
          </div>
        </div>

        {/* Ligne Bas: Block (Qt├® x Prix) + Bouton Lot */}
        <div className="flex items-center gap-2 mt-2">
           {/* Combo Input Qt├® + Prix Unitaire + Remise */}
           <div className="flex items-center bg-slate-100 border border-slate-200 rounded-lg focus-within:border-emerald-300 focus-within:ring-1 focus-within:ring-emerald-100 overflow-hidden transition-all">
             <input
               ref={(el) => {
                 if (el) quantityInputsRef.current.set(ligne.produit.id, el)
                 else quantityInputsRef.current.delete(ligne.produit.id)
               }}
               type="text"
               inputMode="numeric"
               value={localQty}
               onChange={(e) => handleQtyChange(e.target.value)}
               onBlur={handleQtySubmit}
               onKeyDown={(e) => {
                 if (e.key === 'Enter') {
                   e.preventDefault()
                   handleQtySubmit()
                   onReturnFocus()
                 }
               }}
               className="w-12 h-9 bg-transparent px-1 text-xs text-center font-semibold text-slate-700 focus:bg-white focus:outline-none"
             />
             <div className="flex items-center h-9 px-1.5 bg-slate-50 border-l border-slate-200 text-[10px] font-semibold text-slate-400">
                <span className="mr-1">├ù</span>
                <input
                   type="text"
                   inputMode="decimal"
                   value={localPrice}
                   onChange={(e) => setLocalPrice(e.target.value.replace(/[^0-9.]/g, ''))}
                   onBlur={handlePriceSubmit}
                   onKeyDown={(e) => {
                     if (e.key === 'Enter') {
                       e.preventDefault()
                       handlePriceSubmit()
                       onReturnFocus()
                     }
                   }}
                   disabled={!canModifyPrice}
                   className={`w-16 bg-transparent text-left font-semibold border-none focus:outline-none focus:text-slate-800 ${!canModifyPrice ? 'text-slate-400 cursor-not-allowed' : 'text-slate-600'}`}
                   title={!canModifyPrice ? t('facturation:messages.price_modification_forbidden') : t('facturation:cart.edit_price')}
                />
             </div>
             {/* Champ de Remise */}
             <div className="flex items-center h-9 px-1.5 bg-amber-50 border-l border-amber-200 text-[10px] w-14 focus-within:bg-amber-100">
                <span className="text-amber-500 font-bold mr-0.5">-</span>
                <input
                   type="text"
                   inputMode="decimal"
                   value={localRemise}
                   onChange={(e) => setLocalRemise(e.target.value.replace(/[^0-9.]/g, ''))}
                   onBlur={handleRemiseSubmit}
                   onKeyDown={(e) => {
                     if (e.key === 'Enter') {
                       e.preventDefault()
                       handleRemiseSubmit()
                       onReturnFocus()
                     }
                   }}
                   className="w-full bg-transparent text-left font-semibold text-amber-600 focus:text-amber-700 focus:outline-none placeholder-amber-300"
                   placeholder={t('facturation:cart_extra.rem_placeholder')}
                   title={t('facturation:cart.discount_amount')}
                />
             </div>
           </div>

           {/* Bouton Lot FEFO condens├® */}
           <Button
             variant="outline"
             size="sm"
             onClick={(e) => { e.stopPropagation(); onOpenLotModal(ligne.produit, ligne.lotId || null, ligne.quantite, ligne.lotAllocations || null); }}
             className={`h-9 px-2 text-[11px] font-semibold uppercase transition-colors shrink gap-1.5
               ${(ligne.lotId || ligne.lotAllocations?.length)
                 ? 'bg-emerald-50 text-emerald-600 border-emerald-200 hover:bg-emerald-100 hover:border-emerald-300'
                 : 'bg-slate-100 text-slate-400 border-slate-200 hover:bg-slate-200 hover:text-slate-600'}`}
             title={lotTooltip}
           >
             <Tag className="size-3 shrink-0" />
             <span className="truncate max-w-[320px] tracking-wide">{lotDisplayText}</span>
           </Button>
        </div>
      </div>
    )

  }

  return (
    <TableRow
      className={`hover:bg-slate-50/50 group border-b border-slate-100 last:border-0 cursor-pointer transition-colors duration-150
        ${index === selectedIndex ? '!bg-emerald-50/70 border-l-4 border-l-emerald-500 shadow-sm' : ''}
        ${isReturn ? 'bg-red-50 text-red-600 font-semibold' : ''}`}
      ref={index === selectedIndex ? (el) => el?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }) : null}
      onClick={() => onSelectLine?.(index)}
    >
      <TableCell className="pl-2 md:pl-4 py-2">
        <div className={`font-medium ${ligne.produit.is_deleted ? 'italic' : ''}`}>
          <div className="flex items-center gap-2">
            <span className="truncate text-slate-800">{ligne.produit.name}</span>
            {ligne.isPromis && (
              <Badge variant="secondary" className="text-[10px] h-5 bg-amber-100 text-amber-700 border-amber-200 animate-pulse shrink-0">
                {t('facturation:cart_extra.promis')}
              </Badge>
            )}
          </div>
          {ligne.produit.is_deleted && <span className="text-xs ml-2 opacity-75 text-red-500">{t('facturation:cart.product_status.deleted')}</span>}
          {ligne.produit.is_chronic && (
            <div className="flex items-center gap-2 mt-1">
              <Badge variant="default" className="text-[10px] h-5 bg-emerald-100 text-emerald-700 border-emerald-200 gap-1">
               <span>{t('facturation:cart.product_status.chronic')}</span>
              </Badge>
              <div className="flex items-center gap-1 border border-emerald-200 rounded px-1.5 bg-emerald-50">
                <span className="text-[10px] text-emerald-600">{t('facturation:cart.product_status.treatment')}</span>
                <input
                   type="number"
                   className="w-8 bg-transparent text-[10px] font-semibold text-emerald-700 outline-none"
                    value={ligne.treatment_duration_days || ''}
                    onChange={(e) => updateTreatmentDuration?.(ligne.produit.id, normalizeNumberInput(e.target.value) || 0)}
                    min={1}
                />
                <span className="text-[10px] text-emerald-600">{t('facturation:cart.product_status.days_unit')}</span>
              </div>
            </div>
          )}
        </div>
      </TableCell>
      <TableCell className="text-right py-1">
        <Input
          ref={(el) => {
            if (el) quantityInputsRef.current.set(ligne.produit.id, el)
            else quantityInputsRef.current.delete(ligne.produit.id)
          }}
          type="text"
          value={localQty}
          onChange={(e) => handleQtyChange(e.target.value)}
          onBlur={handleQtySubmit}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              e.preventDefault()
              handleQtySubmit()
              onReturnFocus()
            }
          }}
          className="w-full text-right font-medium text-sm h-8 min-h-[32px] sm:min-h-0"
        />
      </TableCell>
      <TableCell className="text-right py-1">
        <Input
          type="text"
          value={localPrice}
          onChange={(e) => setLocalPrice(e.target.value.replace(/[^0-9.]/g, ''))}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              e.preventDefault()
              handlePriceSubmit()
              onReturnFocus()
            }
          }}
          className={`w-full text-right font-medium text-sm h-8 min-h-[32px] sm:min-h-0 ${!canModifyPrice ? 'text-slate-400 cursor-not-allowed' : 'text-slate-700'}`}
          disabled={!canModifyPrice}
          title={!canModifyPrice ? t('facturation:messages.price_modification_forbidden') : ""}
        />
      </TableCell>
      <TableCell className="text-right py-1 hidden lg:table-cell">
        <Input
          type="text"
          value={localRemise}
          onChange={(e) => setLocalRemise(e.target.value.replace(/[^0-9.]/g, ''))}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              e.preventDefault()
              handleRemiseSubmit()
              onReturnFocus()
            }
          }}
          className="w-full text-right font-medium text-sm h-8 min-h-[32px] sm:min-h-0 text-amber-600 placeholder-amber-300"
          placeholder="%"
        />
      </TableCell>
      <TableCell className="text-center py-2 hidden md:table-cell">
        <div className={`font-mono font-semibold ${
          (ligne.produit.stock ?? 0) <= 0 ? 'text-red-500' :
          (ligne.produit.stock ?? 0) < 5 ? 'text-amber-500' : 'text-emerald-600'
        }`}>
          {ligne.produit.stock ?? 0}
        </div>
      </TableCell>
      <TableCell className="text-center py-2 hidden md:table-cell">
        <Button
          variant={(ligne.lotId || ligne.lotAllocations?.length) ? 'default' : 'outline'}
          size="sm"
          onClick={() => onOpenLotModal(ligne.produit, ligne.lotId || null, ligne.quantite, ligne.lotAllocations || null)}
          className={`w-full max-w-[260px] truncate text-xs h-7 ${(ligne.lotId || ligne.lotAllocations?.length) ? 'bg-emerald-600 hover:bg-emerald-700' : 'border-slate-200 text-slate-500 hover:bg-slate-50'}`}
          title={lotTooltip}
        >
          {lotDisplayText}
        </Button>
      </TableCell>
      <TableCell className="text-right font-semibold text-slate-800 pr-2 md:pr-4 py-2">
        {formatCurrency(normalizeNumberInput(ligne.total_ligne))}
      </TableCell>
      <TableCell className="text-center py-2">
        <Button
          variant="ghost"
          size="icon"
          onClick={() => removeLigne(ligne.produit.id)}
          className="size-7 text-slate-300 hover:text-red-500 hover:bg-red-50 sm:opacity-0 group-hover:opacity-100 transition-opacity"
        >
          <span className="sr-only">{t('facturation:cart.actions.remove')}</span>
          <Trash2 className="size-3.5" />
        </Button>
      </TableCell>
    </TableRow>
  )
})

const CartTable = React.memo(({
  lignesFacture,
  updateQuantite,
  updatePrix,
  updateRemiseProduit,
  updateTreatmentDuration,
  removeLigne,
  onOpenLotModal,
  quantityInputsRef,
  onReturnFocus,
  selectedIndex = -1,
  onSelectLine,
  refreshTrigger,
  isSidebarStyle
}: CartTableProps) => {
  const { user } = useAuth()
  const { t } = useTranslation(['facturation', 'common'])

  // Permission Checks
  const canModifyPrice = user?.is_superuser || user?.profile?.can_modify_price
  const maxDiscount = user?.is_superuser ? 100 : (normalizeNumberInput(user?.profile?.max_discount_rate || 0))

  if (lignesFacture.length === 0) {
    return (
      <div className="h-full flex flex-col items-center justify-center gap-4 min-h-[200px] text-slate-300">
        <ShoppingCart className="size-16" />
        <p className="font-light text-slate-400">{t('facturation:cart.empty')}</p>
      </div>
    )
  }

  if (isSidebarStyle) {
    return (
      <div className="flex flex-col">
        {lignesFacture.map((ligne, index) => (
          <CartRow
            key={ligne.produit.id}
            ligne={ligne}
            index={index}
            selectedIndex={selectedIndex}
            onSelectLine={onSelectLine}
            updateQuantite={updateQuantite}
            updatePrix={updatePrix}
            updateRemiseProduit={updateRemiseProduit}
            updateTreatmentDuration={updateTreatmentDuration}
            removeLigne={removeLigne}
            onOpenLotModal={onOpenLotModal}
            quantityInputsRef={quantityInputsRef}
            onReturnFocus={onReturnFocus}
            canModifyPrice={!!canModifyPrice}
            maxDiscount={maxDiscount}
            t={t}
            refreshTrigger={refreshTrigger}
            isSidebarStyle={true}
          />
        ))}
      </div>
    )
  }

  return (
    <Table className="w-full">
      <TableHeader className="sticky top-0 z-30 bg-slate-100">
        <TableRow className="bg-slate-100 uppercase tracking-wider text-slate-500 font-semibold border-b border-slate-200 text-xs hover:bg-slate-100">
          <TableHead className="bg-slate-100 pl-2 md:pl-4 min-w-[120px] py-2">{t('facturation:cart.headers.product')}</TableHead>
          <TableHead className="bg-slate-100 text-right w-12 sm:w-20 py-2">{t('facturation:cart.headers.qty')}</TableHead>
          <TableHead className="bg-slate-100 text-right w-16 sm:w-24 py-2">{t('facturation:cart.headers.price')}</TableHead>
          <TableHead className="bg-slate-100 text-right w-14 md:w-16 hidden lg:table-cell py-2">{t('facturation:cart.headers.discount')}</TableHead>
          <TableHead className="bg-slate-100 text-center w-24 hidden md:table-cell py-2">{t('facturation:cart.headers.stock')}</TableHead>
          <TableHead className="bg-slate-100 text-center w-36 sm:w-64 hidden md:table-cell py-2">{t('facturation:cart.headers.lot')}</TableHead>
          <TableHead className="bg-slate-100 text-right w-18 sm:w-28 pr-2 md:pr-4 py-2">{t('facturation:cart.headers.total')}</TableHead>
          <TableHead className="bg-slate-100 w-8 py-2"></TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {lignesFacture.map((ligne, index) => (
          <CartRow
            key={ligne.produit.id}
            ligne={ligne}
            index={index}
            selectedIndex={selectedIndex}
            onSelectLine={onSelectLine}
            updateQuantite={updateQuantite}
            updatePrix={updatePrix}
            updateRemiseProduit={updateRemiseProduit}
            updateTreatmentDuration={updateTreatmentDuration}
            removeLigne={removeLigne}
            onOpenLotModal={onOpenLotModal}
            quantityInputsRef={quantityInputsRef}
            onReturnFocus={onReturnFocus}
            canModifyPrice={!!canModifyPrice}
            maxDiscount={maxDiscount}
            t={t}
            refreshTrigger={refreshTrigger}
          />
        ))}
      </TableBody>
    </Table>
  )
})

export default CartTable

import React, { useState, useRef, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Camera, Upload, Trash2, Search, Check, RefreshCw, Loader2, AlertCircle } from 'lucide-react';
import PremiumModal from '../common/PremiumModal';
import { prescriptionOcrService } from '../../services/prescriptionOcrService';
import type { ScannedPrescription } from '../../services/prescriptionOcrService';
import fuzzysort from 'fuzzysort';
import api from '../../services/api';
import { toast } from 'react-hot-toast';
import type { ProduitModel } from '../../types';

interface PrescriptionScannerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAddProducts: (products: ProduitModel[]) => void;
  onExtractionDone: (data: Partial<ScannedPrescription> & { imageFile?: File }) => void;
}

interface MatchResult {
  ocrLine: string;
  matchedProduct: ProduitModel | null;
  score: number;
  suggestions: ProduitModel[];
}

const PrescriptionScannerModal: React.FC<PrescriptionScannerModalProps> = ({ 
  isOpen, 
  onClose, 
  onAddProducts,
  onExtractionDone 
}) => {
  const { t } = useTranslation(['facturation', 'common']);
  const [preview, setPreview] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [matchResults, setMatchResults] = useState<MatchResult[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [extractionData, setExtractionData] = useState<ScannedPrescription | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageRef = useRef<File | null>(null);
  const productsRef = useRef<ProduitModel[]>([]);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [showCamera, setShowCamera] = useState(false);

  // Load products for fuzzy matching when modal opens
  useEffect(() => {
    if (isOpen && productsRef.current.length === 0) {
      loadProducts();
    }
  }, [isOpen]);

  const loadProducts = async () => {
    setLoadingProducts(true);
    try {
      const response = await api.get('produits/', { params: { page_size: 10000 } });
      const results = Array.isArray(response.data) ? response.data : response.data.results;
      productsRef.current = results || [];
    } catch (error) {
      console.error('Failed to load products for OCR matching', error);
      toast.error(t('facturation:prescription_scanner.error_load_products'));
    } finally {
      setLoadingProducts(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      imageRef.current = file;
      setPreview(URL.createObjectURL(file));
      setMatchResults([]);
      setShowCamera(false);
    }
  };

  const startCamera = async () => {
    setShowCamera(true);
    setPreview(null);
    imageRef.current = null;
    try {
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      }
    } catch {
      toast.error(t('facturation:prescription_scanner.error_camera'));
      setShowCamera(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
    }
    setShowCamera(false);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        canvas.toBlob((blob) => {
          if (blob) {
            const file = new File([blob], 'capture.jpg', { type: 'image/jpeg' });
            imageRef.current = file;
            setPreview(URL.createObjectURL(file));
            stopCamera();
          }
        }, 'image/jpeg', 0.9);
      }
    }
  };

  const processOcr = async () => {
    const image = imageRef.current;
    if (!image) return;

    setIsProcessing(true);
    setProgress(0);
    try {
      const result = await prescriptionOcrService.scanImage(image);
      const extracted = prescriptionOcrService.parseOcrResult(result);
      setExtractionData(extracted);

      // Fuzzy match products using fuzzysort (optimized)
      const matches: MatchResult[] = extracted.potential_products.map(ocrLine => {
        const cleanQuery = ocrLine
          .replace(/\b(boite|boites|comprim├®|comprim├®s|cpr|gelules|sirop|ampoules|matin|midi|soir|posologie|ordonnance|qsp|jours|mois|de|la|le|les|des|un|une|et|a|au|dr|docteur)\b/gi, '')
          .replace(/[^\w\s]/gi, ' ')
          .replace(/\s+/g, ' ')
          .trim();

        const query = cleanQuery.length > 2 ? cleanQuery : ocrLine;

        // Utiliser fuzzysort pour un matching rapide et pr├®cis
        const results = fuzzysort.go(query, productsRef.current, {
          key: 'name',
          limit: 3,
          threshold: -10000, // Ajuster si besoin pour ├¬tre plus ou moins permissif
        });

        const topResults = results.map(r => r.obj);

        return {
          ocrLine,
          matchedProduct: topResults[0] || null,
          score: results[0] ? results[0].score : 0,
          suggestions: topResults,
        };
      });

      // Garder les lignes qui ont au moins une suggestion (laisser l'utilisateur juger)
      setMatchResults(matches.filter(m => m.suggestions.length > 0));
      
      if (matches.length === 0) {
        toast.error(t('facturation:prescription_scanner.error_no_products'));
      }
    } catch (err: unknown) {
      console.error('OCR Error:', err);
      const errorMessage = err && typeof err === 'object' && 'message' in err ? err.message : t('facturation:prescription_scanner.error_console');
      toast.error(t('facturation:prescription_scanner.error_ocr', { error: errorMessage }));
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSelectProduct = (index: number, product: ProduitModel) => {
    const updated = [...matchResults];
    updated[index].matchedProduct = product;
    setMatchResults(updated);
  };

  const validateScan = () => {
    const selectedProducts = matchResults
      .map(m => m.matchedProduct)
      .filter((p): p is ProduitModel => p !== null);

    onAddProducts(selectedProducts);
    
    if (extractionData) {
        onExtractionDone({
            ...extractionData,
            imageFile: imageRef.current || undefined
        });
    }
    
    onClose();
    toast.success(t('facturation:prescription_scanner.products_added', { count: selectedProducts.length }));
  };

  const reset = () => {
    imageRef.current = null;
    setPreview(null);
    setMatchResults([]);
    setExtractionData(null);
    stopCamera();
  };

  return (
    <PremiumModal
      isOpen={isOpen}
      onClose={onClose}
      title={t('facturation:prescription_scanner.title')}
      subtitle={t('facturation:prescription_scanner.subtitle')}
      icon={<Camera className="size-5 text-emerald-600" />}
      maxWidth="max-w-4xl"
    >
      <div className="flex flex-col h-[70vh]">

        {/* Main Content Area */}
        <div className="flex-1 overflow-y-auto p-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full">

            {/* Left Column: Image Source */}
            <div className="flex flex-col gap-4">
              {!preview && !showCamera && (
                <div
                  className="flex-1 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center gap-4 bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer"
                  onClick={() => fileInputRef.current?.click()}
                >
                  <div className="p-4 bg-emerald-50 rounded-full text-emerald-600">
                    <Upload className="size-8" />
                  </div>
                  <div className="text-center">
                    <p className="font-bold text-slate-800">{t('facturation:prescription_scanner.drag_image')}</p>
                    <p className="text-sm text-slate-400">{t('facturation:prescription_scanner.click_browse')}</p>
                  </div>
                  <button
                    className="inline-flex items-center justify-center h-8 px-4 rounded-lg text-sm font-medium bg-emerald-600 text-white hover:bg-emerald-700 transition-colors"
                    onClick={(e) => { e.stopPropagation(); startCamera(); }}
                  >
                    <Camera className="size-4 mr-2" />
                    {t('facturation:prescription_scanner.use_camera')}
                  </button>
                </div>
              )}

              {showCamera && (
                <div className="relative flex-1 bg-gray-950 rounded-2xl overflow-hidden shadow-xl">
                  <video
                    ref={videoRef}
                    autoPlay
                    playsInline
                    className="size-full object-cover"
                  />
                  <div className="absolute bottom-6 left-0 right-0 flex justify-center gap-3">
                    <button className="inline-flex items-center justify-center size-14 rounded-full bg-emerald-600 text-white shadow-lg hover:bg-emerald-700 transition-colors" onClick={capturePhoto}>
                      <div className="size-4 rounded-full border-2 border-white" />
                    </button>
                    <button className="inline-flex items-center justify-center size-12 rounded-full bg-white/10 backdrop-blur-md text-white hover:bg-white/20 transition-colors" onClick={stopCamera}>
                      <Trash2 className="size-5" />
                    </button>
                  </div>
                </div>
              )}

              {preview && (
                <div className="relative flex-1 rounded-2xl overflow-hidden group shadow-lg bg-slate-200">
                  <img src={preview} alt="Scan preview" className="size-full object-contain" />
                  <div className="absolute top-4 right-4 flex gap-2">
                    <button className="inline-flex items-center justify-center size-9 rounded-full bg-red-600 text-white shadow-lg hover:bg-red-700 transition-colors" onClick={reset}>
                      <Trash2 className="size-4" />
                    </button>
                  </div>
                  {!isProcessing && matchResults.length === 0 && (
                    <div className="absolute bottom-6 left-0 right-0 flex justify-center">
                      <button
                        className="inline-flex items-center justify-center h-10 px-8 rounded-xl text-sm font-semibold bg-emerald-600 text-white shadow-lg hover:bg-emerald-700 transition-colors"
                        onClick={processOcr}
                        disabled={loadingProducts}
                      >
                        {loadingProducts ? <Loader2 className="size-4 animate-spin mr-2" /> : <RefreshCw className="size-4 mr-2" />}
                        {t('facturation:prescription_scanner.launch_ocr')}
                      </button>
                    </div>
                  )}
                </div>
              )}

              {isProcessing && (
                <div className="mt-4 space-y-2">
                  <div className="flex justify-between text-xs font-bold uppercase tracking-wider text-slate-400">
                    <span>{t('facturation:prescription_scanner.ocr_processing')}</span>
                    <span>{Math.round(progress * 100)}%</span>
                  </div>
                  <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                    <div className="h-full bg-emerald-600 rounded-full transition-all" style={{ width: `${progress * 100}%` }}></div>
                  </div>
                </div>
              )}
            </div>

            {/* Right Column: OCR Results */}
            <div className="flex flex-col bg-slate-50 rounded-2xl border border-slate-100 overflow-hidden">
                <div className="p-4 border-b border-slate-100 bg-slate-100/80 backdrop-blur-sm flex justify-between items-center">
                    <h3 className="font-bold flex items-center gap-2 text-slate-800">
                        <Search className="size-4 text-emerald-600" />
                        {t('facturation:prescription_scanner.medicines_identified')}
                    </h3>
                    <span className="inline-flex items-center px-2.5 h-6 text-xs rounded-full bg-slate-200 text-slate-700 font-medium">{matchResults.filter(r => r.matchedProduct).length} {t('facturation:prescription_scanner.recognized')}</span>
                </div>

                <div className="flex-1 overflow-y-auto p-4 space-y-3">
                  {matchResults.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center p-8 text-center text-slate-400 italic">
                      <AlertCircle className="size-12 mb-4 stroke-1" />
                      <p>{t('facturation:prescription_scanner.no_results_placeholder')}</p>
                    </div>
                  ) : (
                    matchResults.map((result, idx) => (
                      <div key={result.ocrLine} className={`p-3 rounded-xl border transition-all ${result.matchedProduct ? 'bg-emerald-50/50 border-emerald-200' : 'bg-white border-slate-100'}`}>
                        <div className="flex justify-between items-start mb-2">
                          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{t('facturation:prescription_scanner.ocr_line_label')}</span>
                          {result.matchedProduct && <Check className="size-4 text-emerald-600" />}
                        </div>
                        <p className="font-medium text-sm mb-2 text-slate-800">{result.ocrLine}</p>

                        <div className="space-y-1">
                          {result.suggestions.map((product) => (
                            <button
                                key={product.id}
                                className={`w-full text-left p-2 rounded-lg text-xs flex justify-between items-center transition-colors ${result.matchedProduct?.id === product.id ? 'bg-emerald-600 text-white' : 'hover:bg-slate-100 bg-slate-50'}`}
                                onClick={() => handleSelectProduct(idx, product)}
                            >
                                <span className="truncate flex-1 font-bold">{product.name}</span>
                                <span className="ml-2 text-[10px] text-slate-400">{product.selling_price} F</span>
                            </button>
                          ))}

                          {result.suggestions.length === 0 && (
                              <p className="text-[10px] text-red-600 flex items-center gap-1 py-1">
                                  <AlertCircle className="size-3" />
                                  {t('facturation:prescription_scanner.no_match')}
                              </p>
                          )}
                        </div>
                      </div>
                    ))
                  )}
                </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-6 bg-slate-100/80 backdrop-blur-md border-t border-slate-100 flex justify-between items-center">
            <div className="text-xs text-slate-400">
                {extractionData && (
                    <div className="flex gap-4">
                        <span className="flex items-center gap-1"><Check className="size-3 text-emerald-600" /> {t('facturation:prescription_scanner.patient_detected')}</span>
                        <span className="flex items-center gap-1"><Check className="size-3 text-emerald-600" /> {t('facturation:prescription_scanner.doctor_detected')}</span>
                    </div>
                )}
            </div>
            <div className="flex gap-3">
                <button className="inline-flex items-center justify-center h-9 px-4 rounded-xl text-sm font-medium text-slate-700 bg-white border border-slate-200 hover:bg-slate-50 transition-colors" onClick={onClose}>{t('facturation:prescription_scanner.cancel')}</button>
                <button
                  className="inline-flex items-center justify-center h-9 px-8 rounded-xl text-sm font-semibold bg-emerald-600 text-white shadow-lg hover:bg-emerald-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  disabled={matchResults.filter(r => r.matchedProduct).length === 0 || isProcessing}
                  onClick={validateScan}
                >
                  <Check className="size-4 mr-2" />
                  {t('facturation:prescription_scanner.validate_add')}
                </button>
            </div>
        </div>
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        accept="image/*" 
        className="hidden" 
      />
      <canvas ref={canvasRef} className="hidden" />
    </PremiumModal>
  );
};

