export const LAST_ACTIVITY_KEY = 'lastActivityTime';

// D├®finition du type pour le contexte d'authentification
// Ce sont les donn├®es et fonctions qui seront accessibles partout dans l'application via useAuth()
interface AuthContextType {
  user: User | null;          // L'utilisateur connect├® (ou null si non connect├®)
  login: (userData: User) => void; // Fonction pour connecter un utilisateur
  logout: () => void;         // Fonction pour d├®connecter
  isAuthenticated: boolean;   // Bool├®en pratique pour savoir si on est connect├®
  loading: boolean;           // ├ëtat de chargement (utile au d├®marrage pour v├®rifier si une session existe)
  getServerDate: () => Date;
  syncTime: (serverTime: string) => void;
}

// Cr├®ation du contexte React
const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Composant Provider qui va envelopper l'application (dans App.tsx g├®n├®ralement)
export const AuthProvider = ({ children }: { children: ReactNode }) => {
  // ├ëtat local pour stocker l'utilisateur connect├®
  const [user, setUser] = useState<User | null>(null);
  // ├ëtat de chargement, initialis├® ├á true le temps de v├®rifier le localStorage
  const [loading, setLoading] = useState(true);
  const [timeOffset, setTimeOffset] = useState<number>(0);

  // Fonction pour obtenir la date synchronis├®e avec le serveur
  const getServerDate = useCallback(() => {
    return new Date(Date.now() + timeOffset);
  }, [timeOffset]);

  // Effet qui s'ex├®cute une seule fois au chargement de l'application (mount)
  useEffect(() => {
    // On tente de r├®cup├®rer les infos de connexion depuis le stockage s├®curis├®
    const token = safeStorage.getItem('authToken');
    const username = safeStorage.getItem('username');
    const userId = safeStorage.getItem('userId');
    const is_superuser = safeStorage.getItem('is_superuser') === 'true';
    const allowed_menus = JSON.parse(safeStorage.getItem('allowed_menus') || '[]');
    const can_do_returns = safeStorage.getItem('can_do_returns') === 'true';
    const can_sell_negative_stock = safeStorage.getItem('can_sell_negative_stock') === 'true';
    const can_cash_out = safeStorage.getItem('can_cash_out') === 'true';
    const can_delete_product = safeStorage.getItem('can_delete_product') === 'true';
    const can_adjust_stock = safeStorage.getItem('can_adjust_stock') === 'true';
    const can_delete_fournisseur = safeStorage.getItem('can_delete_fournisseur') === 'true';
    const can_delete_commande = safeStorage.getItem('can_delete_commande') === 'true';
    const can_close_commande = safeStorage.getItem('can_close_commande') === 'true';
    const can_generate_coupon = safeStorage.getItem('can_generate_coupon') === 'true';
    const is_terminal_account = safeStorage.getItem('is_terminal_account') === 'true';
    const role = safeStorage.getItem('role') || undefined;

    const storedOffset = safeStorage.getItem('timeOffset');
    if (storedOffset) {
      setTimeOffset(parseInt(storedOffset, 10));
    }

    // Si un token et un username existent, on restaure la session
    if (token && username) {
      setUser({ 
        id: userId ? parseInt(userId, 10) : undefined,
        username, 
        token, 
        is_superuser, 
        allowed_menus,
        can_do_returns,
        can_sell_negative_stock,
        can_cash_out,
        can_delete_product,
        can_adjust_stock,
        can_delete_fournisseur,
        can_delete_commande,
        can_close_commande,
        can_generate_coupon,
        is_terminal_account,
        role,
        profile: {
          can_generate_coupon,
          can_close_commande,
          role: 'VENDEUR' // Default
        }
      });
      // On configure le client API canonique pour inclure ce token
      setAuthToken(token);
    }
    // On indique que le chargement initial est termin├®
    setLoading(false);
  }, []);

  // Fonction pour synchroniser le d├®calage temporel
  const syncTime = useCallback((serverTimeStr: string) => {
    const serverTime = new Date(serverTimeStr).getTime();
    const localTime = Date.now();
    const offset = serverTime - localTime;
    setTimeOffset(offset);
    safeStorage.setItem('timeOffset', String(offset));
  }, []);

  // Fonction de connexion appel├®e apr├¿s un succ├¿s login (ex: depuis Login.tsx)
  const login = useCallback((userData: User) => {
    // Calculer le d├®calage temporel si l'heure serveur est fournie
    if (userData.server_time) {
      syncTime(userData.server_time);
    }
    
    // Reset activity timer and session flags
    safeStorage.setItem(LAST_ACTIVITY_KEY, Date.now().toString(), 'local');
    resetSessionExpiredFlag();

    // 1. On sauvegarde tout dans le stockage s├®curis├®
    safeStorage.setItem('authToken', userData.token || '');
    safeStorage.setItem('username', userData.username);
    safeStorage.setItem('is_superuser', String(userData.is_superuser));
    safeStorage.setItem('allowed_menus', JSON.stringify(userData.allowed_menus));
    safeStorage.setItem('can_do_returns', String(userData.can_do_returns || false));
    safeStorage.setItem('can_sell_negative_stock', String(userData.can_sell_negative_stock || false));
    safeStorage.setItem('can_cash_out', String(userData.can_cash_out ?? true));
    safeStorage.setItem('can_delete_product', String(userData.can_delete_product || false));
    safeStorage.setItem('can_adjust_stock', String(userData.can_adjust_stock || false));
    safeStorage.setItem('can_delete_fournisseur', String(userData.can_delete_fournisseur || false));
    safeStorage.setItem('can_delete_commande', String(userData.can_delete_commande || userData.profile?.can_delete_commande || false));
    safeStorage.setItem('can_close_commande', String(userData.can_close_commande || userData.profile?.can_close_commande || false));
    safeStorage.setItem('can_generate_coupon', String(userData.can_generate_coupon || userData.profile?.can_generate_coupon || false));
    safeStorage.setItem('is_terminal_account', String(userData.is_terminal_account || false));
    if (userData.role) {
      safeStorage.setItem('role', userData.role);
    }
    
    // Support either id or user_id from backend
    const userId = userData.id || (userData as unknown).user_id;
    if (userId) {
      safeStorage.setItem('userId', String(userId));
      userData.id = userId;
    }
    
    // 2. On met ├á jour l'├®tat de l'application
    setUser(userData);
    
    // 3. On configure le header Authorization pour les requ├¬tes API
    setAuthToken(userData.token || '');
  }, []);

  // Fonction de d├®connexion
  const logout = useCallback(async () => {
    // 1. On tente d'informer le serveur de la d├®connexion pour le suivi
    try {
      const workstation = localStorage.getItem('zenith_workstation');
      await api.post('auth/logout/', { workstation });
    } catch (err) {
      console.warn('Erreur lors de l\'enregistrement de la d├®connexion au serveur:', err);
    }

    // 2. On nettoie le stockage
    clearAuthSession();
    
    // 3. On remet l'utilisateur ├á null
    setUser(null);
  }, []);

  // M├®moriser l'objet value pour ├®viter les re-renders inutiles des enfants
  const contextValue = useMemo(() => ({
    user,
    login,
    logout,
    isAuthenticated: !!user,
    loading,
    getServerDate,
    syncTime
  }), [user, login, logout, loading, getServerDate, syncTime]);

  return (
    // On rend le contexte disponible pour tous les enfants
    // isAuthenticated est calcul├® dynamiquement : vrai si 'user' n'est pas null
    <AuthContext.Provider value={contextValue}>
      {children}
    </AuthContext.Provider>
  );
};

// Hook personnalis├® pour utiliser le contexte d'authentification plus facilement
export const useAuth = () => {
  const context = use(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { createContext, use, useState, useEffect, useMemo, useCallback, type ReactNode } from 'react';
import api from '../services/api';
import { toast } from 'react-hot-toast';
import i18n from '../i18n';

interface LicenceInfo {
    pharmacie_nom: string;
    pharmacien_nom: string;
    plan: 'TRIAL' | 'BASIC' | 'PREMIUM';
    exp: number;
    is_valid: boolean;
}

interface LicenceContextType {
    licence: LicenceInfo | null;
    loading: boolean;
    daysRemaining: number | null;
    refreshLicence: () => Promise<void>;
}

const LicenceContext = createContext<LicenceContextType | undefined>(undefined);

const LICENCE_STORAGE_KEY = 'pharmacy_licence_cache:v1';

function loadCachedLicence(): LicenceInfo | null {
    try {
        const cached = localStorage.getItem(LICENCE_STORAGE_KEY);
        if (!cached) return null;
        const data = JSON.parse(cached) as LicenceInfo;
        const expMs = (data.exp ?? 0) * 1000;
        if (!data.exp || expMs > Date.now()) return data;
        localStorage.removeItem(LICENCE_STORAGE_KEY);
    } catch {}
    return null;
}

export const LicenceProvider = ({ children }: { children: ReactNode }) => {
    const [licence, setLicence] = useState<LicenceInfo | null>(() => loadCachedLicence());
    const [loading, setLoading] = useState(true);
    const [daysRemaining, setDaysRemaining] = useState<number | null>(() => {
        const cached = loadCachedLicence();
        if (!cached?.exp) return null;
        return Math.ceil(((cached.exp * 1000) - Date.now()) / (1000 * 60 * 60 * 24));
    });

    const fetchLicence = useCallback(async () => {
        try {
            const res = await api.get('licence/');
            if (res.data.is_valid && res.data.payload) {
                const data = res.data.payload;
                const licenceInfo = { ...data, is_valid: true };
                setLicence(licenceInfo);
                // Persister la derni├¿re licence valide pour survie aux red├®marrages
                try { localStorage.setItem(LICENCE_STORAGE_KEY, JSON.stringify(licenceInfo)); } catch {}

                // Calcul des jours restants
                const expTimestamp = data.exp * 1000;
                const now = Date.now();
                const diff = expTimestamp - now;
                const days = Math.ceil(diff / (1000 * 60 * 60 * 24));
                setDaysRemaining(days);

                // Alerte si < 7 jours
                if (days <= 7 && days > 0) {
                    toast.error(i18n.t('licence_toast.expiry_warning', { days, plural: days > 1 ? 's' : '', ns: 'common' }), {
                        duration: 8000,
                        id: 'licence-expiry-warning',
                        icon: 'ÔÜá´©Å'
                    });
                } else if (days <= 0) {
                    toast.error(i18n.t('licence_toast.expired', { ns: 'common' }), {
                        duration: 10000,
                        id: 'licence-expired-error',
                        icon: '­ƒÜ½'
                    });
                }
            } else {
                // Licence invalide c├┤t├® serveur ÔÇö effacer le cache local
                try { localStorage.removeItem(LICENCE_STORAGE_KEY); } catch {}
                setLicence(null);
                setDaysRemaining(null);
            }
        } catch (err) {
            console.error("Erreur chargement licence globale", err);
            // En cas d'erreur r├®seau, utiliser la derni├¿re licence valide connue
            try {
                const cached = localStorage.getItem(LICENCE_STORAGE_KEY);
                if (cached) {
                    const cachedLicence = JSON.parse(cached) as LicenceInfo;
                    // V├®rifier que la licence en cache n'est pas expir├®e
                    const expMs = (cachedLicence.exp ?? 0) * 1000;
                    if (!cachedLicence.exp || expMs > Date.now()) {
                        setLicence(cachedLicence);
                        const days = cachedLicence.exp ? Math.ceil((expMs - Date.now()) / (1000 * 60 * 60 * 24)) : null;
                        setDaysRemaining(days);
                        return;
                    }
                }
            } catch {}
            setLicence(null);
            setDaysRemaining(null);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchLicence();
    }, []);

    // M├®moriser l'objet value pour ├®viter les re-renders inutiles
    const contextValue = useMemo(() => ({
        licence,
        loading,
        daysRemaining,
        refreshLicence: fetchLicence
    }), [licence, loading, daysRemaining, fetchLicence]);

    return (
        <LicenceContext.Provider value={contextValue}>
            {children}
        </LicenceContext.Provider>
    );
};

export const useLicence = () => {
    const context = use(LicenceContext);
    if (context === undefined) {
        throw new Error('useLicence must be used within a LicenceProvider');
    }
    return context;
};

