interface PharmacySettingsContextType {
  settings: PharmacySettings;
  loading: boolean;
  error: string | null;
  updateSettings: (updates: Partial<PharmacySettings>) => Promise<PharmacySettings>;
  uploadLogo: (file: File) => Promise<PharmacySettings>;
  removeLogo: () => Promise<PharmacySettings>;
  refetch: () => Promise<void>;
}

const PharmacySettingsContext = createContext<PharmacySettingsContextType | undefined>(undefined);

export const PharmacySettingsProvider = ({ children }: { children: ReactNode }) => {
  const [settings, setSettings] = useState<PharmacySettings>(DEFAULT_SETTINGS);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { syncTime, isAuthenticated } = useAuth();
  const { licence } = useLicence();

  const fetchSettings = useCallback(async () => {
    try {
      setLoading(true);
      const { data } = await api.get<PharmacySettings & { server_time: string }>('pharmacy-settings/');
      if (data.server_time) syncTime(data.server_time);
      setSettings(data);
      setError(null);
    } catch (err) {
      console.error('Error fetching pharmacy settings:', err);
      setError('Erreur lors du chargement des param├¿tres');
      setSettings(DEFAULT_SETTINGS);
    } finally {
      setLoading(false);
    }
  }, [syncTime]);

  const updateSettings = useCallback(async (updates: Partial<PharmacySettings>) => {
    try {
      const { data } = await api.put<PharmacySettings>('pharmacy-settings/', updates);
      setSettings(data);
      toast.success('Param├¿tres sauvegard├®s');
      return data;
    } catch (err) {
      console.error('Error updating pharmacy settings:', err);
      toast.error('Erreur lors de la sauvegarde');
      throw err;
    }
  }, []);

  const uploadLogo = useCallback(async (file: File) => {
    try {
      const formData = new FormData();
      formData.append('logo', file);
      const { data } = await api.put<PharmacySettings>('pharmacy-settings/', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setSettings(data);
      toast.success('Logo import├® avec succ├¿s');
      return data;
    } catch (err) {
      console.error('Error uploading logo:', err);
      toast.error('Erreur lors de l\'import du logo');
      throw err;
    }
  }, []);

  const removeLogo = useCallback(async () => {
    try {
      const { data } = await api.put<PharmacySettings>('pharmacy-settings/', { logo: '' });
      setSettings(data);
      toast.success('Logo supprim├®');
      return data;
    } catch (err) {
      console.error('Error removing logo:', err);
      toast.error('Erreur lors de la suppression du logo');
      throw err;
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchSettings();
    } else {
      setLoading(false);
    }
  }, [fetchSettings, isAuthenticated]);

  // On fusionne les param├¿tres avec le nom de la pharmacie provenant de la licence
  const effectiveSettings = {
    ...settings,
    pharmacy_name: licence?.pharmacie_nom || settings.pharmacy_name
  };

  // M├®moriser l'objet value pour ├®viter les re-renders inutiles
  const contextValue = useMemo(() => ({
    settings: effectiveSettings,
    loading,
    error,
    updateSettings,
    uploadLogo,
    removeLogo,
    refetch: fetchSettings
  }), [effectiveSettings, loading, error, updateSettings, uploadLogo, removeLogo, fetchSettings]);

  return (
    <PharmacySettingsContext.Provider value={contextValue}>
      {children}
    </PharmacySettingsContext.Provider>
  );
};

export const usePharmacySettings = () => {
  const context = use(PharmacySettingsContext);
  if (context === undefined) {
    throw new Error('usePharmacySettings must be used within a PharmacySettingsProvider');
  }
  return context;
};

import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react'
import { useAuth } from './AuthContext'
import { cashSessionService, type PosteVente } from '../services/cashSessionService'

const POS_TAB_KEY = 'pos_tab_poste_vente_id'
const POS_MODE_KEY = 'pos_tab_mode'

interface PosteCaisseModeContextType {
  activePoste: PosteVente | null
  selectedPosteCaisseId: number | null
  isPosMode: boolean
  isLoading: boolean
  refresh: () => Promise<void>
  openPoste: (caisseId: number, fondDeCaisse?: string) => Promise<PosteVente>
  setActivePosteVente: (poste: PosteVente) => void
  closePoste: (hideAmounts?: boolean) => Promise<void>
  selectPoste: (id: number | null) => void
}

const PosteCaisseModeContext = createContext<PosteCaisseModeContextType | undefined>(undefined)

export function PosteCaisseModeProvider({ children }: { children: ReactNode }) {
  const { isAuthenticated } = useAuth()
  const [activePoste, setActivePoste] = useState<PosteVente | null>(null)
  const [selectedPosteCaisseId, setSelectedPosteCaisseId] = useState<number | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const refresh = useCallback(async () => {
    if (!isAuthenticated) return
    setIsLoading(true)
    try {
      const tabPosteId = sessionStorage.getItem(POS_TAB_KEY)
      // Un nouvel onglet n'a pas POS_TAB_KEY ÔåÆ ne pas forcer la restauration du POS
      if (!tabPosteId) {
        setActivePoste(null)
        setIsLoading(false)
        return
      }

      const postes = await cashSessionService.getMyActivePostesVente()
      const matching = postes.find((p) => String(p.id) === tabPosteId) || postes[0] || null

      if (matching) {
        setActivePoste(matching)
        sessionStorage.setItem(POS_TAB_KEY, String(matching.id))
        sessionStorage.setItem(POS_MODE_KEY, matching.mode_pos ? 'pos' : 'caisse')
        if (!matching.mode_pos && matching.caisse) {
          setSelectedPosteCaisseId(matching.caisse)
        }
      } else {
        sessionStorage.removeItem(POS_TAB_KEY)
        sessionStorage.removeItem(POS_MODE_KEY)
        setActivePoste(null)
      }
    } catch (err) {
      console.error('Erreur refresh poste actif:', err)
    } finally {
      setIsLoading(false)
    }
  }, [isAuthenticated])

  useEffect(() => {
    refresh()
  }, [refresh])

  const openPoste = useCallback(async (posteVenteId: number, fondDeCaisse?: string) => {
    const data = await cashSessionService.activerPosteVente(posteVenteId, fondDeCaisse)
    sessionStorage.setItem(POS_TAB_KEY, String(data.id))
    sessionStorage.setItem(POS_MODE_KEY, 'pos')
    setActivePoste(data)
    // POS n'a pas de caisse ÔÇö ne pas remplacer le selectedPosteCaisseId
    return data
  }, [])

  const setActivePosteVente = useCallback((poste: PosteVente) => {
    sessionStorage.setItem(POS_TAB_KEY, String(poste.id))
    sessionStorage.setItem(POS_MODE_KEY, poste.mode_pos ? 'pos' : 'caisse')
    setActivePoste(poste)
    // Seulement assigner selectedPosteCaisseId si c'est une caisse physique (mode_pos=False)
    if (!poste.mode_pos && poste.caisse) {
      setSelectedPosteCaisseId(poste.caisse)
    }
  }, [])

  const closePoste = useCallback(async (hideAmounts?: boolean) => {
    if (!activePoste) return
    await cashSessionService.closePosteVente(activePoste.id, hideAmounts)
    sessionStorage.removeItem(POS_TAB_KEY)
    sessionStorage.removeItem(POS_MODE_KEY)
    setActivePoste(null)
    setSelectedPosteCaisseId(null)
  }, [activePoste])

  const selectPoste = useCallback((id: number | null) => {
    setSelectedPosteCaisseId(id)
  }, [])

  const value: PosteCaisseModeContextType = {
    activePoste,
    selectedPosteCaisseId,
    // Le mode POS d├®pend du mode d'ouverture (mode_pos).
    // Un POS n'a pas de caisse physique ÔÇö il envoie les ventes vers la caisse de la caissi├¿re.
    isPosMode: !!activePoste && (activePoste.mode_pos === true || sessionStorage.getItem(POS_MODE_KEY) === 'pos'),
    isLoading,
    refresh,
    openPoste,
    setActivePosteVente,
    closePoste,
    selectPoste
  }

  return (
    <PosteCaisseModeContext.Provider value={value}>
      {children}
    </PosteCaisseModeContext.Provider>
  )
}

export function usePosteCaisseMode(): PosteCaisseModeContextType {
  const ctx = useContext(PosteCaisseModeContext)
  if (!ctx) {
    throw new Error('usePosteCaisseMode must be used within PosteCaisseModeProvider')
  }
  return ctx
}

import { useState, useEffect, useMemo, createContext, type ReactNode } from 'react'

export interface SidebarContextType {
  isOpen: boolean
  isCollapsed: boolean
  isZenithMode: boolean
  isMidnightTheme: boolean
  toggleSidebar: () => void
  closeSidebar: () => void
  openSidebar: () => void
  toggleCollapse: () => void
  toggleZenithMode: () => void
  toggleMidnightTheme: () => void
}

export const SidebarContext = createContext<SidebarContextType | undefined>(undefined)

export function SidebarProvider({ children }: { children: ReactNode }) {
  const [isOpen, setIsOpen] = useState(false)
  // Lire l'├®tat sauvegard├® depuis localStorage
  const [isCollapsed, setIsCollapsed] = useState(() => {
    const saved = localStorage.getItem('sidebar-collapsed')
    return saved === 'true'
  })
  const [isZenithMode, setIsZenithMode] = useState(false)
  const [isMidnightTheme, setIsMidnightTheme] = useState(() => {
    return localStorage.getItem('theme-midnight') === 'true'
  })

  // Appliquer le th├¿me ├á la racine du document (pour affecter aussi les Modals et SweetAlerts)
  useEffect(() => {
    if (isMidnightTheme) {
      document.documentElement.classList.add('theme-midnight')
      document.documentElement.setAttribute('data-theme', 'dark')
    } else {
      document.documentElement.classList.remove('theme-midnight')
      document.documentElement.setAttribute('data-theme', 'light')
    }
  }, [isMidnightTheme])

  // Auto-collapse on small screens (< 1280px)
  useEffect(() => {
    const checkScreenWidth = () => {
      const isSmall = window.innerWidth < 1280
      if (isSmall) {
        setIsCollapsed(true)
      }
    }
    checkScreenWidth()
    window.addEventListener('resize', checkScreenWidth)
    return () => window.removeEventListener('resize', checkScreenWidth)
  }, [])

  // Persister les pr├®f├®rences utilisateur
  useEffect(() => {
    localStorage.setItem('sidebar-collapsed', String(isCollapsed))
  }, [isCollapsed])

  useEffect(() => {
    localStorage.setItem('theme-midnight', String(isMidnightTheme))
  }, [isMidnightTheme])

  const toggleSidebar = () => setIsOpen(prev => !prev)
  const closeSidebar = () => setIsOpen(false)
  const openSidebar = () => setIsOpen(true)
  const toggleCollapse = () => setIsCollapsed(prev => !prev)
  const toggleZenithMode = () => setIsZenithMode(prev => !prev)
  const toggleMidnightTheme = () => setIsMidnightTheme(prev => !prev)

  // M├®moriser l'objet value pour ├®viter les re-renders inutiles
  const contextValue = useMemo(() => ({
    isOpen,
    isCollapsed,
    isZenithMode,
    isMidnightTheme,
    toggleSidebar,
    closeSidebar,
    openSidebar,
    toggleCollapse,
    toggleZenithMode,
    toggleMidnightTheme
  }), [isOpen, isCollapsed, isZenithMode, isMidnightTheme]);

  return (
    <SidebarContext.Provider value={contextValue}>
      {children}
    </SidebarContext.Provider>
  )
}

import { useState, useEffect, useRef } from 'react';
import api from '../../services/api';
import { toast } from 'react-hot-toast';
import { useTranslation } from 'react-i18next';
import type { Inventaire, LigneInventaire, InventoryStats, ProduitModel } from '../../types';

export const useInventaireEditor = (
    fetchInventaires: () => void,
    setViewMode: (mode: 'LIST' | 'CREATE' | 'EDIT' | 'AUDIT') => void,
    requireSudo: (action: (validatorId: number, password?: string) => Promise<void>, options?: { title?: string; message?: string; permission?: string }) => void,
    confirm: (options: { title?: string; message: string; variant?: 'success' | 'warning' | 'danger' | 'info'; confirmText?: string }) => Promise<boolean>
) => {
    const { t } = useTranslation(['stock', 'common']);

    const [activeInventaire, setActiveInventaire] = useState<Inventaire | null>(null);
    const [lignes, setLignes] = useState<LigneInventaire[]>([]);
    const [saving, setSaving] = useState(false);
    const [autoSaving, setAutoSaving] = useState(false);
    const [importing, setImporting] = useState(false);
    const [inventoryStats, setInventoryStats] = useState<InventoryStats | null>(null);

    // Header fields
    const [dateInventaire, setDateInventaire] = useState('');
    const [description, setDescription] = useState('');

    // Line selection and bulk actions
    const [selectedLines, setSelectedLines] = useState<Set<number>>(new Set());

    // Auto-save: track lines with unsaved quantity changes
    const [dirtyLineIds, setDirtyLineIds] = useState<Set<number>>(new Set());
    const pendingChangesRef = useRef<Map<number, number>>(new Map());
    const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const localOnlyDebounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const isReadOnly = activeInventaire?.status === 'VALIDEE';

    const handleCreate = async () => {
        // Now handled by handleCreateWithOptions, but keep default for backward compatibility if needed
        return handleCreateWithOptions({ action: 'ENTRY', stockType: 'GLOBAL' });
    };

    const handleCreateWithOptions = async (options: {
        action: 'VERIFY' | 'ENTRY';
        stockType: 'GLOBAL' | 'RAYON' | 'RESERVE';
        rayonId?: number;
        groupeId?: number;
        formeId?: number;
    }) => {
        try {
            setSaving(true);
            // Reset dirty tracking
            pendingChangesRef.current = new Map();
            setDirtyLineIds(new Set());
            cancelPendingSyncs();

            // 1. Create the inventory header
            const response = await api.post('inventaires/', {
                date: new Date().toISOString().split('T')[0],
                description: t('inventaire.detail.placeholder_desc'),
                status: 'EN_COURS',
                inventory_type: options.stockType
            });
            const newInv = response.data;
            setActiveInventaire(newInv);
            setDateInventaire(newInv.date);
            setDescription(newInv.description || '');

            // 2. Switch to CREATE mode immediately so the editor is mounted
            setViewMode('CREATE');

            // 3. Pre-populate if requested
            if (options.action === 'VERIFY') {
                await api.post(`inventaires/${newInv.id}/pre_populate/`, {
                    rayon_id: options.rayonId,
                    groupe_id: options.groupeId,
                    forme_id: options.formeId
                });
                // Reload lines and stats
                const [linesRes, statsRes] = await Promise.all([
                    api.get(`inventaires/${newInv.id}/lignes/`),
                    api.get(`inventaires/${newInv.id}/stats/`).catch(() => ({ data: null }))
                ]);

                setLignes(linesRes.data.map((l: LigneInventaire) => ({ ...l, isLocalOnly: false })));
                if (statsRes.data) setInventoryStats(statsRes.data);
            } else {
                setLignes([]);
                setInventoryStats(null);
            }

            return newInv;
        } catch (error) {
            console.error(error);
            toast.error(t('inventaire.detail.auto_create_error'));
        } finally {
            setSaving(false);
        }
    };

    const handleEdit = async (inv: Inventaire) => {
        // Reset dirty tracking
        pendingChangesRef.current = new Map();
        setDirtyLineIds(new Set());
        cancelPendingSyncs();

        setActiveInventaire(inv);
        setDateInventaire(inv.date);
        setDescription(inv.description || '');
        setViewMode('EDIT');
        try {
            const res = await api.get(`inventaires/${inv.id}/lignes/`);
            const fetchedLignes = res.data.map((l: LigneInventaire) => ({
                ...l,
                isLocalOnly: false
            }));
            setLignes(fetchedLignes);
            await fetchInventoryStats(inv.id);
        } catch (error) {
            console.error(error);
            toast.error(t('common:messages.error_loading'));
        }
    };

    const handleSaveHeader = async () => {
        if (!activeInventaire) return;
        try {
            await api.patch(`inventaires/${activeInventaire.id}/`, {
                date: dateInventaire,
                description
            });
            toast.success(t('inventaire.detail.header_saved'));
            // Optionally update the active inventaire object
            setActiveInventaire(prev => prev ? { ...prev, date: dateInventaire, description } : null);
        } catch {
            toast.error(t('inventaire.detail.save_error'));
        }
    };


    // Ref to latest state for use inside async callbacks / intervals
    const autoSaveInvRef = useRef({ activeInventaire, lignes, saving, flushPendingChanges: async () => {}, syncLocalOnlyLines: async () => {} });

    // Preserve focus across state updates / reloads
    const preserveFocus = () => {
        const active = document.activeElement;
        if (!active || !(active instanceof HTMLInputElement)) return null;
        return {
            id: active.id,
            selectionStart: active.selectionStart,
            selectionEnd: active.selectionEnd,
            value: active.value
        };
    };

    const restoreFocus = (focusInfo: ReturnType<typeof preserveFocus>) => {
        if (!focusInfo) return;
        const el = document.getElementById(focusInfo.id);
        if (el && el instanceof HTMLInputElement) {
            el.focus();
            if (focusInfo.value !== undefined && el.value !== focusInfo.value) {
                // If the input was modified by a state update, keep the current value
                // to avoid overwriting what the user is typing.
            }
            if (focusInfo.selectionStart !== null && focusInfo.selectionEnd !== null) {
                try {
                    el.setSelectionRange(focusInfo.selectionStart, focusInfo.selectionEnd);
                } catch {
                    // ignore if input type doesn't support selection
                }
            }
        }
    };

    const flushPendingChanges = async () => {
        const pending = pendingChangesRef.current;
        if (pending.size === 0 || !activeInventaire) return;

        const focusInfo = preserveFocus();
        setAutoSaving(true);
        const updates = Array.from(pending.entries());
        pendingChangesRef.current = new Map();

        try {
            // Send all pending updates in parallel ÔÇö no full reload, no toast
            await Promise.all(
                updates.map(([lineId, qty]) =>
                    api.patch(`lignes-inventaire/${lineId}/`, { quantite_physique: qty })
                )
            );
            // Clear dirty flags for successfully saved lines
            setDirtyLineIds(prev => {
                const next = new Set(prev);
                updates.forEach(([id]) => next.delete(id));
                return next;
            });
        } catch (err) {
            console.error("Auto-save batch error:", err);
        } finally {
            setAutoSaving(false);
            restoreFocus(focusInfo);
        }
    };

    const syncLocalOnlyLines = async () => {
        const { activeInventaire: inv, lignes: currentLignes } = autoSaveInvRef.current;
        if (!inv) return;
        if (inv.status === 'VALIDEE') return;

        const linesToSync = currentLignes.filter(l => l.isLocalOnly);
        if (linesToSync.length === 0) return;

        // Never disturb an active quantity input: defer if the user is typing
        const active = document.activeElement;
        const isTyping = active instanceof HTMLInputElement && active.type === 'number';
        if (isTyping) {
            // Reschedule: user is still typing, wait for the next quiet window
            scheduleLocalOnlySync();
            return;
        }

        const focusInfo = preserveFocus();
        setAutoSaving(true);
        try {
            const payload = {
                lignes: linesToSync.map(l => ({
                    produit: typeof l.produit === 'object' ? l.produit.id : l.produit,
                    stock_lot: l.stock_lot,
                    quantite_physique: l.quantite_physique,
                    lot_numero: l.lot_numero,
                    lot_expiration: l.lot_expiration
                }))
            };
            await api.post(`inventaires/${inv.id}/lignes/bulk/`, payload);
            const res = await api.get(`inventaires/${inv.id}/lignes/`);
            setLignes(res.data.map((l: LigneInventaire) => ({ ...l, isLocalOnly: false })));
        } catch (err) {
            console.error("Auto-save local-only lines error:", err);
        } finally {
            setAutoSaving(false);
            restoreFocus(focusInfo);
        }
    };

    const scheduleLocalOnlySync = () => {
        if (localOnlyDebounceTimerRef.current) {
            clearTimeout(localOnlyDebounceTimerRef.current);
        }
        localOnlyDebounceTimerRef.current = setTimeout(() => {
            syncLocalOnlyLines();
        }, 5000);
    };

    const cancelPendingSyncs = () => {
        if (debounceTimerRef.current) {
            clearTimeout(debounceTimerRef.current);
            debounceTimerRef.current = null;
        }
        if (localOnlyDebounceTimerRef.current) {
            clearTimeout(localOnlyDebounceTimerRef.current);
            localOnlyDebounceTimerRef.current = null;
        }
    };

    const handleUpdateQuantity = (lineId: number, newQty: number) => {
        // Optimistic update
        setLignes(prev => prev.map(l => {
            if (l.id === lineId) {
                const ecart = newQty - l.stock_theorique;
                return { ...l, quantite_physique: newQty, ecart };
            }
            return l;
        }));

        const line = lignes.find(l => l.id === lineId);
        if (line?.isLocalOnly) {
            // Local-only lines have no real ID yet; schedule a background sync
            // after the user stops typing so we don't disturb the active input.
            scheduleLocalOnlySync();
            return;
        }

        // Track pending change for auto-save debounce
        pendingChangesRef.current.set(lineId, newQty);
        setDirtyLineIds(prev => new Set(prev).add(lineId));

        // Reset debounce timer
        if (debounceTimerRef.current) {
            clearTimeout(debounceTimerRef.current);
        }
        debounceTimerRef.current = setTimeout(() => {
            flushPendingChanges();
        }, 1500);
    };

    const handleDeleteLine = async (lineId: number) => {
        const confirmed = await confirm({
            title: 'Retirer le produit',
            message: 'Retirer ce produit de l\'inventaire ?',
            variant: 'warning',
            confirmText: 'Retirer'
        });
        if (!confirmed) return;

        try {
            const line = lignes.find(l => l.id === lineId);
            if (line && !line.isLocalOnly) {
                await api.delete(`lignes-inventaire/${lineId}/`);
            }
            setLignes(prev => prev.filter(l => l.id !== lineId));
            // Clean up dirty tracking
            pendingChangesRef.current.delete(lineId);
            setDirtyLineIds(prev => {
                const next = new Set(prev);
                next.delete(lineId);
                return next;
            });
        } catch (err) {
            console.error("Erreur suppression ligne", err);
            toast.error(t('inventaire.lines.delete_error'));
        }
    };

    const toggleSelectLine = (id: number) => {
        const newSet = new Set(selectedLines);
        if (newSet.has(id)) {
            newSet.delete(id);
        } else {
            newSet.add(id);
        }
        setSelectedLines(newSet);
    };

    const toggleSelectAll = () => {
        const ecartLines = lignes.filter(l => (l.quantite_physique || 0) !== (l.stock_theorique || 0));
        if (selectedLines.size === ecartLines.length && ecartLines.length > 0) {
            setSelectedLines(new Set());
        } else {
            setSelectedLines(new Set(ecartLines.map(l => l.id)));
        }
    };

    const handleBulkDelete = async () => {
        if (selectedLines.size === 0) return;

        const confirmed = await confirm({
            title: t('inventaire.detail.bulk_delete_title'),
            message: t('inventaire.detail.bulk_delete_message', { count: selectedLines.size }),
            variant: 'danger',
            confirmText: t('inventaire.detail.bulk_delete_confirm')
        });
        if (!confirmed) return;

        try {
            setSaving(true);
            const idsToDelete = Array.from(selectedLines);

            const remoteIds = idsToDelete.filter(id => {
                const line = lignes.find(l => l.id === id);
                return line && !line.isLocalOnly;
            });

            // 1. Suppression distante group├®e
            if (remoteIds.length > 0 && activeInventaire) {
                await api.post(`inventaires/${activeInventaire.id}/lignes/bulk-delete/`, {
                    ids: remoteIds
                });
            }

            // 2. Mise ├á jour locale
            setLignes(prev => prev.filter(l => !selectedLines.has(l.id)));
            setSelectedLines(new Set());
            toast.success(t('inventaire.detail.bulk_delete_success', { count: idsToDelete.length }));

        } catch (err) {
            console.error("Erreur suppression bulk", err);
            toast.error(t('inventaire.detail.save_error'));
        } finally {
            setSaving(false);
        }
    };

    const fetchInventoryStats = async (id: number) => {
        try {
            const res = await api.get(`inventaires/${id}/stats/`);
            setInventoryStats(res.data);
        } catch (error) {
            console.error("Failed to fetch inventory stats", error);
        }
    };

    const handleValidateConfirm = async (creds: { validated_by_id: number; sudo_password: string }) => {
        if (!activeInventaire) return;

        try {
            setSaving(true);
            await api.post(`inventaires/${activeInventaire.id}/validate/`, creds);
            toast.success(t('inventaire.validation.success'));
            setViewMode('LIST');
            fetchInventaires();
        } catch (err: unknown) {
            const error = err as { response?: { data?: { detail?: string } } };
            toast.error(error.response?.data?.detail || t('inventaire.validation.error'));
            console.error(err);
            throw err;
        } finally {
            setSaving(false);
        }
    };

    const handleOpenValidateModal = async () => {
        if (!activeInventaire) return;

        // Cancel any pending debounce and flush changes
        cancelPendingSyncs();

        // Flush pending quantity changes first
        if (pendingChangesRef.current.size > 0) {
            setSaving(true);
            try {
                await flushPendingChanges();
            } catch (err) {
                console.error("Flush before validate failed", err);
                toast.error(t('inventaire.detail.save_error'));
                setSaving(false);
                return;
            } finally {
                setSaving(false);
            }
        }

        // Auto-save local lines before validation
        const linesToSync = lignes.filter(l => l.isLocalOnly);
        if (linesToSync.length > 0) {
            setSaving(true);
            try {
                const payload = {
                    lignes: linesToSync.map(l => ({
                        produit: typeof l.produit === 'object' ? l.produit.id : l.produit,
                        stock_lot: l.stock_lot,
                        quantite_physique: l.quantite_physique,
                        lot_numero: l.lot_numero,
                        lot_expiration: l.lot_expiration
                    }))
                };
                await api.post(`inventaires/${activeInventaire.id}/lignes/bulk/`, payload);
                const res = await api.get(`inventaires/${activeInventaire.id}/lignes/`);
                setLignes(res.data.map((l: LigneInventaire) => ({ ...l, isLocalOnly: false })));
            } catch (err) {
                console.error("Auto-save before validate failed", err);
                toast.error(t('inventaire.detail.save_error'));
                setSaving(false);
                return; // Stop if auto-save fails
            } finally {
                setSaving(false);
            }
        }

        requireSudo(
            async (validatorId, password) => {
                await handleValidateConfirm({ validated_by_id: validatorId, sudo_password: password || '' });
            },
            {
                title: t('inventaire.validation.title'),
                message: t('inventaire.validation.message')
            }
        );
    };

    const handleManualSave = async () => {
        if (!activeInventaire) return;
        setSaving(true);
        try {
            // Cancel any pending debounce
            cancelPendingSyncs();

            // 1. Flush pending quantity changes first
            await flushPendingChanges();

            // 2. Save Header
            await api.patch(`inventaires/${activeInventaire.id}/`, {
                date: dateInventaire,
                description
            });
            setActiveInventaire(prev => prev ? { ...prev, date: dateInventaire, description } : null);

            // 3. Sync Lines
            const linesToSync = lignes.filter(l => l.isLocalOnly);
            if (linesToSync.length > 0) {
                const payload = {
                    lignes: linesToSync.map(l => ({
                        produit: typeof l.produit === 'object' ? l.produit.id : l.produit,
                        stock_lot: l.stock_lot,
                        quantite_physique: l.quantite_physique,
                        lot_numero: l.lot_numero,
                        lot_expiration: l.lot_expiration
                    }))
                };
                await api.post(`inventaires/${activeInventaire.id}/lignes/bulk/`, payload);
                const res = await api.get(`inventaires/${activeInventaire.id}/lignes/`);
                setLignes(res.data.map((l: LigneInventaire) => ({ ...l, isLocalOnly: false })));
                await fetchInventoryStats(activeInventaire.id);
            }

            toast.success(t('common:messages.saved'));
        } catch (error) {
            console.error("Erreur save manual", error);
            toast.error(t('inventaire.detail.save_error'));
        } finally {
            setSaving(false);
        }
    };

    const handleImportCSV = async (file: File) => {
        if (!activeInventaire) return;

        setImporting(true);

        // 1. Charger TOUS les produits pour le matching (optimis├®)
        let allProducts: ProduitModel[] = [];
        try {
            const response = await api.get('produits/for_import/');
            allProducts = Array.isArray(response.data) ? response.data : (response.data.results || []);
        } catch (err) {
            toast.error("Erreur lors du chargement des produits pour l'import");
            console.error(err);
            setImporting(false);
            return;
        }

        // Helper de normalisation CIP (identique ├á Commandes.tsx)
        const normalizeCip = (cip: string | null | undefined): string => {
            if (!cip) return '';
            const normalized = cip.trim().replace(/[\s\-\.]/g, '');
            return normalized.toUpperCase();
        };

        const reader = new FileReader();
        reader.onload = async (e) => {
            const text = e.target?.result as string;
            if (!text) {
                setImporting(false);
                return;
            }

            const lines = text.split(/\r\n|\n/);

            // 1. Cr├®er une Map d'indexation pour les produits par CIP (O(1) lookup)
            const productByCipMap = new Map<string, ProduitModel>();
            allProducts.forEach(p => {
                const cips = [normalizeCip(p.cip1), normalizeCip(p.cip2), normalizeCip(p.cip3)];
                cips.forEach(cip => {
                    if (cip) {
                        productByCipMap.set(cip, p);
                        // Aussi indexer sans les z├®ros de t├¬te pour plus de flexibilit├®
                        const numeric = cip.replace(/^0+/, '');
                        if (numeric && !productByCipMap.has(numeric)) {
                            productByCipMap.set(numeric, p);
                        }
                    }
                });
            });

            const importMap = new Map<number, number>(); // productId -> totalQuantity
            let productsFoundCount = 0;
            const notFoundItems: { cip: string; qty: string }[] = [];

            // D├®tection du d├®limiteur (simple sur la premi├¿re ligne significative)
            let delimiter = ';';
            for (const line of lines) {
                if (line.trim() && line.includes(',')) {
                    if (!line.includes(';')) delimiter = ',';
                    break;
                }
            }

            // 2. Parsing et Matching
            lines.forEach((line, index) => {
                if (!line.trim() || index === 0) return; // Sauter en-t├¬te ou vide

                const parts = line.split(delimiter);
                const rawCip = parts[0]?.trim();
                const rawQty = parts[1]?.trim() || '1';

                if (!rawCip) return;

                const normalizedSearchCip = normalizeCip(rawCip);
                const numericSearch = normalizedSearchCip.replace(/^0+/, '');

                // Recherche O(1) via la Map
                const product = productByCipMap.get(normalizedSearchCip) || productByCipMap.get(numericSearch);

                if (product) {
                    const qty = parseFloat(rawQty.replace(',', '.')) || 0;
                    if (qty > 0) {
                        const current = importMap.get(product.id) || 0;
                        importMap.set(product.id, current + qty);
                        productsFoundCount++;
                    }
                } else {
                    notFoundItems.push({ cip: rawCip, qty: rawQty });
                }
            });

            // 2. G├®rer les produits non trouv├®s
            if (notFoundItems.length > 0) {
                const txtContent = notFoundItems.map(item => `${item.cip}${delimiter}${item.qty}`).join('\n');
                const blob = new Blob([txtContent], { type: 'text/plain;charset=utf-8;' });
                const link = document.createElement('a');
                const dateStr = new Date().toISOString().slice(0, 10);
                link.href = URL.createObjectURL(blob);
                link.download = `produits_non_reconnus_inventaire_${dateStr}.txt`;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);

                toast.error(`${notFoundItems.length} produits non reconnus. Fichier rapport t├®l├®charg├®.`);
            }

            if (importMap.size === 0) {
                toast.error("Aucun produit valide trouv├® dans le fichier.");
                setImporting(false);
                return;
            }

            // 3. Envoyer les donn├®es match├®es au backend via bulk
            try {
                const payload = {
                    lignes: Array.from(importMap.entries()).map(([productId, qty]) => ({
                        produit: productId,
                        quantite_physique: qty,
                        stock_lot: null // L'import CSV standard ne g├¿re pas encore les lots explicitement
                    }))
                };

                await api.post(`inventaires/${activeInventaire.id}/lignes/bulk/`, payload);

                toast.success(`${importMap.size} produits import├®s (${productsFoundCount} lignes).`);

                // Recharger les lignes et stats
                const res = await api.get(`inventaires/${activeInventaire.id}/lignes/`);
                setLignes(res.data.map((l: LigneInventaire) => ({ ...l, isLocalOnly: false })));
                await fetchInventoryStats(activeInventaire.id);
            } catch (error: unknown) {
                console.error("Erreur lors de l'envoi bulk", error);
                const err = error as { response?: { data?: { detail?: string } } };
                toast.error(err.response?.data?.detail || "Erreur lors de l'enregistrement des lignes import├®es.");
            } finally {
                setImporting(false);
            }
        };

        reader.onerror = () => {
            toast.error("Erreur de lecture du fichier.");
            setImporting(false);
        };

        reader.readAsText(file);
    };

    useEffect(() => {
        autoSaveInvRef.current = { activeInventaire, lignes, saving, flushPendingChanges, syncLocalOnlyLines };
    });

    // Cleanup debounce timers on unmount
    useEffect(() => {
        return () => {
            cancelPendingSyncs();
        };
    }, []);

    useEffect(() => {
        const interval = setInterval(async () => {
            const { activeInventaire: inv, lignes: currentLignes, saving: isSaving, flushPendingChanges: flush, syncLocalOnlyLines: sync } = autoSaveInvRef.current;
            if (!inv || isSaving) return;
            if (inv.status === 'VALIDEE') return;

            // 1. Flush pending quantity changes first (silent, no reload)
            await flush();

            // 2. Sync local-only lines in the background (deferred if user is typing)
            const linesToSync = currentLignes.filter(l => l.isLocalOnly);
            if (linesToSync.length > 0) {
                await sync();
            }
        }, 30000);

        return () => clearInterval(interval);
    }, []);

    return {
        activeInventaire, setActiveInventaire,
        lignes, setLignes,
        dateInventaire, setDateInventaire,
        description, setDescription,
        saving, setSaving,
        autoSaving,
        isReadOnly, importing,
        selectedLines, setSelectedLines,
        dirtyLineIds,
        handleCreate, handleEdit, handleCreateWithOptions,
        handleSaveHeader, handleManualSave, handleImportCSV,
        handleUpdateQuantity, handleDeleteLine,
        toggleSelectLine, toggleSelectAll, handleBulkDelete,
        handleOpenValidateModal,
        inventoryStats, fetchInventoryStats
    };
};

import { useState, useEffect, useRef } from 'react';
import api from '../../services/api';
import { toast } from 'react-hot-toast';
import { useTranslation } from 'react-i18next';
import { getApiErrorDetail } from '../../utils/errorHandling';
import type { Inventaire } from '../../types';

interface UseInventaireMergeProps {
    viewMode: 'LIST' | 'CREATE' | 'EDIT' | 'AUDIT';
    selectedInventaireIds: Set<number>;
    inventaires: Inventaire[];
    setSelectedInventaireIds: (ids: Set<number>) => void;
    fetchInventaires: () => void;
    activeInventaire: Inventaire | null;
    handleEdit: (inv: Inventaire) => void;
}

export const useInventaireMerge = ({
    viewMode,
    selectedInventaireIds,
    inventaires,
    setSelectedInventaireIds,
    fetchInventaires,
    activeInventaire,
    handleEdit
}: UseInventaireMergeProps) => {
    const { t } = useTranslation(['stock', 'common']);
    const [showMergeModal, setShowMergeModal] = useState(false);
    const [mergeCandidates, setMergeCandidates] = useState<Inventaire[]>([]);
    const [loadingMergeCandidates, setLoadingMergeCandidates] = useState(false);
    const [selectedMergeSource, setSelectedMergeSource] = useState<number | null>(null);
    const [merging, setMerging] = useState(false);

    const mergeControllerRef = useRef<AbortController | null>(null);

    const canMergeSelectedInventaires = () => {
        if (selectedInventaireIds.size < 2) return { canMerge: false, reason: t('inventaire.merge.need_two', { defaultValue: 'S├®lectionnez au moins 2 inventaires.' }) };

        const selectedDocs = inventaires.filter(i => selectedInventaireIds.has(i.id));
        if (selectedDocs.length === 0) return { canMerge: false, reason: t('inventaire.merge.error', { defaultValue: 'Erreur lors de la s├®lection.' }) };

        const firstStatus = selectedDocs[0].status;
        const allSameStatus = selectedDocs.every((i: Inventaire) => i.status === firstStatus);
        if (!allSameStatus) return { canMerge: false, reason: t('inventaire.merge.same_status_required', { defaultValue: 'Les inventaires s├®lectionn├®s doivent avoir le m├¬me ├®tat (tous en pr├®paration ou tous cl├┤tur├®s).' }) };

        return { canMerge: true, reason: null };
    };

    const fetchMergeCandidates = async () => {
        if (!activeInventaire) return;
        mergeControllerRef.current?.abort();
        const controller = new AbortController();
        mergeControllerRef.current = controller;
        setLoadingMergeCandidates(true);
        try {
            const res = await api.get('inventaires/', { params: { status: activeInventaire.status }, signal: controller.signal });
            const candidates = (Array.isArray(res.data) ? res.data : res.data.results)
                .filter((inv: Inventaire) => inv.id !== activeInventaire.id);
            setMergeCandidates(candidates);
        } catch (err) {
            if (err instanceof Error && err.name === 'CanceledError') return;
            console.error("Erreur candidats fusion", err);
        } finally {
            setLoadingMergeCandidates(false);
        }
    };

    useEffect(() => {
        if (showMergeModal && viewMode !== 'LIST') {
            fetchMergeCandidates();
        }
        return () => mergeControllerRef.current?.abort();
    }, [showMergeModal]);

    const handleMerge = async () => {
        const isListMode = viewMode === 'LIST';
        const targetId = isListMode ? selectedMergeSource : activeInventaire?.id;

        if (!targetId) return;

        // Confirmation is currently mocked, ideally use useConfirm from hook
        const confirmed = window.confirm(
            isListMode
                ? t('inventaire.modals.merge_warning_list_plain', { defaultValue: 'Les inventaires s├®lectionn├®s seront fusionn├®s DANS l\'inventaire cible. ├ètes-vous s├╗r ?' })
                : t('inventaire.merge.confirm_msg', { defaultValue: 'L\'inventaire source sera fusionn├® dans l\'inventaire actuel. Confirmer ?' })
        );
        if (!confirmed) return;

        setMerging(true);
        try {
            if (isListMode) {
                // List Mode: Merge multiple sources into selected target
                const sources = Array.from(selectedInventaireIds).filter(id => id !== targetId);
                let successCount = 0;

                for (const sourceId of sources) {
                    await api.post(`inventaires/${targetId}/merge/`, {
                        source_inventaire_id: sourceId
                    });
                    successCount++;
                }

                toast.success(t('inventaire.merge.success_count', { count: successCount }));
                setSelectedInventaireIds(new Set());
                fetchInventaires();
            } else {
                // Detail Mode: Merge single external source into active inventory
                await api.post(`inventaires/${activeInventaire?.id}/merge/`, {
                    source_inventaire_id: selectedMergeSource
                });
                toast.success(t('inventaire.merge.success'));
                if (activeInventaire) handleEdit(activeInventaire);
            }

            setShowMergeModal(false);
            setSelectedMergeSource(null);
        } catch (err: unknown) {
            console.error("Erreur fusion", err);
            toast.error(getApiErrorDetail(err, t('inventaire.merge.error', { defaultValue: 'Erreur lors de la fusion' })));
        } finally {
            setMerging(false);
        }
    };

    return {
        showMergeModal, setShowMergeModal,
        mergeCandidates,
        loadingMergeCandidates,
        selectedMergeSource, setSelectedMergeSource,
        merging,
        canMergeSelectedInventaires,
        handleMerge
    };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import api from '../services/api';
import { toast } from 'react-hot-toast';
import { useTranslation } from 'react-i18next';
import type { StockAdjustment, PaginatedResponse, StockAdjustmentStats } from '../types';
import { toApiDateEnd } from '../utils/dateUtils';

export const useAjustementsData = () => {
    const { t } = useTranslation(['common']);
    const [adjustments, setAdjustments] = useState<StockAdjustment[]>([]);
    const [loading, setLoading] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterReasonType, setFilterReasonType] = useState('');
    const [dateStart, setDateStart] = useState('');
    const [dateEnd, setDateEnd] = useState('');

    // Pagination State
    const [currentPage, setCurrentPage] = useState(1);
    const [totalPages, setTotalPages] = useState(1);
    const [totalCount, setTotalCount] = useState(0);

    // Stats State
    const [stats, setStats] = useState({
        total_count: 0,
        positive_sum: 0,
        negative_sum: 0
    });

    const controllerRef = useRef<AbortController | null>(null);

    const fetchAdjustments = useCallback(async (page = 1) => {
        controllerRef.current?.abort();
        const controller = new AbortController();
        controllerRef.current = controller;

        setLoading(true);
        try {
            const params: Record<string, string | number> = {
                page: page,
                page_size: 20
            };

            if (searchQuery) params.search = searchQuery;
            if (filterReasonType) params.reason_type = filterReasonType;
            if (dateStart) params.created_at__gte = dateStart;
            if (dateEnd) params.created_at__lte = toApiDateEnd(new Date(dateEnd + 'T00:00:00'));

            // 1. Fetch List
            const response = await api.get<PaginatedResponse<StockAdjustment> | StockAdjustment[]>('stock-adjustments/', { params, signal: controller.signal });

            if (response.data && 'results' in response.data && Array.isArray(response.data.results)) {
                setAdjustments(response.data.results);
                setTotalCount(response.data.count);
                setTotalPages(Math.ceil(response.data.count / 20));
            } else {
                const data = response.data as StockAdjustment[];
                setAdjustments(Array.isArray(data) ? data : []);
                setTotalCount(Array.isArray(data) ? data.length : 0);
                setTotalPages(1);
            }
            setCurrentPage(page);

            // 2. Fetch Stats
            const statsParams = { ...params };
            delete statsParams.page;
            delete statsParams.page_size;

            const statsResponse = await api.get<StockAdjustmentStats>('stock-adjustments/stats/', { params: statsParams, signal: controller.signal });
            if (statsResponse.data) {
                setStats(statsResponse.data);
            }

        } catch (err) {
            if (err instanceof Error && err.name === 'AbortError') return;
            toast.error(t('common:messages.error_loading'));
            console.error(err);
        } finally {
            setLoading(false);
        }
    }, [searchQuery, filterReasonType, dateStart, dateEnd]);

    useEffect(() => {
        const timer = setTimeout(() => {
            fetchAdjustments(1);
        }, 500);
        return () => { clearTimeout(timer); controllerRef.current?.abort(); };
    }, [fetchAdjustments]);

    const handleExportExcel = useCallback(async () => {
        try {
            const params: Record<string, string> = {};
            if (searchQuery) params.search = searchQuery;
            if (filterReasonType) params.reason_type = filterReasonType;
            if (dateStart) params.created_at__gte = dateStart;
            if (dateEnd) params.created_at__lte = toApiDateEnd(new Date(dateEnd + 'T00:00:00'));

            const response = await api.get('stock-adjustments/export_excel/', {
                params,
                responseType: 'blob'
            });

            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
            link.setAttribute('download', `ajustements_stock_${timestamp}.xlsx`);
            document.body.appendChild(link);
            link.click();
            link.remove();
            window.URL.revokeObjectURL(url);

            toast.success(t('common:messages.export_success'));
        } catch (err) {
            toast.error(t('common:messages.export_error'));
            console.error(err);
        }
    }, [searchQuery, filterReasonType, dateStart, dateEnd]);

    return {
        adjustments,
        loading,
        totalCount,
        totalPages,
        currentPage,
        stats,
        filters: {
            searchQuery,
            filterReasonType,
            dateStart,
            dateEnd
        },
        setFilters: {
            setSearchQuery,
            setFilterReasonType,
            setDateStart,
            setDateEnd
        },
        pagination: {
            setCurrentPage: fetchAdjustments
        },
        actions: {
            fetchAdjustments,
            handleExportExcel
        }
    };
};

import { useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'react-hot-toast';
import { useDebounce } from 'use-debounce';
import { useLocation } from 'react-router-dom';
import type { Fournisseur, ProduitModel, Avoir, LigneAvoir, StockLot, SudoState, SudoOptions, PaginatedResponse } from '../types';
import { useSudo } from './useSudo';
import avoirService from '../services/avoirService';
import fournisseurService from '../services/fournisseurService';
import produitService from '../services/produitService';
import { useAvoirsStore, type ViewMode } from '../stores/useAvoirsStore';

export interface UseAvoirsDataReturn {
    // Navigation State
    viewMode: ViewMode;
    setViewMode: (value: ViewMode) => void;

    // Data State
    avoirs: Avoir[];
    loading: boolean;
    selectedAvoir: Avoir | null;
    setSelectedAvoir: React.Dispatch<React.SetStateAction<Avoir | null>>;

    // Search State (List View)
    listSearchQuery: string;
    setListSearchQuery: (value: string) => void;

    // Sudo State
    sudoState: SudoState;
    requireSudo: (onSuccess: (validatorId: number, password: string) => void | Promise<void>, options?: SudoOptions) => void;
    closeSudo: () => void;
    savingValidation: boolean;

    // Form State (Create/Edit View)
    editingAvoirId: number | null;
    selectedFournisseurId: string;
    setSelectedFournisseurId: (value: string) => void;
    typeAvoir: string;
    setTypeAvoir: (value: string) => void;
    observations: string;
    setObservations: (value: string) => void;
    lignes: LigneAvoir[];
    setLignes: React.Dispatch<React.SetStateAction<LigneAvoir[]>>;

    // Fournisseur Search State
    fournisseurSearch: string;
    setFournisseurSearch: (value: string) => void;
    filteredFournisseurs: Fournisseur[];
    isSearchingFournisseur: boolean;
    showFournisseurList: boolean;
    setShowFournisseurList: (value: boolean) => void;
    selectFournisseur: (f: Fournisseur) => void;

    // Actions
    fetchAvoirs: (search?: string) => Promise<void>;
    handleCreateNew: () => void;
    handleEdit: (avoir: Avoir) => void;
    handleBackToList: () => void;
    handleSave: (e: React.FormEvent) => Promise<void>;
    handleDelete: (avoir: Avoir) => Promise<void>;
    handleValidate: (avoir: Avoir) => Promise<void>;
    handleToggleCloture: (ligneId: number, currentStatus: boolean | undefined) => Promise<void>;
    handleToggleAllCloture: () => Promise<void>;
    handleDechargerStock: (avoir: Avoir) => Promise<void>;

    // Products & Lots Management (Form View)
    selectProduct: (product: ProduitModel) => void;
    updateLine: (index: number, field: keyof LigneAvoir, value: string | number | boolean | ProduitModel | undefined) => void;
    removeLine: (index: number) => void;

    // Lot Modal Specific
    lotModal: { open: boolean; lineIndex: number | null; produitId: number | null };
    setLotModal: React.Dispatch<React.SetStateAction<{ open: boolean; lineIndex: number | null; produitId: number | null }>>;
    availableLots: StockLot[];
    loadingLots: boolean;
    handleOpenLotModal: (lineIndex: number) => Promise<void>;
    handleSelectLot: (lot: StockLot) => void;

    // Selection & Bulk Actions
    selectedIds: Set<number>;
    onToggleSelection: (id: number) => void;
    onToggleSelectAll: () => void;
    onClearSelection: () => void;
    handleBulkDelete: () => Promise<void>;
    handleBulkValidate: () => Promise<void>;
    bulkLoading: boolean;
}

export function useAvoirsData(): UseAvoirsDataReturn {
    const { t } = useTranslation(['stock', 'common']);
    const location = useLocation();

    const viewMode = useAvoirsStore((s) => s.viewMode);
    const setViewMode = useAvoirsStore((s) => s.setViewMode);
    const avoirs = useAvoirsStore((s) => s.avoirs);
    const setAvoirs = useAvoirsStore((s) => s.setAvoirs);
    const loading = useAvoirsStore((s) => s.loading);
    const setLoading = useAvoirsStore((s) => s.setLoading);
    const selectedAvoir = useAvoirsStore((s) => s.selectedAvoir);
    const setSelectedAvoir = useAvoirsStore((s) => s.setSelectedAvoir);
    const listSearchQuery = useAvoirsStore((s) => s.listSearchQuery);
    const setListSearchQuery = useAvoirsStore((s) => s.setListSearchQuery);
    const [debouncedListSearch] = useDebounce(listSearchQuery, 500);

    const editingAvoirId = useAvoirsStore((s) => s.editingAvoirId);
    const setEditingAvoirId = useAvoirsStore((s) => s.setEditingAvoirId);
    const selectedFournisseurId = useAvoirsStore((s) => s.selectedFournisseurId);
    const setSelectedFournisseurId = useAvoirsStore((s) => s.setSelectedFournisseurId);
    const typeAvoir = useAvoirsStore((s) => s.typeAvoir);
    const setTypeAvoir = useAvoirsStore((s) => s.setTypeAvoir);
    const observations = useAvoirsStore((s) => s.observations);
    const setObservations = useAvoirsStore((s) => s.setObservations);
    const lignes = useAvoirsStore((s) => s.lignes);
    const setLignes = useAvoirsStore((s) => s.setLignes);

    const fournisseurSearch = useAvoirsStore((s) => s.fournisseurSearch);
    const setFournisseurSearch = useAvoirsStore((s) => s.setFournisseurSearch);
    const [debouncedFournisseurSearch] = useDebounce(fournisseurSearch, 300);
    const filteredFournisseurs = useAvoirsStore((s) => s.filteredFournisseurs);
    const setFilteredFournisseurs = useAvoirsStore((s) => s.setFilteredFournisseurs);
    const isSearchingFournisseur = useAvoirsStore((s) => s.isSearchingFournisseur);
    const setIsSearchingFournisseur = useAvoirsStore((s) => s.setIsSearchingFournisseur);
    const showFournisseurList = useAvoirsStore((s) => s.showFournisseurList);
    const setShowFournisseurList = useAvoirsStore((s) => s.setShowFournisseurList);

    const lotModal = useAvoirsStore((s) => s.lotModal);
    const setLotModal = useAvoirsStore((s) => s.setLotModal);
    const availableLots = useAvoirsStore((s) => s.availableLots);
    const setAvailableLots = useAvoirsStore((s) => s.setAvailableLots);
    const loadingLots = useAvoirsStore((s) => s.loadingLots);
    const setLoadingLots = useAvoirsStore((s) => s.setLoadingLots);

    // Sudo State
    const { sudoState, requireSudo, closeSudo } = useSudo();
    const savingValidation = useAvoirsStore((s) => s.savingValidation);
    const setSavingValidation = useAvoirsStore((s) => s.setSavingValidation);
    const selectedIds = useAvoirsStore((s) => s.selectedIds);
    const setSelectedIds = useAvoirsStore((s) => s.setSelectedIds);
    const bulkLoading = useAvoirsStore((s) => s.bulkLoading);
    const setBulkLoading = useAvoirsStore((s) => s.setBulkLoading);

    // --- Fetch Avoirs ---
    const fetchAvoirs = useCallback(async (search = '') => {
        setLoading(true);
        try {
            const results = await avoirService.getAll(search);
            setAvoirs(results);
            setSelectedIds(new Set());
        } catch (err: unknown) {
            console.error('Error fetching avoirs:', err);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchAvoirs(debouncedListSearch);
    }, [fetchAvoirs, debouncedListSearch]);

    // --- Supplier Search ---
    useEffect(() => {
        if (!fournisseurSearch && viewMode !== 'CREATE') return;

        const searchFournisseurs = async () => {
            setIsSearchingFournisseur(true);
            try {
                const data = await fournisseurService.getAll({ search: debouncedFournisseurSearch });
                setFilteredFournisseurs(Array.isArray(data) ? data : (data as PaginatedResponse<Fournisseur>).results || []);
            } catch (error) {
                console.error("Erreur recherche fournisseur", error);
            } finally {
                setIsSearchingFournisseur(false);
            }
        };

        searchFournisseurs();
    }, [debouncedFournisseurSearch, viewMode]);

    const selectFournisseur = (f: Fournisseur) => {
        setSelectedFournisseurId(f.id.toString());
        setFournisseurSearch(f.name);
        setShowFournisseurList(false);
    };

    // --- Handlers ---
    const handleCreateNew = () => {
        setViewMode('CREATE');
        setSelectedAvoir(null);
        setEditingAvoirId(null);
        setSelectedFournisseurId('');
        setFournisseurSearch('');
        setTypeAvoir('PERIME');
        setObservations('');
        setLignes([]);
    };

    // --- Direct Navigation Setup (From Commandes) ---
    useEffect(() => {
        interface CommandeSource {
            createFromCommande?: {
                fournisseur?: number;
                fournisseur_nom?: string;
                source_commande?: number;
                produits?: Array<{
                    id: number;
                    name: string;
                    cip: string;
                    quantity: number;
                    purchase_price: string;
                    lot: string;
                    expiration: string;
                }>;
            };
        }
        const state = location.state as CommandeSource;
        if (state && state.createFromCommande) {
            const data = state.createFromCommande;

            setViewMode('CREATE');
            setSelectedAvoir(null);
            setEditingAvoirId(null);
            setLignes([]);

            if (data.fournisseur) {
                setSelectedFournisseurId(String(data.fournisseur));
                setFournisseurSearch(data.fournisseur_nom || '');
            }

            setTypeAvoir('PERIME');
            setObservations(`Retour suite ├á commande #${data.source_commande}`);

            if (Array.isArray(data.produits)) {
                const newLignes: LigneAvoir[] = data.produits.map((p, idx: number) => ({
                    id: Date.now() + idx,
                    avoir: 0,
                    produit: { id: p.id, name: p.name, cip1: p.cip, stock: 0 } as ProduitModel,
                    quantity: p.quantity || 0,
                    price: p.purchase_price || '0',
                    lot: p.lot || '',
                    date_expiration: p.expiration || '',
                    total: '0'
                }));
                setLignes(newLignes);
            }

            window.history.replaceState({}, document.title);
        }
    }, []);

    const handleEdit = (avoir: Avoir) => {
        setEditingAvoirId(avoir.id);
        setSelectedAvoir(avoir);
        setSelectedFournisseurId(avoir.fournisseur.toString());
        setFournisseurSearch(avoir.fournisseur_name || '');
        setTypeAvoir(avoir.type_avoir);
        setObservations(avoir.observations || '');

        const existingLignes: LigneAvoir[] = (avoir.produits || []).map(p => ({
            id: p.id,
            avoir: avoir.id,
            produit: {
                id: p.produit,
                name: p.produit_nom,
                cip1: p.produit_cip || '',
                stock: 0,
                selling_price: p.price,
                cost_price: p.price
            } as ProduitModel,
            quantity: p.quantity,
            price: p.price,
            lot: p.lot || '',
            stock_lot: p.stock_lot || undefined,
            date_expiration: p.date_expiration || '',
            motif: p.motif || '',
            total: p.total || (Number(p.quantity) * Number(p.price)).toString()
        }));

        setLignes(existingLignes);
        setViewMode('EDIT');
    };

    const handleBackToList = () => {
        if (viewMode === 'DETAILS') {
            setViewMode('LIST');
            setSelectedAvoir(null);
            return;
        }

        if (confirm(t('avoirs.confirms.back_to_list'))) {
            setViewMode('LIST');
            setSelectedAvoir(null);
        }
    };

    const handleSave = async (e: React.FormEvent): Promise<void> => {
        e.preventDefault();
        if (!selectedFournisseurId) {
            toast(t('avoirs.toasts.select_supplier'), { icon: 'ÔÜá´©Å' });
            return;
        }
        if (lignes.length === 0) {
            toast(t('avoirs.toasts.add_product'), { icon: 'ÔÜá´©Å' });
            return;
        }

        try {
            setLoading(true);
            const avoirPayload = {
                fournisseur: parseInt(selectedFournisseurId),
                type_avoir: typeAvoir as Avoir['type_avoir'],
                observations
            };

            let avoirId: number;

            if (editingAvoirId) {
                await avoirService.update(editingAvoirId, avoirPayload);
                avoirId = editingAvoirId;
                const existingLignes = selectedAvoir?.produits || [];
                await Promise.all(
                    existingLignes.map(l => avoirService.deleteLigne(l.id).catch(() => { }))
                );
            } else {
                const newAvoir = await avoirService.create(avoirPayload);
                avoirId = newAvoir.id;
            }

            const linePromises = lignes.map(ligne => {
                const produitId = typeof ligne.produit === 'object' ? ligne.produit.id : ligne.produit;
                return avoirService.createLigne({
                    avoir: avoirId,
                    produit: produitId,
                    stock_lot: ligne.stock_lot || null,
                    quantity: ligne.quantity,
                    price: ligne.price,
                    lot: ligne.lot,
                    date_expiration: ligne.date_expiration || undefined,
                    motif: ligne.motif || ''
                });
            });

            await Promise.all(linePromises);
            toast.success(editingAvoirId ? 'Avoir modifi├® avec succ├¿s' : 'Avoir cr├®├® avec succ├¿s (Brouillon)');
            setEditingAvoirId(null);
            setViewMode('LIST');
            fetchAvoirs();
        } catch (err: unknown) {
            const error = err as { response?: { data?: { message?: string } }; message?: string };
            toast.error(t('avoirs.toasts.save_error') + ': ' + (error.response?.data?.message || error.message));
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (avoir: Avoir) => {
        if (!confirm(t('avoirs.confirms.delete_avoir', { numero: avoir.numero }))) return;
        try {
            setLoading(true);
            await avoirService.delete(avoir.id);
            toast.success(t('avoirs.toasts.delete_success'));
            setAvoirs(avoirs.filter(a => a.id !== avoir.id));
            if (viewMode === 'DETAILS') setViewMode('LIST');
        } catch (err: unknown) {
            const error = err as { response?: { data?: { error?: string } }; message?: string };
            toast.error(t('avoirs.toasts.delete_error') + ': ' + (error.response?.data?.error || error.message));
        } finally {
            setLoading(false);
        }
    };

    const handleValidate = async (avoir: Avoir) => {
        if (!confirm(`Valider l'avoir ${avoir.numero} ? Le statut passera ├á "Valid├®".`)) return;
        try {
            setSavingValidation(true);
            const updated = await avoirService.valider(avoir.id);
            toast.success(t('avoirs.toasts.validate_success'));
            setAvoirs(avoirs.map(a => a.id === avoir.id ? updated : a));
            if (viewMode === 'DETAILS') setSelectedAvoir(updated);
        } catch (err: unknown) {
            const error = err as { response?: { data?: { error?: string } }; message?: string };
            toast.error(t('avoirs.toasts.validate_error') + ': ' + (error.response?.data?.error || error.message || 'Erreur inconnue'));
        } finally {
            setSavingValidation(false);
        }
    };

    const handleDechargerStock = async (avoir: Avoir) => {
        requireSudo(async (validatorId, password) => {
            try {
                setLoading(true);
                const updated = await avoirService.dechargerStock(avoir.id, {
                    validated_by_id: validatorId,
                    password: password
                });
                toast.success('Stock d├®charg├® avec succ├¿s. Les mouvements ont ├®t├® enregistr├®s.');
                setAvoirs(avoirs.map(a => a.id === avoir.id ? updated : a));
                setSelectedAvoir(updated);
            } catch (err: unknown) {
                const error = err as { response?: { data?: { error?: string } }; message?: string };
                toast.error('Erreur : ' + (error.response?.data?.error || error.message || 'Erreur inconnue'));
                throw err;
            } finally {
                setLoading(false);
            }
        }, {
            title: `D├®charger stock ÔÇö ${avoir.numero}`,
            message: `Cette action va retirer physiquement ${avoir.produits?.length || 0} produit(s) du stock et enregistrer les mouvements. Action irr├®versible.`
        });
    };

    const handleToggleCloture = async (ligneId: number, currentStatus: boolean | undefined) => {
        const newStatus = !currentStatus;
        const currentAvoirId = selectedAvoir?.id;

        const updateState = (status: boolean) => {
            setSelectedAvoir(prev => {
                if (!prev) return null;
                return {
                    ...prev,
                    produits: prev.produits?.map(p => p.id === ligneId ? { ...p, est_cloture: status } : p) || []
                };
            });
            if (currentAvoirId !== undefined) {
                setAvoirs(prev => prev.map(a => {
                    if (a.id === currentAvoirId) {
                        return {
                            ...a,
                            produits: a.produits?.map(p => p.id === ligneId ? { ...p, est_cloture: status } : p)
                        };
                    }
                    return a;
                }));
            }
        };

        updateState(newStatus);
        try {
            await avoirService.updateLigne(ligneId, { est_cloture: newStatus });
            toast.success(newStatus ? t('avoirs.toasts.line_closed') : t('avoirs.toasts.line_reopened'));
        } catch {
            toast.error(t('avoirs.toasts.update_line_error'));
            updateState(!newStatus);
        }
    };

    const handleToggleAllCloture = async () => {
        if (!selectedAvoir || !selectedAvoir.produits) return;
        const allClosed = selectedAvoir.produits.every(p => p.est_cloture);
        const targetStatus = !allClosed;
        const currentAvoirId = selectedAvoir.id;

        // Optimistic Update
        const originalProduits = [...selectedAvoir.produits];
        const updateState = (status: boolean) => {
            setSelectedAvoir(prev => {
                if (!prev) return null;
                return {
                    ...prev,
                    produits: prev.produits?.map(p => ({ ...p, est_cloture: status })) || []
                };
            });
            setAvoirs(prev => prev.map(a => {
                if (a.id === currentAvoirId) {
                    return {
                        ...a,
                        produits: a.produits?.map(p => ({ ...p, est_cloture: status }))
                    };
                }
                return a;
            }));
        };

        updateState(targetStatus);

        try {
            const promises = selectedAvoir.produits
                .filter(p => !!p.id)
                .map(p => avoirService.updateLigne(p.id, { est_cloture: targetStatus }));
            await Promise.all(promises);
            toast.success(targetStatus ? t('avoirs.toasts.bulk_lines_closed') : t('avoirs.toasts.bulk_lines_reopened'));
        } catch {
            toast.error(t('avoirs.toasts.bulk_update_error'));
            // Rollback
            setSelectedAvoir(prev => prev ? { ...prev, produits: originalProduits } : null);
        }
    };

    // --- Line Building functions ---
    const selectProduct = (product: ProduitModel) => {
        const existing = lignes.find(l => (typeof l.produit === 'object' ? l.produit.id : l.produit) === product.id);
        if (existing) {
            toast.error(t('avoirs.toasts.product_exists'));
            return;
        }
        const newLine: LigneAvoir = {
            id: Date.now(),
            avoir: 0,
            produit: product,
            quantity: 1,
            price: product.cost_price || '0',
            lot: '',
            date_expiration: '',
            total: product.cost_price || '0'
        };
        setLignes(prev => [newLine, ...prev]);
    };

    const updateLine = (index: number, field: keyof LigneAvoir, value: string | number | boolean | ProduitModel | undefined) => {
        setLignes(prev => {
            const newLignes = [...prev];
            const line = { ...newLignes[index] };
            // @ts-ignore
            line[field] = value;
            if (field === 'quantity' || field === 'price') {
                const qty = field === 'quantity' ? Number(value) : Number(line.quantity);
                const price = field === 'price' ? Number(value) : Number(line.price);
                line.total = (qty * price).toString();
            }
            newLignes[index] = line;
            return newLignes;
        });
    };

    const removeLine = (index: number) => {
        setLignes(prev => prev.filter((_, i) => i !== index));
    };

    // --- Lots Modal Functions ---
    const handleOpenLotModal = async (lineIndex: number) => {
        const line = lignes[lineIndex];
        if (!line) return;
        const produitId = typeof line.produit === 'object' ? line.produit.id : line.produit;

        setLotModal({ open: true, lineIndex, produitId });
        setLoadingLots(true);

        try {
            const lots = await produitService.getLots(produitId);
            setAvailableLots(lots.filter((l: StockLot) => l.quantity_remaining > 0));
        } catch {
            toast.error(t('avoirs.toasts.load_lots_error'));
        } finally {
            setLoadingLots(false);
        }
    };

    const handleSelectLot = (lot: StockLot) => {
        if (lotModal.lineIndex === null) return;
        setLignes(prev => {
            const newLignes = [...prev];
            const line = { ...newLignes[lotModal.lineIndex!] };

            line.stock_lot = lot.id;
            line.lot = lot.lot || '';
            line.date_expiration = lot.date_expiration || '';
            line.price = lot.price_cost?.toString() || line.price;
            line.total = (Number(line.quantity) * Number(line.price)).toString();

            newLignes[lotModal.lineIndex!] = line;
            return newLignes;
        });
        setLotModal({ open: false, lineIndex: null, produitId: null });
    };

    // --- Bulk Handlers ---
    const onToggleSelection = (id: number) => {
        setSelectedIds(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    const onToggleSelectAll = () => {
        const draftIds = avoirs.filter(a => a.status === 'BROUILLON').map(a => a.id);
        if (selectedIds.size === draftIds.length && draftIds.length > 0) {
            setSelectedIds(new Set());
        } else {
            setSelectedIds(new Set(draftIds));
        }
    };

    const onClearSelection = () => setSelectedIds(new Set());

    const handleBulkDelete = async () => {
        const count = selectedIds.size;
        if (count === 0) return;
        if (!confirm(t('avoirs.confirms.bulk_delete', { count }))) return;

        setBulkLoading(true);
        try {
            const idsToDelete = Array.from(selectedIds);
            await Promise.all(idsToDelete.map(id => avoirService.delete(id)));
            toast.success(t('avoirs.toasts.bulk_delete_success', { count }));
            setAvoirs(avoirs.filter(a => !selectedIds.has(a.id)));
            setSelectedIds(new Set());
        } catch {
            toast.error(t('avoirs.toasts.bulk_delete_error'));
        } finally {
            setBulkLoading(false);
        }
    };

    const handleBulkValidate = async () => {
        const count = selectedIds.size;
        if (count === 0) return;
        if (!confirm(`Valider ${count} avoir(s) s├®lectionn├®(s) ?`)) return;

        setBulkLoading(true);
        try {
            await Promise.all(Array.from(selectedIds).map(id => avoirService.valider(id)));
            toast.success(t('avoirs.toasts.bulk_validate_success', { count }));
            setSelectedIds(new Set());
            fetchAvoirs();
        } catch {
            toast.error(t('avoirs.toasts.bulk_validate_error'));
        } finally {
            setBulkLoading(false);
        }
    };

    return {
        viewMode,
        setViewMode,
        avoirs,
        loading,
        selectedAvoir,
        setSelectedAvoir,
        listSearchQuery,
        setListSearchQuery,
        sudoState,
        requireSudo,
        closeSudo,
        savingValidation,
        editingAvoirId,
        selectedFournisseurId,
        setSelectedFournisseurId,
        typeAvoir,
        setTypeAvoir,
        observations,
        setObservations,
        lignes,
        setLignes,
        fournisseurSearch,
        setFournisseurSearch,
        filteredFournisseurs,
        isSearchingFournisseur,
        showFournisseurList,
        setShowFournisseurList,
        selectFournisseur,
        fetchAvoirs,
        handleCreateNew,
        handleEdit,
        handleBackToList,
        handleSave,
        handleDelete,
        handleValidate,
        handleToggleCloture,
        handleToggleAllCloture,
        handleDechargerStock,
        selectProduct,
        updateLine,
        removeLine,
        lotModal,
        setLotModal,
        availableLots,
        loadingLots,
        handleOpenLotModal,
        handleSelectLot,
        selectedIds,
        onToggleSelection,
        onToggleSelectAll,
        onClearSelection,
        handleBulkDelete,
        handleBulkValidate,
        bulkLoading
    };
}

import { useState, useCallback } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { toast } from 'react-hot-toast'
import api from '../services/api'
import type { Facture, TicketCaisse, CouponMonnaie } from '../types'
import { getApiErrorDetail } from '../utils/errorHandling'

interface PaymentState {
  selectedFacture: Facture | null
  couponsParFacture: Record<number, CouponMonnaie>
  setCouponsParFacture: React.Dispatch<React.SetStateAction<Record<number, CouponMonnaie>>>
  setTicketCaisse: (ticket: TicketCaisse | null) => void
  setIsPaymentModalOpen: (isOpen: boolean) => void
  setShowTicketPreview: (show: boolean) => void
  fetchFacturesEnAttente: () => Promise<void>
  fetchSessionRecap: () => Promise<void>
  fetchCoupons: () => Promise<void>
  utiliserCouponApresEncaissement: (couponId: number, factureId: number) => Promise<void>
  onSuccess?: () => void
}

const processCouponPayment = async (factureId: number, coupon: CouponMonnaie): Promise<void> => {
  const couponPayload = {
    facture: factureId,
    mode_paiement: 'coupon',
    montant: coupon.montant,
    reference: `COUPON-${coupon.numero}`,
    statut: 'completee',
  }
  await api.post('caisse/', couponPayload)
}

const processRegularPayments = async (
  factureId: number,
  paiements: { mode: string; montant: number }[],
  montantAEncaisser: number,
  hasTiersPayant: boolean
): Promise<void> => {
  let resteAEnregistrer = montantAEncaisser

  for (const paiement of paiements) {
    if (resteAEnregistrer <= 0) break

    const montantReel = Math.min(paiement.montant, resteAEnregistrer)

    const paiementPayload: unknown = {
      facture: factureId,
      mode_paiement: paiement.mode,
      montant: montantReel,
      reference: null,
      statut: 'completee',
    }

    if (hasTiersPayant) {
      paiementPayload.part_patient = montantReel
      paiementPayload.part_assurance = 0
    }

    await api.post('caisse/', paiementPayload)
    resteAEnregistrer -= montantReel
  }
}

const createTicketData = (
  facture: Facture,
  paiements: { mode: string; montant: number }[],
  montantTotal: number,
  montantAEncaisser: number,
  user: unknown
): TicketCaisse => {
  const rendu = montantTotal - montantAEncaisser
  const clientName = facture.client_name_override || facture.client_name || 'Client de passage'

  return {
    id: facture.id,
    facture: facture as unknown,
    mode_paiement: paiements.length > 1 ? 'Mixte' : (paiements[0]?.mode || 'especes'),
    montant: facture.total_ttc,
    montant_verse: (facture.montant_verse ? Number(facture.montant_verse) : montantTotal).toString(),
    rendu: (facture.montant_rendu ? Number(facture.montant_rendu) : rendu).toString(),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    statut: 'completee',
    date_paiement: new Date().toISOString(),
    client_name: clientName,
    paiements_details: (facture as unknown).paiements || [],
    user_details: user,
    reference: null
  } as TicketCaisse
}

export const useCaissePayment = ({
  selectedFacture,
  couponsParFacture,
  setCouponsParFacture,
  setTicketCaisse,
  setIsPaymentModalOpen,
  setShowTicketPreview,
  fetchFacturesEnAttente,
  fetchSessionRecap,
  fetchCoupons,
  utiliserCouponApresEncaissement,
  onSuccess
}: PaymentState) => {
  const queryClient = useQueryClient()
  const [loading, setLoading] = useState(false)

  const enregistrerPaiement = useCallback(async (
    paiementsValides: { mode: string; montant: number }[],
    t: (key: string, options?: unknown) => string,
    user: unknown,
    successMessage: string = 'Paiement enregistr├®'
  ) => {
    if (!selectedFacture) return

    const montantTotal = paiementsValides.reduce((acc, p) => acc + p.montant, 0)

    if (montantTotal === 0) {
      toast.error(t('messages.invalid_amount'))
      return
    }

    setLoading(true)

    try {
      // 1. Valider la facture si n├®cessaire
      let factureValidee = selectedFacture
      if (selectedFacture.status !== 'VAL' && selectedFacture.status !== 'VALIDEE') {
        const { data } = await api.post<Facture>(`factures/${selectedFacture.id}/valider/`, {})
        factureValidee = data
      }

      // 2. Calculer le montant ├á encaisser
      const montantAEncaisser = factureValidee.reste_a_payer !== undefined && factureValidee.reste_a_payer !== null
        ? Number(factureValidee.reste_a_payer)
        : (factureValidee.part_client !== null && Number(factureValidee.part_client) >= 0
            ? Number(factureValidee.part_client)
            : Number(factureValidee.total_ttc))

      // 3. Traiter le coupon si pr├®sent
      const couponUtilise = couponsParFacture[factureValidee.id]
      if (couponUtilise) {
        await processCouponPayment(factureValidee.id, couponUtilise)
      }

      // 4. Traiter les paiements r├®guliers
      const hasTiersPayant = factureValidee.part_client !== null && Number(factureValidee.part_client) >= 0
      await processRegularPayments(factureValidee.id, paiementsValides, montantAEncaisser, hasTiersPayant)

      // 5. Mettre ├á jour le statut et stocker les infos ticket
      await api.patch(`factures/${factureValidee.id}/`, {
          status: 'PAY',
          montant_verse: montantTotal.toString(),
          montant_rendu: (montantTotal - montantAEncaisser).toString(),
      });

      // 6. R├®cup├®rer la facture finale
      const { data: factureFinale } = await api.get<Facture>(`factures/${factureValidee.id}/`)

      // 7. Cr├®er le ticket
      const ticketData = createTicketData(factureFinale, paiementsValides, montantTotal, montantAEncaisser, user)
      setTicketCaisse(ticketData)

      // 8. Fermer modale et afficher ticket
      setIsPaymentModalOpen(false)
      setShowTicketPreview(true)

      // 9. Rafra├«chir les donn├®es
      await fetchFacturesEnAttente()
      fetchSessionRecap()
      queryClient.invalidateQueries({ queryKey: ['products'] })

      // 10. Marquer le coupon comme utilis├®
      if (couponUtilise) {
        await utiliserCouponApresEncaissement(couponUtilise.id, factureFinale.id)
        setCouponsParFacture(prev => {
          const updated = { ...prev }
          delete updated[factureFinale.id]
          return updated
        })
      }

      toast.success(successMessage)
      onSuccess?.()
    } catch (err) {
      console.error('Erreur lors du paiement:', err)
      toast.error(getApiErrorDetail(err, t('messages.save_payment_error')))
    } finally {
      setLoading(false)
    }
  }, [
    selectedFacture,
    couponsParFacture,
    setTicketCaisse,
    setIsPaymentModalOpen,
    setShowTicketPreview,
    fetchFacturesEnAttente,
    fetchSessionRecap,
    fetchCoupons,
    utiliserCouponApresEncaissement,
    setCouponsParFacture,
    onSuccess,
    queryClient
  ])

  return {
    loading,
    enregistrerPaiement
  }
}

import { useState, useCallback, useMemo, useEffect, useRef } from 'react'
import api from '../services/api'
import { toast } from 'react-hot-toast'
import type { ProduitModel, LigneFacture, StockLot } from '../types'
import { normalizeNumberInput } from '../utils/formatters'
import { calculateLineTotal, calculateCartStats } from '../utils/finance'
import { useAuth } from '../context/AuthContext'
import { differenceInDays, parseISO } from 'date-fns'
import { showExpirationToast } from '../utils/toastUtils'
import { safeStorage } from '../utils/storage'

interface UseCartOptions {
    apiBaseUrl?: string
    onRequirePrescription?: () => void
    onAlert?: (msg: string, title: string, type: 'product' | 'client', is_blocking: boolean, targetId?: number) => void
    onSubstitution?: (produit: ProduitModel) => void
    onForceStock?: (produit: ProduitModel) => void
    quantityInputsRef?: React.MutableRefObject<Map<number, HTMLInputElement>>
}

export function useCart({ onRequirePrescription, onAlert, onSubstitution, onForceStock, quantityInputsRef }: UseCartOptions = {}) {
    const { user } = useAuth()
    
    // Logic keys (prefixed with user ID for multi-user safety)
    const cartStorageKey = useMemo(() => user?.id ? `activeCartLignes_${user.id}` : null, [user?.id])

    const [lignesFacture, setLignesFacture] = useState<LigneFacture[]>([])
    const [loading, setLoading] = useState(false)
    const hasHydratedRef = useRef(false)

    // 1. Hydrate from localStorage when user becomes available
    useEffect(() => {
        if (cartStorageKey && !hasHydratedRef.current) {
            try {
                const saved = safeStorage.getItem(cartStorageKey, 'local')
                if (saved) {
                    // Use functional update to avoid overwriting data already set by useDevisLoader
                    setLignesFacture(prev => prev.length > 0 ? prev : JSON.parse(saved))
                }
                hasHydratedRef.current = true
            } catch (err) {
                console.error("Failed to hydrate cart:", err)
            }
            
            // Cleanup: remove old global key if it exists
            safeStorage.removeItem('activeCartLignes', 'local')
        }
    }, [cartStorageKey])

    // 2. Persist to localStorage on change (debounced implicitly by render cycle)
    useEffect(() => {
        if (!cartStorageKey || !hasHydratedRef.current) return

        if (lignesFacture.length > 0) {
            safeStorage.setItem(cartStorageKey, JSON.stringify(lignesFacture), 'local')
        } else {
            safeStorage.removeItem(cartStorageKey, 'local')
        }
    }, [lignesFacture, cartStorageKey])

    const addProduit = useCallback(async (produit: ProduitModel, options?: { isRetrocession?: boolean; preventFocus?: boolean; markupPercentage?: number; forceStock?: boolean }) => {
        setLoading(true)
        try {
            const { data: fullProduit } = await api.get<ProduitModel>(`produits/${produit.id}/`)

            // SUBSTITUTION CHECK: if product is out of stock, ask whether to force or substitute
            if (fullProduit.stock <= 0 && !options?.forceStock) {
                setLoading(false)
                if (onForceStock) {
                    onForceStock(fullProduit)
                } else if (onSubstitution) {
                    onSubstitution(fullProduit)
                }
                return
            }

            setLignesFacture(prevLignes => {
                // REDUNDANCY / INTERACTION CHECK
                if (fullProduit.famille_risque) {
                    const conflict = prevLignes.find(l =>
                        l.produit.id !== fullProduit.id && // Don't warn for itself (redundancy of quantity is fine)
                        l.produit.famille_risque === fullProduit.famille_risque
                    )

                    if (conflict) {
                        // Trigger toast outside of render cycle
                        setTimeout(() => {
                            toast.error(
                                `ÔÜá´©Å Interaction / Redondance\n${fullProduit.name} est de la m├¬me famille (${fullProduit.famille_risque_nom}) que ${conflict.produit.name} d├®j├á pr├®sent.`,
                                {
                                    duration: 6000,
                                    position: 'top-center',
                                    style: { border: '2px solid #fbbd23', background: '#fff', color: '#333', maxWidth: '400px' },
                                    icon: 'ÔÜá´©Å'
                                }
                            )
                        }, 100)
                    }
                }

                const existingLigne = prevLignes.find(ligne => ligne.produit.id === fullProduit.id)

                if (existingLigne) {
                    const nouvelleQuantite = existingLigne.quantite + 1
                    return prevLignes.map(ligne =>
                        ligne.produit.id === fullProduit.id
                            ? {
                                ...ligne,
                                produit: fullProduit, // Update product with fresh data (stock, prices, etc.)
                                quantite: nouvelleQuantite,
                                total_ligne: calculateLineTotal(nouvelleQuantite, ligne.prix_unitaire, ligne.remise_produit),
                            }
                            : ligne
                    )
                } else {
                    let basePrice = fullProduit.selling_price ?? '0'

                    if (options?.isRetrocession) {
                        // R├®trocession: Use Last Purchase Price (Best) -> Cost Price (Fallback) -> Selling Price
                        const price = fullProduit.last_purchase_price
                            ? fullProduit.last_purchase_price
                            : fullProduit.cost_price ?? '0'
                        basePrice = price.toString()
                    }

                    let basePriceValue = Number(basePrice)
                    if (options?.markupPercentage && options.markupPercentage > 0) {
                        basePriceValue = basePriceValue * (1 + options.markupPercentage / 100)
                    }

                    const prixUnitaire = normalizeNumberInput(basePriceValue, { min: 0 })
                    const nouvelleLigne: LigneFacture = {
                        produit: fullProduit,
                        quantite: 1,
                        prix_unitaire: prixUnitaire.toString(),
                        remise_produit: '0',
                        total_ligne: prixUnitaire,
                        lotId: null,
                        lotText: null,
                        lotExpiration: null,
                        lotSellingPrice: null,
                        treatment_duration_days: fullProduit.is_chronic ? fullProduit.default_treatment_days : undefined
                    }

                    // Focus logic moved to after ALERT check to avoid stealing focus from the modal.
                    // This prevents typing implicitly behind the modal.
                    
                    return [...prevLignes, nouvelleLigne]
                }
            })

            // ORDONNANCIER CHECK
            const requiresOrdonnance = fullProduit.requires_prescription ||
                (fullProduit.surveillance_category && fullProduit.surveillance_category !== 'NONE')

            if (requiresOrdonnance && onRequirePrescription) {
                onRequirePrescription()
                toast('Produit sous ordonnance/surveillance d├®tect├®', { icon: '­ƒôï' })
            }

            // CHECKOUT ALERT MESSAGE CHECK
            let hasAlert = false;
            if (fullProduit.message_alerte && onAlert) {
                onAlert(fullProduit.message_alerte, fullProduit.name, 'product', !!fullProduit.blocking_alerte, fullProduit.id)
                hasAlert = true;
            }

            // Focus logic: only focus if there is NO alert. If there is an alert, 
            // the Acknowledge handler of the alert modal will do the focus to avoid stealing 
            // focus while the modal is open.
            if (!options?.preventFocus && !hasAlert) {
                setTimeout(() => {
                    if (quantityInputsRef?.current) {
                        const qtyInput = quantityInputsRef.current.get(fullProduit.id)
                        if (qtyInput) {
                            qtyInput.focus()
                            qtyInput.select()
                        }
                    }
                }, 50)
            }

            // PEREMPTION CHECK
            // Use calculated property from serializer (next_expiring_date) if available, fallback to expire_date
            const expirationToCheck = fullProduit.next_expiring_date || fullProduit.expire_date;





            if (expirationToCheck) {
                const daysUntilExpiration = differenceInDays(parseISO(expirationToCheck), new Date())
                showExpirationToast(daysUntilExpiration)
            }
        } catch (err) {
            console.error('Erreur lors du chargement des d├®tails du produit:', err)
            toast.error('Impossible de charger les d├®tails complets du produit')
        } finally {
            setLoading(false)
        }
    }, [onRequirePrescription, quantityInputsRef])

    const updateQuantite = useCallback((produitId: number, quantite: number, callback?: (err: string) => void) => {
        // Permettre les quantit├®s n├®gatives (retours) et positives (ventes)
        const normalizedQuantite = Math.floor(normalizeNumberInput(quantite))
        const finalQuantite = normalizedQuantite === 0 ? 1 : normalizedQuantite

        // V├®rifier les permissions pour les retours (quantit├® n├®gative)
        if (finalQuantite < 0 && !user?.can_do_returns) {
            const msg = "Vous n'avez pas la permission d'effectuer des retours (quantit├®s n├®gatives)."
            toast.error(msg)
            if (callback) callback(msg)
            return
        }

        setLignesFacture(prevLignes => prevLignes.map(ligne =>
            ligne.produit.id === produitId
                ? {
                    ...ligne,
                    quantite: finalQuantite,
                    total_ligne: calculateLineTotal(finalQuantite, ligne.prix_unitaire, ligne.remise_produit),
                    // Clear promis if stock is sufficient (logic simplified here, mostly clearing old promis state)
                    isPromis: undefined,
                    promisQuantity: undefined,
                    promisPhone: undefined
                }
                : ligne
        ))
    }, [user?.can_do_returns])

    const updatePrix = useCallback((produitId: number, prix: string) => {
        setLignesFacture(prevLignes => prevLignes.map(ligne =>
            ligne.produit.id === produitId
                ? { ...ligne, prix_unitaire: prix, total_ligne: calculateLineTotal(ligne.quantite, prix, ligne.remise_produit) }
                : ligne
        ))
    }, [])

    const updateRemiseProduit = useCallback((produitId: number, remise: string) => {
        setLignesFacture(prevLignes => prevLignes.map(ligne =>
            ligne.produit.id === produitId
                ? { ...ligne, remise_produit: remise, total_ligne: calculateLineTotal(ligne.quantite, ligne.prix_unitaire, remise) }
                : ligne
        ))
    }, [calculateLineTotal])

    const updateLineLot = useCallback((produitId: number, lot: StockLot | null) => {
        setLignesFacture(prevLignes => prevLignes.map(ligne =>
            ligne.produit.id === produitId
                ? {
                    ...ligne,
                    lotId: lot ? String(lot.id) : null,
                    lotText: lot ? lot.lot : null,
                    lotExpiration: lot?.date_expiration || null,
                    lotSellingPrice: lot?.selling_price ?? null,
                    // Update price if lot has a specific selling price
                    prix_unitaire: (lot && lot.selling_price !== null && lot.selling_price !== undefined)
                        ? String(lot.selling_price)
                        : ligne.prix_unitaire,
                    // Recalculate total with new price
                    total_ligne: calculateLineTotal(
                        ligne.quantite,
                        (lot && lot.selling_price !== null && lot.selling_price !== undefined)
                            ? String(lot.selling_price)
                            : ligne.prix_unitaire,
                        ligne.remise_produit
                    )
                }
                : ligne
        ))
    }, [])

    const updateTreatmentDuration = useCallback((produitId: number, duration: number) => {
        setLignesFacture(prevLignes => prevLignes.map(ligne =>
            ligne.produit.id === produitId
                ? { ...ligne, treatment_duration_days: duration }
                : ligne
        ))
    }, [])

    const removeLigne = useCallback((produitId: number) => {
        setLignesFacture(prev => prev.filter(ligne => ligne.produit.id !== produitId))
    }, [])

    const clearCart = useCallback(() => {
        setLignesFacture([])
    }, [])

    const cartStats = useMemo(() => calculateCartStats(lignesFacture), [lignesFacture])

    const bulkAddProduits = useCallback((items: { product: ProduitModel, quantity: number, discountPercent?: string }[]) => {
        setLignesFacture(prevLignes => {
            const newLignes = [...prevLignes]
            items.forEach(({ product, quantity, discountPercent }) => {
                const existingIndex = newLignes.findIndex(l => l.produit.id === product.id)
                const remise = discountPercent || '0'
                const prixBase = product.selling_price || '0'

                if (existingIndex >= 0) {
                    const existing = newLignes[existingIndex]
                    const newQty = existing.quantite + quantity
                    // For bulk add, we might want to override remise if specified, or keep existing.
                    // Usually for a Pack, we want to apply the pack discount.
                    const finalRemise = discountPercent !== undefined ? remise : existing.remise_produit

                    newLignes[existingIndex] = {
                        ...existing,
                        produit: product,
                        quantite: newQty,
                        remise_produit: finalRemise,
                        total_ligne: calculateLineTotal(newQty, existing.prix_unitaire, finalRemise)
                    }
                } else {
                    newLignes.push({
                        produit: product,
                        quantite: quantity,
                        prix_unitaire: prixBase,
                        remise_produit: remise,
                        total_ligne: calculateLineTotal(quantity, prixBase, remise),
                        lotId: null,
                        lotText: null,
                        lotExpiration: null,
                        lotSellingPrice: null,
                        treatment_duration_days: product.is_chronic ? product.default_treatment_days : undefined
                    })
                }
            })
            return newLignes
        })
    }, [])

    const applyMarkupToCart = useCallback((percentage: number) => {
        setLignesFacture(prevLignes => prevLignes.map(ligne => {
            const basePrice = Number(ligne.produit.selling_price || 0)
            const markedUpPrice = basePrice * (1 + percentage / 100)
            const finalPrice = normalizeNumberInput(markedUpPrice, { min: 0 }).toString()
            
            return {
                ...ligne,
                prix_unitaire: finalPrice,
                total_ligne: calculateLineTotal(ligne.quantite, finalPrice, ligne.remise_produit)
            }
        }))
    }, [])

    return {
        lignesFacture,
        setLignesFacture,
        addProduit,
        applyMarkupToCart,
        bulkAddProduits,
        updateQuantite,
        updatePrix,
        updateRemiseProduit,
        updateLineLot,
        updateTreatmentDuration,
        removeLigne,
        clearCart,
        cartStats,
        loading
    }
}

import { useState, useCallback, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';
import api from '../services/api';
import { toast } from 'react-hot-toast';
import { getApiErrorDetail } from '../utils/errorHandling';
import { usePharmacySettings } from './usePharmacySettings';
import { exportToExcel, downloadBlob } from '../utils/excelExport';

// Re-export types and constants from modular files
export type { QueryDefinition, QueryParam, ParamType, PaginationData, Client, Supplier, User, Famille } from './reports/types';
export * from './reports/utils';
export { QUERIES } from './reports/queries';

import { QUERIES } from './reports/queries';
import { 
    formatColumnHeader, 
    isSummableColumn,
    isAverageColumn,
    isPercentageColumn 
} from './reports/utils';
import type { 
    QueryDefinition, 
    PaginationData, 
    Client, 
    Supplier,
    User,
    Famille
} from './reports/types';

export function useCentreRapports() {
    const { t, i18n } = useTranslation(['reports', 'common']);
    const [searchParams] = useSearchParams();
    const { settings: pharmacySettings } = usePharmacySettings();

    const [selectedQuery, setSelectedQuery] = useState<QueryDefinition | null>(null);
    const [params, setParams] = useState<Record<string, string | number | boolean>>({});
    const [results, setResults] = useState<unknown>(null);
    const [pagination, setPagination] = useState<PaginationData | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const [clients, setClients] = useState<Client[]>([]);
    const [clientSearch, setClientSearch] = useState('');
    const [filteredClients, setFilteredClients] = useState<Client[]>([]);
    const [showClientDropdown, setShowClientDropdown] = useState(false);
    const [selectedClientName, setSelectedClientName] = useState('');

    const [suppliers, setSuppliers] = useState<Supplier[]>([]);
    const [supplierSearch, setSupplierSearch] = useState('');
    const [filteredSuppliers, setFilteredSuppliers] = useState<Supplier[]>([]);
    const [showSupplierDropdown, setShowSupplierDropdown] = useState(false);
    const [selectedSupplierName, setSelectedSupplierName] = useState('');

    const [users, setUsers] = useState<User[]>([]);
    const [userSearch, setUserSearch] = useState('');
    const [filteredUsers, setFilteredUsers] = useState<User[]>([]);
    const [showUserDropdown, setShowUserDropdown] = useState(false);
    const [selectedUserName, setSelectedUserName] = useState('');

    const [familles, setFamilles] = useState<Famille[]>([]);
    const [familleSearch, setFamilleSearch] = useState('');
    const [filteredFamilles, setFilteredFamilles] = useState<Famille[]>([]);
    const [showFamilleDropdown, setShowFamilleDropdown] = useState(false);
    const [selectedFamilleName, setSelectedFamilleName] = useState('');

    const [presets, setPresets] = useState<Record<string, unknown>[]>([]);

    const getCurrentMonth = useCallback(() => {
        const now = new Date();
        return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    }, []);

    const getCurrentDateTime = useCallback(() => {
        const now = new Date();
        return now.toISOString().slice(0, 16);
    }, []);

    const getTodayDate = useCallback(() => {
        return new Date().toISOString().slice(0, 10);
    }, []);

    const safeDate = useCallback((dateStr: unknown): Date | null => {
        if (!dateStr || typeof dateStr !== 'string') return null;
        const d = new Date(dateStr);
        return isNaN(d.getTime()) ? null : d;
    }, []);

    const extractPath = useCallback((url: string | null): string | null => {
        if (!url) return null;
        try {
            const parsed = new URL(url);
            return parsed.pathname + parsed.search;
        } catch {
            return url;
        }
    }, []);

    useEffect(() => {
        const controller = new AbortController();
        const signal = controller.signal;

        const loadClients = async () => {
            try {
                const { data } = await api.get('clients/', { signal });
                const clientList = data.results || data;
                setClients(clientList);
            } catch (err) {
                if (err instanceof Error && err.name !== 'CanceledError') console.error(t('reports.err_load_clients', { defaultValue: 'Erreur chargement clients:' }), err);
            }
        };
        loadClients();

        const loadSuppliers = async () => {
            try {
                const { data } = await api.get('rapports/suppliers_with_stock/', { signal });
                setSuppliers(data);
            } catch (err) {
                if (err instanceof Error && err.name !== 'CanceledError') console.error(t('reports.err_load_suppliers', { defaultValue: 'Erreur chargement fournisseurs:' }), err);
            }
        };
        loadSuppliers();

        const loadUsers = async () => {
            try {
                const { data } = await api.get('users/', { signal });
                setUsers(data.results || data);
            } catch (err) {
                if (err instanceof Error && err.name !== 'CanceledError') console.error(t('reports.err_load_users', { defaultValue: 'Erreur chargement utilisateurs:' }), err);
            }
        };
        loadUsers();

        const loadFamilles = async () => {
            try {
                const { data } = await api.get('familles/', { signal });
                setFamilles(data.results || data);
            } catch (err) {
                if (err instanceof Error && err.name !== 'CanceledError') console.error(t('reports.err_load_families', { defaultValue: 'Erreur chargement familles:' }), err);
            }
        };
        loadFamilles();

        // Load Presets from LocalStorage
        const savedPresets = localStorage.getItem('report_presets:v1');
        if (savedPresets) setPresets(JSON.parse(savedPresets));

        return () => controller.abort();
    }, []);

    useEffect(() => {
        if (supplierSearch.length > 0) {
            const filtered = suppliers.filter(s =>
                s.name.toLowerCase().includes(supplierSearch.toLowerCase())
            );
            setFilteredSuppliers(filtered.slice(0, 10));
            setShowSupplierDropdown(true);
        } else {
            setFilteredSuppliers([]);
            setShowSupplierDropdown(false);
        }
    }, [supplierSearch, suppliers]);

    useEffect(() => {
        if (clientSearch.length > 0) {
            const filtered = clients.filter(c =>
                c.name.toLowerCase().includes(clientSearch.toLowerCase()) ||
                (c.phone && c.phone.includes(clientSearch))
            );
            setFilteredClients(filtered.slice(0, 10));
            setShowClientDropdown(true);
        } else {
            setFilteredClients([]);
            setShowClientDropdown(false);
        }
    }, [clientSearch, clients]);

    useEffect(() => {
        if (userSearch.length > 0) {
            const filtered = users.filter(u =>
                u.username.toLowerCase().includes(userSearch.toLowerCase())
            );
            setFilteredUsers(filtered.slice(0, 10));
        } else {
            setFilteredUsers(users.slice(0, 10));
        }
    }, [userSearch, users]);

    useEffect(() => {
        if (familleSearch.length > 0) {
            const filtered = familles.filter(f =>
                f.nom.toLowerCase().includes(familleSearch.toLowerCase())
            );
            setFilteredFamilles(filtered.slice(0, 10));
            setShowFamilleDropdown(true);
        } else {
            setFilteredFamilles([]);
            setShowFamilleDropdown(false);
        }
    }, [familleSearch, familles]);

    const savePreset = useCallback((name: string) => {
        if (!selectedQuery) return;
        const newPreset = {
            id: Date.now().toString(),
            name,
            queryId: selectedQuery.id,
            params: { ...params }
        };
        const updated = [...presets, newPreset];
        setPresets(updated);
        localStorage.setItem('report_presets:v1', JSON.stringify(updated));
        toast.success(t('reports.preset_saved', { defaultValue: 'Configuration enregistr├®e !' }));
    }, [selectedQuery, params, presets]);

    const deletePreset = useCallback((id: string) => {
        const updated = presets.filter(p => p.id !== id);
        setPresets(updated);
        localStorage.setItem('report_presets:v1', JSON.stringify(updated));
    }, [presets]);

    const applyPreset = useCallback((preset: unknown) => {
        const query = QUERIES.find(q => q.id === preset.queryId);
        if (query) {
            setSelectedQuery(query);
            setParams(preset.params);
            toast.success(t('reports.preset_loaded', { name: preset.name, defaultValue: `Chargement de : ${preset.name}` }));
        }
    }, []);

    const handleSelectQuery = useCallback((query: QueryDefinition) => {
        setSelectedQuery(query);
        setResults(null);
        setPagination(null);
        setError(null);
        setClientSearch('');
        setSelectedClientName('');
        setSupplierSearch('');
        setSelectedSupplierName('');

        const defaultParams: Record<string, string | number | boolean> = {};
        query.params.forEach(p => {
            if (p.default !== undefined) {
                defaultParams[p.key] = p.default;
            } else if (p.type === 'month') {
                defaultParams[p.key] = getCurrentMonth();
            } else if (p.type === 'datetime') {
                defaultParams[p.key] = getCurrentDateTime();
            } else if (p.type === 'date') {
                defaultParams[p.key] = getTodayDate();
            }
        });
        setParams(defaultParams);
    }, [getCurrentMonth, getCurrentDateTime, getTodayDate]);

    const executeQuery = useCallback(async (urlOverride?: string, extraParams?: Record<string, unknown>) => {
        if (!selectedQuery) return;

        setLoading(true);
        setError(null);

        try {
            const relPath = (p: string) => p.replace(/^\/api\//, '');
            const endpoint = urlOverride ? urlOverride : relPath(selectedQuery.endpoint);

            const mergedParams = extraParams ? { ...params, ...extraParams } : params;

            if (selectedQuery.id === 'balance_stock' && !urlOverride) {
                const response = await api.get(endpoint, {
                    params: { ...params, lang: i18n.language },
                    responseType: 'blob'
                });

                const filename = `Balance_Stocks_${params.date_debut}_${params.date_fin}.xlsx`;
                downloadBlob(response.data, filename);

                toast.success(t('results.export_success', { filename }));
                setResults({ status: 'success', filename });
                setLoading(false);
                return;
            }

            if (selectedQuery.id === 'export_sage' && !urlOverride) {
                const response = await api.get(endpoint, {
                    params: mergedParams,
                    responseType: 'blob'
                });

                const filename = `Export_Sage_i7_${params.date_debut}_${params.date_fin}.csv`;
                downloadBlob(response.data, filename, 'text/csv');

                toast.success(t('results.export_success', { filename }));
                setResults({ status: 'success', filename });
                setLoading(false);
                return;
            }

            if (selectedQuery.id === 'recap_valeur_stock_pdf' && !urlOverride) {
                const valorisation = params.valorisation || 'ACHAT';
                const groupBy = params.group_by || '';
                const printUrl = `/app/printing/0?type=STOCK_VALUATION&valorisation=${valorisation}&group_by=${groupBy}`;
                const printWin = window.open(printUrl, '_blank');
                if (!printWin) toast.error('Popup bloqu├®. Autorisez les popups pour imprimer.');
                setResults({ status: 'success', filename: t('reports.results.print_launched', { defaultValue: 'Impression lanc├®e' }) });
                setLoading(false);
                return;
            }

            const response = urlOverride
                ? await api.get(urlOverride)
                : await api.get(endpoint, { params: mergedParams });

            const data = response.data;
            if (data.results && Array.isArray(data.results)) {
                setResults(data.results);
                setPagination({
                    count: data.count,
                    next: extractPath(data.next),
                    previous: extractPath(data.previous)
                });
            } else {
                setResults(data);
                setPagination(null);
            }

            if (!urlOverride) toast.success(t('reports.results.execute_success', { name: selectedQuery.name, defaultValue: `Requ├¬te "${selectedQuery.name}" ex├®cut├®e` }));
        } catch (err) {
            console.error('Erreur requ├¬te:', err);
            setError(getApiErrorDetail(err, err instanceof Error ? err.message : t('reports.results.error_execution', { defaultValue: 'Erreur lors de l\'ex├®cution de la requ├¬te' })));
            toast.error(t('reports.results.error_execution_toast', { defaultValue: 'Erreur lors de l\'ex├®cution' }));
        } finally {
            setLoading(false);
        }
    }, [selectedQuery, params, extractPath, i18n.language, t]);

    const handlePageChange = useCallback((url: string | null) => {
        if (url) executeQuery(url);
    }, [executeQuery]);

    const downloadExcel = useCallback(async () => {
        if (!results || !selectedQuery) {
            toast.error(t('results.export_no_result'));
            return;
        }

        if (selectedQuery.id === 'rapport_remises' || selectedQuery.id === 'rapport_remises_details') {
            const { date_debut, date_fin } = params;
            const isDetails = selectedQuery.id === 'rapport_remises_details';
            const action = isDetails ? 'rapport_remises_details_excel' : 'rapport_remises_excel';
            const filename = isDetails ? `Details_Remises_${date_debut}.xlsx` : `Rapport_Remises_${date_debut}.xlsx`;

            try {
                const response = await api.get(`rapports/${action}/`, {
                    params: { date_debut, date_fin },
                    responseType: 'blob'
                });

                downloadBlob(response.data, filename);
                toast.success(t('results.export_success', { filename }));
            } catch (err) {
                console.error('Excel download error:', err);
                toast.error("Erreur lors du t├®l├®chargement Excel");
            }
            return;
        }

        let data: Record<string, string | number | boolean>[] = [];

        if (Array.isArray(results) && results.length > 0) {
            const columns = Object.keys(results[0]).filter(k => !k.startsWith('_') && k !== 'id').slice(0, 20);
            data = (results as Record<string, unknown>[]).map(row => {
                const obj: Record<string, string | number | boolean> = {};
                columns.forEach(col => {
                    const header = formatColumnHeader(col, t);
                    const val = row[col];
                    if (val === null || val === undefined) {
                        obj[header] = '';
                    } else if (typeof val === 'object' && val !== null) {
                        obj[header] = (val as { name?: string }).name || JSON.stringify(val);
                    } else if (typeof val === 'number') {
                        obj[header] = Math.round(val);
                    } else {
                        if (col === 'Mois') {
                            obj[header] = t(`common:months.${val}`, { defaultValue: String(val) });
                        } else {
                            obj[header] = val as string | boolean;
                        }
                    }
                });
                return obj;
            });

            // Summary Footer Logic
            const footerRow: Record<string, string | number | boolean> = {};
            columns.forEach((col, idx) => {
                const header = formatColumnHeader(col, t);
                if (idx === 0) {
                    footerRow[header] = t('reports.footer_total_avg', { defaultValue: 'TOTAL / MOYENNE' });
                } else if (isAverageColumn(col)) {
                    const total = results.reduce((sum: number, r: unknown) => sum + (Number(r[col]) || 0), 0);
                    const avg = results.length > 0 ? total / results.length : 0;
                    footerRow[header] = `${Math.round(avg)} ${t('reports.footer_avg_suffix', { defaultValue: '(Moy)' })}`;
                } else if (isSummableColumn(col)) {
                    const total = results.reduce((sum: number, r: unknown) => sum + (Number(r[col]) || 0), 0);
                    footerRow[header] = Math.round(total);
                } else if (isPercentageColumn(col)) {
                    let finalVal: string | number = '';
                    if (col === 'taux_marge') {
                        const totalMtVente = results.reduce((sum: number, r: unknown) => sum + (Number(r['mt_vente']) || 0), 0);
                        const totalMarge   = results.reduce((sum: number, r: unknown) => sum + (Number(r['marge']) || 0), 0);
                        if (totalMtVente > 0) {
                            finalVal = ((totalMarge / totalMtVente) * 100).toFixed(1) + t('reports.footer_pct_global', { defaultValue: ' % (Global)' });
                        }
                    }
                    if (!finalVal) {
                        const total = results.reduce((sum: number, r: unknown) => sum + (Number(r[col]) || 0), 0);
                        const avg = results.length > 0 ? (total / results.length) : 0;
                        finalVal = avg.toFixed(1) + t('reports.footer_pct_avg', { defaultValue: ' % (Moy)' });
                    }
                    footerRow[header] = finalVal;
                } else {
                    footerRow[header] = '';
                }
            });
            data.push(footerRow);
        } else if (typeof results === 'object' && results !== null && !Array.isArray(results)) {
            Object.entries(results).forEach(([key, value]) => {
                const formattedKey = formatColumnHeader(key);
                let formattedValue = '';
                if (typeof value === 'object' && value !== null) {
                    formattedValue = Object.entries(value).map(([k, v]) => `${k}: ${v}`).join(', ');
                } else {
                    formattedValue = String(value ?? '');
                }
                const row: Record<string, string | number | boolean> = { 'Indicateur': formattedKey, 'Valeur': formattedValue };
                data.push(row);
            });
        } else {
            toast.error(t('results.export_unsupported'));
            return;
        }

        const today = new Date().toISOString().slice(0, 10);
        const filename = `${selectedQuery.id}_${today}.xlsx`;
        exportToExcel(data, pharmacySettings, {
            sheetName: 'Rapport',
            filename,
            title: selectedQuery.name,
        });
        toast.success(t('results.export_success', { filename }));
    }, [results, selectedQuery, t, params, pharmacySettings]);

    useEffect(() => {
        const reportId = searchParams.get('report');
        if (reportId && !selectedQuery) {
            const query = QUERIES.find(q => q.id === reportId);
            if (query) {
                handleSelectQuery(query);
            }
        }
    }, [searchParams, handleSelectQuery, selectedQuery]);

    return {
        state: {
            selectedQuery,
            params,
            results,
            pagination,
            loading,
            error,
            clientSearch,
            filteredClients,
            showClientDropdown,
            selectedClientName,
            supplierSearch,
            filteredSuppliers,
            showSupplierDropdown,
            selectedSupplierName,
            userSearch,
            filteredUsers,
            showUserDropdown,
            selectedUserName,
            familleSearch,
            filteredFamilles,
            showFamilleDropdown,
            selectedFamilleName,
            presets
        },
        actions: {
            handleSelectQuery,
            setParams,
            executeQuery,
            handlePageChange,
            downloadExcel,
            clientActions: {
                setQuery: setClientSearch,
                setShowDropdown: setShowClientDropdown,
                setSelectedName: setSelectedClientName
            },
            supplierActions: {
                setQuery: setSupplierSearch,
                setShowDropdown: setShowSupplierDropdown,
                setSelectedName: setSelectedSupplierName
            },
            userActions: {
                setQuery: setUserSearch,
                setShowDropdown: setShowUserDropdown,
                setSelectedName: setSelectedUserName
            },
            familleActions: {
                setQuery: setFamilleSearch,
                setShowDropdown: setShowFamilleDropdown,
                setSelectedName: setSelectedFamilleName
            },
            presets: {
                save: savePreset,
                delete: deletePreset,
                apply: applyPreset
            },
            safeDate
        }
    };
}

