                          if (!isNaN(pEuro)) {
                              const priceFCFA = pEuro * rate;
                              const costPrice = priceFCFA * coeff;
                              const newPrice = Math.round(costPrice).toString();

                              const currentMargin = normalizeNumberInput(String(item.marge || 1.3));
