  const handleCsvImport = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsImporting(true);

    let allProducts: ProduitModel[] = [];
    try {
      const response = await api.get(produitsEndpoint);
      allProducts = response.data;
    } catch (err) {
      console.error("Failed to load products for import:", err);
      toast.error(t('orders:messages.import_load_error'));
      setIsImporting(false);
      return;
    }

    const normalizeCip = (cip: string | null | undefined): string => {
      if (!cip) return '';
      const normalized = cip.trim().replace(/[\s\-\.]/g, '');
      return normalized.toUpperCase();
    };

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) {
        setIsImporting(false);
        return;
      }

      const lines = text.split(/\r\n|\n/);
      const currentList = [...commandeProduits];
      let productsFound = 0;
      let productsNotFound = 0;
      const notFoundItems: { cip: string; qty: number }[] = [];

      let isFirstLine = true;
      lines.forEach(line => {
        if (!line.trim()) return;

        // Ignorer la ligne d'en-t├¬te (contient "CIP/EAN13" ou "Libell├®")
        if (isFirstLine) {
          isFirstLine = false;
          if (line.toLowerCase().includes('cip') || line.toLowerCase().includes('libell') || line.toLowerCase().includes('ean')) {
            return; // Skip header line
          }
        }

        // Parser les colonnes : CIP;Qt├®;Prix cession (format flexible, reste optionnel)
        const cols = line.split(';');
        const cip = cols[0];
        if (!cip) return;

        const qty = normalizeNumberInput(cols[1]) || 0;              // Colonne 2: Qt├® (obligatoire)
        const ug = 0;                                                 // UG non pr├®sent dans ce format
        const prixCession = parseCsvPrice(cols[2]);                   // Colonne 3: Prix cession (optionnel)
        const prixPublic = parseCsvPrice(cols[3]);                    // Colonne 4: Prix public (optionnel)

        const cleanCip = cip.trim();
        const normalizedSearchCip = normalizeCip(cleanCip);
        const libelle = '';  // Libell├® non pr├®sent dans ce format
        const normalizedLibelle = normalizeText(libelle);

        // 1. Chercher par CIP
        let product = allProducts.find(p => {
          const norm1 = normalizeCip(p.cip1);
          const norm2 = normalizeCip(p.cip2);
          const norm3 = normalizeCip(p.cip3);

          if (norm1 === normalizedSearchCip || norm2 === normalizedSearchCip || norm3 === normalizedSearchCip) return true;

          const numericSearch = normalizedSearchCip.replace(/^0+/, '');
          if (numericSearch && (
            norm1.replace(/^0+/, '') === numericSearch ||
            norm2.replace(/^0+/, '') === numericSearch ||
            norm3.replace(/^0+/, '') === numericSearch
          )) return true;

          return false;
        });

        // 2. Si pas trouv├® par CIP, chercher par nom avec scoring fuzzy
        if (!product && normalizedLibelle) {
          let bestMatch: ProduitModel | undefined = undefined;
          let bestScore = 0;
          const MIN_SCORE = 60; // Seuil minimum 60% de correspondance

          for (const p of allProducts) {
            const score = calculateNameScore(libelle, p.name);
            if (score > bestScore && score >= MIN_SCORE) {
              bestScore = score;
              bestMatch = p;
            }
          }

          if (bestMatch) {
            product = bestMatch;
            console.log(`[CSV Import] Produit trouv├® par nom (${bestScore.toFixed(0)}%): "${libelle}" ÔåÆ "${product.name}"`);
          }
        }

        if (product) {
            productsFound++;
            const existingIndex = currentList.findIndex(
               p => (typeof p.produit === 'object' ? p.produit.id : p.produit) === product.id
            );

            // Prix : utiliser CSV si pr├®sent (d├®j├á format├® en string), sinon syst├¿me
            const priceFromSystem = product.cost_price || '0';

            const finalPrice = prixCession || priceFromSystem;
            const finalPriceCost = prixCession || priceFromSystem;

            // Prix public : utiliser CSV si pr├®sent, sinon syst├¿me
            const finalSellingPrice = prixPublic || product.selling_price || '0';

            if (existingIndex !== -1) {
                const currentQty = normalizeNumberInput(String(currentList[existingIndex].quantity || 0));
                const currentUg = normalizeNumberInput(String(currentList[existingIndex].unites_gratuites || 0));
                const currentItem = currentList[existingIndex];
                // Si le produit existant a un prix ├á 0 et qu'on a un prix syst├¿me, utiliser le prix syst├¿me
                const currentPrice = normalizeNumberInput(String(currentItem.price || 0));
                const currentPriceCost = normalizeNumberInput(String(currentItem.price_cost || 0));
                const currentSellingPrice = normalizeNumberInput(String(currentItem.selling_price || 0));

                // Prix d'achat : CSV > Syst├¿me > Actuel (si d├®j├á d├®fini et > 0)
                const updatedPrice = prixCession || (currentPrice > 0 ? String(currentPrice) : priceFromSystem);
                const updatedPriceCost = prixCession || (currentPriceCost > 0 ? String(currentPriceCost) : priceFromSystem);
                // Prix de vente : CSV > Syst├¿me > Actuel (si d├®j├á d├®fini et > 0)
                const updatedSellingPrice = prixPublic || (currentSellingPrice > 0 ? String(currentSellingPrice) : (product.selling_price || '0'));

                currentList[existingIndex] = {
                    ...currentItem,
                    quantity: currentQty + qty,
                    unites_gratuites: currentUg + ug,
                    price: updatedPrice,
                    price_cost: updatedPriceCost,
                    selling_price: updatedSellingPrice,
                };
            } else {
                const newCommandeProduit: CommandeProduit = {
                  id: Date.now() + Math.random(), 
                  produit: product,
                  quantity: qty,
                  unites_gratuites: ug,
                  prix_euro: commandeType === 'DIR' ? (finalPrice ? (normalizeNumberInput(finalPrice) / normalizeNumberInput(tauxChange)).toFixed(0) : '0') : undefined,
                  price: finalPrice,
                  price_cost: finalPriceCost,
                  tva: product.tva || '0',
                  marge: product.taux_marge || '1.3',
                  selling_price: finalSellingPrice,
                  lot: '',
                  date_expiration: '',
                };
                currentList.push(newCommandeProduit);
            }
        } else {
            console.warn(`[CSV Import] CIP non trouv├®: "${cleanCip}" (normalis├®: "${normalizeCip(cleanCip)}")`);
            notFoundItems.push({ cip: cleanCip, qty });
            productsNotFound++;
        }
      });

      setCommandeProduits(currentList);

      if (productsNotFound > 0) {
        const txtContent = notFoundItems.map(item => `${item.cip};${item.qty}`).join('\n');
        const blob = new Blob([txtContent], { type: 'text/plain;charset=utf-8;' });
        const link = document.createElement('a');
        const dateStr = new Date().toISOString().slice(0, 10);
        link.href = URL.createObjectURL(blob);
        link.download = `produits_non_reconnus_${dateStr}.txt`;
        link.style.visibility = 'hidden';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        toast.error(t('orders:messages.csv_partial_import', { found: productsFound, notFound: productsNotFound }));
      } else {
        toast.success(t('orders:messages.csv_import_success', { count: productsFound }));
      }

      if (fileInputRef.current) fileInputRef.current.value = '';
      setIsImporting(false);
    };
    reader.readAsText(file);
  };

  const handleCsvExport = (wholesaler: 'PRINCIPAL' | 'SECONDAIRE' | 'SECONDAIRE_CIP3') => {
    if (commandeProduits.length === 0) {
      toast(t('orders:messages.csv_empty_order'), { icon: 'ÔÜá´©Å' });
      return;
    }

    const cipLabel = wholesaler === 'PRINCIPAL' ? 'CIP1' : wholesaler === 'SECONDAIRE' ? 'CIP2' : 'CIP3';
    const dateStr = new Date().toISOString().slice(0, 10);

    let csvContent = "";
    let exportedCount = 0;
    const skippedProducts: { nom: string; qty: number }[] = [];

    commandeProduits.forEach(item => {
        const product = typeof item.produit === 'object' ? item.produit : produitsList.find(p => p.id === item.produit);
        const nom = (typeof item.produit === 'object' ? item.produit?.name : product?.name) || `Produit #${item.produit}`;
        const qty = item.quantity || 0;

        if (!product) {
            skippedProducts.push({ nom, qty });
            return;
        }

        let code = '';
        if (wholesaler === 'PRINCIPAL')           code = product.cip1 || '';
        else if (wholesaler === 'SECONDAIRE')       code = product.cip2 || '';
        else if (wholesaler === 'SECONDAIRE_CIP3')  code = product.cip3 || product.cip2 || '';

        if (code) {
            csvContent += `${code};${qty}\n`;
            exportedCount++;
        } else {
            skippedProducts.push({ nom: product.name || nom, qty });
        }
    });

    // T├®l├®charger le CSV si au moins 1 produit exportable
    if (exportedCount > 0) {
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        const url = URL.createObjectURL(blob);
        link.setAttribute("href", url);
        link.setAttribute("download", `commande_${wholesaler}_${dateStr}.csv`);
        link.style.visibility = 'hidden';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    }

    // G├®n├®rer un fichier .txt listant les produits sans CIP
    if (skippedProducts.length > 0) {
        const lines = [
            `Produits non export├®s vers ${wholesaler} (code ${cipLabel} manquant)`,
            `Date : ${dateStr}`,
            ``,
            ...skippedProducts.map(p => `- ${p.nom}  (Qt├® : ${p.qty})`)
        ];
        const txtBlob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8;' });
        const txtLink = document.createElement("a");
        const txtUrl = URL.createObjectURL(txtBlob);
        txtLink.setAttribute("href", txtUrl);
        txtLink.setAttribute("download", `produits_sans_${cipLabel}_${dateStr}.txt`);
        txtLink.style.visibility = 'hidden';
        document.body.appendChild(txtLink);
        txtLink.click();
        document.body.removeChild(txtLink);

        if (exportedCount === 0) {
            toast(`Aucun produit export├® ÔÇö ${skippedProducts.length} produit(s) sans code ${cipLabel} list├®s dans le fichier t├®l├®charg├®.`, { icon: 'ÔÜá´©Å' });
        } else {
            toast(`${exportedCount} export├®(s), ${skippedProducts.length} sans ${cipLabel} ÔåÆ liste t├®l├®charg├®e`, { icon: 'ÔÜá´©Å' });
        }
    } else if (exportedCount > 0) {
        toast.success(`${exportedCount} produit(s) export├®s vers ${wholesaler}`);
    }
  };

