import { createContext, use, useState, type ReactNode } from 'react'
import ConfirmDialog from '../components/ConfirmDialog'

interface ConfirmOptions {
  title?: string
  message: string
  confirmText?: string
  cancelText?: string
  variant?: 'danger' | 'warning' | 'info' | 'success'
}

interface ConfirmContextType {
  confirm: (options: ConfirmOptions) => Promise<boolean>
}

const ConfirmContext = createContext<ConfirmContextType | undefined>(undefined)

export function ConfirmProvider({ children }: { children: ReactNode }) {
  const [confirmState, setConfirmState] = useState<{
    isOpen: boolean
    options: ConfirmOptions
    resolver?: (value: boolean) => void
  }>({
    isOpen: false,
    options: {
      title: '',
      message: '',
      variant: 'warning'
    }
  })

  const confirm = (options: ConfirmOptions): Promise<boolean> => {
    return new Promise((resolve) => {
      setConfirmState({
        isOpen: true,
        options,
        resolver: resolve
      })
    })
  }

  const handleConfirm = () => {
    confirmState.resolver?.(true)
    setConfirmState({ ...confirmState, isOpen: false })
  }

  const handleCancel = () => {
    confirmState.resolver?.(false)
    setConfirmState({ ...confirmState, isOpen: false })
  }

  return (
    <ConfirmContext.Provider value={{ confirm }}>
      {children}
      <ConfirmDialog
        isOpen={confirmState.isOpen}
        title={confirmState.options.title || ''}
        message={confirmState.options.message}
        confirmText={confirmState.options.confirmText}
        cancelText={confirmState.options.cancelText}
        variant={confirmState.options.variant}
        onConfirm={handleConfirm}
        onCancel={handleCancel}
      />
    </ConfirmContext.Provider>
  )
}

export function useConfirm() {
  const context = use(ConfirmContext)
  if (!context) {
    throw new Error('useConfirm must be used within a ConfirmProvider')
  }
  return context.confirm
}

import { useState, useCallback } from 'react';
import { toast } from 'react-hot-toast';
import { useTranslation } from 'react-i18next';
import type { Creance } from '../types';
import { useSudo } from './useSudo';
import creanceService from '../services/creanceService';
import { usePharmacySettings } from './usePharmacySettings';
import { generateRelevePdfDraft } from '../utils/print/relevePdfDraft';
import { generateTicketReglementPdfDraft } from '../utils/print/ticketReglementPdfDraft';

interface UseCreanceActionsProps {
    refresh: () => void;
    selectedIds: number[];
    setSelectedIds: (ids: number[]) => void;
    filteredCreances: Creance[];
    creancesEndpoint?: string;
    updateLocalCreance?: (id: number, data: unknown) => void;
    updateLocalSynthese?: (clientId: number, data: unknown) => void;
}

export const useCreanceActions = ({
    refresh,
    selectedIds,
    setSelectedIds,
    filteredCreances,
    creancesEndpoint: _creancesEndpoint,
    updateLocalCreance,
    updateLocalSynthese: _updateLocalSynthese
}: UseCreanceActionsProps) => {
    const { t } = useTranslation(['creances', 'common']);
    const { sudoState, requireSudo, closeSudo } = useSudo();
    const { settings: pharmacySettings } = usePharmacySettings();

    // Modal states
    const [selectedCreance, setSelectedCreance] = useState<Creance | null>(null);
    const [isPaiementModalOpen, setIsPaiementModalOpen] = useState(false);
    const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
    const [isBulkModalOpen, setIsBulkModalOpen] = useState(false);

    // Form states
    const [modePaiement, setModePaiement] = useState('especes');
    const [montantPaiement, setMontantPaiement] = useState('');
    const [referencePaiement, setReferencePaiement] = useState('');
    const [montantTotalBulk, setMontantTotalBulk] = useState<string>(''); // Pour paiement partiel sur plusieurs factures

    const handleOpenPaiementModal = useCallback((creance: Creance) => {
        setSelectedCreance(creance);
        setModePaiement('especes');
        setMontantPaiement(creance.reste_a_payer);
        setReferencePaiement('');
        setIsPaiementModalOpen(true);
    }, []);

    const handleOpenDetailsModal = useCallback((creance: Creance) => {
        setSelectedCreance(creance);
        setIsDetailsModalOpen(true);
    }, []);

    const handleBulkPayment = useCallback(() => {
        if (selectedIds.length === 0) return;
        setIsBulkModalOpen(true);
        setModePaiement('especes');
        setReferencePaiement('');
        setMontantPaiement('');
        setMontantTotalBulk(''); // Reset du montant bulk
    }, [selectedIds.length]);

    const handlePrintDirectReceipt = useCallback(async (creanceId: number, paiementId?: number) => {
        try {
            const blob = await creanceService.imprimerRecu(creanceId, paiementId);
            const blobUrl = window.URL.createObjectURL(blob);
            const printWindow = window.open(blobUrl, '_blank');

            if (!printWindow) {
                const link = document.createElement('a');
                link.href = blobUrl;
                link.setAttribute('download', `recu_paiement_${creanceId}_${paiementId || 'all'}.pdf`);
                document.body.appendChild(link);
                link.click();
                link.parentNode?.removeChild(link);
            }

            setTimeout(() => window.URL.revokeObjectURL(blobUrl), 100);
        } catch (err: unknown) {
            console.error('Erreur lors de l\'impression du re├ºu:', err);
            const error = err as { response?: { data?: { detail?: string } } };
            toast.error(error.response?.data?.detail || t('creances:toasts.error_print_receipt'));
        }
    }, []);

    const handlePrintBulkReceipt = useCallback(async (releveId: number) => {
        if (!releveId) return;

        try {
            const blob = await creanceService.imprimerRelevePaiement(releveId);
            const url = window.URL.createObjectURL(blob);
            const printWindow = window.open(url, '_blank');

            if (!printWindow) {
                const link = document.createElement('a');
                link.href = url;
                link.setAttribute('download', `recapitulatif_reglement_${releveId}.pdf`);
                document.body.appendChild(link);
                link.click();
                link.parentNode?.removeChild(link);
            }

            setTimeout(() => window.URL.revokeObjectURL(url), 100);
        } catch (err: unknown) {
            console.error('Erreur lors de l\'impression du relev├®:', err);
            const error = err as { response?: { data?: { detail?: string } } };
            toast.error(error.response?.data?.detail || t('creances:toasts.error_print_statement'));
        }
    }, []);

    const performAjouterPaiement = useCallback(async (validatorId: number, password: string) => {
        if (!selectedCreance || !montantPaiement) return;

        try {
            const data = await creanceService.ajouterPaiement(selectedCreance.id, {
                mode_paiement: modePaiement,
                montant: parseFloat(montantPaiement),
                reference: referencePaiement || undefined,
                validated_by_id: validatorId,
                sudo_password: password
            });

            const paiementId = data.paiement_id;

            setIsPaiementModalOpen(false);
            
            // Instant update if possible
            if (updateLocalCreance && data.creance) {
                updateLocalCreance(selectedCreance.id, data.creance);
            } else {
                refresh();
            }

            toast.success(t('creances:toasts.payment_success'));

            if (window.confirm(t('creances:toasts.confirm_print_receipt'))) {
                await handlePrintDirectReceipt(selectedCreance.id, paiementId);
            }
        } catch (err: unknown) {
            const error = err as { response?: { data?: { detail?: string } } };
            toast.error(error.response?.data?.detail || t('common:messages.error_saving'));
            console.error('Erreur:', err);
            throw err;
        }
    }, [selectedCreance, montantPaiement, modePaiement, referencePaiement, refresh, handlePrintDirectReceipt, updateLocalCreance]);

    const handleAjouterPaiement = () => {
        requireSudo(performAjouterPaiement);
    };

    const performBulkPayment = useCallback(async (validatorId: number, password: string) => {
        try {
            const payload: unknown = {
                facture_ids: selectedIds,
                mode_paiement: modePaiement,
                reference: referencePaiement,
                validated_by_id: validatorId,
                sudo_password: password
            };
            // Si un montant bulk personnalis├® est saisi, l'ajouter
            if (montantTotalBulk && parseFloat(montantTotalBulk) > 0) {
                payload.montant_total = parseFloat(montantTotalBulk);
            }
            
            const data = await creanceService.bulkPaiement(payload);

            const releveId = data.releve_id;

            setIsBulkModalOpen(false);
            setSelectedIds([]);
            setMontantTotalBulk(''); // Reset apr├¿s paiement
            refresh();
            toast.success(t('creances:toasts.bulk_success'));

            // G├®n├®rer le ticket de confirmation avec les d├®tails
            if (data.paiements && data.paiements.length > 0) {
                try {
                    // R├®cup├®rer le nom du client depuis les cr├®ances
                    const firstCreance = filteredCreances.find(c => c.id === selectedIds[0]);
                    const clientName = firstCreance?.client_name || 'Client';
                    
                    console.log('=== BULK PAYMENT RESPONSE ===');
                    console.log('Total dettes:', data.total_dettes);
                    console.log('Montant r├®gl├®:', data.total_amount);
                    console.log('Reste ├á payer global:', data.reste_a_payer);
                    console.log('=== PAIEMENTS D├ëTAIL ===');
                    data.paiements?.forEach((p: unknown, i: number) => {
                        console.log(`  ${i+1}. Facture ${p.numero_facture}:`, {
                            montant_paye: p.montant_paye,
                            reste_avant: p.reste_avant,
                            reste_apres: p.reste_apres,
                            est_soldee: p.est_soldee,
                            type_est_soldee: typeof p.est_soldee
                        });
                    });
                    
                    const ticketDoc = generateTicketReglementPdfDraft({
                        reference: data.releve_reference || `REL-${releveId}`,
                        date: new Date().toISOString(),
                        client_name: clientName,
                        mode_paiement: modePaiement,
                        total_dettes: data.total_dettes || data.total_amount,
                        montant_regle: data.total_amount,
                        reste_a_payer: data.reste_a_payer || '0.00',
                        paiements: data.paiements,
                        settings: pharmacySettings
                    });
                    
                    ticketDoc.save(`ticket_reglement_${data.releve_reference || releveId}.pdf`);
                } catch (ticketErr) {
                    console.error('Erreur g├®n├®ration ticket:', ticketErr);
                    toast.error('Erreur lors de la g├®n├®ration du ticket de confirmation');
                }
            }

            if (releveId && window.confirm(t('creances:toasts.confirm_print_bulk_receipt'))) {
                await handlePrintBulkReceipt(releveId);
            }
        } catch (err: unknown) {
            const error = err as { response?: { data?: { detail?: string } } };
            toast.error(error.response?.data?.detail || t('common:messages.error_saving'));
            console.error('Erreur:', err);
            throw err;
        }
    }, [selectedIds, modePaiement, referencePaiement, montantTotalBulk, setSelectedIds, refresh, handlePrintBulkReceipt, filteredCreances, pharmacySettings]);

    const confirmBulkPayment = () => {
        requireSudo(performBulkPayment);
    };

    const handleImprimerReleve = useCallback(async (selectedClient: string, dateDebut: string, dateFin: string) => {
        if (!selectedClient) {
            toast.error(t('creances:toasts.select_client_error'));
            return;
        }

        const loadingToast = toast.loading('G├®n├®ration du relev├®...');
        try {
            const releveData = await creanceService.getReleve({
                client_id: selectedClient,
                ...(dateDebut ? { date_debut: dateDebut } : {}),
                ...(dateFin ? { date_fin: dateFin } : {}),
            });

            const doc = generateRelevePdfDraft({
                client: releveData.client,
                creances: releveData.creances,
                totaux: releveData.totaux,
                periode: releveData.periode,
                settings: pharmacySettings,
            });

            const clientSlug = releveData.client?.name
                ? releveData.client.name.toLowerCase().replace(/\s+/g, '_')
                : selectedClient;
            doc.save(`releve_${clientSlug}_${new Date().toISOString().slice(0, 10)}.pdf`);
            toast.success('Relev├® g├®n├®r├® avec succ├¿s.', { id: loadingToast });
        } catch {
            toast.error(t('creances:toasts.error_print_statement'), { id: loadingToast });
        }
    }, [t, pharmacySettings]);

    const handleExportExcel = useCallback(async (params: {
        client_id?: string;
        date_debut?: string;
        date_fin?: string;
        history?: boolean;
    }) => {
        const loadingToast = toast.loading('G├®n├®ration du fichier Excel...');
        try {
            const blob = await creanceService.exportExcel(params);
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            const dateStr = new Date().toISOString().slice(0, 10);
            link.setAttribute('download', `creances_${dateStr}.xlsx`);
            document.body.appendChild(link);
            link.click();
            link.parentNode?.removeChild(link);
            setTimeout(() => window.URL.revokeObjectURL(url), 100);
            toast.success('Export Excel g├®n├®r├® avec succ├¿s.', { id: loadingToast });
        } catch (err) {
            console.error('Erreur export Excel:', err);
            toast.error('Erreur lors de l\'export Excel.', { id: loadingToast });
        }
    }, []);

    return {
        selectedCreance,
        modals: {
            isPaiementModalOpen,
            setIsPaiementModalOpen,
            isDetailsModalOpen,
            setIsDetailsModalOpen,
            isBulkModalOpen,
            setIsBulkModalOpen,
            sudoState,
            closeSudo
        },
        form: {
            modePaiement,
            setModePaiement,
            montantPaiement,
            setMontantPaiement,
            referencePaiement,
            setReferencePaiement,
            montantTotalBulk,
            setMontantTotalBulk
        },
        actions: {
            handleOpenPaiementModal,
            handleOpenDetailsModal,
            handleBulkPayment,
            confirmBulkPayment,
            handleAjouterPaiement,
            handlePrintDirectReceipt,
            handlePrintBulkReceipt,
            handleImprimerReleve,
            handleExportExcel
        }
    };
};

import { useState, useCallback, useRef } from 'react';
import { parseDataMatrix, normalizeDateExpiration } from '../utils/parseDataMatrix';
import type { CommandeProduit } from '../types/procurement';
import type { ProduitModel } from '../types/catalog';

export type ScanResult =
    | { status: 'filled'; index: number; cip: string; lot: string; date: string }
    | { status: 'already_filled'; index: number; cip: string }
    | { status: 'not_found'; cip: string | null; raw: string }
    | { status: 'parse_error'; raw: string };

interface UseDataMatrixScannerOptions {
    commandeProduits: CommandeProduit[];
    updateCommandeProduitField: (
        index: number,
        field: 'lot' | 'date_expiration',
        value: string
    ) => void;
    onNotFound?: () => void;
}

function normalizeCip(cip: string | null | undefined): string {
    if (!cip) return '';
    return cip.trim().replace(/[\s\-\.]/g, '').toUpperCase();
}

function getProductCip(produit: number | ProduitModel | null | undefined): string[] {
    if (!produit || typeof produit === 'number') return [];
    return [
        normalizeCip((produit as ProduitModel).cip1),
        normalizeCip((produit as ProduitModel).cip2),
        normalizeCip((produit as ProduitModel).cip3),
    ].filter(Boolean);
}

export function useDataMatrixScanner({
    commandeProduits,
    updateCommandeProduitField,
    onNotFound,
}: UseDataMatrixScannerOptions) {
    const [lastScanResult, setLastScanResult] = useState<ScanResult | null>(null);
    const [highlightedIndex, setHighlightedIndex] = useState<number | null>(null);
    const clearHighlightTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

    const processScan = useCallback(
        (rawScan: string): ScanResult => {
            if (!rawScan.trim()) {
                const r: ScanResult = { status: 'parse_error', raw: rawScan };
                setLastScanResult(r);
                return r;
            }

            const parsed = parseDataMatrix(rawScan);

            // Si le parsing n'a rien donn├® (cha├«ne inconnue), tenter un fallback :
            // certaines douchettes envoient juste le CIP13 brut (13 chiffres)
            let cip = parsed.cip;
            const lot = parsed.lot;
            const dateExpiration = parsed.dateExpiration;

            if (!cip && /^\d{13}$/.test(rawScan.trim())) {
                cip = rawScan.trim();
            }

            if (!cip) {
                const r: ScanResult = { status: 'not_found', cip: null, raw: rawScan };
                setLastScanResult(r);
                onNotFound?.();
                return r;
            }

            const normalizedScannedCip = normalizeCip(cip);
            const numericScanned = normalizedScannedCip.replace(/^0+/, '');

            // Chercher la ligne correspondante dans la commande
            const matchIndex = commandeProduits.findIndex((cp) => {
                const cips = getProductCip(cp.produit);
                return cips.some(
                    (c) =>
                        c === normalizedScannedCip ||
                        c.replace(/^0+/, '') === numericScanned
                );
            });

            if (matchIndex === -1) {
                const r: ScanResult = { status: 'not_found', cip, raw: rawScan };
                setLastScanResult(r);
                onNotFound?.();
                return r;
            }

            const existing = commandeProduits[matchIndex];
            const alreadyFilled = !!(existing.lot && existing.lot.trim() !== '');

            if (alreadyFilled) {
                // Surligner la ligne et signaler
                setHighlightedIndex(matchIndex);
                if (clearHighlightTimer.current) clearTimeout(clearHighlightTimer.current);
                clearHighlightTimer.current = setTimeout(() => setHighlightedIndex(null), 5000);

                const r: ScanResult = { status: 'already_filled', index: matchIndex, cip };
                setLastScanResult(r);
                return r;
            }

            // Remplir lot et date
            const finalLot = lot ?? '';
            const finalDate = dateExpiration ?? normalizeDateExpiration(parsed.rawDate) ?? '';

            if (finalLot) {
                updateCommandeProduitField(matchIndex, 'lot', finalLot);
            }
            if (finalDate) {
                updateCommandeProduitField(matchIndex, 'date_expiration', finalDate);
            }

            const r: ScanResult = {
                status: 'filled',
                index: matchIndex,
                cip,
                lot: finalLot,
                date: finalDate,
            };
            setLastScanResult(r);
            return r;
        },
        [commandeProduits, updateCommandeProduitField, onNotFound]
    );

    const clearHighlight = useCallback(() => {
        setHighlightedIndex(null);
    }, []);

    return {
        processScan,
        lastScanResult,
        highlightedIndex,
        clearHighlight,
    };
}

import { useEffect, useRef } from 'react'
import api from '../services/api'
import { toast } from 'react-hot-toast'
import { safeStorage } from '../utils/storage'
import type { ProduitModel, Facture, LigneFacture } from '../types'

export interface UseDevisLoaderOptions {
    clientsHook: {
        setSelectedClient: (id: number | null) => void
        setUseManualClient: (v: boolean) => void
        setManualClientName: (name: string) => void
        setSelectedAyantDroit: (id: number | null) => void
    }
    cart: {
        setLignesFacture: (lignes: LigneFacture[]) => void
    }
    ui: {
        setRemiseGlobale: (v: string) => void
        setRemiseMode: (v: 'montant' | 'taux') => void
        setIsModificationMode: (v: boolean) => void
        setModificationInvoiceId: (v: number | null) => void
        setModificationInvoiceStatus: (v: string | null) => void
        setOriginalTotalTtc: (v: number) => void
        setIsAvoirClient?: (v: boolean) => void
    }
}

export function useDevisLoader({ clientsHook, cart, ui }: UseDevisLoaderOptions) {
    const hasLoadedDevisRef = useRef(false)

    useEffect(() => {
        const loadDevis = async () => {
            if (hasLoadedDevisRef.current) return
            const devisString = safeStorage.getItem('devis_to_load', 'local')
            if (!devisString) return
            try {
                hasLoadedDevisRef.current = true
                const devis = JSON.parse(devisString) as Facture

                if (devis.client) {
                    clientsHook.setSelectedClient(devis.client)
                    clientsHook.setUseManualClient(false)
                    if (devis.ayant_droit) clientsHook.setSelectedAyantDroit(devis.ayant_droit)
                } else if (devis.client_name_override) {
                    clientsHook.setUseManualClient(true)
                    clientsHook.setManualClientName(devis.client_name_override)
                }

                if (devis.produits && devis.produits.length > 0) {
                    const lignes: LigneFacture[] = await Promise.all(devis.produits.map(async (p: unknown) => {
                        let produitData: ProduitModel
                        if (typeof p.produit === 'object' && p.produit.stock !== undefined) {
                            produitData = p.produit
                        } else {
                            const produitId = typeof p.produit === 'object' ? p.produit.id : p.produit
                            try {
                                const { data: fullProduct } = await api.get<ProduitModel>(`produits/${produitId}/`)
                                produitData = fullProduct
                            } catch {
                                produitData = { id: produitId, name: p.produit_nom || `Produit #${produitId}`, stock: 0, is_deleted: true } as ProduitModel
                            }
                        }
                        const lotId = p.stock_lot ? String(p.stock_lot) : (p.lot || null)
                        return {
                            produit: produitData,
                            quantite: p.quantity,
                            prix_unitaire: p.selling_price,
                            remise_produit: '0',
                            total_ligne: p.quantity * Number(p.selling_price),
                            lotId: lotId,
                            lotText: p.lot || null,
                            lotExpiration: p.date_expiration || null,
                            lotSellingPrice: p.selling_price || null,
                            treatment_duration_days: p.treatment_duration_days
                        }
                    }))
                    cart.setLignesFacture(lignes)
                }

                if (devis.remise) {
                    ui.setRemiseGlobale(devis.remise)
                    ui.setRemiseMode('montant')
                }

                if (devis.is_avoir_client && ui.setIsAvoirClient) {
                    ui.setIsAvoirClient(devis.is_avoir_client)
                }

                const isValidatedOrPaid = devis.status === 'VAL' || devis.status === 'PAY'
                if (isValidatedOrPaid && devis.id) {
                    ui.setIsModificationMode(true)
                    ui.setModificationInvoiceId(devis.id)
                    ui.setModificationInvoiceStatus(devis.status || null)
                    ui.setOriginalTotalTtc(Number(devis.total_ttc || 0))
                    toast.success(`Facture #${devis.numero_facture || devis.id} charg├®e en mode modification`)
                } else if (devis.id) {
                    toast.success(`Devis #${devis.numero_facture || devis.id} charg├®`)
                } else {
                    toast.success(`Panier pr├®-rempli ├á partir de la copie`)
                }
                safeStorage.removeItem('devis_to_load', 'local')
            } catch {
                toast.error('Impossible de charger le devis')
                safeStorage.removeItem('devis_to_load', 'local')
            }
        }
        loadDevis()
    }, [])
}

import { useCallback } from 'react';
import api from '../services/api';
import { toast } from 'react-hot-toast';
import { getApiErrorDetail } from '../utils/errorHandling';
import { safeStorage } from '../utils/storage';
import type { Facture, LigneFacture, TotalsData, User, Client, LotAllocation } from '../types';
import type { PosteVente } from '../services/cashSessionService';
import type { OrdonnanceData } from '../components/OrdonnanceModal';
import type { useFacturationClients } from './useFacturationClients';
import type { useFacturationUI } from './useFacturationUI';
import type { usePendingSales } from './usePendingSales';
import type { useProductSearch } from './useProductSearch';

export interface UseFacturationActionsProps {
    apiBaseUrl?: string;
    cart: {
        lignesFacture: LigneFacture[];
        setLignesFacture: (lignes: LigneFacture[]) => void;
    };
    clientsHook: ReturnType<typeof useFacturationClients>;
    ui: ReturnType<typeof useFacturationUI>;
    totals: TotalsData & { tauxCouverture: number; partPatient: number };
    pendingSales: ReturnType<typeof usePendingSales>;
    setLoading: (loading: boolean) => void;
    setError: (error: string | null) => void;
    t: (key: string, options?: Record<string, unknown>) => string;
    productSearch: ReturnType<typeof useProductSearch>;
    searchInputRef: React.RefObject<HTMLInputElement | null>;
    paymentInputRef: React.RefObject<HTMLInputElement | null>;
    pendingPrintFacture: Facture | null;
    setPendingPrintFacture: (f: Facture | null) => void;
    setShowClientNameModal: (show: boolean) => void;
    secureUpdateQuantite: (produitId: number, qty: number) => void;
    user: User | null;
    myActivePoste?: PosteVente | null;
    postesCaisses?: { id: number }[];
}

export function useFacturationActions({
    cart,
    clientsHook,
    ui,
    totals,
    pendingSales,
    setLoading,
    setError,
    t,
    productSearch,
    searchInputRef,
    paymentInputRef,
    pendingPrintFacture,
    setPendingPrintFacture,
    setShowClientNameModal,
    secureUpdateQuantite,
    user,
    myActivePoste,
    postesCaisses: _postesCaisses
}: UseFacturationActionsProps) {

    const handleProforma = useCallback(async () => {
        if (cart.lignesFacture.length === 0) return
        setLoading(true)
        try {
            const facturePayload = {
                client: clientsHook.useManualClient ? null : clientsHook.selectedClient,
                client_name_override: clientsHook.useManualClient ? clientsHook.manualClientName : null,
                remise: totals.remiseMontant.toString(),
                tva: '0',
                status: 'PROF',
                ayant_droit: clientsHook.selectedAyantDroit,
                part_client: (clientsHook.selectedClient && clientsHook.clients.find((c: Client) => c.id === clientsHook.selectedClient)?.client_type === 'PROFESSIONNEL' && totals.tauxCouverture > 0) ? totals.partPatient : null
            }
            const { data: createdFacture } = await api.post('factures/', facturePayload)

            const produitsPayload = cart.lignesFacture.map((ligne: LigneFacture) => {
                const prixUnitaire = Number(ligne.prix_unitaire)
                const remiseProduit = Number(ligne.remise_produit)
                const prixNet = prixUnitaire * (1 - remiseProduit / 100)
                return {
                    facture: createdFacture.id,
                    produit: ligne.produit.id,
                    quantity: Number(ligne.quantite),
                    selling_price: prixNet.toString(),
                    discount: (prixUnitaire - prixNet).toFixed(0),
                    stock_lot: ligne.lotId ? Number(ligne.lotId) : null,
                    lot: null,
                    date_expiration: ligne.produit.expire_date || null,
                    lot_allocations: ligne.lotAllocations && ligne.lotAllocations.length > 0
                        ? ligne.lotAllocations.map(a => ({
                            lot_id: Number(a.lotId),
                            quantity: Number(a.quantity),
                            selling_price: a.sellingPrice ? Number(a.sellingPrice) : undefined,
                        }))
                        : undefined,
                }
            })

            await Promise.all(produitsPayload.map((payload) => api.post('facture-produits/', payload)))

            try {
                const w = window.open(`/app/print-invoice/${createdFacture.id}`, '_blank')
                if (!w) toast.error("Popup bloqu├®. Autorisez les popups pour imprimer.")
                toast.success("Proforma g├®n├®r├® avec succ├¿s")
            } catch {}

            cart.setLignesFacture([])
            ui.setMontantPaye('')
            ui.setModePaiement('especes')
            ui.setPaiements([{ mode: 'especes', montant: 0 }])
            clientsHook.setSelectedClient(null)
            clientsHook.setManualClientName('')
            ui.setTicketCaisse(null)
        } catch {
            toast.error("Erreur lors de la cr├®ation du proforma")
        } finally {
            setLoading(false)
        }
    }, [cart.lignesFacture, clientsHook, totals, ui, setLoading])

    const handleBonDeLivraison = useCallback(async () => {
        if (cart.lignesFacture.length === 0) {
            toast.error("Le panier est vide")
            return
        }
        if (ui.isModificationMode && ui.modificationInvoiceId) {
            const w = window.open(`/app/print-invoice/${ui.modificationInvoiceId}?type=BL`, '_blank')
            if (!w) toast.error("Popup bloqu├®. Autorisez les popups pour imprimer.")
            return
        }

        setLoading(true)
        try {
            const facturePayload = {
                client: clientsHook.selectedClient || null,
                client_name_override: clientsHook.manualClientName || null,
                ayant_droit: clientsHook.selectedAyantDroit || null,
                status: 'PROF',
                remise: Number(ui.remiseGlobale) || 0,
                notes: "G├®n├®r├® via Bon de Livraison"
            }

            const res = await api.post('factures/', facturePayload)
            const createdFacture = res.data

            const produitsPayload = cart.lignesFacture.map((ligne: LigneFacture) => {
                const prixUnitaire = Number(ligne.prix_unitaire)
                const remiseProduit = Number(ligne.remise_produit) || 0
                const prixNet = prixUnitaire * (1 - remiseProduit / 100)
                const lotIdNum = ligne.lotId && !isNaN(Number(ligne.lotId)) ? Number(ligne.lotId) : null

                return {
                    facture: createdFacture.id,
                    produit: ligne.produit.id,
                    produit_nom: ligne.produit.name,
                    quantity: Number(ligne.quantite),
                    selling_price: prixNet.toFixed(2),
                    discount: (prixUnitaire - prixNet).toFixed(2),
                    stock_lot_id: lotIdNum,
                    lot: ligne.lotText || null,
                    date_expiration: ligne.lotExpiration || ligne.produit.expire_date || null,
                    lot_allocations: ligne.lotAllocations && ligne.lotAllocations.length > 0
                        ? ligne.lotAllocations.map(a => ({
                            lot_id: Number(a.lotId),
                            quantity: Number(a.quantity),
                            selling_price: a.sellingPrice ? Number(a.sellingPrice) : undefined,
                        }))
                        : undefined,
                }
            })

            for (const payload of produitsPayload) {
                await api.post('facture-produits/', payload)
            }

            const blWin = window.open(`/app/print-invoice/${createdFacture.id}?type=BL`, '_blank')
            if (!blWin) toast.error("Popup bloqu├®. Autorisez les popups pour imprimer.")

            ui.setModificationInvoiceId(createdFacture.id)
            ui.setModificationInvoiceStatus('PROF')
            ui.setIsModificationMode(true)

            toast.success("Bon de livraison g├®n├®r├® - Document pr├¬t pour validation")
        } catch (error) {
            toast.error(`Erreur lors de la cr├®ation du document : ${error instanceof Error ? error.message : 'Erreur inconnue'}`)
        } finally {
            setLoading(false)
        }
    }, [cart.lignesFacture, clientsHook, ui, setLoading])

    const handleImprimerFacture = useCallback(async (facture: Facture) => {
        if (!facture) {
            setError("Aucune facture ├á imprimer.");
            return;
        }
        try {
            if (facture.id) {
                const w = window.open(`/app/print-invoice/${facture.id}`, '_blank')
                if (!w) setError("Popup bloqu├®. Autorisez les popups pour imprimer.")
            }
        } catch (err) {
            setError(getApiErrorDetail(err, "Erreur lors de l'impression de la facture"))
        }
    }, [setError])

    const handleConfirmPrintClientName = useCallback(async (clientNameInput: string) => {
        if (!pendingPrintFacture) return;
        try {
            await api.patch(`factures/${pendingPrintFacture.id}/`,
                { client_name_override: clientNameInput }
            );
            let url = `/app/print-invoice/${pendingPrintFacture.id}`;
            if (clientNameInput) url += `?client_name=${encodeURIComponent(clientNameInput)}`;
            const w1 = window.open(url, '_blank');
            if (!w1) toast.error("Popup bloqu├®. Autorisez les popups pour imprimer.");
        } catch {
            let url = `/app/print-invoice/${pendingPrintFacture.id}`;
            if (clientNameInput) url += `?client_name=${encodeURIComponent(clientNameInput)}`;
            const w2 = window.open(url, '_blank');
            if (!w2) toast.error("Popup bloqu├®. Autorisez les popups pour imprimer.");
        } finally {
            setShowClientNameModal(false);
            setPendingPrintFacture(null);
            setTimeout(() => searchInputRef.current?.focus(), 100);
        }
    }, [pendingPrintFacture, setShowClientNameModal, setPendingPrintFacture, searchInputRef])

    const ouvrirModalPaiement = useCallback((facture?: Facture) => {
        // Bloquer si aucun poste de vente actif pour l'utilisateur courant
        if (!myActivePoste) {
            setError(t('facturation:messages.no_cash_register_open'))
            return
        }
        if (facture) {
            ui.setMontantPaye(Math.round(Number(facture.total_ttc)).toString())
            ui.openPaymentModal(facture)
        } else {
            if (!clientsHook.selectedClient) {
                setError(t('facturation:messages.select_client'))
                return
            }
            if (cart.lignesFacture.length === 0) {
                setError(t('facturation:messages.add_product'))
                return
            }
            const montantInitial = totals.tauxCouverture > 0 ? totals.partPatient : totals.totalTtc
            ui.setMontantPaye(Math.round(montantInitial).toString())
            ui.openPaymentModal()
        }
        ui.setModePaiement('especes')
        ui.setReference('')
        ui.setPaiements([])
        setTimeout(() => {
            paymentInputRef.current?.focus()
            paymentInputRef.current?.select()
        }, 100)
    }, [ui, clientsHook.selectedClient, cart.lignesFacture.length, totals.totalTtc, totals.tauxCouverture, totals.partPatient, setError, paymentInputRef, myActivePoste, t])

    const handleSendWhatsApp = useCallback(async () => {
        if (!ui.ticketCaisse || !ui.ticketCaisse.facture || typeof ui.ticketCaisse.facture === 'number') return
        const facture = ui.ticketCaisse.facture as unknown
        const clientPhone = (typeof facture.client === 'object' ? facture.client?.phone : '') || facture.client_phone
        const phone = window.prompt(t('facturation.messages.enter_whatsapp_number') || 'Entrez le num├®ro WhatsApp', clientPhone || '')
        if (!phone) return

        setLoading(true)
        try {
            const response = await api.post(`factures/${facture.id}/send_whatsapp/`, { phone: phone })
            toast.success(response.data.detail || 'Ticket envoy├® par WhatsApp !')
        } catch (err) {
            toast.error(getApiErrorDetail(err, "Erreur lors de l'envoi WhatsApp"))
        } finally {
            setLoading(false)
        }
    }, [ui.ticketCaisse, t, setLoading])

    const handleOrdonnanceSave = useCallback(async (data: OrdonnanceData) => {
        setLoading(true);
        try {
            const lignesForBackend = data.lignes.map((ligne) => ({
                produit: ligne.produit_id,
                produit_nom: ligne.produit_nom,
                quantite: ligne.quantite,
                surveillance_category: ligne.surveillance_category
            }));
            const payload = {
                patient_nom: data.patient_nom,
                prescripteur_nom: data.prescripteur_nom,
                facture: ui.pendingOrdonnanceFacture?.id || null,
                lignes: lignesForBackend
            };
            await api.post('ordonnancier/', payload);
            toast.success(t('prescriptions:messages.save_success'));
            ui.setShowOrdonnanceModal(false);
            ui.setPendingOrdonnanceFacture(null);
        } catch (err) {
            toast.error(t('prescriptions:messages.save_error') + ": " + getApiErrorDetail(err, err instanceof Error ? err.message : 'Erreur'));
        } finally {
            setLoading(false);
        }
    }, [ui, t, setLoading])

    const handleQuantityShortcut = useCallback((qty: number) => {
        if (cart.lignesFacture.length > 0) {
            const lastLine = cart.lignesFacture[cart.lignesFacture.length - 1];
            secureUpdateQuantite(lastLine.produit.id, qty);
            toast.success(`Quantit├® mise ├á jour : ${qty} x ${lastLine.produit.name}`, { icon: '­ƒöó' });
        } else {
            toast.error("Aucun produit dans le panier pour appliquer une quantit├®");
        }
    }, [cart.lignesFacture, secureUpdateQuantite])

    const handleLotSelect = useCallback((allocations: LotAllocation[] | null) => {
        const product = ui.lotModal.product;
        if (!product) return
        cart.setLignesFacture(
            cart.lignesFacture.map((l) => {
                if (l.produit.id === product.id) {
                    if (!allocations || allocations.length === 0) {
                        return {
                            ...l,
                            lotId: null,
                            lotText: null,
                            lotExpiration: null,
                            lotSellingPrice: null,
                            lotAllocations: null,
                        }
                    }
                    if (allocations.length === 1) {
                        const alloc = allocations[0]
                        return {
                            ...l,
                            lotId: String(alloc.lotId),
                            lotText: alloc.lotText,
                            lotExpiration: alloc.lotExpiration || null,
                            lotSellingPrice: alloc.sellingPrice || null,
                            lotAllocations: allocations,
                        }
                    }
                    return {
                        ...l,
                        lotId: null,
                        lotText: `${allocations.length} lots`,
                        lotExpiration: null,
                        lotSellingPrice: null,
                        lotAllocations: allocations,
                    }
                }
                return l
            })
        )
        ui.closeLotModal()
        setTimeout(() => searchInputRef.current?.focus(), 100)
    }, [ui.lotModal.product, cart, ui.closeLotModal, searchInputRef])

    const _resetSaleDataOnly = useCallback(() => {
        cart.setLignesFacture([])
        clientsHook.setClientSearch('')
        clientsHook.setManualClientName('')
        clientsHook.setSelectedClient(null)
        const clientsDivers = clientsHook.clients.find((c: Client) => c.name.toLowerCase() === 'clients divers')
        clientsHook.setSelectedClient(clientsDivers ? clientsDivers.id : null)
        clientsHook.setUseManualClient(false)
        clientsHook.setManualClientName('')
        ui.setRemiseGlobale('0')
        ui.setRemiseMode('montant')
        clientsHook.setAyantDroitNom('')
        clientsHook.setAyantDroitMatricule('')
        clientsHook.setAyantDroitSociete('')
        clientsHook.setSelectedAyantDroit(null)
        clientsHook.setShowNewAyantDroit(false)
        productSearch.setSearchQuery('')
        ui.setTempOrdonnanceData(null)

        if (user?.id) {
            safeStorage.removeItem(`activeCartLignes_${user.id}`, 'local')
            safeStorage.removeItem(`activeSaleContext_${user.id}`, 'local')
        }

        // Auto-focus search input for next sale
        setTimeout(() => {
            if (searchInputRef.current) {
                searchInputRef.current.focus()
                searchInputRef.current.select()
            }
        }, 150)
    }, [cart, clientsHook, ui, productSearch, user, searchInputRef])

    const _resetSale = useCallback(() => {
        _resetSaleDataOnly()
    }, [_resetSaleDataOnly])

    const mettreEnAttente = useCallback(() => {
        if (cart.lignesFacture.length === 0) {
            setError('Impossible de mettre en attente une vente vide')
            return
        }
        if (pendingSales.ventesEnAttente.length >= 4) {
            setError('Maximum 4 ventes en attente atteint')
            return
        }
        const clientName = !clientsHook.useManualClient && clientsHook.selectedClient
            ? clientsHook.clients.find((c: Client) => c.id === clientsHook.selectedClient)?.name || ''
            : clientsHook.manualClientName

        const ayantDroitData = clientsHook.selectedAyantDroit || clientsHook.showNewAyantDroit || clientsHook.ayantDroitNom ? {
            id: clientsHook.selectedAyantDroit,
            nom: clientsHook.ayantDroitNom,
            matricule: clientsHook.ayantDroitMatricule,
            societe: clientsHook.ayantDroitSociete,
            showNew: clientsHook.showNewAyantDroit
        } : null

        pendingSales.savePendingSale({
            client: clientsHook.useManualClient ? null : clientsHook.selectedClient,
            clientName,
            useManualClient: clientsHook.useManualClient,
            manualClientName: clientsHook.manualClientName,
            lignes: cart.lignesFacture,
            remise: ui.remiseGlobale,
            remiseMode: ui.remiseMode,
            ayantDroit: ayantDroitData
        })
        _resetSale()
        toast.success('Vente mise en attente')
    }, [cart.lignesFacture, clientsHook, pendingSales, ui, setError, _resetSale])

    const annulerVente = useCallback(() => {
        if (cart.lignesFacture.length > 0) {
            ui.setConfirmModal({
                isOpen: true,
                message: t('facturation.messages.cancel_sale_confirm', { defaultValue: '├ètes-vous s├╗r de vouloir annuler cette vente en cours ? Tout le panier sera perdu.' }),
                onConfirm: () => _resetSale()
            })
            return
        }
        _resetSale()
    }, [cart.lignesFacture.length, ui, t, _resetSale])

    const restaurerVente = useCallback((id: number) => {
        const vente = pendingSales.ventesEnAttente.find((v) => v.id === id)
        if (!vente) return
        if (cart.lignesFacture.length > 0) {
            if (!window.confirm('Le panier actuel n\'est pas vide. Voulez-vous le remplacer par la vente en attente ?')) return
        }
        cart.setLignesFacture(vente.lignes)
        clientsHook.setUseManualClient(vente.useManualClient)
        clientsHook.setManualClientName(vente.manualClientName)
        ui.setRemiseGlobale(vente.remise)
        ui.setRemiseMode(vente.remiseMode)
        if (vente.client) clientsHook.setSelectedClient(vente.client)
        else clientsHook.setSelectedClient(null)
        if (vente.ayantDroit) {
            clientsHook.setSelectedAyantDroit(vente.ayantDroit.id)
            clientsHook.setAyantDroitNom(vente.ayantDroit.nom)
            clientsHook.setAyantDroitMatricule(vente.ayantDroit.matricule)
            clientsHook.setAyantDroitSociete(vente.ayantDroit.societe)
            clientsHook.setShowNewAyantDroit(vente.ayantDroit.showNew)
        }
        pendingSales.deletePendingSale(id)
        pendingSales.setShowPendingSales(false)
        toast.success(t('facturation:messages.save_success'))
    }, [pendingSales, cart, clientsHook, ui, t])

    const supprimerVenteEnAttente = useCallback((id: number) => {
        ui.setConfirmModal({
            isOpen: true,
            message: "Voulez-vous vraiment supprimer cette vente en attente ?",
            onConfirm: () => {
                pendingSales.deletePendingSale(id);
                ui.setConfirmModal(null);
                toast.success("Vente en attente supprim├®e");
            }
        });
    }, [ui, pendingSales])

    return {
        handleProforma,
        handleBonDeLivraison,
        handleImprimerFacture,
        handleConfirmPrintClientName,
        ouvrirModalPaiement,
        handleSendWhatsApp,
        handleOrdonnanceSave,
        handleQuantityShortcut,
        handleLotSelect,
        _resetSaleDataOnly,
        _resetSale,
        mettreEnAttente,
        annulerVente,
        restaurerVente,
        supprimerVenteEnAttente
    }
}

import { useCallback } from 'react'
import api from '../services/api'
import { toast } from 'react-hot-toast'
import type { ProduitModel } from '../types'

export interface UseFacturationImportOptions {
    cart: {
        bulkAddProduits: (items: { product: ProduitModel; quantity: number; discountPercent: string }[]) => void
    }
    apiBaseUrl: string
    t: (key: string, options?: unknown) => string
}

export function useFacturationImport({ cart, t }: UseFacturationImportOptions) {
    // Pack Addition
    const addPackToFacture = useCallback(async (pack: unknown) => {
        if (!pack.pack_items || pack.pack_items.length === 0) {
            toast.error(t('facturation:messages.pack_empty'))
            return
        }
        const toastId = toast.loading(t('facturation:messages.adding_pack'))
        try {
            const itemPromises = pack.pack_items.map(async (item: unknown) => {
                try {
                    const { data: product } = await api.get<ProduitModel>(`produits/${item.product}/`)
                    return { product, quantity: item.quantity }
                } catch {
                    return null
                }
            })
            const results = await Promise.all(itemPromises)
            const items = results.filter(i => i !== null) as { product: ProduitModel, quantity: number }[]

            if (items.length === 0) {
                toast.error(t('facturation:messages.pack_items_error'), { id: toastId })
                return
            }
            const totalNormalPrice = items.reduce((sum, item) => sum + (Number(item.product.selling_price) * item.quantity), 0)
            const packPrice = Number(pack.value)
            const ratio = totalNormalPrice > 0 ? packPrice / totalNormalPrice : 1

            const itemsToBulkAdd = items.map(({ product, quantity }) => {
                return {
                    product,
                    quantity,
                    discountPercent: ratio < 1 ? (Math.round((1 - ratio) * 10000) / 100).toFixed(0) : '0'
                }
            })
            cart.bulkAddProduits(itemsToBulkAdd)
            toast.success(t('facturation.messages.pack_added', { name: pack.name }), { id: toastId })
        } catch {
            toast.error(t('facturation.messages.pack_error'), { id: toastId })
        }
    }, [cart.bulkAddProduits, t])

    // CSV Import
    const handleCsvImport = useCallback(async (file: File) => {
        const toastId = toast.loading('Analyse et importation du fichier CSV...');
        try {
            const text = await file.text();
            const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
            if (lines.length === 0) {
                toast.error('Le fichier CSV est vide.', { id: toastId });
                return;
            }
            const params: { identifiers: string[], quantities: Record<string, number> } = {
                identifiers: [],
                quantities: {}
            };
            for (let i = 0; i < lines.length; i++) {
                const parts = lines[i].split(/[,;]/).map(s => s.trim());
                if (parts.length >= 2) {
                    const identifier = parts[0];
                    if (identifier.toLowerCase() === 'cip' || identifier.toLowerCase() === 'id') continue;
                    const quantity = parseInt(parts[1], 10);
                    if (identifier && !isNaN(quantity) && quantity > 0) {
                        params.identifiers.push(identifier);
                        params.quantities[identifier] = quantity;
                    }
                }
            }
            if (params.identifiers.length === 0) {
                toast.error('Aucune donn├®e valide trouv├®e dans le CSV.', { id: toastId });
                return;
            }
            let fetchedProducts: ProduitModel[] = [];
            try {
                const res = await api.post('produits/bulk_search/', { identifiers: params.identifiers });
                fetchedProducts = res.data;
            } catch {
                const productPromises = params.identifiers.map(async (ident) => {
                    try {
                        const res = await api.get('produits/', { params: { search: ident } });
                        const results = res.data.results || res.data;
                        if (results && results.length > 0) {
                            const match = results.find((p: unknown) => p.cip1 === ident || String(p.id) === ident) || results[0];
                            return { identifier: ident, product: match };
                        }
                    } catch { return null; }
                    return null;
                });
                const results = await Promise.all(productPromises);
                const items = results.filter(i => i !== null) as { identifier: string; product: ProduitModel }[];
                fetchedProducts = items.map(i => {
                    (i.product as unknown)._matched_identifier = i.identifier;
                    return i.product;
                });
            }
            if (fetchedProducts.length === 0) {
                toast.error('Aucun produit correspondant trouv├®.', { id: toastId });
                return;
            }
            const itemsToBulkAdd = fetchedProducts.map(product => {
                const identifier = (product as unknown)._matched_identifier || product.cip1 || String(product.id);
                const qty = params.quantities[identifier] || 1;
                return {
                    product,
                    quantity: qty,
                    discountPercent: '0'
                }
            });
            cart.bulkAddProduits(itemsToBulkAdd);
            toast.success(`${itemsToBulkAdd.length} produit(s) import├®(s).`, { id: toastId });
        } catch {
            toast.error("Erreur lecture CSV.", { id: toastId });
        }
    }, [cart.bulkAddProduits])

    return {
        addPackToFacture,
        handleCsvImport
    }
}

