import { useState, useEffect, useMemo, useCallback, useRef } from 'react'
import api from '../services/api'
import { toast } from 'react-hot-toast'
import { useQueryClient } from '@tanstack/react-query'
import type { ProduitModel, Facture, LigneFacture, PaginatedResponse } from '../types'
import type { SaleCompletionResult } from '../types/finance'
import { useProductSearch } from './useProductSearch'
import { useCart } from './useCart'
import { useAuth } from '../context/AuthContext'
import { useFacturationClients } from './useFacturationClients'
import { usePendingSales } from './usePendingSales'
import { usePharmacySettings } from './usePharmacySettings'
import { useKeyboardNavigation } from './useKeyboardNavigation'
import { useClinicalCheck } from './useClinicalCheck'
import { useSidebar } from './useSidebar'
import { useTranslation } from 'react-i18next'
import { useSudo } from './useSudo'
import useSaleCompletion from './useSaleCompletion'
import { useFacturationKeyboardShortcuts } from './useFacturationKeyboardShortcuts'
import { useFacturationUI } from './useFacturationUI'
import { useFacturationSession } from './useFacturationSession'
import { useFacturationActions } from './useFacturationActions'
import { useMultiCaisse } from './useMultiCaisse'
import { useSecureCartOperations } from './useSecureCartOperations'
import { useDevisLoader } from './useDevisLoader'
import { useFacturationImport } from './useFacturationImport'

export function useFacturationState() {
  const { t } = useTranslation(['prescriptions', 'common', 'facturation', 'sales'])
  const queryClient = useQueryClient()
  const { settings: pharmacySettings } = usePharmacySettings()
  const { isZenithMode, toggleZenithMode, isMidnightTheme, toggleMidnightTheme } = useSidebar()
  const { user } = useAuth()

  // --- Core local state ---
  const [loading, setLoading] = useState(false)
  const [isRetrocession, setIsRetrocession] = useState(false)
  const [isFactureA4, setIsFactureA4] = useState(false)
  const [sortBy, setSortBy] = useState<'chrono' | 'stock' | 'name' | 'qty'>('chrono')

  const [error, setError] = useState<string | null>(null)
  const [successInfo, setSuccessInfo] = useState<Facture | null>(null)
  const [showClientNameModal, setShowClientNameModal] = useState(false)
  const [pendingPrintFacture, setPendingPrintFacture] = useState<Facture | null>(null)
  const [pointsToUse, setPointsToUse] = useState(0)
  const [usePendingDiscount, setUsePendingDiscount] = useState(false)
  const [showHelp, setShowHelp] = useState(false)
  const [substitutionProduct, setSubstitutionProduct] = useState<ProduitModel | null>(null)
  const [forceStockProduct, setForceStockProduct] = useState<ProduitModel | null>(null)

  const [refreshTrigger, setRefreshTrigger] = useState(0)
  const triggerUiRefresh = useCallback(() => {
    setRefreshTrigger(prev => prev + 1)
  }, [])

  // --- Refs ---
  const quantityInputsRef = useRef<Map<number, HTMLInputElement>>(new Map())
  const addProductRef = useRef<((product: ProduitModel, options?: { isRetrocession?: boolean; preventFocus?: boolean; markupPercentage?: number }) => void) | null>(null)
  const searchInputRef = useRef<HTMLInputElement>(null)
  const paymentInputRef = useRef<HTMLInputElement>(null)
  const clientSearchRef = useRef<HTMLInputElement>(null)

  // --- Sudo ---
  const { sudoState, requireSudo, closeSudo } = useSudo()
  const [activeSudoCreds, setActiveSudoCreds] = useState<{ validatorId: number, password: string } | null>(null)

  // --- UI Hook ---
  const ui = useFacturationUI()

  // --- Cart Hook ---
  const cart = useCart({
    onRequirePrescription: () => ui.setShowOrdonnanceModal(true),
    onAlert: (message, title, type, is_blocking, targetId) => ui.pushDisplayAlert({ message, title, type, is_blocking, targetId }),
    onSubstitution: (produit) => setSubstitutionProduct(produit),
    onForceStock: (produit) => setForceStockProduct(produit),
    quantityInputsRef
  })

  // --- Secure Cart Operations (sudo-protected) ---
  const maxDiscountRate = user?.is_superuser ? 100 : (Number(user?.profile?.max_discount_rate || 0))
  const { secureUpdateQuantite, secureUpdatePrix, secureUpdateRemiseProduit, secureSetRemiseGlobale } = useSecureCartOperations({
    cart,
    requireSudo,
    setActiveSudoCreds,
    activeSudoCreds,
    t,
    triggerUiRefresh,
    maxDiscountRate
  })

  // --- Clinical Check ---
  const { alerts: clinicalAlerts } = useClinicalCheck(cart.lignesFacture)

  // --- Clients ---
  const clientsHook = useFacturationClients()
  const pendingSales = usePendingSales()

  const currentMarkup = useMemo(() => {
    if (!clientsHook.selectedClient || clientsHook.useManualClient) return 0
    const client = clientsHook.clients.find(c => c.id === clientsHook.selectedClient)
    if (client?.client_type === 'PROFESSIONNEL') {
      return Number(client.majoration_pro_pourcentage || 0)
    }
    return 0
  }, [clientsHook.selectedClient, clientsHook.clients, clientsHook.useManualClient])

  // --- Barcode scanning ---
  addProductRef.current = cart.addProduit

  const handleBarcodeMatch = useCallback((product: ProduitModel) => {
    if (addProductRef.current) {
      addProductRef.current(product, { isRetrocession, preventFocus: true, markupPercentage: currentMarkup })
      toast.success(t('facturation:messages.scan_added', { name: product.name }), { duration: 1500 })
    }
  }, [isRetrocession, t, currentMarkup])

  const productSearch = useProductSearch({
    minSearchLength: 2,
    debounceMs: 400,
    pageSize: 1000,
    onBarcodeMatch: handleBarcodeMatch
  })

  // --- Import (CSV + Packs) ---
  const { addPackToFacture, handleCsvImport } = useFacturationImport({
    cart,
    apiBaseUrl: '',
    t
  })

  // Apply markup when client changes
  useEffect(() => {
    if (cart.lignesFacture.length > 0) {
      cart.applyMarkupToCart(currentMarkup)
    }
  }, [currentMarkup, cart.applyMarkupToCart])

  // --- Session Persistence (auto-save / restore) ---
  useFacturationSession({
    clientsHook,
    ui,
    isRetrocession,
    setIsRetrocession,
    isFactureA4,
    setIsFactureA4,
    cartLength: cart.lignesFacture.length
  })

  // --- Multi-Caisse ---
  const multiCaisse = useMultiCaisse({})

  // --- Devis Loader (on mount) ---
  useDevisLoader({ clientsHook, cart, ui })

  // --- Totals ---
  const totals = useMemo(() =>
    ui.calculateTotals(cart.cartStats, clientsHook.clients.find(c => c.id === clientsHook.selectedClient)),
    [cart.cartStats, clientsHook.selectedClient, clientsHook.clients, ui.calculateTotals]
  )

  const isNewSale = !ui.facturePourPaiement

  // --- Actions ---
  const actions = useFacturationActions({
    cart,
    clientsHook,
    ui,
    totals,
    pendingSales,
    setLoading,
    setError,
    t,
    productSearch,
    searchInputRef,
    paymentInputRef,
    pendingPrintFacture,
    setPendingPrintFacture,
    setShowClientNameModal,
    secureUpdateQuantite,
    user,
    myActivePoste: multiCaisse.myActivePoste,
    postesCaisses: multiCaisse.postesCaisses
  })

  // --- Sale Completion ---
  const { completeSale, completeExistingInvoicePayment, loading: saleLoading } = useSaleCompletion({
    onSuccess: (result: SaleCompletionResult) => {
      if (result.success && result.facture) {
        // Notification visuelle uniquement si vente pay├®e directement (pas en attente caisse centralis├®e)
        if (result.ticketCaisse) {
          setSuccessInfo(result.facture)
          ui.setTicketCaisse(result.ticketCaisse)

          if (isFactureA4) {
            const normalize = (str: string) => str?.toLowerCase().trim() || ''
            const clientName = normalize(result.facture.client_name || '')
            const isGenericClient = !result.facture.client_name_override && (
              !clientName || clientName.includes('passage') || clientName.includes('divers')
            )
            if (isGenericClient) {
              setPendingPrintFacture(result.facture)
              setShowClientNameModal(true)
            } else {
              const nameToUse = result.facture.client_name_override || result.facture.client_name
              let url = `/app/print-invoice/${result.facture.id}`
              if (nameToUse) url += `?client_name=${encodeURIComponent(nameToUse)}`
              const w = window.open(url, '_blank')
              if (!w) toast.error('Popup bloqu├®. Autorisez les popups pour imprimer.')
            }
            setIsFactureA4(false)
          } else {
            ui.setShowTicketPreview(true)
          }
        } else {
          // Envoi caisse centralis├®e ÔÇö reset du flag facture
          if (isFactureA4) {
            setIsFactureA4(false)
          }
        }

        ui.resetUIState()

        // Mettre ├á jour le cache stock dans tous les cas
        cart.lignesFacture.forEach((ligne: LigneFacture) => {
          queryClient.setQueriesData({ queryKey: ['produits'] }, (oldData: PaginatedResponse<ProduitModel> | ProduitModel[] | undefined) => {
            if (!oldData) return oldData
            if (!Array.isArray(oldData) && oldData.results && Array.isArray(oldData.results)) {
              return {
                ...oldData,
                results: oldData.results.map((p: ProduitModel) =>
                  p.id === ligne.produit.id ? { ...p, stock: Math.max(0, (p.stock || 0) - ligne.quantite) } : p
                )
              }
            } else if (Array.isArray(oldData)) {
              return (oldData as ProduitModel[]).map((p: ProduitModel) =>
                p.id === ligne.produit.id ? { ...p, stock: Math.max(0, (p.stock || 0) - ligne.quantite) } : p
              )
            }
            return oldData
          })
          queryClient.setQueriesData({ queryKey: ['produit', ligne.produit.id] }, (oldData: ProduitModel | undefined) => {
            if (!oldData) return oldData
            return { ...oldData, stock: Math.max(0, (oldData.stock || 0) - ligne.quantite) }
          })
        })

        actions._resetSaleDataOnly()
        setActiveSudoCreds(null)
        ui.closePaymentModal()
      }
    },
    onReset: () => {
      actions._resetSaleDataOnly()
      setActiveSudoCreds(null)
    },
    onError: (msg: string) => setError(msg)
  })

  const isPosteCaisseActive = Boolean(multiCaisse.myActivePoste)
  const hasActiveCaisse = multiCaisse.activePostesVente.some((p) => !!p.caisse)
  const hasMyActivePoste = multiCaisse.activePostesVente.some((p) => p.vendeur === user?.id)

  // --- Complete Sale Handler ---
  const handleCompleteSale = async (sudoCredentials?: { validatorId: number, password: string }) => {
    // En mode caisse centrale, une caisse doit ├¬tre ouverte avant toute vente
    if (multiCaisse.centralizedCashRegister && !hasActiveCaisse) {
      setError(t('facturation:messages.no_cash_register_open'))
      return
    }

    // Sudo required when sending to centralized cash register or when selling on an opened cash register point
    if ((multiCaisse.centralizedCashRegister || isPosteCaisseActive) && !sudoCredentials) {
      requireSudo(async (validatorId, password) => {
        await handleCompleteSale({ validatorId, password })
      }, {
        title: isPosteCaisseActive ? 'Validation vendeur' : t('facturation:payment.sudo_confirm_identity'),
        message: isPosteCaisseActive
          ? 'Ce poste est partag├®. Veuillez saisir vos identifiants de vendeur pour cette vente.'
          : t('facturation:payment.sudo_send_to_caisse'),
        forceCurrentUser: false,
      })
      return
    }

    const effectiveSudo = sudoCredentials || activeSudoCreds

    // En mode caisse centrale, les ventes des POS convergent vers le point de caisse ouvert.
    // On cherche uniquement parmi les postes qui ont une caisse physique (caisse non null).
    const activeCaissePosteVente = multiCaisse.centralizedCashRegister
      ? multiCaisse.activePostesVente.find((p) => p.caisse && p.caisse === multiCaisse.selectedPosteCaisseId)
        ?? multiCaisse.activePostesVente.find((p) => !!p.caisse)
      : null

    const posteVenteId = multiCaisse.centralizedCashRegister
      ? (activeCaissePosteVente?.id ?? null)
      : (multiCaisse.myActivePoste?.id ?? null)

    const params = {
      selectedClient: clientsHook.selectedClient,
      useManualClient: clientsHook.useManualClient,
      manualClientName: clientsHook.manualClientName,
      clients: clientsHook.clients,
      selectedAyantDroit: clientsHook.selectedAyantDroit,
      ayantDroitNom: clientsHook.ayantDroitNom,
      ayantDroitMatricule: clientsHook.ayantDroitMatricule,
      ayantDroitSociete: clientsHook.ayantDroitSociete,
      ayantsDroitList: clientsHook.ayantsDroitList,
      showNewAyantDroit: clientsHook.showNewAyantDroit,
      lignesFacture: cart.lignesFacture,
      totals: totals,
      modePaiement: ui.modePaiement,
      montantPaye: ui.montantPaye,
      paiements: ui.paiements,
      reference: ui.reference,
      couponNumero: '',
      usePendingDiscount,
      pointsToUse,
      isRetrocession,
      centralizedCashRegister: multiCaisse.centralizedCashRegister,
      isModificationMode: ui.isModificationMode,
      devisIdToValidate: null,
      tempOrdonnanceData: ui.tempOrdonnanceData,
      validated_by_id: effectiveSudo?.validatorId || null,
      sudo_password: effectiveSudo?.password || undefined,
      modificationInvoiceStatus: ui.modificationInvoiceStatus || undefined,
      poste_vente_id: posteVenteId,
      prescriptionImage: ui.prescriptionImage,
      modificationInvoiceId: ui.modificationInvoiceId,
      isFactureA4: isFactureA4,
      is_avoir_client: ui.isAvoirClient
    }
    await completeSale(params)
  }

  const applyLoyaltyReward = useCallback(() => {
    if (!clientsHook.selectedClient || clientsHook.useManualClient) return
    const client = clientsHook.clients.find(c => c.id === clientsHook.selectedClient)
    if (client?.pending_discount && Number(client.pending_discount) > 0) {
      ui.setRemiseGlobale(client.pending_discount)
      ui.setRemiseMode('taux')
      setUsePendingDiscount(true)
      toast.success(t('facturation:messages.reward_applied', { discount: client.pending_discount }))
    }
  }, [clientsHook.selectedClient, clientsHook.clients, clientsHook.useManualClient, ui, t])

  // --- Payment Preparation ---
  const handlePaymentClick = async () => {
    setLoading(true)
    let freshLignes = cart.lignesFacture
    try {
      const productIds = cart.lignesFacture.map((l: LigneFacture) => l.produit.id)
      const { data: freshProductsData } = await api.post<ProduitModel[]>('produits/bulk_refresh/', { ids: productIds })

      const productMap = new Map(freshProductsData.map((p: ProduitModel) => [p.id, p]))
      freshLignes = cart.lignesFacture.map((ligne: LigneFacture) => {
        const freshProduct = productMap.get(ligne.produit.id)
        if (freshProduct) {
          return {
            ...ligne,
            isPromis: ligne.isPromis,
            promisQuantity: ligne.promisQuantity,
            promisPhone: ligne.promisPhone,
            produit: { ...ligne.produit, stock: freshProduct.stock, selling_price: freshProduct.selling_price, is_active: freshProduct.is_active }
          }
        }
        return ligne
      })
    } catch {
      toast.error(t('facturation.messages.refresh_failed') || "Erreur de rafra├«chissement des stocks")
    }

    cart.setLignesFacture(freshLignes)
    setLoading(false)

    const problematicLines = freshLignes.filter((l: LigneFacture) => !l.isPromis && l.quantite > (l.produit.stock ?? 0))

    if (problematicLines.length > 0) {
      const items = problematicLines.map((l: LigneFacture) => ({ product: l.produit, quantity: l.quantite, stock: l.produit.stock ?? 0 }))
      ui.setStockResolutionItems(items)

      const initialActions: Record<number, 'promis' | 'force' | 'reduce'> = {}
      items.forEach(item => {
        initialActions[item.product.id] = 'promis'
      })
      ui.setResolutionActions(initialActions)

      const client = clientsHook.clients.find(c => c.id === clientsHook.selectedClient)
      ui.setPromisPhone(client?.phone || '')
      if (clientsHook.useManualClient) {
        ui.setPromisClientName(clientsHook.manualClientName)
      } else if (client) {
        ui.setPromisClientName(client.name)
      } else {
        ui.setPromisClientName('')
      }
      ui.setShowStockResolution(true)
    } else {
      const totalTtc = totals.totalTtc

      if (totalTtc <= 0) {
        // Enforce sudo for non-positive sales
        if (activeSudoCreds) {
          await handleCompleteSale(activeSudoCreds)
        } else {
          requireSudo(async (validatorId, password) => {
            await handleCompleteSale({ validatorId, password })
          }, {
            title: t('facturation:payment.sudo_mode.validate_by'),
            message: `Cette vente avec un total de ${totalTtc} F n├®cessite l'autorisation d'un superviseur.`
          })
        }
      } else {
        const montantInitial = (totals.tauxCouverture > 0) ? totals.partPatient : totalTtc
        ui.setMontantPaye(montantInitial.toString())
        ui.openPaymentModal()
      }
    }
  }

  const handlePaymentClickWithSudo = (updatedLignes?: LigneFacture[], sudoCredentials?: { validatorId: number, password: string }) => {
    if (updatedLignes && updatedLignes.length > 0) {
      cart.setLignesFacture(updatedLignes)
    }
    if (sudoCredentials) {
      setActiveSudoCreds(sudoCredentials)
    }
    const montantInitial = (totals.tauxCouverture > 0) ? totals.partPatient : totals.totalTtc
    ui.setMontantPaye(montantInitial.toString())
    ui.openPaymentModal()
  }

  // --- Auto-focus on mount ---
  useEffect(() => {
    const timer = setTimeout(() => searchInputRef.current?.focus(), 300)
    return () => clearTimeout(timer)
  }, [])

  // --- Client auto-discount & alerts ---
  useEffect(() => {
    if (!clientsHook.selectedClient || clientsHook.useManualClient) return
    const client = clientsHook.clients.find(c => c.id === clientsHook.selectedClient)
    if (client?.remise_automatique && Number(client.remise_automatique) > 0) {
      ui.setRemiseGlobale(client.remise_automatique)
      ui.setRemiseMode('taux')
    }
    if (client?.message_alerte) {
      ui.pushDisplayAlert({
        message: client.message_alerte,
        title: client.name,
        type: 'client',
        is_blocking: !!client.blocking_alerte
      })
    }
  }, [clientsHook.selectedClient, clientsHook.clients, clientsHook.useManualClient])

  // --- Reset loyalty/discount on client change ---
  useEffect(() => {
    setPointsToUse(0)
    setUsePendingDiscount(false)
  }, [clientsHook.selectedClient, isNewSale])

  // --- Sorting ---
  const sortedLignes = useMemo(() => {
    if (sortBy === 'chrono') return cart.lignesFacture
    return cart.lignesFacture.slice().sort((a: LigneFacture, b: LigneFacture) => {
      if (sortBy === 'name') return (a.produit.name || '').localeCompare(b.produit.name || '')
      if (sortBy === 'stock') return (b.produit.stock || 0) - (a.produit.stock || 0)
      if (sortBy === 'qty') return b.quantite - a.quantite
      return 0
    })
  }, [cart.lignesFacture, sortBy])

  // --- Keyboard Navigation ---
  const handleIncrement = useCallback((index: number) => {
    if (sortedLignes[index]) {
      const pId = sortedLignes[index].produit.id
      const currentQty = sortedLignes[index].quantite
      cart.updateQuantite(pId, currentQty + 1)
    }
  }, [sortedLignes, cart.updateQuantite])

  const handleDecrement = useCallback((index: number) => {
    if (sortedLignes[index]) {
      const pId = sortedLignes[index].produit.id
      const currentQty = sortedLignes[index].quantite
      if (currentQty > 1) {
        cart.updateQuantite(pId, currentQty - 1)
      }
    }
  }, [sortedLignes, cart.updateQuantite])

  const handleDeleteLine = useCallback((index: number) => {
    if (sortedLignes[index]) {
      cart.removeLigne(sortedLignes[index].produit.id)
    }
  }, [sortedLignes, cart.removeLigne])

  const handleValidateShortcut = useCallback(() => {
    if (cart.lignesFacture.length > 0) {
      handlePaymentClick()
    } else {
      toast.error(t('facturation.messages.cart_empty'))
    }
  }, [cart.lignesFacture.length, handlePaymentClick, t])

  const keyboardNav = useKeyboardNavigation({
    listLength: sortedLignes.length,
    onValidate: handleValidateShortcut,
    onIncrement: handleIncrement,
    onDecrement: handleDecrement,
    onDelete: handleDeleteLine,
    enabled: !ui.isPaymentModalOpen && !ui.showOrdonnanceModal && !clientsHook.showClientCreateModal && !ui.lotModal.isOpen && !ui.showStockResolution
  })

  // --- Alert Message Handler ---
  const handleAddAlertMessage = useCallback(() => {
    if (keyboardNav.selectedIndex >= 0 && sortedLignes[keyboardNav.selectedIndex]) {
      const ligne = sortedLignes[keyboardNav.selectedIndex]
      ui.setAlertTarget({
        type: 'product',
        id: ligne.produit.id,
        name: ligne.produit.name,
        currentMessage: ligne.produit.message_alerte || ''
      })
      ui.setIsAlertModalOpen(true)
      return
    }

    if (clientsHook.selectedClient && !clientsHook.useManualClient) {
      const client = clientsHook.clients.find(c => c.id === clientsHook.selectedClient)
      if (client) {
        ui.setAlertTarget({
          type: 'client',
          id: client.id,
          name: client.name,
          currentMessage: client.message_alerte || ''
        })
        ui.setIsAlertModalOpen(true)
      }
    }
  }, [keyboardNav.selectedIndex, sortedLignes, clientsHook.selectedClient, clientsHook.useManualClient, clientsHook.clients, ui.setAlertTarget, ui.setIsAlertModalOpen])

  // --- Keyboard Shortcuts ---
  useFacturationKeyboardShortcuts({
    searchInputRef,
    clientSearchRef,
    lignesFacture: cart.lignesFacture,
    quantityInputsRef,
    handlePaymentClick,
    toggleZenithMode,
    isPaymentModalOpen: ui.isPaymentModalOpen,
    closePaymentModal: ui.closePaymentModal,
    showTicketPreview: ui.showTicketPreview,
    setShowTicketPreview: ui.setShowTicketPreview,
    showOrdonnanceModal: ui.showOrdonnanceModal,
    setShowOrdonnanceModal: ui.setShowOrdonnanceModal,
    lotModalOpen: ui.lotModal.isOpen,
    closeLotModal: ui.closeLotModal,
    showClientCreateModal: clientsHook.showClientCreateModal,
    setShowClientCreateModal: clientsHook.setShowClientCreateModal,
    showStockResolution: ui.showStockResolution,
    setShowStockResolution: ui.setShowStockResolution,
    confirmModal: ui.confirmModal,
    setConfirmModal: ui.setConfirmModal,
    setSearchQuery: productSearch.setSearchQuery,
    successInfo,
    setSuccessInfo,
    setShowHelp,
    handleSuspendSale: actions.mettreEnAttente,
    handleAddAlertMessage,
    showPendingSales: pendingSales.showPendingSales,
    setShowPendingSales: pendingSales.setShowPendingSales
  })

  return {
    t,
    isZenithMode, toggleZenithMode,
    isMidnightTheme, toggleMidnightTheme,
    loading: loading || saleLoading,
    error, setError,
    successInfo, setSuccessInfo,
    refreshTrigger,
    showClientNameModal, setShowClientNameModal,
    pendingPrintFacture, setPendingPrintFacture,
    showHelp, setShowHelp,

    // Core state
    isRetrocession, setIsRetrocession,
    isFactureA4, setIsFactureA4,
    sortBy, setSortBy,
    isMultiCaisse: multiCaisse.isMultiCaisse, setIsMultiCaisse: multiCaisse.setIsMultiCaisse,
    centralizedCashRegister: multiCaisse.centralizedCashRegister,
    postesCaisses: multiCaisse.postesCaisses, setPostesCaisses: multiCaisse.setPostesCaisses,
    activePostesVente: multiCaisse.activePostesVente, setActivePostesVente: multiCaisse.setActivePostesVente,
    selectedPosteCaisseId: multiCaisse.selectedPosteCaisseId, setSelectedPosteCaisseId: multiCaisse.setSelectedPosteCaisseId,
    activePoste: multiCaisse.myActivePoste,
    isPosteCaisseActive,
    hasMyActivePoste,
    allPostes: multiCaisse.postesCaisses,
    lignesFacture: cart.lignesFacture,
    sortedLignes,
    totals,
    isModificationMode: ui.isModificationMode,
    modificationInvoiceId: ui.modificationInvoiceId,
    originalTotalTtc: ui.originalTotalTtc,
    setOriginalTotalTtc: ui.setOriginalTotalTtc,
    setIsModificationMode: ui.setIsModificationMode,
    setModificationInvoiceId: ui.setModificationInvoiceId,
    setLignesFacture: cart.setLignesFacture,
    isNewSale,

    // Modals and Drawers
    showOrdonnanceModal: ui.showOrdonnanceModal,
    setShowOrdonnanceModal: ui.setShowOrdonnanceModal,
    pendingOrdonnanceFacture: ui.pendingOrdonnanceFacture,
    setPendingOrdonnanceFacture: ui.setPendingOrdonnanceFacture,
    tempOrdonnanceData: ui.tempOrdonnanceData,
    showTicketPreview: ui.showTicketPreview,
    setShowTicketPreview: ui.setShowTicketPreview,
    ticketCaisse: ui.ticketCaisse,
    showPendingSales: pendingSales.showPendingSales,
    setShowPendingSales: pendingSales.setShowPendingSales,
    ventesEnAttente: pendingSales.ventesEnAttente,
    confirmModal: ui.confirmModal,
    setConfirmModal: ui.setConfirmModal,
    lotModal: ui.lotModal,
    closeLotModal: ui.closeLotModal,
    showStockResolution: ui.showStockResolution,
    setShowStockResolution: ui.setShowStockResolution,

    // Actions
    handleCompleteSale,
    handleProforma: actions.handleProforma,
    handleBonDeLivraison: actions.handleBonDeLivraison,
    addPackToFacture,
    mettreEnAttente: actions.mettreEnAttente,
    annulerVente: actions.annulerVente,
    restaurerVente: actions.restaurerVente,
    supprimerVenteEnAttente: actions.supprimerVenteEnAttente,
    handlePaymentClick,
    handlePaymentClickWithSudo,
    ouvrirModalPaiement: actions.ouvrirModalPaiement,
    handleSendWhatsApp: actions.handleSendWhatsApp,
    handleImprimerFacture: actions.handleImprimerFacture,
    handleConfirmPrintClientName: actions.handleConfirmPrintClientName,
    handleOrdonnanceSave: actions.handleOrdonnanceSave,
    handleLotSelect: actions.handleLotSelect,
    handleQuantityShortcut: actions.handleQuantityShortcut,
    handleCsvImport,
    removeLigne: cart.removeLigne,
    secureUpdateQuantite,
    secureUpdatePrix,
    secureUpdateRemiseProduit,
    secureSetRemiseGlobale,
    completeExistingInvoicePayment,

    // Sub-hooks exposed state
    clientsHook,
    productSearch,
    cart,
    ui,
    pendingSales,
    sudoState,
    requireSudo,
    closeSudo,
    clinicalAlerts,
    keyboardNav,
    pharmacySettings,

    currentMarkup,
    // Substitution
    substitutionProduct,
    setSubstitutionProduct,
    // Force stock
    forceStockProduct,
    setForceStockProduct,
    // Refs
    searchInputRef,
    clientSearchRef,
    quantityInputsRef,
    paymentInputRef,
    applyLoyaltyReward,
    user
  }
}

import { useEffect, useState, useMemo, useCallback, type FormEvent, useRef, type KeyboardEvent } from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation } from 'react-router-dom';
import api from '../services/api';
import { useConfirm } from './useConfirm';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-hot-toast';
import { getApiErrorDetail } from '../utils/errorHandling';
import type { Fournisseur, PaginatedResponse } from '../types';
import { useSudo } from './useSudo';

export interface CatalogueItem {
  produit_id: number;
  produit_nom: string;
  cip: string;
  dernier_prix_achat: number;
  derniere_commande: string | null;
  prix_vente: number;
  marge: number;
  marge_pourcent: number;
  qte_totale: number;
  stock_actuel: number;
}

export interface CatalogueResponse {
  fournisseur_id: number;
  fournisseur_nom: string;
  total_produits: number;
  produits: CatalogueItem[];
}

export const emptyForm: Omit<Fournisseur, 'id'> = {
  name: '',
  address: '',
  phone: '',
  email: '',
  type_reglement: 'FACTURE',
  delai_paiement_jours: 0,
  periode_releve_jours: 10,
};

export function useFournisseurs() {
  const { t } = useTranslation(['providers', 'common']);
  const location = useLocation();
  const confirm = useConfirm()
  const { user } = useAuth();

  const [fournisseurs, setFournisseurs] = useState<Fournisseur[]>([]);
  const [selectedFournisseur, setSelectedFournisseur] = useState<Fournisseur | null>(null);
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const itemsPerPage = 50;

  // Sudo Mode State
  const { sudoState, requireSudo, closeSudo } = useSudo();

  const [error, setError] = useState<string | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState<boolean>(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState<boolean>(false);
  const [newFournisseur, setNewFournisseur] = useState(emptyForm);
  const [editingFournisseur, setEditingFournisseur] = useState<Fournisseur | null>(null);
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);

  const [searchTerm, setSearchTerm] = useState<string>('');
  const [debouncedSearch, setDebouncedSearch] = useState<string>('');
  const [highlightedIndex, setHighlightedIndex] = useState<number>(-1);
  const searchInputRef = useRef<HTMLInputElement>(null);

  // Catalogue state
  const [catalogue, setCatalogue] = useState<CatalogueItem[]>([]);
  const [catalogueLoading, setCatalogueLoading] = useState<boolean>(false);
  const [catalogueSearch, setCatalogueSearch] = useState<string>('');
  const [showCatalogue, setShowCatalogue] = useState<boolean>(true);
  const [showInactive, setShowInactive] = useState<boolean>(false);

  const [financeModalState, setFinanceModalState] = useState<{
    isOpen: boolean;
    prefilledMontant?: number;
    commandeIds?: number[];
  }>({ isOpen: false });
  const [isEcheancierModalOpen, setIsEcheancierModalOpen] = useState(false);
  const [isPointageModalOpen, setIsPointageModalOpen] = useState(false);

  // Debounce search term to prevent excessive API calls
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setCurrentPage(1); // Reset page on new search
    }, 300);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  // Auto-refresh selectedFournisseur when list changes
  useEffect(() => {
    if (selectedFournisseur) {
      const updated = fournisseurs.find(f => f.id === selectedFournisseur.id);
      if (updated && updated !== selectedFournisseur) {
        setSelectedFournisseur(updated);
      }
    }
  }, [fournisseurs]); // Ô£à Retir├® selectedFournisseur des d├®pendances

  const totalPages = Math.max(1, Math.ceil(totalCount / itemsPerPage));

  const filteredCatalogue = useMemo(() => {
    if (!catalogueSearch.trim()) return catalogue;
    const term = catalogueSearch.toLowerCase();
    return catalogue.filter((item: CatalogueItem) => 
      item.produit_nom.toLowerCase().includes(term) ||
      item.cip.toLowerCase().includes(term)
    );
  }, [catalogue, catalogueSearch]);

  const catalogueControllerRef = useRef<AbortController | null>(null);

  const fetchCatalogue = useCallback(async (fournisseurId: number) => {
    catalogueControllerRef.current?.abort();
    const controller = new AbortController();
    catalogueControllerRef.current = controller;

    setCatalogueLoading(true);
    try {
      const response = await api.get<CatalogueResponse>(
        `fournisseurs/${fournisseurId}/catalogue/`,
        { signal: controller.signal }
      );
      setCatalogue(response.data.produits || []);
    } catch (err) {
      if (err instanceof Error && err.name === 'AbortError') return;
      console.error('Erreur lors du chargement du catalogue:', err);
      setCatalogue([]);
    } finally {
      setCatalogueLoading(false);
    }
  }, []);

  useEffect(() => {
    if (selectedFournisseur) {
      fetchCatalogue(selectedFournisseur.id as number);
      setCatalogueSearch('');
    } else {
      setCatalogue([]);
    }
    return () => catalogueControllerRef.current?.abort();
  }, [selectedFournisseur?.id, fetchCatalogue]);

  const fournisseursControllerRef = useRef<AbortController | null>(null);

  const fetchFournisseurs = useCallback(async () => {
    fournisseursControllerRef.current?.abort();
    const controller = new AbortController();
    fournisseursControllerRef.current = controller;

    setError(null);
    try {
      const response = await api.get('fournisseurs/', {
        params: { 
          include_inactive: showInactive,
          page: currentPage,
          page_size: itemsPerPage,
          search: debouncedSearch
        },
        signal: controller.signal,
      });
      const data = response.data as PaginatedResponse<Fournisseur> | Fournisseur[];
      if (Array.isArray(data)) {
         setFournisseurs(data);
         setTotalCount(data.length);
      } else if ('results' in data) {
         setFournisseurs(data.results);
         setTotalCount(data.count || 0);
      } else {
         setFournisseurs([]);
         setTotalCount(0);
      }
    } catch (err: unknown) {
      const axiosErr = err as { code?: string; response?: { data?: { message?: string } }; message?: string };
      if (axiosErr?.code === 'ERR_CANCELED') return;
      if (axiosErr?.response) {
        setError(axiosErr.response?.data?.message ?? axiosErr.message ?? 'Erreur r├®seau');
      } else {
        setError(t('providers:messages.load_error') || 'Erreur inconnue lors du chargement des fournisseurs');
      }
    }
  }, [showInactive, currentPage, debouncedSearch, t]);

  useEffect(() => {
    fetchFournisseurs();
    return () => fournisseursControllerRef.current?.abort();
  }, [showInactive, currentPage, debouncedSearch]); // Ô£à D├®pendances directes au lieu de la fonction

  useEffect(() => {
    if (selectedFournisseur && !fournisseurs.some(f => f.id === selectedFournisseur.id)) {
      setSelectedFournisseur(null);
    }
  }, [fournisseurs]); // Ô£à Retir├® selectedFournisseur des d├®pendances

  useEffect(() => {
    if (location.state?.selectedSupplierId && fournisseurs.length > 0) {
      const supplier = fournisseurs.find(f => f.id === location.state.selectedSupplierId);
      if (supplier) {
        setSelectedFournisseur(supplier);
        if (location.state.openFinance) {
          setFinanceModalState({ isOpen: true });
        }
        window.history.replaceState({}, document.title);
      }
    }
  }, [fournisseurs]);

  function openAddModal() {
    setNewFournisseur(emptyForm);
    setIsAddModalOpen(true);
  }

  function closeAddModal() {
    setIsAddModalOpen(false);
    setError(null);
    setNewFournisseur(emptyForm);
  }

  function handleKeyDown(e: KeyboardEvent<HTMLInputElement>) {
    if (!searchTerm) return;
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setHighlightedIndex(prev => prev < fournisseurs.length - 1 ? prev + 1 : prev);
        break;
      case 'ArrowUp':
        e.preventDefault();
        setHighlightedIndex(prev => prev > 0 ? prev - 1 : -1);
        break;
      case 'Enter':
        e.preventDefault();
        if (highlightedIndex >= 0 && highlightedIndex < fournisseurs.length) {
          selectFournisseur(fournisseurs[highlightedIndex]);
        }
        break;
      case 'Escape':
        setSearchTerm('');
        setHighlightedIndex(-1);
        break;
    }
  }

  function selectFournisseur(fournisseur: Fournisseur) {
    setSelectedFournisseur(fournisseur);
    setSearchTerm('');
    setHighlightedIndex(-1);
  }

  function openEditModal() {
    if (!selectedFournisseur) return;
    setEditingFournisseur(selectedFournisseur);
    setIsEditModalOpen(true);
  }

  function closeEditModal() {
    setIsEditModalOpen(false);
  }

  function formatBackendErrors(data: unknown): string {
    if (data == null) return t('common:unknown_error') || 'Erreur inconnue du serveur';
    if (typeof data === 'string') return data;
    if (typeof data === 'object') {
      try {
        const entries = Object.entries(data as Record<string, unknown>);
        const parts = entries.map(([field, messages]) => {
          if (Array.isArray(messages)) return `${field}: ${messages.join(', ')}`;
          if (typeof messages === 'string') return `${field}: ${messages}`;
          return `${field}: ${JSON.stringify(messages)}`;
        });
        return parts.join(' | ');
      } catch {
        return JSON.stringify(data);
      }
    }
    return String(data);
  }

  async function handleAddFournisseur(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);
    setIsSubmitting(true);
    try {
      const { data: addedFournisseur } = await api.post<Fournisseur>('fournisseurs/', newFournisseur);
      setFournisseurs(prev => [addedFournisseur, ...prev].sort((a, b) => a.name.localeCompare(b.name)));
      setSelectedFournisseur(addedFournisseur);
      setNewFournisseur(emptyForm);
      closeAddModal();
    } catch (err: unknown) {
      const axiosErr = err as { response?: { data?: unknown }; message?: string };
      if (axiosErr?.response) {
        const detail = axiosErr.response?.data ?? axiosErr.message;
        setError(typeof detail === 'string' ? detail : formatBackendErrors(detail));
      } else {
        setError(t('providers:messages.save_error') || "Erreur inconnue lors de l'ajout du fournisseur");
      }
      console.error("Erreur lors de l'ajout du fournisseur:", err);
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handleEditFournisseur(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!editingFournisseur) return;
    try {
      const { data: updatedFournisseur } = await api.patch<Fournisseur>(
        `fournisseurs/${editingFournisseur.id}/`,
        editingFournisseur
      );
      setFournisseurs(prev => prev.map(f => (f.id === updatedFournisseur.id ? updatedFournisseur : f)));
      setSelectedFournisseur(updatedFournisseur);
      closeEditModal();
    } catch (err: unknown) {
      const axiosErr = err as { response?: { data?: unknown }; message?: string };
      if (axiosErr?.response) {
        const detail = axiosErr.response?.data ?? axiosErr.message;
        setError(typeof detail === 'string' ? detail : formatBackendErrors(detail));
      } else {
        setError(t('providers:messages.save_error') || "Erreur inconnue lors de la modification du fournisseur");
      }
      console.error('Erreur lors de la modification du fournisseur:', err);
    }
  }

  const executeDeleteFournisseur = async (id: number, validatorId?: number, password?: string) => {
    try {
      await api.delete(`fournisseurs/${id}/`, { data: { validated_by_id: validatorId, sudo_password: password } });
      setFournisseurs(prev => prev.filter(f => f.id !== id));
      setSelectedFournisseur(null);
      toast.success(t('providers:messages.delete_success'));
    } catch (err: unknown) {
      const axiosErr = err as { response?: { status?: number; data?: { detail?: string; message?: string; error?: string } }; message?: string };
      if (axiosErr?.response) {
        if (axiosErr.response?.status === 500 || (axiosErr.response?.data?.detail && String(axiosErr.response.data.detail).includes('protected'))) {
             toast.error(t('providers:messages.delete_protected'));
        } else {
             const msg = axiosErr.response?.data?.message ?? axiosErr.message ?? t('common:network_error');
             toast.error(`${t('common:error')}: ${msg}`);
        }
      } else {
        toast.error(t('providers:messages.delete_error'));
      }
      console.error('Erreur lors de la suppression du fournisseur:', err);
      throw err;
    }
  }

  const executeBulkDeleteFournisseurs = async (validatorId?: number, password?: string) => {
    try {
      await api.post('fournisseurs/bulk_delete/', { ids: selectedIds, validated_by_id: validatorId, sudo_password: password });
      setFournisseurs(prev => prev.filter(f => !selectedIds.includes(f.id!)));
      setSelectedIds([]);
      if (selectedFournisseur && selectedIds.includes(selectedFournisseur.id!)) {
        setSelectedFournisseur(null);
      }
      toast.success(t('providers:messages.bulk_delete_success', { count: selectedIds.length }));
    } catch (err) {
      toast.error(getApiErrorDetail(err, t('providers:messages.bulk_delete_error')));
      console.error(err);
      throw err;
    }
  }

  async function handleBulkDelete() {
    if (selectedIds.length === 0) return;
    if (!user?.is_superuser && !user?.can_delete_fournisseur) {
        toast.error(t('providers:messages.access_denied_delete'))
        return;
    }
    const confirmMessage = selectedIds.length === 1 
      ? t('providers:messages.delete_confirm_message', { name: fournisseurs.find(f => f.id === selectedIds[0])?.name })
      : `├ètes-vous s├╗r de vouloir supprimer ${selectedIds.length} fournisseurs ?`;

    const confirmed = await confirm({
      title: t('providers:messages.delete_confirm_title'),
      message: confirmMessage,
      variant: 'danger',
      confirmText: t('providers:messages.delete_btn')
    });

    if (confirmed) {
        requireSudo(async (validatorId, password) => {
            await executeBulkDeleteFournisseurs(validatorId, password);
        }, {
            title: t('providers:messages.sudo_title'),
            message: t('providers:messages.sudo_message'),
            permission: 'can_delete_fournisseur'
        });
    }
  }

  function toggleSelectAll() {
    if (selectedIds.length === fournisseurs.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(fournisseurs.map(f => f.id!));
    }
  }

  function toggleSelect(id: number) {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  }

  async function handleDeleteFournisseur() {
    if (!selectedFournisseur) return;
    if (!user?.is_superuser && !user?.can_delete_fournisseur) {
        toast.error(t('providers:messages.access_denied_delete'));
        return;
    }
    const confirmed = await confirm({
      title: t('providers:messages.delete_confirm_title'),
      message: t('providers:messages.delete_confirm_message', { name: selectedFournisseur.name }),
      variant: 'danger',
      confirmText: t('providers:messages.delete_btn')
    });

    if (confirmed) {
        requireSudo(async (validatorId, password) => {
            await executeDeleteFournisseur(selectedFournisseur.id as number, validatorId, password);
        }, {
            title: t('providers:messages.sudo_title'),
            message: t('providers:messages.sudo_message'),
            permission: 'can_delete_fournisseur'
        });
    }
  }

  async function handleToggleActive() {
    if (!selectedFournisseur) return;
    try {
      const response = await api.post(`fournisseurs/${selectedFournisseur.id}/toggle_active/`);
      const isActive = response.data.is_active;
      toast.success(isActive ? t('providers:messages.reactivated') : t('providers:messages.hidden'));
      setSelectedFournisseur(prev => prev ? ({ ...prev, is_active: isActive }) : null);
      fetchFournisseurs();
    } catch (err) {
      toast.error(t('providers:messages.status_change_error'));
      console.error(err);
    }
  }

  return {
    state: {
      t,
      fournisseurs,
      selectedFournisseur, setSelectedFournisseur,
      selectedIds, setSelectedIds,
      currentPage, setCurrentPage,
      totalCount,
      itemsPerPage, totalPages,
      error, setError,
      isAddModalOpen, setIsAddModalOpen,
      isEditModalOpen, setIsEditModalOpen,
      newFournisseur, setNewFournisseur,
      editingFournisseur, setEditingFournisseur,
      isSubmitting, setIsSubmitting,
      searchTerm, setSearchTerm,
      debouncedSearch,
      highlightedIndex, setHighlightedIndex,
      searchInputRef,
      catalogue,
      catalogueLoading,
      catalogueSearch, setCatalogueSearch,
      showCatalogue, setShowCatalogue,
      showInactive, setShowInactive,
      financeModalState, setFinanceModalState,
      isEcheancierModalOpen, setIsEcheancierModalOpen,
      isPointageModalOpen, setIsPointageModalOpen,
      sudoState,
    },
    derived: {
      filteredCatalogue
    },
    actions: {
      fetchFournisseurs,
      openAddModal, closeAddModal, handleAddFournisseur,
      handleKeyDown, selectFournisseur,
      openEditModal, closeEditModal, handleEditFournisseur,
      handleBulkDelete, toggleSelectAll, toggleSelect,
      handleDeleteFournisseur, handleToggleActive,
      closeSudo,
    }
  };
}

import { useState, useCallback, useEffect, useRef } from 'react'

interface UseKeyboardNavigationProps {
    listLength: number
    onValidate?: () => void
    onDelete?: (index: number) => void
    onIncrement?: (index: number) => void
    onDecrement?: (index: number) => void
    enabled?: boolean
}

export const useKeyboardNavigation = ({
    listLength,
    onValidate,
    onDelete,
    onIncrement,
    onDecrement,
    enabled = true
}: UseKeyboardNavigationProps) => {
    const [selectedIndex, setSelectedIndex] = useState<number>(-1)

    // Reset selection when list is empty
    useEffect(() => {
        if (listLength === 0) {
            setSelectedIndex(-1)
        } else if (selectedIndex >= listLength) {
            setSelectedIndex(listLength - 1)
        }
    }, [listLength])

    const handleKeyDown = useCallback((e: KeyboardEvent) => {
        if (!enabled) return

        // Navigation
        if (e.key === 'ArrowDown') {
            e.preventDefault()
            setSelectedIndex(prev => (prev < listLength - 1 ? prev + 1 : prev))
        } else if (e.key === 'ArrowUp') {
            e.preventDefault()
            setSelectedIndex(prev => (prev > 0 ? prev - 1 : prev))
        }
        // Actions on selected item
        else if (selectedIndex !== -1) {
            if (e.key === '+' || e.key === 'Add') { // Numpad + or standard +
                e.preventDefault()
                onIncrement?.(selectedIndex)
            } else if (e.key === '-' || e.key === 'Subtract') { // Numpad - or standard -
                e.preventDefault()
                onDecrement?.(selectedIndex)
            } else if (e.key === 'Delete' || e.key === 'Backspace') {
                // Avoid deleting if focusing an input (though enabled check should handle this usually)
                if (document.activeElement?.tagName === 'INPUT') return

                e.preventDefault()
                onDelete?.(selectedIndex)
            }
        }

        // Validation
        if (e.key === 'F10' || (e.ctrlKey && e.key === 'Enter')) {
            e.preventDefault()
            onValidate?.()
        }
    }, [enabled, listLength, selectedIndex, onIncrement, onDecrement, onDelete, onValidate]);

    // Use a ref to keep the latest handler version without re-subscribing to window
    const handlerRef = useRef(handleKeyDown);
    useEffect(() => {
        handlerRef.current = handleKeyDown;
    }, [handleKeyDown]);

    useEffect(() => {
        const listener = (e: KeyboardEvent) => handlerRef.current(e);
        window.addEventListener('keydown', listener);
        return () => window.removeEventListener('keydown', listener);
    }, []); // Empty deps: subscription stays put!

    return {
        selectedIndex,
        setSelectedIndex
    }
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { cashSessionService, type PosteCaisse, type PosteVente } from '../services/cashSessionService'
import { usePosteCaisseMode } from '../context/PosteCaisseModeContext'

export interface UseMultiCaisseOptions {
}

export interface UseMultiCaisseReturn {
    isMultiCaisse: boolean
    setIsMultiCaisse: (v: boolean) => void
    centralizedCashRegister: boolean
    setCentralizedCashRegister: (v: boolean) => void
    postesCaisses: PosteCaisse[]
    setPostesCaisses: (v: PosteCaisse[]) => void
    activePostesVente: PosteVente[]
    setActivePostesVente: (v: PosteVente[]) => void
    selectedPosteCaisseId: number | null
    setSelectedPosteCaisseId: (v: number | null) => void
    multiCaisseLoading: boolean
    myActivePoste: PosteVente | null
    refreshPostes: () => Promise<void>
}

export function useMultiCaisse(_options: UseMultiCaisseOptions = {}): UseMultiCaisseReturn {
    const [centralizedCashRegister, setCentralizedCashRegister] = useState<boolean>(true)
    const [isMultiCaisse, setIsMultiCaisse] = useState<boolean>(false)
    const [postesCaisses, setPostesCaisses] = useState<PosteCaisse[]>([])
    const [activePostesVente, setActivePostesVente] = useState<PosteVente[]>([])
    const [multiCaisseLoading, setMultiCaisseLoading] = useState(false)

    const {
        activePoste,
        selectedPosteCaisseId,
        selectPoste,
        refresh: refreshActivePoste
    } = usePosteCaisseMode()

    const selectedPosteCaisseIdRef = useRef<number | null>(null)
    selectedPosteCaisseIdRef.current = selectedPosteCaisseId

    const refreshPostes = useCallback(async () => {
        setMultiCaisseLoading(true)
        try {
            const [allCaisses, activePostes, myPostes] = await Promise.all([
                cashSessionService.getAllCaisses().catch(() => []),
                cashSessionService.getActivePostesVente().catch(() => []),
                cashSessionService.getMyActivePostesVente().catch(() => [])
            ])

            setPostesCaisses(allCaisses)
            setActivePostesVente(activePostes)

            const hasMulti = activePostes.length > 1
            setIsMultiCaisse(hasMulti)

            if (!selectedPosteCaisseIdRef.current) {
                const myPoste = myPostes.length > 0 ? myPostes[0] : null
                if (myPoste) {
                    selectPoste(myPoste.caisse)
                }
            }

            await refreshActivePoste()
        } catch (err) {
            console.error('Erreur chargement postes caisses:', err)
        } finally {
            setMultiCaisseLoading(false)
        }
    }, [selectPoste, refreshActivePoste])

    useEffect(() => {
        refreshPostes()
    }, [refreshPostes])

    useEffect(() => {
        const interval = setInterval(refreshPostes, 60000)
        return () => clearInterval(interval)
    }, [refreshPostes])

    return {
        isMultiCaisse, setIsMultiCaisse,
        centralizedCashRegister, setCentralizedCashRegister,
        postesCaisses, setPostesCaisses,
        activePostesVente, setActivePostesVente,
        selectedPosteCaisseId, setSelectedPosteCaisseId: selectPoste,
        multiCaisseLoading,
        myActivePoste: activePoste,
        refreshPostes
    }
}

import { useCallback, useRef } from 'react';
import { toast } from 'react-hot-toast';
import { escHtml } from '../utils/print/printHelpers';
import { usePharmacySettings } from './usePharmacySettings';
import { formatDateTime } from '../utils/dateUtils';
import { useTranslation } from 'react-i18next';

/**
 * Types de documents imprimables
 */
export type PrintDocumentType = 'ticket' | 'invoice' | 'cloture' | 'stock' | 'custom';

/**
 * Options d'impression
 */
export interface PrintOptions {
  /** Titre du document (affich├® dans la fen├¬tre) */
  title?: string;
  /** Largeur de la fen├¬tre d'impression (d├®faut: 400) */
  width?: number;
  /** Hauteur de la fen├¬tre d'impression (d├®faut: 600) */
  height?: number;
  /** Fermer automatiquement apr├¿s impression (d├®faut: true) */
  autoClose?: boolean;
  /** Imprimer automatiquement (d├®faut: true) */
  autoPrint?: boolean;
  /** D├®lai avant impression automatique en ms (d├®faut: 500) */
  printDelay?: number;
}

/**
 * Configuration du template d'impression
 */
export interface PrintTemplateConfig {
  /** Inclure l'en-t├¬te de la pharmacie (d├®faut: true) */
  showHeader?: boolean;
  /** Inclure le pied de page (d├®faut: true) */
  showFooter?: boolean;
  /** Message personnalis├® en pied de page */
  footerMessage?: string;
  /** Styles CSS additionnels */
  customStyles?: string;
}

/**
 * R├®sultat du hook usePrint
 */
export interface UsePrintReturn {
  /** Imprimer du contenu HTML personnalis├® */
  printHTML: (html: string, options?: PrintOptions) => void;
  /** Imprimer avec un template (en-t├¬te pharmacie, pied de page) */
  printWithTemplate: (content: string, options?: PrintOptions & PrintTemplateConfig) => void;
  /** Ouvrir une page d'impression d├®di├®e */
  openPrintPage: (url: string) => void;
  /** R├®f├®rence pour impression via react-to-print */
  printRef: React.RefObject<HTMLDivElement | null>;
  /** Imprimer le contenu d'une r├®f├®rence */
  printElement: (element: HTMLElement, options?: PrintOptions) => void;
}

/**
 * Hook centralis├® pour l'impression de documents
 * 
 * @example
 * ```tsx
 * const { printWithTemplate, printHTML, openPrintPage } = usePrint();
 * 
 * // Imprimer avec le template pharmacie
 * printWithTemplate('<div>Mon contenu</div>', { title: 'Ma facture' });
 * 
 * // Imprimer du HTML brut
 * printHTML('<html>...</html>');
 * 
 * // Ouvrir une page d'impression d├®di├®e
 * openPrintPage('/app/print-invoice/123');
 * ```
 */
function usePrint(): UsePrintReturn {
  const { settings } = usePharmacySettings();
  const { t } = useTranslation('common');
  const printRef = useRef<HTMLDivElement>(null);

  /**
   * G├®n├¿re les styles CSS de base pour l'impression
   */
  const getBaseStyles = useCallback(() => {
    return `
      * {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
        color-adjust: exact !important;
      }
      body {
        font-family: 'Courier New', Courier, monospace;
        padding: 0;
        margin: 0;
        color: black;
        background: white;
      }
      @media print {
        body { padding: 0; margin: 0; }
        .no-print { display: none !important; }
      }
      .print-container {
        width: ${settings.ticket_paper_width || 80}mm;
        max-width: ${settings.ticket_paper_width || 80}mm;
        margin: 0 auto;
        padding: 5px;
      }
      .print-header {
        text-align: center;
        margin-bottom: 10px;
        padding-bottom: 5px;
        border-bottom: 1px dashed black;
      }
      .print-header h2 {
        margin: 0 0 5px 0;
        font-size: 1.1em;
        font-weight: bold;
        text-transform: uppercase;
      }
      .print-header p {
        margin: 1px 0;
        font-size: 0.8em;
      }
      .print-footer {
        text-align: center;
        margin-top: 15px;
        padding-top: 5px;
        border-top: 1px dashed black;
        font-size: 0.7em;
      }
      .print-row {
        display: flex;
        justify-content: space-between;
        font-size: 0.85em;
        margin: 2px 0;
      }
      .print-divider {
        border-top: 1px dashed black;
        margin: 5px 0;
      }
      .print-total {
        font-weight: bold;
        font-size: 1.0em;
        border-top: 1px solid black;
        padding-top: 5px;
        margin-top: 5px;
      }
    `;
  }, []);

  /**
   * G├®n├¿re l'en-t├¬te avec les informations de la pharmacie
   */
  const getHeaderHTML = useCallback(() => {
    if (!settings) return '';

    return `
      <div class="print-header">
        <h2>${escHtml(settings.pharmacy_name || 'PHARMACIE')}</h2>
        ${settings.address ? `<p>${escHtml(settings.address)}</p>` : ''}
        ${settings.phone ? `<p>T├®l: ${escHtml(settings.phone)}</p>` : ''}
        ${settings.email ? `<p>${escHtml(settings.email)}</p>` : ''}
        ${settings.niu ? `<p>NIU: ${escHtml(settings.niu)}</p>` : ''}
        ${settings.registre_commerce ? `<p>RC: ${escHtml(settings.registre_commerce)}</p>` : ''}
      </div>
    `;
  }, [settings]);

  /**
   * G├®n├¿re le pied de page
   */
  const getFooterHTML = useCallback((message?: string) => {
    const footerText = message || settings?.ticket_footer_message || 'Merci de votre visite !';
    return `
      <div class="print-footer">
        <p>${escHtml(footerText)}</p>
        <p style="margin-top: 5px; font-size: 0.7em;">
          ${t('print.printed_on', { defaultValue: 'Imprim├® le' })} ${formatDateTime(new Date())}
        </p>
      </div>
    `;
  }, [settings]);

  /**
   * Ouvre une fen├¬tre d'impression avec le contenu HTML
   */
  const openPrintWindow = useCallback((
    content: string,
    options: PrintOptions = {}
  ) => {
    const {
      title = 'Impression',
      width = 400,
      height = 600,
      autoClose = true,
      autoPrint = true,
      printDelay = 500
    } = options;

    const printWindow = window.open('about:blank', '', `height=${height},width=${width}`);

    if (!printWindow) {
      console.error('Impossible d\'ouvrir la fen├¬tre d\'impression. V├®rifiez les param├¿tres du navigateur.');
      return null;
    }

    printWindow.document.write(content);
    printWindow.document.close();
    printWindow.document.title = title;

    if (autoPrint) {
      setTimeout(() => {
        printWindow.print();
        if (autoClose) {
          printWindow.close();
        }
      }, printDelay);
    }

    return printWindow;
  }, []);

  /**
   * Imprimer du contenu HTML brut
   */
  const printHTML = useCallback((
    html: string,
    options?: PrintOptions
  ) => {
    openPrintWindow(html, options);
  }, [openPrintWindow]);

  /**
   * Imprimer avec le template de la pharmacie
   */
  const printWithTemplate = useCallback((
    content: string,
    options: PrintOptions & PrintTemplateConfig = {}
  ) => {
    const {
      showHeader = true,
      showFooter = true,
      footerMessage,
      customStyles = '',
      ...printOptions
    } = options;

    const fullHTML = `
      <!DOCTYPE html>
      <html>
        <head>
          <meta charset="UTF-8">
          <title>${printOptions.title || 'Impression'}</title>
          <style>
            ${getBaseStyles()}
            ${customStyles}
          </style>
        </head>
        <body>
          <div class="print-container">
            ${showHeader ? getHeaderHTML() : ''}
            ${content}
            ${showFooter ? getFooterHTML(footerMessage) : ''}
          </div>
        </body>
      </html>
    `;

    openPrintWindow(fullHTML, printOptions);
  }, [getBaseStyles, getHeaderHTML, getFooterHTML, openPrintWindow]);

  /**
   * Ouvrir une page d'impression d├®di├®e
   */
  const openPrintPage = useCallback((url: string) => {
    const w = window.open(url, '_blank');
    if (!w) toast.error('Popup bloqu├®. Autorisez les popups pour imprimer.');
  }, []);

  /**
   * Imprimer le contenu d'un ├®l├®ment DOM
   */
  const printElement = useCallback((
    element: HTMLElement,
    options?: PrintOptions
  ) => {
    const html = `
      <!DOCTYPE html>
      <html>
        <head>
          <style>${getBaseStyles()}</style>
        </head>
        <body>
          ${element.outerHTML}
        </body>
      </html>
    `;
    openPrintWindow(html, options);
  }, [getBaseStyles, openPrintWindow]);

  return {
    printHTML,
    printWithTemplate,
    openPrintPage,
    printRef,
    printElement
  };
}

