  remise_automatique: z.coerce.number().min(0).max(100, "La remise ne peut pas d├®passer 100%").default(0),
  plafond: z.coerce.number().min(-1).default(-1),
  taux_couverture: z.coerce.number().min(0).max(100).default(0),
