  remise_automatique: z.coerce.number().min(0).max(100, 'La remise automatique doit ├¬tre entre 0 et 100').default(0),
  majoration_pro_pourcentage: z.coerce.number().min(0).max(100, 'La majoration doit ├¬tre entre 0 et 100').default(0),
