export const playNotificationSound = () => {
    try {
        // @ts-ignore
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        const oscillator = audioCtx.createOscillator();
        const gainNode = audioCtx.createGain();

        oscillator.connect(gainNode);
        gainNode.connect(audioCtx.destination);

        // Modern UI "ping" sound using sine wave
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(880, audioCtx.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(1760, audioCtx.currentTime + 0.1);

        gainNode.gain.setValueAtTime(0, audioCtx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0.3, audioCtx.currentTime + 0.05);
        gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.3);

        oscillator.start(audioCtx.currentTime);
        oscillator.stop(audioCtx.currentTime + 0.3);
    } catch(e) {
        console.warn("Audio context not supported or blocked", e);
    }
};

/**
 * Parsing Data Matrix / GS1-128 pour m├®dicaments
 * Extrait les Application Identifiers (AI) GS1 depuis la cha├«ne envoy├®e par la douchette
 *
 * Format GS1-128 typique :  ]d2  01  03400936191017  10  LOT123  17  260531
 * Avec s├®parateurs GS (char 0x1D) entre champs de longueur variable
 */

export interface ParsedDataMatrix {
    cip: string | null;       // AI 01 ÔåÆ GTIN-13 (CIP)
    lot: string | null;       // AI 10 ÔåÆ Num├®ro de lot
    dateExpiration: string | null; // AI 17 ÔåÆ Date de p├®remption au format MM/YY
    serial: string | null;    // AI 21 ÔåÆ Num├®ro de s├®rie (si pr├®sent)
    rawDate: string | null;   // Date brute extraite avant normalisation
}

/**
 * Normalise une date de p├®remption vers le format MM/YY
 * Supporte : "05/2026", "05 2026", "05.2026", "05.26", "05/26", "260531" (YYMMDD GS1)
 */
export function normalizeDateExpiration(raw: string | null | undefined): string | null {
    if (!raw) return null;
    const s = raw.trim();

    // Format GS1 YYMMDD (ex: "260531" = Mai 2026)
    if (/^\d{6}$/.test(s)) {
        const yy = s.slice(0, 2);
        const mm = s.slice(2, 4);
        // dd = s.slice(4, 6) ÔÇö ignor├®, on ne garde que MM/YY
        if (parseInt(mm) >= 1 && parseInt(mm) <= 12) {
            return `${mm}/${yy}`;
        }
    }

    // Format YYYY-MM-DD ou YYYY/MM/DD (ISO)
    const isoMatch = s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/);
    if (isoMatch) {
        const mm = isoMatch[2].padStart(2, '0');
        const yy = isoMatch[1].slice(-2);
        return `${mm}/${yy}`;
    }

    // Format MM/YYYY, MM YYYY, MM.YYYY
    const longMatch = s.match(/^(\d{1,2})[\/\s\.](\d{4})$/);
    if (longMatch) {
        const mm = longMatch[1].padStart(2, '0');
        const yy = longMatch[2].slice(-2);
        return `${mm}/${yy}`;
    }

    // Format MM/YY, MM YY, MM.YY (d├®j├á court)
    const shortMatch = s.match(/^(\d{1,2})[\/\s\.](\d{2})$/);
    if (shortMatch) {
        const mm = shortMatch[1].padStart(2, '0');
        const yy = shortMatch[2];
        return `${mm}/${yy}`;
    }

    return null;
}

/**
 * Parse une cha├«ne GS1 Data Matrix re├ºue de la douchette
 * La douchette envoie g├®n├®ralement : ]d2<donn├®es>
 * Les champs de longueur variable sont s├®par├®s par GS (0x1D)
 */
export function parseDataMatrix(raw: string): ParsedDataMatrix {
    const result: ParsedDataMatrix = {
        cip: null,
        lot: null,
        dateExpiration: null,
        serial: null,
        rawDate: null,
    };

    if (!raw || raw.trim() === '') return result;

    // Nettoyer le pr├®fixe AIM (]d2, ]C1, etc.)
    let data = raw.trim().replace(/^\]d[12]/i, '').replace(/^\]C1/i, '');

    // Remplacer le s├®parateur GS (0x1D) par un d├®limiteur lisible
    const GS = '\x1d';
    // Certaines douchettes envoient <GS> en ASCII char ou en \x1D
    data = data.replace(/\x1d/g, GS);

    // Extraction des AI GS1 connus
    // Strat├®gie : parcourir la cha├«ne position par position
    let pos = 0;

    while (pos < data.length) {
        // Sauter les s├®parateurs GS
        if (data[pos] === GS) {
            pos++;
            continue;
        }

        // Lire l'AI (2 ou 3 chiffres)
        const remaining = data.slice(pos);

        // AI 01 : GTIN (14 chiffres fixes)
        if (remaining.startsWith('01') && /^\d{16}$/.test(remaining.slice(2, 16).padEnd(14, 'X'))) {
            const gtin14 = remaining.slice(2, 16);
            if (/^\d{14}$/.test(gtin14)) {
                // Extraire CIP13 : supprimer premier chiffre (indicateur packaging) et checkdigit ?
                // Format GTIN-14 : 0 + CIP13 (13 chiffres)
                // ou : 1 chiffre emballage + CIP (12) + checkdigit
                // En France : 034XXXXXXXXXX checkdigit ÔåÆ CIP7 ou CIP13
                const cip13 = gtin14.slice(1); // Retire le leading indicator
                result.cip = cip13;
                pos += 16;
                continue;
            }
        }

        // AI 10 : Lot (longueur variable, max 20 chars)
        // Termin├® par GS (\x1D) si pr├®sent, sinon on cherche uniquement AI 21 imbriqu├®.
        // Note : certains fabricants encodent un lot court pr├®c├®d├® d'un pr├®fixe (ex: "2310" + lot "3091")
        // mais sans GS s├®parateur, on extrait le champ complet tel quel depuis le Data Matrix.
        if (remaining.startsWith('10')) {
            pos += 2;
            const endGs = data.indexOf(GS, pos);
            if (endGs !== -1) {
                // GS pr├®sent : extraction propre
                result.lot = data.slice(pos, endGs).trim();
                pos = endGs;
            } else {
                // Pas de GS : chercher seulement AI 21 imbriqu├® (pattern "21" + alphanum, longueur connue)
                // On ne tente la d├®tection que si la cha├«ne restante est > 6 chars (lot min + "21" + s├®rie)
                const rest = data.slice(pos);
                const ai21Idx = rest.search(/21[A-Z0-9]/i);
                if (ai21Idx > 0 && ai21Idx <= 20) {
                    result.lot = rest.slice(0, ai21Idx).trim();
                    pos += ai21Idx;
                } else {
                    result.lot = rest.trim();
                    pos = data.length;
                }
            }
            continue;
        }

        // AI 17 : Date d'expiration (6 chiffres fixes YYMMDD)
        if (remaining.startsWith('17')) {
            const dateStr = remaining.slice(2, 8);
            if (/^\d{6}$/.test(dateStr)) {
                result.rawDate = dateStr;
                result.dateExpiration = normalizeDateExpiration(dateStr);
                pos += 8;
                continue;
            }
        }

        // AI 21 : Num├®ro de s├®rie (longueur variable, max 20 chars, termin├® par GS ou fin)
        if (remaining.startsWith('21')) {
            pos += 2;
            const endGs = data.indexOf(GS, pos);
            const end = endGs !== -1 ? endGs : data.length;
            result.serial = data.slice(pos, end).trim();
            pos = end;
            continue;
        }

        // AI inconnu : avancer d'un caract├¿re pour ├®viter la boucle infinie
        pos++;
    }

    return result;
}

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { formatNumber } from '../formatters';
import type { PharmacySettings } from '../../context/PharmacySettingsContext';

interface PaiementDetail {
    facture_id: number;
    numero_facture: string;
    montant_total_facture: number | string;
    montant_paye: number | string;
    reste_avant: number | string;
    reste_apres: number | string;
    est_soldee: boolean;
}

interface TicketReglementData {
    reference: string;
    date: string;
    client_name: string;
    mode_paiement: string;
    total_dettes: number | string;
    montant_regle: number | string;
    reste_a_payer: number | string;
    paiements: PaiementDetail[];
    settings: PharmacySettings;
}

export function generateTicketReglementPdf(data: TicketReglementData): jsPDF {
    const doc = new jsPDF('p', 'mm', 'a4');
    const pageWidth = doc.internal.pageSize.getWidth();
    const margin = 15;

    const fmt = (val: number | string | null | undefined) => {
        if (val == null || val === '') return '0';
        const num = Number(val);
        if (isNaN(num)) return '0';
        return formatNumber(Math.round(num)).replace(/[\u00A0\u202F]/g, ' ');
    };

    let y = 20;

    // ÔöÇÔöÇ HEADER ÔöÇÔöÇ
    doc.setFontSize(18);
    doc.setFont('helvetica', 'normal');
    doc.text(data.settings.pharmacy_name || 'PHARMACIE', pageWidth / 2, y, { align: 'center' });
    y += 8;

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    if (data.settings.address) {
        doc.text(data.settings.address, pageWidth / 2, y, { align: 'center' });
        y += 5;
    }
    if (data.settings.phone) {
        doc.text(`Tel: ${data.settings.phone}`, pageWidth / 2, y, { align: 'center' });
        y += 5;
    }
    y += 8;

    // ÔöÇÔöÇ TITRE ÔöÇÔöÇ
    doc.setFontSize(14);
    doc.setFont('helvetica', 'normal');
    doc.text('TICKET DE R├êGLEMENT', pageWidth / 2, y, { align: 'center' });
    y += 10;

    // ÔöÇÔöÇ INFOS G├ëN├ëRALES ÔöÇÔöÇ
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');

    const leftCol = margin;
    const rightCol = pageWidth - margin;

    doc.text(`R├®f├®rence:`, leftCol, y);
    doc.setFont('helvetica', 'normal');
    doc.text(data.reference, leftCol + 25, y);
    doc.setFont('helvetica', 'normal');

    doc.text(`Date:`, rightCol - 40, y);
    doc.text(new Date(data.date).toLocaleDateString('fr-FR'), rightCol, y, { align: 'right' });
    y += 7;

    doc.text(`Client:`, leftCol, y);
    doc.setFont('helvetica', 'normal');
    doc.text(data.client_name, leftCol + 25, y);
    doc.setFont('helvetica', 'normal');
    y += 7;

    doc.text(`Mode:`, leftCol, y);
    doc.text(data.mode_paiement.toUpperCase(), leftCol + 25, y);
    y += 10;

    // ÔöÇÔöÇ LIGNE DE S├ëPARATION ÔöÇÔöÇ
    doc.setDrawColor(200, 200, 200);
    doc.line(margin, y, pageWidth - margin, y);
    y += 8;

    // ÔöÇÔöÇ TABLEAU DES PAIEMENTS ÔöÇÔöÇ
    const tableData = data.paiements.map((p, index) => {
        // S'assurer que est_soldee est un boolean (le backend peut envoyer true, 'true', ou false)
        const isSoldee = p.est_soldee === true || String(p.est_soldee).toLowerCase() === 'true';
        const resteApres = Number(p.reste_apres) || 0;

        return [
            (index + 1).toString(),
            p.numero_facture || `-`,
            fmt(p.montant_total_facture),
            fmt(p.montant_paye),
            isSoldee ? 'SOLD├ëE' : (resteApres > 0 ? `${fmt(resteApres)} reste` : '0'),
        ];
    });

    autoTable(doc, {
        startY: y,
        head: [['N┬░', 'Facture', 'Total Facture', 'Montant R├®gl├®', 'Statut']],
        body: tableData,
        theme: 'plain',
        headStyles: {
            fillColor: [255, 255, 255],
            textColor: [0, 0, 0],
            fontSize: 9,
            fontStyle: 'normal',
        },
        bodyStyles: {
            fontSize: 9,
            fontStyle: 'normal',
        },
        columnStyles: {
            0: { cellWidth: 8, halign: 'center' },
            1: { cellWidth: 42, halign: 'left' },
            2: { cellWidth: 28, halign: 'right' },
            3: { cellWidth: 28, halign: 'right' },
            4: { cellWidth: 34, halign: 'center' },
        },
        margin: { left: margin, right: margin },
        didParseCell: (hookData) => {
            // Colorer selon le statut
            if (hookData.section === 'body' && hookData.column.index === 4) {
                const cellText = String(hookData.cell.text[0] || '');
                if (cellText.includes('SOLD├ëE')) {
                    hookData.cell.styles.textColor = [0, 0, 0]; // Vert
                    hookData.cell.styles.fontStyle = 'bold';
                } else if (cellText.includes('reste')) {
                    hookData.cell.styles.textColor = [0, 0, 0]; // Orange
                    hookData.cell.styles.fontStyle = 'bold';
                }
            }
        },
    });

    // @ts-ignore
    y = doc.lastAutoTable.finalY + 10;

    // ÔöÇÔöÇ R├ëCAPITULATIF ÔöÇÔöÇ
    doc.setFontSize(11);
    doc.setFont('helvetica', 'normal');
    doc.text('R├ëCAPITULATIF', margin, y);
    y += 8;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);

    const recapWidth = 80;
    const recapX = pageWidth - margin - recapWidth;

    // Total dettes
    doc.text('Total des dettes:', recapX, y);
    doc.text(`${fmt(data.total_dettes)} F`, pageWidth - margin, y, { align: 'right' });
    y += 6;

    // Montant r├®gl├® (en vert/gras)
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(0, 0, 0);
    doc.text('Montant r├®gl├®:', recapX, y);
    doc.text(`${fmt(data.montant_regle)} F`, pageWidth - margin, y, { align: 'right' });
    y += 6;

    // Reste ├á payer (en rouge si > 0)
    const reste = Number(data.reste_a_payer);
    if (reste > 0) {
        doc.setTextColor(0, 0, 0);
    } else {
        doc.setTextColor(100, 100, 100);
    }
    doc.text('Reste ├á payer:', recapX, y);
    doc.text(`${fmt(data.reste_a_payer)} F`, pageWidth - margin, y, { align: 'right' });
    y += 10;

    // ÔöÇÔöÇ MESSAGE ├ëTAT ÔöÇÔöÇ
    doc.setTextColor(100, 100, 100);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    if (reste > 0) {
        doc.text(`ÔÜá Il reste ${fmt(data.reste_a_payer)} F ├á r├®gler`, margin, y);
    } else {
        doc.setTextColor(0, 0, 0);
        doc.text('Ô£ô Toutes les factures sont sold├®es !', margin, y);
    }
    y += 15;

    // ÔöÇÔöÇ FOOTER ÔöÇÔöÇ
    doc.setTextColor(150, 150, 150);
    doc.setFontSize(8);
    doc.text('Ce document est un justificatif de r├¿glement.', pageWidth / 2, y, { align: 'center' });
    y += 5;
    doc.text(`G├®n├®r├® le ${new Date().toLocaleString('fr-FR')}`, pageWidth / 2, y, { align: 'center' });

    return doc;
}
